// Commit feedback on both backends: fb_new makes the MTL4CommitOptions on Metal 4 and a list on Metal 3, fb_add adds a handler to either. On Metal 3 m3_commit makes each handler a
// completed handler and passes it the command buffer, which answers error / GPUStartTime / GPUEndTime as the commit feedback does (the only things the handlers read)
typedef void (^fb_fn)(id<MTL4CommitFeedback> f);
static inline id fb_new(void) { return g_m3 ? [NSMutableArray array] : [MTL4CommitOptions new]; }
static inline void fb_add(id o, fb_fn h) { if (g_m3) [(NSMutableArray *)o addObject:h]; else [(MTL4CommitOptions *)o addFeedbackHandler:h]; }
// Metal 3 commit: the feedback handlers become completed handlers and a fence signal is encoded at its end (Metal 4 signals on the queue after the commit, rec_signal).
// With the encode thread on this runs on that thread (rec_commit_m3 records it), which is why the handlers must be recorded with it
// A Metal 3 command buffer on g_q3. Unretained references as on Metal 4, where command buffers retain nothing: the replay already keeps what a command buffer uses alive until its fence
// has completed (defer_obj_release, g_done is advanced by the completion handler)
static id<MTLCommandBuffer> m3_cb(void) { return [g_q3 commandBufferWithUnretainedReferences]; }
static void m3_commit(id<MTLCommandBuffer> cb, NSArray *fb, id<MTLSharedEvent> ev, uint64_t v) {
    if (!gpu_go()) return;   // GPU 安全停后不交（反馈处理也不挂：不会再有回调）
    for (fb_fn h in fb) [cb addCompletedHandler:^(id<MTLCommandBuffer> c) { h((id)c); }];
    if (ev) [cb encodeSignalEvent:ev value:v];
    [cb commit];
}
// 旧队列上「交了就等完」的几处（回读 / 截图 / 帧录放）：安全停后不交也不等（没交的命令缓冲 waitUntilCompleted 永远不返回），返回 0，调用方按没拿到结果处理
static int cb_run(id<MTLCommandBuffer> cb) { if (!gpu_go()) return 0; [cb commit]; [cb waitUntilCompleted]; return 1; }
static int cb_put(id<MTLCommandBuffer> cb) { if (!gpu_go()) return 0; [cb commit]; return 1; }
// Metal 3 encoders (#278 D3-2): the main command buffer's draw passes, compute and copy encoders are the old ones (MTLRenderCommandEncoder / MTLComputeCommandEncoder /
// MTLBlitCommandEncoder, whose state setters have the Metal 4 selectors), ordered by g_fence3 (m3_wait, m4_end). Argument binding is D3-3 (#279):
// enc_r_table / enc_c_table note each stage's DmTable3 and every draw and dispatch hands its slots to the encoder first (m3_bind_draw / m3_bind_dispatch)
// Metal 3: GPU address → buffer and offset. Old encoders take a buffer where Metal 4 takes a GPU address (index and indirect buffers here; vertex and constant buffers in D3-3).
// Every buffer the GPU reaches by address is in the residency set, so res_add / res_remove keep a table of them sorted by GPU address (under g_res_mu). The residency set holds each
// buffer until res_remove, so the table holds them unretained
typedef struct { uint64_t lo, hi; __unsafe_unretained id<MTLBuffer> b; } m3_span;
static m3_span *g_m3_buf; static int g_m3_nbuf, g_m3_cap;
static int m3_buf_find(uint64_t a) { int lo = 0, hi = g_m3_nbuf - 1, hit = -1; while (lo <= hi) { int m = (lo + hi) / 2; if (g_m3_buf[m].lo <= a) { hit = m; lo = m + 1; } else hi = m - 1; } return hit; }   // the last one starting at or before a
static void m3_buf_add(id<MTLBuffer> b) {
    uint64_t lo = b.gpuAddress; int i = m3_buf_find(lo) + 1;
    if (g_m3_nbuf == g_m3_cap) { int c = g_m3_cap ? g_m3_cap * 2 : 1024; if (!GROW(g_m3_buf, (size_t)c * sizeof *g_m3_buf, "metal3 buffer table")) return; g_m3_cap = c; }
    memmove(g_m3_buf + i + 1, g_m3_buf + i, (size_t)(g_m3_nbuf - i) * sizeof *g_m3_buf);
    g_m3_buf[i] = (m3_span){lo, lo + b.length, b}; g_m3_nbuf++;
}
static void m3_buf_del(id<MTLBuffer> b) {
    int i = m3_buf_find(b.gpuAddress); while (i >= 0 && g_m3_buf[i].b != b) i--;   // spans of no length may share a start
    if (i < 0) return;
    memmove(g_m3_buf + i, g_m3_buf + i + 1, (size_t)(g_m3_nbuf - i - 1) * sizeof *g_m3_buf); g_m3_nbuf--;
}
static int m3_buf_at(uint64_t gpu, id<MTLBuffer> __strong *buf, NSUInteger *off) {   // the interface agreed in #279; 0 = in no resident buffer (reported red)
    pthread_mutex_lock(&g_res_mu);
    int i = m3_buf_find(gpu); id<MTLBuffer> b = i >= 0 && gpu < g_m3_buf[i].hi ? g_m3_buf[i].b : nil; if (b) *off = (NSUInteger)(gpu - g_m3_buf[i].lo);
    pthread_mutex_unlock(&g_res_mu);
    if (!b) { static _Atomic int n; int k = atomic_fetch_add(&n, 1); if (k % 600 == 0) MLOG("【红】 Metal 3: GPU address %#llx is in no resident buffer; what uses it is skipped (%d so far)", (unsigned long long)gpu, k + 1); }
    *buf = b; return b != nil;
}
int mtl_m3_buf(uint64_t gpu, void **buf, uint64_t *off) { NSUInteger o = 0; id<MTLBuffer> b; int ok = m3_buf_at(gpu, &b, &o); *buf = (__bridge void *)b; *off = o; return ok; }   // for tests/t_nvn_m3.m
static NSHashTable *g_res_objects;
// Residency churn by call site (the power line every 300 frames, nvn_be_res_stats): each commit with changes is a kernel call whose cost grows with what was added or removed
enum { RS_SITES = 16 }; static struct { int line; uint64_t n, bytes; } g_rs_site[RS_SITES]; static uint64_t g_rs_rm, g_rs_commits, g_rs_commit_ns;
#define res_add(r) res_add_at((r), __LINE__)
// 大贴图建立账（S2A_MEM_SPLIT=1，缺省关；11-05 时之笛第二十三版读档进场景：约 0.1 秒私有贴图 417 → 1708 MB，同期随包首传只有约 325 MB，要知道多出来的是哪些）：
//   进驻留集的私有贴图 ≥ 4 MB 各打一行（建它的源码行号定是哪条路：GPU 贴图 / 随包上传 / 升级 / 放宽 / 内部分辨率 / 临时图），带 Metal 侧尺寸、格式、级数、层数、用途与累计；
//   GPU 贴图另有 tex_big_note 一行补 NVN 侧描述（flags、池 flags、存储碰没碰过）。只按 ≥ 4 MB 打，前 400 行后按 2 的幂
static int big_tex_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("S2A_MEM_SPLIT"); on = e && *e && strcmp(e, "0"); } return on; }
static _Atomic uint64_t g_big_tex_n, g_big_tex_bytes;
static _Atomic uint64_t g_cur_frame;   // defined with the frame statistics below (tentative definition)
static void big_tex_res(id<MTLResource> r, int line) {
    if (![r conformsToProtocol:@protocol(MTLTexture)]) return;
    id<MTLTexture> t = (id<MTLTexture>)r; if (t.parentTexture || t.buffer || t.storageMode != MTLStorageModePrivate) return;
    uint64_t b = t.allocatedSize; if (b < (4u << 20)) return;
    uint64_t k = atomic_fetch_add(&g_big_tex_n, 1) + 1, tot = atomic_fetch_add(&g_big_tex_bytes, b) + b;
    if (k <= 400 || !(k & (k - 1))) MLOG("[大贴图] 第 %llu 张 源码行 %d：%lux%lux%lu 层 %lu 级 %lu 格式 %lu 类型 %lu 用途 %#lx 分配 %llu KB（累计 %llu MB，帧 %llu）", (unsigned long long)k, line,
        (unsigned long)t.width, (unsigned long)t.height, (unsigned long)t.depth, (unsigned long)t.arrayLength, (unsigned long)t.mipmapLevelCount, (unsigned long)t.pixelFormat, (unsigned long)t.textureType,
        (unsigned long)t.usage, (unsigned long long)(b >> 10), (unsigned long long)(tot >> 20), (unsigned long long)atomic_load(&g_cur_frame));
}
// 游戏线程上没有会清空的自动释放池（长寿命线程、没有 run loop），Metal / Foundation 内部把对象「强引用 + autorelease」一次（弱引用表查询 / 写入、
//   驻留集增删等）就永远放不掉。11-06 DOOM Eternal（c1106_rj13）：游戏释放的内存池 34 个 2720 MB 的零拷贝缓冲一直活着（「freed but alive」），
//   GPU 已分配 4645 MB；删池时线程自动释放池里挂着 36–56 个缓冲对象。池生命周期上这四处入口（建池 / 删池 / 进驻留集 / 出驻留集）各自带池：
//   改后同局 freed but alive 0、GPU 已分配 1920 MB
static void res_add_at_body(id<MTLResource> r, int line);
static void res_add_at(id<MTLResource> r, int line) { @autoreleasepool { res_add_at_body(r, line); } }
static void res_add_at_body(id<MTLResource> r, int line) {
    if (!r) return;
    pthread_mutex_lock(&g_res_mu);
    if (!g_res_objects) g_res_objects = [NSHashTable weakObjectsHashTable];
    if ([g_res_objects containsObject:r]) { pthread_mutex_unlock(&g_res_mu); return; }   // already resident (a shared texture resolved again): marking the set dirty would cost a commit that changes nothing
    if (big_tex_on()) big_tex_res(r, line);   // first time into the residency set only
    { int k = 0; while (k < RS_SITES - 1 && g_rs_site[k].line && g_rs_site[k].line != line) k++; g_rs_site[k].line = line; g_rs_site[k].n++; g_rs_site[k].bytes += r.allocatedSize; }
    [g_res addAllocation:(id<MTLAllocation>)r];
    [g_res_objects addObject:r];
    if (g_m3 && [r conformsToProtocol:@protocol(MTLBuffer)]) m3_buf_add((id<MTLBuffer>)r);
    g_res_dirty = 1;
    pthread_mutex_unlock(&g_res_mu);
}
static int pool_pin_retire(void *r);   // a pool table names it (pool_ent_put): it stays resident until no entry does
static void res_remove_body(id<MTLResource> r);
static void res_remove(id<MTLResource> r) { @autoreleasepool { res_remove_body(r); } }
static void res_remove_body(id<MTLResource> r) {
    if (!r) return;
    pthread_mutex_lock(&g_res_mu);
    if (![g_res_objects containsObject:r]) { pthread_mutex_unlock(&g_res_mu); return; }
    if (pool_pin_retire((__bridge void *)r)) { pthread_mutex_unlock(&g_res_mu); return; }
    [g_res removeAllocation:(id<MTLAllocation>)r];
    [g_res_objects removeObject:r];
    if (g_m3 && [r conformsToProtocol:@protocol(MTLBuffer)]) m3_buf_del((id<MTLBuffer>)r);
    g_res_dirty = 1; g_rs_rm++;
    pthread_mutex_unlock(&g_res_mu);
}
// ---------- Metal 3 argument tables (#279 D3-3) ----------
// Metal 4 binds a buffer by its GPU address (MTL4ArgumentTable setAddress) and a texture / sampler by its resource ID; the old encoders take the objects (setVertexBuffer:offset:atIndex: …).
// Addresses go back to buffer + offset through m3_buf_at; helper passes hold their objects and bind them directly (tab_buf / tab_tex / tab_samp). DmTable3 stands in for
// MTL4ArgumentTable on this path: it keeps the slots and, per stage, which changed since they last went to an encoder (m3_table_apply)
enum { M3T_BUF = 31, M3T_TEX = 4, M3T_SMP = 4 };
@interface DmTable3 : NSObject { @public __strong id<MTLBuffer> buf[M3T_BUF]; NSUInteger off[M3T_BUF]; __strong id<MTLTexture> tex[M3T_TEX]; __strong id<MTLSamplerState> smp[M3T_SMP];
    uint32_t dbuf[5], dtex[5], dsmp[5]; } @end   // per stage (0 vertex, 1 fragment, 2 compute, 3 object, 4 mesh: a task / mesh draw, nvn_geometry.inc mtk_encode): slots changed since they last went to that stage
@implementation DmTable3 @end
// Per stage, the encoder and the table whose slots went to it last (m3_table_apply). Held strongly: an ended encoder that is freed can hand its address to the next one, which
// then looked like the same encoder and got only the changed slots (Diablo II, forced Metal 3: the widen push at slot 13, set once and skipped by the vbuf cache, was never bound on the
// new encoder; the scene draws read nothing and the frame stayed black)
static __strong id g_m3_sent_enc[5], g_m3_sent_tab[5];
// A table on either path: Metal 4 makes the MTL4ArgumentTable, Metal 3 a DmTable3. nb / nt / ns: buffer / texture / sampler slots
static id tab_new(NSUInteger nb, NSUInteger nt, NSUInteger ns, NSError **e) {
    if (g_m3) { if (nb > M3T_BUF || nt > M3T_TEX || ns > M3T_SMP) { if (e) *e = [NSError errorWithDomain:@"DmTable3" code:1 userInfo:@{NSLocalizedDescriptionKey: @"too many slots"}]; return nil; } return [DmTable3 new]; }
    MTL4ArgumentTableDescriptor *d = [MTL4ArgumentTableDescriptor new]; d.maxBufferBindCount = nb; d.maxTextureBindCount = nt; d.maxSamplerStateBindCount = ns;
    return [g_dev newArgumentTableWithDescriptor:d error:e];
}
static inline void tab_buf(id t, id<MTLBuffer> b, NSUInteger off, NSUInteger i) {
    if (!g_m3) { [(id<MTL4ArgumentTable>)t setAddress:b.gpuAddress + off atIndex:i]; return; }
    DmTable3 *x = t; if (i >= M3T_BUF) return; x->buf[i] = b; x->off[i] = off; for (int k = 0; k < 5; k++) x->dbuf[k] |= 1u << i;
}
static inline void tab_addr(id t, uint64_t gpu, NSUInteger i) {   // an address only (the main path's bindings): Metal 3 looks the buffer up
    if (!g_m3) { [(id<MTL4ArgumentTable>)t setAddress:gpu atIndex:i]; return; }
    id<MTLBuffer> b; NSUInteger o = 0;
    if (!m3_buf_at(gpu, &b, &o)) { DmTable3 *x = t; if (i < M3T_BUF) { x->buf[i] = nil; for (int k = 0; k < 5; k++) x->dbuf[k] &= ~(1u << i); } return; }   // reported red there; the slot is left unbound
    tab_buf(t, b, o, i);
}
static inline void tab_tex(id t, id<MTLTexture> x, NSUInteger i) {
    if (!g_m3) { [(id<MTL4ArgumentTable>)t setTexture:x.gpuResourceID atIndex:i]; return; }
    DmTable3 *y = t; if (i >= M3T_TEX) return; y->tex[i] = x; for (int k = 0; k < 5; k++) y->dtex[k] |= 1u << i;
}
static inline void tab_samp(id t, id<MTLSamplerState> s, NSUInteger i) {
    if (!g_m3) { [(id<MTL4ArgumentTable>)t setSamplerState:s.gpuResourceID atIndex:i]; return; }
    DmTable3 *y = t; if (i >= M3T_SMP) return; y->smp[i] = s; for (int k = 0; k < 5; k++) y->dsmp[k] |= 1u << i;
}
// Metal 3 (the seam with #278: m3_bind_draw / m3_bind_dispatch call it before each draw / dispatch): the slots of table t that changed since they last went to this stage go to the encoder,
// all of them when this stage last got another encoder (a new one starts with nothing bound) or another table (a helper pass's table took over slots of this one on the same encoder,
// which Metal 4's setArgumentTable undoes as a whole). stage: 0 vertex, 1 fragment (render encoder), 2 compute, 3 object, 4 mesh (render encoder, a task / mesh draw)
static void m3_table_apply(id enc, int stage, id tab) {
    DmTable3 *t = tab; if (!t) return;
    int all = g_m3_sent_enc[stage] != enc || g_m3_sent_tab[stage] != t; g_m3_sent_enc[stage] = enc; g_m3_sent_tab[stage] = t;
    uint32_t mb = all ? ~0u : t->dbuf[stage], mt = all ? ~0u : t->dtex[stage], ms = all ? ~0u : t->dsmp[stage];
    for (NSUInteger i = 0; i < M3T_BUF; i++) if ((mb >> i & 1) && t->buf[i]) {
        if (stage == 0) [(id<MTLRenderCommandEncoder>)enc setVertexBuffer:t->buf[i] offset:t->off[i] atIndex:i];
        else if (stage == 1) [(id<MTLRenderCommandEncoder>)enc setFragmentBuffer:t->buf[i] offset:t->off[i] atIndex:i];
        else if (stage == 3) [(id<MTLRenderCommandEncoder>)enc setObjectBuffer:t->buf[i] offset:t->off[i] atIndex:i];
        else if (stage == 4) [(id<MTLRenderCommandEncoder>)enc setMeshBuffer:t->buf[i] offset:t->off[i] atIndex:i];
        else [(id<MTLComputeCommandEncoder>)enc setBuffer:t->buf[i] offset:t->off[i] atIndex:i];
    }
    for (NSUInteger i = 0; i < M3T_TEX; i++) if ((mt >> i & 1) && t->tex[i]) {
        if (stage == 0) [(id<MTLRenderCommandEncoder>)enc setVertexTexture:t->tex[i] atIndex:i];
        else if (stage == 1) [(id<MTLRenderCommandEncoder>)enc setFragmentTexture:t->tex[i] atIndex:i];
        else if (stage == 3) [(id<MTLRenderCommandEncoder>)enc setObjectTexture:t->tex[i] atIndex:i];
        else if (stage == 4) [(id<MTLRenderCommandEncoder>)enc setMeshTexture:t->tex[i] atIndex:i];
        else [(id<MTLComputeCommandEncoder>)enc setTexture:t->tex[i] atIndex:i];
    }
    for (NSUInteger i = 0; i < M3T_SMP; i++) if ((ms >> i & 1) && t->smp[i]) {
        if (stage == 0) [(id<MTLRenderCommandEncoder>)enc setVertexSamplerState:t->smp[i] atIndex:i];
        else if (stage == 1) [(id<MTLRenderCommandEncoder>)enc setFragmentSamplerState:t->smp[i] atIndex:i];
        else if (stage == 3) [(id<MTLRenderCommandEncoder>)enc setObjectSamplerState:t->smp[i] atIndex:i];
        else if (stage == 4) [(id<MTLRenderCommandEncoder>)enc setMeshSamplerState:t->smp[i] atIndex:i];
        else [(id<MTLComputeCommandEncoder>)enc setSamplerState:t->smp[i] atIndex:i];
    }
    t->dbuf[stage] = t->dtex[stage] = t->dsmp[stage] = 0;
}
// DM_RES_CHECK=1 (diagnostic): if textures / buffers the shader accesses through the argument block are not in the residency set, print the first 40 (textures are attributed to the actual allocation via parent texture / underlying buffer)
static int g_res_check_on;
static void res_check(id r, const char *what, int reg) {
    static int nbad;
    if (!g_res_check_on || !r || nbad >= 40) return;
    int is_tex = [r conformsToProtocol:@protocol(MTLTexture)], is_buf = [r conformsToProtocol:@protocol(MTLBuffer)];
    if (!is_tex && !is_buf) return;   // Samplers etc. are not allocations
    id<MTLResource> a = r; int hops = 0;
    if (is_tex) { id<MTLTexture> t = (id<MTLTexture>)a; while (t.parentTexture) { t = t.parentTexture; hops++; } a = t.buffer ? (id<MTLResource>)t.buffer : (id<MTLResource>)t; }
    pthread_mutex_lock(&g_res_mu); int ok = [g_res_objects containsObject:a]; pthread_mutex_unlock(&g_res_mu);
    if (!ok) { nbad++; id<MTLTexture> t = is_tex ? (id<MTLTexture>)r : nil;
        MLOG("【红】 missing residency #%d: %s slot %d %s %p (parent chain %d deep) allocated %lu B storage mode %lu%s", nbad, what, reg, is_tex ? "texture" : "buffer", (__bridge void *)a, hops, (unsigned long)a.allocatedSize, (unsigned long)a.storageMode,
             t ? [NSString stringWithFormat:@" format %lu %lux%lu type %lu usage %#lx", (unsigned long)t.pixelFormat, (unsigned long)t.width, (unsigned long)t.height, (unsigned long)t.textureType, (unsigned long)t.usage].UTF8String : ""); }
}
static void res_commit(void) {
    pthread_mutex_lock(&g_res_mu);
    if (g_res_dirty) { uint64_t t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); [g_res commit]; g_res_dirty = 0; g_rs_commits++; g_rs_commit_ns += clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0; }
    pthread_mutex_unlock(&g_res_mu);
}
// Since the last call: residency commits (count, time), additions by source line (count, MB; the four largest by bytes) and removals
void nvn_be_res_stats(char *out, size_t n) {
    pthread_mutex_lock(&g_res_mu);
    uint64_t tn = 0, tb = 0; for (int k = 0; k < RS_SITES; k++) { tn += g_rs_site[k].n; tb += g_rs_site[k].bytes; }
    size_t o = snprintf(out, n, "commits %llu / %.1f ms, added %llu, %.0f MB (", (unsigned long long)g_rs_commits, g_rs_commit_ns / 1e6, (unsigned long long)tn, tb / 1048576.0);
    for (int i = 0; i < 4 && o < n; i++) { int best = -1; for (int k = 0; k < RS_SITES; k++) if (g_rs_site[k].n && (best < 0 || g_rs_site[k].bytes > g_rs_site[best].bytes)) best = k;
        if (best < 0) break; o += snprintf(out + o, n - o, "%sline %d: %llu, %.0f MB", i ? ", " : "", g_rs_site[best].line, (unsigned long long)g_rs_site[best].n, g_rs_site[best].bytes / 1048576.0); g_rs_site[best].n = 0; }
    if (o < n) snprintf(out + o, n - o, "), removed %llu", (unsigned long long)g_rs_rm);
    memset(g_rs_site, 0, sizeof g_rs_site); g_rs_rm = g_rs_commits = g_rs_commit_ns = 0;
    pthread_mutex_unlock(&g_res_mu);
}

static char g_atomic_root_key;   // associated object on an RGBA8 view: the R32 integer storage it was made over for image atomics (tex_upgrade)
static char g_twin_view_key;     // associated object on an sRGB / linear view tex_mtl_ / tex_upgrade made of an NVN texture's twin (srgb_twin_mark): only those are judged stale or remade.
                                 //   A view's shape alone is not ours: an external texture (mtl_ext_tex, e.g. a BGRA8_sRGB view of a linear swapchain image) has the same shape and no NVN twin
@interface NvDeferredRelease : NSObject { @public id object; uint64_t fence; int keep_resident; } @end
@implementation NvDeferredRelease @end
static NSMutableArray<NvDeferredRelease *> *g_deferred;
static pthread_mutex_t g_deferred_mu = PTHREAD_MUTEX_INITIALIZER;
// Deferred release has two meanings that must be kept apart (the root of the GPU memory fault on the first frame on entering Travincal):
//   defer_obj_release = this object is retired: drop the reference after the submissions that used it complete, and remove it from the residency set;
//   defer_obj_unref   = only the reference I hold is no longer wanted, the object itself may still be in use (the view cache of a texture ID may hold the base texture itself): only drop the reference, leave the residency set alone.
// Previously only the former existed: when the view cache was invalidated, a texture that 'is still the current storage of some serial' was also removed from the residency set. Invalidation used to happen only when the base texture was really replaced, so it was never hit;
// after the transparency chain's in-place composite swapped the storage of two textures, each of the two live textures was removed once this way, and afterwards they are used as attachments and sampled every frame as usual - the GPU accesses non-resident memory.
static void defer_obj_release_ex(id obj, int keep_resident) {
    if (!obj) return;
    NvDeferredRelease *d = [NvDeferredRelease new]; d->object = obj; d->fence = g_fence + 1; d->keep_resident = keep_resident;
    pthread_mutex_lock(&g_deferred_mu);
    if (!g_deferred) g_deferred = [NSMutableArray array];
    [g_deferred addObject:d];
    pthread_mutex_unlock(&g_deferred_mu);
}
static void defer_obj_release(id obj) { defer_obj_release_ex(obj, 0); }
static void defer_obj_unref(id obj) { defer_obj_release_ex(obj, 1); }
// Its own autorelease pool: nvn_be_sub_begin drains before it pushes the submission's pool, on the guest submit thread, whose implicit pool is never drained. The weak-table lookups and the residency-set removal
// autorelease the retired object, so whatever that thread drained (instead of the completion handler, which wins the race only when the CPU is idle) stayed alive for good: in Metroid Dread every
// re-upload of its map mask kept the old texture and its 32 MB upload staging block, and GPU memory grew by several GB within minutes under CPU load.
static void defer_drain(void) { @autoreleasepool {
    NSMutableArray<NvDeferredRelease *> *ready = [NSMutableArray array];
    pthread_mutex_lock(&g_deferred_mu);
    // One pass that keeps the rest: removing each from the middle moved the whole tail, quadratic in the queue, which a scene load fills (upstream reference implementation, MIT: minutes in memmove)
    uint64_t done = g_done;
    for (NvDeferredRelease *d in g_deferred) if (d->fence <= done) [ready addObject:d];
    if (ready.count) { NSMutableArray<NvDeferredRelease *> *keep = [NSMutableArray arrayWithCapacity:g_deferred.count - ready.count]; for (NvDeferredRelease *d in g_deferred) if (d->fence > done) [keep addObject:d]; g_deferred = keep; }
    pthread_mutex_unlock(&g_deferred_mu);
    for (NvDeferredRelease *d in ready) {
        id obj = d->object;
        if (!d->keep_resident && [obj conformsToProtocol:@protocol(MTLResource)]) {
            pthread_mutex_lock(&g_res_mu);
            int registered = [g_res_objects containsObject:obj];
            pthread_mutex_unlock(&g_res_mu);
            if (registered) res_remove((id<MTLResource>)obj);
            id root = objc_getAssociatedObject(obj, &g_atomic_root_key);   // an RGBA8 view of integer storage made for image atomics (tex_upgrade): the storage is what is resident
            if (root) res_remove((id<MTLResource>)root);
        }
        d->object = nil;
    }
} }

static pthread_mutex_t g_bf_want_mu = PTHREAD_MUTEX_INITIALIZER;
static char **g_bf_want_keys; static size_t g_bf_want_n, g_bf_want_cap; static int g_bf_want_loaded;
void bf_want_note(const char *key) {
    const char *path = getenv("DM_NVN_BF_WANT");
    if (!path || !key || strlen(key) != 16) return;
    for (int i = 0; i < 16; i++) if (!((key[i] >= '0' && key[i] <= '9') || (key[i] >= 'a' && key[i] <= 'f') || (key[i] >= 'A' && key[i] <= 'F'))) return;
    pthread_mutex_lock(&g_bf_want_mu);
    if (!g_bf_want_loaded) {
        FILE *f = fopen(path, "r"); char line[64];
        if (f) { while (fgets(line, sizeof line, f)) { char *e = strpbrk(line, "\r\n"); if (e) *e = 0; if (strlen(line) != 16) continue;
                if (g_bf_want_n == g_bf_want_cap) { size_t c = g_bf_want_cap ? g_bf_want_cap * 2 : 64; if (!GROW(g_bf_want_keys, c * sizeof *g_bf_want_keys, "bf want list")) break; g_bf_want_cap = c; }
                g_bf_want_keys[g_bf_want_n++] = strdup(line); } fclose(f); }
        g_bf_want_loaded = 1;
    }
    for (size_t i = 0; i < g_bf_want_n; i++) if (!strcmp(g_bf_want_keys[i], key)) { pthread_mutex_unlock(&g_bf_want_mu); return; }
    if (g_bf_want_n == g_bf_want_cap) { size_t c = g_bf_want_cap ? g_bf_want_cap * 2 : 64; if (!GROW(g_bf_want_keys, c * sizeof *g_bf_want_keys, "bf want list")) { pthread_mutex_unlock(&g_bf_want_mu); return; } g_bf_want_cap = c; }
    g_bf_want_keys[g_bf_want_n++] = strdup(key);
    FILE *f = fopen(path, "a"); if (f) { fprintf(f, "%s\n", key); fclose(f); }
    pthread_mutex_unlock(&g_bf_want_mu);
}

// ---------- Memory pools ----------
typedef struct { uintptr_t lo, hi; uintptr_t base; __unsafe_unretained id<MTLBuffer> buf; uint64_t gpu; const void *key; int res; uintptr_t host;
    int reg, gm, gslot, gout; uint64_t gseen, gfence; } pool_ent;   // res: already in the residency set (on demand, see pool_res); host: the CPU bytes of the pool (pool_host). The raw pool table's on-demand residency (gmem_scan):
    // reg: an address of it went to the GPU through a binding (pool_res): resident for good; gm: resident because a raw access reached it (1; 2 = for good, no access bit was free);
    // gslot: its bit in the access bitmap + 1 (0: none); gout: times it was taken out for not being reached; gseen: the frame its bit was last seen; gfence: the submission after which the last taking out lets it go
static pool_ent *g_pools; static int g_npool, g_cap;
static int g_pidx_ok, g_plast = -1;   // whether the address→pool index is valid, the last hit (pool_find)
static NSMutableArray *g_keep;                  // Holds the buffer references (pool_ent has non-owning pointers)
static uint64_t g_pool_adds;
static int g_pool_res_n;   // registered pools already in the residency set (for the memory readout; under g_mu)
// Access bits of the raw pool table (gmem_map / gmem_scan): a pool the table lists but the host has not made resident, or made resident only for the table, gets a bit, which a raw
// access sets when it chooses the pool's entry. Bits belong to pools, not entries, so a rebuilt table loses none set by submissions still running. Under g_mu
enum { GSLOT_MAX = 65536 };
static int *g_gslot_pool, *g_gslot_free, g_gslot_nfree, g_gslot_hi;   // bit → pool index (-1: free); freed bits; bits ever given out
static __strong id<MTLBuffer> g_gbits;   // the bitmap the shaders set (GSLOT_MAX bits), resident
static int gslot_get(int i) {   // pool i's bit, given out on first use; -1 when all are taken
    if (g_pools[i].gslot) return g_pools[i].gslot - 1;
    if (!g_gslot_pool) { g_gslot_pool = malloc(sizeof *g_gslot_pool * GSLOT_MAX); g_gslot_free = malloc(sizeof *g_gslot_free * GSLOT_MAX); if (!g_gslot_pool || !g_gslot_free) MDIE("raw global memory: out of memory for the access bits"); }
    int b = g_gslot_nfree ? g_gslot_free[--g_gslot_nfree] : g_gslot_hi < GSLOT_MAX ? g_gslot_hi++ : -1;
    if (b < 0) return -1;
    g_gslot_pool[b] = i; g_pools[i].gslot = b + 1;
    return b;
}
static void gslot_put(int i) {   // pool i goes: its bit is free again (a submission still running may set it once more: the next pool to get it is then taken as reached, which only makes it resident)
    int b = g_pools[i].gslot - 1; if (b < 0) return;
    g_gslot_pool[b] = -1; g_gslot_free[g_gslot_nfree++] = b; g_pools[i].gslot = 0;
    if (g_gbits) atomic_fetch_and((_Atomic uint32_t *)g_gbits.contents + (b >> 5), ~(1u << (b & 31)));
}

#define C1_BANK_SIZE (4u << 20)
#define C1_DECL_SIZE (64u << 10)
static NSMutableArray *g_c1_banks;
static size_t g_c1_bank_off, g_c1_alloc_bytes, g_c1_data_bytes;
static uint64_t g_c1_count, g_c1_exclusive;
static NSMutableSet<NSString *> *g_c1_full;
static int g_c1_full_valid;
static NSDictionary<NSString *, NSString *> *g_cb_ext;   // cb_extent.tsv: shader key → "reg:bytes ..." (how far into each uniform slot the shader can read); nil when stale or missing
static os_unfair_lock g_c1_lock = OS_UNFAIR_LOCK_INIT;

// DM_UDC_SELFTEST=1 (diagnostic, checks DontCare behavior on a real A19 device): private-storage Depth32Float_Stencil8 / RGBA8 (1952x900) are first cleared to write known values,
// then Load + DontCare without drawing, read back and compared pixel by pixel, printing one result line
static void udc_selftest(void) {
    if (!getenv("DM_UDC_SELFTEST")) return;
    id<MTLCommandQueue> q = [g_dev newCommandQueue];
    for (int depth = 1; depth >= 0; depth--) {
        NSUInteger w = 1952, h = 900;
        MTLTextureDescriptor *td = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:depth ? MTLPixelFormatDepth32Float_Stencil8 : MTLPixelFormatRGBA8Unorm width:w height:h mipmapped:NO];
        td.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead; td.storageMode = MTLStorageModePrivate;
        id<MTLTexture> t = [g_dev newTextureWithDescriptor:td];
        id<MTLCommandBuffer> cb = [q commandBuffer];
        for (int pass = 0; pass < 2; pass++) {
            MTLRenderPassDescriptor *rp = [MTLRenderPassDescriptor renderPassDescriptor];
            MTLLoadAction la = pass ? MTLLoadActionLoad : MTLLoadActionClear; MTLStoreAction sa = pass ? MTLStoreActionDontCare : MTLStoreActionStore;
            if (depth) { rp.depthAttachment.texture = t; rp.depthAttachment.loadAction = la; rp.depthAttachment.storeAction = sa; rp.depthAttachment.clearDepth = 0.3125;
                         rp.stencilAttachment.texture = t; rp.stencilAttachment.loadAction = la; rp.stencilAttachment.storeAction = sa; rp.stencilAttachment.clearStencil = 0x5a; }
            else { rp.colorAttachments[0].texture = t; rp.colorAttachments[0].loadAction = la; rp.colorAttachments[0].storeAction = sa; rp.colorAttachments[0].clearColor = MTLClearColorMake(0.2, 0.4, 0.6, 0.8); }
            [[cb renderCommandEncoderWithDescriptor:rp] endEncoding];
        }
        id<MTLBuffer> out = [g_dev newBufferWithLength:w * h * 4 options:MTLResourceStorageModeShared];
        id<MTLBlitCommandEncoder> b = [cb blitCommandEncoder];
        [b copyFromTexture:t sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(w, h, 1) toBuffer:out destinationOffset:0
            destinationBytesPerRow:w * 4 destinationBytesPerImage:w * h * 4 options:depth ? MTLBlitOptionDepthFromDepthStencil : MTLBlitOptionNone];
        [b endEncoding]; [cb commit]; [cb waitUntilCompleted];
        const uint32_t *px = out.contents; NSUInteger bad = 0; for (NSUInteger i = 0; i < w * h; i++) if (px[i] != px[0]) bad++;
        MLOG("UDC self-check %s %s %lux%lu first value %08x, values differing from it %lu / %lu", g_dev.name.UTF8String, depth ? "Depth32F_S8" : "RGBA8", (unsigned long)w, (unsigned long)h, px[0], (unsigned long)bad, (unsigned long)(w * h));
    }
}
void mtl_init(void) {
    if (g_dev) return;
    const char *vbc = getenv("DM_NVN_VBUF_CACHE"); g_vbuf_cache = !(vbc && !strcmp(vbc, "0"));
    const char *link = getenv("DM_PRESENT_LINK");
    g_dm_present_link = link ? atoi(link) : 1; if (g_dm_present_link < 0 || g_dm_present_link > 2) g_dm_present_link = 1;   // Default 1 (real-device same-process alternation: when load exceeds one display-link period, long frames 15% → 0 and frame intervals even out; no difference from 0 at a steady 60); DM_PRESENT_LINK=0 turns it off   // 1 = present on every tick of a 60 Hz display link; 2 = 120 Hz display link, the game presents a frame every other display-link tick (when behind, it can present on the next 8.33 ms display-link tick)
    const char *latency = getenv("DM_PRESENT_LATENCY");
    if (latency && atoi(latency) > 0) g_present_latency = atoi(latency);
    g_res_check_on = getenv("DM_RES_CHECK") != NULL;
    s2a_mtl_slot_take("mtl_init");   // machine-wide Metal client slot (graphics/metal/mtl_slot.h): taken before the device, held until exit
    g_dev = MTLCreateSystemDefaultDevice();
    if (!g_dev) MDIE("no Metal device");
    if (!g_dev.hasUnifiedMemory) MDIE("needs a unified-memory device (zero-copy memory pools)");
    int os26 = 0, family4 = 0, ios26x = 0; const char *be_why;
    if (@available(macOS 26.0, iOS 26.0, *)) { os26 = 1; family4 = [g_dev supportsFamily:MTLGPUFamilyMetal4]; }
#if TARGET_OS_IPHONE
    if (os26) { if (@available(iOS 27.0, *)) {} else ios26x = 1; }   // iOS 26.x：见 nvn_be.h（#311）
#endif
    g_m3 = nvn_be_pick(getenv("NXGAL_BE"), os26, family4, ios26x, &be_why) == NVN_BE_MTL3;
    MLOG("direct backend: Metal %d (%s)", g_m3 ? 3 : 4, be_why);
    g_mesh_ok = [g_dev supportsFamily:MTLGPUFamilyMetal3];   // object / mesh functions (NVN2 DrawMeshTasks): Apple7+ / Mac2, every Metal 4 GPU; an older GPU on the Metal 3 path has none
    g_red_emu = !s2a_reduce_native(g_dev); g_lb_emu = !s2a_lodbias_native(g_dev);
    g_red_emu_why = s2a_samp_emu_forced() ? "forced by S2A_SAMP_EMU=1" : !os26 ? "macOS / iOS before 26" : "the GPU is not Apple10";
    MLOG("sampler reduction: %s; sampler LOD bias: %s (%s)", g_red_emu ? "in the shader" : "native", g_lb_emu ? "in the shader" : "native", g_dev.name.UTF8String);
    g_q = [g_dev newCommandQueue];
    MTLResidencySetDescriptor *rd = [MTLResidencySetDescriptor new];
    rd.initialCapacity = 4096;
    NSError *re = nil;
    g_res = [g_dev newResidencySetWithDescriptor:rd error:&re];
    if (!g_res) MDIE("failed to create the MTLResidencySet");
    [g_q addResidencySet:g_res];
    { void crash_set_wait_dump(void (*fn)(void)); void mtl_wait_state_dump(void); crash_set_wait_dump(mtl_wait_state_dump); }
    if (g_m3) {
        // The same residency set on an old queue (macOS 15 / iOS 18 on). Not made here: the Metal 4 queue, the three allocator rotations (main, upload, present), the argument tables
        // (bindings are D3-3 #279), the present argument table and UV buffers (present_encode binds directly)
        g_q3 = [g_dev newCommandQueue];
        if (!g_q3) MDIE("failed to create the Metal 3 MTLCommandQueue");
        [g_q3 addResidencySet:g_res];
        g_fence3 = [g_dev newFence];
        NSError *te = nil;   // the argument tables as DmTable3 (#279 D3-3; tab_new)
        g_vt = tab_new(31, 1, 0, &te); g_ft = tab_new(31, 1, 0, &te); g_ct = tab_new(31, 1, 0, &te); g_up_ct = tab_new(31, 1, 0, &te); g_ot = tab_new(31, 1, 0, &te); g_present_args = tab_new(1, 1, 1, &te);
        if (!g_vt || !g_ft || !g_ct || !g_up_ct || !g_present_args) MDIE("failed to create the Metal 3 argument tables: %s", te.localizedDescription.UTF8String);
        // Metal 3 编码线程：缺省关（DM_NVN_ENC_THREAD=1 可开），rec_on() 按 g_m3 判断
        MLOG("Metal 3 path: draw passes, copies and fills on the old encoders (D3-2 #278), argument tables DmTable3 (D3-3 #279), bindings below a buffer's start through prefixed scratch (D3-4 #329)");
    } else {
        dispatch_queue_attr_t feedback_attr = s2a_qos_queue_attr(DISPATCH_QUEUE_SERIAL, S2A_QOS_MTL_FEEDBACK);
        g_feedback_q = dispatch_queue_create("dm.nvn.mtl4-feedback", feedback_attr);
        MTL4CommandQueueDescriptor *q4d = [MTL4CommandQueueDescriptor new]; q4d.feedbackQueue = g_feedback_q;
        g_q4 = [g_dev newMTL4CommandQueueWithDescriptor:q4d error:&re];
        if (!g_q4) MDIE("failed to create the MTL4CommandQueue");
        [g_q4 addResidencySet:g_res];
        g_alloc_n = 3;
        for (int i = 0; i < 3; i++) {
            MTL4CommandAllocatorDescriptor *ad = [MTL4CommandAllocatorDescriptor new];
            ad.label = [NSString stringWithFormat:@"nvn-mtl allocator %d", i];
            NSError *ae = nil;
            g_alloc4[i] = [g_dev newCommandAllocatorWithDescriptor:ad error:&ae];
            if (!g_alloc4[i]) MDIE("failed to create MTL4CommandAllocator[%d]: %s", i, ae.localizedDescription.UTF8String);
            g_up_alloc4[i] = [g_dev newCommandAllocatorWithDescriptor:ad error:&ae];
            if (!g_up_alloc4[i]) MDIE("failed to create upload MTL4CommandAllocator[%d]: %s", i, ae.localizedDescription.UTF8String);
            MTL4CommandAllocatorDescriptor *pad = [MTL4CommandAllocatorDescriptor new];
            pad.label = [NSString stringWithFormat:@"nvn-mtl present allocator %d", i];
            g_present_alloc4[i] = [g_dev newCommandAllocatorWithDescriptor:pad error:&ae];
            if (!g_present_alloc4[i]) MDIE("failed to create present MTL4CommandAllocator[%d]: %s", i, ae.localizedDescription.UTF8String);
            g_present_cb[i] = [g_dev newCommandBuffer];
            if (!g_present_cb[i]) MDIE("failed to create present MTL4CommandBuffer[%d]", i);
        }
        MTL4ArgumentTableDescriptor *atd = [MTL4ArgumentTableDescriptor new];
        atd.maxBufferBindCount = 31; atd.maxTextureBindCount = 1;
        NSError *ate = nil;
        g_vt = rec_table([g_dev newArgumentTableWithDescriptor:atd error:&ate]); if (!g_vt) MDIE("failed to create the vertex argument table: %s", ate.localizedDescription.UTF8String);
        g_vt_valid = 0;
        g_ft = rec_table([g_dev newArgumentTableWithDescriptor:atd error:&ate]); if (!g_ft) MDIE("failed to create the fragment argument table: %s", ate.localizedDescription.UTF8String);
        g_ct = rec_table([g_dev newArgumentTableWithDescriptor:atd error:&ate]); if (!g_ct) MDIE("failed to create the compute argument table: %s", ate.localizedDescription.UTF8String);
        g_ot = rec_table(tab_new(31, 1, 0, &ate));   // through tab_new: the object table is new code (avail / MTL4 ratchets)
        if (!g_ot) MDIE("failed to create the object argument table: %s", ate.localizedDescription.UTF8String);
        g_up_ct = [g_dev newArgumentTableWithDescriptor:atd error:&ate]; if (!g_up_ct) MDIE("failed to create the upload compute argument table: %s", ate.localizedDescription.UTF8String);
        MTL4ArgumentTableDescriptor *pad = [MTL4ArgumentTableDescriptor new];
        pad.maxTextureBindCount = 1; pad.maxSamplerStateBindCount = 1; pad.maxBufferBindCount = 1;
        g_present_args = [g_dev newArgumentTableWithDescriptor:pad error:&ate];
        if (!g_present_args) MDIE("failed to create the present argument table: %s", ate.localizedDescription.UTF8String);
        for (int i = 0; i < 3; i++) {
            g_present_uv[i] = [g_dev newBufferWithLength:sizeof(float) * 8 options:MTLResourceStorageModeShared];
            if (!g_present_uv[i]) MDIE("failed to create present UV buffer[%d]", i);
            res_add(g_present_uv[i]);
        }
    }
    g_half_masks = [g_dev newBufferWithLength:256 * sizeof(uint32_t) options:MTLResourceStorageModeShared];
    if (!g_half_masks) MDIE("failed to create the half color rounding table");
    for (unsigned i = 0; i < 256; i++) ((uint32_t *)g_half_masks.contents)[i] = i;
    res_add(g_half_masks);
    g_ev = [g_dev newSharedEvent];
    g_keep = [NSMutableArray array];
    // Both backends share one pipeline (newComputePipelineStateWithFunction); only the encode differs: Metal 4 sets an argument table and takes the parameter block from a buffer, Metal 3 passes it
    // with setBytes on the old compute encoder (#329 D3-4 class 3). Same kernel, so the Metal 3 result is byte-identical to the CPU deswizzle it replaces.
    g_nvn_deswz_gpu = nvn_deswz_gpu_init(g_dev) == 0;
    dm_res_report_register(mtl_res_counts);
    if (g_m3 && g_nvn_deswz_gpu) MLOG("Metal 3: GPU deswizzle on (classic compute encoder, parameter block through setBytes)");
    else if (!g_nvn_deswz_gpu) MLOG("【红】 GPU deswizzle init failed; swizzled textures fall back to the CPU");
    MLOG("Metal device %s", g_dev.name.UTF8String);
    udc_selftest();
    warm_announce();
}



// No-copy buffers of finalized pools (weak references, under g_mu): the memory report counts how many are still alive and their length -- a buffer that outlives its pool is still strongly referenced by something else (a texture built directly on the pool, etc.)
static NSHashTable *g_dead_pools;
// Address → pool cache per thread (nvn_be_addr / mtl_gpu_addr), valid while g_pool_gen is unchanged (every pool add / removal bumps it under g_mu), holding only pools already in the residency set.
// Every buffer binding of every draw used to take g_mu, which game threads creating pools and the GPU completion handler also take, and search the pool index. Two levels: a table direct-mapped
// by 4 KB page, then the last 8 pools found, which also fill the table. Breath of the Wild binds from more pools a frame than 8 entries alone could hold (about 2300 of its 21000 lookups a frame
// took the lock), and its uniform rings move to a new page every few draws (the table alone missed as often)
enum { PC_BITS = 10, PC_RECENT = 8 };
static _Atomic uint64_t g_pool_gen = 1;
typedef struct { uintptr_t lo, hi, base; __unsafe_unretained id<MTLBuffer> buf; uint64_t gpu; uintptr_t host; } pc_ent;   // host: buf.contents (the pool's pages, or their far shadow), kept so a CPU read sends no message
static __thread struct { uint64_t gen; unsigned next; pc_ent r[PC_RECENT], e[1u << PC_BITS]; } t_pc;   // an empty entry has hi 0
static inline unsigned pc_slot(uint64_t addr) { return (unsigned)(((addr >> 12) * 0x9E3779B97F4A7C15ull) >> (64 - PC_BITS)); }
static inline const pc_ent *pc_get(uint64_t addr, uint64_t len) {
    if (t_pc.gen != atomic_load_explicit(&g_pool_gen, memory_order_acquire)) return NULL;
    pc_ent *c = &t_pc.e[pc_slot(addr)];
    if (addr >= c->lo && addr + len <= c->hi) return c;
    for (unsigned k = 0; k < PC_RECENT; k++) { const pc_ent *x = &t_pc.r[k]; if (addr >= x->lo && addr + len <= x->hi) { *c = *x; return c; } }
    return NULL;
}
static void pc_put(int i, uint64_t addr) {   // caller holds g_mu, pool i is resident and holds addr
    uint64_t gen = atomic_load_explicit(&g_pool_gen, memory_order_relaxed);
    if (t_pc.gen != gen) { memset(t_pc.r, 0, sizeof t_pc.r); memset(t_pc.e, 0, sizeof t_pc.e); t_pc.gen = gen; }
    pc_ent c = {g_pools[i].lo, g_pools[i].hi, g_pools[i].base, g_pools[i].buf, g_pools[i].gpu, g_pools[i].host};
    t_pc.e[pc_slot(addr)] = c; t_pc.r[t_pc.next++ % PC_RECENT] = c;
}
static _Atomic uint64_t g_reg_gen = 1;   // Change generation of memory pool / texture / sampler registration: one of the invalidation conditions for argument buffer reuse
// Raw global memory (gmem_map below) reaches only pools the game holds a GPU address in, and the driver gives addresses out by buffer, pool or texture (hle_nvn.c pool_mark_addressed:
//   GetBufferAddress / BufferInitialize / GetTextureAddress, the pool's own CPU range). A pool with none holds only textures, which Metal keeps in textures of its own: the table leaves it
//   out and nothing wires it for the table's sake (upstream reference implementation (MIT): Ocarina of Time, 172 pools of 3,721 MB of 4,588 MB held only textures, with them in the first
//   scene passed Metal's working set). Sorted, disjoint CPU ranges. Under g_mu
static struct { uintptr_t lo, hi; } *g_addr; static int g_naddr, g_addr_cap;
static int addr_first(uintptr_t lo) { int a = 0, b = g_naddr; while (a < b) { int m = (a + b) / 2; if (g_addr[m].hi <= lo) a = m + 1; else b = m; } return a; }   // the first range that ends after lo
static int addr_meets(uintptr_t lo, uintptr_t hi) { int i = addr_first(lo); return i < g_naddr && g_addr[i].lo < hi; }
void nvn_be_pool_addressed(const void *mem, uint64_t size) {
    uintptr_t lo = (uintptr_t)mem, hi = lo + (size ? size : 1);
    if (!mem) return;
    pthread_mutex_lock(&g_mu);
    int i = addr_first(lo);
    if (i == g_naddr || g_addr[i].lo > lo || g_addr[i].hi < hi) {
        if (i > 0 && g_addr[i - 1].hi == lo) i--;   // touching on the left
        int j = i;
        while (j < g_naddr && g_addr[j].lo <= hi) { lo = MIN(lo, g_addr[j].lo); hi = MAX(hi, g_addr[j].hi); j++; }
        if (i == j && g_naddr == g_addr_cap) { int c = g_addr_cap ? g_addr_cap * 2 : 256;
            if (!GROW(g_addr, (size_t)c * sizeof *g_addr, "addressed pool ranges")) { pthread_mutex_unlock(&g_mu); { static int said; if (!said++) MLOG("【红】 raw global memory: the addressed pool range table could not grow: pool %p+%#llx stays out of the pool table", mem, (unsigned long long)size); } return; }
            g_addr_cap = c; }
        if (j != i + 1) memmove(g_addr + i + 1, g_addr + j, (size_t)(g_naddr - j) * sizeof *g_addr);
        g_naddr += 1 - (j - i); g_addr[i].lo = lo; g_addr[i].hi = hi;
        atomic_fetch_add(&g_pool_gen, 1);   // the pool table rebuilds before the next draw that uses it (gmem_map)
    }
    pthread_mutex_unlock(&g_mu);
}
// On-demand residency of memory pools: putting a zero-copy buffer into the residency set makes iOS read the whole pool into memory and pin it as wired, even a pool the game never uses
// (they measured on a 17 Pro Max a 512 MB render-target pool addressed 0 times in a run, with about 530 MB more device wired memory; a 4 GB A14 was ended by the system within seconds of launch because of it).
// So a pool is not put into the residency set when created; it is put in, and the residency set committed on the spot, the first time the GPU gets its address through nvn_be_addr / mtl_gpu_addr -- these are the only two ways the GPU gets pool addresses,
// and committing on the spot is earlier than any command buffer commit that uses it. CPU-side reads of pool contents through nvn_be_addr trigger it too (conservative, never misses). Caller holds g_mu
static uint64_t g_gmem_rgen = 1;   // the raw pool table's residency generation (gmem_map rebuilds when it moves)
static void pool_res(int i) {
    if (!g_pools[i].reg) { g_pools[i].reg = 1; if (g_pools[i].gslot) g_gmem_rgen++; }   // the raw pool table never takes it out (gmem_scan): bindings encoded with its address may be reused;
                                                                                          //   a table that has its entry cold or tracked is rebuilt with it plainly usable
    if (g_pools[i].res) return;
    res_add(g_pools[i].buf); res_commit(); g_pools[i].res = 1; g_pool_res_n++;
}
__attribute__((weak)) uint8_t *s2a_far_g2h(uint64_t a) { (void)a; return NULL; }   // native far.c; graphics unit tests have no far region
// The game's address of a memory pool may lie in the far part of the alias region (address-space root fix: the host has no address there, the contents live in
// the shadow, runtime/src/far.c). The zero-copy buffer is then built over the shadow; offsets into the buffer equal offsets from the pool's guest base.
// A pool mapped by one physical-map request is contiguous in the shadow. One the game made over memory of several requests need not be: the shadow is handed out in 2 MiB blocks in the
//   order the game maps them (runtime/src/far.c), so neighbouring guest blocks usually, not always, get neighbouring shadow blocks (#450, a first-party RPG on an iPhone: a 61 MB pool
//   whose shadow broke at a 2 MiB boundary, and this stopped the game before its first frame). One buffer needs one host range: the blocks' shadow pages are mapped again, in guest
//   order, into one reserved range (vm_remap, no copy: the same pages, so the shadow and the view are the same memory for the CPU, the GPU and the far-fault emulation); *view = 1 then,
//   and the range goes with the buffer (its deallocator)
static uintptr_t pool_host(uintptr_t a, uintptr_t b, int *view) {
    *view = 0;
    uint8_t *h = s2a_far_g2h(a);
    if (!h) return a;
    uintptr_t gap = 0;
    for (uintptr_t x = (a | 0x1FFFFF) + 1; x < b && !gap; x += 0x200000) if (s2a_far_g2h(x) != h + (x - a)) gap = x;
    if (!gap) return (uintptr_t)h;
    vm_address_t v = 0; kern_return_t kr = vm_allocate(mach_task_self(), &v, b - a, VM_FLAGS_ANYWHERE);
    if (kr != KERN_SUCCESS) MDIE("memory pool %#lx..%#lx: its far shadow is not contiguous at %#lx and no host range of %#lx bytes could be reserved for one view of it (%d)", (unsigned long)a, (unsigned long)b, (unsigned long)gap, (unsigned long)(b - a), kr);
    unsigned pieces = 0;
    for (uintptr_t x = a; x < b; pieces++) {
        uintptr_t e = MIN((x | 0x1FFFFF) + 1, b); uint8_t *src = s2a_far_g2h(x);
        vm_address_t dst = v + (x - a); vm_prot_t cur, max;
        if (!src || (kr = vm_remap(mach_task_self(), &dst, e - x, 0, VM_FLAGS_FIXED | VM_FLAGS_OVERWRITE, mach_task_self(), (vm_address_t)src, FALSE, &cur, &max, VM_INHERIT_NONE)) != KERN_SUCCESS || dst != v + (x - a))
            MDIE("memory pool %#lx..%#lx: mapping its far shadow block at %#lx into one view failed (%s %d)", (unsigned long)a, (unsigned long)b, (unsigned long)x, src ? "vm_remap" : "no shadow", src ? kr : 0);
        x = e;
    }
    { static int n; if (n++ < 8) MLOG("memory pool %#lx..%#lx: its far shadow is not contiguous (first break at %#lx); one view of its %u shadow pieces made at %#lx", (unsigned long)a, (unsigned long)b, (unsigned long)gap, pieces, (unsigned long)v); }
    *view = 1; return (uintptr_t)v;
}
static void nvn_be_pool_add_body(const void *mem, uint64_t size);
void nvn_be_pool_add(const void *mem, uint64_t size) { @autoreleasepool { nvn_be_pool_add_body(mem, size); } }
static void nvn_be_pool_add_body(const void *mem, uint64_t size) {
    mtl_init(); g_reg_gen++;
    uintptr_t pg = (uintptr_t)getpagesize(), lo = (uintptr_t)mem, hi = lo + size;
    int view = 0; uintptr_t a = lo & ~(pg - 1), b = (hi + pg - 1) & ~(pg - 1), ha = pool_host(a, b, &view);
    void (^unview)(void *, NSUInteger) = view ? ^(void *p, NSUInteger n) { vm_deallocate(mach_task_self(), (vm_address_t)p, n); } : nil;   // a view of a split shadow goes with its buffer (pool_host)
    if (ha != a) MLOG("memory pool %p+%#llx is in the far alias region: zero-copy buffer over its shadow %#lx", mem, (unsigned long long)size, (unsigned long)ha);
    id<MTLBuffer> buf = [g_dev newBufferWithBytesNoCopy:(void *)ha length:b - a options:MTLResourceStorageModeShared deallocator:unview];
    // Pokémon Legends: Z-A: twice on the Mac a small pool's buffer was refused although its pages were one read-write VM region, both times while another heavy job (a shader compile,
    // a second game instance) took the machine's memory; every run on an idle machine created all of them. Wiring the pages may fail under memory pressure: retry for up to about 2 s
    for (int t = 0; !buf && t < 12; t++) {
        usleep(10000u << (t < 4 ? t : 4));
        buf = [g_dev newBufferWithBytesNoCopy:(void *)ha length:b - a options:MTLResourceStorageModeShared deallocator:unview];
        if (buf) MLOG("【红】 memory pool %p+%#llx: the zero-copy buffer was refused, created at retry %d", mem, (unsigned long long)size, t + 1);
    }
    if (!buf) {   // say what the pages looked like: every VM region over the range, with its protection (an unmapped page in the range is the usual cause)
        for (vm_address_t r = ha; r < ha + (b - a); ) {
            vm_size_t rs = 0; vm_region_basic_info_data_64_t vi; mach_msg_type_number_t cnt = VM_REGION_BASIC_INFO_COUNT_64; mach_port_t obj = MACH_PORT_NULL;
            if (vm_region_64(mach_task_self(), &r, &rs, VM_REGION_BASIC_INFO_64, (vm_region_info_t)&vi, &cnt, &obj) != KERN_SUCCESS) { MLOG("【红】   no VM region at or after %#llx", (unsigned long long)r); break; }
            MLOG("【红】   VM region %#llx+%#llx protection %d (max %d)", (unsigned long long)r, (unsigned long long)rs, vi.protection, vi.max_protection);
            r += rs;
        }
        MDIE("memory pool %p+%#llx: failed to create the zero-copy buffer over %#lx..%#lx", mem, (unsigned long long)size, (unsigned long)ha, (unsigned long)(ha + (b - a)));
    }
    pthread_mutex_lock(&g_mu);
    if (g_npool == g_cap) { int c = g_cap ? g_cap * 2 : 64;
        if (!GROW(g_pools, (size_t)c * sizeof *g_pools, "memory pool table")) { pthread_mutex_unlock(&g_mu); MLOG("【红】 memory pool %p+%#llx not registered: its addresses resolve to nothing (draws using it are skipped)", mem, (unsigned long long)size); return; }
        g_cap = c; }
    g_pidx_ok = 0; g_plast = -1; atomic_fetch_add(&g_pool_gen, 1);   // the address index and the per-thread caches are invalid (pool_find, pc_get)
    g_pools[g_npool++] = (pool_ent){lo, hi, a, buf, buf.gpuAddress, mem, 0, ha};   // not in the residency set yet: put in the first time it is addressed (pool_res)
    g_pool_adds++;
    [g_keep addObject:buf];
    pthread_mutex_unlock(&g_mu);
}

static void nvn_be_pool_del_body(const void *mem);
void nvn_be_pool_del(const void *mem) { @autoreleasepool { nvn_be_pool_del_body(mem); } }
static void nvn_be_pool_del_body(const void *mem) {
    g_reg_gen++;
    pthread_mutex_lock(&g_mu);
    // The no-copy buffer goes through deferred release (out of the residency set and unreferenced after submitted commands complete). It used to be removed only from g_keep while the residency set still held a strong reference: after the pool was freed the buffer stayed alive wrapping that guest memory,
    // and a new pool at the same address wrapped it again. Engage's title demo cycles scenes; GPU allocated grew to 5.4 GB and resident memory to 3.6 GB in 850 s
    for (int i = 0; i < g_npool; i++)
        if (g_pools[i].key == mem) { id<MTLBuffer> b = g_pools[i].buf; [g_keep removeObject:b]; defer_obj_release(b); if (g_pools[i].res) g_pool_res_n--;
            if (!g_dead_pools) g_dead_pools = [NSHashTable weakObjectsHashTable];
            gslot_put(i);
            [g_dead_pools addObject:b]; g_pools[i] = g_pools[--g_npool]; if (i < g_npool && g_pools[i].gslot) g_gslot_pool[g_pools[i].gslot - 1] = i;   // the moved pool's bit follows it
            g_pidx_ok = 0; g_plast = -1; atomic_fetch_add(&g_pool_gen, 1); break; }
    pthread_mutex_unlock(&g_mu);
}

// Address → pool: the last hit first, then a binary search over indices sorted by start address, and a full linear scan only when that fails (pools overlapping).
// The Legend of Zelda: Breath of the Wild keeps about 1760 memory pools alive and every buffer binding of every draw looks one up; the old full scan took about 4% of the submit thread's samples (mtl_gpu_addr 222 / 6 s). Adding / removing pools invalidates the index, which is re-sorted when next used. Caller holds g_mu
static int *g_pidx; static int g_pidx_cap;
static int pidx_cmp(const void *a, const void *b) { uintptr_t x = g_pools[*(const int *)a].lo, y = g_pools[*(const int *)b].lo; return x < y ? -1 : x > y; }
static int pool_find(uint64_t addr, uint64_t len) {
    if (g_plast >= 0 && g_plast < g_npool && addr >= g_pools[g_plast].lo && addr + len <= g_pools[g_plast].hi) return g_plast;
    if (!g_pidx_ok) {
        if (g_pidx_cap < g_npool) { int c = g_npool * 2; if (!GROW(g_pidx, (size_t)c * sizeof *g_pidx, "pool address index")) { for (int i = 0; i < g_npool; i++) if (addr >= g_pools[i].lo && addr + len <= g_pools[i].hi) return g_plast = i; return -1; } g_pidx_cap = c; }   // no index: the full scan
        for (int i = 0; i < g_npool; i++) g_pidx[i] = i;
        qsort(g_pidx, (size_t)g_npool, sizeof *g_pidx, pidx_cmp); g_pidx_ok = 1;
    }
    int lo = 0, hi = g_npool - 1, hit = -1;   // the last one whose start ≤ addr
    while (lo <= hi) { int m = (lo + hi) / 2; if (g_pools[g_pidx[m]].lo <= addr) { hit = m; lo = m + 1; } else hi = m - 1; }
    if (hit >= 0 && addr + len <= g_pools[g_pidx[hit]].hi) return g_plast = g_pidx[hit];
    for (int i = 0; i < g_npool; i++) if (addr >= g_pools[i].lo && addr + len <= g_pools[i].hi) return g_plast = i;
    return -1;
}
// An address no pool holds may lie in a virtual pool's pages that cannot be aliased (mapped at 4 KB, not on a host page): hle_nvn.c then makes copies of them from its page table
//   and registers them as a pool (审计 #1592 P1-112; textures read the page table themselves), and the lookup is made once more: len bytes must be covered, up to want are copied
//   where pages are mapped (a binding looked up by its first byte, as before, still gets its whole range copied)
int nvn_sparse_shadow(uint64_t a, uint64_t len, uint64_t want);
int nvn_be_addr(uint64_t addr, uint64_t len, void **buf, uint64_t *off) {
    addr = nvn_ga2ca(addr);   // 兜底：录制入口已换成 CPU 地址，这里只接住从游戏内存里读出、没在读出处换的 GPU 地址（hle_nvn.c GPU 地址空间）
    const pc_ent *c = pc_get(addr, len);
    if (c) { *buf = (__bridge void *)c->buf; *off = addr - c->base; return 1; }
    int ok = 0;
    pthread_mutex_lock(&g_mu);
    int i = pool_find(addr, len);
    if (i >= 0) { pool_res(i); pc_put(i, addr); *buf = (__bridge void *)g_pools[i].buf; *off = addr - g_pools[i].base; ok = 1; }
    pthread_mutex_unlock(&g_mu);
    if (!ok && nvn_sparse_shadow(addr, len, len)) {   // outside g_mu: it registers pools (g_vp_mu → g_mu)
        pthread_mutex_lock(&g_mu); i = pool_find(addr, len);
        if (i >= 0) { pool_res(i); pc_put(i, addr); *buf = (__bridge void *)g_pools[i].buf; *off = addr - g_pools[i].base; ok = 1; }
        pthread_mutex_unlock(&g_mu); }
    return ok;
}
// The CPU bytes behind a pool address: the pool buffer's contents at its offset, from the kept pointer (pool_ent / pc_ent host) instead of -[MTLBuffer contents]. That message, contents
//   being an inner pointer, also retained and autoreleased the buffer at every read; the reads are per draw (bindless handles, uniform floats). From upstream (MIT) 442680db (#1070):
//   Fire Emblem: Fortune's Weave about 4% of the submit thread in the reads and as much in the autorelease drain. Here the pool's pages may be a far shadow (pool_host), so the kept
//   pointer is the buffer's own, not the guest address
static inline const uint8_t *addr_cpu(uint64_t addr, uint64_t len) {
    addr = nvn_ga2ca(addr);
    const pc_ent *c = pc_get(addr, len);
    if (c) return (const uint8_t *)(c->host + (addr - c->base));
    const uint8_t *r = NULL;
    pthread_mutex_lock(&g_mu);
    int i = pool_find(addr, len);
    if (i >= 0) { pool_res(i); pc_put(i, addr); r = (const uint8_t *)(g_pools[i].host + (addr - g_pools[i].base)); }
    pthread_mutex_unlock(&g_mu);
    if (!r) { void *mb; uint64_t mo; if (nvn_be_addr(addr, len, &mb, &mo)) r = (const uint8_t *)[(__bridge id<MTLBuffer>)mb contents] + mo; }   // a sparse shadow registered on the way (nvn_be_addr)
    return r;
}
// *avail: bytes the GPU pointer has behind it up to the end of the pool's zero-copy buffer (mtl_add_pool rounds the pool's end up to a page). Audit #1534 P1-65 probe (encode_args)
static inline uint64_t pool_buf_end(uintptr_t hi) { static uintptr_t pg; if (!pg) pg = (uintptr_t)getpagesize(); return (hi + pg - 1) & ~(pg - 1); }
static inline int gpu_addr_want(uint64_t addr, uint64_t len, uint64_t want, void **buf, uint64_t *off, uint64_t *gpu, uint64_t *avail) {
    addr = nvn_ga2ca(addr);   // 同 nvn_be_addr
    const pc_ent *c = pc_get(addr, len);
    if (c) { *buf = (__bridge void *)c->buf; *off = addr - c->base; *gpu = c->gpu + *off; *avail = pool_buf_end(c->hi) - addr; return 1; }
    int ok = 0;
    pthread_mutex_lock(&g_mu);
    int i = pool_find(addr, len);
    if (i >= 0) { pool_res(i); pc_put(i, addr); *buf = (__bridge void *)g_pools[i].buf; *off = addr - g_pools[i].base; *gpu = g_pools[i].gpu + *off; *avail = pool_buf_end(g_pools[i].hi) - addr; ok = 1; }
    pthread_mutex_unlock(&g_mu);
    if (!ok && nvn_sparse_shadow(addr, len, want > len ? want : len)) {   // as nvn_be_addr
        pthread_mutex_lock(&g_mu); i = pool_find(addr, len);
        if (i >= 0) { pool_res(i); pc_put(i, addr); *buf = (__bridge void *)g_pools[i].buf; *off = addr - g_pools[i].base; *gpu = g_pools[i].gpu + *off; *avail = pool_buf_end(g_pools[i].hi) - addr; ok = 1; }
        pthread_mutex_unlock(&g_mu); }
    return ok;
}
static inline int gpu_addr_avail(uint64_t addr, uint64_t len, void **buf, uint64_t *off, uint64_t *gpu, uint64_t *avail) { return gpu_addr_want(addr, len, len, buf, off, gpu, avail); }
int mtl_gpu_addr(uint64_t addr, uint64_t len, void **buf, uint64_t *off, uint64_t *gpu) { uint64_t avail; return gpu_addr_avail(addr, len, buf, off, gpu, &avail); }

// ---------- Submission ----------
static void defer_reset(void); static void defer_fallback(void);
typedef struct { int kind; volatile uint32_t *val; uint32_t mode, v; uint64_t addr; uint32_t type; void *vis; uint32_t seg; } post_op;   // vis: the visibility slot table for kind 3; seg: the segment it was encoded in (sub_cut)
static uint32_t g_seg;   // Index of the segment being encoded in this submission (0 until the first sub_cut)
typedef struct seg_clk seg_clk; static seg_clk *g_sclk; static void seg_clk_put(seg_clk *c);   // Counter timestamps by segment (see gpu_ticks)
// ---------- Conditional rendering (profile render_cond) ----------
// SetRenderEnableConditional(mode, rec) enables rendering if the 64-bit counter of the report at rec equals (RENDER_IF_EQUAL) or differs from (RENDER_IF_NOT_EQUAL) the one at
// rec + 16, until the next SetRenderEnable(true). Tears of the Kingdom wraps nearly every ClearColor / ClearDepthStencil this way: rec is set to 1 from the CPU when the target
// needs a clear, each clear is followed by ReportCounter(TIMESTAMP_TOP, rec), and rec + 16 is never written. A timestamp report puts 0 in the counter field (the time goes in the
// second field), so after one clear the two compare equal and later conditional clears of that target are skipped. The host used to ignore the condition and write the time
// into both fields, so every clear ran: the first tile-lighting round, the half-resolution scene depth its light volumes test against and the light accumulation were cleared
// before the composite read them, and the 3D scene came out black.
// Metal has no predication, so the condition is evaluated here at replay, on the CPU, from the records in memory. A report replayed earlier in this submission is not written yet
// (that happens when the GPU completes): a timestamp one counts with its known counter 0; a samples-passed result (an occlusion query, written from the visibility buffers) is
// unknown, and a condition on it keeps drawing, as before (occlusion culling only saves work). Inside a block evaluated false, draws and clears are dropped
static int g_rc_skip;   // a render-enable block evaluated false is active
// Neither table may drop an entry: a timestamp report forgotten leaves the condition reading the 1 the CPU wrote, so the clear runs again. They held 256 reports a submission of
// both kinds; Ocarina of Time (Switch 2) reports about 600 occlusion queries in a frame it walks in (320 standing), the table filled, the timestamp reports after them were
// forgotten, the conditional depth clears ran 3 more times before the lit materials' EQUAL depth test, and the frame came out white (half the frames while walking).
// Now only timestamps are kept per submission, the query addresses apart, and both tables grow (upstream reference implementation (MIT), the same fix for Splatoon Raiders)
static uint64_t *g_rc_pend; static uint32_t g_rc_npend, g_rc_pcap;   // timestamp reports replayed in this submission: their counter is 0, though memory does not show it yet
// Submitted timestamp reports are still pending until their completion handler
// writes memory and publishes g_done. A later submission must see their known 0,
// not the old CPU counter. Only the submit thread owns this table.
typedef struct { uint64_t addr, fence; } rc_submitted;
static rc_submitted *g_rc_submitted; static uint32_t g_rc_nsubmitted, g_rc_scap;
static uint64_t rc_done(void) { pthread_mutex_lock(&g_mu); uint64_t done = g_done; pthread_mutex_unlock(&g_mu); return done; }
static void rc_retire(void) {
    if (!g_rc_nsubmitted) return;
    uint64_t done = rc_done(); uint32_t n = 0;
    for (uint32_t i = 0; i < g_rc_nsubmitted; i++) if (g_rc_submitted[i].fence > done) g_rc_submitted[n++] = g_rc_submitted[i];
    g_rc_nsubmitted = n;
}
static void rc_commit(uint64_t fence) {
    rc_retire();
    uint32_t need = g_rc_nsubmitted + g_rc_npend;
    if (need > g_rc_scap) { uint32_t cap = g_rc_scap ? g_rc_scap : 256; while (cap < need) cap *= 2;
        rc_submitted *p = realloc(g_rc_submitted, (size_t)cap * sizeof *p); if (!p) MDIE("no memory for submitted timestamp reports"); g_rc_submitted = p; g_rc_scap = cap; }
    for (uint32_t i = 0; i < g_rc_npend; i++) g_rc_submitted[g_rc_nsubmitted++] = (rc_submitted){g_rc_pend[i], fence};
}
static uint64_t *g_rc_occ; static uint32_t g_rc_ocap, g_rc_on;   // addresses ever written by a non-timestamp report (open addressing, a power of two): conditions on them keep drawing
static int rc_occ_has(uint64_t a) { if (!g_rc_ocap) return 0; for (uint32_t i = (uint32_t)(a >> 4) & (g_rc_ocap - 1);; i = (i + 1) & (g_rc_ocap - 1)) { if (g_rc_occ[i] == a) return 1; if (!g_rc_occ[i]) return 0; } }
static void rc_occ_add(uint64_t a) {
    if (rc_occ_has(a)) return;
    if ((g_rc_on + 1) * 2 > g_rc_ocap) { uint32_t oc = g_rc_ocap, nc = oc ? oc * 2 : 4096; uint64_t *old = g_rc_occ, *t = calloc(nc, 8); if (!t) MDIE("no memory for the query report table");
        for (uint32_t k = 0; k < oc; k++) if (old[k]) { uint32_t i = (uint32_t)(old[k] >> 4) & (nc - 1); while (t[i]) i = (i + 1) & (nc - 1); t[i] = old[k]; }
        g_rc_occ = t; g_rc_ocap = nc; free(old); }
    uint32_t i = (uint32_t)(a >> 4) & (g_rc_ocap - 1); while (g_rc_occ[i]) i = (i + 1) & (g_rc_ocap - 1);
    g_rc_occ[i] = a; g_rc_on++;
}
static void rc_note(uint64_t a, int kind) {
    if (kind == 2) { rc_occ_add(a); return; }   // rc_value asks this table first
    for (uint32_t i = 0; i < g_rc_npend; i++) if (g_rc_pend[i] == a) return;
    if (g_rc_npend == g_rc_pcap) { uint32_t nc = g_rc_pcap ? g_rc_pcap * 2 : 256; uint64_t *t = realloc(g_rc_pend, (size_t)nc * 8); if (!t) MDIE("no memory for the timestamp report table"); g_rc_pend = t; g_rc_pcap = nc; }
    g_rc_pend[g_rc_npend++] = a;
}
static int rc_value(uint64_t a, uint64_t *v) {   // 0 = unknown at encode time
    if (rc_occ_has(a)) return 0;
    for (uint32_t i = g_rc_npend; i-- > 0;) if (g_rc_pend[i] == a) { *v = 0; return 1; }
    for (uint32_t i = g_rc_nsubmitted; i-- > 0;) if (g_rc_submitted[i].addr == a) {
        if (g_rc_submitted[i].fence > rc_done()) { *v = 0; return 1; }
        break;   // completed: subsequent CPU writes are authoritative again
    }
    *v = *(const volatile uint64_t *)a; return 1;
}
// ---------- Occlusion queries (NVN_COUNTER_TYPE_SAMPLES_PASSED) ----------
// NVN semantics: samples passed is a cumulative counter on the queue - ResetCounter zeroes it, every draw afterwards adds to it, and ReportCounter writes out the cumulative value at that moment (+ timestamp) when the GPU completes.
// Metal: every render pass attaches a visibility result buffer; draws during counting use counting mode, with a new slot per pass (no reliance on accumulation across passes); a reset empties the 'slot table since the reset',
// and a report hands the slot table together with its buffer (retained) to the completion callback to sum and write back; after a report a new slot is used, so later draws are not counted into the reported value.
// (Previously always wrote 0: occlusion query = 'fully occluded', campfires / light sources got culled - the character select screen calls ResetCounter 21 times per frame)
// fence: the fence of the submission the slot's pass was encoded in (g_fence + 1 then; segment cuts do not advance it), so the slot's value is final once g_done reaches it.
// Slots whose submission has completed are folded into g_vis_base (vis_fold) instead of staying in the table until the next reset: a game that keeps reporting without
// resetting (11-05 Tears of the Kingdom, about 33k frames) grew the table to 8 MiB and every report copied it whole until std::bad_alloc; and the ring buffer a slot points into
// is reused by a later submission once its fence completes, so an unfolded old slot was read after being overwritten.
typedef struct { void *buf; uint32_t slot; uint64_t fence; } vis_slot;
typedef struct { int n; uint64_t base; vis_slot s[]; } vis_list;
#define VIS_SLOTS 8192
typedef struct { __strong id<MTLBuffer> buf; uint64_t fence; } vis_buf;
// One visibility buffer per submission in flight, as many as command allocators: with 4, Age of Calamity (about twelve submissions a frame) waited in nvn_be_sub_begin for the previous frame's GPU work; its first battle went from 18.0 to 16.9 ms a frame on the Mac
enum { VIS_RING = ALLOC_MAX };
static vis_buf g_vis_ring[VIS_RING]; static int g_vis_ring_n, g_vis_ring_i = -1;
static id<MTLBuffer> g_vis; static uint32_t g_vis_n;   // This submission's visibility buffer and number of slots used
static int vis_in_ring(id<MTLBuffer> b) { for (int i = 0; i < g_vis_ring_n; i++) if (g_vis_ring[i].buf == b) return 1; return 0; }
static int g_vis_on, g_vis_counting, g_vis_cur = -1; static uint64_t g_vis_cur_pass;
static vis_slot *g_vs; static int g_nvs, g_vscap;      // Slots since the last reset whose submission has not completed yet
static uint64_t g_vis_base;                            // Samples of the slots since the last reset already folded (their submission completed)
static uint64_t g_cnt_report[32], g_cnt_reset[32];       // Report / reset counts per counter type (diagnostics)
static void vis_clear(void) { for (int i = 0; i < g_nvs; i++) CFRelease(g_vs[i].buf); g_nvs = 0; g_vis_base = 0; g_vis_cur = -1; }
// Fold the slots whose submission has completed into g_vis_base (encode thread; g_done read without the lock as elsewhere: a stale value only folds less).
// Called before a report snapshots the table and before a ring visibility buffer is reused (sub begin), so a slot is never read after its buffer was handed to a new submission.
static void vis_fold(void) {
    uint64_t done = g_done; int j = 0;
    for (int i = 0; i < g_nvs; i++) {
        if (g_vs[i].fence <= done) { g_vis_base += ((const uint64_t *)((__bridge id<MTLBuffer>)g_vs[i].buf).contents)[g_vs[i].slot]; CFRelease(g_vs[i].buf); }
        else g_vs[j++] = g_vs[i];
    }
    g_nvs = j;
}
static vis_list *vis_snapshot(void) {
    vis_fold();
    vis_list *l = malloc(sizeof *l + g_nvs * sizeof(vis_slot)); l->n = g_nvs; l->base = g_vis_base;
    for (int i = 0; i < g_nvs; i++) { l->s[i] = g_vs[i]; CFRetain(g_vs[i].buf); }
    return l;
}
// Target ranges of buffer writes (copies / inline uniform updates) already encoded in this submission but not yet executed on the GPU: reading these addresses on the CPU side at encode time yields old values (uv_proof avoids them when reading uniforms)
// Inline updates keep where their data sits in the update ring (g_pend_upd: index + 1 into g_upd), so a bindless handle they wrote can be read as the GPU will see it (pend_read).
// The writes are indexed by 4 KB page (a chain per hash bucket, newest first); a write over more than PEND_SPAN pages goes to a short list that every lookup scans.
// The list grows as a submission needs it and keeps its size for the next (pend_room). It used to stop at a fixed count (256, then 8,192), and past it the submission counted as a
// write anywhere (g_pend_over): every partly covered uniform shadow was refused, so every draw that read one ended its render pass. One Switch 2 title's boss stage queues about
// 11,000 writes in a submission (7 inline uniform updates before each of about 1,550 occlusion queries on a 6400x6400 map) and stayed at 1-2 fps past the old limit.
// A write anywhere is left for a list that cannot grow (no memory) and a full wide list. Ported from nxnative 6d5ed7184 (MIT)
enum { PEND_HB_BITS = 13, PEND_HB = 1 << PEND_HB_BITS, PEND_SPAN = 8, PEND_WIDE = 256 };
static uint64_t *g_pend_lo, *g_pend_hi; static int g_npend, g_pend_over, g_pend_cap; static uint8_t *g_pend_kind; static uint32_t *g_pend_upd;   // kind: 1 inline update, 2 copy, 3 fill
static int32_t g_pend_head[PEND_HB]; static uint32_t g_pend_hgen[PEND_HB], g_pend_gen = 1;   // a bucket's chain is valid when its generation is this submission's
typedef struct { int32_t e, next; } pend_node;
static pend_node *g_pend_node; static int g_npnode, g_pnode_cap;
static int32_t g_pend_wide[PEND_WIDE]; static int g_nwide;
// The newest write per byte, by 4 KB page (pend_last): each page this submission wrote holds sorted, disjoint segments {lo, hi, e} of its bytes, e the newest write over them
//   (writes are numbered in order, so a new write simply takes over its range). A lookup is a binary search plus the segments that actually overlap, instead of walking every
//   write the page's hash chain holds: Monster Hunter Rise rewrites inline uniform ranges many times a submission on few pages, and the chain walk for a bound range those
//   writes do not touch went through all of them (11-02 device Time Profiler: pend_last 24 % of the submit thread). Pool or table full → this submission looks up by the chains
enum { PSEG_PAGES = 4096, PSEG_POOL = 65536 };
typedef struct { uint16_t lo, hi; int32_t e; } pseg;   // hi ≤ 4096 (page bytes)
static struct { uint64_t page; uint32_t gen; int32_t off, n, cap; } g_psp[PSEG_PAGES];
static pseg g_pseg[PSEG_POOL]; static int g_npseg, g_pseg_over;
enum { PZERO_MAX = 64 };   // zero-length writes take no segment but still overlap a lookup strictly around their address (a < dst < a + n): kept apart, checked one by one
static int32_t g_pzero[PZERO_MAX]; static int g_npzero;
static int pseg_page(uint64_t page, int make) {   // slot of the page's segment list in this submission; −1 when absent (or no room)
    unsigned h = (unsigned)((page * 0x9E3779B97F4A7C15ull) >> 52) & (PSEG_PAGES - 1);
    for (int i = 0; i < 64; i++, h = (h + 1) & (PSEG_PAGES - 1)) {
        if (g_psp[h].gen != g_pend_gen) { if (!make) return -1; g_psp[h].gen = g_pend_gen; g_psp[h].page = page; g_psp[h].off = g_psp[h].n = g_psp[h].cap = 0; return (int)h; }
        if (g_psp[h].page == page) return (int)h;
    }
    return -1;
}
static int pseg_first(const pseg *v, int n, unsigned lo) { int a = 0, b = n; while (a < b) { int m = (a + b) / 2; if (v[m].hi <= lo) a = m + 1; else b = m; } return a; }   // first with hi > lo
static void pseg_put(uint64_t page, unsigned lo, unsigned hi, int e) {
    int h = pseg_page(page, 1); if (h < 0) { g_pseg_over = 1; return; }
    int n = g_psp[h].n;
    if (n + 2 > g_psp[h].cap) {   // room for the at most two more segments a write adds: move the list to the pool's end with twice the room
        int cap = g_psp[h].cap ? 2 * g_psp[h].cap : 4; if (cap < n + 2) cap = n + 2;
        if (g_npseg + cap > PSEG_POOL) { g_pseg_over = 1; return; }
        memcpy(&g_pseg[g_npseg], &g_pseg[g_psp[h].off], sizeof(pseg) * (size_t)n); g_psp[h].off = g_npseg; g_psp[h].cap = cap; g_npseg += cap;
    }
    pseg *v = &g_pseg[g_psp[h].off]; int i = pseg_first(v, n, lo), j = i; while (j < n && v[j].lo < hi) j++;
    pseg rep[3]; int k = 0;
    if (i < j && v[i].lo < lo) rep[k++] = (pseg){v[i].lo, (uint16_t)lo, v[i].e};
    rep[k++] = (pseg){(uint16_t)lo, (uint16_t)hi, e};
    if (i < j && v[j - 1].hi > hi) rep[k++] = (pseg){(uint16_t)hi, v[j - 1].hi, v[j - 1].e};
    memmove(&v[i + k], &v[j], sizeof(pseg) * (size_t)(n - j)); memcpy(&v[i], rep, sizeof(pseg) * (size_t)k); g_psp[h].n = n - (j - i) + k;
}
typedef struct { uint64_t lo; size_t off; __unsafe_unretained id<MTLBuffer> buf; } upd_ent;   // the ring block lives until this submission completes (mtl_sub_update)
static upd_ent *g_upd; static int g_nupd;   // one per entry at most: sized with the entries
static int *g_ubp_idx;   // every entry a lookup can meet (pend_since): at most one per node of the range's chains, plus the wide list
static int pend_grow(void **p, size_t n, size_t each) { void *q = realloc(*p, n * each); if (!q) return 0; *p = q; return 1; }
// Room for one more entry and nodes more nodes: 0 when memory runs out (the caller counts the write as one anywhere)
static int pend_room(int nodes) {
    if (g_npend == g_pend_cap) { if (g_pend_cap > INT_MAX / 2) return 0; int c = g_pend_cap ? g_pend_cap * 2 : 4096;
        if (!pend_grow((void **)&g_pend_lo, c, sizeof *g_pend_lo) || !pend_grow((void **)&g_pend_hi, c, sizeof *g_pend_hi) || !pend_grow((void **)&g_pend_kind, c, sizeof *g_pend_kind)
            || !pend_grow((void **)&g_pend_upd, c, sizeof *g_pend_upd) || !pend_grow((void **)&g_upd, c, sizeof *g_upd)) return 0;   // a grown array kept at its new size is only spare room
        g_pend_cap = c; }
    if (!g_pnode_cap || g_npnode + nodes > g_pnode_cap) { int c = g_pnode_cap ? g_pnode_cap : 8192; while (c < g_npnode + nodes) { if (c > INT_MAX / 2) return 0; c *= 2; }
        if (!pend_grow((void **)&g_pend_node, c, sizeof *g_pend_node) || !pend_grow((void **)&g_ubp_idx, (size_t)c + PEND_WIDE, sizeof *g_ubp_idx)) return 0;
        g_pnode_cap = c; }
    return 1;
}
// Other writes to guest memory in this submission, which the pend list does not hold: writable storage buffers bound to a shader, texture→buffer copies, counter reports (ubp_get).
// Kept by 4 KB page (Breath of the Wild's particle dispatches bind about ten storage buffers each, hundreds a frame): a set of pages tagged with the submission (g_pend_gen) and with what
// wrote them. A counter report does not count against this submission's shadows: the host writes reports on the CPU when the whole submission has completed, so no draw of it reads one
// (Fire Emblem Engage writes its query reports into the page of a uniform block); it counts for later submissions while this one runs (gw_commit)
enum { SBW_N = 16384, SBW_PAGES = 4096 };
static struct { uint64_t page; uint32_t gen; uint8_t src; } g_sbwp[SBW_N]; static int g_nsbw, g_sbw_over;   // src: SBW_* bits; pages in the set this submission; over: a write could not be kept (too large, set full, size not known)
static int sbw_slot(uint64_t pg, int add) {   // open addressing; −1 = not there (or no room to add)
    unsigned h = (unsigned)((pg * 0x9E3779B97F4A7C15ull) >> 50) & (SBW_N - 1);
    for (int i = 0; i < 64; i++, h = (h + 1) & (SBW_N - 1)) {
        if (g_sbwp[h].gen != g_pend_gen) { if (!add) return -1; g_sbwp[h].page = pg; g_sbwp[h].gen = g_pend_gen; g_sbwp[h].src = 0; g_nsbw++; return (int)h; }
        if (g_sbwp[h].page == pg) return (int)h; }
    return -1;
}
enum { SBW_GPU = 1, SBW_REPORT = 2 };
static uint32_t g_sbw_gen;   // bumped by every write noted that this submission's shadows must respect (a cached shadow made before it is checked again)
static uint64_t g_sbw_pages;   // pages walked by sbw_note (submit cost line, hle_nvn.c)
// Ranges already noted whole in this submission (same start, size and source): noting one again changes no page and no shadow verdict, so it returns at once
//   and does not bump g_sbw_gen (10-31 Monster Hunter Rise: the same multi-MB writable storage buffer bound draw after draw walked ~280k pages a frame on the submit thread)
enum { SBW_MEMO = 64 };
static struct { uint64_t lo, n; uint32_t gen; uint8_t src; } g_sbw_memo[SBW_MEMO];
// A writable storage buffer whose size the game never gave (a binding of size 0, or an address kept in a uniform buffer): its bounds table says no clamp (len_fill), so the shader
//   can write from its address to the end of the Metal buffer that holds it, and no further. That is the range to note: it used to be noted as size 0, which sbw_note takes as
//   "too large to keep" and marks the whole submission over (g_sbw_over), so every later indexed geometry draw waited for the GPU and left its geometry run
//   (11-06 Donkey Kong: compute shaders 80c1f2f388617e69 / 1cc137863bec3f11 / c3de3d90f81ac8e0 bind such buffers with 59–320 KB left in theirs)
static uint64_t sbw_to_end(void *mb, uint64_t mo) { uint64_t len = mb ? (uint64_t)[(__bridge id<MTLBuffer>)mb length] : 0; return len > mo ? len - mo : 0; }
static void sbw_note(uint64_t lo, uint64_t n, int src) {
    unsigned m = (unsigned)(((lo ^ (n << 20)) * 0x9E3779B97F4A7C15ull) >> 58) & (SBW_MEMO - 1);
    if (n && g_sbw_memo[m].gen == g_pend_gen && g_sbw_memo[m].lo == lo && g_sbw_memo[m].n == n && (g_sbw_memo[m].src & src) == src) return;
    if (src == SBW_GPU) g_sbw_gen++;
    if (!n || n > (uint64_t)SBW_PAGES << 12) { if (src == SBW_GPU) g_sbw_over = 1; return; }   // a report too large to keep cannot happen (16 bytes)
    g_sbw_pages += ((lo + n - 1) >> 12) - (lo >> 12) + 1;
    for (uint64_t pg = lo >> 12; pg <= (lo + n - 1) >> 12; pg++) { int k = sbw_slot(pg, 1); if (k < 0) { g_sbw_over = 1; return; } g_sbwp[k].src |= (uint8_t)src; }
    uint8_t had = g_sbw_memo[m].gen == g_pend_gen && g_sbw_memo[m].lo == lo && g_sbw_memo[m].n == n ? g_sbw_memo[m].src : 0;
    g_sbw_memo[m].lo = lo; g_sbw_memo[m].n = n; g_sbw_memo[m].gen = g_pend_gen; g_sbw_memo[m].src = (uint8_t)(had | src);   // only after every page went in
}
static int sbw_hits(uint64_t lo, uint64_t hi) { if (!g_nsbw) return 0; for (uint64_t pg = lo >> 12; pg <= (hi - 1) >> 12; pg++) { int k = sbw_slot(pg, 0); if (k >= 0 && (g_sbwp[k].src & SBW_GPU)) return 1; } return 0; }
static inline unsigned pend_bucket(uint64_t page) { return (unsigned)((page * 0x9E3779B97F4A7C15ull) >> (64 - PEND_HB_BITS)); }
static void pend_reset(void) { g_npend = g_pend_over = g_nupd = g_npnode = g_nwide = g_nsbw = g_sbw_over = g_npseg = g_pseg_over = g_npzero = 0; if (!++g_pend_gen) { memset(g_pend_hgen, 0, sizeof g_pend_hgen); memset(g_psp, 0, sizeof g_psp); memset(g_sbwp, 0, sizeof g_sbwp); memset(g_sbw_memo, 0, sizeof g_sbw_memo); g_pend_gen = 1; } }
static void vc_gpu_write(uint64_t dst, uint64_t n);   // kept index ranges under the written range are not trusted again (ix_range)
static void gpw_clear(uint64_t lo, uint64_t n);   // guest bytes the GPU wrote into memory itself are current again (see gpw_mark)
static int pend_add(uint64_t dst, uint64_t n, int kind) {
    vc_gpu_write(dst, n); gpw_clear(dst, n);
    if (g_pend_over) return -1;
    uint64_t p0 = dst >> 12, p1 = (dst + (n ? n : 1) - 1) >> 12; int narrow = p1 - p0 < PEND_SPAN;
    if (!pend_room(narrow ? (int)(p1 - p0 + 1) : 0)) { g_pend_over = 1; return -1; }
    int e = g_npend;
    if (narrow) {
        for (uint64_t pg = p0; pg <= p1; pg++) { unsigned b = pend_bucket(pg); int k = g_npnode++;
            g_pend_node[k].e = e; g_pend_node[k].next = g_pend_hgen[b] == g_pend_gen ? g_pend_head[b] : -1; g_pend_head[b] = k; g_pend_hgen[b] = g_pend_gen; }
        uint64_t end = dst + n;
        if (!n) { if (g_npzero < PZERO_MAX) g_pzero[g_npzero++] = e; else g_pseg_over = 1; }
        for (uint64_t pg = p0; pg <= p1 && n && !g_pseg_over; pg++) { uint64_t a0 = pg << 12; pseg_put(pg, (unsigned)((dst > a0 ? dst : a0) - a0), (unsigned)((end < a0 + 4096 ? end : a0 + 4096) - a0), e); } }
    else if (g_nwide < PEND_WIDE) g_pend_wide[g_nwide++] = e;
    else { g_pend_over = 1; return -1; }
    g_pend_lo[e] = dst; g_pend_hi[e] = dst + n; g_pend_kind[e] = (uint8_t)kind; g_pend_upd[e] = 0; return g_npend++;
}
// The newest queued write overlapping [a, a+n): its index, -1 for none, -2 when it cannot be told (overflow)
static int pend_last(uint64_t a, uint64_t n) {
    if (g_pend_over) return -2;
    int best = -1; uint64_t p0 = a >> 12, p1 = (a + (n ? n : 1) - 1) >> 12;
    for (int i = 0; i < g_nwide; i++) { int e = g_pend_wide[i]; if (e > best && a < g_pend_hi[e] && a + n > g_pend_lo[e]) best = e; }
    if (p1 - p0 >= PEND_SPAN) { for (int e = g_npend - 1; e > best; e--) if (a < g_pend_hi[e] && a + n > g_pend_lo[e]) return e; return best; }
    if (!g_pseg_over && n) {   // by the per-page segments (see pseg_put); a zero-length lookup keeps the chain walk's exact test
        uint64_t end = a + n;
        for (int i = 0; i < g_npzero; i++) { int e = g_pzero[i]; if (e > best && a < g_pend_lo[e] && end > g_pend_lo[e]) best = e; }
        for (uint64_t pg = p0; pg <= p1; pg++) { int h = pseg_page(pg, 0); if (h < 0) continue;
            uint64_t a0 = pg << 12; unsigned lo = (unsigned)((a > a0 ? a : a0) - a0), hi = (unsigned)((end < a0 + 4096 ? end : a0 + 4096) - a0);
            const pseg *v = &g_pseg[g_psp[h].off]; int cnt = g_psp[h].n;
            for (int i = pseg_first(v, cnt, lo); i < cnt && v[i].lo < hi; i++) if (v[i].e > best) best = v[i].e; }
        return best;
    }
    for (uint64_t pg = p0; pg <= p1; pg++) { unsigned b = pend_bucket(pg); if (g_pend_hgen[b] != g_pend_gen) continue;
        for (int k = g_pend_head[b]; k >= 0 && g_pend_node[k].e > best; k = g_pend_node[k].next) { int e = g_pend_node[k].e; if (a < g_pend_hi[e] && a + n > g_pend_lo[e]) { best = e; break; } } }
    return best;
}
static int pend_hits(uint64_t a, uint64_t n) { return pend_last(a, n) != -1; }
// The n bytes at a as the last write queued in this submission leaves them, when that write is an inline update covering them all → 1; otherwise → 0 and *kind = what wrote them (0 = too many writes to tell)
static int pend_read(uint64_t a, uint64_t n, void *out, int *kind) {
    int e = pend_last(a, n); *kind = e >= 0 ? g_pend_kind[e] : 0;
    if (e < 0 || !g_pend_upd[e] || a < g_pend_lo[e] || a + n > g_pend_hi[e]) return 0;
    const upd_ent *u = &g_upd[g_pend_upd[e] - 1]; memcpy(out, (const uint8_t *)u->buf.contents + u->off + (a - u->lo), n); return 1;
}
typedef struct { uint64_t ser; uint16_t level, slice; } zskip_zero;
static zskip_zero g_zskip_zero[4096]; static int g_zskip_n, g_zskip_count;
static zskip_zero g_zskip_cand[8]; static uint8_t g_zskip_cand_ok[8];
static void zskip_clear(void);
static int tbdr_on(void);
static id g_cb;
static void main_barrier_reset(void);
static id<MTL4ComputeCommandEncoder> g_blit;
static NSMutableArray<dispatch_block_t> *g_commit_blocks;
// The uniform shadows taken once a shader with stores through loaded pointers has run (g_gml_on), each with the fence of the submission that took it: every shadow made or checked
// again after a GPU write was noted (ubp_get). A write log that shows a pool the prediction left out checks the shadows of its own submission and of the later ones encoded before
// it completed, the ones that relied on its writes (gml_read): the miss matters only if one of them covers a page the stores wrote (upstream reference implementation (MIT))
// A geometry run that took in draws whose pool-table writes were predicted (geo_runset_gsr, nvn_geometry.inc) adds the ranges its draws read and wrote, as it reordered them on that prediction
enum { GSR_N = 16384 };
static struct { uint64_t fence, lo, hi; } g_gsr[GSR_N]; static uint64_t g_gsr_n; static int g_gml_on;
static pthread_mutex_t g_gsr_mu = PTHREAD_MUTEX_INITIALIZER;
static uint64_t g_alloc_fence[ALLOC_MAX]; static uint64_t g_alloc_waits, g_alloc_grown;
int nvn_be_wait(uint64_t fence, uint64_t timeout_ns);
static void up_flush(void);
// The upload batch belongs only to the submit thread (the thread that called nvn_be_sub_begin): the batch's encoder cannot be used across threads. Every entry point asserts current thread == submit thread,
// and on mismatch prints the stack and aborts on the spot - so that 'another thread touched the batch' is exposed deterministically on Mac too, not by timing (real iOS device stuck at the main menu: the present thread flushed the submit thread's batch via q_cb).
static pthread_t g_sub_thread; static _Atomic int g_sub_thread_set;
static int on_sub_thread(void) { return atomic_load(&g_sub_thread_set) && pthread_equal(pthread_self(), g_sub_thread); }
static void up_owner_check(const char *where) {
    if (!atomic_load(&g_sub_thread_set) || on_sub_thread()) return;
    char name[64] = ""; pthread_getname_np(pthread_self(), name, sizeof name);
    MLOG("【红】 upload batches belong to the submit thread only: %s called on thread '%s'", where, name);
    void *bt[32]; int n = backtrace(bt, 32); backtrace_symbols_fd(bt, n, 2);
    abort();
}
// Every command buffer created outside the replay / upload batch goes through this. On the submit thread: flush this batch's uploads first, so that commands that then read or write these textures are ordered after the uploads;
// other threads (the present thread etc.) creating a command buffer do not touch the batch: they do not read or write textures uploaded in this batch; commands that need these textures all come after this replay submission (the batch is flushed before it)
// Old-queue command buffers (readback / diagnostics / present; to be deleted once M4-4 and M4-5 are migrated away): uploads are already on the Metal 4 queue, and there is no ordering guarantee between the two queues -
// wait for the upload to complete after flushing it, and only then can the old queue read the upload result (nvn_be_read_texels waited first and flushed afterwards, the readback beat the upload, 4 failures on t_nvn upload content)
static void up_wait_zero(_Atomic int *v);
static id<MTLCommandBuffer> q_cb(void) { if (on_sub_thread()) { up_flush(); rec_drain(); up_wait_zero(&g_up_pending); } return [g_q commandBuffer]; }
static post_op *g_post; static int g_npost, g_postcap;
// One autorelease pool per submission: submissions run on a guest thread (long-lived, no run loop, never drains the implicit pool), so objects autoreleased in the Metal replay
// (command buffers, encoders, pass descriptors, etc.) are never released unless put in a pool. Measured on the character select screen of a real iOS device: the host heap grows by about 47 objects per frame, 0.22 MiB/s.
void *objc_autoreleasePoolPush(void); void objc_autoreleasePoolPop(void *);
static void *g_sub_pool;
static int tbdr_on(void);

static void wd_sub_begin(void), wd_sub_end(void), wd_release(uint64_t ser), wd_widen_rts(void), wd_widen_resolve_dst(const tex_t *src, const tex_t *dst);   // S2Arm widen glue (graphics/nvn/widen_glue.inc)
static void rs_rts(void), rs_flush(void);   // S2Arm internal resolution (nvn_rscale_ops.inc)
static _Atomic int g_fit_pillar;   // S2Arm full-screen check, the generic present layer's pillar kinds (nxgal_present_pillar): 1 = the widen core said the frame last handed to present is a 16:9 page kept centred with black bars, 2 = the widen core said its sides were drawn by widened content (black is the game's), 4 =the game draws wide itself (UI mode) and that frame was all 2D (wd_present); read by fit_* on the present thread
void mtl_fit_pillar(int kind) { atomic_store(&g_fit_pillar, kind); }   // nvn_mtl.h：GL 前端（gl_widen.inc gl_wd_present）上屏前设，同 widen_glue.inc wd_present
// S2Arm widen edge push: every vertex function of the B library reads float4 s2a_push at PUSH_SLOT (dm/gfx/tools/dmsh_build.py vs_push); each draw starts with it zero (unpushed)
// and the widen glue's wd_draw sets it for the draws the widen core pushes; bind_vbufs binds it
enum { PUSH_SLOT = 13 };   // = dmsh_build.py PUSH_SLOT; the geometry capture pass (nvn_geometry.inc) binds its own info at 13 after bind_vbufs
static float g_wd_push[4];
static int g_wd_inst, g_wd_vc;   // S2Arm widen: the current draw's instance / vertex (index) count for wd_draw (draw sets them; 0 = unknown, an indirect draw)
