}
static inline void enc_full_barrier_end(id e) {
    [(id<MTL4CommandEncoder>)e barrierAfterStages:MTLStageAll beforeQueueStages:MTLStageAll visibilityOptions:MTL4VisibilityOptionDevice];
}
// A full producer covers later encoders in its queue. Only reuse that proof for
