    if (k < 0 || k >= g_gp_n || g_m3) return;
    char kind = g_gp_lab[k].kind; uint32_t n0 = g_gp_lab[k].draws; int cur = g_gp_cur;
    __unsafe_unretained id enc = g_gp_enc;
    g_gp_lab[k].kind = kind == 'P' ? 'R' : 'C'; g_gp_cur = k; g_gp_enc = e; gp_end(e); g_gp_cur = cur; g_gp_enc = enc;   // gp_end writes the end timestamp by kind
    g_gp_lab[k].kind = kind; g_gp_lab[k].draws = n1 - n0;
}
static void gp_report(int n, int dropped, gp_lab *lab, uint64_t frame) {   // the frame's last command buffer has completed
    // Both resolve to 2n 64-bit timestamps in order (MTLCounterResultTimestamp holds the one field); Metal 3's sample buffer reports nanoseconds, Metal 4's heap ticks
    NSData *r = g_m3 ? [g_gp_sb resolveCounterRange:NSMakeRange(0, 2 * n)] : [g_gp_heap resolveCounterRange:NSMakeRange(0, 2 * n)];
    const uint64_t *t = r.bytes; if (!t) { free(lab); atomic_store(&g_gp_rearm_frame, atomic_load(&g_cur_frame)); atomic_store(&g_gp_state, 0); return; }
    double tick_ns = g_m3 ? 1.0 : 1e9 / (double)[g_dev queryTimestampFrequency], tot[2] = {0}, span = 0, gm_us = 0; int gm_n = 0; uint64_t t0 = 0, t1 = 0;
    for (int i = 0; i < n; i++) { uint64_t a = t[2 * i], b = t[2 * i + 1]; if (!a || !b || b < a) continue;
        double us = (b - a) * tick_ns / 1e3; const gp_lab *l = &lab[i]; tot[l->kind != 'R' && l->kind != 'P'] += us; if (l->gm) { gm_us += us; gm_n++; }
        if (!t0 || a < t0) t0 = a; if (b > t1) t1 = b;
        if (l->kind == 'P' || l->kind == 'K') MLOG("[gpuprof] F%llu %4d %8.1f us geometry run %s, %u geometry draws, after pass %llu start %+.1f seg %u", (unsigned long long)frame, i, us,
            l->kind == 'P' ? "captures (render)" : "geometry kernels + compaction (compute)", l->draws, (unsigned long long)l->pass, (a - t[0]) * tick_ns / 1e3, l->seg);
        else if (l->kind == 'R') MLOG("[gpuprof] F%llu %4d %8.1f us render pass %llu %ux%u colors %u depth %u loads %u draws %u start %+.1f seg %u", (unsigned long long)frame, i, us, (unsigned long long)l->pass, l->w, l->h, l->nc, l->depth, l->loads, l->draws, (a - t[0]) * tick_ns / 1e3, l->seg);
        else MLOG("[gpuprof] F%llu %4d %8.1f us compute / copy after pass %llu start %+.1f seg %u copies %u (uniform updates %u) dispatches %u", (unsigned long long)frame, i, us, (unsigned long long)l->pass, (a - t[0]) * tick_ns / 1e3, l->seg, l->draws, l->h, l->w); }
    span = (t1 - t0) * tick_ns / 1e3;
    MLOG("[gpuprof] frame %llu: render %.2f ms, compute / copy %.2f ms over %d encoders, first start to last end %.2f ms; encoders with raw-memory-pool-table draws / dispatches %.2f ms (%d)%s", (unsigned long long)frame, tot[0] / 1e3, tot[1] / 1e3, n, span / 1e3, gm_us / 1e3, gm_n, dropped ? " (TRUNCATED: see the next line)" : "");
    // 11-05 金刚：一帧 4000 多个编码器，只记得下前 GP_MAX / 2 个，报告曾被当成整帧读。记满时明说截断：之后的编码器没记，以上合计 / 跨度只是前段
    if (dropped) MLOG("【黄】 [gpuprof] frame %llu TRUNCATED: %d more encoders after the first %d were not recorded (limit %d per frame = the largest timestamp heap); the totals and span above cover only the frame's start", (unsigned long long)frame, dropped, n, GP_MAX / 2);
    free(lab); atomic_store(&g_gp_rearm_frame, atomic_load(&g_cur_frame)); atomic_store(&g_gp_state, 0);
}
// Render pass descriptors: MTL4RenderPassDescriptor on Metal 4, MTLRenderPassDescriptor on Metal 3. The replay writes them through the Metal 4 type and uses only what both classes have
// with the same names and meanings (attachments, target size and layers, raster sample count, visibility buffer)
static inline id pass_desc(void) { return g_m3 ? [MTLRenderPassDescriptor new] : [MTL4RenderPassDescriptor new]; }
// Argument tables. Metal 4 sets them on the encoder. Metal 3 (the interface agreed in #279) only notes each stage's current table (0 vertex, 1 fragment, 2 compute), and every draw or
// dispatch hands those to m3_table_apply first (m3_bind_draw / m3_bind_dispatch)
static id g_m3_tab[5];   // 3 object, 4 mesh: noted by a task / mesh draw (mtk_encode), applied by m3_bind_mesh
static inline void enc_r_table(id e, id t, MTLRenderStages s) {
    if (!g_m3) { [(id<MTL4RenderCommandEncoder>)e setArgumentTable:t atStages:s]; return; }
    if (s & MTLRenderStageVertex) g_m3_tab[0] = t;
    if (s & MTLRenderStageFragment) g_m3_tab[1] = t;
    if (s & MTLRenderStageObject) g_m3_tab[3] = t;
    if (s & MTLRenderStageMesh) g_m3_tab[4] = t;
}
static inline void enc_c_table(id e, id t) { if (!g_m3) [(id<MTL4ComputeCommandEncoder>)e setArgumentTable:t]; else g_m3_tab[2] = t; }
static inline void m3_bind_draw(id e) { m3_table_apply(e, 0, g_m3_tab[0]); m3_table_apply(e, 1, g_m3_tab[1]); }
static inline void m3_bind_dispatch(id e) { m3_table_apply(e, 2, g_m3_tab[2]); }
static inline void m3_bind_mesh(id e) { m3_table_apply(e, 1, g_m3_tab[1]); m3_table_apply(e, 3, g_m3_tab[3]); m3_table_apply(e, 4, g_m3_tab[4]); }   // a task / mesh draw: fragment, object, mesh (no vertex stage)
static inline id<MTL4RenderCommandEncoder> enc_r_begin_pass(MTL4RenderPassDescriptor *d) {   // the draw passes (rp_begin_ex); see barrier_game
    if (!g_rlane) geo_run_flush();
    enc_close_blit();
    g_half_mask_sent = -1;
    gp_pre(d, 'R');   // Metal 3: the sample points go on the pass descriptor before the encoder is made (no-op elsewhere)
    id<MTL4RenderCommandEncoder> e = [g_cb renderCommandEncoderWithDescriptor:d];
    int relaxed = g_last_end_relaxed && !g_game_barrier;
    int full = !relaxed;
    if (g_m3) m3_wait(e, 1, relaxed);
    else full = main_barrier_begin(e, relaxed);
    if (full) g_bar_full++; else g_bar_skip++;
    g_game_barrier = 0;
    enc_r_table(e, g_vt, MTLRenderStageVertex); enc_r_table(e, g_ft, MTLRenderStageFragment); gp_begin(e, 'R', d); return e;
}
static inline void enc_r_end_pass(id e) {
    if (!barrier_game()) { m4_end(e); return; }
    if (g_m3) { m4_end(e); g_last_end_relaxed = 1; return; }   // the fence is updated after the fragment stage either way; the next pass waits before its fragments only (enc_r_begin_pass)
    gp_end(e); [(id<MTL4CommandEncoder>)e barrierAfterStages:MTLStageVertex | MTLStageFragment beforeQueueStages:MTLStageFragment | MTLStageDispatch | MTLStageBlit visibilityOptions:MTL4VisibilityOptionDevice];
    [e endEncoding]; main_barrier_reset(); g_last_end_relaxed = 1;
}
static inline id<MTL4RenderCommandEncoder> enc_r_begin(MTL4RenderPassDescriptor *d) {
    if (!g_rlane) geo_run_flush();
    enc_close_blit();
    g_half_mask_sent = -1;
    gp_pre(d, 'R');
    id<MTL4RenderCommandEncoder> e = [g_cb renderCommandEncoderWithDescriptor:d];
    if (g_m3) m3_wait(e, 1, 0); else main_barrier_begin(e, 0);
    enc_r_table(e, g_vt, MTLRenderStageVertex); enc_r_table(e, g_ft, MTLRenderStageFragment); gp_begin(e, 'R', d); return e;
}
static inline void enc_r_end(id e) { m4_end(e); }
static inline void enc_r_pso(id<MTL4RenderCommandEncoder> e, id<MTLRenderPipelineState> p) { [e setRenderPipelineState:p]; }
static inline void enc_r_dss(id<MTL4RenderCommandEncoder> e, id<MTLDepthStencilState> s) { [e setDepthStencilState:s]; }
static inline void enc_r_viewport(id<MTL4RenderCommandEncoder> e, MTLViewport v) { [e setViewport:v]; }
static inline void enc_r_scissor(id<MTL4RenderCommandEncoder> e, MTLScissorRect r) { [e setScissorRect:r]; }
static inline void enc_r_cull(id<MTL4RenderCommandEncoder> e, MTLCullMode m) { [e setCullMode:m]; }
static inline void enc_r_winding(id<MTL4RenderCommandEncoder> e, MTLWinding w) { [e setFrontFacingWinding:w]; }
static inline void enc_r_fill(id<MTL4RenderCommandEncoder> e, MTLTriangleFillMode m) { [e setTriangleFillMode:m]; }
