static inline id enc_b_begin(id cb) { return [cb respondsToSelector:@selector(beginCommandBufferWithAllocator:)] ? [cb computeCommandEncoder] : [cb blitCommandEncoder]; }
static inline void enc_b_end(id e) { m4_end(e); }
static inline void enc_b_copy_buffer(id e, id<MTLBuffer> s, NSUInteger so, id<MTLBuffer> d, NSUInteger doff, NSUInteger n) { [e copyFromBuffer:s sourceOffset:so toBuffer:d destinationOffset:doff size:n]; }
static inline void enc_b_copy_buffer_texture(id e, id<MTLBuffer> s, NSUInteger so, NSUInteger row, NSUInteger img, MTLSize z, id<MTLTexture> d, NSUInteger sl, NSUInteger lv, MTLOrigin o) { [e copyFromBuffer:s sourceOffset:so sourceBytesPerRow:row sourceBytesPerImage:img sourceSize:z toTexture:d destinationSlice:sl destinationLevel:lv destinationOrigin:o]; }
static inline void enc_b_copy_texture_buffer(id e, id<MTLTexture> s, NSUInteger sl, NSUInteger lv, MTLOrigin o, MTLSize z, id<MTLBuffer> d, NSUInteger doff, NSUInteger row, NSUInteger img) { [e copyFromTexture:s sourceSlice:sl sourceLevel:lv sourceOrigin:o sourceSize:z toBuffer:d destinationOffset:doff destinationBytesPerRow:row destinationBytesPerImage:img]; }
static inline void enc_b_copy_texture(id e, id<MTLTexture> s, NSUInteger sl, NSUInteger lv, MTLOrigin so, MTLSize z, id<MTLTexture> d, NSUInteger dl, NSUInteger dv, MTLOrigin doo) { [e copyFromTexture:s sourceSlice:sl sourceLevel:lv sourceOrigin:so sourceSize:z toTexture:d destinationSlice:dl destinationLevel:dv destinationOrigin:doo]; }
static void blit_note(void);   // Per-pass dump: a copy / buffer update ended the render pass (defined after PD)
// Ordering inside the copy encoder: Metal 4 does not order copies / fills within one encoder (no automatic hazard tracking); an operation reading or writing a range an earlier one wrote needs an intra-encoder barrier.
// Without it, SMBW's two updates per frame to the same uniform slot ("write 4 bytes −1, then 16 bytes of coefficients") occasionally landed in reverse order; the fountain water wave simulation took −1 as its self coefficient, diverged, and the water vertices were pushed to the top of the screen.
// Buffer operations check conflicts by guest address range: a barrier when an operation reads a range written earlier, or writes a range read or written earlier; texture operations get
// one whenever the encoder already holds an operation. Reads were not tracked at first, so a copy writing bytes an earlier copy reads could run first (seen in Cuphead while its pool
// allocator gave out overlapping blocks, see hle_nvn.c zcull_size; NVN runs copies in order for any game)
enum { BW_MAX = 64 };
static uint64_t g_bw_lo[BW_MAX], g_bw_hi[BW_MAX], g_br_lo[BW_MAX], g_br_hi[BW_MAX]; static int g_bw_n, g_br_n, g_blit_ops; static uint64_t g_blit_barriers;
static uint64_t g_blit_splits;   // copies / buffer updates / fills that ended an open draw pass (the residency set line; a pass ended this way stores and the next one reloads its attachments)
uint64_t nvn_be_blit_splits(void) { return g_blit_splits; }
static int enc_open(void);
static int g_blit_ct;   // the open copy encoder has the compute argument table set (dispatches share it, dispatch_enc)
// Metal 4 copies and dispatches share g_blit, a compute encoder. Metal 3 has them in different encoders: g_blit is a copy encoder (MTLBlitCommandEncoder) for copies and a compute
// encoder for dispatches (g_blit_cmp); a copy after a dispatch or a dispatch after a copy ends it and begins the other kind, ordered by g_fence3 like any two encoders
static int g_blit_cmp;
static uint64_t g_blit_splits3;   // Metal 3: copy encoders ended for a barrier inside them (blit_barrier)
static id<MTL4ComputeCommandEncoder> blit_open_k(int cmp) {
    if (!g_rlane) geo_run_flush();   // a geometry run's lanes go before any other encoder of the main stream (nvn_geometry.inc)
    if (g_blit && g_m3 && g_blit_cmp != cmp) { enc_b_end(g_blit); g_blit = nil; }
    if (!g_blit) { ser_gate();
        if (g_m3) {
            if (cmp && gp_active() && g_gp_state < 2) {   // GPUPROF: the shared dispatch encoder samples too; a copy encoder cannot (no sample buffer attachments)
                MTLComputePassDescriptor *cd = [MTLComputePassDescriptor computePassDescriptor]; gp_pre(cd, 'C');
                g_blit = [g_cb computeCommandEncoderWithDescriptor:cd];
            } else g_blit = cmp ? [g_cb computeCommandEncoder] : [g_cb blitCommandEncoder];
            g_blit_cmp = cmp; m3_wait(g_blit, 0, 0);
        }
        else { g_blit = enc_b_begin(g_cb); main_barrier_begin(g_blit, 0); }
        gp_begin(g_blit, 'C', nil); g_bw_n = g_br_n = 0; g_blit_ops = 0; g_blit_ct = 0; }
    return g_blit;
}
static id<MTL4ComputeCommandEncoder> blit_open(void) { return blit_open_k(0); }
static void ubd_flush(void); static int g_nubd;   // the inline updates deferred (see mtl_sub_update)
static int g_ubd_landing;
static id<MTL4ComputeCommandEncoder> blit_raw(void) {
    blit_note(); if (enc_open()) g_blit_splits++; rp_end(); id<MTL4ComputeCommandEncoder> e = blit_open();
    if (g_nubd && !g_ubd_landing) { g_ubd_landing = 1; ubd_flush(); g_ubd_landing = 0; }   // deferred inline updates come before this copy or dispatch in command order
    (void)e; return g_blit;   // not e: on Metal 3 a barrier in the updates may have begun a new copy encoder (blit_barrier)
}
// Land the deferred inline updates before other GPU work outside the copy encoder (helper compute passes, the end of the submission, a GPU wait)
static void ubd_land(void) { if (g_nubd && !g_ubd_landing) { rp_end(); g_ubd_landing = 1; ubd_flush(); g_ubd_landing = 0; } }
static void ubd_land_compute(void) { if (g_nubd && !g_ubd_landing) { ubd_land(); if (g_blit) { enc_b_end(g_blit); g_blit = nil; } } }   // before a compute encoder of its own (no other encoder may be open then)
// 计算编码器内屏障（之前的派发 / 拷贝写完、之后的才读）：Metal 4 编码器内屏障，Metal 3 计算编码器的内存屏障（iOS 12 起）。blit_barrier 与 enc_c_dep 共用
static void enc_c_inner_barrier(id e) {
    if (!g_m3) [e barrierAfterEncoderStages:MTLStageDispatch | MTLStageBlit beforeEncoderStages:MTLStageDispatch | MTLStageBlit visibilityOptions:MTL4VisibilityOptionDevice];
    else [(id<MTLComputeCommandEncoder>)e memoryBarrierWithScope:MTLBarrierScopeBuffers | MTLBarrierScopeTextures];
}
static void blit_barrier(void) {
    static int off = -1; if (off < 0) { const char *e = getenv("DM_NVN_BLIT_ORDER"); off = e && !strcmp(e, "0"); if (off) MLOG("DM_NVN_BLIT_ORDER=0: no barriers inside the copy encoder (diagnostic; brings back the fountain's vertical stripes)"); }
    // Only the stages a compute encoder has: MTLStageAll here fails Metal validation (macOS 27: "must be a valid combination of MTLStages for the current encoder type")
    if (!off && (!g_m3 || g_blit_cmp)) enc_c_inner_barrier(g_blit);
    // Metal 3: compute encoders have a barrier inside them (memoryBarrierWithScope, iOS 12 on); copy encoders have none, so the copy encoder ends and a new one begins after the fence.
    // Callers take g_blit again after this
    else if (!off) { enc_b_end(g_blit); g_blit = nil; blit_open_k(0); g_blit_splits3++; }
    g_bw_n = g_br_n = 0; g_blit_ops = 0; g_blit_barriers++;
}
uint64_t mtl_blit_barriers(void) { return g_blit_barriers; }
static int bw_hit(uint64_t lo, uint64_t hi) { for (int i = 0; i < g_bw_n; i++) if (lo < g_bw_hi[i] && g_bw_lo[i] < hi) return 1; return 0; }
static int br_hit(uint64_t lo, uint64_t hi) { for (int i = 0; i < g_br_n; i++) if (lo < g_br_hi[i] && g_br_lo[i] < hi) return 1; return 0; }
// buffer → buffer / fill: reads [rlo, rhi) (0, 0 when nothing is read), writes [wlo, whi)
static uint64_t g_wr_epoch;   // Bumped by every buffer write outside a render pass (copy / update / fill, texture → buffer, dispatch): indirect-draw conversions made before it are stale (ixc_run)
static uint64_t g_mdx_epoch;  // Bumped by GPU writes that can change an indirect-count multi-draw's records or count (copy, fill, texture → buffer, dispatch; see mdx_run)
static id<MTL4ComputeCommandEncoder> blit_buf(uint64_t rlo, uint64_t rhi, uint64_t wlo, uint64_t whi) {
    g_wr_epoch++;
    id<MTL4ComputeCommandEncoder> e = blit_raw();
    if (g_blit_ops && (g_bw_n == BW_MAX || g_br_n == BW_MAX || (rhi > rlo && bw_hit(rlo, rhi)) || bw_hit(wlo, whi) || br_hit(wlo, whi))) blit_barrier();
    g_bw_lo[g_bw_n] = wlo; g_bw_hi[g_bw_n++] = whi; g_blit_ops++; g_gp_copies++;
    if (rhi > rlo) { g_br_lo[g_br_n] = rlo; g_br_hi[g_br_n++] = rhi; }
    (void)e; return g_blit;   // see blit_raw
}
// texture copies / readbacks: barrier if anything came before, and later operations must wait for it too
static id<MTL4ComputeCommandEncoder> blit(void) {
    id<MTL4ComputeCommandEncoder> e = blit_raw();
    if (g_blit_ops) blit_barrier();
    g_bw_lo[0] = 0; g_bw_hi[0] = ~0ull; g_bw_n = 1; g_br_n = 0; g_blit_ops = 1;   // record as "everything written": the next operation always gets a barrier
    (void)e; return g_blit;   // see blit_raw
}

void mtl_sub_copy(uint64_t src, uint64_t dst, uint64_t n) {
    pend_add(dst, n, 2); g_mdx_epoch++;
    void *sb, *db; uint64_t so, dof;
    if (!nvn_be_addr(src, n, &sb, &so) || !nvn_be_addr(dst, n, &db, &dof))
        MDIE("buffer copy address is in no memory pool src=%#llx dst=%#llx n=%#llx", (unsigned long long)src, (unsigned long long)dst, (unsigned long long)n);
    if (src != dst && src < dst + n && dst < src + n) { static int once;   // Metal leaves an overlapping copy undefined; seen only in Cuphead while its pool allocator gave out overlapping blocks (hle_nvn.c zcull_size)
        if (!once++) MLOG("【红】 buffer copy with overlapping source and destination (src %#llx dst %#llx, %llu bytes): the result is undefined", (unsigned long long)src, (unsigned long long)dst, (unsigned long long)n); }
    enc_b_copy_buffer(blit_buf(src, src + n, dst, dst + n), (__bridge id<MTLBuffer>)sb, so, (__bridge id<MTLBuffer>)db, dof, n);
}

// Inline uniform update (UpdateUniformBuffer): the data is copied into the host's own shared ring at encode time, then copied in order to the destination.
// Previously it was read from command memory only when the GPU executed - if the game recycles command memory before the GPU runs, it reads the bytes of the next batch of commands (SMBW's fountain water wave simulation got the wrong coefficients and diverged to ±65504).
static id<MTLBuffer> g_ubs_buf; static size_t g_ubs_off, g_ubs_size;
// Inline updates inside an open render pass are deferred instead of ending the pass. Metal cannot copy into a buffer inside a render pass, so each update used to end it: all attachments stored,
// reloaded by the next pass, new encoders (Metroid Dread about 246 times a frame, Tears of the Kingdom about 50). NVN applies the update in command order, so the draws after it in the pass must
// read the new data: a draw whose uniform binding overlaps a deferred update reads a shadow. When the updates deferred in this pass cover all of the binding the shader can read, the shadow is
// made of them alone, latest first per byte (exactly what the GPU would read, whatever earlier frames still have in flight); when they cover only part of it, the rest comes from memory (ubp_get).
// The real copies are encoded in order when the pass ends (rp_end), so later passes and the CPU see them as before. The pass still ends before a draw that would need more: a partly covered binding
// whose rest memory cannot give, or a read of the deferred data through a vertex, index, indirect or storage buffer (ubd_conflict). Also on in TBDR mode (see ubd_on). DM_NVN_UB_DEFER=0 turns it off
static size_t arena_alloc(size_t n, id<MTLBuffer> *buf); static inline void args_dirty_all(void); static void ubd_dirty(uint64_t lo, uint64_t hi);
typedef struct { uint64_t lo, hi, gpu; size_t off; __unsafe_unretained id<MTLBuffer> buf; uint32_t seq; } ubd_ent;   // data at buf + off (the ubs ring; a ring block replaced meanwhile lives until this submission completes); seq: order deferred
enum { UBD_MAX = 512 };
static ubd_ent g_ubd[UBD_MAX]; static int g_nubd;   // in the order deferred (ubd_flush lands them so)
// The same entries sorted by start (equal starts in the order deferred), and g_ubx_hi[i] = the largest end among g_ubx[0..i]. Every update overlapping [lo, hi) starts before hi,
// and walking back from the last of those can stop once the running end is lo or less: a lookup reads the entries that can overlap, a binary search and a few more, not the list.
// 11-01 Monster Hunter Rise: about 1,700 deferred updates a frame keep the list hundreds long, and every uniform binding of every draw was looked up in it several times
// (ubd_conflict, encode_args, the widen glue). Its iPhone submit thread ran ~100k instructions a draw, and across 194 logged 300-frame windows they grew with the deferred updates,
// not the draws. A page filter in front of the scan did not help when the bindings share pages with the updates. A Mac replay of that pattern (1,440 draws, a partial update
// before each): the scans were a third of the submit thread's samples, 35.3k → 20.2k instructions a draw (29.7k → 14.5k with the encode thread on); t_nvn_ubd_index ②: 7,992 → 199 a lookup
static ubd_ent g_ubx[UBD_MAX]; static uint64_t g_ubx_hi[UBD_MAX]; static uint32_t g_ubd_seq;
static uint64_t g_ubd_gen = 1;   // + 1 at every ubd_flush (seq starts over): the widen glue's view of a binding made from the deferred updates continues from an earlier one only within one generation
static uint64_t g_ubd_deferred, g_ubd_conflicts;   // updates deferred, passes ended before a draw that needed more (the residency set line)
// Not exclusive with tbdr_on() (S2Arm 11-04 energy line): the upstream import tied it off whenever DM_NVN_TBDR=1, and every in-pass update then ended the pass again —
//   botw on a Mac: 116 passes a frame with TBDR off, 341 with it on, 337 with TBDR off and DM_NVN_UB_DEFER=0. The TBDR lookaheads that reorder passes (defer_try, hoist, fuse)
//   already stop at OP_UPDATE_UB, so deferring updates only makes them bail earlier. Same for lc_on (lazy clears) below
static int ubd_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_UB_DEFER"); v = !(e && !strcmp(e, "0")); if (!v) MLOG("DM_NVN_UB_DEFER=0: uniform updates inside a pass end the pass as before"); } return v; }
void nvn_be_ubd_stats(uint64_t *deferred, uint64_t *conflicts) { *deferred = g_ubd_deferred; *conflicts = g_ubd_conflicts; }
// Across passes (DM_NVN_UB_LAZY=n, at most n updates kept past a pass end, default 160; 0 = landed at every pass end as before): the deferred updates are not landed when their pass ends but
// when something needs the memory itself: a copy or dispatch (they go into that compute encoder first), a draw that reads them other than as a uniform buffer the shadows cover
// (ubd_conflict), the end of the submission, more than n of them. An update with no pass
// open is deferred too, unless a compute encoder is open (it then goes in there). Breath of the Wild had about 45 small copy encoders between its render passes a frame, each with
// 10-50 µs of idle GPU before and after it: GPU time 9.3 → 8.0 ms a frame, frame 11.9 → 10.7 ms at the 120 fps cap (M2 Max), for about 0.8 ms more translation (more shadows).
// The list can then hold hundreds of updates: lookups go through the sorted copy g_ubx
static int ubd_lazy(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_UB_LAZY"); v = e ? atoi(e) : 160; if (v < 0) v = 0; } return v; }   // the most updates kept across a pass end (0 = off)
static int ubx_lb(uint64_t a) { int l = 0, h = g_nubd; while (l < h) { int m = (l + h) >> 1; if (g_ubx[m].lo < a) l = m + 1; else h = m; } return l; }    // the first entry starting at or after a
static int ubx_ub(uint64_t a) { int l = 0, h = g_nubd; while (l < h) { int m = (l + h) >> 1; if (g_ubx[m].lo <= a) l = m + 1; else h = m; } return l; }   // the first entry starting after a
static void ubx_fix(int from) { uint64_t m = from ? g_ubx_hi[from - 1] : 0; for (int i = from; i < g_nubd; i++) { if (g_ubx[i].hi > m) m = g_ubx[i].hi; g_ubx_hi[i] = m; } }
// A new deferred update [lo, hi) (mtl_sub_update): the ones it covers whole never need to land (the same landing writes these bytes after them, and the draws that read them hold
// their ring copies, ubd_shadow) and leave both lists; then it joins them. Games rewrite one block before every draw group (Breath of the Wild: the same 64 bytes), so this keeps the list short
static void ubd_add(uint64_t lo, uint64_t hi, uint64_t gpu, size_t off, id<MTLBuffer> buf) {
    int a = ubx_lb(lo), b = ubx_lb(hi), w = a;   // the covered ones start inside [lo, hi)
    for (int i = a; i < b; i++) if (g_ubx[i].hi > hi) g_ubx[w++] = g_ubx[i];
    if (w < b) {   // some were covered: out of the list in order too
        memmove(&g_ubx[w], &g_ubx[b], (size_t)(g_nubd - b) * sizeof *g_ubx);
        int k = 0; for (int i = 0; i < g_nubd; i++) if (!(lo <= g_ubd[i].lo && g_ubd[i].hi <= hi)) g_ubd[k++] = g_ubd[i];
        g_nubd = k; }
    ubd_ent e = {lo, hi, gpu, off, buf, g_ubd_seq++};
    int at = ubx_ub(lo); memmove(&g_ubx[at + 1], &g_ubx[at], (size_t)(g_nubd - at) * sizeof *g_ubx);
    g_ubx[at] = e; g_ubd[g_nubd++] = e;
    ubx_fix(a < at ? a : at);
}
static int ubd_hits(uint64_t lo, uint64_t hi) {
    if (hi <= lo || !g_nubd) return 0;
    int j = ubx_lb(hi); return j > 0 && g_ubx_hi[j - 1] > lo;   // some entry starting before hi ends after lo
}
// Whether the deferred updates cover [lo, hi) entirely (any order of overlap): from at = lo, the farthest end among the entries starting at or before at, until at reaches hi
static int ubd_covers(uint64_t lo, uint64_t hi) {
    for (uint64_t at = lo; at < hi;) { int j = ubx_ub(at); if (!j || g_ubx_hi[j - 1] <= at) return 0; at = g_ubx_hi[j - 1]; }
    return 1;
}
// The deferred updates overlapping [lo, hi), oldest first, into ov (room for cap) → their count, or -1 when more than cap overlap; *newest = the newest of them (NULL for none)
static int ubd_overlaps(uint64_t lo, uint64_t hi, const ubd_ent **ov, int cap, const ubd_ent **newest) {
    int n = 0; *newest = NULL;
    for (int i = ubx_lb(hi) - 1; i >= 0 && g_ubx_hi[i] > lo; i--) if (g_ubx[i].hi > lo) {
        if (!*newest || g_ubx[i].seq > (*newest)->seq) *newest = &g_ubx[i];
        if (n >= 0 && n < cap) ov[n++] = &g_ubx[i]; else n = -1; }
    for (int i = 1; i < n; i++) { const ubd_ent *v = ov[i]; int j = i; while (j > 0 && ov[j - 1]->seq > v->seq) { ov[j] = ov[j - 1]; j--; } ov[j] = v; }
    return n;
}
// [lo, hi) into d as the deferred updates leave it: each overlapping one laid over in the order deferred, so each byte ends with the newest write (bytes none of them covers are left alone)
static void ubd_lay1(const ubd_ent *e, uint64_t lo, uint64_t hi, uint8_t *d) {
    uint64_t a = e->lo > lo ? e->lo : lo, b = e->hi < hi ? e->hi : hi;
    if (a < b) memcpy(d + (a - lo), (const uint8_t *)e->buf.contents + e->off + (a - e->lo), (size_t)(b - a));
}
static void ubd_lay(uint64_t lo, uint64_t hi, uint8_t *d, const ubd_ent *const *ov, int n) {
    if (n < 0) { for (int i = 0; i < g_nubd; i++) ubd_lay1(&g_ubd[i], lo, hi, d); return; }   // many overlap: the whole list, which is in that order
    for (int i = 0; i < n; i++) ubd_lay1(ov[i], lo, hi, d);
}
enum { UBD_OV = 32 };
// GPU address of the shadow of uniform range [lo, hi) (ubd_covers holds): the newest update overlapping it, when it holds all of it and is suitably aligned, is used in place; otherwise the updates are laid into the arena in order
static uint64_t ubd_shadow(uint64_t lo, uint64_t hi) {
    const ubd_ent *ov[UBD_OV], *e; int n = ubd_overlaps(lo, hi, ov, UBD_OV, &e);
    if (e && e->lo <= lo && hi <= e->hi) { uint64_t g = e->gpu + (lo - e->lo); if (!(g & 15)) return g; }
    id<MTLBuffer> ab; size_t o = arena_alloc((size_t)(hi - lo), &ab); uint8_t *d = (uint8_t *)ab.contents + o;
    ubd_lay(lo, hi, d, ov, n);
    return ab.gpuAddress + o;
}
// Encode the deferred copies in order (rp_end, once the pass has ended)
static void ubd_flush(void) {
    int n = g_nubd; g_nubd = 0; g_ubd_seq = 0; g_ubd_gen++;
    for (int i = 0; i < n; i++) { const ubd_ent *e = &g_ubd[i]; void *db; uint64_t dof;
        if (!nvn_be_addr(e->lo, e->hi - e->lo, &db, &dof)) continue;
        enc_b_copy_buffer(blit_buf(0, 0, e->lo, e->hi), e->buf, e->off, (__bridge id<MTLBuffer>)db, dof, e->hi - e->lo); g_gp_ubd++; }
}
// The bytes [lo, lo+n) as the deferred updates leave them (ubd_covers holds): for bindless handles read from uniform memory (ubo_handle)
static void ubd_read(uint64_t lo, size_t n, void *out) {
    const ubd_ent *ov[UBD_OV], *e; int k = ubd_overlaps(lo, lo + n, ov, UBD_OV, &e); ubd_lay(lo, lo + n, (uint8_t *)out, ov, k);
}
// Bindings the deferred updates cover only in part. The rest of the binding is what memory holds when the pass runs on the GPU. The shadow then starts from memory as the CPU sees it at encode
// time and lays over it every inline update queued in this submission that overlaps it, in queue order (earlier passes' updates, encoded but not yet run, and this pass's deferred ones): exactly
// what the GPU would read. It is made only when nothing else can have written the range by then: no copy, fill or feedback write queued in this submission (pend kinds 2–4), no writable storage
// buffer, texture→buffer copy or counter report over it in this submission (sbw), and no GPU write of an earlier submission still running (gw, by 4 KB page). Otherwise the pass ends as before.
// Breath of the Wild updates part of a bound block about 226 times a frame outdoors and ended a pass for nearly every one (about 900 MB of attachment loads and stores a frame on an iPhone).
// DM_NVN_UB_PARTIAL=0 turns it off
static int ub_partial_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_UB_PARTIAL"); v = !(e && !strcmp(e, "0")); if (!v) MLOG("DM_NVN_UB_PARTIAL=0: a binding the deferred uniform updates cover only in part ends the pass as before"); } return v; }
enum { GW_N = 1 << 16, GW_PAGES = 4096 };   // 4,096 slots fill up in Ocarina of Time, every slot then a false hit for some page (passes ended over blocks no GPU write touched; upstream reference implementation, MIT)
static struct { uint64_t page, fence; } g_gw[GW_N];   // page ~0: two live pages met in the slot, so any page there counts as written until fence completes
static uint64_t g_gw_all;                            // every page counts as written until this fence completes (a submission whose writes could not all be listed)
static uint64_t g_ubp_made, g_ubp_reused, g_ubp_refused;   // partial shadows made / taken from the cache / refused (the pass ended), for the residency set line
static uint64_t g_ubp_why[5];   // why ubp_get refused: 0 too large or off, 1 other GPU writes in this submission (sbw), 2 GPU writes of an earlier submission still running, 3 a copy, fill or feedback write queued, 4 unreadable or too many writes
static inline unsigned gw_slot(uint64_t pg) { return (unsigned)((pg * 0x9E3779B97F4A7C15ull) >> (64 - __builtin_ctz(GW_N))) & (GW_N - 1); }   // the top log2(GW_N) bits of the product
static void gw_put(uint64_t lo, uint64_t hi, uint64_t fence, uint64_t done) {
    if (hi <= lo) return;
    uint64_t p0 = lo >> 12, p1 = (hi - 1) >> 12;
    if (p1 - p0 >= GW_PAGES) { if (fence > g_gw_all) g_gw_all = fence; return; }
    for (uint64_t pg = p0; pg <= p1; pg++) { unsigned s = gw_slot(pg);
        g_gw[s].page = g_gw[s].page == pg || g_gw[s].fence <= done ? pg : ~0ull;
        if (fence > g_gw[s].fence) g_gw[s].fence = fence; }
}
static int gw_live(uint64_t lo, uint64_t hi) {
    uint64_t done = g_done;   // read without the lock as elsewhere: a stale value only refuses more
    if (g_gw_all > done) return 1;
    for (uint64_t pg = lo >> 12; pg <= (hi - 1) >> 12; pg++) { unsigned s = gw_slot(pg); if ((g_gw[s].page == pg || g_gw[s].page == ~0ull) && g_gw[s].fence > done) return 1; }
    return 0;
}
// The submission's GPU writes go into the page table with its fence (nvn_be_sub_commit)
static void gw_commit(uint64_t fence) {
    uint64_t done = g_done;
    if ((g_pend_over || g_sbw_over) && fence > g_gw_all) g_gw_all = fence;
    for (int e = 0; e < g_npend; e++) gw_put(g_pend_lo[e], g_pend_hi[e], fence, done);
    if (g_nsbw) for (int i = 0; i < SBW_N; i++) if (g_sbwp[i].gen == g_pend_gen) gw_put(g_sbwp[i].page << 12, (g_sbwp[i].page + 1) << 12, fence, done);
}
// The writes queued in this submission from index since on that overlap [a, b), newest first, into out (room for every entry a lookup can meet); -1 when they cannot all be told
static int pend_since(uint64_t a, uint64_t b, int since, int *out) {
    if (g_pend_over) return -1;
    int n = 0; uint64_t p0 = a >> 12, p1 = (b - 1) >> 12;
    if (p1 - p0 >= PEND_SPAN) { for (int e = g_npend - 1; e >= since; e--) if (a < g_pend_hi[e] && g_pend_lo[e] < b) out[n++] = e; return n; }   // every entry, newest first
    for (int i = 0; i < g_nwide; i++) { int e = g_pend_wide[i]; if (e >= since && a < g_pend_hi[e] && g_pend_lo[e] < b) out[n++] = e; }
    for (uint64_t pg = p0; pg <= p1; pg++) { unsigned bk = pend_bucket(pg); if (g_pend_hgen[bk] != g_pend_gen) continue;
        for (int k = g_pend_head[bk]; k >= 0 && g_pend_node[k].e >= since; k = g_pend_node[k].next) { int e = g_pend_node[k].e; if (a < g_pend_hi[e] && g_pend_lo[e] < b) out[n++] = e; } }   // chains run newest first
    if (n > 1 && (g_nwide || p1 > p0)) {   // several lists: newest first, each once
        for (int i = 1; i < n; i++) { int v = out[i], j = i; while (j > 0 && out[j - 1] < v) { out[j] = out[j - 1]; j--; } out[j] = v; }
        int m = 1; for (int i = 1; i < n; i++) if (out[i] != out[m - 1]) out[m++] = out[i];
        n = m; }
    return n;
}
int nvn_host_readable(uint64_t a, uint64_t n);   // hle_nvn.c: guest memory and sparse pools
// Shadows made from memory, per range. One is kept while no write is queued after it (the draws after an update bind the same block again and again); the next one for the same range starts
// from it and lays over only the writes queued since (the game rewrites one block hundreds of times a submission). A range read whole from memory once is not read from memory again in the submission
enum { UBP_CACHE = 16, UBP_MAX_BYTES = 65536 };
enum { UBP_DMAX = 64 };
typedef struct { uint64_t lo, hi, gpu; uint8_t *cpu; int npend; uint32_t gen, sbw; uint64_t q, agen, pq; int nd; uint32_t d[2 * UBP_DMAX]; } ubp_ent;   // agen: g_arena_gen when made (the shadow lives in the frame scratch)   // sbw: g_sbw_gen when the other writes were last checked; q: end of the copies that fill it (g_ubq)
//   pq / nd / d: the lineage the shadow was made with (see g_ubp_prevq below), handed out again when the kept shadow is reused: the vertex and fragment stages bind the same range,
//   and the second one (a cache hit, same shadow) used to get "continues itself, nothing changed", so a copy still holding the previous shadow was rebuilt and compared whole
//   (11-02 Breath of the Wild replay: ~237 whole hand-overs of ~62 KB a frame, the largest part of wd_draw)
static uint64_t g_ubp_q;   // q of the shadow ubp_get returned last: ubq_cpu(g_ubp_q) before reading it on the CPU, ubq_gpu(g_ubp_q) when it is bound for the GPU
// Lineage of that shadow (the widen glue hands the widen core only what changed, widen_glue.inc wd_cb_view): g_ubp_prevq = the shadow it continues and g_ubp_nd its g_ubp_d pairs
//   [lo, hi) (offsets in the range, ascending, disjoint) where it can differ from that one; nd 0 = the same bytes, -1 = not known (a fresh shadow, or more pieces than kept)
static uint64_t g_ubp_prevq; static int g_ubp_nd; static uint32_t g_ubp_d[2 * UBP_DMAX];
static ubp_ent g_ubpc[UBP_CACHE]; static unsigned g_ubpc_i;
// The copies that fill shadows, in order, made only once someone needs them: a shadow read on the CPU (the widen glue's view of a binding, a bindless handle, ubp_check) is made
// right here on the submit thread (ubq_cpu); one bound for the GPU (encode_args) goes to the copy worker when large, here when small (ubq_gpu); the rest go before every commit (ubq_flush).
// They used to be queued to the worker as soon as the shadow was made, and a CPU reader then waited for it. In a draw ubd_conflict makes the shadows first and the widen glue reads
// them right after: 11-01 Monster Hunter Rise did that about 4,600 times a frame on iPhone, the worker took 0.12 of a core, the submit thread's wall clock ran 2 ms a frame past its CPU
// time and its kernel time was 2.4 ms a frame (each hand-off can wake the worker and the waiter: two condition-variable calls). A shadow's copies all go one way (see ubq_issue)
typedef struct { void *d; const void *s; uint32_t n; uint8_t big, dep; uint64_t seq; } ubq_op;   // big: its shadow is ≥ 512 bytes (worker when bound for the GPU); dep: s is another shadow; seq: the worker's ready when handed there
enum { UBQ_N = 8192 };
// Shadows of at least this many bytes go to the worker when bound for the GPU. The hand-off is not free: on an M5 Max (t_nvn_submit_cost-like replay, 1,440 draws, one shadow each, best
//   of three) the submit thread took 1.99 / 2.29 / 2.30 / 2.27 ms of CPU a frame with the worker against 1.88 / 2.00 / 2.22 / 2.80 ms copying itself, for shadows of 2 / 4 / 8 / 16 KB;
//   the worker's start was 512 bytes. Breath of the Wild's shadows (14 MB in about 440 a frame, ~32 KB each) still go there
enum { UBQ_ASYNC = 8192 };
static ubq_op g_ubq[UBQ_N]; static uint64_t g_ubq_head, g_ubq_tail, g_ubq_async;   // [head, tail) not made yet; async: the last op handed to the worker
static uint64_t g_ubq_cpu, g_ubq_gpu;   // ops made here / handed to the worker (tests)
static void ubq_issue(uint64_t upto, int cpu) {
    for (; g_ubq_head < upto; g_ubq_head++) { ubq_op *o = &g_ubq[g_ubq_head % UBQ_N];
        if (!cpu && o->big && ubc_on()) { o->seq = g_ubq_async = ubc_push(o->d, o->s, o->n); g_ubq_gpu++; continue; }
        if (o->dep && g_ubq_async) ubc_wait(g_ubq_async);   // its source shadow may have been handed to the worker
        memcpy(o->d, o->s, o->n); o->seq = 0; g_ubq_cpu++; }
}
static void ubq_cpu(uint64_t q) {   // the shadow whose copies end at q is read on the CPU now
    if (q > g_ubq_head) { ubq_issue(q, 1); return; }
    uint64_t s = q && q + UBQ_N > g_ubq_tail ? g_ubq[(q - 1) % UBQ_N].seq : g_ubq_async;   // made already: wait only if its last op went to the worker
    if (s) ubc_wait(s);
}
static void ubq_gpu(uint64_t q) { if (q > g_ubq_head) ubq_issue(q, 0); }
static void ubq_flush(void) { ubq_issue(g_ubq_tail, 0); }   // before a commit (rec_commit / rec_commit_m3): the GPU reads every shadow made so far
static void ubq_put(void *d, const void *s, size_t n, int big, int dep) { g_ubq[g_ubq_tail++ % UBQ_N] = (ubq_op){d, s, (uint32_t)n, (uint8_t)big, (uint8_t)dep, 0}; }
// The bytes [lo, hi) as the GPU will read them at this point of the submission (see above): 1 with the shadow's GPU and CPU addresses, 0 when they cannot be known (the pass ends instead)
static void ubp_lineage(const ubp_ent *c) {   // a kept shadow handed out again: the same shadow, with the lineage it was made with
    g_ubp_q = c->q; g_ubp_prevq = c->pq; g_ubp_nd = c->nd; if (c->nd > 0) memcpy(g_ubp_d, c->d, 2 * (size_t)c->nd * sizeof *g_ubp_d);
}
static int ubp_get(uint64_t lo, uint64_t hi, uint64_t *gpu, const uint8_t **cpu) {
    if (!ub_partial_on() || hi <= lo || hi - lo > UBP_MAX_BYTES) { g_ubp_why[0]++; return 0; }
    ubp_ent *c = NULL;
    for (int i = 0; i < UBP_CACHE; i++) if (g_ubpc[i].lo == lo && g_ubpc[i].hi == hi && g_ubpc[i].gen == g_pend_gen && g_ubpc[i].agen == g_arena_gen) { c = &g_ubpc[i]; break; }
    if (!c || c->sbw != g_sbw_gen) { if (g_sbw_over || sbw_hits(lo, hi)) { g_ubp_why[1]++; return 0; } if (c) c->sbw = g_sbw_gen;
        if (g_gml_on) { pthread_mutex_lock(&g_gsr_mu); uint64_t i = g_gsr_n++ % GSR_N; g_gsr[i].fence = g_fence + 1; g_gsr[i].lo = lo; g_gsr[i].hi = hi; pthread_mutex_unlock(&g_gsr_mu); } }
    if (c && c->npend == g_npend) { g_ubp_reused++; *gpu = c->gpu; *cpu = c->cpu; ubp_lineage(c); return 1; }
    int since = c ? c->npend : 0;
    if (!c && gw_live(lo, hi)) { g_ubp_why[2]++; return 0; }
    if (!c && !nvn_host_readable(lo, hi - lo)) { g_ubp_why[4]++; return 0; }
    int n = pend_since(lo, hi, since, g_ubp_idx); if (n < 0) { g_ubp_why[4]++; return 0; }
    // Nothing queued over the range since the kept shadow (the writes since went elsewhere): the next one would be a byte-for-byte copy of it, so it is the answer.
    //   The kept one is of this arena generation (the lookup above), so its scratch has not been handed back (cdad08ca9)
    if (c && !n) { c->npend = g_npend; g_ubp_reused++; *gpu = c->gpu; *cpu = c->cpu; ubp_lineage(c); return 1; }
    // Newest first, keep the writes that still show through somewhere (a write only newer ones cover is never read, whatever wrote it); stop once they cover the range
    enum { COVN = 64 }; uint64_t cl[COVN], ch[COVN]; int nc = 0, nk = 0, exact = 1;   // covered intervals, sorted and disjoint; exact = 0 once they no longer fit
    for (int i = 0; i < n; i++) { int e = g_ubp_idx[i];
        uint64_t x = g_pend_lo[e] > lo ? g_pend_lo[e] : lo, y = g_pend_hi[e] < hi ? g_pend_hi[e] : hi;
        int j = 0; while (j < nc && ch[j] < y) j++;
        if (exact && j < nc && cl[j] <= x && y <= ch[j]) continue;   // newer writes cover all of it
        if (g_pend_kind[e] != 1 || !g_pend_upd[e]) { g_ubp_why[3]++; return 0; }   // a copy, fill or feedback write the CPU cannot see
        g_ubp_idx[nk++] = e;
        if (exact) {   // add [x, y) and merge neighbours
            int k = 0; while (k < nc && ch[k] < x) k++;
            int m = k; uint64_t nl = x, nh = y; while (m < nc && cl[m] <= y) { nl = MIN(nl, cl[m]); nh = MAX(nh, ch[m]); m++; }
            if (nc - (m - k) + 1 > COVN) exact = 0;
            else { memmove(&cl[k + 1], &cl[m], (nc - m) * sizeof *cl); memmove(&ch[k + 1], &ch[m], (nc - m) * sizeof *ch); nc = nc - (m - k) + 1; cl[k] = nl; ch[k] = nh;
                   if (nc == 1 && cl[0] == lo && ch[0] == hi) break; } } }
    uint64_t len = hi - lo;
    id<MTLBuffer> ab; size_t o = arena_alloc((size_t)len, &ab); uint8_t *d = (uint8_t *)ab.contents + o;
    int big = len >= UBQ_ASYNC;   // smaller ones are always copied here: handing a copy to the worker costs more than making it (see UBQ_ASYNC)
    if (UBQ_N - (g_ubq_tail - g_ubq_head) < (uint64_t)nk + 1) ubq_flush();   // a shadow's copies never straddle a forced flush
    ubq_put(d, c ? c->cpu : (const uint8_t *)(uintptr_t)lo, (size_t)len, big, c != NULL);   // the previous shadow's own copies are queued before these
    for (int i = nk - 1; i >= 0; i--) { int e = g_ubp_idx[i]; const upd_ent *u = &g_upd[g_pend_upd[e] - 1];   // oldest first: each byte ends with the newest write
        uint64_t x = g_pend_lo[e] > lo ? g_pend_lo[e] : lo, y = g_pend_hi[e] < hi ? g_pend_hi[e] : hi;
        ubq_put(d + (x - lo), (const uint8_t *)u->buf.contents + u->off + (x - u->lo), (size_t)(y - x), big, 0); }
    g_ubp_made++;
    g_ubp_nd = -1; g_ubp_prevq = c ? c->q : 0;
    if (c && nk <= UBP_DMAX) {   // continued from c: it differs from c only where the kept writes land (insertion sort, then merge the overlapping)
        int nd = 0;
        for (int i = 0; i < nk; i++) { int e = g_ubp_idx[i]; uint32_t x = (uint32_t)((g_pend_lo[e] > lo ? g_pend_lo[e] : lo) - lo), y = (uint32_t)((g_pend_hi[e] < hi ? g_pend_hi[e] : hi) - lo);
            int j = nd++; while (j > 0 && g_ubp_d[2 * (j - 1)] > x) { g_ubp_d[2 * j] = g_ubp_d[2 * (j - 1)]; g_ubp_d[2 * j + 1] = g_ubp_d[2 * (j - 1) + 1]; j--; }
            g_ubp_d[2 * j] = x; g_ubp_d[2 * j + 1] = y; }
        int m = 0; for (int i = 0; i < nd; i++) { if (m && g_ubp_d[2 * (m - 1) + 1] >= g_ubp_d[2 * i]) { if (g_ubp_d[2 * i + 1] > g_ubp_d[2 * (m - 1) + 1]) g_ubp_d[2 * (m - 1) + 1] = g_ubp_d[2 * i + 1]; }
                                                 else { g_ubp_d[2 * m] = g_ubp_d[2 * i]; g_ubp_d[2 * m + 1] = g_ubp_d[2 * i + 1]; m++; } }
        g_ubp_nd = m; }
    if (!c) c = &g_ubpc[g_ubpc_i++ % UBP_CACHE];
    *c = (ubp_ent){lo, hi, ab.gpuAddress + o, d, g_npend, g_pend_gen, g_sbw_gen, g_ubq_tail, g_arena_gen};
    c->pq = g_ubp_prevq; c->nd = g_ubp_nd; if (g_ubp_nd > 0) memcpy(c->d, g_ubp_d, 2 * (size_t)g_ubp_nd * sizeof *g_ubp_d);
    *gpu = c->gpu; *cpu = d; g_ubp_q = g_ubq_tail; return 1;
}
void nvn_be_ubp_stats(uint64_t *made, uint64_t *reused, uint64_t *refused) { *made = g_ubp_made; *reused = g_ubp_reused; *refused = g_ubp_refused; }
void nvn_be_ubp_why(uint64_t w[5]) { memcpy(w, g_ubp_why, sizeof g_ubp_why); }
void mtl_sub_update(const void *data, uint64_t dst, uint64_t n) {
    if (!n) return;
    int pi = pend_add(dst, n, 1);
    void *db; uint64_t dof;
    if (!nvn_be_addr(dst, n, &db, &dof)) MDIE("uniform update target is in no memory pool dst=%#llx n=%#llx", (unsigned long long)dst, (unsigned long long)n);
    int defer = (enc_open() || (ubd_lazy() && !g_blit)) && g_nubd < UBD_MAX && ubd_on();
    size_t need = (n + 255u) & ~(size_t)255u;   // 256-aligned slots: a deferred update is read in place by draws as a uniform buffer
    if (!g_ubs_buf || g_ubs_off + need > g_ubs_size) {
        if (g_ubs_buf) defer_obj_release(g_ubs_buf);   // copies already encoded still reference the old block: release after this submission completes
        g_ubs_size = MAX((size_t)1 << 20, need);
        g_ubs_buf = [g_dev newBufferWithLength:g_ubs_size options:MTLResourceStorageModeShared];
        if (!g_ubs_buf) MDIE("uniform update ring allocation failed %#zx", g_ubs_size);
        res_add(g_ubs_buf); g_ubs_off = 0;
    }
    memcpy((uint8_t *)g_ubs_buf.contents + g_ubs_off, data, n);
    if (pi >= 0) { g_upd[g_nupd] = (upd_ent){dst, g_ubs_off, g_ubs_buf}; g_pend_upd[pi] = (uint32_t)++g_nupd; }
    if (defer) {
        ubd_add(dst, dst + n, g_ubs_buf.gpuAddress + g_ubs_off, g_ubs_off, g_ubs_buf); g_ubd_deferred++; ubd_dirty(dst, dst + n); }   // see ubd_add / ubd_shadow
    else enc_b_copy_buffer(blit_buf(0, 0, dst, dst + n), g_ubs_buf, g_ubs_off, (__bridge id<MTLBuffer>)db, dof, n);
    g_ubs_off += need;
}

// In-order buffer fill within the submission: all four bytes equal → fillBuffer; otherwise copied in chunks from a 64 KiB pattern buffer
void mtl_sub_fill(uint64_t dst, uint64_t n, uint32_t value) {
    if (!n) return;
    pend_add(dst, n, 3); g_mdx_epoch++;
    void *db; uint64_t dof;
    if (!nvn_be_addr(dst, n, &db, &dof)) MDIE("buffer fill address is in no memory pool dst=%#llx n=%#llx", (unsigned long long)dst, (unsigned long long)n);
    uint8_t b0 = (uint8_t)value;
    if (value == (uint32_t)b0 * 0x01010101u) { [blit_buf(0, 0, dst, dst + n) fillBuffer:(__bridge id<MTLBuffer>)db range:NSMakeRange(dof, n) value:b0]; return; }
    enum { PAT = 0x10000 }; static __strong id<MTLBuffer> pat; static uint32_t pat_v; static int pat_ok;
    if (!pat_ok || pat_v != value) { uint32_t *tmp = malloc(PAT); for (unsigned i = 0; i < PAT / 4; i++) tmp[i] = value;
        pat = [g_dev newBufferWithBytes:tmp length:PAT options:MTLResourceStorageModeShared]; free(tmp); pat_v = value; pat_ok = 1; res_add(pat); }
    for (uint64_t off = 0; off < n; off += PAT) { uint64_t k = n - off < PAT ? n - off : PAT; enc_b_copy_buffer(blit_buf(0, 0, dst + off, dst + off + k), pat, 0, (__bridge id<MTLBuffer>)db, dof + off, k); }
}

static void post(post_op o) {
    if (g_npost == g_postcap) { size_t c = g_postcap ? g_postcap * 2 : 64; if (!GROW(g_post, c * sizeof *g_post, "completion write list")) return; g_postcap = c; }   // dropped: this event / report is not written
    g_post[g_npost++] = o;
}
// GPU 等事件（NVN_EV_WAIT，hle_nvn.c nvnCommandBufferWaitEvent）。NVN：GPU 执行到这里停住，直到事件值满足条件（等于 / 回绕大于等于）。
//   本层事件值由 CPU 写：游戏的 nvnEventSignal，或 GPU 侧 SignalEvent 在所在提交完成时的回调（post kind 1）。所以：
//   ① 当前值、再按队列顺序叠上还没落地的 GPU 侧信号（本提交已录的 + 已提交未完成的，g_evs）后已满足 → 不等：这些信号在 GPU 上排在等待之前，同一队列按序执行；
//   ② 否则队列在 GPU 上等宿主共享事件 g_evw_ev 到本等待的票号（queue_wait_event，同 OP_WAIT_SYNC），CPU 不阻塞；每次事件值被写（nvn_be_event_written、
//      完成回调）按票号顺序复查，满足的前缀放行（票号单调，放行 n 即放行 ≤ n）；
//   ③ 保险：EVW_TIMEOUT_MS 内没满足就强制放行并报红一次，免得一笔永远不来的信号挂死 GPU（Metal 会把超时的命令缓冲判错）；放行后复查后面的票（已满足的跟着放）
//   ④ 跨队列：本层把游戏所有 NVN 队列按提交顺序排进同一条 Metal 队列。等待之后才录到的 GPU 侧 SignalEvent 排在等待后面，GPU 永远先到等待——在 GPU 上等就是互锁到超时
//      （11-05 时之笛 7 条队列、每帧 3 次等别的队列稍后发的信号，每帧约 1031 ms、1.41 帧/秒）。所以：录到 GPU 侧信号时，同一事件上在等的立即放行；
//      只由 GPU 侧信号写、CPU 没写过的事件之后不再在 GPU 上等（同改前）；CPU 写过的（nvnEventSignal，⑵ 的情形，极品飞车）照常等
#define EVW_MAX 64
#define EVS_MAX 512
static int g_evw_timeout_ms = 1000;
typedef struct { volatile uint32_t *val; uint32_t mode, v; uint64_t ticket; } evw_t;
typedef struct { volatile uint32_t *val; uint32_t mode, v; } evs_t;
static pthread_mutex_t g_evw_mu = PTHREAD_MUTEX_INITIALIZER;
static evw_t g_evw[EVW_MAX]; static int g_nevw;
static evs_t g_evs[EVS_MAX]; static int g_nevs, g_evs_over;   // 已录、还没在完成回调里落地的 GPU 侧事件写，按录制顺序
static uint64_t g_evw_next, g_evw_released, g_evw_waits, g_evw_forced;
static id<MTLSharedEvent> g_evw_ev;
#define EVA_MAX 256
static struct { volatile uint32_t *val; uint8_t gpu, cpu; } g_eva[EVA_MAX]; static int g_neva;   // 见过的事件地址：录过 GPU 侧信号 / CPU 写过
static uint64_t g_evw_xq, g_evw_xq_skip;   // 录到排在等待之后的 GPU 侧信号而放行的次数 / 只由 GPU 侧写的事件不等的次数
static int eva_at(volatile uint32_t *val) {   // 调用方持 g_evw_mu；表满返回 -1
    for (int i = 0; i < g_neva; i++) if (g_eva[i].val == val) return i;
    if (g_neva == EVA_MAX) return -1;
    g_eva[g_neva].val = val; g_eva[g_neva].gpu = g_eva[g_neva].cpu = 0; return g_neva++;
}
static int ev_cond(uint32_t cur, uint32_t mode, uint32_t v) { return mode == 1 ? (int32_t)(cur - v) >= 0 : cur == v; }   // NVN_EVENT_WAIT_MODE_EQUAL 0 / GEQUAL_WRAP 1
static void evw_release_locked(uint64_t upto) {   // 放行票号 ≤ upto 的等待（调用方持 g_evw_mu）
    if (upto <= g_evw_released) return;
    g_evw_released = upto; [g_evw_ev setSignaledValue:upto];
    int k = 0; for (int i = 0; i < g_nevw; i++) if (g_evw[i].ticket > upto) g_evw[k++] = g_evw[i];
    g_nevw = k;
}
static void evw_check_locked(void) {   // 按票号顺序：满足的前缀放行
    uint64_t upto = 0;
    for (int i = 0; i < g_nevw; i++) { if (!ev_cond(*g_evw[i].val, g_evw[i].mode, g_evw[i].v)) break; upto = g_evw[i].ticket; }
    if (upto) evw_release_locked(upto);
}
// ⑤ 录制时就知道写它的是 GPU 侧信号（11-05 时之笛第二十九版读档：事件第一次被等时还没提交过写它的信号，④ 的「只由 GPU 侧写」判不出来，
//   等待卡住唯一的 Metal 队列 1000 ms 超时放行；而写它的 SignalEvent 早已录在别的队列的命令缓冲里）。录制时记下，回放到等待点按 ④ 处理
void nvn_be_event_gpu_recorded(volatile uint32_t *val) {
    if (!val) return;
    pthread_mutex_lock(&g_evw_mu); int a = eva_at(val); if (a >= 0) g_eva[a].gpu = 1; pthread_mutex_unlock(&g_evw_mu);
}
void nvn_be_event_written(volatile uint32_t *val) {
    pthread_mutex_lock(&g_evw_mu); int a = val ? eva_at(val) : -1; if (a >= 0) g_eva[a].cpu = 1;
    if (g_nevw) evw_check_locked(); pthread_mutex_unlock(&g_evw_mu);
}
void mtl_sub_event(volatile uint32_t *val, uint32_t mode, uint32_t v) {
    post((post_op){1, val, mode, v, 0, 0, NULL});
    pthread_mutex_lock(&g_evw_mu); if (g_nevs < EVS_MAX) g_evs[g_nevs++] = (evs_t){val, mode, v}; else g_evs_over = 1;
    int a = eva_at(val); if (a >= 0) g_eva[a].gpu = 1;
    uint64_t upto = 0; for (int i = 0; i < g_nevw; i++) if (g_evw[i].val == val) upto = g_evw[i].ticket;   // ④ 这笔信号排在这些等待后面：在 GPU 上等不到它
    if (upto) { g_evw_xq++; static int n; if (n++ < 4) MLOG("【红】 GPU event wait on %p: its signal was recorded after the wait (another queue, all on one Metal queue here); released at once", val);
        evw_release_locked(upto); evw_check_locked(); }
    pthread_mutex_unlock(&g_evw_mu);
}
static void evs_landed(volatile uint32_t *val) {   // 完成回调落地了一笔 GPU 侧事件写：从在途表摘掉最早那笔同地址的，再复查等待
    pthread_mutex_lock(&g_evw_mu);
    for (int i = 0; i < g_nevs; i++) if (g_evs[i].val == val) { memmove(&g_evs[i], &g_evs[i + 1], (size_t)(g_nevs - i - 1) * sizeof *g_evs); g_nevs--; break; }
    if (!g_nevs) g_evs_over = 0;
    if (g_nevw) evw_check_locked();
    pthread_mutex_unlock(&g_evw_mu);
}
static void queue_wait_event(void *ev, uint64_t v);
// The event's value once the GPU-side signals already encoded have landed (holds g_evw_mu)
static uint32_t ev_now_locked(volatile uint32_t *val) { uint32_t cur = *val; for (int i = 0; i < g_nevs; i++) if (g_evs[i].val == val) cur = g_evs[i].mode == 1 ? cur + g_evs[i].v : g_evs[i].v; return cur; }
static uint32_t ev_now(volatile uint32_t *val) { pthread_mutex_lock(&g_evw_mu); uint32_t c = ev_now_locked(val); pthread_mutex_unlock(&g_evw_mu); return c; }
static int xq_may_park(const uint8_t *p, volatile uint32_t *val, uint32_t mode, uint32_t v);   // nvn_xqueue.inc
static volatile uint32_t *g_xq_pval; static uint32_t g_xq_pmode, g_xq_pv; static int g_xq_unwind;
// next = the operation after the wait. Returns 1 when the wait parks the queue being replayed (nvn_xqueue.inc): the caller stops replaying and unwinds
static int ev_wait(volatile uint32_t *val, uint32_t mode, uint32_t v, const uint8_t *next) {   // 回放 OP_SIGNAL_EVENT + NVN_EV_WAIT
    if (!val) return 0;
    pthread_mutex_lock(&g_evw_mu);
    uint32_t cur = ev_now_locked(val);
    uint64_t ticket = 0;
    int a = eva_at(val);
    if (!g_evs_over && !ev_cond(cur, mode, v) && a >= 0 && g_eva[a].gpu && !g_eva[a].cpu) {   // ④ 只由 GPU 侧信号写的事件：写它的信号还在后面的提交里，不在 GPU 上等
        if (xq_may_park(next, val, mode, v)) { g_xq_pval = val; g_xq_pmode = mode; g_xq_pv = v; g_xq_unwind = 1; pthread_mutex_unlock(&g_evw_mu); return 1; }   // 停住这条队列，等那笔信号回放后再接着回放（nvn_xqueue.inc）
        g_evw_xq_skip++; static int n; if (!n++) MLOG("GPU event waits: event %p is written only by GPU-side signals recorded after its waits (another queue); these waits do not stall the queue", val);
    } else if (!g_evs_over && !ev_cond(cur, mode, v)) {
        if (!g_evw_ev) g_evw_ev = [g_dev newSharedEvent];
        if (g_nevw < EVW_MAX) { ticket = ++g_evw_next; g_evw[g_nevw++] = (evw_t){val, mode, v, ticket}; g_evw_waits++; }
        else { static int n; if (!n++) MLOG("【红】 GPU event waits: more than %d pending at once; this one does not wait", EVW_MAX); }
    }
    pthread_mutex_unlock(&g_evw_mu);
    if (!ticket) return 0;
    queue_wait_event((__bridge void *)g_evw_ev, ticket);
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)g_evw_timeout_ms * 1000000), dispatch_get_global_queue(QOS_CLASS_DEFAULT, 0), ^{
        pthread_mutex_lock(&g_evw_mu);
        if (g_evw_released < ticket) { g_evw_forced++; static int n; if (n++ < 4) MLOG("【红】 GPU event wait ticket %llu (event %p, mode %u, value %u, now %u): not satisfied after %d ms; released so the GPU does not hang",
                                                                                     (unsigned long long)ticket, val, mode, v, *val, g_evw_timeout_ms);
            evw_release_locked(ticket); evw_check_locked(); }
        pthread_mutex_unlock(&g_evw_mu);
    });
    return 0;
}
static void ts_clk(void);
void mtl_sub_counter(uint64_t addr, uint32_t type) { sbw_note(addr, 16, SBW_REPORT); post((post_op){2, NULL, 0, 0, addr, type, NULL, g_seg}); ts_clk(); }
void mtl_counter_stats(uint64_t rep[32], uint64_t rst[32]) { memcpy(rep, g_cnt_report, sizeof g_cnt_report); memcpy(rst, g_cnt_reset, sizeof g_cnt_reset); }

// Counter timestamps (19.2 MHz) are taken from the guest clock (hle_os.c guest_ns, the same source as svc GetSystemTick / cntpct): on hardware GPU timestamps and the CPU counter share one timebase, and games compare them.
// They used to come from CLOCK_MONOTONIC, which keeps running while the Mac sleeps while the guest clock (mach_absolute_time) does not, so the two differed by the sleep time; once timestamps were converted to ns, Mario halved its frame rate. In graphics unit tests guest_ns is a weak definition returning 0; fall back to the monotonic clock
uint64_t guest_ns(void);
static uint64_t gpu_ticks(void) { uint64_t g = guest_ns(); if (!g) { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); g = (uint64_t)t.tv_sec * 1000000000ull + t.tv_nsec; } return g * 12 / 625; }
// Counter timestamps by segment (profile gpu_timestamps segment; DM_NVN_GPU_TS=segment / submission overrides it). On hardware a timestamp report is written when the GPU reaches it, so two reports of one submission bracket the GPU work between them.
// The host writes all reports of a submission in its completion handler; with one time for all of them a game that measures its GPU time that way reads 0 (Breath of the Wild: frame-interval controller and dynamic resolution).
// In segment mode a report takes the GPU time of the segment it was encoded in (sub_cut): TIMESTAMP_TOP (0x10) that segment's GPU start, other types its GPU end. The writes stay in the last segment's handler, before the fence,
// so a game that waits for the fence reads one submission's reports together; a segment whose feedback has not arrived by then takes the last segment's times
#define SEG_CLK_N 1024
struct seg_clk { _Atomic int refs; _Atomic uint64_t t[SEG_CLK_N][2]; uint32_t nb; uint16_t b[SEG_CLK_N + 1]; };   // per submission (g_sclk, allocated at its first cut or report): guest ns of each cut segment's GPU start / end (0 = no feedback yet); b: with ts_on, the timestamp heap slots of the segment boundaries, segment k from b[k] to b[k + 1]
static int seg_ts(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_GPU_TS"); v = e && *e ? !strcmp(e, "segment") : DM_GAME_GPU_TS_SEGMENT; MLOG("counter timestamps: %s (profile key gpu_timestamps; DM_NVN_GPU_TS=segment / submission)", v ? "GPU start / end time of their segment" : "one time for the whole submission"); } return v; }
static void seg_clk_put(seg_clk *c) { if (c && atomic_fetch_sub(&c->refs, 1) == 1) free(c); }
static uint64_t gpu_s_guest_ns(double s) {   // a feedback GPU time (seconds on the mach absolute time base) on the guest clock; 0 when unknown
    static mach_timebase_info_data_t tb; if (!tb.denom) mach_timebase_info(&tb);
    uint64_t g = guest_ns(), now = tb.denom ? mach_absolute_time() * tb.numer / tb.denom : 0, at = (uint64_t)(s * 1e9);
    if (s <= 0 || !g || at > now || now - at > g) return 0;
    return g - (now - at);
}
static uint64_t rep_ticks(const post_op *o, seg_clk *sc, uint32_t last, uint64_t c0, uint64_t c1) {   // the time a counter report records (19.2 MHz); c0 / c1: the last segment's GPU start / end on the guest clock
    int top = o->type == 0x10; uint64_t ns = 0;
    uint32_t bi = o->seg + !top;
    if (sc && bi < sc->nb && g_ts_heap) if (@available(macOS 26.0, iOS 26.0, *)) {   // the boundary's own GPU timestamp, on the guest clock through a pair of samples: how long ago it was on the GPU's clock, back from the guest clock now
        NSData *d = [g_ts_heap resolveCounterRange:NSMakeRange(sc->b[bi], 1)]; const uint64_t *e = d.bytes; MTLTimestamp cpu = 0, gpu = 0; [g_dev sampleTimestamps:&cpu gpuTimestamp:&gpu];   // e: a timestamp heap entry, one 64-bit GPU timestamp
        static double scale; if (!scale) { uint64_t hz = [g_dev queryTimestampFrequency]; scale = hz ? 1e9 / (double)hz : 1; }
        uint64_t g = guest_ns(); if (!g) { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); g = (uint64_t)t.tv_sec * 1000000000ull + t.tv_nsec; }   // as gpu_ticks
        if (e && d.length >= sizeof *e && *e) { double at = (double)*e * scale, ago = (double)gpu - at; if (ago >= 0 && ago < 2e9 && ago < (double)g) ns = g - (uint64_t)ago; }   // an entry counts at queryTimestampFrequency, a sample in ns (upstream, measured on Apple GPUs)
        if (ns) return ns * 12 / 625;
    }
    if (sc && o->seg < last && o->seg < SEG_CLK_N) ns = atomic_load(&sc->t[o->seg][!top]);
    if (!ns) ns = top ? c0 : c1;
    return ns ? ns * 12 / 625 : gpu_ticks();
}

// ---------- Boot instrumentation (DM_BOOTPROF=1): metallib loading, pipeline creation (both happen synchronously during replay on the submit thread), texture upload, first-frame present ----------
static uint64_t bp_now(void) { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return (uint64_t)t.tv_sec * 1000000000ull + t.tv_nsec; }
static uint64_t g_bp_t0;   // Time of process start (when this module is loaded)
__attribute__((constructor)) static void bp_t0(void) { g_bp_t0 = bp_now(); }
static int bootprof(void) { static int v = -1; if (v < 0) v = getenv("DM_BOOTPROF") != NULL; return v; }
static uint64_t g_bp_lib_n, g_bp_lib_ns, g_bp_lib_wait_ns, g_bp_pso_n, g_bp_pso_ns, g_bp_up_bytes, g_bp_first_present;
static uint64_t g_up_total_ns;   // Cumulative upload time (same source as the per-frame @upload_ms)
// S2Arm first-encounter readout (graphics/nvn/fe_stat.h; 10-29, after the direct linked stand-ins were dropped): every pipeline the submit thread gets on a cache miss
//   (built here or waited for from the background, the same spots that count g_bp_pso_n / the long-frame line's "new pipelines"), counted after the autoplay MARK and
//   while a prewarm past DM_PSO_PREPARE_MAX_MS goes on in the background; printed with the resource counts (mtl_res_counts: at the end of the run, and every 30 s with the address watch when it finds the hook)
#include "../../fe_stat.h"
int s2a_ap_marked(void);
__attribute__((weak)) int s2a_ap_marked(void) { return 0; }   // native ap_host.c: 1 after the first MARK; graphics unit tests without the host have none
static fe_stat g_fe; static pthread_mutex_t g_fe_mu = PTHREAD_MUTEX_INITIALIZER;
static void fe_sync_note(uint64_t ns) { int m = s2a_ap_marked(); pthread_mutex_lock(&g_fe_mu); fe_note(&g_fe, ns, m); pthread_mutex_unlock(&g_fe_mu); }
// ---------- Per-frame GPU time aggregation ----------
#define GRING 1024
static struct { _Atomic uint64_t frame, ns, t0, t1; _Atomic int pending; } g_gpu[GRING];   // t0 / t1: the frame's earliest GPUStart / latest GPUEnd (mach absolute time, ns)
static _Atomic uint64_t g_cur_frame;
// ---------- Same-process alternating measurement (DM_NVN_UB, off by default: without the environment variable the code below only adds one 'is it enabled' check) ----------
// On a hot real device the system keeps adjusting power / frequency, and segment comparison (segments A and B each run for a minute) cannot resolve differences of <10%; within the same run, toggle by phase in turn and take differences of adjacent phase pairs, so the drift cancels.
// DM_NVN_UB="name=item,item;name=item", one phase every DM_NVN_UB_N frames (default 180, minimum 60): even phases = baseline (nothing changed), odd phases take one category in turn. Each item of a category:
//   @set:<global variable name>=<value>   on entering the phase set this int global variable to the value, on leaving restore it (address found by symbol name; switches to be used on a real device must have a line added to the registration table below)
//   <fragment shader key prefix> or *   the phase drops all draws of these fragment shaders (the picture will be wrong; it only measures 'how much this kind of draw is worth'; a nearly idle category needs a round of its own)
// Readings: each phase discards its first 45 frames (transition + present lag); for the remaining frames, the mean of the actual present interval (same source as perf.txt) and the frame counts in the three buckets 16.7 / 25 / ≥33 ms, one log line "UB present".
static int g_ub_n = -1, g_ub_N = 180; static _Atomic int g_ub_cur = -1; static char g_ub_name[16][16], g_ub_keys[16][16][48]; static int g_ub_nk[16];
static _Atomic int g_ubp_on, g_ubp_c[4]; static _Atomic uint64_t g_ubp_sum_us;
void nvn_be_ub_present(double iv) {   // Called once per frame by the present thread: actual present interval in ms (−1 = dropped, 0 = no reading)
    if (!atomic_load(&g_ubp_on) || iv == 0) return;
    if (iv < 0) { atomic_fetch_add(&g_ubp_c[3], 1); return; }
    atomic_fetch_add(&g_ubp_c[iv <= 20.8 ? 0 : iv <= 29.2 ? 1 : 2], 1); atomic_fetch_add(&g_ubp_sum_us, (uint64_t)(iv * 1000));
}
// Registered runtime switches: name → address. Main-program symbols of an iOS release build are not in the dynamic symbol table and dlsym cannot find them (in the first real-device round all four categories were "global variable not found" and the whole round was wasted),
// so a switch to be measured on a real device must have a line added here; on Mac / in unit tests unregistered ones are still looked up by symbol name.
static int *ub_var(const char *nm) {
    extern int g_dm_present_link;
    static const struct { const char *n; int *p; } t[] = { {"g_dm_present_link", &g_dm_present_link} };
    for (size_t i = 0; i < sizeof t / sizeof t[0]; i++) if (!strcmp(nm, t[i].n)) return t[i].p;
    return dlsym(RTLD_DEFAULT, nm);
}
static void ub_frame(uint64_t f) {
    if (g_ub_n < 0) { g_ub_n = 0; const char *e = getenv("DM_NVN_UB"), *n = getenv("DM_NVN_UB_N"); if (n && atoi(n) >= 60) g_ub_N = atoi(n);
        for (const char *q = e; q && *q && g_ub_n < 16; ) { const char *eq = strchr(q, '='), *end = strchr(q, ';'); if (!end) end = q + strlen(q); if (!eq || eq > end) break;
            int c = g_ub_n++; size_t l = (size_t)(eq - q); if (l > 15) l = 15; memcpy(g_ub_name[c], q, l);
            for (const char *k = eq + 1; k < end && g_ub_nk[c] < 16; ) { size_t kl = 0; while (k + kl < end && k[kl] != ',') kl++; size_t cl = kl > 47 ? 47 : kl; memcpy(g_ub_keys[c][g_ub_nk[c]++], k, cl); k += kl; if (k < end) k++; }
            q = *end ? end + 1 : end; }
        if (g_ub_n) MLOG("DM_NVN_UB: %d categories, %d frames per phase (measured alternately in one process; phases that drop draws render wrong)", g_ub_n, g_ub_N); }
    if (!g_ub_n) return;
    uint64_t ph = f / (uint64_t)g_ub_N, r = f % (uint64_t)g_ub_N;
    if (r == 45) { for (int i = 0; i < 4; i++) atomic_store(&g_ubp_c[i], 0); atomic_store(&g_ubp_sum_us, 0); atomic_store(&g_ubp_on, 1); }
    if (r != 0) return;
    if (f && atomic_load(&g_ubp_on)) { atomic_store(&g_ubp_on, 0); uint64_t pp = ph - 1; int pc = (pp & 1) ? (int)((pp / 2) % (uint64_t)g_ub_n) : -1;
        int c0 = atomic_load(&g_ubp_c[0]), c1 = atomic_load(&g_ubp_c[1]), c2 = atomic_load(&g_ubp_c[2]), c3 = atomic_load(&g_ubp_c[3]), n_ = c0 + c1 + c2;
        MLOG("UB present %llu %s frames %d mean %.3f ms 2 ticks %d 3 ticks %d 4+ ticks %d discarded %d", (unsigned long long)pp, pc < 0 ? "base" : g_ub_name[pc], n_, n_ ? atomic_load(&g_ubp_sum_us) / 1000.0 / n_ : 0.0, c0, c1, c2, c3); }
    int nc = (ph & 1) ? (int)((ph / 2) % (uint64_t)g_ub_n) : -1;
    static int *sp[16]; static int sv[16], ns;   // Variables set by the previous phase: restore first
    for (int i = 0; i < ns; i++) *sp[i] = sv[i]; ns = 0;
    for (int i = 0; nc >= 0 && i < g_ub_nk[nc] && ns < 16; i++) { const char *k = g_ub_keys[nc][i]; if (strncmp(k, "@set:", 5)) continue;
        char nm[48]; const char *eq = strchr(k, '='); if (!eq) continue; size_t l = (size_t)(eq - (k + 5)); if (l >= sizeof nm) continue; memcpy(nm, k + 5, l); nm[l] = 0;
        int *a_ = ub_var(nm); static int bad, ok;
        if (!a_) { if (bad++ < 8) MLOG("【红】 DM_NVN_UB: global variable not found: %s (on a device, register it in the ub_var table first)", nm); continue; }
        sp[ns] = a_; sv[ns] = *a_; ns++; *a_ = atoi(eq + 1); if (ok++ < 8) MLOG("DM_NVN_UB: %s = %d (was %d)", nm, atoi(eq + 1), sv[ns - 1]); }
    atomic_store(&g_ub_cur, nc);
}
static int ub_skip(const char *key) {   // Whether this phase should drop draws of this fragment shader
    int uc = atomic_load(&g_ub_cur); if (uc < 0) return 0;
    for (int i = 0; i < g_ub_nk[uc]; i++) { const char *k = g_ub_keys[uc][i]; if (k[0] == '@') continue; if (k[0] == '*' || !strncmp(key, k, strlen(k))) return 1; }
    return 0;
}
void nvn_be_set_frame(uint64_t f) { atomic_store(&g_cur_frame, f); if (g_ub_n) ub_frame(f); }
// GPU timing registration: gpu_tag_begin(frame) before commit, gpu_tag_done(frame, GPU start, GPU end) on completion (seconds on the CACurrentMediaTime base).
// Old-queue command buffers go through gpu_tag_f; the Metal 4 main submission backfills in the feedback of nvn_be_sub_commit (when switching to Metal 4 all the call sites were lost and the GPU column of the timing line became empty)
static double gpu_tag_begin(uint64_t f) {   // 返回提交时刻（CACurrentMediaTime）：调用方原样交给 gpu_tag_done，GPU 不可能早于它开始
    unsigned k = f % GRING;
    if (atomic_load(&g_gpu[k].frame) != f) { atomic_store(&g_gpu[k].frame, f); atomic_store(&g_gpu[k].ns, 0); atomic_store(&g_gpu[k].pending, 0); atomic_store(&g_gpu[k].t0, UINT64_MAX); atomic_store(&g_gpu[k].t1, 0); }
    atomic_fetch_add(&g_gpu[k].pending, 1);
    return CACurrentMediaTime();
}
// A frame whose command buffers keep the GPU busy longer than this in all is no longer usable: the run stops (mtl_gpu_halt: GPU safe stop) before the driver's timeout recovery takes over
//   (10-31: the Mac's kernel panicked in the GPU driver's event machine after runs whose frames took 1.5-3.3 s of GPU)
#define S2A_GPU_FRAME_MAX_MS 1000
// 开始时间早于提交时刻（11-11 #647：Mac mini M4 / macOS 27.2.1，Metal 4，23 局都以本门收局，停前每帧整帧 16–24 ms 照常出帧，记到的帧 GPU
//   每帧线性涨约一帧时长、涨过 1 秒——某个提交回报的 GPUStartTime 停在过去，跨度被一路拉长；驱动没报任何命令缓冲错误）：GPU 不可能在提交之前开始干这份活，
//   早于提交时刻 sub 的开始按 sub 算，计数并打黄行（时间戳原样写出；本机 macOS 26.4 / 门禁机 27.0.1 的探针 900 次提交 0 次，是防线不是已证根因）。
//   主因：同一队列上的提交按序执行，回报的跨度里含排队等前面几份的时间——一帧切成多段提交（每 64 笔一段）时各段跨度层层包含，相加就重复计；
//   GPU 跟不上 CPU（作者 M4：帧 GPU 中位 21.8 ms，屏上约 20 帧/秒）时积压越深跨度越长。帧 GPU 时间改记每份的独占时间：
//   结束 − max(开始, 本队列上一份结束)，每个时刻在一条队列上只算一次。真挂死（GPU 真跑满 1 秒以上）独占时间同样过门，照停、不更慢
static _Atomic uint64_t g_gpu_start_early;
static _Atomic uint64_t g_gpu_qend[2];   // 各队列已回报的最晚 GPU 结束（ns）：0 = 主回放 / 分段提交（g_q4 / g_q3），1 = 旧队列（gpu_tag_f）
uint64_t mtl_gpu_start_early(void) { return atomic_load(&g_gpu_start_early); }
static void gpu_tag_done(uint64_t f, int qi, double sub, double g0, double g1) {
    unsigned k = f % GRING;
    if (atomic_load(&g_gpu[k].frame) != f) return;
    if (g0 > 0 && sub > 0 && g0 < sub - 0.001) {
        uint64_t n = atomic_fetch_add(&g_gpu_start_early, 1);
        if (n < 4 || !(n & (n - 1))) MLOG("【黄】 GPU 开始时间早于提交 %.1f ms：帧 %llu 提交 %.3f，GPU %.3f→%.3f；按提交时刻算（第 %llu 次）",
            (sub - g0) * 1e3, (unsigned long long)f, sub, g0, g1, (unsigned long long)n + 1);
        g0 = sub;
    }
    double d = g1 - g0;
    // 结束时间不可能晚于现在（GPUStart / GPUEnd 与 CACurrentMediaTime 同一时基）。11-09 M1 Pro 时之笛 S2：切出窗口再切回后，一个命令缓冲回报的跨度算出 6147890790964 ms（约 195 年），
    //   这道 1 秒门把它当成 GPU 挂死、安全停收局。这样的时间戳只打红行、不计进本帧 GPU 时间；真挂死的跨度结束在过去，照判
    if (d > 0 && g0 > 0 && g1 > CACurrentMediaTime() + 1.0) {
        static _Atomic int n; int k = atomic_fetch_add(&n, 1);
        if (k < 4 || !(k & (k - 1))) MLOG("【红】 GPU 时间戳不可能（结束在现在之后）：帧 %llu GPU %.3f→%.3f，现在 %.3f；不计进本帧 GPU 时间、不判挂死（第 %d 次）",
            (unsigned long long)f, g0, g1, CACurrentMediaTime(), k + 1);
        d = 0;
    }
    if (d > 0 && g0 > 0) {   // a command buffer can complete with no start time (0, while a movie's frames upload each frame in Big Brain Academy: Brain vs. Brain), and its span would be the whole clock
        uint64_t s0 = (uint64_t)(g0 * 1e9), s1 = (uint64_t)(g1 * 1e9), v;
        _Atomic uint64_t *qe = &g_gpu_qend[qi & 1]; uint64_t prev = atomic_load(qe);
        while (s1 > prev && !atomic_compare_exchange_weak(qe, &prev, s1)) {}
        uint64_t from = s0 > prev ? s0 : prev, excl = s1 > from ? s1 - from : 0;   // 本队列上一份结束之前的那段是排队，不算
        uint64_t busy = atomic_fetch_add(&g_gpu[k].ns, excl) + excl;
        for (v = atomic_load(&g_gpu[k].t0); s0 < v && !atomic_compare_exchange_weak(&g_gpu[k].t0, &v, s0);) {}
        for (v = atomic_load(&g_gpu[k].t1); s1 > v && !atomic_compare_exchange_weak(&g_gpu[k].t1, &v, s1);) {}
        if (busy > S2A_GPU_FRAME_MAX_MS * 1000000ull) { char w[120]; snprintf(w, sizeof w, "frame %llu kept the GPU busy %.0f ms (limit %d ms)", (unsigned long long)f, busy / 1e6, S2A_GPU_FRAME_MAX_MS); mtl_gpu_halt(w); }
    }
    atomic_fetch_sub(&g_gpu[k].pending, 1);
}
static void gpu_tag_f(id<MTLCommandBuffer> cb, uint64_t f) { double sub = gpu_tag_begin(f); [cb addCompletedHandler:^(id<MTLCommandBuffer> c) { gpu_tag_done(f, 1, sub, c.GPUStartTime, c.GPUEndTime); }]; }
void gpu_tag(id<MTLCommandBuffer> cb) { gpu_tag_f(cb, atomic_load(&g_cur_frame)); }
double nvn_be_gpu_ms(uint64_t f) {
    unsigned k = f % GRING;
    if (atomic_load(&g_gpu[k].frame) != f || atomic_load(&g_gpu[k].pending)) return -1;
    return atomic_load(&g_gpu[k].ns) / 1e6;
}
int nvn_be_gpu_span(uint64_t f, uint64_t *t0, uint64_t *t1) {
    unsigned k = f % GRING;
    if (atomic_load(&g_gpu[k].frame) != f || atomic_load(&g_gpu[k].pending)) return 0;
    *t0 = atomic_load(&g_gpu[k].t0); *t1 = atomic_load(&g_gpu[k].t1);
    return *t1 >= *t0 && *t1;
}
static void rp_flush(void);
static void rt_keep_state(void);
static void ghost_finish_submission(void);
static void alias_dead_views(void);
static const char *cctx_snap(void);   // What is in this submission (printed into the failure line on error; defined before nvn_be_exec)
static void lc_land(void); static int g_nlc;   // lazy clears waiting (lc_push; fb_prepare lands them before a feedback read)
static _Atomic int g_seg_inflight;   // main command buffers committed and not reported back yet (sub_cut)
// 诊断开关 DM_TEST_GPU_HANG=<帧号>（只为验证 GPU 安全停，玩家包不设）：到这一帧往旧队列交一个死循环计算核，人为造出本进程的 GPU 挂死；
//   驱动恢复时报 Hang / Timeout，之后同进程的提交被牵连 —— 同 11-07 测试设备2 金刚那局，但可控、能在 Duo 上复现
static void gpu_hang_inject(void) {
    static int at = -1; static _Atomic int done;
    if (at < 0) { const char *e = getenv("DM_TEST_GPU_HANG"); at = e ? atoi(e) : 0; if (at > 0) MLOG("DM_TEST_GPU_HANG=%d: frame %d gets an endless compute kernel (deliberate GPU hang, diagnostics only)", at, at); }
    if (at <= 0 || atomic_load(&g_cur_frame) < (uint64_t)at || atomic_exchange(&done, 1)) return;
    NSError *e = nil;
    id<MTLLibrary> lib = [g_dev newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal;\n"
        "kernel void spin(device atomic_uint *p [[buffer(0)]]) { uint n = 0; while (atomic_load_explicit(p, memory_order_relaxed) != 0x5a5a5a5au) n++; atomic_store_explicit(p + 1, n, memory_order_relaxed); }\n" options:nil error:&e];
    id<MTLComputePipelineState> ps = lib ? [g_dev newComputePipelineStateWithFunction:[lib newFunctionWithName:@"spin"] error:&e] : nil;
    if (!ps) { MLOG("【红】 DM_TEST_GPU_HANG: cannot build the endless kernel: %s", e.localizedDescription.UTF8String); return; }
    id<MTLBuffer> b = [g_dev newBufferWithLength:16 options:MTLResourceStorageModeShared]; memset(b.contents, 0, 16);
    id<MTLCommandBuffer> cb = [g_q commandBuffer]; id<MTLComputeCommandEncoder> ce = [cb computeCommandEncoder];
    [ce setComputePipelineState:ps]; [ce setBuffer:b offset:0 atIndex:0]; [ce dispatchThreads:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(1, 1, 1)]; [ce endEncoding];
    uint64_t f = atomic_load(&g_cur_frame);
    [cb addCompletedHandler:^(id<MTLCommandBuffer> c) { if (c.error && !mtl_gpu_cb_error(c.error, "DM_TEST_GPU_HANG", f)) MLOG("【红】 DM_TEST_GPU_HANG: the endless kernel ended with a non-hang error: %s", c.error.description.UTF8String); else if (!c.error) MLOG("【红】 DM_TEST_GPU_HANG: the endless kernel completed without error"); }];
    MLOG("DM_TEST_GPU_HANG: frame %llu, committing the endless kernel", (unsigned long long)f);
    cb_put(cb);
}
uint64_t nvn_be_sub_commit(void) {
    gpu_hang_inject();
    lc_land();   // clears still waiting (the command list ends with them)
    defer_fallback();   // Deferred merged pass: at the end of the submission there are still P draws not replayed (the normal path never gets here)
    rp_flush(); ubd_land();
    rt_keep_state();   // bound descriptors outlive the command records consumed by this submission
    g_ts_pend = -1;   // nothing after it: the last segment's end is the command buffer's own (rep_ticks)
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    up_flush();
    g_cut_copy = 0;
    ghost_finish_submission();   // before the fence is taken: what it drops is released behind this submission
    alias_dead_views();   // likewise for the texture-ID views of textures dropped as overwritten
    uint64_t fence = ++g_fence;
    rc_commit(fence);
    gw_commit(fence);
    if (g_vis_ring_i >= 0) g_vis_ring[g_vis_ring_i].fence = fence;
    // CPU-visible effects after completion: copy the op table into the callback
    int n = g_npost; post_op *ops = n ? malloc(n * sizeof *ops) : NULL;
    if (n) memcpy(ops, g_post, n * sizeof *ops);
    NSArray<dispatch_block_t> *commit_blocks = [g_commit_blocks copy];
    NSArray<NSString *> *qsus = quar_take();   // this commit's suspects for a GPU error (quar_fault)
    id o = fb_new();
    atomic_fetch_add(&g_seg_inflight, 1);
    fb_add(o, ^(id f) { (void)f; atomic_fetch_sub(&g_seg_inflight, 1); for (dispatch_block_t block in commit_blocks) block(); });
    uint64_t gpu_f = atomic_load(&g_cur_frame); double gpu_sub = gpu_tag_begin(gpu_f);
    NSString *cctx = @(cctx_snap());
    seg_clk *sc = g_sclk; uint32_t seg_last = g_seg; g_sclk = NULL;
    fb_add(o, ^(id<MTL4CommitFeedback> cb) {
        gpu_tag_done(gpu_f, 0, gpu_sub, cb.GPUStartTime, cb.GPUEndTime);
        uint64_t c0 = 0, c1 = 0; if (seg_ts()) { c0 = gpu_s_guest_ns(cb.GPUStartTime); c1 = gpu_s_guest_ns(cb.GPUEndTime); }
        if (cb.error) { atomic_store(&g_last_commit_error, 1); atomic_fetch_add(&g_commit_error_n, 1); if (mtl_gpu_halted()) mtl_gpu_cb_error(cb.error, "main replay", fence); else { static int n, nv; int victim = [cb.error.description containsString:@"InnocentVictim"]; if (!victim) quar_fault(qsus, cb.error); if (victim ? nv++ < 1 : n++ < 8) MLOG("【红】 command buffer error details fence=%llu: %s | GPU %.3f→%.3f", (unsigned long long)fence, cb.error.description.UTF8String, cb.GPUStartTime, cb.GPUEndTime); if (!victim) MLOG("【红】 state of the failed submission fence=%llu: %s", (unsigned long long)fence, cctx.UTF8String); MLOG("【红】 command buffer execution error: %s", cb.error.localizedDescription.UTF8String); mtl_gpu_cb_error(cb.error, "main replay", fence); s2a_direct_gpu_error(cb.error.localizedDescription.UTF8String); } }
        for (int i = 0; i < n; i++) {
            if (ops[i].kind == 1) { if (ops[i].mode == 1) *ops[i].val += ops[i].v; else *ops[i].val = ops[i].v; evs_landed(ops[i].val); }
            else if (ops[i].kind == 3) {   // Samples passed: the sum of all slots since the reset (the folded part + the slots not yet completed at the report)
                vis_list *l = ops[i].vis; uint64_t sum = l->base;
                for (int k = 0; k < l->n; k++) { sum += ((const uint64_t *)((__bridge id<MTLBuffer>)l->s[k].buf).contents)[l->s[k].slot]; CFRelease(l->s[k].buf); }
                free(l); uint64_t rec[2] = {sum, gpu_ticks()}; memcpy((void *)ops[i].addr, rec, sizeof rec);
            }
            else { uint64_t t = rep_ticks(&ops[i], sc, seg_last, c0, c1), rec[2] = {(ops[i].type == 0 || ops[i].type == 0x10) && !DM_GAME_RENDER_COND ? t : 0, t}; memcpy((void *)ops[i].addr, rec, sizeof rec); }   // render_cond: a timestamp report's counter field is 0, as on the GPU (see rc_value)
        }
        free(ops); seg_clk_put(sc);
        pthread_mutex_lock(&g_mu); if (fence > g_done) g_done = fence; pthread_cond_broadcast(&g_cv); pthread_mutex_unlock(&g_mu);
        defer_drain();
    });
    void arena_commit(uint64_t fence); arena_commit(fence);
    res_commit();
    if ((g_gp_state == 1 && !gp_active()) || g_gp_state == 3) { int gn = g_gp_n, gd = g_gp_drop; gp_lab *gl = malloc(sizeof(gp_lab) * (gn ? gn : 1)); memcpy(gl, g_gp_lab, sizeof(gp_lab) * gn); uint64_t gf = g_gp_frame; g_gp_state = 2;
        fb_add(o, ^(id<MTL4CommitFeedback> f) { (void)f; gp_report(gn, gd, gl, gf); }); }
    if (g_m3) { rec_commit_m3(g_cb, o, g_ev, fence, 1); rec_drain(); }   // the handlers and the signal go with the commit record; the encode thread makes them on the real buffer
    else {
        [g_cb endCommandBuffer];
        rec_commit(g_cb, o);
        rec_signal(g_ev, fence);
        rec_drain();
    }
    g_alloc_fence[g_alloc_cur] = fence;
    main_barrier_reset(); g_cb = nil;
    g_commit_blocks = nil;
    objc_autoreleasePoolPop(g_sub_pool); g_sub_pool = NULL;
    wd_sub_end();
    return fence;
}

uint64_t nvn_be_last_fence(void) { return g_fence; }
int mtl_last_commit_error(void) { return atomic_load(&g_last_commit_error); }

int nvn_be_wait(uint64_t fence, uint64_t timeout_ns) {
    struct timespec dl; clock_gettime(CLOCK_REALTIME, &dl);
    uint64_t ns = (uint64_t)dl.tv_nsec + (timeout_ns > 3600000000000ull ? 3600000000000ull : timeout_ns);
    dl.tv_sec += ns / 1000000000ull; dl.tv_nsec = ns % 1000000000ull;
    pthread_mutex_lock(&g_mu);
    int r = 0, blk = g_done < fence; if (blk) { pthread_mutex_unlock(&g_mu); DM_BLOCK_BEGIN(); pthread_mutex_lock(&g_mu); }
    while (g_done < fence && !dm_gfx_session_stopping()) if ((r = pthread_cond_timedwait(&g_cv, &g_mu, &dl))) break;
    int ok = g_done >= fence;
    pthread_mutex_unlock(&g_mu);
    if (blk) DM_BLOCK_END();
    return ok;
}

// ---------- 跨队列同步（GL 层 ⇄ NVN，nvnSyncCreateGLSync / nvnSyncInitializeFromFencedGLSync）与 GPU 错误等待（nvnDeviceWaitForError） ----------
void *nvn_be_fence_event(void) { mtl_init(); return (__bridge void *)g_ev; }   // NVN 提交的共享事件：值 = 已完成的栅栏号（提交时 signal）
// NVN 队列在 GPU 上等别的队列的共享事件到 v：此后提交到本层队列的全部工作（主命令缓冲、上传批）都排在它后面。先等录制线程把已录的提交交出去，再下等待：
//   Metal 4 是队列级 waitForEvent；Metal 3 是只含一条 encodeWaitForEvent 的命令缓冲（同一队列后续命令缓冲都被它挡住，11-01 本机实测）。此前还没提交的工作也会一起等（只多等不少等）
static void queue_wait_event(void *ev, uint64_t v) {   // the wait itself; the replay calls it while encoding a submission (OP_WAIT_SYNC), whose command buffer commits after it
    id<MTLSharedEvent> e = (__bridge id<MTLSharedEvent>)ev;
    if (e.signaledValue >= v) return;
    if (mtl_gpu_halted()) return;   // GPU 安全停后不再往队列放东西
    if (g_m3) { id<MTLCommandBuffer> cb = m3_cb(); [cb encodeWaitForEvent:e value:v]; [cb commit]; }
    else [g_q4 waitForEvent:e value:v];
}
void nvn_be_queue_wait_event(void *ev, uint64_t v) {
    if (!ev) return;
    mtl_init(); rec_drain();
    queue_wait_event(ev, v);
}
// CPU 上等别的队列的共享事件到 v（最多 timeout_ns）；返回 1 = 已到
int nvn_be_event_wait(void *ev, uint64_t v, uint64_t timeout_ns) {
    if (!ev) return 1;
    id<MTLSharedEvent> e = (__bridge id<MTLSharedEvent>)ev; uint64_t t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    while (e.signaledValue < v && !dm_gfx_session_stopping()) {
        uint64_t el = clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0; if (el >= timeout_ns) break;
        uint64_t ms = (timeout_ns - el) / 1000000 + 1; [e waitUntilSignaledValue:v timeoutMS:ms > 50 ? 50 : ms];
    }
    return e.signaledValue >= v;
}
// 等到出现比 *seen 新的 GPU 执行错误（命令缓冲报错）或超时；有新错误返回 1 并把 *seen 推到当前累计数
int nvn_be_wait_error(uint64_t *seen, uint64_t timeout_ns) {
    uint64_t t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    for (;;) {
        uint64_t n = atomic_load(&g_commit_error_n); if (n > *seen) { *seen = n; return 1; }
        uint64_t el = clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0; if (el >= timeout_ns || dm_gfx_session_stopping()) return 0;
        uint64_t step = timeout_ns - el > 100000000ull ? 100000000ull : timeout_ns - el;   // 每个提交完成都会广播 g_cv；至多 100 ms 自查一次（段命令缓冲的报错不广播）
        struct timespec dl; clock_gettime(CLOCK_REALTIME, &dl); uint64_t ns = (uint64_t)dl.tv_nsec + step; dl.tv_sec += ns / 1000000000ull; dl.tv_nsec = ns % 1000000000ull;
        pthread_mutex_lock(&g_mu); if (atomic_load(&g_commit_error_n) <= *seen) pthread_cond_timedwait(&g_cv, &g_mu, &dl); pthread_mutex_unlock(&g_mu);
    }
}
static void mtl_finish_gpu(void) {
    // Callers must end the current render / blit pass before this call.
    // ReadTexels may initialize a texture after replay has started. Publish
    // its deferred upload before waiting; only the submit thread owns it.
    if (on_sub_thread()) { up_flush(); rec_drain(); }
    if (g_fence) nvn_be_wait(g_fence, UINT64_MAX);
    up_wait_zero(&g_up_pending);
}
void mtl_present_flush(void);
// nvnQueueFinish waits for the GPU work submitted so far, not for queued presents to reach the screen: with a window, the display link takes one present per tick, so waiting for them
// made every QueueFinish cost one or two display frames. Fire Emblem: Three Houses' loader submits a copy and calls QueueFinish for each resource it uploads, and its first loading screen
// took 78 s on the iPhone (5 s windowless on the Mac). A swapchain texture is not handed back before its previous present is processed (AcquireTexture waits for that ticket)
void nvn_be_finish(void) { mtl_finish_gpu(); }
// nvnQueueFinish 分两段（hle_nvn.c queue_finish）：持提交锁只做「冲掉本线程的上传批 + 记下要等的栅栏」，放锁后再等 GPU——
//   等 GPU 期间别的线程照常提交（直连线 11-02 建议：FE 风花雪月加载线程每个资源 Finish 一次，持锁等会把渲染线程的提交全挡住）
uint64_t nvn_be_finish_publish(void) { if (on_sub_thread()) { up_flush(); rec_drain(); } return g_fence; }
void nvn_be_finish_wait(uint64_t fence) { if (fence) nvn_be_wait(fence, UINT64_MAX); up_wait_zero(&g_up_pending); }
static void present_drop_for_suspend(void);
void nvn_be_drain(void) { if (mtl_gpu_halted()) { MLOG("GPU 安全停中：后台排空不再交 / 等 GPU"); return; } present_drop_for_suspend(); mtl_present_flush(); mtl_init(); id<MTLCommandBuffer> cb = q_cb(); cb_run(cb); mtl_finish_gpu(); }

// ================= Render replay =================
#include "../../host/front.h"
static int g_red_once[186];   // RED_ONCE keys 0..185 (183 / 184 / 185: an incompatible Metal texture format view fell back to the base format in rt_view_fmt / attach / clear_tex; 182: a block-compressed texture whose GPU writer resolved to its own Metal format, bcal_copy; 181: a texture view whose target and layer range Metal cannot express (#199), tex_by_id; 179 / 180: a pass's own depth attachment sampled in it could not be copied / viewed (#387); 178: a slot read on-chip by the first draw of a pass was not opened loaded; 177: a compute dispatch's binding ended the shared encoder again on the retry; 175 / 176: a block-compressed texture's GPU-written bytes not taken: no host texture of the uncompressed writer / no staging buffer, bcal_sync; 174: a converted vertex attribute stream address in no memory pool, vconv_bind; 172 / 173: a pool table for handles traced to no slot could not be allocated / grown, pool_tab_new / pool_tab_put_n; 171: a first-invocation store skipped, dispatch; 170: an sRGB / linear view not made again on its upgraded parent, tex_upgrade; 169: unused since 11-07 (a not-loaded color attachment written: g_noload_wrong, first 8 lines); 167 / 168: a storage buffer address the pools do not hold, slot / handle in a uniform buffer; 166: a texture turning packaged whose old host texture has another shape, its GPU-written texels not carried over, carry_gpu) (162: a vertex buffer address the pools do not hold, bind_vbufs) (160 / 161 / 163–165: tensor-core network stand-in, nvn_tensor.inc; 147–159 left for the NVN2 task / mesh branch) (143–146: NVN2 DLSS → MetalFX, nvn_dlss.inc) (139–142: folded linear textures: tex_linear, se_want, se_bind, copies / clears into one) (137 / 138: a GL texture an NVN texture is built from has no usable storage / no matching NVN format) (136: a draw's binding ended its pass twice) (134 / 135: alpha test / multisampling off the fragment shader cannot take); same-pass feedback snapshot too large 127, native image atomics use 128/129, same-pass feedback view narrowing 133
// The key must be a constant inside the table: a key past the end wrote into the statics next to it (11-05: nvn_tensor.inc used 160 / 161 with 147 slots)
#define RED_ONCE(k, ...) do { _Static_assert((k) >= 0 && (k) < (int)(sizeof g_red_once / sizeof g_red_once[0]), "RED_ONCE key outside g_red_once"); if (!g_red_once[k]++) MLOG("【红】 " __VA_ARGS__); } while (0)
// NVN vertex streams 0–15 → Metal vertex buffer slots: 0–13 go to 16–29 (30 is the constant fallback buffer), 14 and 15 to 14 and 15. Metal has only the 31 slots 0–30; translated shaders use only buffer(0) (the argument buffer),
// and the host's own vertex functions read no vertex buffers. 13 Sentinels uses stream 15, and the old 16 + stream went out of range (Metal assertion: buffer index (31) must be < 31)
#define VB_SLOT(st) ((st) < 14 ? 16 + (st) : (st))

// ---------- Texture → MTLTexture ----------
static int fmt_compressed(int f) { return (f >= 0x41 && f <= 0x50) || (f >= 0x79 && f <= 0x94); }
static int fmt_depth(int f) { return f >= 0x31 && f <= 0x36; }
typedef struct { MTLPixelFormat a, b; } pfv_pair;
static const pfv_pair g_pfv_srgb[] = {
    {MTLPixelFormatRGBA8Unorm, MTLPixelFormatRGBA8Unorm_sRGB},
    {MTLPixelFormatBGRA8Unorm, MTLPixelFormatBGRA8Unorm_sRGB},
    {MTLPixelFormatBC1_RGBA, MTLPixelFormatBC1_RGBA_sRGB},
    {MTLPixelFormatBC2_RGBA, MTLPixelFormatBC2_RGBA_sRGB},
    {MTLPixelFormatBC3_RGBA, MTLPixelFormatBC3_RGBA_sRGB},
    {MTLPixelFormatBC7_RGBAUnorm, MTLPixelFormatBC7_RGBAUnorm_sRGB},
};
static int tex_need_pfv(MTLPixelFormat base, MTLPixelFormat view) {
    if (base == view) return 0;
    for (size_t i = 0; i < sizeof g_pfv_srgb / sizeof *g_pfv_srgb; i++)
        if ((base == g_pfv_srgb[i].a && view == g_pfv_srgb[i].b) || (base == g_pfv_srgb[i].b && view == g_pfv_srgb[i].a)) return 0;
    return 1;
}
// Cache tables on the replay hot path always use nvn_hmap (C hash, keys not boxed); the table stores CFBridgingRetain'ed objects, CFRelease'd on replace / delete
static void hm_rel(void *v) { CFRelease(v); }
static __unsafe_unretained id hm_get_id(const nvn_hmap *m, const void *k) { return (__bridge id)nvn_hm_get(m, k); }
static void hm_put_id(nvn_hmap *m, const void *k, id o) { void *old = nvn_hm_put(m, k, (void *)CFBridgingRetain(o)); if (old) CFRelease(old); }
static void hm_del_id(nvn_hmap *m, const void *k) { void *old = nvn_hm_del(m, k); if (old) CFRelease(old); }
static nvn_hmap g_by_serial = {.klen = 8};     // Serial → MTLTexture / NvPkg / NvProg
static pthread_mutex_t g_smu = PTHREAD_MUTEX_INITIALIZER;
// Serial table generation: +1 when entries are added / removed or a packaged texture is replaced. Downstream caches (texture views, programs) record the generation at fetch time; if it is unchanged they can be used directly without another table lookup
static _Atomic uint64_t g_ser_gen = 1;
// Textures shared by storage (non-packaged): key = memory pool + offset + texture description. An NVN texture object is only a descriptor; an object rebuilt over the same storage with the same description is the same texture;
// SMBW rebuilds its transient render targets on new objects every frame and never Finalizes them, so building one per serial leaked about 13 MB of GPU memory per frame. Textures here are kept resident by the sharing table,
// and when the serial table replaces / deletes them it only drops its reference (defer_obj_unref), never removing them from the residency set. Entries go when their pool is finalized (nvn_be_alias_drop_pool)
// or another texture takes over their storage (alias_take_over).
typedef struct { uint64_t pool; int64_t off; nvn_texdesc d; } alias_key;
// The key leaves out the texture flags that only state a use, not the storage layout (nvn_tex_layout reads LINEAR / SPARSE / LINEAR_RENDER_TARGET / VIDEO_DECODE; MINIMAL_LAYOUT and
// DISPLAY are kept too): objects over the same storage that differ only in IMAGE, COMPRESSIBLE or the zcull hints are the same texture. Xenoblade Chronicles 3 makes its G-buffer
// depth-stencil (COMPRESSIBLE) and, over the same storage, the object its material pass reads the stencil through (COMPRESSIBLE | IMAGE): keyed apart, the second was a new zero-filled
// texture, every material depth came out 0, the depth-equal lighting passes lit nothing, and everything lit in deferred came out black (10-26 维护者 on test device 1). A use the shared
// texture lacks is added in place (tex_mtl → tex_upgrade)
enum { ALIAS_USE_FLAGS = NVN_TEXTURE_FLAGS_IMAGE | NVN_TEXTURE_FLAGS_COMPRESSIBLE | NVN_TEXTURE_FLAGS_ADAPTIVE_ZCULL | NVN_TEXTURE_FLAGS_DEPTH16_PREFER_FAST_CLEAR | NVN_TEXTURE_FLAGS_ZCULL_SUPPORT_STENCIL };
static int mtl_fmt_depth(MTLPixelFormat f);
static void alias_key_of(alias_key *k, const tex_t *t) { memset(k, 0, sizeof *k); k->pool = (uint64_t)(uintptr_t)t->pool; k->off = t->off; k->d = t->d; k->d.flags &= ~(uint32_t)ALIAS_USE_FLAGS; }
static nvn_hmap g_alias = {.klen = sizeof(alias_key)};
static nvn_hmap g_alias_seen = {.klen = sizeof(alias_key)};   // key → g_fence + 1 at its last lookup or creation (alias_take_over spares entries looked up lately)
static nvn_hmap g_alias_wrote = {.klen = sizeof(alias_key)};   // key → g_fence + 1 at its last GPU write (gpw_mark), under g_smu
static CFMutableSetRef g_alias_set;   // Textures in the sharing table (non-owning; used to ask "is this shared")
static uint64_t g_alias_evicted;   // shared textures evicted on pool Finalize so far (for the memory report)
static int alias_has(id o) { return g_alias_set && o && CFSetContainsValue(g_alias_set, (__bridge const void *)o); }
// On memory pool Finalize, evict the textures built on that pool from the sharing table (collect the keys first, then delete: deletion shifts entries back). The sharing table used not to evict: Mario's pools stay for good, so entries are bounded;
// Engage frees pools on scene changes and rebuilds on new ones, so the old pools' render targets and other private textures stayed in the table forever (about 0.8 GB more GPU memory over 850 s of the title demo), and linear textures built directly on a pool also kept the whole pool buffer alive.
// Also, when a pool object's address is reused, old entries would hand a texture on the old storage to the new pool's texture at the same offset and description. Evicted textures go through deferred release; if the serial table still holds one, that is just one more reference
static void treg_drop_pool_views(const void *pool);
static void pool_dirty(int samp, int id_);   // a registration changed what the ID names: a pool table entry is looked up again (pool_gpu)
static void pool_gpuw_drop(const void *pool);   // with tex_cpu_content
static void bcal_drop_pool(const void *pool);   // g_bcal (below, with gpw_mark)
void nvn_be_alias_drop_pool(const void *pool) {
    if (!pool) return;
    pthread_mutex_lock(&g_smu);
    uint32_t n = 0; alias_key *ks = NULL;
    for (uint32_t i = 0; i < g_alias.cap; i++) {
        if (!g_alias.vals[i]) continue;
        alias_key k; memcpy(&k, g_alias.keys + (size_t)i * g_alias.klen, sizeof k);
        if (k.pool != (uint64_t)(uintptr_t)pool) continue;
        alias_key *nk = realloc(ks, (n + 1) * sizeof *ks); if (!nk) break; ks = nk; ks[n++] = k;
    }
    for (uint32_t j = 0; j < n; j++) {
        void *old = nvn_hm_del(&g_alias, &ks[j]);
        if (!old) continue;
        nvn_hm_del(&g_alias_seen, &ks[j]); nvn_hm_del(&g_alias_wrote, &ks[j]);
        id o = CFBridgingRelease(old);
        if (g_alias_set) CFSetRemoveValue(g_alias_set, (__bridge const void *)o);
        defer_obj_release(o);
    }
    if (n) { g_ser_gen++; g_alias_evicted += n; }
    pthread_mutex_unlock(&g_smu);
    free(ks);
    treg_drop_pool_views(pool);   // outside g_smu: the texture ID registry lock g_rmu is taken before g_smu
    bcal_drop_pool(pool);
    pool_gpuw_drop(pool);   // first-use storage rule (tex_cpu_content): the pool's GPU-written mark and its uncompressed textures taken from storage
}
// A new shared texture takes over storage: entries of the same pool whose storage overlaps the new texture's under another description go, unless a live texture object still resolves
// to them (an object rebuilt over the same storage with the same description must keep finding it: SMBW's transient render targets) or a lookup found them in the last ALIAS_IDLE submissions
// (Breath of the Wild finalizes its transient render targets before it submits and makes them again the next frame: targets sharing storage would evict each other every frame). On NVN the memory now belongs to the new texture;
// the old private Metal texture only held a copy nothing can name again. STEINS;GATE RE:BOOT decodes every image it shows into one scratch region of a pool that lives for good and
// finalizes the texture before the next one: each image added an entry, 468 of them and 1.58 GB of GPU memory 24,000 frames into a new game. A finalized object resolved through g_ghost
// keeps its own reference, so the entry's reference is only unref'd while one does; otherwise the texture is retired (deferred until the submissions that used it complete).
// Cached texture-ID views follow g_ser_gen. Caller holds g_smu
enum { ALIAS_IDLE = 16 };
static uint64_t g_alias_taken;   // shared textures evicted when another texture took over their storage (for the memory report)
static nvn_hmap g_ghost;   // defined below (finalized texture serials)
static nvn_hmap g_ghost_active = {.klen = 8};   // finalized serials resolved while the current submission is encoded (serial → retained object), under g_smu; see ghost_finish_submission
static int serial_holds(nvn_hmap *m, id o) { for (uint32_t i = 0; i < m->cap; i++) if (m->vals[i] == (__bridge void *)o) return 1; return 0; }
// Storage written over by another texture (Switch / Ryujinx semantics: textures over the same memory share its bytes; once another texture's GPU write lands there, the
//   earlier one's content is gone, and Ryujinx's texture cache drops the overlapped host texture). 11-05 Ocarina of Time on Switch 2: its shadow map changes size nearly
//   every frame and each size is a new live texture object over the same storage (429 depth textures 961x961..1280x1280 at one pool offset in a 120 s Mac run, 6 MB of
//   storage, 2.2 GB of private Metal textures): live objects were never evicted, and the phone was killed for memory loading a scene. A live object's texture now goes too
//   once it has been idle ALIAS_IDLE submissions and another texture over its storage was GPU-written after its last use; using it again makes it anew, with the stale
//   runs zeroed as for any texture whose storage another GPU write covered (tex_init_fill)
static uint64_t g_alias_dead;   // live objects' textures dropped as overwritten (alias_take_over)
static uint64_t *g_alias_dead_ser; static uint32_t g_alias_dead_n, g_alias_dead_cap;   // their serials, under g_smu, until alias_dead_views
static int alias_overwritten(const alias_key *a, int64_t lo, int64_t hi, uint64_t seen) {   // caller holds g_smu
    for (uint32_t i = 0; i < g_alias_wrote.cap; i++) {
        if (!g_alias_wrote.vals[i]) continue;
        alias_key k; memcpy(&k, g_alias_wrote.keys + (size_t)i * g_alias_wrote.klen, sizeof k);
        if (k.pool != a->pool || !memcmp(&k, a, sizeof k) || k.off >= hi) continue;
        nvn_texlayout kl; nvn_tex_layout(&k.d, &kl);
        if (k.off + (int64_t)kl.size > lo && (uint64_t)(uintptr_t)g_alias_wrote.vals[i] > seen) return 1;
