        const s2a_lowva_api *(*get)(void) = (const s2a_lowva_api *(*)(void))dlsym(RTLD_DEFAULT, "s2a_lowva"); const s2a_lowva_api *lv = get ? get() : NULL;
        if (lv && lv->size >= sizeof(s2a_lowva_api) && lv->version == S2A_LOWVA_VERSION) { g_orph_lv = lv; g_orph_lv_me = lv->user("unreferenced shared textures", alias_orph_evict, NULL); } } }
    typedef struct { alias_key k; const uint8_t *mem; uint64_t size; } cand_t;
    pthread_mutex_lock(&g_smu);
    CFMutableSetRef held = alias_held();
    uint32_t nc = 0, nw = 0; alias_key *cache = g_alias.n ? malloc(g_alias.n * sizeof *cache) : NULL; cand_t *wr = g_alias.n ? malloc(g_alias.n * sizeof *wr) : NULL;
    int64_t wbytes = 0;
    for (uint32_t i = 0; cache && wr && i < g_alias.cap; i++) { alias_key k;
        if (!alias_orph_cand(i, held, &k)) continue;
        if (!nvn_hm_get(&g_alias_wrote, &k)) { cache[nc++] = k; continue; }
        const pool_t *p = (const pool_t *)(uintptr_t)k.pool; nvn_texlayout L; nvn_tex_layout(&k.d, &L);
        wbytes += (int64_t)res_bytes((__bridge id)g_alias.vals[i]);
        if (p && p->mem && L.size) wr[nw++] = (cand_t){k, p->mem + k.off, L.size};
    }
    CFRelease(held);
    for (uint32_t j = 0; j < nc; j++) alias_orph_drop(&cache[j], 0);
    pthread_mutex_unlock(&g_smu);
    uint32_t nr = 0;
    for (uint32_t j = 0; j < nw; j++) {   // outside g_smu: the write ledger has its own lock
        uint64_t *runs = NULL, b = 0; int n = gpw_stale(wr[j].mem, wr[j].size, &runs, &b); free(runs);
        if (n == 0) wr[nr++] = wr[j];
    }
    if (nr) { pthread_mutex_lock(&g_smu); CFMutableSetRef h2 = alias_held();
        for (uint32_t j = 0; j < nr; j++) { void *v = nvn_hm_get(&g_alias, &wr[j].k); uint64_t seen = (uint64_t)(uintptr_t)nvn_hm_get(&g_alias_seen, &wr[j].k);
            if (!v || CFSetContainsValue(h2, v) || (seen && g_fence + 1 - seen < ALIAS_IDLE)) continue;   // taken up again meanwhile
            wbytes -= (int64_t)alias_orph_drop(&wr[j].k, 1); }
        CFRelease(h2); pthread_mutex_unlock(&g_smu); }
    if (g_orph_lv) { pthread_mutex_lock(&g_smu); int64_t d = wbytes - g_orph_noted; g_orph_noted = wbytes; pthread_mutex_unlock(&g_smu); if (d) g_orph_lv->note(g_orph_lv_me, d); }   // attribution: the ledger asks the largest holders first
    free(cache); free(wr);
}
static __unsafe_unretained id serial_get(uint64_t k) { pthread_mutex_lock(&g_smu); __unsafe_unretained id o = hm_get_id(&g_by_serial, &k); pthread_mutex_unlock(&g_smu); return o; }
static void serial_put(uint64_t k, id o) { pthread_mutex_lock(&g_smu); id old = hm_get_id(&g_by_serial, &k); if (old) { if (alias_has(old)) defer_obj_unref(old); else defer_obj_release(old); } hm_put_id(&g_by_serial, &k, o); g_ser_gen++; pthread_mutex_unlock(&g_smu); }
static void serial_del(uint64_t k) { pthread_mutex_lock(&g_smu); id old = hm_get_id(&g_by_serial, &k); if (old) { if (alias_has(old)) defer_obj_unref(old); else defer_obj_release(old); hm_del_id(&g_by_serial, &k); g_ser_gen++; } pthread_mutex_unlock(&g_smu); }   // nothing to drop: the texture ID caches stay valid
// Texture serials owned by a live NVN texture object (TextureInitialize until Finalize or re-initialization, hle_nvn.c). Command records and texture pool registrations snapshot the
// texture object (tex_snap in hle_nvn.c, nvn_be_reg_tex), so replay can resolve a texture the game has already finalized: Breath of the Wild records each frame's transient render targets
// (the HUD captures, the 640x360 half-resolution buffers) and finalizes their objects before it submits. Those serials went back into g_by_serial and stayed there for good, as no second
// Finalize comes: about 10 a frame, 200,000 after an hour in the first shrine. A dead serial resolves through g_ghost instead, a small table whose oldest entry goes when a new one comes,
// so a record replayed again soon still finds its texture
enum { NGHOST = 512 };
static nvn_hmap g_tex_live = {.klen = 8};   // serial → (void *)1, under g_smu
static nvn_hmap g_ghost = {.klen = 8}; static uint64_t g_ghost_ring[NGHOST]; static unsigned g_ghost_next; static uint64_t g_ghost_puts;
int nvn_be_tex_is_live(uint64_t ser) { pthread_mutex_lock(&g_smu); int r = nvn_hm_get(&g_tex_live, &ser) != NULL; pthread_mutex_unlock(&g_smu); return r; }   // 这个序号的贴图对象还活着（没 Finalize / 重新初始化）
uint32_t nvn_be_tex_live_n(void) { pthread_mutex_lock(&g_smu); uint32_t n = g_tex_live.n; pthread_mutex_unlock(&g_smu); return n; }   // 活着的贴图对象数（宽屏胶水表满时对照：是游戏真有这么多，还是登记漏还）
void nvn_be_tex_init(const tex_t *t) { if (!t->serial) return; atomic_fetch_add(&g_tex_init_n, 1); pthread_mutex_lock(&g_smu); nvn_hm_put(&g_tex_live, &t->serial, (void *)1); pthread_mutex_unlock(&g_smu); }
static void obj_drop(id o) { if (alias_has(o)) defer_obj_unref(o); else defer_obj_release(o); }   // caller holds g_smu
// A submission can resolve more finalized textures than the ring holds (S2Arm 11-05, after upstream PR #1299 commit 2 "A bindless pool churns finalized textures within a submission",
//   MIT, seedds/upstream 9fb44679: about 12,000 finalized descriptors in Ocarina of Time's Kokiri Forest, 18.9 GB resident on the Mac). The ring then evicted a texture that draws already
//   encoded in the same submission use, the next resolution made it again (a packaged one re-uploaded), and every copy stayed alive until the submission's fence. Finalized serials
//   resolved while a submission is encoded (submit thread, g_cb open) are also held in g_ghost_active until it ends: a lookup finds them there after the ring has let them go, and the ring
//   does not drop them early; ghost_finish_submission releases the overflow behind this submission's fence
static __unsafe_unretained id tex_get(uint64_t k) {
    pthread_mutex_lock(&g_smu);
    __unsafe_unretained id o = hm_get_id(&g_by_serial, &k);
    if (!o && g_ghost_active.n) o = hm_get_id(&g_ghost_active, &k);
    if (!o && g_ghost.n && (o = hm_get_id(&g_ghost, &k)) && g_cb && on_sub_thread()) hm_put_id(&g_ghost_active, &k, o);
    pthread_mutex_unlock(&g_smu);
    return o;
}
static void tex_put(uint64_t k, id o) {   // serials from 2^62 up are external textures (mtl_ext_tex), never initialized by the game
    pthread_mutex_lock(&g_smu);
    int live = k >= (1ull << 62) || nvn_hm_get(&g_tex_live, &k);
    id active = live ? nil : hm_get_id(&g_ghost_active, &k);
    nvn_hmap *m = live ? &g_by_serial : active && !hm_get_id(&g_ghost, &k) ? &g_ghost_active : &g_ghost;   // evicted from the ring earlier in this submission: replaced where it is held
    id old = hm_get_id(m, &k);
    if (old) { if (old != o) obj_drop(old); }
    else if (m == &g_ghost) {
        uint64_t *slot = &g_ghost_ring[g_ghost_next++ % NGHOST];
        if (*slot) { id ev = hm_get_id(&g_ghost, slot); if (ev && ev != hm_get_id(&g_ghost_active, slot)) obj_drop(ev); hm_del_id(&g_ghost, slot); }   // still used by this submission: dropped when it ends
        *slot = k; g_ghost_puts++;
    }
    hm_put_id(m, &k, o); g_ser_gen++;
    if (m == &g_ghost && (active || (g_cb && on_sub_thread()))) hm_put_id(&g_ghost_active, &k, o);
    pthread_mutex_unlock(&g_smu);
}
// End of the submission's encoding (nvn_be_sub_commit, before its fence is taken): finalized textures the ring no longer holds are dropped behind this submission's fence, the rest stay in the ring.
//   The texture ID caches resolved them; g_ser_gen moves so they resolve again
static uint64_t g_ghost_kept;   // textures held past their ring eviction until their submission ended
static uint64_t g_ghost_shared;   // finalized serials resolved straight to a shared texture (tex_mtl_)
static void ghost_finish_submission(void) {
    pthread_mutex_lock(&g_smu);
    int dropped = 0;
    for (uint32_t i = 0; i < g_ghost_active.cap && g_ghost_active.n; i++) {
        void *v = g_ghost_active.vals[i]; if (!v) continue;
        if (nvn_hm_get(&g_ghost, g_ghost_active.keys + (size_t)i * g_ghost_active.klen) != v) { obj_drop((__bridge id)v); dropped++; }
    }
    if (g_ghost_active.n) nvn_hm_clear(&g_ghost_active, hm_rel);
    if (dropped) { g_ser_gen++; g_ghost_kept += (uint64_t)dropped; }
    pthread_mutex_unlock(&g_smu);
}
// NVN ⇄ GL 纹理互操作（nvnTextureBuilderSetGLTextureName；11-03 火影羁绊：Scaleform 往 GL 纹理画界面，游戏按纹理名建 NVN 纹理，场景先拷进去、界面画完再拷回 NVN 画面）。
//   真机两边是同一块显存：NVN 纹理的格式 / 尺寸 / 级数取 GL 纹理的（构建器上那几项不看），存储就是 GL 那张。本层把 GL 层交出的 MTLTexture 登记在这个序号下，
//   NVN 的拷贝 / 采样 / 渲染目标解析（tex_mtl）直接拿到它；GL 内部格式换成 NVN 格式后，按 NVN 格式该用的 Metal 格式核一遍，对不上不登记（报红，免得按错格式解释同一份字节）。
//   原先只记名字，NVN 纹理格式 0、0×0，「texture format 0 has no Metal equivalent」，两次拷贝都落空，界面画不到屏上
id<MTLTexture> gl_tex_export(uint32_t name, uint32_t *internal, uint32_t *levels);   // gfx/gl/gl_tex.m
static int gl_internal_to_nvn(uint32_t f) {
    switch (f) {
        case 0x8058: return NVN_FORMAT_RGBA8; case 0x8C43: return NVN_FORMAT_RGBA8_SRGB; case 0x881A: return NVN_FORMAT_RGBA16F; case 0x8814: return NVN_FORMAT_RGBA32F;
        case 0x8229: return NVN_FORMAT_R8; case 0x822B: return NVN_FORMAT_RG8; case 0x8059: return NVN_FORMAT_RGB10A2; case 0x8C3A: return NVN_FORMAT_R11G11B10F;
        case 0x8D62: return NVN_FORMAT_RGB565; case 0x81A5: return NVN_FORMAT_DEPTH16; case 0x81A6: return NVN_FORMAT_DEPTH24; case 0x8CAC: return NVN_FORMAT_DEPTH32F;
        case 0x88F0: return NVN_FORMAT_DEPTH24_STENCIL8;
    }
    return 0;
}
int nvn_be_tex_from_gl(tex_t *t, uint32_t gl_name) { @autoreleasepool {
    uint32_t internal = 0, levels = 0; id<MTLTexture> img = gl_tex_export(gl_name, &internal, &levels);
    if (!img) { RED_ONCE(137, "nvnTextureBuilderSetGLTextureName: GL texture %u has no 2D storage (not a texture, not 2D, or level 0 undefined); the NVN texture stays empty (first case)", gl_name); return 0; }
    int f = gl_internal_to_nvn(internal); uint32_t pf = 0; uint8_t swz[4];
    if (!f || !nvn_fmt_to_mtl((uint32_t)f, &pf, swz) || pf != (uint32_t)img.pixelFormat) {
        RED_ONCE(138, "nvnTextureBuilderSetGLTextureName: GL texture %u internal format %#x (Metal %lu) has no NVN format stored the same way; the NVN texture stays empty (first case)", gl_name, internal, (unsigned long)img.pixelFormat);
        return 0;
