}}
// Host record of a packaged texture: the current MTLTexture, the upload stamp, and the global write generation at the last check
// spare: the texture the last re-upload replaced, kept resident and written by the next re-upload once the GPU has passed spare_fence (a texture the CPU rewrites every frame, a movie frame,
// alternates between two textures instead of allocating one per frame: Link's Awakening's title movie made and freed an 8 MB texture a frame)
@interface NvPkg : NSObject { @public id<MTLTexture> tex, spare, view; uint64_t stamp, seen, hash, spare_fence, vgen, vseen, check_epoch; const void *span; int sparse, vbase; uint64_t *ph, *pgpu; uint32_t nph; } @end   // hash: full hash of the uploaded content under DM_NVN_DIRTYCHECK; span: its tracked range (nvn_dirty_span, NULL = untracked);
// sparse: in a sparse virtual pool, read through its page table (hle_nvn.c nvn_sparse_*), vgen the page table's generation at the upload and vseen at the last look; view: what it is bound as (sparse_view)
@implementation NvPkg
- (void)dealloc { res_remove(tex); if (spare) res_remove(spare); free(ph); free(pgpu); }
@end
static uint64_t g_pkg_uploads, g_pkg_reuploads, g_pkg_miss, g_pkg_same, g_pkg_gpu_writes, g_pkg_gpu_kept, g_pkg_partial;
// pgpu (S2Arm 10-25): per host page, the dirty-page generation when the GPU last wrote the texture's bytes there (a copy or clear into it; nvn_dirty_now at encoding, which is the game's submission).
// The replay's GPU writes reach the host texture, never guest memory, so a whole re-upload from guest memory would undo them. Who wrote a page last decides: written by the CPU after the GPU
// (page generation > pgpu) is uploaded, written before it is left as the GPU made it. Pages are re-uploaded as the texel rectangles their bytes hold (tex_bytes_rects), into the same texture
// ph / nph (S2Arm 10-25): a hash of the texture's bytes in each host page of its storage, taken at the upload between the stamp and the read (pkg_upload_). A written page is not a changed texture:
// host pages are 16 KB on Apple systems and NVN resources only 4 KB aligned, so a page holds the edge of a texture and other data the CPU rewrites every frame. Mario Kart 8 Deluxe re-uploaded
// whole textures on such pages (a 2048x2048 one of 32 MB among them) about 72,000 times in a run, 2,000 of 2,000 with the same bytes (DM_NVN_DIRTYCHECK), and the phone ran at 4.4 W instead of
// 2.4 - 3.4. Before a re-upload tex_mtl_ hashes the texture's bytes in the written pages only and keeps the upload when they all match
static uint64_t g_pfv_upgrades;
// DM_NVN_DIRTYCHECK=1 (diagnostic, compared against ground truth): fully hash the pool content on every use; changed but not detected by dirty-page tracking = a missed detection
static int dirtycheck(void) { static int v = -1; if (v < 0) v = getenv("DM_NVN_DIRTYCHECK") != NULL; return v; }
static uint64_t full_hash(const uint8_t *m, uint64_t n) { uint64_t h = 1469598103934665603ull; for (uint64_t i = 0; i < n; i++) h = (h ^ m[i]) * 1099511628211ull; return h; }
// GPUs without BC compressed formats (A15 / A16 and older, MTLDevice.supportsBCTextureCompression = NO): BC textures are created in the decompressed format and decoded at upload /
// buffer→texture copy time. Ported from MacNativeGames (MIT, games/wonder/third_party/d2r_gfx/gfx/nvn/nvn_mtl.m no_bc / bc_unpack); decoding in tex/nvn_bcdec.c (bcdec).
// Without it a BC game draws nothing on those phones, and the iOS 18 floor for direct mode means little. DM_TEST_NO_BC=1 forces the path on any machine (Mac checks)
static int no_bc(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DM_TEST_NO_BC"); v = (e && *e && strcmp(e, "0")) || ![g_dev supportsBCTextureCompression];
        if (v) MLOG("GPU without BC compressed formats%s: BC textures are created decompressed and decoded at upload", e && *e && strcmp(e, "0") ? " (test switch DM_TEST_NO_BC)" : ""); }
    return v;
}
// Textures the host stores in another format than the game's: BC on a GPU without BC (decompressed), and the formats it expands (nvn_fmt_expanded: three components into four,
//   *_UI2F / *_I2F into float, RGB10A2 signed into 16 bits; 缺口族 30). Both are deswizzled on the CPU and converted into the staging area (fmt_decode), read back never
static int fmt_unpack(uint32_t nvn_fmt, uint32_t *pf, int *bpp) { return nvn_fmt_expanded(nvn_fmt, pf, bpp) || (no_bc() && nvn_bc_unpacked(nvn_fmt, pf, bpp)); }
static int fmt_decode(uint32_t f, const uint8_t *src, size_t pitch, uint32_t w, uint32_t h, uint8_t *dst, size_t dpitch) {
    return nvn_fmt_expanded(f, NULL, NULL) ? nvn_fmt_expand(f, src, pitch, w, h, dst, dpitch) : nvn_bc_decode(f, src, pitch, w, h, dst, dpitch);
