    return upgraded_view ? upgraded_view : upgraded;
}
static id<MTLTexture> tex_upgrade_pfv(const tex_t *t, id<MTLTexture> base, MTLPixelFormat view_pf) { return tex_upgrade(t, base, MTLTextureUsagePixelFormatView, view_pf); }
// Packaged texture upload: first set read-only, then take the stamp, then read the pool memory and deswizzle into a staging buffer, and blit into a new private texture.
// Batching: uploads within one replay submission share one upload command buffer (compute encoder deswizzle + a unified blit), flushed before the replay command buffer is committed;
// the same queue executes in commit order ⇒ uploads are always finished before the first sample. Uploads outside a submission are flushed on the spot. The staging area is cut from 32 MB private blocks, held by the command buffer until completion.
static _Atomic uint64_t g_upload_ns;   // Cumulative time of deswizzle + upload encoding on the submit thread (timing instrumentation)
static _Atomic uint64_t g_upload_gpu_ns;
static id g_up_cb;   // MTL4CommandBuffer on Metal 4, MTLCommandBuffer on Metal 3
static id g_up_ce;   // its open encoder: Metal 4 compute (deswizzles, then the copies), Metal 3 copy encoder (the copies only)
static _Atomic int g_up_alloc_busy[3];
// Waiting for upload batches to finish (g_up_pending, g_up_alloc_busy): the batches' completion handler broadcasts after it updates them, so waiters sleep until then (they used to poll every 0.2–1 ms;
// Three Houses' loader calls QueueFinish after each resource, each one waited up to a millisecond late). The 10 ms timeout is only a safety net
static pthread_mutex_t g_up_wmu = PTHREAD_MUTEX_INITIALIZER; static pthread_cond_t g_up_wcv = PTHREAD_COND_INITIALIZER;
static void up_wake(void) { pthread_mutex_lock(&g_up_wmu); pthread_cond_broadcast(&g_up_wcv); pthread_mutex_unlock(&g_up_wmu); }
static void up_wait_zero(_Atomic int *v) {
    if (!atomic_load(v)) return;
    DM_BLOCK_BEGIN(); pthread_mutex_lock(&g_up_wmu);
    while (atomic_load(v)) { struct timespec dl; clock_gettime(CLOCK_REALTIME, &dl); dl.tv_nsec += 10000000; if (dl.tv_nsec >= 1000000000) { dl.tv_sec++; dl.tv_nsec -= 1000000000; } pthread_cond_timedwait(&g_up_wcv, &g_up_wmu, &dl); }
    pthread_mutex_unlock(&g_up_wmu); DM_BLOCK_END();
}
static unsigned g_up_seq;
#define UP_BLOCK_SIZE (32u * 1024u * 1024u)
// Each of the three upload slots keeps one staging block of UP_SLOT_BLOCK for good (resident, reused once that slot's previous batch has finished: up_begin waits for it). Every batch used to make a fresh
// 32 MB private block, put it in the residency set and retire it after the GPU was done: Breath of the Wild re-uploads a few CPU-written textures each frame (about 40 KB each), so that was about 1.7 blocks
// a frame, about 3 GB/s of GPU memory allocated, made resident and freed, and 2.4 residency commits a frame. A slot's block grows to fit the first texture of a batch (up to UP_BLOCK_SIZE); what does
// not fit after that continues in fresh blocks of UP_BLOCK_SIZE as before
#define UP_SLOT_BLOCK (4u * 1024u * 1024u)
static __strong id<MTLBuffer> g_up_slot_blk[3]; static unsigned g_up_cur_slot;
typedef struct {
    __unsafe_unretained id<MTLBuffer> src;
    size_t off, row, image;
    MTLSize size;
    __unsafe_unretained id<MTLTexture> dst;   // Strongly referenced by g_up_texs until the flush is encoded
    NSUInteger slice, level, x0, y0;   // x0 / y0: where in the level the region goes (a partial re-upload, pkg_upload_rects); 0 for a whole level
} up_blit;
static up_blit *g_up_blits; static int g_nup_blits, g_up_blitcap;
static NSMutableArray *g_up_texs;   // Target textures in the batch: before the flush, textures may be replaced / released within the same submission
static id<MTLBuffer> g_up_block;
static size_t g_up_block_off, g_up_block_size;
static NSMutableArray *g_up_keep;
// Bytes of staging held in g_up_keep for the open batch. Kept staging is retired only after the batch's flush commits, and a batch stays open while a submission is open (uploads flush with the
// submission), so one submission that uploads a lot piled up blocks without bound: a frame replay re-uploading every texture held 2729 blocks, 116 GB, and locked ~110 GB of the 128 GB machine.
// up_begin flushes the batch once it holds UP_KEEP_CAP: between two texture uploads, where every recorded copy is complete; the upload commits before the open submission, so order is kept
#define UP_KEEP_CAP (256ull << 20)
static uint64_t g_up_keep_bytes; static uint64_t g_up_cap_flushes;
static void up_keep_add(id<MTLBuffer> b) { if (!g_up_keep) g_up_keep = [NSMutableArray array]; [g_up_keep addObject:b]; g_up_keep_bytes += b.length; }


// The upload command buffer was discarded by the system (dropped along during GPU error recovery; the first frame on entering Travincal drops one every run): the objects of this batch of textures are built and the timestamps updated, but the content was never written in,
// and if the pool memory on the game side no longer changes it will never be re-uploaded. Record this batch of target textures, and the next time any of them is fetched treat it as dirty and re-upload once.
// DM_TEST_UP_LOST=<batch index> (for testing): treat that batch of uploads as dropped, to verify the re-upload path.
static NSHashTable *g_up_lost; static os_unfair_lock g_up_lost_lk = OS_UNFAIR_LOCK_INIT; static _Atomic int g_up_lost_n; static _Atomic uint64_t g_up_lost_redo;   // Weak-reference table: if a texture in the record is never fetched again and is released normally, this table does not keep it alive
static int up_lost_take(id tex) {   // This texture's upload was dropped: take it out of the record and return 1
    if (!tex) return 0; os_unfair_lock_lock(&g_up_lost_lk); int hit = [g_up_lost containsObject:tex]; if (hit) { [g_up_lost removeObject:tex]; atomic_store(&g_up_lost_n, (int)g_up_lost.allObjects.count); atomic_fetch_add(&g_up_lost_redo, 1); } os_unfair_lock_unlock(&g_up_lost_lk); return hit;
}
static void up_diag(void);
static void up_flush(void) {
    up_owner_check("up_flush");
    if (!g_up_cb) return;
    if (g_up_ce) {
        m4_end(g_up_ce); g_up_ce = nil;
    }
    if (g_nup_decs) {   // no BC, GPU decompression (up_dec): after the deswizzles that wrote the blocks; the decoded textures take no copy, so this runs before the copies' encoder
        id e = [g_up_cb computeCommandEncoder]; g_up_ce = e;
        if (g_m3) m3_wait(e, 0, 0); else { enc_full_barrier_begin(e); [e setArgumentTable:g_up_ct]; }
        [e setComputePipelineState:bcd_pso()];
        for (int i = 0; i < g_nup_decs; i++) { up_dec *x = &g_up_decs[i];
            if (g_m3) { [(id<MTLComputeCommandEncoder>)e setBuffer:x->src offset:0 atIndex:0]; [(id<MTLComputeCommandEncoder>)e setBuffer:x->params offset:x->poff atIndex:1]; [(id<MTLComputeCommandEncoder>)e setTexture:x->view atIndex:0]; }
            else { [g_up_ct setAddress:x->src.gpuAddress atIndex:0]; [g_up_ct setAddress:x->params.gpuAddress + x->poff atIndex:1]; [(id<MTL4ArgumentTable>)g_up_ct setTexture:x->view.gpuResourceID atIndex:0]; }
            [e dispatchThreadgroups:MTLSizeMake((x->bw + 7) / 8, (x->bh + 7) / 8, 1) threadsPerThreadgroup:MTLSizeMake(8, 8, 1)]; }
        m4_end(e); g_up_ce = nil;   // Metal 3: m4_end updates the fence the copies' encoder waits on
    }
    id b = g_nup_blits ? g_up_ce = g_m3 ? [g_up_cb blitCommandEncoder] : [g_up_cb computeCommandEncoder] : nil;
    if (b) { if (g_m3) [b waitForFence:g_fence3]; else enc_full_barrier_begin(b); }   // Metal 3: the fence stands in for the queue barrier
    for (int i = 0; b && i < g_nup_blits; i++) {
        up_blit *x = &g_up_blits[i];
        enc_b_copy_buffer_texture(b, x->src, x->off, x->row, x->image, x->size, x->dst, x->slice, x->level, MTLOriginMake(x->x0, x->y0, 0));
    }
    if (b) { m4_end(b); g_up_ce = nil; }   // Metal 3: m4_end updates the fence
    id cb = g_up_cb;
    unsigned slot = (g_up_seq - 1) % 3;
    NSMutableArray *dsts = [NSMutableArray arrayWithCapacity:(NSUInteger)g_nup_blits]; for (int i = 0; i < g_nup_blits; i++) if (g_up_blits[i].dst) [dsts addObject:g_up_blits[i].dst];
    for (int i = 0; i < g_nup_decs; i++) if (g_up_decs[i].base) [dsts addObject:g_up_decs[i].base];   // a dropped batch re-uploads its GPU-decoded textures too
    static int lost_at = -2; static uint64_t batch_n; if (lost_at == -2) { const char *e = getenv("DM_TEST_UP_LOST"); lost_at = e ? atoi(e) : -1; } int fake_lost = dsts.count && lost_at > 0 && (int)++batch_n == lost_at;
    // This batch's staging is read only by this upload command buffer: retire it when the upload completes. defer_obj_release waits for the next replay submission's fence, which an
    // open submission does not reach until it ends, so batches flushed at UP_KEEP_CAP inside one submission still kept every block (a frame replay grew past 37 GB)
    NSMutableArray *kept = g_up_keep.count ? [g_up_keep mutableCopy] : [NSMutableArray array];
    if (g_up_block && g_up_block != g_up_slot_blk[slot]) [kept addObject:g_up_block];   // the slot's own block stays (UP_SLOT_BLOCK)
    id o = fb_new();
    atomic_fetch_add(&g_up_pending, 1);
    fb_add(o, ^(id<MTL4CommitFeedback> f) {
        if (f.error && !mtl_gpu_halted()) MLOG("【红】 upload command buffer execution error: %s", f.error.description.UTF8String);
        if (f.error) mtl_gpu_cb_error(f.error, "upload", 0);
        if (f.error || fake_lost) {
            os_unfair_lock_lock(&g_up_lost_lk); if (!g_up_lost) g_up_lost = [NSHashTable weakObjectsHashTable]; for (id d in dsts) [g_up_lost addObject:d]; int n = (int)g_up_lost.allObjects.count; atomic_store(&g_up_lost_n, n); os_unfair_lock_unlock(&g_up_lost_lk);
            pthread_mutex_lock(&g_smu); g_ser_gen++; pthread_mutex_unlock(&g_smu);   // Make the view cache of every texture ID take the slow path once (on a cache hit tex_mtl is not passed through and this record is not seen)
            MLOG("%supload command buffer dropped: the %lu textures of this batch are marked unwritten and re-uploaded on next use (%d awaiting re-upload)", fake_lost ? "DM_TEST_UP_LOST: " : "", (unsigned long)dsts.count, n);
        }
        double d = f.GPUEndTime - f.GPUStartTime;
        if (d > 0) atomic_fetch_add(&g_upload_gpu_ns, (uint64_t)(d * 1e9));
        @autoreleasepool { for (id k in kept) res_remove((id<MTLResource>)k); [kept removeAllObjects]; }
        atomic_store(&g_up_alloc_busy[slot], 0);
        atomic_fetch_sub(&g_up_pending, 1);
        up_wake();
    });
    res_commit();
    if (g_m3) rec_commit_m3(cb, o, nil, 0, 0);
    else { [cb endCommandBuffer]; rec_commit_upload(cb, o); }
    g_up_cb = nil; g_up_block = nil; g_up_block_off = g_up_block_size = 0;   // the block and the kept staging are retired by the upload's completion above
    [g_up_keep removeAllObjects]; g_up_keep_bytes = 0;
    up_diag();
    g_nup_blits = 0; g_nup_decs = 0;
    [g_up_texs removeAllObjects];
}

static void up_begin(void) {
    up_owner_check("up_begin");
    if (g_up_cb && g_up_keep_bytes < UP_KEEP_CAP) return;
    if (g_up_cb) { up_flush(); g_up_cap_flushes++; }
    unsigned slot = g_up_seq++ % 3;
    // With deferred encoding (nvn_rec.h, on by default on iPhone) the batch that last used this slot may still be a commit record in this thread's open block: the GPU has not seen it,
    // so waiting for it to finish never ends. Hand everything recorded to the encode thread first, as every other wait for the GPU does. Textures deswizzled on the CPU (a sparse
    // virtual pool's, read through its page table) are one batch each, so four in a row within one submission got here: Monster Hunter Rise stopped at frame 721 for 45 s
    if (atomic_load(&g_up_alloc_busy[slot])) rec_drain();
    up_wait_zero(&g_up_alloc_busy[slot]);
    atomic_store(&g_up_alloc_busy[slot], 1); g_up_cur_slot = slot;
    if (g_m3) {   // no allocator; the copies get a blit encoder at flush, so this batch's GPU deswizzles need their own compute encoder opened here
        g_up_cb = m3_cb();
        if (g_nvn_deswz_gpu) { id e3 = [g_up_cb computeCommandEncoder]; m3_wait(e3, 0, 0); g_up_ce = e3; }
    }
    else {
        [g_up_alloc4[slot] reset];
        g_up_cb = [g_dev newCommandBuffer];
        [g_up_cb beginCommandBufferWithAllocator:g_up_alloc4[slot]];
        g_up_ce = [g_up_cb computeCommandEncoder];
        enc_full_barrier_begin(g_up_ce);
        enc_c_table(g_up_ce, g_up_ct);
    }
    if (!g_up_texs) g_up_texs = [NSMutableArray array];
    if (!g_up_keep) g_up_keep = [NSMutableArray array];
}

// Diagnostic readout (low frequency; printed only when the block switch count changed and ≥ 1 second since the last line, at most 200 lines per game): how many times an upload batch ran out of staging block and switched blocks midway; GPU allocated, residency set object count, deferred-release queue length.
// If the old block is not retired on a switch it stays in the residency set and can never be freed, and "GPU allocated" climbs one block at a time with the switch count
static uint64_t g_up_blocks_new, g_up_swaps, g_up_swap_bytes; static NSHashTable *g_up_old;   // g_up_old: old blocks switched out (weak references); the diagnostic line counts how many are still alive
static void up_diag(void) {
    // Print a line when the block switch count changes; then one more line 5 seconds later (that batch's commit is long done and deferred retirement drained, so "GPU allocated" is the settled number)
    static uint64_t said_swaps = ~0ull, last_ns; static int lines, follow; uint64_t now = clock_gettime_nsec_np(CLOCK_MONOTONIC);
    int chg = g_up_swaps != said_swaps, fol = follow && now - last_ns >= 5000000000ull; if ((!chg && !fol) || lines >= 200) return;
    if (chg && last_ns && now - last_ns < 1000000000ull) return; last_ns = now; said_swaps = g_up_swaps; lines++; follow = chg;
    // Own pool: allObjects returns the old blocks (and every resident object) autoreleased, and the submit thread's pool drains only when the submission ends, so a line printed inside one long
    // submission (a frame replay) kept every block alive at that moment until the end
    @autoreleasepool {
    unsigned long alive = 0, inres = 0; uint64_t abytes = 0; NSArray *olds = g_up_old.allObjects;
    pthread_mutex_lock(&g_res_mu); unsigned long nres = (unsigned long)g_res_objects.allObjects.count; for (id<MTLBuffer> o in olds) { alive++; abytes += o.length; inres += [g_res_objects containsObject:o]; } pthread_mutex_unlock(&g_res_mu);
    pthread_mutex_lock(&g_deferred_mu); unsigned long ndef = (unsigned long)g_deferred.count; pthread_mutex_unlock(&g_deferred_mu);
    MLOG("upload staging blocks%s: %llu created in total, swapped within a batch %llu times (%llu MB of old blocks swapped out), batches flushed early at the 256 MB staging cap %llu; swapped-out blocks still alive now %lu, %llu MB, still in the residency set %lu; GPU allocated %llu MB, residency set %lu objects, deferred-release queue %lu", fol && !chg ? " (settled)" : "",
         (unsigned long long)g_up_blocks_new, (unsigned long long)g_up_swaps, (unsigned long long)(g_up_swap_bytes >> 20), (unsigned long long)g_up_cap_flushes, alive, (unsigned long long)(abytes >> 20), inres, (unsigned long long)(g_dev.currentAllocatedSize >> 20), nres, ndef);
    }
}
// Diagnostic-only fork: observe the first failed private upload allocation, then preserve MDIE.
// No recovery, no residency insertion, no GPU command submission/wait, no guest-budget change.
static void up_fail_vm(const char *phase) {
    task_vm_info_data_t t = {0}; mach_msg_type_number_t tc = TASK_VM_INFO_COUNT;
    kern_return_t tk = task_info(mach_task_self(), TASK_VM_INFO, (task_info_t)&t, &tc);
    vm_statistics64_data_t v = {0}; mach_msg_type_number_t vc = HOST_VM_INFO64_COUNT;
    mach_port_t host = mach_host_self();
    kern_return_t vk = host_statistics64(host, HOST_VM_INFO64, (host_info64_t)&v, &vc);
    mach_port_deallocate(mach_task_self(), host);
    unsigned long long avail = 0;
#if TARGET_OS_IPHONE
    avail = (unsigned long long)os_proc_available_memory();
#endif
    MLOG("[up_fail_diag] vm phase=%s task_kr=%d task_count=%u footprint=%llu resident=%llu virtual=%llu internal=%llu compressed=%llu available=%llu host_kr=%d page_size=%u free_pages=%llu active_pages=%llu inactive_pages=%llu wired_pages=%llu compressor_pages=%llu speculative_pages=%llu",
         phase, tk, tc, (unsigned long long)t.phys_footprint, (unsigned long long)t.resident_size, (unsigned long long)t.virtual_size,
         (unsigned long long)t.internal, (unsigned long long)t.compressed, avail, vk, (unsigned)vm_page_size,
         (unsigned long long)v.free_count, (unsigned long long)v.active_count, (unsigned long long)v.inactive_count,
         (unsigned long long)v.wire_count, (unsigned long long)v.compressor_page_count, (unsigned long long)v.speculative_count);
}
// A raw VM-region scan, NOT a claim of GPU-mappable address capacity. The existing runtime
// scan additionally excludes its guest window; use its read-only function if exported.
static void up_fail_holes(size_t n) {
    void (*low)(uint64_t *, uint64_t *) = (void (*)(uint64_t *, uint64_t *))dlsym(RTLD_DEFAULT, "s2a_low_holes");
    if (low) { uint64_t t = 0, b = 0; low(&t, &b); MLOG("[up_fail_diag] runtime_holes total=%llu largest=%llu", (unsigned long long)t, (unsigned long long)b); }
    else MLOG("[up_fail_diag] runtime_holes unavailable; use native crash address ledger");
    uint64_t (*topfn)(void) = (uint64_t (*)(void))dlsym(RTLD_DEFAULT, "s2a_va_top");
    uint64_t top = topfn ? topfn() : 0, hi = 1ull << 39;
    if (top && top < hi) hi = top;
    uint64_t prev = 1ull << 32, total = 0, largest = 0, fit = 0, fit2m = 0, fit32m = 0;
    unsigned regions = 0, holes = 0; kern_return_t kr = KERN_SUCCESS;
    while (prev < hi && regions < 65536) {
        vm_address_t a = (vm_address_t)prev; vm_size_t sz = 0;
        vm_region_basic_info_data_64_t info; mach_msg_type_number_t count = VM_REGION_BASIC_INFO_COUNT_64; mach_port_t obj = MACH_PORT_NULL;
        kr = vm_region_64(mach_task_self(), &a, &sz, VM_REGION_BASIC_INFO_64, (vm_region_info_t)&info, &count, &obj);
        if (MACH_PORT_VALID(obj)) mach_port_deallocate(mach_task_self(), obj);
        if (kr != KERN_SUCCESS && kr != KERN_INVALID_ADDRESS) break;
        uint64_t end = kr == KERN_SUCCESS && a < hi ? a : hi;
        if (end > prev) {
            uint64_t len = end - prev, a2 = (prev + ((1ull << 21) - 1)) & ~((1ull << 21) - 1), a32 = (prev + ((1ull << 25) - 1)) & ~((1ull << 25) - 1);
            holes++; total += len; if (len > largest) largest = len;
            fit += len >= n; fit2m += a2 < end && end - a2 >= n; fit32m += a32 < end && end - a32 >= n;
        }
        if (kr != KERN_SUCCESS || a >= hi) { prev = hi; break; }
        uint64_t next = (uint64_t)a + sz;
        if (next <= prev) break;
        prev = next; regions++;
    }
    MLOG("[up_fail_diag] raw_va top_known=%d scan_end=%#llx complete=%d kr=%d regions=%u holes=%u total=%llu largest=%llu fit=%llu fit_2m_align=%llu fit_32m_align=%llu requested=%zu (raw gaps may include guest/reserved address space)",
         top != 0, (unsigned long long)hi, prev >= hi, kr, regions, holes, (unsigned long long)total, (unsigned long long)largest,
         (unsigned long long)fit, (unsigned long long)fit2m, (unsigned long long)fit32m, n);
}
static void up_fail_probe(const char *label, size_t n, MTLResourceOptions options) {
    const size_t cap = 64u << 20;
    if (!n || n > cap || n > g_dev.maxBufferLength) { MLOG("[up_fail_diag] probe=%s bytes=%zu skipped=length_cap", label, n); return; }
#if TARGET_OS_IPHONE
    size_t avail = os_proc_available_memory();
    if (avail < n + (16u << 20)) { MLOG("[up_fail_diag] probe=%s bytes=%zu skipped=process_headroom available=%zu", label, n, avail); return; }
#endif
    MLOG("[up_fail_diag] probe=%s begin bytes=%zu storage=%lu", label, n, (unsigned long)options);
    unsigned long long before = g_dev.currentAllocatedSize, during = before;
    int ok = 0; uint64_t start = clock_gettime_nsec_np(CLOCK_MONOTONIC);
    @autoreleasepool {
        id<MTLBuffer> b = [g_dev newBufferWithLength:n options:options];
        ok = b != nil; during = g_dev.currentAllocatedSize;
        b = nil;
    }
    MLOG("[up_fail_diag] probe=%s result=%s bytes=%zu elapsed_us=%llu gpu_before=%llu gpu_during=%llu gpu_after=%llu",
         label, ok ? "ok" : "nil", n, (unsigned long long)((clock_gettime_nsec_np(CLOCK_MONOTONIC) - start) / 1000),
         before, during, (unsigned long long)g_dev.currentAllocatedSize);
}
static void up_alloc_failed(const char *site, size_t want, size_t payload, size_t aligned) {
    const char *enabled = getenv("DM_NVN_UPLOAD_DIAG");
    if (enabled && !strcmp(enabled, "0")) return;
    static _Atomic int once;
    if (atomic_exchange(&once, 1)) return;
    MLOG("[up_fail_diag] begin v=1 site=%s request=%zu payload=%zu aligned=%zu m3=%d slot=%u seq=%u pending=%d busy=%d/%d/%d open_batch=%d block_off=%zu block_size=%zu kept_bytes=%llu kept_count=%lu blits=%d textures=%lu new_blocks=%llu swaps=%llu",
         site, want, payload, aligned, g_m3, g_up_cur_slot, g_up_seq, atomic_load(&g_up_pending),
         atomic_load(&g_up_alloc_busy[0]), atomic_load(&g_up_alloc_busy[1]), atomic_load(&g_up_alloc_busy[2]), g_up_cb != nil,
         g_up_block_off, g_up_block_size, (unsigned long long)g_up_keep_bytes, (unsigned long)g_up_keep.count,
         g_nup_blits, (unsigned long)g_up_texs.count, (unsigned long long)g_up_blocks_new, (unsigned long long)g_up_swaps);
    // Count only; never enumerate weak tables or take a blocking renderer lock on this path.
    long res = -1, deferred = -1;
    if (!pthread_mutex_trylock(&g_res_mu)) { res = (long)g_res_objects.count; pthread_mutex_unlock(&g_res_mu); }
    if (!pthread_mutex_trylock(&g_deferred_mu)) { deferred = (long)g_deferred.count; pthread_mutex_unlock(&g_deferred_mu); }
    unsigned long long recommended = 0;
    if (@available(iOS 16.0, macOS 10.12, *)) recommended = g_dev.recommendedMaxWorkingSetSize;
    MLOG("[up_fail_diag] gpu allocated=%llu recommended=%llu max_buffer=%llu residency_count=%ld deferred_count=%ld slot_bytes=%llu/%llu/%llu",
         (unsigned long long)g_dev.currentAllocatedSize, recommended, (unsigned long long)g_dev.maxBufferLength, res, deferred,
         (unsigned long long)g_up_slot_blk[0].length, (unsigned long long)g_up_slot_blk[1].length, (unsigned long long)g_up_slot_blk[2].length);
    up_fail_vm("before");
    up_fail_holes(want);
    // Address reservation only: no writes, no wired pages, never MAP_FIXED.
    if (want && want <= (64u << 20)) {
        MLOG("[up_fail_diag] probe=cpu_reserve begin bytes=%zu", want);
        errno = 0; void *p = mmap(NULL, want, PROT_NONE, MAP_PRIVATE | MAP_ANON, -1, 0);
        int err = p == MAP_FAILED ? errno : 0, released = -1;
        if (p != MAP_FAILED) released = munmap(p, want);
        MLOG("[up_fail_diag] probe=cpu_reserve result=%s bytes=%zu errno=%d release_rc=%d (no page touch)", p == MAP_FAILED ? "fail" : "ok", want, err, released);
    } else MLOG("[up_fail_diag] probe=cpu_reserve skipped=length_cap bytes=%zu", want);
    up_fail_probe("private_64k", 64u << 10, MTLResourceStorageModePrivate);
    up_fail_probe("private_4m", 4u << 20, MTLResourceStorageModePrivate);
    up_fail_probe("shared_same", want, MTLResourceStorageModeShared);
    up_fail_probe("private_same_repeat", want, MTLResourceStorageModePrivate);
    up_fail_vm("after");
    MLOG("[up_fail_diag] end; original fatal follows");
}

static id<MTLBuffer> up_alloc(size_t n, size_t *off) {
    size_t need = (n + 255u) & ~((size_t)255u);
    if (!g_up_block && need <= UP_BLOCK_SIZE) {   // first allocation of the batch: the slot's own block, grown to the next power of two that holds it (a movie frame re-uploaded every frame, 8 MB in Link's Awakening)
        __strong id<MTLBuffer> *sb = &g_up_slot_blk[g_up_cur_slot];
        size_t want = UP_SLOT_BLOCK; while (want < need) want <<= 1;
        if (*sb && (*sb).length < want) { defer_obj_release(*sb); *sb = nil; }   // the slot's previous batch has finished (up_begin waited for it)
        if (!*sb) { *sb = [g_dev newBufferWithLength:want options:MTLResourceStorageModePrivate]; if (!*sb) { up_alloc_failed("slot", want, n, need); MDIE("failed to create the swizzled-upload staging block %#zx", want); } res_add(*sb); g_up_blocks_new++; }
        g_up_block = *sb; g_up_block_size = (*sb).length; g_up_block_off = 0;
    }
    if (!g_up_block || g_up_block_off + need > g_up_block_size) {
        // Block switch: the old block is still referenced by copy / decompress commands already recorded in this batch and cannot be freed on the spot; hand it to g_up_keep, to be retired later with the other staging after the flush commits (removed from the residency set on retire).
        // Previously g_up_block was simply replaced with the new block here: nobody retired the old block, yet it stayed in the residency set, so each extra block switch in an upload batch leaked one block (usually 32 MB) of GPU memory.
        // The old block and the "current block" retired at flush are two objects, so nothing is retired twice
        g_up_blocks_new++; if (g_up_block) { g_up_swaps++; g_up_swap_bytes += g_up_block_size; if (!g_up_old) g_up_old = [NSHashTable weakObjectsHashTable]; [g_up_old addObject:g_up_block]; static int leak = -1; if (leak < 0) leak = getenv("DM_TEST_UP_LEAK") != NULL;   // test switch DM_TEST_UP_LEAK=1: do not retire the old block, as before the fix (for comparison, to measure the leak)
            if (!leak && g_up_block != g_up_slot_blk[g_up_cur_slot]) up_keep_add(g_up_block); }   // the slot's block is not retired: it stays for the slot's later batches
        g_up_block_size = n > UP_BLOCK_SIZE ? need : UP_BLOCK_SIZE;
        g_up_block = [g_dev newBufferWithLength:g_up_block_size options:MTLResourceStorageModePrivate];
        if (!g_up_block) { up_alloc_failed("continuation", g_up_block_size, n, need); MDIE("failed to create the swizzled-upload staging block %#zx", g_up_block_size); }
        res_add(g_up_block);
        g_up_block_off = 0;
    }
    *off = g_up_block_off;
    g_up_block_off += need;
    return g_up_block;
}

// Deswizzle parameter blocks: 64 bytes per cell, cut sequentially from a 64 KB shared-storage block; a full block is replaced by a new one, and the old block is released lazily by fence
static id<MTLBuffer> g_up_pblock; static size_t g_up_pblock_off;
static id<MTLBuffer> up_param_alloc(size_t *off) {
    if (!g_up_pblock || g_up_pblock_off + 64 > g_up_pblock.length) {
        if (g_up_pblock) defer_obj_release(g_up_pblock);
        g_up_pblock = [g_dev newBufferWithLength:64 << 10 options:MTLResourceStorageModeShared];
        if (!g_up_pblock) MDIE("failed to create the deswizzle parameter block");
        res_add(g_up_pblock); g_up_pblock_off = 0;
    }
    *off = g_up_pblock_off; g_up_pblock_off += 64;
    return g_up_pblock;
}
static void up_blit_add_at(id<MTLBuffer> src, size_t off, size_t row, size_t image, MTLSize size,
                           id<MTLTexture> dst, NSUInteger slice, NSUInteger level, NSUInteger x0, NSUInteger y0) {
    if (g_nup_blits == g_up_blitcap) {
        size_t c = g_up_blitcap ? g_up_blitcap * 2 : 256;
        if (!GROW(g_up_blits, c * sizeof *g_up_blits, "texture upload list")) return;   // dropped: this upload is not made (the texture keeps its old content)
        g_up_blitcap = c;
    }
    g_up_blits[g_nup_blits++] = (up_blit){src, off, row, image, size, dst, slice, level, x0, y0};
}
static void up_blit_add(id<MTLBuffer> src, size_t off, size_t row, size_t image, MTLSize size, id<MTLTexture> dst, NSUInteger slice, NSUInteger level) {
    up_blit_add_at(src, off, row, image, size, dst, slice, level, 0, 0);
}

static uint64_t span_hash(const uint8_t *m, size_t n) {   // 8 bytes at a time (the page check runs on every written page): a multiply-xorshift mix, then the tail bytes
    uint64_t h = 0x9e3779b97f4a7c15ull ^ n, w; size_t i = 0;
    for (; i + 8 <= n; i += 8) { memcpy(&w, m + i, 8); h = (h ^ w) * 0xff51afd7ed558ccdull; h ^= h >> 32; }
    for (; i < n; i++) h = (h ^ m[i]) * 0x100000001b3ull;
    return h;
}
// Guest storage bytes as the host can read them (P1-160): a texture's storage address is the guest's (pool->mem + off), and in a far-alias pool (runtime/src/far.c) that address is
//   unmapped — reading it directly faults once per load into the far-fault emulation, or stops the game where an access cannot be emulated. Read the shadow instead (s2a_far_g2h, the
//   one address map). Valid for a span inside one host page (a GOB, a page_span piece): the shadow's 2 MiB blocks are page-aligned. Outside the far region the guest address is the host's
static const uint8_t *host_rd(const uint8_t *g) { const uint8_t *h = s2a_far_g2h((uint64_t)(uintptr_t)g); return h ? h : g; }
static uint64_t gob_hash(uint64_t g) { return span_hash(host_rd((const uint8_t *)(uintptr_t)(g << 9)), 512); }
static void page_span(const tex_t *t, size_t k, const uint8_t **lo, size_t *n) {   // the texture's bytes in host page k of its storage (pages counted from the one holding t->mem)
    uintptr_t pg = nvn_dirty_page_size(), a = (uintptr_t)t->mem, e = a + t->L.size, p0 = a & ~(pg - 1);
    uintptr_t b = MAX(a, p0 + k * pg), c = MIN(e, p0 + (k + 1) * pg); *lo = (const uint8_t *)b; *n = c > b ? c - b : 0;
}
static uint32_t page_count(const tex_t *t) { uintptr_t pg = nvn_dirty_page_size(), a = (uintptr_t)t->mem; return t->L.size ? (uint32_t)(((a + t->L.size - 1) & ~(pg - 1)) - (a & ~(pg - 1))) / (uint32_t)pg + 1 : 0; }
static unsigned tex_layers(const tex_t *t) { return (t->d.target == 4 || t->d.target == 9) ? t->d.depth : t->d.target == 8 ? 6 : t->d.target == 3 ? t->d.height : 1; }   // as pkg_upload_ (a cube array's depth counts layer-faces)
// Block-linear storage (Tegra X1): each layer holds its levels one after another; a level is rows of blocks, a block 2^tileH GOBs tall and one GOB (64 bytes x 8 rows of format blocks) wide,
// laid out GOB column after GOB column. So a byte range of one block row is a run of GOB columns: a texel rectangle. fn gets (level, layer, x, y, w, h) in texels for every rectangle [lo, hi)
// (storage offsets) touches. 3D, deep-tiled (tileD), multisampled or unlaid-out levels: the whole level
typedef void (*rect_fn)(void *u, unsigned level, unsigned layer, uint32_t x, uint32_t y, uint32_t w, uint32_t h);
static void tex_bytes_rects(const tex_t *t, uint64_t lo, uint64_t hi, rect_fn fn, void *u) {
    int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh); if (!bpb || 64 % bpb) return;
    unsigned layers = tex_layers(t), nl = t->d.levels ? t->d.levels : 1; uint64_t ls = t->L.layer_size ? t->L.layer_size : t->L.size;
    for (unsigned y = 0; y < layers; y++) for (unsigned l = 0; l < nl; l++) {
        uint64_t a = (uint64_t)y * ls + nvn_tex_level_offset(&t->d, l), e = l + 1 < nl ? (uint64_t)y * ls + nvn_tex_level_offset(&t->d, l + 1) : (uint64_t)(y + 1) * ls;
        if (hi <= a || lo >= e) continue;
        uint32_t w = MAX(t->d.width >> l, 1u), h = MAX(t->d.height >> l, 1u); unsigned th = 0, td = 0; nvn_tex_level_tiles(&t->d, l, &th, &td); uint32_t gobs = nvn_tex_level_gobs(&t->d, l);
        if (t->d.target == 2 || td || t->d.samples > 1 || !gobs) { fn(u, l, y, 0, 0, w, h); continue; }
        uint64_t blk = 512ull << th, row = (uint64_t)gobs * blk, b0 = MAX(lo, a) - a, b1 = MIN(hi, e) - a;
        uint32_t cw = (uint32_t)(64 / bpb) * (uint32_t)bw, rh = (8u << th) * (uint32_t)bh;   // texels one GOB column / one block row spans
        for (uint64_t r = b0 / row; r * row < b1; r++) {
