            uint32_t x = (uint32_t)(c0 * cw), yy = (uint32_t)(r * rh);
            if (x < w && yy < h) fn(u, l, y, x, yy, MIN((uint32_t)((c1 - c0) * cw), w - x), MIN(rh, h - yy));
