}
// The other way: the storage bytes of a texel rectangle of a level, as one byte range per block row (whole level for the cases above); fn(lo, hi)
typedef void (*range_fn)(void *u, uint64_t lo, uint64_t hi);
static void tex_rect_bytes(const tex_t *t, unsigned l, unsigned layer, uint32_t x, uint32_t y, uint32_t w, uint32_t h, range_fn fn, void *u) {
    int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh); unsigned nl = t->d.levels ? t->d.levels : 1; if (!bpb || 64 % bpb || l >= nl) return;
    uint64_t ls = t->L.layer_size ? t->L.layer_size : t->L.size, a = (uint64_t)layer * ls + nvn_tex_level_offset(&t->d, l), e = l + 1 < nl ? (uint64_t)layer * ls + nvn_tex_level_offset(&t->d, l + 1) : (uint64_t)(layer + 1) * ls;
    unsigned th = 0, td = 0; nvn_tex_level_tiles(&t->d, l, &th, &td); uint32_t gobs = nvn_tex_level_gobs(&t->d, l);
    if (t->d.target == 2 || td || t->d.samples > 1 || !gobs || !w || !h) { fn(u, a, e); return; }
    uint64_t blk = 512ull << th, row = (uint64_t)gobs * blk; uint32_t cw = (uint32_t)(64 / bpb) * (uint32_t)bw, rh = (8u << th) * (uint32_t)bh;
    for (uint32_t r = y / rh; r * rh < y + h; r++) fn(u, a + r * row + (x / cw) * blk, MIN(e, a + r * row + ((x + w + cw - 1) / cw) * blk));
}
typedef struct { const tex_t *t; uint64_t *pgpu, now; uint32_t n; } gw_ctx;
static void gw_mark(void *u, uint64_t lo, uint64_t hi) {   // pages of storage [lo, hi) get the GPU write generation
    gw_ctx *c = u; uintptr_t pg = nvn_dirty_page_size(), p0 = (uintptr_t)c->t->mem & ~(pg - 1);
    for (uintptr_t k = ((uintptr_t)c->t->mem + lo - p0) / pg; k < c->n && p0 + k * pg < (uintptr_t)c->t->mem + hi; k++) c->pgpu[k] = c->now;
}
// A copy or clear wrote texel rectangle (x, y, w, h) of layers [layer0, layer0 + nlayers) of level `level` (w / h 0 = the whole level): note the generation on its pages (see NvPkg pgpu)
static void pkg_gpu_wrote(const tex_t *t, unsigned level, unsigned layer0, unsigned nlayers, uint32_t x, uint32_t y, uint32_t w, uint32_t h);
static id<MTLTexture> pkg_upload_(const tex_t *t, uint64_t *stamp, id<MTLTexture> reuse, uint64_t **ph, uint32_t *nph);
int nvn_host_readable(uint64_t a, uint64_t n);   // hle_nvn.c: guest memory and sparse pools
int nvn_sparse_pool(const void *pool); uint64_t nvn_sparse_gen(void); uint64_t nvn_sparse_copy(const void *pool, void *dst, uint64_t a, uint64_t n);
int nvn_sparse_since(const void *pool, uint64_t a, uint64_t n, uint64_t gen, uint64_t stamp); void nvn_sparse_protect(const void *pool, uint64_t a, uint64_t n); int nvn_sparse_mapped(const void *pool, uint64_t a, uint64_t n);
static id<MTLTexture> pkg_upload(const tex_t *t, uint64_t *stamp, id<MTLTexture> reuse, uint64_t **ph, uint32_t *nph) {   // reuse: a texture of the same description, idle on the GPU, to upload into instead of a new one; ph / nph: per-page hashes (NvPkg), or NULL
    struct timespec a, b; clock_gettime(CLOCK_MONOTONIC, &a);
    id<MTLTexture> r = pkg_upload_(t, stamp, reuse, ph, nph);
    clock_gettime(CLOCK_MONOTONIC, &b); uint64_t d_ = (uint64_t)((b.tv_sec - a.tv_sec) * 1000000000ll + b.tv_nsec - a.tv_nsec);
    atomic_fetch_add(&g_upload_ns, d_); g_up_total_ns += d_;
    return r;
}
uint64_t nvn_be_upload_ns_take(void) { return atomic_exchange(&g_upload_ns, 0); }
uint64_t nvn_be_upload_gpu_ns_take(void) { return atomic_exchange(&g_upload_gpu_ns, 0); }
void nvn_be_create_stats(uint64_t *lib, uint64_t *pso) { *lib = g_bp_lib_n; *pso = g_bp_pso_n; }
void nvn_be_create_ns(uint64_t *lib_ns, uint64_t *pso_ns) { *lib_ns = g_bp_lib_ns; *pso_ns = g_bp_pso_ns; }   // Cumulative submit-thread shader load (construction or shared wait) / pipeline time; the long-frame log takes per-frame differences
uint64_t nvn_be_upload_bytes(void) { return g_bp_up_bytes; }   // Cumulative texture upload bytes
// Diagnostic DM_NVN_ZBLOCK=1: all-zero 16-byte blocks of each ASTC texture uploaded on the CPU, per level (an all-zero ASTC block decodes as the error colour, magenta). tex_mtl_ logs
// a texture whose bound levels hold any (zb_report), with each level's zero blocks, its total and whether all its pages are mapped (sparse pools)
static int zblock_on(void) { static int v = -1; if (v < 0) { v = getenv("DM_NVN_ZBLOCK") != NULL; if (v) MLOG("DM_NVN_ZBLOCK: counting all-zero blocks of ASTC textures at upload (diagnostic)"); } return v; }
static uint64_t g_zb_ser; static uint32_t g_zb[16], g_zb_tot[16]; static int g_zb_n;
static void zb_report(const tex_t *t, unsigned base, const char *why) {
    if (!zblock_on() || g_zb_ser != t->serial) return;
    int bad = 0; for (int l = (int)base; l < g_zb_n; l++) bad |= g_zb[l] != 0;
    g_zb_ser = 0; if (!bad) return;
    static int nl; if (nl++ >= 400) return;
    char b[512]; size_t o = 0; int sp = t->pool && nvn_sparse_pool(t->pool);
    for (int l = 0; l < g_zb_n && o < sizeof b - 48; l++) { uint64_t lo = nvn_tex_level_offset(&t->d, (unsigned)l), hi = l + 1 < (int)t->d.levels ? nvn_tex_level_offset(&t->d, (unsigned)l + 1) : t->L.size;
        o += (size_t)snprintf(b + o, sizeof b - o, " L%d %u/%u%s", l, g_zb[l], g_zb_tot[l], sp ? (nvn_sparse_mapped(t->pool, (uint64_t)(uintptr_t)t->mem + lo, hi - lo) ? "" : " unmapped") : ""); }
    MLOG("[zb] %s ser=%llu format %#x %ux%u levels %u flags %#x mem=%p size %#llx sparse %d bound from level %u frame %llu:%s", why, (unsigned long long)t->serial, t->d.format, t->d.width, t->d.height, t->d.levels,
         t->d.flags, t->mem, (unsigned long long)t->L.size, sp, base, (unsigned long long)atomic_load(&g_cur_frame), b);
    const char *dir = getenv("DM_NVN_ZBLOCK"); static int nd; static uint64_t seen[16];   // DM_NVN_ZBLOCK=<folder>: also the raw storage of the first such texture of each format and size (up to 16), zb_<serial>.bin (unmapped pages as 0)
    uint64_t kind = (uint64_t)t->d.format << 48 | (uint64_t)t->d.width << 24 | t->d.height; int dup = 0; for (int i = 0; i < nd; i++) dup |= seen[i] == kind;
    if (dir && dir[0] == '/' && nd < 16 && !dup) { seen[nd] = kind; uint64_t n = sp ? MAX(t->L.size, 2u << 20) : t->L.size; uint8_t *m = malloc(n); char fp[1024]; FILE *f;   // a sparse texture: 2 MB, and zbm_<serial>.bin a byte per 4 KB page (1 mapped)
        if (m) { if (sp) nvn_sparse_copy(t->pool, m, (uint64_t)(uintptr_t)t->mem, n); else memcpy(m, t->mem, n);
            snprintf(fp, sizeof fp, "%s/zb_%llu.bin", dir, (unsigned long long)t->serial); if ((f = fopen(fp, "wb"))) { fwrite(m, 1, n, f); fclose(f); nd++; }
            if (sp) { for (uint64_t o = 0; o < n; o += 0x1000) m[o >> 12] = (uint8_t)nvn_sparse_mapped(t->pool, (uint64_t)(uintptr_t)t->mem + o, 0x1000);
                snprintf(fp, sizeof fp, "%s/zbm_%llu.bin", dir, (unsigned long long)t->serial); if ((f = fopen(fp, "wb"))) { fwrite(m, 1, n >> 12, f); fclose(f); } }
            free(m); }
        MLOG("[zb] ser=%llu: block height log2 %d (packaged %d), stride %u, depth %u, target %d, samples %d", (unsigned long long)t->serial, (int)t->L.tileH, t->d.pkg_block_h, t->d.stride, t->d.depth, t->d.target, t->d.samples); }
}
// The GPU deswizzle's source for a texture in a pool that holds only textures (no address given out, addr_meets; not resident yet): a zero-copy buffer over just this texture's pages, held by the
// open upload batch (g_up_keep), which takes it out of the residency set when the upload has run. Looked up as usual (nvn_be_addr → pool_res), such a pool went into the residency set whole and
// stayed: iOS reads a resident zero-copy buffer in and wires it, so every pool one texture was ever uploaded from stayed wired. Upstream reference implementation (MIT) 1d4b8e82 / b1d7c707
// up_big_src: in Ocarina of Time's first scene pools that hold only textures took 4.6 GB of the working set against 1.6 GB for the textures made from them; S2Arm 11-06 on a 17 Pro Max, without
// the raw pool table, single command buffers needed 5.1-5.8 GB against the 8 GB maxWired. Large pools in chunks and placement heaps (the rest of up_big_src) are not here. nil: look it up as
// before (outside a pool, an addressed or resident pool, or the buffer refused). Call after up_begin: a flush there would retire it before the copies that read it
static uint64_t g_up_src_n, g_up_src_bytes;   // such sources made, and their bytes (the memory readout)
static id<MTLBuffer> up_tex_src(uint64_t addr, uint64_t len, uint64_t *off) {
    if (!len) return nil;
    pthread_mutex_lock(&g_mu);
    int i = pool_find(addr, len), in = i >= 0 && !g_pools[i].res && !addr_meets(g_pools[i].lo, g_pools[i].hi);
    uintptr_t base = in ? g_pools[i].base : 0, host = in ? g_pools[i].host : 0;
    pthread_mutex_unlock(&g_mu);
    if (!in) return nil;
    // the pool's host bytes as its buffer has them (a far-alias pool: its shadow, or the one view of a split shadow, pool_host); the pool's buffer keeps a view alive past this one
    uintptr_t pg = (uintptr_t)getpagesize(), a = (uintptr_t)addr & ~(pg - 1), b = ((uintptr_t)addr + len + pg - 1) & ~(pg - 1), ha = host + (a - base);
    id<MTLBuffer> buf = [g_dev newBufferWithBytesNoCopy:(void *)ha length:b - a options:MTLResourceStorageModeShared deallocator:nil];
    if (!buf) return nil;
