        id<MTLBuffer> b = [g_dev newBufferWithLength:n options:MTLResourceStorageModeShared];
        if (!b) return nil;
        memset(b.contents, poison ? 0x3c : 0, n); res_add(b);
        if (zb[poison]) defer_obj_release(zb[poison]);
        zb[poison] = b; zn[poison] = n;
    }
