static id<MTLBuffer> zero_buf(size_t need) { return fill_buf(need, 0); }
static uint64_t g_tex_zeroed;
static void tex_fill(id<MTLTexture> mt, int poison);
static int wd_poison(void);
static void tex_zero_fill(id<MTLTexture> mt) { tex_fill(mt, wd_poison() == 2); }   // S2A_WIDEN_POISON=2: every new texture, not only widened storages
// S2Arm widen diagnostic S2A_WIDEN_POISON=1: a widened storage starts as bytes of 0x3c instead of 0 (f16 ≈ 1.06, RGBA8 60): in a one-frame replay, columns of the widened strip that are
//   read but never written this frame show up, which on a device hold another frame's or another texture's content (11-02 Mario Party: coloured blocks top right on the device only)
static int wd_poison(void) { static int on = -1; if (on < 0) { const char *e = getenv("S2A_WIDEN_POISON"); on = e && (!strcmp(e, "1") || !strcmp(e, "2")) ? atoi(e) : 0; } return on; }
static void tex_fill(id<MTLTexture> mt, int poison) {
