            uint64_t lo = MAX(a + i * pg, (uint64_t)(uintptr_t)p), hi = MIN(a + (i + 1) * pg, (uint64_t)(uintptr_t)p + n);
            if (!(vec[i] & (MINCORE_INCORE | MINCORE_PAGED_OUT))) { skipped += hi - lo; continue; }
