        unsigned i = (unsigned)(g & 511); b->bits[i >> 6] |= 1ull << (i & 63); b->h[i] = gob_hash(g);
    }
}
static void gpw_unmark(uint64_t g) {   // under g_gpw_mu: GOB g is current again
    uint64_t k = g >> 9; gpw_blk *b = nvn_hm_get(&g_gpw, &k); unsigned i = (unsigned)(g & 511);
    if (!b || !(b->bits[i >> 6] >> (i & 63) & 1)) return;
    b->bits[i >> 6] &= ~(1ull << (i & 63)); g_gpw_gen++;   // marks deduplicated before this are taken again (gpw_mark)
    uint64_t any = 0; for (int w = 0; w < 8; w++) any |= b->bits[w];
    if (!any) { nvn_hm_del(&g_gpw, &k); free(b); atomic_fetch_sub(&g_gpw_nblk, 1); }
}
static void gpw_clear(uint64_t lo, uint64_t n) {   // this backend's GPU wrote guest memory [lo, lo + n) (buffer copy / fill / update, transform feedback, texture→buffer copy)
    if (!n || !atomic_load_explicit(&g_gpw_nblk, memory_order_relaxed)) return;
    pthread_mutex_lock(&g_gpw_mu);
    for (uint64_t g = lo >> 9, ge = (lo + n + 511) >> 9; g < ge; g++) {
        uint64_t k = g >> 9; if (!nvn_hm_get(&g_gpw, &k)) { g = (k << 9) + 511; continue; }
        gpw_unmark(g);
    }
    pthread_mutex_unlock(&g_gpw_mu);
}
