    if (!w || !h) { x = y = 0; w = lw; h = lh; }
    if (t->d.target == 2 || td || t->d.samples > 1 || !gobs || (x == 0 && y == 0 && w >= lw && h >= lh)) { fn(u, a, e); return; }
    uint64_t blk = 512ull << th, row = (uint64_t)gobs * blk; uint32_t cw = (uint32_t)(64 / bpb) * (uint32_t)bw, gh = 8u * (uint32_t)bh, rh = gh << th;
    for (uint32_t r = y / rh; r * rh < y + h; r++) {
        uint32_t y0 = MAX(y, r * rh) - r * rh, y1 = MIN(y + h, (r + 1) * rh) - r * rh, g0 = y0 / gh, g1 = (y1 + gh - 1) / gh;
