        if (g0 == 0 && g1 == (1u << th)) { fn(u, rb + c0 * blk, MIN(e, rb + c1 * blk)); continue; }
        for (uint64_t c = c0; c < c1; c++) fn(u, rb + c * blk + g0 * 512ull, MIN(e, rb + c * blk + g1 * 512ull));
