}
// The other way at GOB precision: storage offsets [lo, hi) → texel rectangles fn(level, layer, x, y, w, h); a GOB touched in part counts whole. Whole level for the cases tex_rect_gobs takes whole
static void tex_bytes_gobs(const tex_t *t, uint64_t lo, uint64_t hi, rect_fn fn, void *u) {
    int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh); if (!bpb || 64 % bpb) return;
    unsigned layers = tex_layers(t), nl = t->d.levels ? t->d.levels : 1; uint64_t ls = t->L.layer_size ? t->L.layer_size : t->L.size;
    for (unsigned y = 0; y < layers; y++) for (unsigned l = 0; l < nl; l++) {
        uint64_t a = (uint64_t)y * ls + nvn_tex_level_offset(&t->d, l), e = l + 1 < nl ? (uint64_t)y * ls + nvn_tex_level_offset(&t->d, l + 1) : (uint64_t)(y + 1) * ls;
        if (hi <= a || lo >= e) continue;
        uint32_t w = MAX(t->d.width >> l, 1u), h = MAX(t->d.height >> l, 1u); unsigned th = 0, td = 0; nvn_tex_level_tiles(&t->d, l, &th, &td); uint32_t gobs = nvn_tex_level_gobs(&t->d, l);
        if (t->d.target == 2 || td || t->d.samples > 1 || !gobs) { fn(u, l, y, 0, 0, w, h); continue; }
        uint64_t blk = 512ull << th, b0 = MAX(lo, a) - a, b1 = MIN(hi, e) - a; uint32_t cw = (uint32_t)(64 / bpb) * (uint32_t)bw, gh = 8u * (uint32_t)bh, rh = gh << th;
        uint64_t run_c = 0, run_n = 0, run_r = 0; uint32_t run_g0 = 0, run_g1 = 0;
        for (uint64_t B = b0 / blk; B * blk < b1; B++) {
            uint32_t g0 = (uint32_t)((MAX(b0, B * blk) - B * blk) / 512), g1 = (uint32_t)((MIN(b1, (B + 1) * blk) - B * blk + 511) / 512);
            uint64_t r = B / gobs, c = B % gobs;
            if (run_n && r == run_r && c == run_c + run_n && g0 == run_g0 && g1 == run_g1) { run_n++; continue; }
            if (run_n) { uint32_t rx = (uint32_t)(run_c * cw), ry = (uint32_t)(run_r * rh) + run_g0 * gh; if (rx < w && ry < h) fn(u, l, y, rx, ry, MIN((uint32_t)(run_n * cw), w - rx), MIN((run_g1 - run_g0) * gh, h - ry)); }
            run_c = c; run_n = 1; run_r = r; run_g0 = g0; run_g1 = g1;
        }
        if (run_n) { uint32_t rx = (uint32_t)(run_c * cw), ry = (uint32_t)(run_r * rh) + run_g0 * gh; if (rx < w && ry < h) fn(u, l, y, rx, ry, MIN((uint32_t)(run_n * cw), w - rx), MIN((run_g1 - run_g0) * gh, h - ry)); }
    }
}
// Which textures the GPU wrote (nvn_be_tex_gpu_owned asks): serial → its storage range, noted by gpw_mark. size 0 = written where the ledger keeps no GOBs (no pool, a virtual / sparse pool):
//   such a texture counts as GPU content for good. Dropped with the texture (gpw_forget)
typedef struct { const uint8_t *mem; uint64_t size; } gpw_own;
static nvn_hmap g_gpw_own = {.klen = 8};
static void gpw_own_note(const tex_t *t, uint64_t size) {   // under g_gpw_mu
    gpw_own *o = nvn_hm_get(&g_gpw_own, &t->serial);
    if (!o) { if (!(o = calloc(1, sizeof *o))) MDIE("GPU-written texture table allocation failed"); nvn_hm_put(&g_gpw_own, &t->serial, o); }
    o->mem = t->mem; o->size = size;
}
// 块压缩贴图的未压缩别名（11-06 无人深空：植物 / 晶体 / 树干表面彩虹噪点）。游戏在 GPU 上压缩程序生成的贴图：计算着色器 genmipmap_comp_compressbc1 / 5 / 7
//   往一张 RG32UI / RGBA32UI 图像里写，一个像素正好是一个 BC 块，每层一个图像视图；采样的是同一段存储上的 BC1 / BC5 / BC7 贴图。Switch 上两者就是同一段内存，这里是两张
//   Metal 贴图：BC 贴图拿的是游戏内存里的旧字节（tex_cpu_content 把它当 CPU 写过的），解出来是噪点。按 Ryujinx 贴图缓存「格式不同、可按字节拷的重叠贴图」的做法：
//   ① 写：未压缩贴图被 GPU 写过（gpw_mark：附件、图像写、拷贝 / 清除目的）时，若它的像素字节数可能等于某种块的字节数（8 / 16），按存储地址记下这一层的写入代数和写它的贴图（g_bcal）；
//   ② 读：BC 贴图解析时（tex_mtl），同 pool、同偏移、每层块数一致、像素字节 = 块字节、块高一致的写入里，比它已同步的代数新的层，按层「未压缩贴图 → 缓冲 → BC 贴图」逐字节拷过来
//      （bcal_sync，与 bcrt_flush 同一手法，在命令顺序里排在那次写之后）；游戏内存在那之后被 CPU 改写过的层（gpw_stale 认为已不陈旧）不拷，以 CPU 的为准；
//   ③ 有 BC 贴图解析过的存储（g_bcal_seen，不论那时有没有写过）再被写时 g_ser_gen 前进，贴图编号的视图缓存走慢路径重新解析，增量同步；
//      tex_cpu_content 不再把这种存储上的 BC 贴图当 CPU 写过的。
//   热路径（11-06 维护者审）：tex_mtl 每帧几千次解析 BC 贴图、gpw_mark 每遍都记 RGBA16F 之类的写，常规情形都不加全局锁：
//   写侧按存储地址的直接映射缓存（g_bcal_wc）找到记账，同一写入者、同一形状只原子地记代数；解析侧「这段存储登记过」「这里没记账」「这张已同步到最新」各一个无锁判定，
//   只在第一次、或真有新写时走 g_bcal_mu 下的慢路。
enum { BCAL_C = 4096 };   // 直接映射缓存的槽数（存储地址按 GOB 取散列；撞槽只是多走一次慢路）
typedef struct bcal_e {
    uint64_t key;                        // 存储地址（0 = 空闲，在 g_bcal_free 里）
    _Atomic uint64_t seq;                // w 的顺序锁：奇数 = 正在改（慢路，g_bcal_mu 下）
    tex_t w; const pool_t *wpool; uint64_t wshape;   // 最近一次写它的贴图（描述 + 存储）与形状键；写入者序号另存 wser
    _Atomic uint64_t wser, lgen[16], maxgen;          // 各层最近一次写的代数（0 = 没写过）、其中最大的
    _Atomic int seen;                    // 这段存储上解析过 BC 贴图：再写时 g_ser_gen 前进（③）
    _Atomic uint64_t s_ser, s_gen; const void *_Atomic s_r;   // 最近一次同步：哪张 BC 贴图、同步到的代数、它当时解析成的 Metal 贴图（无锁的「已是最新」判定）
    struct bcal_e *next_free;
} bcal_e;
typedef struct { const void *dst; uint64_t lgen[16]; } bcal_s;   // 一张 BC 贴图已同步到的各层代数：目标 Metal 贴图变了（整张重新上传）就从头来
static nvn_hmap g_bcal = {.klen = 8}, g_bcal_sync = {.klen = 8}, g_bcal_seen = {.klen = 8};   // 存储地址 → bcal_e *；BC 贴图序号 → bcal_s *；解析过 BC 贴图的存储地址 → 它的内存池（都在 g_bcal_mu 下）
static pthread_mutex_t g_bcal_mu = PTHREAD_MUTEX_INITIALIZER; static _Atomic uint64_t g_bcal_n, g_bcal_gen, g_bcal_cgen; static uint64_t g_bcal_copies; static bcal_e *g_bcal_free;
static bcal_e *_Atomic g_bcal_wc[BCAL_C];          // 存储地址 → 记账（正向缓存；以 key 核对）
static _Atomic uint64_t g_bcal_neg[BCAL_C], g_bcal_seen_c[BCAL_C];   // 「这里没记账」：地址 | 建账代数 << 48（建了新账就整体失效）；「登记过」：地址
static int g_bcal_off;   // 单测负对照：关掉同步
static inline unsigned bcal_h(uint64_t k) { return (unsigned)(((k >> 9) * 0x9E3779B97F4A7C15ull) >> 52) & (BCAL_C - 1); }
static inline uint64_t bcal_shape(const tex_t *t) { return (uint64_t)(t->d.format & 0xff) | (uint64_t)(t->d.width & 0xffff) << 8 | (uint64_t)(t->d.height & 0xffff) << 24 | (uint64_t)(t->d.levels & 31) << 40 | (uint64_t)(t->L.tileH & 7) << 45; }
static int bcal_writer(const tex_t *t) {
    int bw = 1, bh = 1, b = t->mem && !fmt_compressed(t->d.format) ? nvn_fmt_bpb(t->d.format, &bw, &bh) : 0;
    return (b == 8 || b == 16) && bw == 1 && bh == 1 && t->d.target == NVN_TEXTURE_TARGET_2D && t->d.samples <= 1 && t->d.levels <= 16;
}
static void bcal_note(const tex_t *t, unsigned level) {
