    bcal_e *e = atomic_load_explicit(&g_bcal_wc[h], memory_order_acquire);
    if (!e || e->key != k || atomic_load_explicit(&e->wser, memory_order_relaxed) != t->serial || e->wshape != sh || e->wpool != t->pool) {   // 慢路：新存储、换写入者或换形状
