}
// 写 w 的第 l 层能不能按字节当成 BC 贴图 t 的第 l 层：同 pool、同存储、像素字节 = 块字节、块高一致、这一层的块数一致
static int bcal_level_ok(const tex_t *w, const tex_t *t, unsigned l) {
    int bw = 1, bh = 1, b = nvn_fmt_bpb(t->d.format, &bw, &bh), uw = 1, uh = 1, ub = nvn_fmt_bpb(w->d.format, &uw, &uh);
    if (!b || b != ub || bw < 2 || w->pool != t->pool || w->mem != t->mem || w->L.tileH != t->L.tileH || w->d.target != t->d.target) return 0;
    if (l >= (w->d.levels ? w->d.levels : 1) || l >= (t->d.levels ? t->d.levels : 1)) return 0;
    uint32_t tw = (MAX(t->d.width >> l, 1u) + (uint32_t)bw - 1) / (uint32_t)bw, th = (MAX(t->d.height >> l, 1u) + (uint32_t)bh - 1) / (uint32_t)bh;
    return l ? tw == MAX(w->d.width >> l, 1u) && th == MAX(w->d.height >> l, 1u) : tw == w->d.width && th == w->d.height;
}
static int gpw_stale(const uint8_t *mem, uint64_t size, uint64_t **runs, uint64_t *bytes);
// t（块压缩）的存储有可按字节同步过来、且之后没被 CPU 改写的 GPU 写（tex_cpu_content）：CPU 后来写进的（游戏把这段存储换给了从文件读的贴图）照旧按 CPU 写过的上传
static int bcal_has(const tex_t *t) {
    if (!atomic_load_explicit(&g_bcal_n, memory_order_relaxed) || !t->mem || !fmt_compressed(t->d.format)) return 0;
    uint64_t k = (uint64_t)(uintptr_t)t->mem; int r = 0;
    pthread_mutex_lock(&g_bcal_mu); bcal_e *e = nvn_hm_get(&g_bcal, &k);
    if (e) { tex_t w; uint64_t lg[16]; bcal_snap(e, &w, lg); for (unsigned l = 0; l < 16 && !r; l++) r = lg[l] && bcal_level_ok(&w, t, l); }
    pthread_mutex_unlock(&g_bcal_mu);
