    if (whole && !dd && (dd = calloc(1, sizeof *dd + ((size_t)nl * layers + 63) / 64 * 8))) { dd->n = nl * layers; nvn_hm_put(&g_gpw_ser, &t->serial, dd); }
    if (dd && dd->gen != g_gpw_gen) { memset(dd->bits, 0, (dd->n + 63) / 64 * 8); dd->gen = g_gpw_gen; }
    for (unsigned k = layer0; k < layer0 + nlayers; k++) {
