static void gpw_forget(uint64_t serial) {   // the texture is gone: its bytes stay as they are (a later texture over that memory checks the GOBs, not the serial)
    bcal_forget(serial);
    pthread_mutex_lock(&g_gpw_mu); gpw_dd *dd = nvn_hm_get(&g_gpw_ser, &serial); if (dd) { nvn_hm_del(&g_gpw_ser, &serial); free(dd); }
    gpw_own *o = nvn_hm_get(&g_gpw_own, &serial); if (o) { nvn_hm_del(&g_gpw_own, &serial); free(o); } pthread_mutex_unlock(&g_gpw_mu);
}
// The stale runs of [mem, mem + size) as offsets (malloc'd pairs, the caller frees), after dropping GOBs whose bytes changed since they were marked (current again); returns the run count, *bytes their total
static int gpw_stale(const uint8_t *mem, uint64_t size, uint64_t **runs, uint64_t *bytes) {
    uint64_t a = (uint64_t)(uintptr_t)mem, e = a + size, *r = NULL; int n = 0, cap = 0; *runs = NULL; *bytes = 0;
    if (!atomic_load_explicit(&g_gpw_nblk, memory_order_relaxed)) return 0;
    pthread_mutex_lock(&g_gpw_mu);
    for (uint64_t g = a >> 9, ge = (e + 511) >> 9; g < ge; g++) {
        uint64_t k = g >> 9; gpw_blk *b = nvn_hm_get(&g_gpw, &k); if (!b) { g = (k << 9) + 511; continue; }
        unsigned i = (unsigned)(g & 511); if (!(b->bits[i >> 6] >> (i & 63) & 1)) continue;
        if (gob_hash(g) != b->h[i]) { gpw_unmark(g); continue; }   // rewritten since (by the CPU or anything else that writes guest memory)
        uint64_t lo = MAX(g << 9, a) - a, hi = MIN((g + 1) << 9, e) - a;
