// A texture's content is in the guest's bit order (what its packed-format swizzle is for, nvn_fmt_to_mtl): built on the pool buffer (tex_linear), packaged (NvPkg), or holding only
//   what was taken from its storage — no GPU write on record over its bytes (the write ledger, gpw_stale). Anything the GPU wrote into it is in Metal's order
static int tex_guest_order(const tex_t *t, id<MTLTexture> base) {
    if (base.buffer || [tex_get(t->serial) isKindOfClass:[NvPkg class]]) return 1;
    if (!t->mem || !t->L.size) return 0;
    uint64_t *runs = NULL, b = 0; int n = gpw_stale(t->mem, t->L.size, &runs, &b); free(runs);
    return n == 0;
}
// Zero the texels of the stale runs in a texture just filled from its storage: copies from the shared zero buffer, after the fill's own in the upload batch (a stale GOB reads as the zero fill
// would give it). zn: pass 1 sums the largest copy, pass 2 records them
typedef struct { const tex_t *t; id<MTLTexture> mt; id<MTLBuffer> zb; size_t need; int bw, bh, bpb; size_t bpp; uint64_t blits; } gz_ctx;
static void gpw_zero_rect(void *u, unsigned level, unsigned layer, uint32_t x, uint32_t y, uint32_t w, uint32_t h) {
    gz_ctx *c = u; uint32_t z = c->t->d.target == 2 ? MAX(c->t->d.depth >> level, 1u) : 1;
    size_t row = c->bpp ? (size_t)w * c->bpp : (size_t)((w + c->bw - 1) / c->bw) * c->bpb, rows = c->bpp ? h : (h + c->bh - 1) / c->bh;
    if (!c->zb) { c->need = MAX(c->need, row * rows * z); return; }
    up_blit_add_at(c->zb, 0, row, row * rows, MTLSizeMake(w, h, z), c->mt, c->t->d.target == 2 ? 0 : layer, level, x, y); c->blits++;
}
// Whether the storage of a floating-point texture holds an Inf / NaN (stops at the first; other formats: 0). Splatoon 3 (10-28, test device 1 and the Mac): at the plaza switch the game
// frees its lobby pools and builds a 256×256 R11G11B10F cube map array (13 cubes, 6 levels) for its reflections over that memory; what the CPU had left there gave it 0.30–1.60 M
// Inf / NaN of 6.87 M. Every level and face is drawn over that same frame, and still the exposure locked white: 25 runs on the Mac, all 15 that locked had that fill, none of the 10
// that did not (the array landed on fresh memory, all zero). Bytes earlier GPU textures covered are left out by gpw_stale already; these no texture had ever covered.
// No finite float image data holds these encodings, so such storage is not taken as initial content (DM_NVN_NONFINITE_FILL=1 takes it as before, A/B only)
static int fill_nonfinite(const tex_t *t, const uint8_t *p, id<MTLTexture> mt) {   // p: the bytes the fill would take (the storage, or its copy with the stale runs zeroed)
    int pf = (int)mt.pixelFormat; uint64_t n;
    if (pf == MTLPixelFormatRG11B10Float) { n = t->L.size / 4; for (uint64_t i = 0; i < n; i++) { uint32_t v; memcpy(&v, p + i * 4, 4); if (((v >> 6) & 31) == 31 || ((v >> 17) & 31) == 31 || ((v >> 27) & 31) == 31) return 1; } }
    else if (pf == MTLPixelFormatRGBA16Float || pf == MTLPixelFormatRG16Float || pf == MTLPixelFormatR16Float) { n = t->L.size / 2; for (uint64_t i = 0; i < n; i++) { uint16_t v; memcpy(&v, p + i * 2, 2); if (((v >> 10) & 31) == 31) return 1; } }
    else if (pf == MTLPixelFormatRGBA32Float || pf == MTLPixelFormatRG32Float || pf == MTLPixelFormatR32Float) { n = t->L.size / 4; for (uint64_t i = 0; i < n; i++) { uint32_t v; memcpy(&v, p + i * 4, 4); if (((v >> 23) & 255) == 255) return 1; } }
    return 0;
}
static int tex_init_fill(const tex_t *t, id<MTLTexture> mt) {
    if (!t->mem || !t->pool || (t->pool->flags & NVN_MEMORY_POOL_FLAGS_VIRTUAL) || t->has_layout) return 0;
    if (t->d.samples > 1 || ((int)mt.pixelFormat >= 250 && (int)mt.pixelFormat <= 262)) return 0;   // 250..262: Depth16Unorm … X24_Stencil8 (some names are macOS-only)
    int no_cpu = (t->pool->flags & NVN_MEMORY_POOL_FLAGS_CPU_NO_ACCESS) != 0;
    // COMPRESSIBLE is a memory-compression hint, not a data format. In a CPU_NO_ACCESS pool the game never writes the storage, so the memory may mean nothing to the CPU; in a pool the CPU writes
    // the texels are plain (upstream reference implementation, MIT: SD GUNDAM G GENERATION CROSS RAYS sets it on all 74 of its textures in CPU-writable pools, which skipping the fill left black)
    if (no_cpu && (t->d.flags & NVN_TEXTURE_FLAGS_COMPRESSIBLE)) return 0;
    static int flush_fill = -1; if (flush_fill < 0) { const char *e = getenv("DM_NVN_FLUSH_FILL"); flush_fill = !e || atoi(e) != 0; }
    if (!no_cpu && !flush_fill) return 0;
    if (!atomic_load(&g_sub_thread_set) || !on_sub_thread()) return 0;   // the upload batch belongs to the submit thread
    // Stale runs (gpw_stale): the fill takes the storage, then their texels are zeroed (gpw_zero_rect); the Inf / NaN and all-zero checks look at the storage with them zeroed
    const uint8_t *src = t->mem; uint8_t *masked = NULL; uint64_t *runs = NULL, sb = 0; int nr = 0;
    gz_ctx z = {t, mt, nil, 0, 0, 0, 0, 0, 0};
    // The stale runs hold for a CPU-writable pool too: on the Switch the GPU's writes land in the pool's memory whatever its CPU access, here they stay in Metal storage
    //   and the guest bytes keep what was there before. It Takes Two (11-01): a 64x64 RGBA16F array of 102 faces (17 reflection cubes) built in a CPU-writable pool took
    //   7.5% Inf / NaN from its storage (faces 78-101, every level); the base pass samples it, and every surface inside those captures' radius went black (Cody's black disc).
    //   Judged by the write ledger only (gpw_stale: bytes a GPU write covered and nothing rewrote since): what the game itself wrote there is its data, NaN or not
    { static int old = -1; if (old < 0) { const char *e = getenv("DM_NVN_STALE_FILL"); old = e && atoi(e) == 1; }
        if (!old) nr = gpw_stale(t->mem, t->L.size, &runs, &sb); }
    if (nr) {
        z.bpb = nvn_fmt_bpb(t->d.format, &z.bw, &z.bh); z.bpp = mtl_pf_bytes(mt.pixelFormat);
        int can = sb < t->L.size && (z.bpp || ((z.bw > 1 || z.bh > 1) && z.bpb));   // a copyable format (uncompressed with a known texel size, or block-compressed as is)
        uint64_t k = ++g_gpw_skips;
        if (k <= 4 || !(k & (k - 1)) || t->L.size >= (1u << 20)) MLOG("initial content: ser=%llu %ux%ux%u format %#x: %llu of its %llu bytes (%d runs) not taken from its storage: an earlier GPU write covered them (stale in guest memory), %s (%llu so far)",
            (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.format, (unsigned long long)sb, (unsigned long long)t->L.size, nr, can ? "zero there" : "zero instead (all of it, or a format the zeroing cannot copy into)", (unsigned long long)k);
        if (!can) { free(runs); return 0; }
        if (!(masked = malloc(t->L.size))) MDIE("initial content check copy of %llu bytes failed", (unsigned long long)t->L.size);
        memcpy(masked, t->mem, t->L.size); for (int i = 0; i < nr; i++) memset(masked + runs[2 * i], 0, runs[2 * i + 1] - runs[2 * i]);
        src = masked;
    }
    if (!(masked ? mem_any(src, t->L.size) : mem_any_touched(src, t->L.size))) { free(masked); free(runs); return 0; }   // 游戏内存直接判：不读未触碰页（mem_any_touched）
    // CPU_NO_ACCESS only: the game cannot have written such a pool's bytes as data, so an Inf / NaN there is leftover (Splatoon 3). A CPU-writable pool's bytes may be the
    //   game's own initial data, NaN included (a sentinel in a data texture): taken as they are, only the ledger's stale runs above are dropped
    if (no_cpu) { static int old = -1; if (old < 0) { const char *e = getenv("DM_NVN_NONFINITE_FILL"); old = e && atoi(e) == 1; }
        if (!old && fill_nonfinite(t, src, mt)) { free(masked); free(runs); static uint64_t nf; uint64_t k = ++nf; if (k <= 4 || !(k & (k - 1)) || t->L.size >= (1u << 20)) MLOG("initial content: ser=%llu %ux%ux%u format %#x not taken from its storage: it holds Inf / NaN (left in a CPU_NO_ACCESS pool), zero instead (%llu so far)",
                                                                                            (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.format, (unsigned long long)k); return 0; } }
    free(masked);
    uint64_t t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    if (pkg_upload(t, NULL, mt, NULL, NULL) != mt) { free(runs); return 0; }
    if (nr) {   // after the fill's copies: pass 1 sizes the zero buffer once (a bigger one replaces it), pass 2 records the copies
        for (int i = 0; i < nr; i++) tex_bytes_gobs(t, runs[2 * i], runs[2 * i + 1], gpw_zero_rect, &z);
        if (!(z.zb = zero_buf(MAX(z.need, (size_t)16)))) MDIE("zero buffer of %zu bytes for stale texels failed", z.need);
        up_begin(); for (int i = 0; i < nr; i++) tex_bytes_gobs(t, runs[2 * i], runs[2 * i + 1], gpw_zero_rect, &z);
        [g_up_texs addObject:mt]; if (!g_cb) up_flush();
    }
    free(runs);
    // cumulative count / bytes / submit-thread time of these fills (first 4, then at powers of two): what initial content costs before the frames it shows up in.
    // Every fill / skip of 1 MB or more gets its line too (here and above): 10-28 the Splatoon 3 plaza cube map array fill fell between the 32nd and the 64th, where no line was
    //   written, and the missing line was read as "never filled"
    static uint64_t n[2], bytes, ns; bytes += t->L.size; ns += clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0; uint64_t k = ++n[no_cpu];
    if (k <= 4 || !(k & (k - 1)) || t->L.size >= (1u << 20)) MLOG("initial content: ser=%llu %ux%ux%u format %#x filled from its storage, %s (%llu so far; all fills %.1f MB, %.1f ms on the submit thread)", (unsigned long long)t->serial,
                                       t->d.width, t->d.height, t->d.depth, t->d.format, no_cpu ? "a CPU_NO_ACCESS pool's" : "a CPU-writable pool's, before the GPU wrote it", (unsigned long long)k, bytes / 1048576.0, ns / 1e6);
    return 1;
}

static int clear_rect_zero(int i);
static void wd_clear_x(const tex_t *t, unsigned lv, long *x0, long *x1), wd_clear_y(const tex_t *t, long *y0, long *y1);   // S2Arm widen (defined with the clear triangles)
static void wd_page_clear(id<MTL4RenderCommandEncoder> en);
static void wd_p2_self_clear(id en, const uint32_t r5[5]);   // en 不标 MTL4 协议：Metal 3 设备上 draw() 传进来的也是这个编码器，本函数只经 clr_tri 画（graphics/nvn/tools/avail_count.sh）
// Linear textures (LINEAR) in a CPU-visible pool: the game writes the pool memory directly from the CPU (SMBW's glyph cache: 2048×8192 R8, IMAGE|LINEAR, pool CPU_UNCACHED|GPU_CACHED,
// the font engine rasterizes glyphs into it on the CPU). A GPU-private texture never sees those writes → all menu / dialog text is blank. On unified memory, create a linear texture directly on the pool buffer (zero copy): the GPU reads the current content at execution time, same as NVN.
// A linear 2D texture past Metal's 2D limit that tex_linear folds (nvn_red.h nvn_fold_k): its k (> 1), else 0. The same tests as tex_linear: only such a texture's host object
//   is shorter than its descriptor
static int g_fold_any;   // a folded texture was made this run (se_need looks at texture bindings only then)
static int tex_fold_k(const tex_t *t) {
    if (!t || !(t->d.flags & NVN_TEXTURE_FLAGS_LINEAR) || (t->d.flags & NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET)) return 0;   // IMAGE allowed (SMBW's glyph cache has it): image slots get zero (encode_args)
    if (t->d.target != NVN_TEXTURE_TARGET_2D || t->d.levels > 1 || t->d.samples > 1 || t->d.width > 16384 || t->d.height <= 16384) return 0;
    int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh); if (!bpb || bw != 1 || bh != 1) return 0;
    size_t row = t->d.stride ? t->d.stride : (size_t)t->d.width * bpb; if (row % (size_t)bpb) return 0;
    int k = nvn_fold_k(t->d.width, t->d.height, (uint32_t)(row / (size_t)bpb), 16384); return k > 1 ? k : 0;
}
static uint32_t tex_fold_pitch(const tex_t *t) { int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh); return bpb ? (uint32_t)((t->d.stride ? t->d.stride : (size_t)t->d.width * bpb) / (size_t)bpb) : 0; }
// 线性贴图建不了零拷贝视图（11-09 质量线，#255 / #262）：池里偏移或行距不合本机 Metal 的线性贴图对齐（iPhone 64 字节，Mac 宽：哈迪斯 II 一张 8x8 BGRA 行距 32），
//   或行距放不下一行 Metal 像素（上古卷轴5 A19：bytesPerRow 3840 < 5120，Metal 断言 abort）。原先前者退成私有贴图、只在建时从存储填一次，之后 CPU 写的全看不到；
//   后者直接建视图触发断言。现在这类只读线性贴图（不是线性渲染目标）在 tex_mtl_ 并进 CPU 写过的贴图那条路（打包上传：从客体内存上传、脏页重传，去混排按行距逐行拷）
// 线性贴图对齐：本机 Metal 的要求，诊断 DM_NVN_LINEAR_ALIGN=<字节> 抬高（Mac 上模拟 iPhone 的 64 字节做对照，只用于 A/B）
static NSUInteger linear_align(uint32_t pf) {
    static long ov = -1; if (ov < 0) { const char *e = getenv("DM_NVN_LINEAR_ALIGN"); ov = e ? atol(e) : 0; }
    NSUInteger al = [g_dev minimumLinearTextureAlignmentForPixelFormat:(MTLPixelFormat)pf]; return ov > (long)al ? (NSUInteger)ov : al;
}
static int tex_linear_needs_upload(const tex_t *t) {
    static int off = -1; if (off < 0) { const char *e = getenv("DM_NVN_LINEAR_UPLOAD"); off = e && !strcmp(e, "0"); }   // 诊断：=0 退回旧行为（私有贴图、只填一次），只用于 A/B
    if (off) return 0;
    // IMAGE 照走：线性贴图的图像槽本来就绑零（tex_linear / encode_args），实际只被采样（哈迪斯 II 那张 8x8 是 LINEAR | IMAGE）；线性渲染目标有 GPU 写，不走
    if ((t->d.flags & (NVN_TEXTURE_FLAGS_LINEAR | NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET)) != NVN_TEXTURE_FLAGS_LINEAR || !t->mem || !t->pool) return 0;
    if (t->d.target != NVN_TEXTURE_TARGET_2D || t->d.levels > 1 || t->d.samples > 1 || t->d.width > 16384 || t->d.height > 16384) return 0;   // 折叠 / 超限仍归 tex_linear
    uint32_t pf = 0; uint8_t swz[4]; int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh);
    if (!nvn_fmt_to_mtl(t->d.format, &pf, swz) || !pf || !bpb || bw != 1 || bh != 1 || nvn_fmt_expanded((uint32_t)t->d.format, NULL, NULL)) return 0;
    size_t row = t->d.stride ? t->d.stride : (size_t)t->d.width * bpb; void *mb; uint64_t mo;
    if (!nvn_be_addr((uint64_t)t->mem, (uint64_t)row * (t->d.height ? t->d.height : 1), &mb, &mo)) return 0;
    NSUInteger al = linear_align(pf); int pfb = mtl_pf_bytes((MTLPixelFormat)pf);
    int why = mo % al || row % al ? 1 : pfb && row < (size_t)(t->d.width ? t->d.width : 1) * pfb ? 2 : 0;
    if (why) { static int n; if (n++ < 8) MLOG("linear texture ser=%llu %ux%u format %#x offset %#llx row pitch %zu: %s, uploaded from guest memory and re-uploaded on CPU writes instead of a zero-copy view",
                                               (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format, (unsigned long long)mo, row, why == 1 ? [NSString stringWithFormat:@"not aligned to %lu bytes", (unsigned long)al].UTF8String : "row pitch shorter than a row of Metal pixels"); }
    return why != 0;
}
static id<MTLTexture> tex_linear(const tex_t *t) {
    // LINEAR_RENDER_TARGET is a linear layout too (SMBW's sky colour ramps: four 64×1 RGBA16F, written by the CPU every frame). Also in a pool the CPU cannot access, whose buffer holds what
    //   its storage held at creation (see tex_init_fill): Rhythm Heaven Groove's 228 linear R8 textures (sprite masks), read from files into CPU_NO_ACCESS pools, were private textures of zeros
    if (!(t->d.flags & (NVN_TEXTURE_FLAGS_LINEAR | NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET)) || !t->mem || !t->pool) return nil;
    if (t->d.target != NVN_TEXTURE_TARGET_2D || t->d.levels > 1 || t->d.samples > 1) {   // a private texture: ft_add leaves linear textures out, so CPU writes after its creation never reach it
        static int red; if (!(t->pool->flags & NVN_MEMORY_POOL_FLAGS_CPU_NO_ACCESS) && !red++) MLOG("【红】 linear texture ser=%llu %ux%ux%u target %d levels %u samples %d format %#x in a CPU-writable pool: only 2D / one level / one sample is made on the pool buffer, this one is a private texture and CPU writes after its creation do not show (first case)",
                                                                              (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.target, t->d.levels, t->d.samples, t->d.format);
        return nil;
    }
    // Past Metal's 2D limit (16384) a descriptor fails Metal's validation and the process aborts on the assertion (Nintendo Switch Sports 11-02: its glyph cache, a 1024×32768 R8
    //   linear 2D texture the CPU writes glyphs into, first built by wd_draw_ binding it). Too high, it is folded instead (nvn_red.h nvn_fold_k): k rows to one, W·k × ⌈H/k⌉ on the same
    //   pool bytes with a k times longer row pitch ((k − 1)·P + W wide, P the row pitch in texels), still zero copy; only the sampler-emulation variant reads it, at the logical texel (S2A.Dsh s2a_fx, nvn_mtl.m fold_of / se_bind).
    //   Too wide, or too high to fold within the limit: left to tex_desc, which reports it with its size and format and makes nothing, as every other over-limit texture
    int k = t->d.height <= 16384 ? (t->d.width > 16384 ? 0 : 1) : tex_fold_k(t);
    if (!k) return nil;   // a folded one is only sampled (not a linear render target; its image slots read / write zero, encode_args)
    uint32_t pf = 0; uint8_t swz[4]; int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh);
    if (!nvn_fmt_to_mtl(t->d.format, &pf, swz) || !pf || !bpb || bw != 1 || bh != 1) return nil;
    if (nvn_fmt_expanded((uint32_t)t->d.format, NULL, NULL)) return nil;   // stored expanded (fmt_unpack): not a view of the pool's bytes, uploaded (and re-uploaded on CPU writes) instead
    size_t row = t->d.stride ? t->d.stride : (size_t)t->d.width * bpb;
    uint32_t fh = ((t->d.height ? t->d.height : 1) + k - 1) / k;   // folded height; the last folded row's tail past row H is never read (s2a_ff wraps y within H)
    void *mb; uint64_t mo;
    if (!nvn_be_addr((uint64_t)t->mem, (uint64_t)row * (t->d.height ? t->d.height : 1), &mb, &mo)) { RED_ONCE(64, "linear texture storage is not in a memory pool (%ux%u format %#x)", t->d.width, t->d.height, t->d.format); return nil; }
    id<MTLBuffer> b = (__bridge id<MTLBuffer>)mb;
    if (k > 1 && mo + (uint64_t)row * k * (fh - 1) + (uint64_t)row * (k - 1) + (uint64_t)t->d.width * bpb > b.length) { RED_ONCE(139, "folded linear texture ser=%llu %ux%u: its last folded row would run past the pool buffer; not made", (unsigned long long)t->serial, t->d.width, t->d.height); return nil; }
    NSUInteger al = linear_align(pf);
    if (mo % al || row % al) { RED_ONCE(65, "linear texture offset %#llx / row pitch %zu not aligned to %lu bytes; created as a private texture (CPU writes invisible)", (unsigned long long)mo, row, (unsigned long)al); return nil; }
    NSUInteger dw = (t->d.width ? t->d.width : 1) + (NSUInteger)(k - 1) * (row / (size_t)bpb); int pfb = mtl_pf_bytes((MTLPixelFormat)pf);
    // 行距放不下一行 Metal 像素：建视图会触发 Metal 断言、整进程 abort（#262 上古卷轴5 A19：bytesPerRow 3840 < 5120）。只读的这类已在 tex_mtl_ 改走上传（tex_linear_needs_upload），到这里的是别的（渲染目标 / 图像 / 折叠）
    if (pfb && row * (NSUInteger)k < dw * (NSUInteger)pfb) { RED_ONCE(65, "linear texture ser=%llu %ux%u format %#x row pitch %zu shorter than %lu Metal pixels of %d bytes: no zero-copy view (would abort on Metal's validation); private texture", (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format, row, (unsigned long)dw, pfb); return nil; }
    MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:(MTLPixelFormat)pf width:dw height:fh mipmapped:NO];
    d.resourceOptions = b.resourceOptions;
    d.usage = MTLTextureUsageShaderRead | (t->d.flags & NVN_TEXTURE_FLAGS_IMAGE ? MTLTextureUsageShaderWrite : 0) | (t->d.flags & NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET ? MTLTextureUsageRenderTarget : 0);
    id<MTLTexture> lt = [b newTextureWithDescriptor:d offset:mo bytesPerRow:row * (NSUInteger)k];
    if (lt && k > 1) g_fold_any = 1;
    if (lt && k > 1) { static int n; if (n++ < 8) MLOG("folded linear texture ser=%llu %ux%u format %#x: %d rows to one, %lux%lu on the pool buffer (read through the sampler-emulation variant)",
                                                       (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format, k, (unsigned long)lt.width, (unsigned long)lt.height); }
    if (!lt) RED_ONCE(105, "linear texture create failed ser=%llu %ux%u format %#x pitch %zu: falls back to a private texture (CPU writes invisible)", (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format, row);
    return lt;
}
// CPU-written block-linear textures (WriteTexels): the game gave no packaged layout and changes the content from the CPU each frame (Engage's movie frames: a Y plane R8 + a UV plane RG8, WriteTexels every frame).
// Only packaged textures used to be uploaded from guest memory, so such a texture became a GPU-only texture whose content stayed 0. Their serials are recorded and they resolve through the packaged path (upload + re-upload on dirty pages)
// 序号集合用自己的 nvn_hmap（键混过哈希）：原先是不带回调的 CFSet，把序号原样当哈希，顺序递增的序号挤成一串相邻桶，查不在集合里的序号（几乎每次）要探到串尾
//   （照 the reference port「The set of CPU-written textures hashed by serial」，MIT：100 万次未命中、6442 个连续序号 1700 → 10 ms）。每次绑贴图都查一次（tex_mtl_ / view_pkg）
static pthread_mutex_t g_cpu_tex_mu = PTHREAD_MUTEX_INITIALIZER; static nvn_hmap g_cpu_tex;
// The GPU owns the texture's content: the write ledger holds a GPU write over its bytes that nothing rewrote since (gpw_mark / gpw_stale), or the GPU wrote it where the ledger keeps
//   no GOBs (gpw_own size 0). nvn_ft_poll in hle_nvn.c does not re-upload such a texture from guest memory: those bytes are older than what the GPU made, and its pages showed up written
//   only because the CPU wrote data beside it. Any other texture the CPU wrote after its first use is re-uploaded: on the Switch the GPU reads that very memory.
//   This used to be the host texture's usage (render target or shader writes), which every uncompressed texture that is not packaged has (tex_desc): a texture the CPU fills after it was
//   first sampled stayed what it was then. 11-05 Ocarina of Time (Switch 2): the title screen's button text was missing, its frame drawn (t_nvn_ftpoll)
int nvn_be_tex_gpu_owned(uint64_t serial) {
    pthread_mutex_lock(&g_gpw_mu);
    gpw_own *o = nvn_hm_get(&g_gpw_own, &serial); int have = o != NULL; const uint8_t *mem = have ? o->mem : NULL; uint64_t size = have ? o->size : 0;
    pthread_mutex_unlock(&g_gpw_mu);
    if (!have) return 0;
    if (!size) return 1;
    uint64_t *runs = NULL, b = 0; int n = gpw_stale(mem, size, &runs, &b); free(runs);
    return n > 0;
}
// 脏页轮询用（hle_nvn.c nvn_ft_poll）：上次登记（stamp）以来写过的页，只要有一页不全落在「GPU 写过、字节还没被改」的段里，就是 CPU 另写了别处 → 不算 GPU 所有，
//   按 CPU 写过上传（转随包时 carry_gpu 留住 GPU 写过的级）。原先只要贴图里有一块 GPU 写过的还在就整张算 GPU 所有，巫师3 远景植被那种「GPU 拷进 L1、CPU 写 L0」
//   的 ASTC 贴图里 CPU 写的 L0 永远不上传（11-05 摘入 graphics/witcher3-astc 时 t_nvn_promote_keep B ③④ 红）
int nvn_be_tex_gpu_owned_since(uint64_t serial, uint64_t stamp) {
    pthread_mutex_lock(&g_gpw_mu);
    gpw_own *o = nvn_hm_get(&g_gpw_own, &serial); int have = o != NULL; const uint8_t *mem = have ? o->mem : NULL; uint64_t size = have ? o->size : 0;
    pthread_mutex_unlock(&g_gpw_mu);
    if (!have) return 0;
    if (!size) return 1;
    uint64_t *runs = NULL, b = 0; int n = gpw_stale(mem, size, &runs, &b);
    if (n <= 0) { free(runs); return 0; }
    uintptr_t a = (uintptr_t)mem, pg = (uintptr_t)nvn_dirty_page_size();
    for (uintptr_t p = a & ~(pg - 1); p < a + size; p += pg) {
        if (!nvn_dirty_since((const void *)p, pg, stamp)) continue;
        uint64_t lo = MAX(p, a) - a, hi = MIN(p + pg, a + size) - a; int cov = 0;
        for (int i = 0; i < n && !cov; i++) cov = runs[2 * i] <= lo && runs[2 * i + 1] >= hi;
        if (!cov) { free(runs); return 0; }
    }
    free(runs); return 1;
}
void nvn_be_tex_cpu_written(const tex_t *t) {
    uint64_t serial = t->serial;
    if (!serial) return;
    pthread_mutex_lock(&g_cpu_tex_mu);
    if (!g_cpu_tex.klen) nvn_hm_init(&g_cpu_tex, 8);
    int added = 0;
    if (!nvn_hm_get(&g_cpu_tex, &serial)) {
        nvn_hm_put(&g_cpu_tex, &serial, (void *)1); added = 1;
        static int n; if (n++ < 16) MLOG("CPU-written texture ser=%llu %ux%ux%u format %#x target %d levels %u: uploaded / re-uploaded like a swizzled texture", (unsigned long long)serial, t->d.width, t->d.height, t->d.depth, t->d.format, t->d.target, t->d.levels);
    }
    pthread_mutex_unlock(&g_cpu_tex_mu);
    if (added) { pthread_mutex_lock(&g_smu); g_ser_gen++; pthread_mutex_unlock(&g_smu); }   // the texture IDs that resolve to it take the slow path, which now treats it as packaged (tex_by_id view_pkg)
}
static int tex_cpu_written(uint64_t serial) {
    pthread_mutex_lock(&g_cpu_tex_mu); int r = g_cpu_tex.n && nvn_hm_get(&g_cpu_tex, &serial); pthread_mutex_unlock(&g_cpu_tex_mu);
    return r;
}
// Pools a GPU write into a texture has been recorded in (upstream reference implementation, MIT, 75e5ddd8: a render target, a texture clear, a copy or downsample into a texture,
//   a shader image). Upstream keeps the flag in pool_t; here it is a set keyed by the pool object, since nvn_obj.h is an input of the direct stage key (a host change there would make
//   every game's direct library build again). Recorded at record time (hle_nvn.c) or when an image slot resolves (encode_args), cleared when the pool is finalized (nvn_be_alias_drop_pool)
static pthread_mutex_t g_pool_gpuw_mu = PTHREAD_MUTEX_INITIALIZER;
static nvn_hmap g_pool_gpuw = {.klen = 8};   // pool object → (void *)1
static _Atomic int g_pool_gpuw_new;            // a pool has had its first GPU write since cpu_unc_drop last looked
static _Atomic uint64_t g_pool_gpuw_gen = 1;   // +1 when a pool leaves the set (the per-thread cache below would otherwise hold a finalized pool's address)
void nvn_be_pool_gpu_written(const void *pool) {
    if (!pool) return;
    static __thread const void *last; static __thread uint64_t last_gen;   // the same pool again: SetRenderTargets names the same targets pass after pass
    uint64_t gen = atomic_load_explicit(&g_pool_gpuw_gen, memory_order_acquire);
    if (pool == last && gen == last_gen) return;
    uint64_t k = (uint64_t)(uintptr_t)pool; int fresh = 0;
    pthread_mutex_lock(&g_pool_gpuw_mu); if (!nvn_hm_get(&g_pool_gpuw, &k)) { nvn_hm_put(&g_pool_gpuw, &k, (void *)1); fresh = 1; } pthread_mutex_unlock(&g_pool_gpuw_mu);
    if (fresh) atomic_store(&g_pool_gpuw_new, 1);
    last = pool; last_gen = gen;
}
static int pool_gpu_written(const void *pool) {
    uint64_t k = (uint64_t)(uintptr_t)pool;
    pthread_mutex_lock(&g_pool_gpuw_mu); int r = g_pool_gpuw.n && nvn_hm_get(&g_pool_gpuw, &k) != NULL; pthread_mutex_unlock(&g_pool_gpuw_mu);
    return r;
}
static nvn_hmap g_cpu_unc = {.klen = 8};   // serial → pool: the uncompressed 2D textures tex_cpu_content took from their storage, which leave the CPU-written set at their pool's first GPU write (under g_cpu_tex_mu)
static void pool_gpuw_drop(const void *pool) {   // the pool is finalized (nvn_be_alias_drop_pool): its address may come back as another pool
    uint64_t k = (uint64_t)(uintptr_t)pool;
    pthread_mutex_lock(&g_pool_gpuw_mu); if (nvn_hm_del(&g_pool_gpuw, &k)) atomic_fetch_add(&g_pool_gpuw_gen, 1); pthread_mutex_unlock(&g_pool_gpuw_mu);
    pthread_mutex_lock(&g_cpu_tex_mu);
    for (uint32_t i = 0; i < g_cpu_unc.cap;) if (g_cpu_unc.vals[i] == pool) { uint64_t ser; memcpy(&ser, g_cpu_unc.keys + (size_t)i * 8, 8); nvn_hm_del(&g_cpu_unc, &ser); } else i++;
    pthread_mutex_unlock(&g_cpu_tex_mu);
}
// Storage the CPU wrote before the texture's first use (upstream reference implementation, MIT, 37c7eaa8 + 75e5ddd8; every game). Until the GPU first uses a texture it has not written it,
//   and it writes a block-compressed one only through an uncompressed texture over the same storage (g_bcal: those are synchronized, not taken from guest memory). So a sampled block-compressed or 3D texture in a pool the CPU can write, with no packaged layout, whose storage holds data at its
//   first use (tex_mtl_, submit thread) holds what the CPU wrote, flushed or not, before or after nvnTextureInitialize: it is made CPU-written, uploaded now and re-uploaded when its pages
//   change. The one-time fill (tex_init_fill) is not enough: that GPU texture goes into the sharing table (g_alias), and a new texture object over the same storage with the same
//   description gets it back after the CPU has rewritten the storage (The Great Ace Attorney Chronicles' court-record pictures, BC1 decoded into storage it reuses: each item showed the
//   previous item's picture). An uncompressed 2D texture cannot be told from a render target by its flags, but a pool the GPU has not written (pool_gpu_written) holds only what the CPU
//   wrote: there it takes its storage the same way (Mario Kart World's terrain patches, R16 / RG8 / RGBA8 / R11G11B10F / RGBA16 in a CPU_CACHED pool, no flush: zeros, every patch flat).
//   At the pool's first GPU write such a texture becomes a GPU texture with the content it has (cpu_unc_drop); in a pool the GPU already writes it keeps the one-time fill.
//   Untouched pages are not read for the zero check (mem_any_touched, as tex_init_fill). DM_NVN_STORAGE_FIRST_USE=0 turns this off (to measure it)
static int tex_cpu_content(const tex_t *t) {
    static int on = -1; if (on < 0) { const char *e = getenv("DM_NVN_STORAGE_FIRST_USE"); on = !e || atoi(e) != 0; }
    if (!on || !t->mem || !t->pool || t->has_layout || t->d.samples > 1 || t->d.target == NVN_TEXTURE_TARGET_BUFFER) return 0;
    int unc = !fmt_compressed(t->d.format) && t->d.target != NVN_TEXTURE_TARGET_3D;
    if (unc && (fmt_depth(t->d.format) || (t->d.flags & (NVN_TEXTURE_FLAGS_DISPLAY | NVN_TEXTURE_FLAGS_VIDEO_DECODE)) || pool_gpu_written(t->pool))) return 0;   // not what only the GPU or the decoder fills
    if (t->pool->flags & (NVN_MEMORY_POOL_FLAGS_CPU_NO_ACCESS | NVN_MEMORY_POOL_FLAGS_VIRTUAL)) return 0;   // the CPU cannot write it (tex_init_fill fills it once) / sparse (packaged through the page table)
    // IMAGE only matters for an uncompressed texture: a shader writes a block-compressed one only through an uncompressed image over its storage (g_bcal; Pokopia gives nearly every texture IMAGE, its icons BC1 / BC7)
    if (!unc && bcal_has(t)) return 0;   // the GPU wrote this storage through such an image (No Man's Sky): its bytes come from there (bcal_sync), guest memory holds stale ones
    if ((t->d.flags & (NVN_TEXTURE_FLAGS_COMPRESSIBLE | NVN_TEXTURE_FLAGS_LINEAR | NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET | NVN_TEXTURE_FLAGS_SPARSE))
        || ((t->d.flags & NVN_TEXTURE_FLAGS_IMAGE) && !fmt_compressed(t->d.format))) return 0;
    if (!mem_any_touched(t->mem, t->L.size)) return 0;
    if (unc) { uint64_t ser = t->serial; pthread_mutex_lock(&g_cpu_tex_mu); nvn_hm_put(&g_cpu_unc, &ser, (void *)t->pool); pthread_mutex_unlock(&g_cpu_tex_mu); }
    static uint64_t n[2]; if (n[unc]++ < 4) MLOG("texture written by the CPU before its first use ser=%llu %ux%ux%u format %#x%s pool flags %#x: uploaded from its storage, re-uploaded when it changes (%llu so far)",
                                         (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.format, unc ? " (uncompressed, in a pool the GPU has not written)" : "", t->pool->flags, (unsigned long long)n[unc]);
    return 1;
}
// A pool's first GPU write: what its storage holds is no longer the whole truth, so the uncompressed textures taken from it become GPU textures with the content they have (the rule in
//   a pool the GPU writes). Submit thread, as tex_cpu_content is. The NvPkg's texture is moved out of it first: its dealloc takes its texture out of the residency set
static void cpu_unc_drop(void) {
    if (!atomic_load_explicit(&g_pool_gpuw_new, memory_order_relaxed) || !atomic_exchange(&g_pool_gpuw_new, 0)) return;
    uint64_t *ser = NULL; uint32_t n = 0, cap = 0;
    pthread_mutex_lock(&g_cpu_tex_mu);
    for (uint32_t i = 0; i < g_cpu_unc.cap;) {
        const void *p = g_cpu_unc.vals[i];
        if (!p || !pool_gpu_written(p)) { i++; continue; }
        if (n == cap) { uint64_t *grown = realloc(ser, (cap = cap ? cap * 2 : 64) * sizeof *ser); if (!grown) MDIE("cpu_unc_drop: out of memory"); ser = grown; }
        uint64_t s; memcpy(&s, g_cpu_unc.keys + (size_t)i * 8, 8);
        ser[n++] = s; nvn_hm_del(&g_cpu_unc, &s); if (g_cpu_tex.klen) nvn_hm_del(&g_cpu_tex, &s);
    }
    pthread_mutex_unlock(&g_cpu_tex_mu);
    for (uint32_t i = 0; i < n; i++) {
        __unsafe_unretained id o = tex_get(ser[i]);
        if ([o isKindOfClass:[NvPkg class]]) { NvPkg *pk = o; id<MTLTexture> mt = pk->view ? nil : pk->tex; if (mt) { pk->tex = nil; tex_put(ser[i], mt); } }
    }
    if (n) { pthread_mutex_lock(&g_smu); g_ser_gen++; pthread_mutex_unlock(&g_smu);
        static int nl; if (nl++ < 8) MLOG("a pool's first GPU write: %u uncompressed textures taken from its storage are GPU textures from now on", n); }
    free(ser);
}
static void pkg_gpu_wrote(const tex_t *t, unsigned level, unsigned layer0, unsigned nlayers, uint32_t x, uint32_t y, uint32_t w, uint32_t h) {
    if (!t || !t->serial || !t->mem) return;
    gpw_mark(t, level, layer0, nlayers, x, y, w, h);   // copy / clear destination: the bytes of this rectangle (see gpw_mark)
    __unsafe_unretained id o = tex_get(t->serial); if (![o isKindOfClass:[NvPkg class]]) return;
    NvPkg *pk = o; if (pk->sparse || !pk->nph) return;
    if (!pk->pgpu && !(pk->pgpu = calloc(pk->nph, sizeof *pk->pgpu))) return;
    gw_ctx c = {t, pk->pgpu, nvn_dirty_now(), pk->nph};
    if (!w || !h) { w = MAX(t->d.width >> level, 1u); h = MAX(t->d.height >> level, 1u); x = y = 0; }
    for (unsigned k = 0; k < (nlayers ? nlayers : 1); k++) tex_rect_bytes(t, level, layer0 + k, x, y, w, h, gw_mark, &c);
    g_pkg_gpu_writes++;
}
// Partial re-upload into the texture itself (pages the CPU wrote after the GPU, see NvPkg pgpu): each rectangle's level / layer is deswizzled from guest memory once, only the rectangles go to the texture
typedef struct { unsigned level, layer; uint32_t x, y, w, h; } up_rect;
typedef struct { up_rect *r; int n, cap; } rect_list;
static void rect_add(void *u, unsigned level, unsigned layer, uint32_t x, uint32_t y, uint32_t w, uint32_t h) {
    rect_list *L = u; if (L->n == L->cap) { int nc = L->cap ? 2 * L->cap : 16; up_rect *nr = realloc(L->r, (size_t)nc * sizeof *nr); if (!nr) return; L->r = nr; L->cap = nc; }
    L->r[L->n++] = (up_rect){level, layer, x, y, w, h};
}
static int pkg_upload_rects(const tex_t *t, id<MTLTexture> mt, const rect_list *L) {   // 0 = done
    int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh); if (!bpb) return 1;
    { uint32_t upf; int ubpp; if (fmt_unpack(t->d.format, &upf, &ubpp)) return 1; }   // stored in another format (fmt_unpack): the caller re-uploads it whole
    up_begin();
    for (int i = 0; i < L->n; i++) {
        const up_rect *q = &L->r[i]; int dup = 0; for (int j = 0; j < i; j++) dup |= L->r[j].level == q->level && L->r[j].layer == q->layer; if (dup) continue;   // one deswizzle per level and layer
        uint32_t w = MAX(t->d.width >> q->level, 1u), h = MAX(t->d.height >> q->level, 1u), z = t->d.target == 2 ? MAX(t->d.depth >> q->level, 1u) : 1;
        size_t pitch = (size_t)((w + bw - 1) / bw) * bpb, rows = (h + bh - 1) / bh;
        id<MTLBuffer> stg = [g_dev newBufferWithLength:pitch * rows * z options:MTLResourceStorageModeShared];
        if (!stg) return 1;
        res_add(stg); up_keep_add(stg);
        if (nvn_deswizzle(&t->d, q->level, q->layer, t->mem, stg.contents, pitch)) { RED_ONCE(98, "partial re-upload: deswizzle failed format %#x target %d", t->d.format, t->d.target); return 1; }
        for (int j = i; j < L->n; j++) { const up_rect *r = &L->r[j]; if (r->level != q->level || r->layer != q->layer) continue;
            size_t off = (size_t)(r->y / bh) * pitch + (size_t)(r->x / bw) * bpb; g_bp_up_bytes += (size_t)((r->w + bw - 1) / bw) * bpb * ((r->h + bh - 1) / bh) * z;
            up_blit_add_at(stg, off, pitch, pitch * rows, MTLSizeMake(r->w, r->h, z), mt, t->d.target == 2 ? 0 : r->layer, r->level, r->x, r->y); }
    }
    [g_up_texs addObject:mt];
    if (!g_cb) up_flush();
    return 0;
}
// A GPU-only texture turning packaged (the CPU wrote its storage after it was first resolved: nvn_be_tex_cpu_written) is uploaded whole from guest memory, but what a GPU write
//   (copy / clear destination, attachment, image store) put into it is only in the old host texture: its guest bytes are stale (gpw_stale). Those texels are copied from the old
//   texture into the new one, in command order after the upload batch, and noted as GPU-written (pkg_gpu_wrote → NvPkg pgpu), so a later re-upload keeps them too. As Ryujinx's
//   TextureGroup: a CPU write synchronizes the subresources it touched again, those the GPU modified keep the GPU's content.
//   The Witcher 3 (11-04, Kaer Morhen): a new full-chain ASTC texture takes levels 1 on by CopyTextureToTexture from the old one, then the CPU writes level 0 from the file; uploaded
//   whole, levels 1 on were the zeros of guest memory, decoded as the ASTC error colour (magenta foliage in the distance)
typedef struct { const tex_t *t; __unsafe_unretained id<MTLTexture> from, to; uint64_t rects; } carry_ctx;
static void carry_rect(void *u, unsigned level, unsigned layer, uint32_t x, uint32_t y, uint32_t w, uint32_t h) {
    carry_ctx *c = u; int d3 = c->t->d.target == 2; uint32_t z = d3 ? MAX(c->t->d.depth >> level, 1u) : 1;
    enc_b_copy_texture(blit(), c->from, d3 ? 0 : layer, level, MTLOriginMake(x, y, 0), MTLSizeMake(w, h, z), c->to, d3 ? 0 : layer, level, MTLOriginMake(x, y, 0));
    pkg_gpu_wrote(c->t, level, d3 ? 0 : layer, 1, x, y, w, h); c->rects++;
}
static uint64_t g_carry_tex, g_carry_rects;
static void carry_gpu(const tex_t *t, id<MTLTexture> to, id<MTLTexture> from, const uint64_t *runs, int n, uint64_t bytes) {
    if (from.pixelFormat != to.pixelFormat || from.width != to.width || from.height != to.height || from.depth != to.depth || from.arrayLength != to.arrayLength
        || from.mipmapLevelCount != to.mipmapLevelCount || from.textureType != to.textureType || from.sampleCount != to.sampleCount) {
        RED_ONCE(166, "texture ser=%llu turned packaged: its old host texture has another shape (format %lu → %lu, %lux%lu → %lux%lu, levels %lu → %lu), the %llu bytes the GPU wrote are not carried over",
                 (unsigned long long)t->serial, (unsigned long)from.pixelFormat, (unsigned long)to.pixelFormat, (unsigned long)from.width, (unsigned long)from.height, (unsigned long)to.width,
                 (unsigned long)to.height, (unsigned long)from.mipmapLevelCount, (unsigned long)to.mipmapLevelCount, (unsigned long long)bytes);
        return;
    }
    carry_ctx c = {t, from, to, 0};
    for (int i = 0; i < n; i++) tex_bytes_gobs(t, runs[2 * i], runs[2 * i + 1], carry_rect, &c);
    uint64_t k = ++g_carry_tex; g_carry_rects += c.rects;
    if (k <= 4 || !(k & (k - 1))) MLOG("texture ser=%llu %ux%ux%u format %#x levels %u turned packaged after GPU writes: %llu bytes (%llu rectangles) taken from its old host texture, the rest uploaded from guest memory (%llu textures, %llu rectangles so far)",
                                       (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.format, t->d.levels, (unsigned long long)bytes, (unsigned long long)c.rects, (unsigned long long)k, (unsigned long long)g_carry_rects);
}
static id<MTLTexture> tex_mtl_(const tex_t *ct);
// NVN formats whose Metal format is the other one of an sRGB / linear pair (g_pfv_srgb) of a format's Metal format: up to 4, zero-terminated (an RGBA8 texture has RGBA8_SRGB and RGBX8_SRGB)
//   (upstream reference implementation, MIT, 92f223a7)
static const uint8_t *srgb_twins(uint32_t f) {
    static uint8_t tw[256][5]; static dispatch_once_t once;
    dispatch_once(&once, ^{
        for (int a = 1; a < 256; a++) { uint32_t pa = 0, pb = 0; uint8_t sw[4]; int n = 0;
            if (!nvn_fmt_to_mtl((uint32_t)a, &pa, sw) || !pa) continue;
            for (int b = 1; b < 256 && n < 4; b++) {
                if (b == a || !nvn_fmt_to_mtl((uint32_t)b, &pb, sw) || !pb || pa == pb) continue;
                for (size_t i = 0; i < sizeof g_pfv_srgb / sizeof *g_pfv_srgb; i++)
                    if ((pa == g_pfv_srgb[i].a && pb == g_pfv_srgb[i].b) || (pa == g_pfv_srgb[i].b && pb == g_pfv_srgb[i].a)) { tw[a][n++] = (uint8_t)b; break; }
            }
        }
    });
    return f < 256 ? tw[f] : tw[0];
}
// 审计 #1565 P1-101：并行预编前瞻（pso_predict_rest_）解析后面换画布的贴图时置 1。前瞻只要画布的像素格式与采样数，此时手头这笔绘制的渲染遍还开着；
//   图像对象落在没写权限的共享贴图上时不在这里升级（tex_upgrade 经 blit() 结束渲染遍，并把升级拷贝提前到这一遍剩下的绘制写完之前），留给真正换画布时再升级
static int g_tex_peek;
static uint64_t g_tex_mtl_n;   // calls (tests)
// ② 解析出的 BC 贴图 r：同存储上 GPU 写过、比它已同步的新的层，按层拷过来（见 g_bcal）。只在提交线程的提交里（拷贝排进命令顺序），前瞻不做
static id<MTLTexture> bcal_src(const tex_t *w) {   // 写它的那张未压缩贴图现在的 Metal 贴图：按序号，对象没了按共享表（同存储同描述）
    id o = tex_get(w->serial);
    if (!o) { alias_key k; alias_key_of(&k, w); pthread_mutex_lock(&g_smu); o = hm_get_id(&g_alias, &k); pthread_mutex_unlock(&g_smu); }
    if ([o isKindOfClass:[NvPkg class]]) o = ((NvPkg *)o)->tex;
    id<MTLTexture> m = [o conformsToProtocol:@protocol(MTLTexture)] ? o : nil; while (m.parentTexture) m = m.parentTexture; return m;
}
static void bcal_seen_mark(uint64_t k, const pool_t *pool) {   // ③ 这段存储解析过 BC 贴图：之后的写让它重新解析。登记过的无锁跳过
    unsigned h = bcal_h(k); if (atomic_load_explicit(&g_bcal_seen_c[h], memory_order_relaxed) == k) return;
    pthread_mutex_lock(&g_bcal_mu);
    if (!nvn_hm_get(&g_bcal_seen, &k)) nvn_hm_put(&g_bcal_seen, &k, (void *)pool);
    bcal_e *e = nvn_hm_get(&g_bcal, &k); if (e) atomic_store(&e->seen, 1);
    atomic_store_explicit(&g_bcal_seen_c[h], k, memory_order_relaxed);
    pthread_mutex_unlock(&g_bcal_mu);
}
static bcal_e *bcal_find(uint64_t k) {   // 这段存储的记账：正向缓存 → 「这里没记账」缓存 → 慢路查表
