    sd_finish(); enc_r_end_pass(g_enc); zskip_commit_clears(); g_enc = nil; g_rt_merged = 0; g_rt_range_active = g_rt_range_pending = 0; ts_after(); ms_after(); if (g_lp.count) lp_finish(); fz_end();
    if (g_nubd && g_nubd >= ubd_lazy()) ubd_flush();   // the inline updates deferred in this pass, in order (see mtl_sub_update); across passes they wait for the next copy or dispatch (blit_raw)
    if (g_nbcrt) bcrt_flush();   // blocks drawn into shadows go back into their compressed textures
#ifdef NVN_RT_RANGE_TEST
    rr_finish(ranged);
#endif
    AP_E(0);
} }
// The format an attachment is actually attached with: the view's format if the view changes the format and can be attached, otherwise the base texture's. Shared by attaching (attach) and pipeline prediction (pso_predict_rest) so both agree --
// prediction used the base format, so for a pass written through an sRGB view (Mario's last pass) the predicted pipeline had the wrong format and the real one was compiled at the first draw (from d2r-mobile e2a0c9a9b)
// A compressed texture as a render target (The Legend of Zelda: Breath of the Wild a 32x32 RGTC1 (BC4) texture, Tears of the Kingdom a 32x32x32 3D one drawn one depth plane per pass, both written
// through an RGBA16UI view: one pixel = one 8-byte block, i.e. BC4 encoded on the GPU). Metal can neither attach a compressed format as a colour attachment nor create compressed <-> uncompressed views
// (the pipeline descriptor validation aborts the process). A BC texture with an uncompressed view whose pixel size equals the block size is drawn through a shadow (bcrt_attach); any other compressed target
// is left out (a pass with no attachment at all skips its draws), with a red line
static int mtl_fmt_block(MTLPixelFormat f) { return (f >= MTLPixelFormatBC1_RGBA && f <= MTLPixelFormatBC7_RGBAUnorm_sRGB) || (f >= MTLPixelFormatPVRTC_RGB_2BPP && f < MTLPixelFormatGBGR422); }
static int nvn_fmt_bc(uint32_t f) { return f >= 0x41 && f <= 0x50; }   // NVN BC1–7 / BC6H formats (0x41 RGB_DXT1 … 0x50 BC6H unsigned)
static int bc_block_bytes(MTLPixelFormat f) {   // bytes per 4x4 block of a BC format, 0 for other formats
    if (f < MTLPixelFormatBC1_RGBA || f > MTLPixelFormatBC7_RGBAUnorm_sRGB) return 0;
    return f <= MTLPixelFormatBC1_RGBA_sRGB || f == MTLPixelFormatBC4_RUnorm || f == MTLPixelFormatBC4_RSnorm ? 8 : 16;
}
// A depth texture drawn through a colour view of the same pixel size (Luigi's Mansion 3: a D16 texture through an R16 view at boot) is drawn the same way: Metal can neither attach a depth format
// as a colour attachment nor make a colour view of a depth texture, and the pipeline descriptor validation aborts the process. Only formats whose Metal pixel is the NVN pixel qualify (D16 and D32F;
// D24S8 is Depth32Float_Stencil8 here, whose bytes are not the game's)
static int shrt_block(MTLPixelFormat f, int *side) {   // bytes per block of a texture drawn through a shadow, and the block's side in pixels; 0 for any other format
    int bb = bc_block_bytes(f); if (bb) { *side = 4; return bb; }
    *side = 1; return f == MTLPixelFormatDepth16Unorm ? 2 : f == MTLPixelFormatDepth32Float ? 4 : 0;
}
// A depth clear value as the GPU stores it, made to equal what a draw at that depth stores. NVN (like Vulkan) converts both to fixed point the same way, and games
//   rely on it: Tears of the Kingdom's tiled lighting clears a Depth16 target to 0.5, draws its lit tiles' quads with depth ALWAYS, then draws each light shader's tiles
//   with depth EQUAL; the tiles left at the clear value match the ambient pass's z = 0.5. Apple GPUs round a rasterized depth to the nearest 16-bit step but truncate the
//   clear value (measured: of 70001 depths, 35027 failed EQUAL against the same clear value, 0 with this one; Depth32Float 0 / 70001 either way), so those tiles stayed
//   black. Clearing to the middle of the step a draw rounds to makes the truncation land on it.
static double depth_clear_value(MTLPixelFormat f, double z) {
    if (f != MTLPixelFormatDepth16Unorm) return z;
    z = z < 0 ? 0 : z > 1 ? 1 : z;
    return fmin(1.0, (rint(z * 65535.0) + 0.5) / 65535.0);
}
static int mtl_fmt_depth(MTLPixelFormat f) { return f == MTLPixelFormatDepth16Unorm || f == MTLPixelFormatDepth32Float || f == MTLPixelFormatDepth32Float_Stencil8 || f == MTLPixelFormatX32_Stencil8 || f == MTLPixelFormatStencil8; }
// The shadow's format: the view's, when the base is BC (or a depth format, above) and the view is an uncompressed colour format with one block's bytes per pixel
static int bcrt_view(id<MTLTexture> base, const view_t *v, int has_v, MTLPixelFormat *pf_out) {
    uint32_t pf = 0; uint8_t swz[4]; int bw = 0, bh = 0, side = 0, bb = base ? shrt_block(base.pixelFormat, &side) : 0;
    if (!bb || !has_v || !v->set_format || !nvn_fmt_to_mtl(v->format, &pf, swz) || !pf || mtl_fmt_block((MTLPixelFormat)pf) || mtl_fmt_depth((MTLPixelFormat)pf)) return 0;
    if (nvn_fmt_bpb(v->format, &bw, &bh) != bb || bw != 1 || bh != 1) return 0;
    *pf_out = (MTLPixelFormat)pf; return 1;
}
// Drawing into a BC texture: the pass draws into an uncompressed shadow of blocks x blocks in the view's format. The level / layer / depth plane's blocks are copied into it through a buffer before the pass
// and back, byte for byte, after it (bcrt_flush, from rp_end). The shadow is an attachment of its own: always loaded and stored, and kept out of the load-skip / store-elision / zero-source bookkeeping,
// which keys by the BC texture's serial. Shadows and staging buffers stay resident and are reused per attachment number, format and size, so a pass per depth plane adds no residency churn.
// From PR #11 (digitalhivehub), where Tears of the Kingdom first drew this way
typedef struct { id<MTLTexture> base, shadow; id<MTLBuffer> buf; NSUInteger level, slice, z, w, h, bw, bh, bpb; } bcrt_t;
static bcrt_t g_bcrt[8];
static __strong id<MTLTexture> g_bcrt_sh[8]; static __strong id<MTLBuffer> g_bcrt_buf[8];
static int bcrt_is(id<MTLTexture> t) { for (int i = 0; i < g_nbcrt; i++) if (t && g_bcrt[i].shadow == t) return 1; return 0; }
static void bcrt_flush(void) {
    int n = g_nbcrt; g_nbcrt = 0;
    for (int i = 0; i < n; i++) { bcrt_t e = g_bcrt[i]; g_bcrt[i] = (bcrt_t){0};
        NSUInteger row = e.bw * e.bpb, img = row * e.bh;
        enc_b_copy_texture_buffer(blit(), e.shadow, 0, 0, MTLOriginMake(0, 0, 0), MTLSizeMake(e.bw, e.bh, 1), e.buf, 0, row, img);
        enc_b_copy_buffer_texture(blit(), e.buf, 0, row, img, MTLSizeMake(e.w, e.h, 1), e.base, e.slice, e.level, MTLOriginMake(0, 0, e.z));
    }
}
// a holds the BC texture with its level and layer / plane already set; returns 1 when a now holds the shadow
static int bcrt_attach(MTLRenderPassAttachmentDescriptor *a, id<MTLTexture> base, const view_t *v, int has_v) {
    MTLPixelFormat spf; int k = g_nbcrt; if (k >= 8 || !bcrt_view(base, v, has_v, &spf)) return 0;
    int is3d = base.textureType == MTLTextureType3D, side = 1;
    NSUInteger bpb = (NSUInteger)shrt_block(base.pixelFormat, &side);
    NSUInteger lv = a.level, sl = is3d ? 0 : a.slice, z = is3d ? a.depthPlane : 0, w = mip_extent(base.width, lv), h = mip_extent(base.height, lv), bw = (w + side - 1) / side, bh = (h + side - 1) / side;
    NSUInteger row = bw * bpb, img = row * bh;
    if (!g_bcrt_sh[k] || g_bcrt_sh[k].pixelFormat != spf || g_bcrt_sh[k].width != bw || g_bcrt_sh[k].height != bh) {
        MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:spf width:bw height:bh mipmapped:NO];
        d.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead; d.storageMode = MTLStorageModePrivate;
        id<MTLTexture> sh = [g_dev newTextureWithDescriptor:d]; id<MTLBuffer> buf = [g_dev newBufferWithLength:img options:MTLResourceStorageModePrivate];
        if (!sh || !buf) { RED_ONCE(74, "render target in a compressed or depth texture: cannot create its %lux%lu-block shadow (Metal format %lu)", (unsigned long)bw, (unsigned long)bh, (unsigned long)spf); return 0; }
        if (g_bcrt_sh[k]) { defer_obj_release(g_bcrt_sh[k]); defer_obj_release(g_bcrt_buf[k]); }
        res_add(sh); res_add(buf); g_bcrt_sh[k] = sh; g_bcrt_buf[k] = buf;
    }
    id<MTLTexture> sh = g_bcrt_sh[k]; id<MTLBuffer> buf = g_bcrt_buf[k];
    enc_b_copy_texture_buffer(blit(), base, sl, lv, MTLOriginMake(0, 0, z), MTLSizeMake(w, h, 1), buf, 0, row, img);
    enc_b_copy_buffer_texture(blit(), buf, 0, row, img, MTLSizeMake(bw, bh, 1), sh, 0, 0, MTLOriginMake(0, 0, 0));
    g_bcrt[g_nbcrt++] = (bcrt_t){base, sh, buf, lv, sl, z, w, h, bw, bh, bpb};
    a.texture = sh; a.level = 0; a.slice = 0; a.depthPlane = 0;
    static int once[2]; if (!once[side == 1]++) MLOG("render target in a %s texture: view format %#x drawn into a %lux%lu-block shadow (Metal format %lu) and copied back after the pass (first case pass %llu)",
                                       side == 1 ? "depth" : "compressed", v->format, (unsigned long)bw, (unsigned long)bh, (unsigned long)spf, g_stat_pass + 1);
    return 1;
}
static MTLPixelFormat rt_view_fmt(id<MTLTexture> base, const view_t *v, int has_v) {
    MTLPixelFormat spf;
    if (bcrt_view(base, v, has_v, &spf)) return spf;
    if (base && mtl_fmt_block(base.pixelFormat)) {
        RED_ONCE(78, "render target is a compressed-format texture (Metal format %lu %lux%lu layers %lu, view format change %d → NVN %#x): not attached; draws to this attachment are lost", (unsigned long)base.pixelFormat, (unsigned long)base.width, (unsigned long)base.height,
                 (unsigned long)base.arrayLength, has_v ? v->set_format : 0, has_v ? v->format : 0);
        return MTLPixelFormatInvalid;
    }
    if (!base || !has_v || !v->set_format) return base.pixelFormat;
    uint32_t pf = 0; uint8_t swz[4];
    if (!nvn_fmt_to_mtl(v->format, &pf, swz) || !pf || pf == (uint32_t)base.pixelFormat) return base.pixelFormat;
    // Metal aborts the process when a format view is not compatible (4 B/px → 16 B/px and the like), it does
    // not just return nil. On a GPU without BC the game's BC3 texture is stored decoded as RGBA8Unorm while
    // its "one texel = one BC block" RGBA32Uint view is still requested; that pair used to reach attach().
    // Falling back to the base format keeps the pass descriptor and the pipeline key in agreement (both read
    // rt_view_fmt / the attached texture), so the draw is either built or skipped — never an abort.
    if (!mtl_pfv_compatible(base.pixelFormat, (MTLPixelFormat)pf)) {
        RED_ONCE(183, "render target view format %#x (Metal %u) is not compatible with base texture Metal format %lu: attached in the base format (a BC texture decoded on a GPU without BC?)", v->format, pf, (unsigned long)base.pixelFormat);
        return base.pixelFormat;
    }
    if (tex_need_pfv(base.pixelFormat, (MTLPixelFormat)pf) && !(base.usage & MTLTextureUsagePixelFormatView)) return base.pixelFormat;
    return (MTLPixelFormat)pf;
}
// The same texture level / layer attached at more than one colour slot: only the first is attached, later ones are not (their writes are dropped). The G-buffer passes of The Legend of Zelda: Breath of the Wild attach the albedo and another buffer twice each
// (c1 = c2, c3 = c4), and the channel write masks of c2 / c4 are always 0 (cmask 0x00f0f0ff). The Switch's ROP writes only the masked channels and the two slots do not interfere;
// on Apple's TBDR each attachment has its own tile memory and the whole tile is stored back at the end of the pass, so the copy stored later (loaded, never written) overwrites the writes of the earlier one -- the order differs per 32x32 tile,
// the albedo kept only scattered squares, and the whole 3D picture went black. A red line is printed when a dropped slot is used with a non-zero write mask (those writes are really lost)
static int rt_dup_slot(const p_set_rt *r, int i) {
    if (!r->color[i]) return 0;
    uint8_t lv = r->has_cview[i] && r->cview[i].set_levels ? r->cview[i].base_level : 0; uint16_t ly = r->has_cview[i] && r->cview[i].set_layers ? r->cview[i].min_layer : 0;
    for (int j = 0; j < i; j++) {
        if (!r->color[j] || r->color[j]->serial != r->color[i]->serial) continue;   // compare serials: records hold copies of the texture objects (tex_snap), so the pointers differ
        uint8_t lj = r->has_cview[j] && r->cview[j].set_levels ? r->cview[j].base_level : 0; uint16_t yj = r->has_cview[j] && r->cview[j].set_layers ? r->cview[j].min_layer : 0;
        if (lj == lv && yj == ly) return 1;
    }
    return 0;
}
// S2Arm widen (direct third layer, widen_glue.inc wd_widen_rts): a render target the widen core widens gets storage r texels wide, the game's content in its left part. The core maps this target's
//   viewports and scissors to r (s2a_widen_map_viewport); on the game's width every full-screen pass stretched its picture by k and cut the right (10-26 Mario Kart 8 Deluxe direct title movie,
//   430 px to the right on a 2346-wide screen instead of 142). As tex_upgrade, but every table entry that holds the old storage takes the new one: the serial and finalized-serial tables (the
//   game makes transient objects over the same storage every frame, g_alias) and the sharing table, so later objects on that storage get it too. The new storage is zero-filled first (the
//   widened strip reads 0, as new Switch memory); depth / stencil and multisample ones are not (tex_zero_fill), their passes clear them. Packaged, buffer, view and compressed textures stay
static uint64_t g_wd_widened;   // storages widened (memory report)
// Why this texture's storage cannot be widened (NULL = it can): packaged, buffer-backed (game memory), a view, compressed or 3D. Such a target is registered with the widen
//   core as widenable only when the widened drawing fits its storage as it is (wd_tex: Mario Kart 8 Deluxe's 1920-wide window texture, drawn on 1280 of it, 1564 widened);
//   otherwise without S2A_WIDEN_USE_RT, so the core draws it at the game's width and treats what it holds as a picture. Registered as widenable regardless, Witcher 3's
//   direct logo movie had its 1280-wide video planes drawn as a page moved 142 px right; the cleared left strip read as magenta on the left 11.1% of the screen (10-26)
static const char *tex_widen_why(const tex_t *t) {
    id<MTLTexture> base = tex_mtl(t);
    if (!base) return NULL;
    // 打包贴图（CPU 写过的池）当渲染目标时可以放宽：tex_widen 换 NvPkg 自己的贴图（表里存的是 NvPkg，tex_swap_storage 换不到）；带层级视图的（稀疏池只挂了粗层级，sparse_view）不放宽。
    //   11-02 饥荒：交换链所在池 CPU 开机写过一幅图，一律判「放不宽」→ 整局 16:9 居中留黑边。之后 CPU 再写：重传建原宽贴图，下一遍开遍按核心的宽重新放宽（wd_widen_rts）
    //   稀疏池（经页表读）里没有视图的同样放宽：重传判据（页表代数 / 页写入）与换掉的是哪张贴图无关。11-05 旷野之息 Duo：场景缓冲 1280×720 等 25 张在稀疏池里，
    //   判「放不宽」仍按可加高登记（wd_tex 当时只核宽），核心按 900 行画、存储只有 720 行，画面底部 180 行（900 − 720）全黑
    __unsafe_unretained id o = tex_get(t->serial);
    if ([o isKindOfClass:[NvPkg class]] && ((NvPkg *)o)->view) return "packaged";
    return base.buffer ? "buffer" : base.parentTexture ? "view" : mtl_fmt_block(base.pixelFormat) ? "compressed"
         : base.textureType == MTLTextureType3D ? "3D" : NULL;
}
//   rh (10-26 any aspect ratio): the height the core gives (s2a_widen_tex_h; 0 = keep): a screen narrower than 16:9 widens heights instead (more picture above and below), the same storage swap
// Every table entry that holds the old storage takes the new one (the serial and finalized-serial tables, the sharing table: later objects on that storage get it too);
//   the old storage leaves the residency set once the submissions that used it complete. Returns the entries moved. tex_widen and the internal resolution (rs_rescale) use it
static int tex_swap_storage(id<MTLTexture> base, id<MTLTexture> w) {
    pthread_mutex_lock(&g_smu);
    nvn_hmap *ms[] = {&g_by_serial, &g_ghost, &g_ghost_active, &g_alias}; int n = 0;
    // 打包贴图（NvPkg）表里存的是 NvPkg 对象，贴图在它的 tex 里：同样换掉。原先只有 tex_widen 自己换，内部分辨率（rs_rescale）换不到——新存储没人持有，
    //   打包颜色目标仍是原尺寸、同遍深度缩到一半（11-09 #312 暗黑地牢2，S2A_RES_SCALE=0.5：同遍附件尺寸不一，iPhone 上闪粉色块）
    for (int m = 0; m < 4; m++)
        for (uint32_t i = 0; i < ms[m]->cap; i++) {
            void *v = ms[m]->vals[i]; if (!v) continue;
            if (v == (__bridge void *)base) { CFRelease(v); ms[m]->vals[i] = (void *)CFBridgingRetain(w); n++; }
            else if (m == 0) { __unsafe_unretained id o = (__bridge id)v; if ([o isKindOfClass:[NvPkg class]] && ((NvPkg *)o)->tex == base) { ((NvPkg *)o)->tex = w; n++; } }
        }
    if (g_alias_set && CFSetContainsValue(g_alias_set, (__bridge const void *)base)) { CFSetRemoveValue(g_alias_set, (__bridge const void *)base); CFSetAddValue(g_alias_set, (__bridge const void *)w); }
    g_ser_gen++;
    pthread_mutex_unlock(&g_smu);
    defer_obj_release(base);   // out of the residency set once the submissions that used it complete
    return n;
}
static int tex_widen(const tex_t *t, NSUInteger r, NSUInteger rh) {   // 1 = the storage is r wide and rh high now (canvas units: a storage the internal resolution scaled is r × s, nvn_rscale.inc)
    id<MTLTexture> base = tex_mtl(t);
    if (!base) return 0;
    tex_extent cur = tex_extent_at(t, base, 0, 0);
    if (cur.canvas.width >= r && cur.canvas.height >= rh) return 1;
    tex_extent extent = tex_extent_grow(t, base, r, rh);
    int scaled = rs_state(base) == RS_SCALED; NSUInteger cw = extent.canvas.width, ch = extent.canvas.height;
    r = extent.physical.width; rh = extent.physical.height;
    const char *why = tex_widen_why(t);
    if (why) {   // registered as widenable because the widened drawing fits (see tex_widen_why): drawn at its own width, a viewport past it is a red line (draw)
        { static uint64_t seen[32]; static int ns; int k = 0; while (k < ns && seen[k] != t->serial) k++;   // one line per storage, with the reason
          if (k == ns && ns < 32) { seen[ns++] = t->serial; MLOG("widen: render target ser=%llu %lux%lu storage not widened (%s): drawn at its own width; a viewport past it is a red line", (unsigned long long)t->serial, (unsigned long)base.width, (unsigned long)base.height, why); } }
        return 0;
    }
    MTLTextureDescriptor *d = [MTLTextureDescriptor new];
    d.textureType = base.textureType; d.pixelFormat = base.pixelFormat; d.width = r; d.height = rh; d.depth = base.depth;
    d.arrayLength = base.arrayLength; d.mipmapLevelCount = base.mipmapLevelCount; d.sampleCount = base.sampleCount;
    d.storageMode = base.storageMode; d.cpuCacheMode = base.cpuCacheMode; d.hazardTrackingMode = base.hazardTrackingMode; d.resourceOptions = base.resourceOptions; d.usage = base.usage;
    __unsafe_unretained id po = tex_get(t->serial); NvPkg *pk = [po isKindOfClass:[NvPkg class]] ? po : nil;
    if (pk) d.usage |= MTLTextureUsageRenderTarget;   // 打包贴图建时不带渲染目标用途（当附件时才补）：放宽的存储就是附件
    id<MTLTexture> w = [g_dev newTextureWithDescriptor:d];
    if (!w) { RED_ONCE(112, "widen: render target ser=%llu %lu → %lu wide could not be created", (unsigned long long)t->serial, (unsigned long)base.width, (unsigned long)r); return 0; }
    res_add(w); tex_fill(w, wd_poison() != 0);
    if (scaled) rs_set_info(w, RS_SCALED, cw, ch); else if (rs_state(base) == RS_BLACK) rs_set_info(w, RS_BLACK, 0, 0);   // the new storage keeps the internal resolution's record
    id<MTL4ComputeCommandEncoder> b = blit();
    NSUInteger slices = base.arrayLength * (base.textureType == MTLTextureTypeCube || base.textureType == MTLTextureTypeCubeArray ? 6 : 1);
    for (NSUInteger l = 0; l < base.mipmapLevelCount; l++)
        for (NSUInteger sl = 0; sl < slices; sl++)
            enc_b_copy_texture(b, base, sl, l, MTLOriginMake(0, 0, 0), MTLSizeMake(MAX(base.width >> l, 1u), MAX(base.height >> l, 1u), 1), w, sl, l, MTLOriginMake(0, 0, 0));
    int n = tex_swap_storage(base, w);   // 打包贴图换的是 NvPkg 自己的 tex（tex_swap_storage 里）
    if (g_wd_widened++ < 8) MLOG("widen: render target storage ser=%llu %lux%lu format %lu widened to %lux%lu (%d table entries moved)", (unsigned long long)t->serial, (unsigned long)base.width,
                                 (unsigned long)base.height, (unsigned long)base.pixelFormat, (unsigned long)r, (unsigned long)rh, n);
    return 1;
}
static void attach(MTLRenderPassAttachmentDescriptor *a, const tex_t *t, const view_t *v, int has_v) {
    id<MTLTexture> base = tex_mtl(t); a.texture = base;
    tex_extent extent = tex_extent_at(t, base, has_v && v->set_levels ? v->base_level : 0, has_v && v->set_layers ? v->min_layer : 0);
    if (has_v && v->set_levels) a.level = extent.level;
    if (has_v && v->set_layers) { if (t->d.target == 2) a.depthPlane = extent.layer; else a.slice = extent.layer; }
    if (base && mtl_fmt_block(base.pixelFormat)) { if (!bcrt_attach(a, base, v, has_v)) { rt_view_fmt(base, v, has_v); a.texture = nil; } return; }   // compressed formats: a shadow or nothing (see rt_view_fmt)
    if (base && mtl_fmt_depth(base.pixelFormat) && bcrt_attach(a, base, v, has_v)) return;   // a depth texture through a colour view: a shadow (see shrt_block)
    // A view that changes the format is attached as a Metal view of that format (pipeline formats follow the attachment). SMBW's last pass writes the RGBA8 swapchain texture through an RGBA8_SRGB view, so the hardware encodes sRGB on write;
    // attaching the base texture instead stored the linear values as they were and the whole picture came out dark (every value decoded from sRGB once more, on the Mac and the iPhone). The view lives until this submission completes
    if (base && has_v && v->set_format) {
        MTLPixelFormat pf = rt_view_fmt(base, v, has_v);
        // Defence in depth: rt_view_fmt already filters incompatible pairs, but a new caller must never let
        // one through — newTextureViewWithPixelFormat aborts the whole process instead of returning nil.
        if (pf != base.pixelFormat && !mtl_pfv_compatible(base.pixelFormat, pf)) {
            RED_ONCE(184, "render target view %#x → Metal %u over base %lu is not compatible: drawing in the base format", v->format, (unsigned)pf, (unsigned long)base.pixelFormat);
        } else if (pf != base.pixelFormat) {
            id<MTLTexture> vw = [base newTextureViewWithPixelFormat:pf];
            if (vw) { a.texture = vw; defer_obj_unref(vw); }
            else RED_ONCE(67, "cannot create the render target view: format %#x (base texture Metal format %lu)", v->format, (unsigned long)base.pixelFormat);
        } else { uint32_t want = 0; uint8_t swz[4];
            if (nvn_fmt_to_mtl(v->format, &want, swz) && want && want != (uint32_t)base.pixelFormat)
                RED_ONCE(68, "render target view format %#x cannot be attached (base texture Metal format %lu was created without the format-view usage): drawing in the base format", v->format, (unsigned long)base.pixelFormat); }
    }
}
// mode 1 (clear_only): a pass opened only to land pending clears, attaching only the attachments that have clears; mode 2: the lookahead proves this pass does not use depth-stencil, so depth is not attached.
// clear_only: a pass opened only to land pending clears, attaching only the attachments that have clears - the other attachments are not touched by this pass, and attaching them costs a pointless load and store on TBDR
// (Mac character select screen: the color-clear pass drags along a 400x225 depth load and store)
static id<MTL4RenderCommandEncoder> rp_begin_ex(int clear_only);
static id<MTL4RenderCommandEncoder> rp_begin(void) { return rp_begin_ex(0); }
static id<MTL4RenderCommandEncoder> rp_begin_ex_(int clear_only);
static id<MTL4RenderCommandEncoder> rp_begin_ex(int clear_only) { AP_B; id<MTL4RenderCommandEncoder> e = rp_begin_ex_(clear_only); AP_E(1); return e; }
static void bare_dims(NSUInteger *w, NSUInteger *h);
// S2Arm first-use skip (after LASRecomp / MeloNX): a draw whose pipeline is being compiled in the background is skipped instead of making the submit thread
//   wait for it (mhrise 10-26: a fresh install's first run built 111 such pipelines on the submit thread); the draw after it is ready takes it as before. Only where losing it costs
//   no more than a frame: every colour / depth target was attached in the last two frames too (drawn every frame: a one-off bake target waits), and neither shader writes storage
//   (MeloNX allowAsyncCompileSkip). On by default on every platform (a Mac play session stalled 14 s on one frame's first uses, #187); DM_NVN_FIRST_SKIP=0 waits instead, which frame replay sets because it compares pixels
static int first_skip_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DM_NVN_FIRST_SKIP");
        v = !(e && !strcmp(e, "0"));
        MLOG("first-use skip %s: draws whose pipeline compiles in the background %s (DM_NVN_FIRST_SKIP)", v ? "on" : "off", v ? "are skipped until it is ready" : "wait for it"); }
    return v;
}
static nvn_hmap g_rt_seen = {.klen = 8};
// The same history keyed by storage (memory + format) instead of the texture object's serial: a game that makes new texture objects over the same memory every frame
//   (Breath of the Wild's dynamic resolution: 1564×720 → 1407×648 → 1329×612 G-buffer views; Tears of the Kingdom's G-buffer: a new serial every frame) never had two frames on one
//   serial, so every first use in its G-buffer pass waited for its pipeline on the submit thread (11-06 iPhone BotW: 214 of 507 ms after MARK). Storage drawn every frame and started
//   fresh this frame is made again next frame whatever object views it. Key: {storage address, format}
typedef struct { uint64_t mem, fmt; } rt_mem_key;
static nvn_hmap g_rt_seen_mem = {.klen = sizeof(rt_mem_key)};
static nvn_hmap g_rt_fresh = {.klen = 8};   // serials started fresh in g_rt_history_frame (clear / full coverage)
static uint64_t g_rt_history_frame;
static int g_rt_history_valid;
// Only the serialized submit/replay thread touches these tables. Finalize is
// too early to retire a serial: recorded texture snapshots can be replayed later.
static uint32_t rt_history_frame(void) {
    uint64_t frame = atomic_load_explicit(&g_cur_frame, memory_order_relaxed);
    uint32_t f = (uint32_t)(frame + 1);
    if (g_rt_history_valid && frame == g_rt_history_frame) return f;
    if (g_rt_history_valid && !(frame % 300))
        MLOG("first-use RT history before frame %llu: fresh %u entries / %u slots, seen %u entries / %u slots",
             (unsigned long long)frame, g_rt_fresh.n, g_rt_fresh.cap, g_rt_seen.n, g_rt_seen.cap);
    nvn_hm_clear(&g_rt_fresh, NULL);
    if (!g_rt_history_valid || frame < g_rt_history_frame || ((frame + 1) >> 32) != ((g_rt_history_frame + 1) >> 32)) {
        nvn_hm_clear(&g_rt_seen, NULL); nvn_hm_clear(&g_rt_seen_mem, NULL);   // reset / 32-bit tag wrap: rebuild the previous-frame evidence
    } else for (int t = 0; t < 2; t++) { nvn_hmap *h = t ? &g_rt_seen_mem : &g_rt_seen;
        for (uint32_t i = 0; i < h->cap;) {
            uint64_t v = (uint64_t)(uintptr_t)h->vals[i], last = v >> 32;
            if (v && (uint64_t)f - last > 2) {
                nvn_hm_del(h, h->keys + (size_t)i * h->klen);
                // Backward-shift deletion can move an unvisited key into this slot.
            } else i++;
        } }
    g_rt_history_frame = frame; g_rt_history_valid = 1;
    return f;
}
static void rt_fresh_mark(const tex_t *t) {
    if (!t || !t->serial || !first_skip_on()) return;
    rt_history_frame();
    nvn_hm_put(&g_rt_fresh, &t->serial, (void *)1);   // current-frame membership; never store the empty-slot value at tag wrap
}
// Started fresh this frame: in this pass or an earlier one (a G-buffer cleared by its first pass and loaded by the next ones is made again every frame). A temporal history or an
//   accumulation target is never cleared, so it never qualifies (mhrise 10-26: requiring this very pass refused 225 of 256 first uses)
static int rt_fresh_now(const tex_t *t) {
    if (!t) return 1;
    rt_history_frame();
    return nvn_hm_get(&g_rt_fresh, &t->serial) != NULL;
}   // render target serial → the game frames (+1) it was last / previously attached at, packed in the high / low 32 bits (submit thread only)
static void rt_seen_put(nvn_hmap *h, const void *key, uint64_t f) {
    uint64_t v = (uint64_t)(uintptr_t)nvn_hm_get(h, key);
    if ((v >> 32) != f) nvn_hm_put(h, key, (void *)(uintptr_t)((f << 32) | (v >> 32)));
}
static int rt_seen_had(nvn_hmap *h, const void *key) {
    uint64_t v = (uint64_t)(uintptr_t)nvn_hm_get(h, key), last = v >> 32, prev = v & 0xffffffffu;
    return prev && last - prev <= 2;
}
static void rt_seen_mark(const tex_t *t) {
    if (!t || !t->serial || !first_skip_on()) return;
    uint64_t f = rt_history_frame();
    rt_seen_put(&g_rt_seen, &t->serial, f);
    if (t->mem) { rt_mem_key mk = {(uint64_t)(uintptr_t)t->mem, t->d.format}; rt_seen_put(&g_rt_seen_mem, &mk, f); }
}
// Drawn in the last two frames: by this texture object, or by any object over the same storage and format (g_rt_seen_mem). g_rt_steady_mem: answers given only by the storage
static uint64_t g_rt_steady_mem;
static int rt_seen_steady(const tex_t *t) {
    if (!t) return 1;
    rt_history_frame();
    if (rt_seen_had(&g_rt_seen, &t->serial)) return 1;
    rt_mem_key mk = {(uint64_t)(uintptr_t)t->mem, t->d.format};
    int r = t->mem && rt_seen_had(&g_rt_seen_mem, &mk); g_rt_steady_mem += r;
    return r;
}
// S2Arm widen: whole-level texture clears made while the storage still had the game's width, this frame (clear_tex → wd_pclr_note). When wd_widen_rts then widens that
//   storage, the clear is made again on the widened storage: it reaches the whole widened width and reports the target cleared, as a clear after widening does
static struct { uint64_t ser, frame; p_clear_tex c; } g_wd_pclr[16]; static unsigned g_wd_pclr_n;
static void clear_tex(const p_clear_tex *c);
static void wd_pclr_note(const p_clear_tex *c) {
    unsigned i = g_wd_pclr_n++ % 16; g_wd_pclr[i].ser = c->tex->serial; g_wd_pclr[i].frame = atomic_load(&g_cur_frame); g_wd_pclr[i].c = *c;
}
static void wd_pclr_apply(const tex_t *t) {   // no pass is open (wd_widen_rts): clear_tex may open its own
    uint64_t f = atomic_load(&g_cur_frame);
    for (int i = 0; i < 16; i++) if (g_wd_pclr[i].ser == t->serial && g_wd_pclr[i].frame == f && g_wd_pclr[i].c.tex == t) {
        p_clear_tex c = g_wd_pclr[i].c; g_wd_pclr[i].ser = 0; clear_tex(&c);
    }
}
static id<MTL4RenderCommandEncoder> rp_begin_ex_(int clear_only) {
    if (g_enc) return g_enc;
