            pd.depthAttachment.clearDepth = depth_clear_value(pf, R.cd); pd.depthAttachment.storeAction = MTLStoreActionStore;
            if (clear_only != 4 && (pf == MTLPixelFormatDepth32Float_Stencil8 || pf == MTLPixelFormatStencil8)) {   // 4: depth only
