// User manifest: shaders / pipelines created synchronously on the submit thread while running on this machine, warmed up at the next launch together with the seed manifest.
// Path = DM_PSO_USER, or pso_user.tsv under the parent of the save directory (DM_SAVE, Documents/save on iOS); tests use a fresh save copy per run, so they do not pollute each other
static NSString *pso_user_path(void);
// ---------- GPU error quarantine (10-26 commander: no whole-run switch to the generic mode; the draw that faulted is skipped, and remembered) ----------
// Metal 4's commit feedback names no encoder, so the suspects of a faulted commit (an error that is not an innocent victim's) are the program pairs whose pipeline was first built
//   for that commit (quar_built): a pipeline and its shaders the GPU had already run were not what changed. They are skipped from then on (pso_get_ returns nil, counted as an error
//   drop) and written to gpu_quarantine.tsv beside pso_user.tsv, read at the next start, so later runs skip them too. More than QUAR_MAX new pairs in the commit: nothing pinned,
//   the error is only reported. DM_NVN_QUARANTINE=0 turns it off (a run that wants every draw, to find the faulting shader)
enum { QUAR_MAX = 16 };
static NSMutableSet<NSString *> *g_quar; static NSMutableArray<NSString *> *g_quar_new; static pthread_mutex_t g_quar_mu = PTHREAD_MUTEX_INITIALIZER; static int g_quar_n;
static int quar_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_QUARANTINE"); v = !(e && !strcmp(e, "0")); } return v; }
static NSString *quar_path(void) { NSString *u = pso_user_path(); return u ? [u.stringByDeletingLastPathComponent stringByAppendingPathComponent:@"gpu_quarantine.tsv"] : nil; }
static void quar_load(void) {   // caller holds g_quar_mu
    if (g_quar) return;
    g_quar = [NSMutableSet set]; g_quar_new = [NSMutableArray array];
    NSString *p = quar_path(), *t = p ? [NSString stringWithContentsOfFile:p encoding:NSUTF8StringEncoding error:nil] : nil;
    for (NSString *l in [t componentsSeparatedByString:@"\n"]) if (l.length && ![l hasPrefix:@"#"]) [g_quar addObject:l];
    g_quar_n = (int)g_quar.count;
    if (g_quar_n) MLOG("GPU error quarantine: %d program pairs skipped from the start (%s)", g_quar_n, p.UTF8String);
}
static NSString *quar_name(NvShader *vs, NvShader *fs) { return [NSString stringWithFormat:@"%.16s\t%.16s", vs ? vs->key : "-", fs ? fs->key : "-"]; }
static int quar_has(NvShader *vs, NvShader *fs) {   // submit thread, before a pipeline is built
    if (!quar_on()) return 0;
    pthread_mutex_lock(&g_quar_mu); quar_load(); int hit = g_quar_n && [g_quar containsObject:quar_name(vs, fs)]; pthread_mutex_unlock(&g_quar_mu);
    return hit;
}
static void quar_built(NvShader *vs, NvShader *fs) {   // submit thread: a pipeline first built for the commit being encoded
    if (!quar_on()) return;
    pthread_mutex_lock(&g_quar_mu); quar_load(); if (g_quar_new.count <= QUAR_MAX) [g_quar_new addObject:quar_name(vs, fs)]; pthread_mutex_unlock(&g_quar_mu);
}
static NSArray<NSString *> *quar_take(void) {   // submit thread, at commit: this commit's suspects
    if (!quar_on()) return nil;
    pthread_mutex_lock(&g_quar_mu); quar_load(); NSArray *a = g_quar_new.count ? [g_quar_new copy] : nil; [g_quar_new removeAllObjects]; pthread_mutex_unlock(&g_quar_mu);
    return a;
}
static void quar_fault(NSArray<NSString *> *sus, NSError *err) {   // completion: a commit faulted
    if (!quar_on()) return;
    if (!sus.count || sus.count > QUAR_MAX) { static int n; if (n++ < 8) MLOG("【红】 GPU error quarantine: the faulted commit first built %lu pipelines, %s (%s)", (unsigned long)sus.count, sus.count ? "too many to pin, nothing skipped" : "none new, nothing skipped", err.localizedDescription.UTF8String); return; }
    pthread_mutex_lock(&g_quar_mu);
    NSMutableArray *add = [NSMutableArray array]; for (NSString *q in sus) if (![g_quar containsObject:q]) { [g_quar addObject:q]; [add addObject:q]; }
    g_quar_n = (int)g_quar.count;
    NSString *p = quar_path();
    if (add.count && p) { FILE *f = fopen(p.fileSystemRepresentation, "a"); if (f) { for (NSString *q in add) fprintf(f, "%s\n", q.UTF8String); fclose(f); } }
    pthread_mutex_unlock(&g_quar_mu);
    for (NSString *q in add) MLOG("【红】 GPU error quarantine: program pair %s skipped from now on (the faulted commit first built its pipeline; %s)", q.UTF8String, p ? "remembered for later runs" : "this run only");
}
static NSString *pso_user_path(void) {
    const char *u = getenv("DM_PSO_USER"), *save = getenv("DM_SAVE");
    if (u && *u) return @(u);
    return save && *save ? [[@(save) stringByDeletingLastPathComponent] stringByAppendingPathComponent:@"pso_user.tsv"] : nil;
}
static FILE *g_pso_user; static int g_pso_user_checked;
static NSMutableSet<NSString *> *g_pso_user_seen;
static FILE *pso_user_file(void) {
    if (g_pso_user_checked) return g_pso_user;
    g_pso_user_checked = 1;
    NSString *path = pso_user_path();
    if (path) g_pso_user = fopen(path.fileSystemRepresentation, "a");
    return g_pso_user;
}
static void pso_user_record(const char *fmt, ...) {
    FILE *f = pso_user_file();
    if (!f) return;
    char line[8192]; va_list ap; va_start(ap, fmt); vsnprintf(line, sizeof line, fmt, ap); va_end(ap);
    if (!g_pso_user_seen) {
        g_pso_user_seen = [NSMutableSet set];
        NSString *seed = g_shmap_path ? [g_shmap_path.stringByDeletingLastPathComponent stringByAppendingPathComponent:@"pso_manifest.tsv"] : nil;
        NSMutableArray<NSString *> *paths = [NSMutableArray array]; if (seed) [paths addObject:seed]; NSString *user = pso_user_path(); if (user) [paths addObject:user];
        for (NSString *path in paths) { NSString *txt = [NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:nil];
            for (NSString *old in [txt componentsSeparatedByString:@"\n"]) if (old.length && ![old hasPrefix:@"#"]) [g_pso_user_seen addObject:old]; }
    }
    size_t ll = strlen(line); NSString *s = [[NSString alloc] initWithBytes:line length:ll && line[ll - 1] == '\n' ? ll - 1 : ll encoding:NSUTF8StringEncoding];   // Compared with the manifest file line by line (without the newline)
    if (!s || [g_pso_user_seen containsObject:s]) return;
    [g_pso_user_seen addObject:s]; fputs(line, f); fflush(f);
}
#include "pso_archive.h"   // S2Arm: per-pipeline binary archive (after MacNativeGames, MIT)
// Archive keys: a render pipeline by its pso_skey, as pso_user.tsv records it; nil (not archived) for a specialized fragment (readable-tile merge) or a diagnostic override
static NSString *par_rkey(const pso_key *k, NvShader *vs, NvShader *fs, int merged, id fsfn) {
    if (fsfn || merged) return nil;
