}
static NSString *par_ckey(NvShader *cs, int fc) {   // fc: the pipeline is of the sampler-emulation variant with these SE_* bits (dispatch, se_want): another archive entry from main0's
    if (!cs || !cs->key[0]) return nil;
    size_t n = strnlen(cs->key, sizeof cs->key); char b[sizeof cs->key + 2]; memcpy(b, cs->key, n);
    if (fc) b[n++] = (char)('0' + fc);   // the key's own bytes and one more: no main0 key spells another's
    return [@"c" stringByAppendingString:par_hash(b, n)];
}
// Build the library from a .metallib file without permanently occupying a file descriptor: newLibraryWithURL keeps that file open for as long as the library object lives (one per game shader - of the 258 descriptors the iOS app permanently holds in a run, 213 are these,
// while the default soft limit of an iOS process is 256; new shaders created in other acts raise it further). Here the file is mapped into memory and closed immediately, and the library is built from the in-memory data; the mapping is released when the library's data object is freed
static __thread int t_lib_layer;
// S2Arm 11-05: set by prog_get around its shader_get when the program's guest compute code holds tensor-core matrix multiplies (the game's own upscaling network,
//   nvn_tensor.inc): that shader is never dispatched, so shader_build parses its reflection only (the stand-in reads the bindings) and loads no library
//   (Zelda: Ocarina of Time: 11 programs, 11.2 MB of library slices built at the opening, in the 4 GB..window address range that ran out in its 3D load)
static __thread int t_refl_only;
static id<MTLLibrary> lib_from_file(NSString *path, NSError **err) {
    int fd = open(path.fileSystemRepresentation, O_RDONLY); struct stat st;
    if (fd < 0 || fstat(fd, &st) || st.st_size <= 0) { if (fd >= 0) close(fd); if (err) *err = [NSError errorWithDomain:NSPOSIXErrorDomain code:errno userInfo:@{NSLocalizedDescriptionKey: [NSString stringWithFormat:@"cannot open %@", path]}]; return nil; }
    size_t len = (size_t)st.st_size; void *m = mmap(NULL, len, PROT_READ, MAP_PRIVATE, fd, 0); close(fd);
    t_lib_layer = m != MAP_FAILED && memmem(m, len, "render_target_array_index", 25) != NULL;   // the library's functions use the layer: for a vertex library, its output (shader_load)
    if (m == MAP_FAILED) { if (err) *err = [NSError errorWithDomain:NSPOSIXErrorDomain code:errno userInfo:@{NSLocalizedDescriptionKey: [NSString stringWithFormat:@"mmap failed %@", path]}]; return nil; }
    dispatch_data_t d = dispatch_data_create(m, len, s2a_qos_global(S2A_QOS_IO_BG), ^{ munmap(m, len); });
    return [g_dev newLibraryWithData:d error:err];
}
// S2Arm: the shipped library is one container (b-<chain>/lib.idx + lib.NNN.pak, graphics/nvn/lib_pack.inc): a shader's library and reflection are slices of a mapped shard.
//   A b-<chain>/ without lib.idx is one file per key (<name>.metallib / <name>.json): the Mac cache, a local build and the gate replays; whether a package carries the library is gfxmode.c's call.
//   The on-device fallback translation (DM_MSL_FALLBACK) is always one file per key
#define LP_LOG MLOG
// Library segments go to the host high range (native vawin.c s2a_host_hi_range), not the low range the GC grows its segments in (11-05 Bloodstained / Xuan-Yuan Sword 7 managed OOM).
//   Weak definition: graphics unit tests that do not link the host have no window (-1: map as before, no red)
__attribute__((weak)) int s2a_host_hi_range(uint64_t *lo, uint64_t *hi) { *lo = *hi = 0; return -1; }
#define LP_HI_RANGE(lo, hi) s2a_host_hi_range(lo, hi)
#include "../../lib_pack.inc"
static lp_pack g_libpack; static int g_libpack_ok;   // lp_open: 1 container, 0 one file per key, -1 a broken container (red, nothing loads)
static lp_pack *lp_pack_get(void) {
    static dispatch_once_t once;
    dispatch_once(&once, ^{ int r = g_msl_dir ? lp_open(&g_libpack, g_msl_dir.fileSystemRepresentation, DMSH_CHAIN) : 0;
        if (r == 1) MLOG("direct library container: %u records in %u shards (%s/lib.idx)", g_libpack.n, g_libpack.nshard, g_msl_dir.UTF8String);
        g_libpack_ok = r; });
    return g_libpack_ok == 1 ? &g_libpack : NULL;
