// 多程序合集（runtime/include/s2a_programs.h）：游戏 ExecuteProgram(n) 切到同包另一支程序走进程内重启，这支程序的着色器库在 <游戏数据>/programs/<n>/shaders/direct。
//   宿主（host_adapt.m s2a_direct_program_switch）先把 DM_MSL_DIR / DM_NVN_SHMAP 改到那里再调这里：映射表、c1_full、cb_extent 重读，库容器按新目录重开，预热按新表的清单再起。
//   只在会话之间调（客体线程都已收回、预热 / 预载已停，nvn_session.inc）。已建好的着色器对象按内容键缓存，两支程序同键 = 同一份翻译，不清。
//   回 1 = 换了；0 = 映射表路径没变，什么都不动
int nvn_be_reload_direct_library(void) {
    shmap_load();   // 首次读走过 once，之后 shmap_load 不会再读：这里直接调 shmap_load_once
    NSString *np = shmap_path();
    if (g_shmap_path && [np isEqualToString:g_shmap_path]) return 0;
    NSString *old = g_shmap_path;
    lp_pack_get();   // 同理：让库容器的 once 先走过（旧目录），下面按新目录重开
    if (g_libpack.idx) munmap((void *)g_libpack.idx, g_libpack.idx_len);
    memset(&g_libpack, 0, sizeof g_libpack); g_libpack_ok = 0;
    g_shmap = nil; g_c1_full = nil; g_c1_full_valid = 0; g_cb_ext = nil;
    g_warm_started = 1;   // 先挡住 shmap_load_once 里的预热：预热要用库容器，等新目录的库容器开好再起
    shmap_load_once();
    int r = g_msl_dir ? lp_open(&g_libpack, g_msl_dir.fileSystemRepresentation, DMSH_CHAIN) : 0; g_libpack_ok = r;
    MLOG("multi-program: shader map %s → %s, library %s (container %s)", old.UTF8String ?: "-", np.UTF8String, g_msl_dir.UTF8String ?: "-", r == 1 ? "opened" : r == 0 ? "none, one file per key" : "broken");
    g_warm_started = 0; warm_start();   // 同首次：读完映射表就起预热
    return 1;
}
// A library name <16 hex key>_b / _bf / _bv / _b_t<d> / _bg<i> / _bgv / _bgs<i> / _bgc → its container kind (json: the reflection beside it); -1 if the name is not one
static int lp_kind_of(const char *name, int json) {
    if (strlen(name) < 18 || name[16] != '_') return -1;
    const char *s = name + 17;
    if (!strcmp(s, "b")) return json ? LP_K_BJSON : LP_K_B;
    if (!strcmp(s, "bf")) return json ? -1 : LP_K_BF;
    if (!strcmp(s, "bv")) return json ? -1 : LP_K_BV;
    if (!strcmp(s, "ft")) return json ? -1 : LP_K_FT;   // a pixel shader's typed-output variants (dmsh_build.py ft_finish)
    if (!strcmp(s, "se")) return json ? -1 : LP_K_SE;   // a shader's sampler-emulation variant, precompiled where the census saw it used (se_packed)
    if (!strcmp(s, "bgv")) return json ? LP_K_BGVJSON : LP_K_BGV;
    if (!strcmp(s, "bgc")) return json ? LP_K_BGCJSON : LP_K_BGC;   // passthrough-geometry fast path (nvn_geometry.inc geo_draw)
    if (s[0] == 'b' && s[1] == 'g' && s[2] == 's' && s[3] >= '0' && s[3] <= '9' && !s[4]) return (json ? LP_K_BGSJSON : LP_K_BGS) + (s[3] - '0');
    if (s[0] == 'b' && s[1] == '_' && s[2] == 't' && s[3] >= '0' && s[3] <= '2' && !s[4]) return json ? -1 : LP_K_BT + (s[3] - '0');   // a hull shader's other domains (dmsh_build.py tess_finish)
    if (s[0] == 'b' && s[1] == 'g' && s[2] >= '0' && s[2] <= '9' && !s[3]) return (json ? LP_K_BGJSON : LP_K_BG) + (s[2] - '0');
    return -1;
}
// S2Arm: options for MSL compiled on the device (fallback translations, typed-output variants) — the same convention as the offline iOS chain (ios_metal.py METAL):
//   preserveInvariance for the [[invariant]] positions, and relaxed math (10-27 Odyssey: the translated shaders reproduce Maxwell's NaN semantics with isnan selects; the default fast
//   mode lets the compiler assume no NaN / Inf and drop them — offline-built shaders kept them, these did not)
static MTLCompileOptions *dm_msl_opts(void) {
    MTLCompileOptions *co = [MTLCompileOptions new]; co.preserveInvariance = YES; co.mathMode = MTLMathModeRelaxed;
    return co;
}
static id<MTLLibrary> lib_from_pack(const char *name, NSError **err) {
    lp_pack *p = lp_pack_get(); int k = lp_kind_of(name, 0);
    if (!p && !g_libpack_ok) return lib_from_file([NSString stringWithFormat:@"%@/%s.metallib", g_msl_dir, name], err);
    if (!p || k < 0) { if (err) *err = [NSError errorWithDomain:NSPOSIXErrorDomain code:ENOENT userInfo:@{NSLocalizedDescriptionKey: [NSString stringWithFormat:@"%s is not in the library container", name]}]; return nil; }
    return lp_library(p, g_dev, name, (unsigned)k, &t_lib_layer, err);   // one library a segment: a batched library's keys share it (lib_pack.inc); t_lib_layer as lib_from_file
}
