static id<MTLFunction> lib_entry(id<MTLLibrary> lib, NSString *name) {
    id<MTLFunction> f = lib && name ? [lib newFunctionWithName:name] : nil;
    if (f.functionConstantsDictionary.count) { NSError *e = nil; f = [lib newFunctionWithName:name constantValues:[MTLFunctionConstantValues new] error:&e]; }
    return f;
}
static NSData *json_from_pack(const char *name) {
