static NvShader *shader_build(NSString *pc, int stage, int layer, int depth_zero) {
    NSError *e = nil;
    // S2Arm: a key missing from the library is looked up in DM_MSL_FALLBACK (the on-device fallback translation writes <key>_b.metal + .json there; iOS cannot store a metallib built at runtime)
    NSString *dir = g_msl_dir;
    NSData *jd = json_from_pack(pc.UTF8String);   // S2Arm: from the library container, or its file without one (lib_pack.inc)
    const char *fb = getenv("DM_MSL_FALLBACK");
    if (!jd && fb && *fb) { NSString *fd = @(fb); if ((jd = [NSData dataWithContentsOfFile:[NSString stringWithFormat:@"%@/%@.json", fd, pc]])) dir = fd; }
    NSDictionary *j = jd ? [NSJSONSerialization JSONObjectWithData:jd options:0 error:nil] : nil;
    if (j && dir != g_msl_dir && !fb_json_current(j)) { MLOG("【红】 shader %s: the fallback translation has chain %s / translator %s, this build expects %s / %s", pc.UTF8String, [[j[@"chain"] description] UTF8String], [[j[@"xfp"] description] UTF8String], DMSH_CHAIN, fb_xfp() ?: "(no s2a_dsh_xfp)"); return nil; }
    if (j && stage == 2 && [j[@"gs_slice"] isKindOfClass:[NSDictionary class]] && [j[@"chain"] isEqual:@DMSH_CHAIN]) {   // a slice-writing geometry shader has no library: a stub prog_fold_gs replaces
        NvShader *o = [NvShader new]; o->stage = 2; o->lay_loc = -1; strlcpy(o->key, pc.UTF8String, sizeof o->key);
        o->gs_loc = [j[@"gs_slice"][@"loc"] intValue]; o->gs_comp = [[j[@"gs_slice"][@"comp"] description] UTF8String][0];
        return o;
    }
    if (stage == 2 && !j) return nil;   // missing geometry translation: the caller's red line says so
    if (t_refl_only && stage == 5 && j && [j[@"chain"] isEqual:@DMSH_CHAIN] && !tensor_native_json(j)) {   // old tensor libraries: reflection only
        NvShader *o = [NvShader new]; o->gs_loc = o->lay_loc = -1; o->stage = 5; o->tensor = 1; strlcpy(o->key, pc.UTF8String, sizeof o->key);
        o->fnpfx = [j[@"fn_prefix"] isKindOfClass:[NSString class]] ? j[@"fn_prefix"] : @"";
        char err[160]; if (nvn_refl_from_json(j, &o->rf, err, sizeof err)) { MLOG("【红】 shader %s reflection conversion failed: %s", pc.UTF8String, err); return nil; }
        static _Atomic int n; if (atomic_fetch_add(&n, 1) < 16) MLOG("compute shader %s: tensor-core network, reflection only (its library is not loaded: it is never dispatched)", pc.UTF8String);
        return o;
    }
    NSString *lp = [NSString stringWithFormat:@"%@/%@.metallib", dir, pc];
    // a batched library (json fn_lib, dmsh_build.py unity_flush): every key of the batch has the same library, built once and kept (by its name; in the container all those keys' records are one slice)
    static NSMutableDictionary<NSString *, id<MTLLibrary>> *ulibs; static os_unfair_lock ulock = OS_UNFAIR_LOCK_INIT;
    NSString *ul = dir == g_msl_dir && [j[@"fn_lib"] isKindOfClass:[NSString class]] ? j[@"fn_lib"] : nil;
    id<MTLLibrary> lib = nil;
    if (ul) { os_unfair_lock_lock(&ulock); lib = ulibs[ul]; os_unfair_lock_unlock(&ulock); }
    if (!lib) lib = dir == g_msl_dir ? lib_from_pack(pc.UTF8String, &e) : [NSFileManager.defaultManager fileExistsAtPath:lp] ? lib_from_file(lp, &e) : nil;
    if (lib && ul) { os_unfair_lock_lock(&ulock); if (!ulibs) ulibs = [NSMutableDictionary dictionary]; if (!ulibs[ul]) ulibs[ul] = lib; else lib = ulibs[ul]; os_unfair_lock_unlock(&ulock); }
    if (!lib && dir != g_msl_dir) {   // S2Arm fallback: MSL source compiled here, same options as the offline chain (dm_msl_opts)
        NSString *src = [NSString stringWithContentsOfFile:[NSString stringWithFormat:@"%@/%@.metal", dir, pc] encoding:NSUTF8StringEncoding error:&e];
        if (src) { MTLCompileOptions *co = dm_msl_opts(); t_lib_layer = [src containsString:@"render_target_array_index"]; lib = [g_dev newLibraryWithSource:src options:co error:&e]; }
        if (lib) MLOG("shader %s loaded from the fallback translation (%s)", pc.UTF8String, fb);
    }
    if (!lib || !j) { MLOG("【红】 failed to load shader %s: %s", pc.UTF8String, e ? e.localizedDescription.UTF8String : "no reflection json"); return nil; }
    if (![j[@"chain"] isEqual:@DMSH_CHAIN]) { MLOG("【红】 shader %s has translation chain version %s, but this host expects %s", pc.UTF8String, [[j[@"chain"] description] UTF8String], DMSH_CHAIN); return nil; }
    if (layer && !j[@"entry_layer"]) { MLOG("【红】 vertex shader %s has no layer entry points", pc.UTF8String); return nil; }
    NvShader *o = [NvShader new]; o->gs_loc = o->lay_loc = -1;
    o->fnpfx = [j[@"fn_prefix"] isKindOfClass:[NSString class]] ? j[@"fn_prefix"] : @"";
    if (stage == 0 && [j[@"layer_from"] isKindOfClass:[NSDictionary class]]) { o->lay_loc = [j[@"layer_from"][@"loc"] intValue]; o->lay_comp = [[j[@"layer_from"][@"comp"] description] UTF8String][0]; }
    char err[160];
    if (nvn_refl_from_json(j, &o->rf, err, sizeof err)) { MLOG("【红】 shader %s reflection conversion failed: %s", pc.UTF8String, err); return nil; }
    if (o->rf.dyn && !DM_GAME_TEX_DYN_SLOTS) {   // dynamic texture handles (TEXD / SAMPD) only where the profile says the game picks them from c2's tables, as before otherwise
        // (rf.c1 is freed by dealloc when o goes: freeing it here too was a double free, which aborted FINAL FANTASY RESONANCE at its first such shader)
        MLOG("【红】 shader %s reflection conversion failed: a texture handle the translator could not trace to one slot (profile key tex_dyn_slots off)", pc.UTF8String); return nil; }
    if (o->rf.unb_uncov) {   // #968: texture bindings the runtime normalization bits do not cover (binding > 31, geometry): counted, never silent
        static _Atomic uint64_t n_sh, n_b; uint64_t k = atomic_fetch_add(&n_sh, 1) + 1, nb = atomic_fetch_add(&n_b, o->rf.unb_uncov) + o->rf.unb_uncov;
        if (k <= 8 || !(k & (k - 1))) MLOG("unnorm bits: shader %s has %u texture bindings outside the s2a_flags.yzw bitmap (normalization compiled in); %llu such bindings in %llu shaders so far",
                                           pc.UTF8String, (unsigned)o->rf.unb_uncov, (unsigned long long)nb, (unsigned long long)k); }
    if (rt_range_on()) o->range_ro=rt_range_bindings_ro(j);
    NSString *entry = j[@"entry"];
    if (stage == 0) {
        atomic_fetch_add(&g_vs_loaded, 1);
        if (depth_zero) { if (j[@"entry_z"]) entry = j[@"entry_z"]; else RED_ONCE(85, "vertex shader %s has no near=0 entry (entry_z): depth stays in the GL convention", pc.UTF8String); }
        if (layer) entry = depth_zero ? j[@"entry_layer_z"] : j[@"entry_layer"];
    }
    if (![entry isKindOfClass:[NSString class]] || !entry.length) { MLOG("【红】 shader %s has no entry for stage %d layer %d depth %d", pc.UTF8String, stage, layer, depth_zero); return nil; }
    if (j[@"entry_geometry_capture"]) {
        NSError *ge = nil;
        o->geo_fn = [lib newFunctionWithName:fnn(o, j[@"entry_geometry_capture"]) constantValues:[MTLFunctionConstantValues new] error:&ge];
        if (!o->geo_fn) MLOG("【红】 vertex shader %s: geometry capture entry failed: %s", pc.UTF8String, ge.localizedDescription.UTF8String);
    }
    NSDictionary *geo = j[@"geometry"];
    if (j[@"geometry_reader"]) o->geo_output = [j[@"geometry_output"] unsignedIntValue];
    if (geo) { o->geo_vertices = [geo[@"vertices"] unsignedIntValue]; o->geo_invocations = [geo[@"invocations"] unsignedIntValue];
        o->geo_output = [geo[@"output"] unsignedIntValue]; o->geo_stride = [geo[@"stride"] unsignedIntValue]; o->geo_index_stride = [geo[@"index_stride"] unsignedIntValue];
        o->geo_pt = [geo[@"passthrough"] boolValue];
        NSArray *tf = [geo[@"tf"] isKindOfClass:[NSArray class]] ? geo[@"tf"] : nil;
        for (NSUInteger b = 0; b < 4 && b < tf.count; b++) { NSArray *e = [tf[b] isKindOfClass:[NSArray class]] ? tf[b] : nil; if (e.count != 2) continue;
            NSArray *ent = e[1]; if (ent.count > 32) continue;
            o->geo_tf_stride[b] = [e[0] unsignedIntValue]; o->geo_tf_n[b] = (uint32_t)ent.count;
            for (NSUInteger k = 0; k < ent.count; k++) { o->geo_tf_off[b][k] = [ent[k][0] unsignedIntValue]; o->geo_tf_comp[b][k] = [ent[k][1] unsignedIntValue]; } } }
    o->fn = [lib newFunctionWithName:fnn(o, entry)]; o->stage = stage; o->load_depth_zero = depth_zero; strlcpy(o->key, pc.UTF8String, sizeof o->key); o->ventry = entry;
    if (stage == 5 && tensor_native_json(j)) {
        o->tensor = 3;
        MLOG("compute shader %s: native HMMA.16816 F16 (%d instructions, SIMD-group matrix ABI 1)", pc.UTF8String, [j[@"tensor_mma_count"] intValue]);
    }
    if (!o->fn) { MLOG("【红】 shader %s: no entry point %s in its library", pc.UTF8String, entry.UTF8String); return nil; }
    // writes the layer (render_target_array_index, named in the library's metadata): its passes are layered and its pipelines get an input class (pso_desc). A library with layer entry points
    // names it for those alone: its main0 / main0_z write no layer
    if (stage == 0) o->layer_out = layer || ((o->fnpfx.length ? [j[@"writes_layer"] boolValue] : t_lib_layer) && !j[@"entry_layer"]);   // a batched library holds other keys' functions too: its own MSL says (json writes_layer)
    // A function that declares function constants cannot go into a pipeline until it is specialized, even when every constant is optional. SPIRV-Cross declares one for shaders that read a
    // texel buffer (spvLinearTextureAlignmentOverride, used only through is_function_constant_defined; one of Pokémon Legends: Z-A's imgui pixel shaders, 2bd5037003980716): an empty set of
    // values keeps its default. Without it the first pipeline with that shader failed Metal's validation (`fragmentFunction main0 cannot be used to build a pipeline state`)
    if (j[@"entry_tf"]) {   // transform feedback capture entry point (dmsh_build.py vs_tf) and the bytes per vertex of each feedback buffer
        o->tf_fn = lib_entry(lib, fnn(o, j[@"entry_tf"])); NSArray *ts = j[@"tf_strides"];
        for (NSUInteger b = 0; b < 4 && b < ts.count; b++) o->tf_stride[b] = (uint16_t)[ts[b] unsignedIntValue];
        if (!o->tf_fn) MLOG("【红】 shader %s: no transform feedback entry point %s in its library", pc.UTF8String, [j[@"entry_tf"] UTF8String]);
    }
    o->push = [j[@"s2a_push"] boolValue];   // S2Arm widen (see NvShader.push)
    o->fragc = [j[@"frag_coord"] boolValue];   // S2Arm widen (see NvShader.fragc)
    if ([j[@"cbuf_use"] isKindOfClass:[NSString class]]) o->cbu = j[@"cbuf_use"];   // S2Arm widen (see NvShader.cbu)
    if ([j[@"pos_slice"] isKindOfClass:[NSString class]]) { o->posb = j[@"pos_slice"]; if ([j[@"pos_ubo"] isKindOfClass:[NSArray class]]) o->posu = j[@"pos_ubo"]; }   // S2Arm widen geometry (see NvShader.posb)
    o->exact = j[@"scale_exact"] ? (int8_t)[j[@"scale_exact"] boolValue] : -1;   // S2Arm widen (see NvShader.ts)
    id size_abi = j[@"resolution_scale_abi"], size_exact = j[@"resolution_scale_exact"];
    if (size_abi && (![size_abi isKindOfClass:[NSNumber class]] || [size_abi doubleValue] != 2 ||
        ![size_exact isKindOfClass:[NSNumber class]] || ([size_exact doubleValue] != 0 && [size_exact doubleValue] != 1))) {
        MLOG("【红】 shader %s: malformed or unsupported resolution-scale ABI metadata", pc.UTF8String); return nil;
    }
    o->size_abi = size_abi != nil;
    for (id r in [j[@"resolution_scale_reasons"] isKindOfClass:[NSArray class]] ? j[@"resolution_scale_reasons"] : @[]) {   // P1-20 probe: slots typed 2D by default (dmsh_xlate QuerySamplerType)
        if (![r isKindOfClass:[NSString class]] || ![r hasPrefix:@"unknown_missing_fact:sampler_type:"]) continue;
        NSRange k = [r rangeOfString:@":slot="]; int sl = k.location == NSNotFound ? -1 : atoi([r substringFromIndex:k.location + k.length].UTF8String);
        if (sl >= 0 && sl < 256) o->d2d[sl >> 6] |= 1ull << (sl & 63);
    }
    o->size_exact = o->size_abi && [size_exact boolValue];
    uint8_t scale_indices[73] = {0};
    for (id e in [j[@"tex_scales"] isKindOfClass:[NSArray class]] ? j[@"tex_scales"] : @[]) {
        if (![e isKindOfClass:[NSArray class]] || [e count] != 3 ||
            ![e[0] isKindOfClass:[NSNumber class]] || ![e[2] isKindOfClass:[NSNumber class]]) {
            MLOG("【红】 shader %s: malformed tex_scales metadata", pc.UTF8String); return nil;
        }
        int idx = [e[0] intValue], reg = [e[2] intValue], img = [e[1] isEqual:@"img"];
        if ([e[0] doubleValue] != idx || [e[2] doubleValue] != reg || idx < 1 || idx > 72 || reg < 0 || reg >= (img ? 32 : NTEX) ||
            (!img && ![e[1] isEqual:@"tex"]) || scale_indices[idx] || o->nts >= 72) {
            MLOG("【红】 shader %s: invalid tex_scales index/slot (%d, %d)", pc.UTF8String, idx, reg); return nil;
        }
        scale_indices[idx] = 1;
        o->ts[o->nts++] = (typeof(o->ts[0])){(uint8_t)idx, (uint8_t)img, (uint8_t)reg};
    }
    if (stage == 5 && j[@"spill"]) { o->spill = [j[@"spill"] unsignedIntValue]; o->spill_slot = [j[@"spill_slot"] unsignedIntValue]; }   // shared-memory spill (dispatch)
    if (stage == 1 && j[@"entry_u"]) { o->u_mask = (uint8_t)[j[@"u_mask"] unsignedIntValue]; o->fn_u = [lib newFunctionWithName:fnn(o, j[@"entry_u"])]; if (!o->fn_u) MLOG("【红】 shader %s: no integer-output entry point %s in its library", pc.UTF8String, [j[@"entry_u"] UTF8String]); }
    // Stages 3 / 4 are the tessellation control / evaluation shaders on Switch 1 and task / mesh on NVN2. A tessellation shader's json carries tess (handled below) and its
    //   msl_entry_kind is vertex / kernel, which is right for it: the task / mesh contract (object / mesh functions, workgroup limits) is not its contract. Applied to it, the
    //   kind check printed a false red line and the workgroup check found no threads, called the shader not usable and skipped its draws (#418: 19 red lines on a Switch 1 game)
    if ((stage == 3 || stage == 4) && [j[@"msl_entry_kind"] isKindOfClass:[NSString class]] && !j[@"tess"]) {   // NVN2 task / mesh shader (interface contract item 6; nvn_geometry.inc mesh_tasks_draw)
        int kind = [j[@"msl_entry_kind"] isEqual:@"object"] ? 1 : [j[@"msl_entry_kind"] isEqual:@"mesh"] ? 2 : 0;
        if (kind != stage - 2) { MLOG("【红】 shader %s at stage %d has msl_entry_kind %s (task shaders are object functions at stage 3, mesh shaders mesh functions at stage 4)", pc.UTF8String, stage, [j[@"msl_entry_kind"] UTF8String]); return nil; }
        o->mesh_kind = (uint8_t)kind; o->mesh_task = [j[@"mesh_task"] boolValue];
        o->mesh_threads = (uint16_t)[j[@"mesh_threads"] unsignedIntValue]; o->mesh_payload = (uint16_t)[j[@"mesh_payload"] unsignedIntValue];
        if (j[@"mesh_relay"]) { o->mesh_relay = (uint8_t)[j[@"mesh_relay"] unsignedIntValue]; o->mesh_relay_pw = [j[@"mesh_relay_payload_words"] unsignedIntValue];
                                o->mesh_relay_sw = [j[@"mesh_relay_slice_words"] unsignedIntValue]; }
        o->mesh_maxv = (uint16_t)[j[@"max_vertices"] unsignedIntValue]; o->mesh_maxp = (uint16_t)[j[@"max_primitives"] unsignedIntValue];
        // What Metal cannot run is red here, at the load (interface contract item 9): a workgroup of no thread or past Metal's 1024, a mesh workgroup past Metal's 256 vertices /
        //   512 primitives, a payload past Metal's 16 KB, shared memory of its own (the build spills it for compute shaders only: json spill)
        const char *why = !o->mesh_threads || o->mesh_threads > 1024 ? "workgroup threads outside 1-1024" : kind == 2 && (o->mesh_maxv > 256 || o->mesh_maxp > 512) ? "more than Metal's 256 vertices / 512 primitives a mesh workgroup" :
                          o->mesh_payload > 16384 && (!o->mesh_relay || !o->mesh_relay_pw || (kind == 2 && !o->mesh_relay_sw)) ? "a payload past Metal's 16 KB" : [j[@"spill"] unsignedIntValue] ? "shared memory of its own" : NULL;
        if (why) { MLOG("【红】 %s shader %s: %s (threads %u, payload %u, vertices %u, primitives %u): not usable, its draws are skipped", kind == 1 ? "task" : "mesh", pc.UTF8String, why,
                        o->mesh_threads, o->mesh_payload, o->mesh_maxv, o->mesh_maxp); return nil; }
        if (kind == 2 && depth_zero) {   // the depth convention, as a vertex shader's main0 / main0_z (contract item 2)
            NSString *z = [j[@"entry_z"] isKindOfClass:[NSString class]] ? j[@"entry_z"] : nil;
            id<MTLFunction> f = z ? [lib newFunctionWithName:fnn(o, z)] : nil;
            if (f) { o->fn = f; o->ventry = entry = z; } else RED_ONCE(151, "mesh shader %s has no near=0 entry (entry_z): depth stays in the GL convention", pc.UTF8String);
        }
    }
    if ((stage == 3 || stage == 4) && j[@"tess"]) {   // S2Arm tessellation: hull / domain shader
        o->tess_mode = [j[@"tess"][@"mode"] unsignedIntValue];
        NSDictionary *vars = j[@"tess"][@"variants"];
        if (vars && [vars isKindOfClass:[NSDictionary class]]) o->tess_variants = vars;
        if (stage == 3) {   // hull: 输出控制点数从首个变体取（所有域的ocp相同）
            for (NSString *k in vars) { NSDictionary *v = vars[k];
                if ([v isKindOfClass:[NSDictionary class]] && v[@"output_control_points"]) { o->tess_ocp = [v[@"output_control_points"] unsignedIntValue]; break; } } }
        else o->tess_ocp = 0;   // domain: ocp无意义
    }
    if (o->fn.functionConstantsDictionary.count) {
        if (stage == 1 && o->fn.functionConstantsDictionary[@"S2A_AT"]) { o->has_atms = 1; o->at_lib = lib; o->at_main = fnn(o, entry); o->at_u = o->fn_u ? fnn(o, j[@"entry_u"]) : nil; }   // gap families 34 / 37 (fs_atms_fn)
        NSError *fe = nil; id<MTLFunction> f = [lib newFunctionWithName:fnn(o, entry) constantValues:[MTLFunctionConstantValues new] error:&fe];
        if (f) o->fn = f; else { MLOG("【红】 shader %s: specializing its function constants failed: %s", pc.UTF8String, fe.localizedDescription.UTF8String); return nil; }
        if (o->fn_u) { f = [lib newFunctionWithName:fnn(o, j[@"entry_u"]) constantValues:[MTLFunctionConstantValues new] error:&fe]; o->fn_u = f; }
    }
    if (!shader_args_init(o)) return nil;
    if (o->rf.has_c1) c1_store(o);
    NSString *ext = g_cb_ext[[pc hasSuffix:@"_b"] ? [pc substringToIndex:pc.length - 2] : pc];   // bytes each uniform slot can read (cb_len), storage slots never written (sb_ro)
    for (NSString *f in [ext componentsSeparatedByString:@" "]) { int r = 0, n = 0;
        if (sscanf(f.UTF8String, "%d:%d", &r, &n) == 2 && r >= 0 && r < 16 && n > 0) o->cb_ext[r] = (uint32_t)n;
        else if (sscanf(f.UTF8String, "s%d", &r) == 1 && r >= 0 && r < 32) o->sb_ro |= 1u << r; }
    return o;
}
// Wait for a shader another thread is building, lending that thread this one's urgency. A dispatch group has no owner, so the system cannot do it by itself: the submit thread used
//   to wait on the background prefetch queue (dm.nvn.sh-pre, QOS_CLASS_BACKGROUND, CPU and I/O throttled) with no priority inheritance. GTA III (11-02, Mac, three runs of four):
//   the game's render thread waited over 10 s at its 4th frame on a prefetch build stuck in page faults reading the library container, and the game's hang watchdog crashed it
//   on purpose. The override (CPU and I/O tier) is taken while g_shader_lock is held and the flight still registered: its builder removes it under that lock before it leaves,
//   so the builder is alive when the override starts. Caller holds g_shader_lock; it is released here
static uint64_t flight_wait_locked(ShaderFlight *flight) {
    pthread_override_t ov = flight->builder && !pthread_equal(flight->builder, pthread_self()) ? pthread_override_qos_class_start_np(flight->builder, QOS_CLASS_USER_INTERACTIVE, 0) : NULL;
    os_unfair_lock_unlock(&g_shader_lock);
    uint64_t start = bp_now();
    dispatch_group_wait(flight->done, DISPATCH_TIME_FOREVER);
    uint64_t elapsed = bp_now() - start;
    if (ov) pthread_override_qos_class_end_np(ov);
    return elapsed;
}
static NvShader *shader_load_depth(NSString *pc, int stage, int layer, int depth_zero, int *built, uint64_t *wait_ns) {
    if (built) *built = 0;
    if (wait_ns) *wait_ns = 0;
    NSString *identity = shader_identity(pc, stage, layer, depth_zero);
    atomic_fetch_add_explicit(&g_shader_requests, 1, memory_order_relaxed);
    os_unfair_lock_lock(&g_shader_lock);
    NvShader *cached = g_shcache[identity];
    if (cached) {
        atomic_fetch_add_explicit(&g_shader_hits, 1, memory_order_relaxed);
        os_unfair_lock_unlock(&g_shader_lock); return cached;
    }
    ShaderFlight *flight = g_shader_flights[identity];
    if (flight) {
        atomic_fetch_add_explicit(&g_shader_waits, 1, memory_order_relaxed);
        uint64_t elapsed = flight_wait_locked(flight);
        atomic_fetch_add_explicit(&g_shader_wait_ns, elapsed, memory_order_relaxed);
        if (wait_ns) *wait_ns = elapsed;
        return flight->shader;
    }
    flight = [ShaderFlight new]; flight->done = dispatch_group_create(); dispatch_group_enter(flight->done); flight->builder = pthread_self();
    if (!g_shader_flights) g_shader_flights = [NSMutableDictionary dictionary];
    g_shader_flights[identity] = flight;
    os_unfair_lock_unlock(&g_shader_lock);
    if (built) *built = 1;
    atomic_fetch_add_explicit(&g_shader_builds, 1, memory_order_relaxed);
    atomic_fetch_add_explicit(&g_shader_build_live, 1, memory_order_relaxed);
    NvShader *shader = shader_build(pc, stage, layer, depth_zero);
    atomic_fetch_sub_explicit(&g_shader_build_live, 1, memory_order_relaxed);
    if (!shader) atomic_fetch_add_explicit(&g_shader_failures, 1, memory_order_relaxed);
    os_unfair_lock_lock(&g_shader_lock);
    if (shader) { if (!g_shcache) g_shcache = [NSMutableDictionary dictionary]; g_shcache[identity] = shader; }
    // Existing waiters receive this attempt's result; a later request retries a
    // failure (including a fallback translation that becomes available later).
    flight->shader = shader;
    [g_shader_flights removeObjectForKey:identity];
    dispatch_group_leave(flight->done);
    os_unfair_lock_unlock(&g_shader_lock);
    return shader;
}
static NvShader *shader_load(NSString *pc, int stage, int layer) {
    return shader_load_depth(pc, stage, layer, stage_depth_moded(stage) && atomic_load(&g_depth_zero), NULL, NULL);
}
static NvShader *shader_load_submit(NSString *pc, int stage, int layer, int depth_zero) {
    uint64_t start = bp_now(), wait_ns = 0; int built = 0;
    NvShader *shader = shader_load_depth(pc, stage, layer, depth_zero, &built, &wait_ns);
    // A shared load can block this frame even when another thread constructs
    // it, and a failed attempt still consumed time. Never count a waiter as a
    // construction; expose its time both in the frame ledger and separately.
    if (built) { if (shader) g_bp_lib_n++; g_bp_lib_ns += bp_now() - start; }
    else g_bp_lib_ns += wait_ns;
    g_bp_lib_wait_ns += wait_ns;
    return shader;
}
// The part of uniform slot reg's binding the shader can read: its first cb_ext bytes when cb_extent.tsv bounds them, else the whole binding
static inline uint64_t cb_len(NvShader *sh, int reg, uint64_t size) { uint32_t e = sh && reg >= 0 && reg < 16 ? sh->cb_ext[reg] : 0; return e && e < size ? e : size; }

static int stage_of(NSString *stage) {
    if ([stage isEqualToString:@"vertex"]) return 0; if ([stage isEqualToString:@"pixel"]) return 1; if ([stage isEqualToString:@"compute"]) return 5;
    if ([stage isEqualToString:@"hull"]) return 3; if ([stage isEqualToString:@"domain"]) return 4; if ([stage isEqualToString:@"geometry"]) return 2;
    if ([stage isEqualToString:@"task"]) return 3; if ([stage isEqualToString:@"mesh"]) return 4;   // NVN2: in the tessellation stages' places (nvn2_cmd.h nvn2_stage_host)
    return -1;
}
#define NVN_RT_RANGE_RO_IMPL 1
// Private continuation accepts only B reflection that is explicitly RO; a missing rw on sbuf does not let the default 0 count as proof; does not change the existing reflection / translation chain.
static int rt_range_bindings_ro(NSDictionary *j) {
    if (![j[@"route"] isEqual:@"B"] || ![j[@"bindings"] isKindOfClass:[NSArray class]] ||
        ![j[@"drv_reads"] isKindOfClass:[NSDictionary class]] || [j[@"drv_reads"] count]) return 0;
    for (NSDictionary *b in j[@"bindings"]) {
        if (![b isKindOfClass:[NSDictionary class]] || ![b[@"kind"] isKindOfClass:[NSString class]] || ![b[@"msl_type"] isKindOfClass:[NSString class]]) return 0;
        NSString *k=b[@"kind"], *t=b[@"msl_type"];
        if (b[@"rw"] && (![b[@"rw"] isKindOfClass:[NSNumber class]] || [b[@"rw"] boolValue])) return 0;
        if ([k isEqual:@"cbuf"] || [k isEqual:@"c1"]) { if (![t hasPrefix:@"constant "]) return 0; }
        else if ([k isEqual:@"sbuf"]) { if (![b[@"rw"] isKindOfClass:[NSNumber class]] || [b[@"rw"] boolValue] || ![t hasPrefix:@"const device "]) return 0; }
        else if ([k isEqual:@"samp"] || [k isEqual:@"sampt"]) { if (![t isEqual:@"sampler"]) return 0; }
        else if ([k isEqual:@"tex"] || [k isEqual:@"tbuf"]) {
            if (![t hasPrefix:@"texture"] || ([t containsString:@"access::"] && ![t containsString:@"access::sample>"] && ![t containsString:@"access::read>"])) return 0; }
        else return 0;
    }
    return 1;
}
static int rt_range_pr_ro(NvProg *p) {
    if (!p || !p->sh[0] || !p->sh[1]) return 0;
    for (int k=0;k<6;k++) if (p->sh[k] && (k>1 || p->sh[k]->stage != k || !p->sh[k]->range_ro || p->sh[k]->rf.drv_read[0] || p->sh[k]->rf.drv_read[2])) return 0;
    return 1;
}
// S2Arm: an S line means the shader was used (a program the game draws with), however it reached the cache: loaded here, prefetched at ProgramSetShaders or prewarmed from a list.
//   Prefetched shaders used to be recorded when claimed: Splatoon 3 creates 12610 programs in its first 10 s and draws with 287 keys' pipelines, so pso_user.tsv listed all of them
//   and the next start's prepare step loaded every one before the first frame (delivery line 10-27)
static NvShader *shader_used(NvShader *o, NSString *pc, int stage) {
    if (o && !o->s_rec) { o->s_rec = 1; pso_record("S\t%s\t%d\n", pc.UTF8String, stage); pso_user_record("S\t%s\t%d\n", pc.UTF8String, stage); }
    return o;
}
static NvShader *shader_get(NSString *pc, int stage) {
    warm_claim();
    NvShader *o = shader_load_submit(pc, stage, 0, stage_depth_moded(stage) && atomic_load(&g_depth_zero));
    if (!o) return nil;   // the third tier: a shader not prefetched yet is loaded here, at its first use (it is compiled already, only the read is left)
    shader_used(o, pc, stage);
    return o;
}
// A layer variant follows its bound vertex shader's captured depth convention.
static NvShader *shader_get_layer(NvShader *vs) {
    return shader_load_submit(@(vs->key), 0, 1, vs->load_depth_zero);
}
// A program whose geometry shader is a slice writer (a stub with no function, shader_load) draws with its vertex shader's layer entry points instead, which write the layer the geometry
// shader would have picked: the pass is layered (layer_out) and the geometry stage goes. Metal has no geometry stage. Unreal Engine binds each stage from a program of its own (DRAGON QUEST XI S:
// stage masks 1, 2, 4, 8, 16, an empty program for the stages a draw does not use), so a vertex shader is often combined with the previous draw's geometry shader for a moment before that
// stage is rebound: a stub that does not fit its vertex shader stays in the program, and only a draw with it gets a red line (draw_gs_check)
static void prog_fold_gs(NvProg *o) {
    NvShader *g = o->sh[2];
    if (!g || g->fn || !o->sh[0]) return;
    NvShader *v = o->sh[0], *l = v->lay_loc == g->gs_loc && v->lay_comp == g->gs_comp ? shader_get_layer(v) : nil;
    if (!l) return;
    o->sh[0] = l; o->sh[2] = nil;
    static int once; if (!once++) MLOG("geometry shader %s writes only the layer: vertex shader %s draws with its layer entry points instead (layered pass)", g->key, v->key);
}
// A draw whose geometry stage has no function (a slice writer that does not fit the vertex shader, prog_fold_gs) runs without it, reaching only the first layer, as before
static uint64_t g_gs_miss_draws;
static void draw_gs_check(NvProg *pr) {
    if (pr->gs_miss[0]) { g_gs_miss_draws++; static int m; if (m++ < 8) MLOG("【红】 draw with geometry shader %s, which has no library (vertex %s fragment %s)", pr->gs_miss, pr->sh[0] ? pr->sh[0]->key : "-", pr->sh[1] ? pr->sh[1]->key : "-");
        PD("G %llu draw with geometry shader %s, which has no library", g_stat_pass, pr->gs_miss); }
    NvShader *g = pr->sh[2]; static int n;
    if (g && !g->fn && n++ < 8) MLOG("【红】 geometry shader %s picks the layer from input %d.%c, but vertex shader %s has no layer entry points for it (layer_from %d.%c): the draw reaches only the first layer",
                                    g->key, g->gs_loc, g->gs_comp, pr->sh[0] ? pr->sh[0]->key : "-", pr->sh[0] ? pr->sh[0]->lay_loc : -1, pr->sh[0] && pr->sh[0]->lay_loc >= 0 ? pr->sh[0]->lay_comp : '-');
}
static id<MTLLibrary> g_builtin_lib;
static NSMutableDictionary<NSString *, NvShader *> *g_builtin;
// S2Arm tessellation: 固定曲面细分核PSO（count / scan / emit），按需编译（首次曲面绘制时，tess_init）
static id<MTLLibrary> g_tess_lib;
static id<MTLComputePipelineState> g_tess_count, g_tess_scan, g_tess_emit, g_tess_gather;   // gather：VS 捕获记录 → 规范布局控制点（nvn_builtin.h nvn_tess_gather）
static uint64_t g_tess_draws, g_tess_patches, g_tess_skips;   // 统计：曲面绘制次数、片数、跳过次数
static uint64_t g_tess_dom_draws[3], g_tess_dom_skips[5]; static unsigned g_tess_dom = 4;   // 分域：画出（域编码 0–2）/ 跳过（0–2、3 = 未定义的域值、4 = 解出域之前就跳过）；g_tess_dom = 这一笔的域（tess_draw 设）
static NvShader *builtin_get(const char *ctl);
// S2Arm fallback translation (§12.3 s2a_dsh_compile, graphics/nvn/host_adapt.m dm_shader_miss): keys missing from the map are compiled on the device at ProgramSetShaders, while the control section is valid;
// key → stage name kept beside the map (the map itself stays read-only after loading), looked up where the map has no entry
static NSMutableDictionary<NSString *, NSString *> *g_shmap_rt; static pthread_mutex_t g_shmap_rt_mu = PTHREAD_MUTEX_INITIALIZER;
static NSString *shmap_rt_get(NSString *k) { pthread_mutex_lock(&g_shmap_rt_mu); NSString *s = g_shmap_rt[k]; pthread_mutex_unlock(&g_shmap_rt_mu); return s; }
// A key's stage name: the package map, else the device's fallback translation (registered at ProgramSetShaders by dm_shader_miss when the fallback directory has it). The prefetch and the
//   lookahead looked at the package map alone, so a key a run before had translated on the device was loaded (its MSL compiled) on the submit thread at its first draw in every run
//   (11-06 DRAGON BALL Sparking! ZERO, 测试设备1: 25 such keys, none in the package's 2105-key map)
static NSString *shmap_stage(NSString *k) { NSString *s = g_shmap[k]; return s ? s : shmap_rt_get(k); }
void mtl_shmap_rt_add(const char *key, const char *stage) { pthread_mutex_lock(&g_shmap_rt_mu); if (!g_shmap_rt) g_shmap_rt = [NSMutableDictionary dictionary]; g_shmap_rt[@(key)] = @(stage); pthread_mutex_unlock(&g_shmap_rt_mu); }
int mtl_shmap_known(const char *key) { shmap_load(); NSString *k = @(key); return g_shmap[k] != nil || shmap_rt_get(k) != nil || builtin_get(key) != NULL; }
// S2Arm 两段式出包（10-27）：映射表有键不等于库里有这支——热键版包的映射表是全键、库只带热键，缺的那支要照样走首遇现编（dsh_miss.inc），不能让 shader_load 失败去触发直连失败判据。
// 只查索引不读数据（每次 ProgramSetShaders 都会问）：现编过的 / 内置的 → 有；有库容器 → 容器索引里有没有 <键>_b 的反射；没容器（Mac 开发树）→ <键>_b.json 文件在不在
int mtl_shlib_has(const char *key) {
    if (shmap_rt_get(@(key)) != nil || builtin_get(key) != NULL) return 1;
    char name[32]; snprintf(name, sizeof name, "%.16s_b", key);
    lp_pack *p = lp_pack_get();
    if (!p && !g_libpack_ok) { struct stat st; return !stat([NSString stringWithFormat:@"%@/%s.json", g_msl_dir, name].UTF8String, &st); }
    int ok; uint64_t k = lp_key(name, &ok); return p && ok && p->idx && lp_find(p, k, LP_K_BJSON) != NULL;
}
static NvShader *builtin_get(const char *ctl) {
    for (unsigned i = 0; i < sizeof k_nvn_builtin_map / sizeof *k_nvn_builtin_map; i++) {
        if (strcmp(ctl, k_nvn_builtin_map[i].ctl)) continue;
        if (!g_builtin) g_builtin = [NSMutableDictionary dictionary];
        NvShader *o = g_builtin[@(ctl)];
        if (o) return o;
        if (!g_builtin_lib) {
            NSError *e = nil; g_builtin_lib = [g_dev newLibraryWithSource:@(k_nvn_builtin_msl) options:nil error:&e];
            if (!g_builtin_lib) MDIE("embedded compute kernel MSL compile failed: %s", e.localizedDescription.UTF8String);
        }
        o = [NvShader new]; o->fn = [g_builtin_lib newFunctionWithName:@(k_nvn_builtin_map[i].fn)]; o->stage = 5; o->builtin = k_nvn_builtin_map[i].fn;
        g_builtin[@(ctl)] = o;
        return o;
    }
    return nil;
}
// S2Arm tessellation: 编译固定曲面细分核（count / scan / emit），首次曲面绘制时调用（tess_draw开头）
#define TESS_BASE 20         // 曲面细分接口槽位起点（与离线dmsh_build.py一致）
#define TESS_PT_CAP (1u<<20) // 展开容量上限：域点数（超了的片丢弃）
#define TESS_IX_CAP (1u<<22) // 展开容量上限：索引数
static int tess_init(void) {
    if (g_tess_emit) return 1;   // 已编译
    if (!g_tess_lib) {
        NSError *e = nil;
        g_tess_lib = [g_dev newLibraryWithSource:nvn_tess_msl() options:nil error:&e];
        if (!g_tess_lib) {
            static int once; if (!once++) MLOG("【红】 tessellation kernel MSL compile failed: %s; patch draws will be skipped", e.localizedDescription.UTF8String);
            return 0;
        }
    }
    NSError *e = nil;
    g_tess_count = [g_dev newComputePipelineStateWithFunction:[g_tess_lib newFunctionWithName:@"nvn_tess_count"] error:&e];
    if (!g_tess_count) { static int once; if (!once++) MLOG("【红】 nvn_tess_count PSO build failed: %s", e.localizedDescription.UTF8String); return 0; }
    g_tess_scan = [g_dev newComputePipelineStateWithFunction:[g_tess_lib newFunctionWithName:@"nvn_tess_scan"] error:&e];
    if (!g_tess_scan) { static int once; if (!once++) MLOG("【红】 nvn_tess_scan PSO build failed: %s", e.localizedDescription.UTF8String); g_tess_emit = nil; return 0; }
    g_tess_gather = [g_dev newComputePipelineStateWithFunction:[g_tess_lib newFunctionWithName:@"nvn_tess_gather"] error:&e];
    if (!g_tess_gather) { static int once; if (!once++) MLOG("【红】 nvn_tess_gather PSO build failed: %s", e.localizedDescription.UTF8String); return 0; }
    g_tess_emit = [g_dev newComputePipelineStateWithFunction:[g_tess_lib newFunctionWithName:@"nvn_tess_emit"] error:&e];
    if (!g_tess_emit) { static int once; if (!once++) MLOG("【红】 nvn_tess_emit PSO build failed: %s", e.localizedDescription.UTF8String); return 0; }
    return 1;
}
static const prog_t *g_prog_last_ptr; static uint64_t g_prog_last_serial, g_prog_last_gen; static NvProg *g_prog_last;
static __unsafe_unretained NvProg *prog_get(const prog_t *cp) {   // Called only on the submit thread
    prog_t *p = (prog_t *)cp;
    uint64_t gen = g_ser_gen;
    if (p == g_prog_last_ptr && p->serial == g_prog_last_serial && gen == g_prog_last_gen && g_prog_last) return g_prog_last;
    __unsafe_unretained NvProg *have = p->serial ? serial_get(p->serial) : nil;
    if (have) { g_prog_last_ptr = p; g_prog_last_serial = p->serial; g_prog_last_gen = gen; g_prog_last = have; return have; }
    shmap_load();
    NvProg *o = [NvProg new];
    for (unsigned i = 0; i < p->nstage; i++) {
        // Key = sha256(first 0x880 bytes of the control section + code area): many of Mario's shaders share a control section but differ in code (dm/gfx/tools/shader_split.py). It was computed at SetShaders (hle_nvn.c): by now the game may have freed the control section
        uint8_t md[8]; prog_key(p, i, md);
        { static const uint8_t z[8]; static int nz; if (!memcmp(md, z, 8) && nz++ < 8)   // S2Arm: the state behind a zero key (no control section when the key was taken), for the next diagnosis
            MLOG("【红】 program %p stage %u of %u has no key: control %p, code %#llx, magic %#x, serial %llu", (const void *)p, i, p->nstage, p->sd[i].control, (unsigned long long)p->sd[i].data, p->magic, (unsigned long long)p->serial); }
        NSString *k = [NSString stringWithFormat:@"%02x%02x%02x%02x%02x%02x%02x%02x", md[0], md[1], md[2], md[3], md[4], md[5], md[6], md[7]];
        NSString *stage = g_shmap[k];
        if (!stage) stage = shmap_rt_get(k);   // S2Arm: compiled on the device by the fallback translation
        if (!mtl_shlib_has(k.UTF8String) && dm_shader_miss_late(k.UTF8String, p->sd[i].data, p->sd[i].control)) stage = shmap_rt_get(k);   // S2Arm: not in the library (a hot-key package's cold key): compiled now, at its first use (dsh_miss.inc)
        if (!stage && dm_shader_reuse(k.UTF8String)) stage = shmap_rt_get(k);   // S2Arm: never registered (frame replay restores programs without ProgramSetShaders): reuse the fallback directory's earlier compile
        if (!stage) {   // Not in the package: look up the compute kernels embedded in the main body (nvn_builtin.h)
            NvShader *b = builtin_get(k.UTF8String);
            if (b) { o->sh[5] = b; o->smask |= 1u << 5; continue; }
            o->unres = 1;
            MLOG("【红】 shader %s is not in the shader map (DM_NVN_SHDUMP=directory saves its control section and code area)", k.UTF8String);
            // DM_NVN_SHDUMP=directory: shaders missing from the map are saved as <key>.ctl (0x880-byte control section) and <key>.code (code area, length from control +0x704), to trace their source / add them to the map offline
            static const char *shd; static int shd_init; if (!shd_init) { shd = getenv("DM_NVN_SHDUMP"); shd_init = 1; }
            if (shd) { char path[1024]; FILE *f; uint32_t ncode; memcpy(&ncode, (const uint8_t *)p->sd[i].control + (nvn2_on() && nvn2_ctl(p->sd[i].control) ? 0x44 : 0x704), 4);   /* NVN2's code length at +0x44 (nvn2.h) */   // with SHDUMP set the control section is the host's copy
                snprintf(path, sizeof path, "%s/%s.ctl", shd, k.UTF8String); if ((f = fopen(path, "wb"))) { fwrite(p->sd[i].control, 1, 0x880, f); fclose(f); }
                snprintf(path, sizeof path, "%s/%s.code", shd, k.UTF8String);
                if (p->sd[i].data && ncode && ncode < (1u << 24) && (f = fopen(path, "wb"))) { fwrite((const void *)(uintptr_t)p->sd[i].data, 1, ncode, f); fclose(f); } }
            continue;
        }
        int st = stage_of(stage);
        if (st >= 0) o->smask |= 1u << st; else o->unres = 1;
        // S2Arm 11-05: a Switch 2 compute shader with tensor-core matrix multiplies (the game's own upscaling network): not dispatched, stood in by nvn_tensor.inc. The guest code is
        //   read here, while the program is in use (as the fallback paths above do), before the shader is loaded: such a shader is built from its reflection alone (t_refl_only)
        unsigned nh = 0, nsq = 0;
        if (st == 5) {
            const void *ctl = p->sd[i].control; uint32_t ncode = 0;
            if (ctl && (uintptr_t)ctl < (1ull << 47) && nvn2_on() && nvn2_ctl(ctl)) { memcpy(&ncode, (const uint8_t *)ctl + 0x44, 4); if (p->sd[i].data && ncode && ncode < (1u << 24)) nh = nvn2_hmma_count((const void *)(uintptr_t)p->sd[i].data, ncode); }
            if (nh) nsq = nvn2_hsq_count((const void *)(uintptr_t)p->sd[i].data, ncode);   // the network's output domain (nvn_tensor.inc)
        }
        t_refl_only = nh > 0;
        NvShader *sh = st >= 0 ? shader_get([k stringByAppendingString:@"_b"], st) : nil;
        t_refl_only = 0;
        if (sh) o->sh[st] = sh; else MLOG("【红】 shader %s (%s) failed to load: build the shaders with dm/gfx/tools/dmsh_build.py first", k.UTF8String, stage.UTF8String);
        if (sh && st == 5 && nh) sh->tensor_sq = (uint16_t)MIN(nsq, 0xffffu);
        if (sh && st == 5 && sh->tensor != 1 && sh->tensor != 3) {
            if (nh) MLOG("compute shader %s: %u tensor-core matrix multiplies (HMMA): the game's own upscaling network, stood in (nvn_tensor.inc)", sh->key, nh);
            if (!sh->tensor || nh) sh->tensor = nh ? 1 : 2;   // a full build of the same key (an earlier prewarm) is still never dispatched
        }
        if (!sh && st == 2) strlcpy(o->gs_miss, k.UTF8String, sizeof o->gs_miss);
    }
    prog_fold_gs(o);   // a slice-writing geometry shader: the vertex shader's layer entry points instead
    if (o->sh[0]) warm_bump(o->sh[0]->key, o->sh[1] ? o->sh[1]->key : NULL);   // 预热还在跑：这对着色器的管线插到队头（warm_pick）
    if (o->sh[4] && !o->sh[4]->mesh_kind) {   // S2Arm tessellation: 从domain shader解析曲面细分参数（NVN2 网格着色器也在 4 号位，不是域着色器）（prog_get时，首次使用该程序绘制前）
        uint32_t dm = o->sh[4]->tess_mode;
        o->tess_dom = dm & 3; o->tess_part = (dm >> 4) & 3;
        o->tess_cw = (dm >> 8) & 1; o->tess_point = (dm >> 9) & 1;
    }
    o->gp = p;
    if (p->serial) serial_put(p->serial, o);
    return o;
}
void nvn_be_prog_release(prog_t *p) { if (p->serial) serial_del(p->serial); }

// ---------- Descriptor pool: texture ID / sampler ID → object ----------
// At registration the whole texture object is snapshotted (NVN semantics: the descriptor has been written into the pool); view: the MTLTexture for that ID (a view or the base texture, held via CFBridgingRetain) and the serial-table / guest-write generations at the time it was obtained
typedef struct { tex_t t; int ok; view_t v; int has_v; void *view; uint64_t view_id, view_rid, view_ser, view_dirty, view_ep; int view_pkg;   // view_pkg: CPU-written (packaged); only those depend on guest writes (view_dirty)
                 uint32_t view_pf; uint8_t view_tt;                         // view's pixel format / texture type, read once when it is set (the P1-20 probe compares them per binding without a message send)
                 void *alt, *alt_of; uint64_t alt_rid; uint8_t alt_type;   // alt: compatible view used when the shader's declared type differs from view (tex_fit), alt_of = the view it was built from
                 void *ar, *ar_of; uint64_t ar_rid;                         // ar: the alpha-from-red view for the profile's alpha_from_red shaders (tex_alpha_red), ar_of = the view it was built from
                 void *im, *im_of; uint64_t im_rid;                         // im: the view an image slot reads in the shader's pixel class (img_fit), im_of = the view it was built from
                 uint8_t tt1, gone;   // tt1: Metal texture type + 1 a pool walk found here (0 = not looked; pool_gpu skips the ID in tables of another type); gone: its memory pool was finalized (treg_drop_pool_views), until registered again
                 int ser_next, ser_prev; } treg_t;   // the other IDs registered with the same texture serial (g_treg_ser), as ID + 1, 0 = none
static treg_t *g_treg; static int g_ntreg;
// Texture serial → the IDs registered with it (ok): the first ID + 1 here, the rest chained through ser_next / ser_prev. Exactly the IDs with ok set (linked where ok and t change:
//   nvn_be_reg_tex, nvn_be_unreg_tex_range). A finalized texture's IDs are found by its serial (treg_sweep_gone, alias_dead_views): those passes walked the whole registry, about
//   33,000 IDs in Ocarina of Time, at every submission where a texture had been finalized (11-07 E1 on device: 11% of its submit CPU, 39% of Donkey Kong's). Under g_rmu
static nvn_hmap g_treg_ser = {.klen = 8};
static uint64_t g_treg_ser_walk;   // IDs looked at by serial (treg_sweep_gone, alias_dead_views): the work grows with the finalized textures' IDs, not with the registry (t_nvn_treg_sweep)
static void treg_ser_link(int id_) {
    treg_t *r = &g_treg[id_]; uint64_t s = r->t.serial; int h = (int)(uintptr_t)nvn_hm_get(&g_treg_ser, &s);
    r->ser_prev = 0; r->ser_next = h; if (h) g_treg[h - 1].ser_prev = id_ + 1;
    nvn_hm_put(&g_treg_ser, &s, (void *)(uintptr_t)(id_ + 1));
}
static void treg_ser_unlink(int id_) {
    treg_t *r = &g_treg[id_]; uint64_t s = r->t.serial;
    if (r->ser_next) g_treg[r->ser_next - 1].ser_prev = r->ser_prev;
    if (r->ser_prev) g_treg[r->ser_prev - 1].ser_next = r->ser_next;
    else if (r->ser_next) nvn_hm_put(&g_treg_ser, &s, (void *)(uintptr_t)r->ser_next);
    else nvn_hm_del(&g_treg_ser, &s);
    r->ser_next = r->ser_prev = 0;
}
// Lock-free copy of texture ID → serial (the replay hot path only needs the serial: store lookahead index, binding set of the clear-only hoist): texture IDs are 20 bits, fixed 1M entries (BSS, only touched pages are used),
// release write at registration, relaxed atomic read on the reader side, without entering g_rmu (the former h_ser locked and unlocked on every lookup, thousands of times per frame in the camp)
static _Atomic uint64_t g_tser[1 << 20];
static samp_par *g_sreg; static uint8_t *g_sreg_ok; static void **g_sview; static uint64_t *g_srid; static int g_nsreg; static uint64_t g_samp_rereg;   // g_sview: sampler ID → MTLSamplerState (retained)
static void **g_sbview; static uint64_t *g_sbrid;   // 2 per sampler ID: the same sampler with a transparent black / opaque white border (samp_border_rid; the custom border emulation)
// Memory pool Finalize: for texture IDs whose registered texture lives on this pool, drop the cached MTLTexture (view or base texture). The cache used to be released only when the ID was registered again,
// so a linear texture built directly on a pool kept the whole pool buffer alive (6 to 17 finalized 16 MB pool buffers stayed alive in Engage's title demo). If the ID is still used, the next lookup rebuilds it on the slow path
static void treg_drop_ar(treg_t *r) { if (r->ar) { defer_obj_unref((__bridge id)r->ar); CFRelease(r->ar); r->ar = r->ar_of = NULL; r->ar_rid = 0; }
                                     if (r->im) { defer_obj_unref((__bridge id)r->im); CFRelease(r->im); r->im = r->im_of = NULL; r->im_rid = 0; } }   // and the image class view (img_fit)
static void treg_drop_views(treg_t *r) {   // every view the ID caches (view, alt, ar, im): each retains its base texture
    if (r->view) { defer_obj_unref((__bridge id)r->view); CFRelease(r->view); r->view = NULL; r->view_id = r->view_rid = 0; }
    if (r->alt) { defer_obj_unref((__bridge id)r->alt); CFRelease(r->alt); r->alt = r->alt_of = NULL; r->alt_rid = 0; }
    treg_drop_ar(r);
}
// Texture views by texture serial and view parameters, beside the per-ID view: KTGL (Age of Calamity) registers a texture into the next ID of a ring before every bind (about 21,000
// registrations a frame in battle after the first cutscene, 5 in 6 of them a different texture than the ID held), so the per-ID view was rebuilt for nearly every bind: half the
// registrations ended in a new Metal texture view, 45% of the replay's time. A hit is checked against the current base texture (re-uploads and format-view upgrades replace it).
// Only live textures are cached; entries go when the texture is finalized (nvn_be_tex_release) or its pool is (treg_drop_pool_views), and all of them past VC_MAX textures. Under g_rmu
typedef struct { uint32_t pf, l0, nl, s0, ns; uint8_t tt, sw[4], pad[3]; } vc_key;
enum { VC_WAYS = 4, VC_MAX = 16384 };
typedef struct { const void *pool; unsigned next; vc_key k[VC_WAYS]; void *view[VC_WAYS];   // view: retained
                 void *rows, *rows_of; uint64_t rows_rid, rows_n; int rows_exact; } vc_set;   // rows: a texture buffer as 2D rows (tbuf_as_2d; retained, resident), rows_of / rows_n: the buffer texture it was made from and its element count; rows_exact: the exact layout (f1d 2)
static nvn_hmap g_vc = {.klen = 8};   // texture serial → vc_set
static uint64_t g_vc_hit, g_vc_new;
static void vc_rows_drop(vc_set *s) { if (s->rows) { defer_obj_release((__bridge id)s->rows); CFRelease(s->rows); s->rows = s->rows_of = NULL; s->rows_rid = s->rows_n = 0; s->rows_exact = 0; } }
static void vc_set_free(void *p) {
    vc_set *s = p;
    for (int i = 0; i < VC_WAYS; i++) if (s->view[i]) { defer_obj_unref((__bridge id)s->view[i]); CFRelease(s->view[i]); }
    vc_rows_drop(s);
    free(s);
}
static id<MTLTexture> vc_get(uint64_t ser, const vc_key *k, id<MTLTexture> base) {
    vc_set *s = nvn_hm_get(&g_vc, &ser); if (!s) return nil;
    for (int i = 0; i < VC_WAYS; i++) if (s->view[i] && !memcmp(&s->k[i], k, sizeof *k)) {
        id<MTLTexture> v = (__bridge id<MTLTexture>)s->view[i];
        if (v.parentTexture == base) { g_vc_hit++; return v; }
        defer_obj_unref(v); CFRelease(s->view[i]); s->view[i] = NULL; return nil;   // made from a base texture since replaced
    }
    return nil;
}
static vc_set *vc_set_for(uint64_t ser, const void *pool) {   // the texture's entry, made if needed; NULL for a texture already finalized (resolved through g_ghost): nothing would drop the entry
    pthread_mutex_lock(&g_smu); int live = nvn_hm_get(&g_tex_live, &ser) != NULL; pthread_mutex_unlock(&g_smu);
    if (!live) return NULL;
    vc_set *s = nvn_hm_get(&g_vc, &ser);
    if (!s) {
        if (g_vc.n >= VC_MAX) nvn_hm_clear(&g_vc, vc_set_free);
        if (!(s = calloc(1, sizeof *s))) return NULL;
        s->pool = pool; nvn_hm_put(&g_vc, &ser, s);
    }
    return s;
}
static void vc_put(uint64_t ser, const void *pool, const vc_key *k, id<MTLTexture> v) {
    vc_set *s = vc_set_for(ser, pool); if (!s) return;
    unsigned i = s->next++ % VC_WAYS;
    if (s->view[i]) { defer_obj_unref((__bridge id)s->view[i]); CFRelease(s->view[i]); }
    s->k[i] = *k; s->view[i] = (void *)CFBridgingRetain(v); g_vc_new++;
}
// Serials of textures finalized since the last sweep (treg_sweep_gone). An ID registered with a texture keeps its cached views after the texture is finalized; until the ID was registered
// again or its pool finalized they pinned the texture and its storage: Splatoon 3 held 1.0–1.4 GB of finalized textures this way until a scene change, and an iPhone run was terminated at 8 GB
static uint64_t *g_gone; static uint32_t g_gone_n, g_gone_cap;
void mtl_vc_drop(uint64_t ser) {
    pthread_mutex_lock(&g_rmu);
    vc_set *s = nvn_hm_del(&g_vc, &ser); if (s) vc_set_free(s);
    if (g_gone_n == g_gone_cap) { uint32_t c = g_gone_cap ? 2 * g_gone_cap : 256; uint64_t *n = realloc(g_gone, c * sizeof *n); if (n) { g_gone = n; g_gone_cap = c; } }
    if (g_gone_n < g_gone_cap) g_gone[g_gone_n++] = ser;
    pthread_mutex_unlock(&g_rmu);
}
// At the start of a submission: drop the views of IDs whose texture was finalized since the last sweep (the IDs registered with each finalized serial, g_treg_ser). An ID still
// used afterwards rebuilds its view on the slow path, as after its pool is finalized
void treg_sweep_gone(void) {
    pthread_mutex_lock(&g_rmu);
    for (uint32_t k = 0; k < g_gone_n; k++)
        for (int h = (int)(uintptr_t)nvn_hm_get(&g_treg_ser, &g_gone[k]); h; h = g_treg[h - 1].ser_next) {
            treg_t *r = &g_treg[h - 1]; g_treg_ser_walk++;
            if (r->view || r->alt || r->ar || r->im) treg_drop_views(r);
        }
    g_gone_n = 0;
    pthread_mutex_unlock(&g_rmu);
}
void mtl_vc_stats(unsigned *n, uint64_t *hit, uint64_t *made) { pthread_mutex_lock(&g_rmu); *n = g_vc.n; *hit = g_vc_hit; *made = g_vc_new; pthread_mutex_unlock(&g_rmu); }
static void vc_drop_pool(const void *pool) {   // caller holds g_rmu
    for (uint32_t i = 0; i < g_vc.cap;) {   // a deletion shifts later entries back into slot i: look at it again
        vc_set *s = g_vc.vals[i];
        if (s && s->pool == pool) { uint64_t ser; memcpy(&ser, g_vc.keys + (size_t)i * 8, 8); nvn_hm_del(&g_vc, &ser); vc_set_free(s); }
        else i++;
    }
}
// A texture buffer bound to a slot whose 1D integer fetches the translator made 2D reads of rows of NVN_TBUF_ROW texels (nvn_refl f1d; Program.cs RecordTexelFetch1D): a linear 2D texture of
// such rows over the same pool memory, so the shader reads the buffer. Maxwell reads 1D textures and texture buffers with the same instruction and the descriptor decides; without a type
// answer the translator read them as 2D, and Age of Calamity's light and decal lists (and Three Houses' lighting) read the dummy texture, zeros. Kept with the texture's views (vc_set),
// checked against the buffer texture it was made from. Caller holds g_rmu
static uint64_t g_tb2_binds, g_tb2_made, g_tb2_fail, g_tb2_tail;
// exact (nvn_refl f1d 2, Ampere's wrapped fetch): rows sized to the element count (nvn_tbuf_rows_exact: W * H = n), the shader takes W and H from this form and reads 0 past W * H, as the
//   hardware's fetch past a buffer; no such form (an element count with too few factors of two) → the fixed rows, the tail past the buffer readable (counted, first case red)
// 不对齐池偏移的缓冲纹理：对齐副本上的 2D 行视图（见 tbuf_as_2d）。取不到副本（GPU 本次提交里写过这段、超出影子上限、内存不可读）照旧回 nil（这一槽读 0）并点名
static uint64_t g_tb2_shadow, g_tb2_shadow_fail;
static id<MTLBuffer> arena_find(const uint8_t *p, NSUInteger *off, NSUInteger *len);   // 帧暂存块里 p 所在的缓冲（定义在 NvArena 之后）
// #309 (second half) aligned copies made on the GPU timeline. The CPU copy below (ubp_get) refuses what it cannot see at this point: more than 64 KiB, or bytes the GPU wrote
//   earlier in this submission (a lighting list of 1,052,640 R32UI, 4 MiB, written by a compute pass, at a pool offset 32 bytes off the 64 iPhone needs: the copy was refused and
//   the slot read 0 again, the same flicker). Before a draw / dispatch that reads such a buffer texture as 2D rows, tba_prepare ends the open render pass and has the GPU copy
//   the bytes into the frame arena (256-byte aligned), after every earlier GPU write in queue order; the view is made on the copy. A copy holds until the next buffer write outside
//   a render pass or the next submission (g_wr_epoch / g_arena_gen, as the indirect-draw conversions)
typedef struct { uint64_t ser, off; MTLPixelFormat pf; __unsafe_unretained id<MTLBuffer> src; __strong id<MTLBuffer> buf; size_t boff, len; } tba_ent;
enum { TBA_MAX = 32 };
static tba_ent g_tba[TBA_MAX]; static int g_tba_n; static uint64_t g_tba_epoch, g_tba_sub, g_tba_copies, g_tba_bytes, g_tba_splits;
static void tba_valid(void) {
    if (g_tba_epoch == g_wr_epoch && g_tba_sub == g_arena_gen) return;
    for (int i = 0; i < g_tba_n; i++) g_tba[i].buf = nil;
    g_tba_n = 0; g_tba_epoch = g_wr_epoch; g_tba_sub = g_arena_gen;
}
static const tba_ent *tba_find(uint64_t ser, id<MTLTexture> t) {
    tba_valid();
    for (int i = 0; i < g_tba_n; i++) if (g_tba[i].ser == ser && g_tba[i].src == t.buffer && g_tba[i].off == t.bufferOffset && g_tba[i].pf == t.pixelFormat) return &g_tba[i];
    return NULL;
}
// The 2D-row geometry tbuf_as_2d uses (shared with tba_prepare so the copy covers exactly what the view reads); 0 = no 2D-row form
static int tbuf_geom(const tex_t *tt, id<MTLTexture> t, int exact, uint32_t *w, uint32_t *h, uint32_t *row) {
    int bw, bh; uint32_t bpb = (uint32_t)nvn_fmt_bpb(tt->d.format, &bw, &bh); NSUInteger al = linear_align(t.pixelFormat);
    if (!t.buffer || bw != 1 || bh != 1) return 0;
    if (exact && nvn_tbuf_rows_exact(t.width, bpb, (uint32_t)al, w, h, row)) return 1;
    return nvn_tbuf_rows(t.width, bpb, (uint32_t)al, w, h, row);
}
static id<MTLTexture> tbuf_rows_shadow(int tid, id<MTLTexture> t, const tex_t *tt, uint32_t w, uint32_t h, uint32_t row, uint64_t *rid) {
    const tba_ent *ge = tba_find(tt->serial, t);
    if (ge) {   // copied on the GPU before this draw / dispatch (tba_prepare)
        while (h > 1 && (uint64_t)row * h > ge->len) h--;
        MTLTextureDescriptor *gd = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:t.pixelFormat width:w height:h mipmapped:NO];
        gd.resourceOptions = ge->buf.resourceOptions; gd.usage = MTLTextureUsageShaderRead;
        id<MTLTexture> gv = [ge->buf newTextureWithDescriptor:gd offset:ge->boff bytesPerRow:row];
        if (gv) { defer_obj_release(gv); *rid = gv.gpuResourceID._impl; g_tb2_binds++; return gv; }
        if (!g_tb2_shadow_fail++) MLOG("【红】 cannot create the 2D-row view of a GPU-copied texture buffer: %ux%u format %lu row %u at arena offset %lu", w, h, (unsigned long)t.pixelFormat, row, (unsigned long)ge->boff);
        return nil;
    }
    id<MTLBuffer> buf = t.buffer; uint64_t avail = buf.length > t.bufferOffset ? buf.length - t.bufferOffset : 0, want = (uint64_t)row * h;
    uint64_t len = want < avail ? want : avail;   // 末行越过池缓冲的部分本来就是未定义读，副本只取池里有的
    uint64_t lo = (uint64_t)(uintptr_t)tt->mem, g = 0; const uint8_t *c = NULL;
    if (!len || !tt->mem || !ubp_get(lo, lo + len, &g, &c)) {
        if (!g_tb2_shadow_fail++) MLOG("【红】 texture buffer (texture ID %d, %lu elements at pool offset %lu) is not aligned for a 2D-row view and its bytes cannot be read at this point (GPU writes in this submission / too large): the slot reads 0", tid, (unsigned long)t.width, (unsigned long)t.bufferOffset);
        return nil;
    }
    ubq_gpu(g_ubp_q);   // 副本的拷贝在 GPU 读之前做完
