    if (!v) { if (!g_tb2_fail++) MLOG("【红】 cannot create the 2D-row form of a texture buffer: %ux%u format %lu row %u bytes at pool offset %lu", w, h, (unsigned long)t.pixelFormat, row, (unsigned long)t.bufferOffset); return nil; }
    if (!g_tb2_made++) MLOG("texture buffer read by wrapped 1D fetches: bound as %ux%u rows of %u bytes (texture ID %d, %lu elements; first case)", w, h, row, tid, (unsigned long)t.width);
    // A last row only partly the buffer's (more than one row, element count not a multiple of NVN_TBUF_ROW): a fetch at an index from the element count up to the row's end reads the
    //   memory after the buffer, where the hardware's buffer fetch reads 0 (a texture buffer read past its width on Metal gives 0 too: tests/ampere_isa tbuf_oob). Counted and the first cases named
    if (!ex && h > 1 && t.width % NVN_TBUF_ROW && g_tb2_tail++ < 8)
