//   (pool_seen_scan). A handle read from game memory may name any registered texture and only the GPU knows which; without this every texture had to be made in case it is read
//   (upstream reference implementation (MIT) the reference port b1d7c707: Ocarina of Time registers about 33,000 IDs and reads about 300, about 1 GB). Under g_rmu
enum { POOL_SEEN_WORDS = (1u << 20) / 32 };
static __strong id<MTLBuffer> g_seen_buf; static uint32_t g_seen_done[POOL_SEEN_WORDS], g_seen_todo[POOL_SEEN_WORDS]; static uint64_t g_seen_sub = ~0ull;
static inline int pool_seen(int id_) { return id_ >= 0 && id_ < (int)(POOL_SEEN_WORDS * 32) && (g_seen_done[(unsigned)id_ >> 5] >> (id_ & 31) & 1); }
static void pool_seen_clear(int id_) {   // an ID given another texture has not been read as that texture
    if (id_ < 0 || id_ >= (int)(POOL_SEEN_WORDS * 32)) return;
    uint32_t b = 1u << (id_ & 31);
    g_seen_done[(unsigned)id_ >> 5] &= ~b; g_seen_todo[(unsigned)id_ >> 5] &= ~b;
    if (g_seen_buf) atomic_fetch_and((_Atomic uint32_t *)g_seen_buf.contents + ((unsigned)id_ >> 5), ~b);
}
// 贴图池销毁时清它那段编号的登记（hle_nvn.c dpool_finalize）：只动已登记的项（不扩表），同 nvn_be_reg_tex(id, NULL, NULL) 的清法——丢缓存的视图、记登记代号
void nvn_be_unreg_tex_range(int base, int n) {
    if (base < 0 || n <= 0) return;
    pthread_mutex_lock(&g_rmu);
    int end = base + n < g_ntreg ? base + n : g_ntreg, any = 0;
    for (int id_ = base; id_ < end; id_++) { treg_t *rr = &g_treg[id_]; if (!rr->ok && !rr->view && !rr->alt && !rr->ar && !rr->im) continue;
        treg_drop_views(rr); if (rr->ok) treg_ser_unlink(id_); rr->ok = 0; rr->tt1 = rr->gone = 0; pool_seen_clear(id_); pool_dirty(0, id_); any = 1;
        if (id_ < (1 << 20)) atomic_store_explicit(&g_tser[id_], 0, memory_order_release); }
    if (any) g_reg_gen++;
    pthread_mutex_unlock(&g_rmu);
}
void nvn_be_reg_tex(int tid, const tex_t *t, const view_t *v) {
    int id_ = tid; if (id_ < 0) return;
    pthread_mutex_lock(&g_rmu);
    if (id_ >= g_ntreg) { int n = id_ + 1024;
        if (!GROW(g_treg, (size_t)n * sizeof *g_treg, "texture registration table")) { pthread_mutex_unlock(&g_rmu); return; }   // not registered: binds of this ID find nothing (draw skipped / dummy texture)
        memset(g_treg + g_ntreg, 0, (n - g_ntreg) * sizeof *g_treg); g_ntreg = n; }
    // Registering what the ID already holds changes nothing: its view and the registration generation stay (the lookup still checks the base texture). About 1 in 6 of the
    // registrations KTGL (Age of Calamity) makes before every bind repeat the ID's texture; the rest cycle textures through its IDs (the view cache below, vc_get)
    uint64_t null_reads = 0; if (!id_ && t && !g_tid0_reg) { g_tid0_reg = 1; null_reads = g_stat_tex_null; }   // ID 0 holds a texture from now on (tex_by_id)
    treg_t *rr = &g_treg[id_];
    int same = t && rr->ok && rr->has_v == (v != NULL) && !memcmp(&rr->t, t, sizeof *t) && (!v || !memcmp(&rr->v, v, sizeof *v));
    if (rr->gone) { rr->gone = 0; g_reg_gen++; pool_dirty(0, id_); }   // registered again (pool storage made anew), even with the same data
    if (!same) {
        g_reg_gen++; pool_seen_clear(id_); pool_dirty(0, id_); rr->tt1 = 0;
        treg_drop_views(rr);
        if (rr->ok) treg_ser_unlink(id_);
        rr->ok = t != NULL; if (t) rr->t = *t; rr->has_v = v != NULL; if (v) rr->v = *v;
        if (rr->ok) treg_ser_link(id_);
        if (id_ < (1 << 20)) atomic_store_explicit(&g_tser[id_], t ? t->serial : 0, memory_order_release);
    }
    pthread_mutex_unlock(&g_rmu);
    if (null_reads) MLOG("texture ID 0 registered (frame %llu) after %llu reads as an empty slot: those read 0, as hardware's first descriptor before it was written",
                         (unsigned long long)atomic_load(&g_cur_frame), (unsigned long long)null_reads);
    {   // DM_NVN_TREG_ID=n logs every registration of texture ID n: what it holds from then on, and when (the frame being recorded)
        static int want = -2; if (want == -2) { const char *e = getenv("DM_NVN_TREG_ID"); want = e ? atoi(e) : -1; }
        if (want == tid) MLOG("TREG id %d frame %llu %s ser=%llu %ux%u format=%#x target %d view %d", tid, (unsigned long long)atomic_load(&g_cur_frame), same ? "(the same)" : "→",
                              t ? (unsigned long long)t->serial : 0ull, t ? t->d.width : 0, t ? t->d.height : 0, t ? t->d.format : 0, t ? (int)t->d.target : -1, v != NULL);
    }
    {   // DM_NVN_TEXINFO=WxH also logs registrations of textures of that size: the channel swizzle from the builder and from the view.
        //   DM_NVN_TEXINFO=any (or 0x0) drops the size filter: every registration, all=1 on the line; the cap widens to the first 100 (then one every 600) so the log is not flooded
        static int ti = -1, any; static uint32_t tw, th; static uint64_t n;
        if (ti < 0) { const char *e = getenv("DM_NVN_TEXINFO"); ti = e && sscanf(e, "%ux%u", &tw, &th) == 2; if (e && (!strcmp(e, "any") || (ti && !tw && !th))) { ti = 1; any = 1; } }
        if (ti && t && (any || (t->d.width == tw && t->d.height == th)) && (n++ < (any ? 100u : 40u) || n % 600 == 0))
            MLOG("TEXINFO register all=%d id %d ser=%llu format=%#x %ux%ux%u levels %d creation swizzle %d:%d%d%d%d view %d view swizzle %d:%d%d%d%d view format %d:%#x view levels %d+%d",
                 any, tid, (unsigned long long)t->serial, t->d.format, t->d.width, t->d.height, t->d.depth, t->d.levels,
                 t->set_swz, t->swz & 7, t->swz >> 3 & 7, t->swz >> 6 & 7, t->swz >> 9 & 7, v != NULL, v ? v->set_swizzle : 0, v ? v->swz[0] : 0, v ? v->swz[1] : 0, v ? v->swz[2] : 0, v ? v->swz[3] : 0,
                 v ? v->set_format : 0, v ? v->format : 0, v ? v->base_level : 0, v ? v->nlevels : 0);
    }
}
void nvn_be_reg_samp(int sid, const samp_par *sp) {
    int id_ = sid; if (id_ < 0) return;
    pthread_mutex_lock(&g_rmu);
    if (id_ >= g_nsreg) { int n = id_ + 256;
        if (!GROW(g_sreg, (size_t)n * sizeof *g_sreg, "sampler registration table") || !GROW(g_sreg_ok, (size_t)n, "sampler registration table") || !GROW(g_sview, (size_t)n * sizeof *g_sview, "sampler registration table")
            || !GROW(g_srid, (size_t)n * sizeof *g_srid, "sampler registration table") || !GROW(g_sbview, (size_t)n * 2 * sizeof *g_sbview, "sampler registration table")
            || !GROW(g_sbrid, (size_t)n * 2 * sizeof *g_sbrid, "sampler registration table")) { pthread_mutex_unlock(&g_rmu); return; }   // tables grown so far keep the old count (g_nsreg): not registered
        memset(g_sreg_ok + g_nsreg, 0, n - g_nsreg); memset(g_sview + g_nsreg, 0, (n - g_nsreg) * sizeof *g_sview); memset(g_srid + g_nsreg, 0, (n - g_nsreg) * sizeof *g_srid);
        memset(g_sbview + 2 * g_nsreg, 0, (size_t)(n - g_nsreg) * 2 * sizeof *g_sbview); memset(g_sbrid + 2 * g_nsreg, 0, (size_t)(n - g_nsreg) * 2 * sizeof *g_sbrid); g_nsreg = n; }
    if (g_sview[id_]) { CFRelease(g_sview[id_]); g_sview[id_] = NULL; g_srid[id_] = 0; }
    for (int k = 0; k < 2; k++) if (g_sbview[2 * id_ + k]) { CFRelease(g_sbview[2 * id_ + k]); g_sbview[2 * id_ + k] = NULL; g_sbrid[2 * id_ + k] = 0; }
    { nvn_se_ent e; if (nvn_red_entry(0, sp->reduction, sp->minf, sp->magf, sp->ws, sp->wt, sp->wr, sp->cmp_mode, sp->lod_min, sp->lod_max, sp->lod_bias, sp->border, &e)) g_se_any = 1; }
    g_reg_gen++;
    if (g_sreg_ok[id_] && memcmp(&g_sreg[id_], sp, sizeof *sp)) g_samp_rereg++;
    pool_dirty(1, id_);
    g_sreg[id_] = *sp; g_sreg_ok[id_] = 1;
    pthread_mutex_unlock(&g_rmu);
    {   // DM_NVN_SAMPINFO=N (diagnostic): the first N sampler registrations with their whole state (filters, wraps, LOD clamp / bias, anisotropy, compare, reduction)
        static int lim = -1; static _Atomic int n; if (lim < 0) { const char *e = getenv("DM_NVN_SAMPINFO"); lim = e ? atoi(e) : 0; }
        if (lim && atomic_fetch_add(&n, 1) < lim)
            MLOG("SAMPINFO id %d min %u mag %u wrap %u/%u/%u lod %.3f..%.3f bias %.3f aniso %.1f compare %u/%u reduction %u", sid, sp->minf, sp->magf, sp->ws, sp->wt, sp->wr,
                 sp->lod_min, sp->lod_max, sp->lod_bias, sp->aniso, sp->cmp_mode, sp->cmp_func, sp->reduction);
    }
}
// Every 300 frames when it moved: pool IDs registered again with a different state. A game's sampler cache keeps its IDs stable, so a steady count means the cache
// is thrashing and recorded draws may meet a replaced sampler (Super Mario Odyssey before the samp_t layout fix, #100)
static void samp_report(uint64_t frame) {
    static uint64_t r0;
    if (g_samp_rereg == r0) return;
    MLOG("sampler pool up to frame %llu: %llu IDs registered again with a different state", (unsigned long long)frame, (unsigned long long)(g_samp_rereg - r0));
    r0 = g_samp_rereg;
}
// Handles of deferred binds (BindTexturesDeferred) are read at execution: the record keeps the address of the handles (see hle_nvn.c); every reader of a bind record refreshes it first. Command memory is writable, so it is updated in place
// Bind*BuffersDeferred 的记录（stage 带 BIND_BUF_DEFER）：执行到这条时才读游戏那条 NVNbufferRange，读成普通记录交给后面（hle_nvn.c bind_bufs_deferred）
static inline const p_bind_buf *bb_fresh(const void *a, p_bind_buf *t) {
    const p_bind_buf *b = a; if (!(b->stage & BIND_BUF_DEFER)) return b;
    const NVNbufferRange *r = (const NVNbufferRange *)(uintptr_t)b->addr;
    *t = (p_bind_buf){b->stage & ~BIND_BUF_DEFER, b->index, r ? nvn_ga2ca(r->address) : 0, r ? r->size : 0}; return t;   // 游戏内存里的是 GPU 地址（hle_nvn.c GPU 地址空间）
}
static inline void bh_fresh(const p_bind_handles *b) {
    if (b->defer && b->src && b->n > 0 && b->n <= 32) {
        p_bind_pool_bases bases; memcpy(&bases, b->h + b->n, sizeof bases);
        uint64_t *h = (uint64_t *)b->h;
        memcpy(h, (const void *)(uintptr_t)b->src, 8 * (size_t)b->n);
        for (int i = 0; i < b->n; i++) {
            uint64_t tid = h[i] & 0xfffff, sid = h[i] >> 20;
            h[i] = (tid + (uint64_t)bases.tbase) | (sid ? sid + (uint64_t)bases.sbase : 0) << 20;   // texture ID 0 is the pool's first entry too (hle_nvn.c bind_handles)
        }
    }
}
static MTLTextureType ttype(int target, int fallback) {
    switch (target) { case 0: return MTLTextureType2D; case 1: case 7: return MTLTextureType2D; case 2: return MTLTextureType3D;   // 1D as one-row 2D (see where textures are created)
        case 3: return MTLTextureType2DArray; case 4: return MTLTextureType2DArray; case 5: return MTLTextureType2DMultisample;
        case 6: return MTLTextureType2DMultisampleArray; case 8: return MTLTextureTypeCube; case 9: return MTLTextureTypeCubeArray; }
    return (MTLTextureType)fallback;
}
// Out-of-pool texture ID = empty slot: the game itself uses GetSeparateTextureHandle(0xFFFFF) to get a handle and bind it to unused slots (measured call site main+0x1746820,
// texture pool capacity 15256) and never registers that ID. Read 0 per D3D / empty-slot semantics (the same all-zero dummy textures as unbound), no failure; unregistered IDs inside the pool are still reported a failure
static int g_tpool_n; static uint64_t g_stat_tex_oob;
// NVN window origin. In lower-left mode (GL convention, NVN's default) NDC y = -1 lands on a render target's first memory row and window y grows with the row; Metal puts NDC y = +1 on the first row.
// Viewport and scissor rectangles, fragment coordinates, copies and texture coordinates all address the same memory rows in both conventions, so only the direction inside the viewport differs:
// lower-left draws get a viewport of negative height (and the opposite front-face winding), and the window image, stored bottom-up, is flipped at present (and in raw screenshots).
// Link's Awakening keeps the default: read as upper-left, every texture it renders and samples came out consistently flipped and cancelled out, except where the game compensates for the
// convention itself (text rendered into textures for the title and the menus came out upside down, and a MIRROR_Y copy of the frame)
static _Atomic int g_origin_ll;
extern int s2a_nvn_rast_flip;   // hle_nvn.c nvnQueueInitialize: the submitting queue's front-face raster flip
void nvn_be_set_origin_lower_left(int on) { if (atomic_exchange(&g_origin_ll, on) != on) MLOG("window origin: %s", on ? "lower left (GL: viewport flipped, winding reversed, present flipped)" : "upper left"); }
void nvn_be_set_tex_pool_n(int n) { g_tpool_n = n; }
static id<MTLTexture> tex_by_id(int tid) {   // Caller holds g_rmu
