        if (t && t.textureType == (MTLTextureType)r->dtt && r->dpf != NVN_DPF_FLOAT && tex_rgba_atomic_alias(base)) {   // RGBA8 as an R32 integer image: R32 storage under it (tex_upgrade)
            id<MTLTexture> up = tex_upgrade(&g_treg[tid].t, base, MTLTextureUsageShaderRead | MTLTextureUsageShaderWrite | MTLTextureUsageShaderAtomic, pf);
            if (up != base) { while (up.parentTexture) up = up.parentTexture; base = up; t = tex_by_id(tid); args_dirty_all(); }
        }
        if (!t || t.textureType != (MTLTextureType)r->dtt ||
            (base.pixelFormat != MTLPixelFormatR32Uint && base.pixelFormat != MTLPixelFormatR32Sint)) {
            RED_ONCE(128, "native image atomic binding is unsupported (texture ID %d, type %lu, format %lu; shader needs type %u R32 integer); command skipped", tid, (unsigned long)t.textureType, (unsigned long)base.pixelFormat, r->dtt);
            ok = 0; continue;
        }
        MTLTextureUsage need = MTLTextureUsageShaderRead | MTLTextureUsageShaderWrite | MTLTextureUsageShaderAtomic;
        if (t.pixelFormat != pf) need |= MTLTextureUsagePixelFormatView;
        MTLTextureUsage visible = need & ~MTLTextureUsageShaderAtomic;
        if ((base.usage & visible) != visible || !tex_atomic_usage(base)) {
            base = tex_upgrade(&g_treg[tid].t, base, need, pf); while (base.parentTexture) base = base.parentTexture;
            if ((base.usage & visible) != visible || !tex_atomic_usage(base)) {
                RED_ONCE(129, "native image atomic texture usage upgrade failed (texture ID %d); command skipped", tid);
                ok = 0;
            }
        }
    }
    pthread_mutex_unlock(&g_rmu);
    return ok;
}
static inline __attribute__((always_inline)) uint64_t tex_fast_rid(int tid, void **out) {
    if (tid >= 0 && tid < g_ntreg && g_treg[tid].ok && g_treg[tid].view && g_treg[tid].view_ser == g_ser_gen && (!g_treg[tid].view_pkg || g_treg[tid].view_dirty == nvn_dirty_now() || g_treg[tid].view_ep == g_pkg_epoch)) { if (out) *out = g_treg[tid].view; return g_treg[tid].view_rid; }
    id<MTLTexture> t = tex_by_id(tid); if (out) *out = (__bridge void *)t; return t ? t.gpuResourceID._impl : 0;
}
// Buffer textures of a format the host expands (nvn_fmt_expanded: three-component RGB8 / 16 / 32, *_UI2F / *_I2F, RGB10A2 signed): Metal has no such texture buffer format,
//   so they bound the dummy (Warriors Abyss 11-01: "buffer texture format 0x22 not mapped"; an effect read zeros). At the binding the elements are expanded (nvn_fmt_expand, the
//   same expansion as a texture upload: the fourth component 1, as Maxwell's fetch fills a missing component) in this submission's arena, and a texture buffer in the expanded
//   format over that copy is bound. Once per texture and submission; a replaced texture is released after the GPU is done with it. The copy is the bytes as the CPU sees them at
//   encode: GPU writes queued on them in this submission are reported. Caller holds g_rmu
static id<MTLTexture> tbuf_expand(int tid, int rows2d, uint64_t *rid) {   // rows2d: the shader reads it by wrapped 1D fetches (nvn_refl f1d, as tbuf_as_2d): a 2D form of rows over the copy
    if (tid < 0 || tid >= g_ntreg || !g_treg[tid].ok) return nil;
    const tex_t *t = &g_treg[tid].t; int f = t->d.format; uint32_t upf = 0; int db = 0, bw, bh, sb = nvn_fmt_bpb(f, &bw, &bh);
    if (t->d.target != 10 || !nvn_fmt_expanded((uint32_t)f, &upf, &db) || !db || !sb || !t->mem || !t->d.width) return nil;
    static struct { uint64_t sub, ser; int rows2d; __strong id<MTLTexture> tx; } c[64]; static int next;
    for (int i = 0; i < 64; i++) if (c[i].tx && c[i].sub == g_arena_gen && c[i].ser == t->serial && c[i].rows2d == rows2d) { *rid = c[i].tx.gpuResourceID._impl; return c[i].tx; }
    uint64_t n = t->d.width, src = (uint64_t)t->mem;
    if (!nvn_host_readable(src, n * sb)) { RED_ONCE(130, "buffer texture ser=%llu (format %#x, %llu elements) is not readable on the CPU: the dummy is bound", (unsigned long long)t->serial, f, (unsigned long long)n); return nil; }
    if (pend_hits(src, n * sb)) RED_ONCE(131, "buffer texture ser=%llu (format %#x) has GPU writes queued in this submission: expanded from the bytes before them", (unsigned long long)t->serial, f);
    MTLPixelFormat pf = (MTLPixelFormat)upf;
    NSUInteger al = [g_dev minimumLinearTextureAlignmentForPixelFormat:pf]; uint32_t w = (uint32_t)n, h = 1, rw = 0; size_t row = ((size_t)n * db + al - 1) / al * al;
    // exact (rows2d 2): rows sized to the element count when they fit; otherwise the fixed rows, whose tail this copy zero-fills, so a read past the buffer still reads 0
    if (rows2d) { if (!(rows2d == 2 && nvn_tbuf_rows_exact(n, (uint32_t)db, (uint32_t)al, &w, &h, &rw)) && !nvn_tbuf_rows((uint32_t)n, (uint32_t)db, (uint32_t)al, &w, &h, &rw)) { RED_ONCE(133, "buffer texture ser=%llu (format %#x, %llu elements) has no 2D-row form for a wrapped 1D fetch: the slot reads 0", (unsigned long long)t->serial, f, (unsigned long long)n); return nil; } row = rw; }
    size_t total = row * h;
    id<MTLBuffer> b; size_t off = arena_alloc(total, &b); uint8_t *d = (uint8_t *)b.contents + off; const uint8_t *s = (const uint8_t *)(uintptr_t)src;
    memset(d, 0, total);
    for (uint32_t y = 0; y < h; y++) {   // one row of w elements at a time (a texture buffer is one row of n)
        uint64_t i0 = (uint64_t)y * w; if (i0 >= n) break;
        nvn_fmt_expand((uint32_t)f, s + i0 * sb, (size_t)w * sb, (uint32_t)MIN((uint64_t)w, n - i0), 1, d + (size_t)y * row, row);
    }
    MTLTextureDescriptor *td;
    if (rows2d) { td = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:pf width:w height:h mipmapped:NO]; td.resourceOptions = b.resourceOptions; td.usage = MTLTextureUsageShaderRead; }
    else td = [MTLTextureDescriptor textureBufferDescriptorWithPixelFormat:pf width:n resourceOptions:b.resourceOptions usage:MTLTextureUsageShaderRead];
    id<MTLTexture> tx = [b newTextureWithDescriptor:td offset:off bytesPerRow:row];
    if (!tx) { RED_ONCE(132, "cannot create the expanded copy of buffer texture ser=%llu (format %#x, %llu elements)", (unsigned long long)t->serial, f, (unsigned long long)n); return nil; }
    int k = next++ % 64; if (c[k].tx) defer_obj_release(c[k].tx);
    c[k].sub = g_arena_gen; c[k].ser = t->serial; c[k].rows2d = rows2d; c[k].tx = tx;
    static int said; if (!said++) MLOG("buffer texture (format %#x, %llu elements): expanded at the binding%s (tbuf_expand)", f, (unsigned long long)n, rows2d ? ", as 2D rows for wrapped 1D fetches" : "");
    *rid = tx.gpuResourceID._impl; return tx;
}
static MTLSamplerAddressMode wrapm(int w) { return (MTLSamplerAddressMode)nvn_samp_wrap(w); }   // the one NVN wrap table (nvn_red.h)
static MTLSamplerDescriptor *samp_desc(samp_par p);
static id<MTLSamplerState> samp_by_id(int sid) {   // Caller holds g_rmu
    if (sid < 0 || sid >= g_nsreg || !g_sreg_ok[sid]) { RED_ONCE(12, "sampler ID %d not registered", sid); return nil; }
    if (g_sview[sid]) return (__bridge id<MTLSamplerState>)g_sview[sid];
    id<MTLSamplerState> s = [g_dev newSamplerStateWithDescriptor:samp_desc(g_sreg[sid])];
    if (s) { g_sview[sid] = (void *)CFBridgingRetain(s); g_srid[sid] = s.gpuResourceID._impl; }
    return s;
}
// S2Arm widen (族 2, widen_glue.inc g_wd_uvext): the same sampler with horizontal clamp-to-edge, for a widened overlay whose sampling is extended past [0,1]
//   (a texture with smooth edges: a repeat would wrap the far edge in, a seamless tile keeps the original sampler). Caller holds g_rmu; 0 = none
static uint64_t samp_clamp_rid(int sid, void **obj) {
    static void *view[4096]; static uint64_t rid[4096];
    if (sid <= 0 || sid >= g_nsreg || sid >= 4096 || !g_sreg_ok[sid]) return 0;
    if (!view[sid]) { MTLSamplerDescriptor *d = samp_desc(g_sreg[sid]); d.sAddressMode = MTLSamplerAddressModeClampToEdge;
        id<MTLSamplerState> s = [g_dev newSamplerStateWithDescriptor:d]; if (!s) return 0; view[sid] = (void *)CFBridgingRetain(s); rid[sid] = s.gpuResourceID._impl; }
    *obj = view[sid]; return rid[sid];
}
// The sampler of ID sid with a transparent black (white 0) / opaque white (white 1) border colour, all else the same (samp_desc): the two samples the emulation variant mixes a custom
//   border colour from (nvn_red.h, se_bind). Caller holds g_rmu; 0 = none (se_bind then leaves the border flag off)
static uint64_t samp_border_rid(int sid, int white) {
    if (sid <= 0 || sid >= g_nsreg || !g_sreg_ok[sid]) return 0;
    void **v = &g_sbview[2 * sid + white];
    if (!*v) { MTLSamplerDescriptor *d = samp_desc(g_sreg[sid]); d.borderColor = white ? MTLSamplerBorderColorOpaqueWhite : MTLSamplerBorderColorTransparentBlack;
        id<MTLSamplerState> s = [g_dev newSamplerStateWithDescriptor:d]; if (!s) return 0; *v = (void *)CFBridgingRetain(s); g_sbrid[2 * sid + white] = s.gpuResourceID._impl; }
    return g_sbrid[2 * sid + white];
}
static MTLSamplerDescriptor *samp_desc(samp_par p) {
    // DM_NVN_SAMP_LOD0=1 (diagnostic): every sampler's minimum LOD and bias at 0, to tell a too-high LOD from the sampler state from one the shader computes
    static int lod0 = -1; if (lod0 < 0) lod0 = getenv("DM_NVN_SAMP_LOD0") != NULL;
    if (lod0) { p.lod_min = 0; p.lod_bias = 0; }
    MTLSamplerDescriptor *d = [MTLSamplerDescriptor new];
    d.magFilter = p.magf ? MTLSamplerMinMagFilterLinear : MTLSamplerMinMagFilterNearest;
    d.minFilter = (p.minf == 1 || p.minf == 3 || p.minf == 5) ? MTLSamplerMinMagFilterLinear : MTLSamplerMinMagFilterNearest;
    d.mipFilter = p.minf <= 1 ? MTLSamplerMipFilterNotMipmapped : (p.minf == 2 || p.minf == 3) ? MTLSamplerMipFilterNearest : MTLSamplerMipFilterLinear;
    d.sAddressMode = wrapm(p.ws); d.tAddressMode = wrapm(p.wt); d.rAddressMode = wrapm(p.wr);
    d.lodMinClamp = p.lod_min < 0 ? 0 : p.lod_min; d.lodMaxClamp = p.lod_max;
    d.maxAnisotropy = p.aniso < 1 ? 1 : p.aniso > 16 ? 16 : (NSUInteger)p.aniso;
    if (p.cmp_mode) d.compareFunction = (MTLCompareFunction)(p.cmp_func - 1);
    // Reduction (NVN 1 min / 2 max): the minimum or maximum of the texels a filtered sample covers, per channel (Metal 26). Pokémon Legends: Z-A builds its depth pyramid with a min sampler
    // (151607c7a92386cc reads the level above at an explicit LOD) and tests occlusion boxes against it; averaged, the pyramid is nearer than the scene at depth edges.
    // reductionMode is macOS / iOS 26 on (an unrecognized selector on macOS 15 / iOS 18) and does something on an Apple10 GPU only (#800). There it is set with the sampler's own filters:
    //   11-01 on an M5 Max (macOS 26.4.1) all 12 min / mag / mip filter combinations, nearest ones included, read exactly the footprint definition (nvn_red.h; t_red.py checks it); the
    //   old forced linear mip filter (and LOD clamp to 0 without mips) read two levels where a nearest mip filter reads one, and made a nearest minification a magnification.
    //   Elsewhere (g_red_emu) the sampler stays as it is and a draw binding it runs the shader's emulation variant, which reduces the footprint itself at explicit LODs (se_need / se_fn,
    //   table entry nvn_red_entry); a sample without an explicit LOD is averaged there (reported once)
    if (p.reduction == 1 || p.reduction == 2) {
        if (g_red_emu) { static int once; if (!once++) MLOG("sampler reduction (%s): reduced in the shader at explicit LODs (%s); samples without an explicit LOD are averaged", p.reduction == 1 ? "min" : "max", g_red_emu_why); }
        else if (@available(macOS 26.0, iOS 26.0, *)) d.reductionMode = p.reduction == 1 ? MTLSamplerReductionModeMinimum : MTLSamplerReductionModeMaximum;
    }
    // LOD bias (NVN adds it to every sample's LOD, explicit ones too; so does Metal 26's lodBias, 10-28 M5 probe): on the sampler where this GPU applies it, else main0 adds it to each sample,
    //   sample_compare included (S2A.Dsh FsLb, table s2a_lb, lb_fill)
    if (p.lod_bias != 0 && !g_lb_emu) { if (@available(macOS 26.0, iOS 26.0, *)) d.lodBias = p.lod_bias; }
    // Border colour: Metal's nearest of its three (nvn_red.h nvn_samp_border, the one grading); any other colour a clamp-to-border wrap reaches is mixed in the emulation variant (se_bind),
    //   except on a compare sampler (not linear in the border depth) and on a natively reducing one (min / max is not linear in the colour): those keep the nearest, reported once
    { int exact; d.borderColor = (MTLSamplerBorderColor)nvn_samp_border(p.border, &exact);
      if (!exact && (p.ws == 5 || p.wt == 5 || p.wr == 5) && (p.cmp_mode || (!g_red_emu && (p.reduction == 1 || p.reduction == 2)))) { static int once; if (!once++)
          MLOG("【红】 border colour (%g, %g, %g, %g) on a %s sampler: Metal has only transparent black / opaque black / opaque white, the nearest is used (first case)",
               p.border[0], p.border[1], p.border[2], p.border[3], p.cmp_mode ? "depth-compare" : "natively min / max reducing"); } }
    d.supportArgumentBuffers = YES;
    return d;
}
static inline __attribute__((always_inline)) void *samp_fast(int sid) {
    if (sid > 0 && sid < g_nsreg && g_sreg_ok[sid] && g_sview[sid]) return g_sview[sid];
    return (__bridge void *)samp_by_id(sid);
}

// ---------- Argument buffer blocks: one block per submission, reclaimed after the GPU completes ----------
// A block is reused once the GPU is done with what used it: its submission's fence (fence, against g_done) or, when sub_cut handed the segment to the GPU
//   mid-submission, that segment's own number (sfence, against g_seg_done). Without the segment number a submission's blocks waited for the whole submission:
//   10-31 Xenoblade 3's opening submission ran over 16000 draws through the geometry emulation (geo_draw takes up to 256 MiB of scratch a draw) and piled
//   1679 MB of scratch into one submission, filling the host's address room on the Mac's iPhone address model (frame 1897, "cannot allocate ... of frame scratch")
@interface NvArena : NSObject { @public id<MTLBuffer> buf; uint8_t *cpu; uint64_t gpu, fence, sfence; size_t used, len; } @end   // cpu: buf.contents, len: buf.length, kept so an allocation and its writes send no message (upstream (MIT) #1070)
@implementation NvArena @end
static NSMutableArray<NvArena *> *g_arenas; static NvArena *g_cur_arena; static NSMutableArray<NvArena *> *g_sub_arenas;
static id<MTLBuffer> arena_find(const uint8_t *p, NSUInteger *off, NSUInteger *len) {   // 本次提交的块，再找已分段交出的块（影子按 g_arena_gen 复用，可能在后者里）
    for (NSArray<NvArena *> *list in @[g_sub_arenas ?: @[], g_arenas ?: @[]]) for (NvArena *a in list) if (p >= a->cpu && p < a->cpu + a->len) { *off = (NSUInteger)(p - a->cpu); *len = a->len; return a->buf; }
    return nil;
}
// Scratch bounds: a segment is handed to the GPU at the next safe point once ARENA_CUT bytes went into it (sub_cut), and above ARENA_CAP bytes of blocks in all
//   a new block waits for the oldest block the GPU still holds (at most ARENA_WAIT_S: a segment the GPU cannot finish before the host goes on, a wait on a sync
//   the host signals later, must not hang the host; the block is then made anyway and the wait reported)
#define ARENA_CUT (128ull << 20)
#define ARENA_CAP (768ull << 20)
#define ARENA_WAIT_S 2
static uint64_t g_arena_bytes, g_arena_seg, g_seg_fence_n, g_seg_done, g_arena_waits, g_arena_wait_late;   // g_seg_done under g_mu
static uint64_t arena_bytes(void) { return g_arena_bytes; }
static uint64_t arena_waits(void) { return g_arena_waits; }
static int arena_free(NvArena *it, size_t minimum) {
    return it->buf.length >= minimum && ((it->fence && it->fence <= g_done) || (it->sfence && it->sfence <= g_seg_done));
}
static NvArena *arena_new(size_t minimum) {   // caller holds g_mu
    for (int waited = 0;; waited = 1) {
        // The for-in loop variable does not retain the object: take a strong reference first and then remove it from the array, otherwise what is returned after the array releases it is a dangling pointer
        for (NvArena *it in g_arenas) if (arena_free(it, minimum)) { NvArena *r = it; [g_arenas removeObject:r]; r->fence = r->sfence = 0; r->used = 0; return r; }
        if (waited || g_arena_bytes + MAX(minimum, 4u << 20) <= ARENA_CAP) break;
        uint64_t wf = UINT64_MAX, ws = UINT64_MAX;   // the oldest block still with the GPU: by submission, by segment
        for (NvArena *it in g_arenas) { if (it->fence > g_done && it->fence < wf) wf = it->fence; if (it->sfence > g_seg_done && it->sfence < ws) ws = it->sfence; }
        if (wf == UINT64_MAX && ws == UINT64_MAX) break;   // all blocks are this segment's own: nothing to wait for
        struct timespec dl; clock_gettime(CLOCK_REALTIME, &dl); dl.tv_sec += ARENA_WAIT_S; int late = 0;
        while (!(wf != UINT64_MAX && g_done >= wf) && !(ws != UINT64_MAX && g_seg_done >= ws)) if (pthread_cond_timedwait(&g_cv, &g_mu, &dl)) { late = 1; break; }
        g_arena_waits++; if (late && !g_arena_wait_late++) MLOG("【红】 frame scratch: waited %d s for the GPU to give a block back, made a new one (%llu MB of blocks; first case)", ARENA_WAIT_S, (unsigned long long)(g_arena_bytes >> 20));
    }
    NvArena *a = [NvArena new]; a->buf = [g_dev newBufferWithLength:MAX(minimum, 4u << 20) options:MTLResourceStorageModeShared];
    if (!a->buf) MDIE("cannot allocate %zu bytes of frame scratch (%llu MB of blocks)", minimum, (unsigned long long)(g_arena_bytes >> 20));
    a->gpu = a->buf.gpuAddress; a->cpu = (uint8_t *)a->buf.contents; a->len = a->buf.length; res_add(a->buf); g_arena_made++; g_arena_bytes += a->len; return a;
}
void arena_begin(void) { if (!g_arenas) { g_arenas = [NSMutableArray array]; g_sub_arenas = [NSMutableArray array]; } g_cur_arena = nil; g_arena_seg = 0; g_arena_gen++; }
void arena_commit(uint64_t fence) { for (NvArena *a in g_sub_arenas) { a->fence = fence; [g_arenas addObject:a]; } [g_sub_arenas removeAllObjects]; g_cur_arena = nil; g_arena_seg = 0; }
static uint64_t arena_cut(void) {   // sub_cut hands the segment to the GPU: its blocks come back with the segment's number (arena_seg_done)
    uint64_t sf = ++g_seg_fence_n; g_arena_gen++;   // what was cached in these blocks is not handed out again (see g_arena_gen)
    for (NvArena *a in g_sub_arenas) { a->sfence = sf; [g_arenas addObject:a]; } [g_sub_arenas removeAllObjects]; g_cur_arena = nil; g_arena_seg = 0;
    return sf;
}
static void sub_cut(void);   // hands the encoded part of the submission to the GPU (segmented submission, below)
static void arena_seg_done(uint64_t sf) { pthread_mutex_lock(&g_mu); if (sf > g_seg_done) g_seg_done = sf; pthread_cond_broadcast(&g_cv); pthread_mutex_unlock(&g_mu); }
static size_t arena_alloc(size_t n, id<MTLBuffer> *buf) {
    n = (n + 255) & ~(size_t)255; g_arena_seg += n;
    if (!g_cur_arena || g_cur_arena->used + n > g_cur_arena->len) {
        pthread_mutex_lock(&g_mu); g_cur_arena = arena_new(n); pthread_mutex_unlock(&g_mu);
        [g_sub_arenas addObject:g_cur_arena];
    }
    size_t off = g_cur_arena->used; g_cur_arena->used += n; *buf = g_cur_arena->buf; return off;
}
// Keep the logical vertex-zero pointer inside a real MTLBuffer. Only the payload
// is populated; vertex_id still includes first/baseVertex and skips the prefix.
static size_t arena_alloc_origin(size_t n, uint64_t prefix, id<MTLBuffer> *buf) {
    if (!m3_origin_on() || !prefix) return arena_alloc(n, buf);
    uint64_t limit = g_dev.maxBufferLength;
    if (prefix > SIZE_MAX - 255 || n > SIZE_MAX - 255) MDIE("buffer-origin scratch size overflow");
    size_t start = ((size_t)prefix + 255) & ~(size_t)255, size = (n + 255) & ~(size_t)255; g_arena_seg += size;
    if (start > limit || size > limit - start) MDIE("buffer-origin scratch exceeds Metal buffer limit (%llu + %zu > %llu)", (unsigned long long)prefix, n, (unsigned long long)limit);
    size_t off = g_cur_arena ? MAX(g_cur_arena->used, start) : start;
    if (!g_cur_arena || off > g_cur_arena->buf.length || size > g_cur_arena->buf.length - off) {
        pthread_mutex_lock(&g_mu); g_cur_arena = arena_new(start + size); pthread_mutex_unlock(&g_mu);
        [g_sub_arenas addObject:g_cur_arena]; off = start;
    }
    g_cur_arena->used = off + size; *buf = g_cur_arena->buf; return off;
}

// ---------- Draw state ----------
static struct {
    const prog_t *prog;
    const prog_t *cprog;       // compute program: NVN binds it apart from the graphics stages (see OP_BIND_PROGRAM in state_op)
    p_prim_restart restart;
    const prog_t *bst[5];      // program bound per stage (NVN stage bits 1 vertex 2 fragment 4 geometry 8 / 16 tessellation, indices as in NvProg.sh), see bind_stages
    uint64_t bser[5];          // its serial at bind time: a stage kept from an earlier bind is read only while the object still carries it (bind_stages)
    blend_st blend[8]; color_st color; chmask_st chmask; ms_st ms; poly_st poly; ds_st ds;
    va_st attr[16]; int nattr; vs_st stream[16]; int nstream;
    NVNbufferRange vbuf[16];
    p_bind_buf ubo[6][16], ssbo[6][16];
    uint64_t tex[6][NTEX], samp[6][128], img[6][32];
    uint32_t st_vmask[2], st_wmask[2], st_ref[2];
    p_poly_offset po; float vp[16][4]; float dr[2]; int has_vp; int depth_clamp; uint8_t vp_sw[16][4];   // vp_sw: viewport swizzles XOR the identity (p_vp_swizzle)
    float blend_color[4];
    p_tf_bind tf[4]; uint64_t tf_off[4]; int tf_on, rast_discard;   // transform feedback buffers, bytes written into each since Begin, capture active; rasterizer discard (tf_draw)
    int tf_gpu; uint64_t tf_ctl;   // S2Arm: since Begin a geometry shader captured, so the offsets are the GPU counter (nvn_geometry.inc geo_tf), not tf_off; the control buffer Begin named
    int tex_base, samp_base;   // host-table bases of the texture / sampler pool bound (OP_SET_TEX_POOL / OP_SET_SAMP_POOL), for handles read at replay from uniform buffers (encode_args)
    float alpha_ref;   // SetAlphaRef (OP_ALPHA_REF): fragment slot 30 of alpha-tested draws (alpha_ref_bind)
    int patch_size;   // S2Arm tessellation: control points per patch (SetPatchSize), default 3
    uint8_t push[2][NVN2_PUSH_SLOTS][NVN2_PUSH_BYTES];   // NVN2 push constants (OP_PUSH_CONST): graphics / compute, slot k read as c[24 + k] (NVN_RB_PUSH)
    uint64_t push_ver[2][NVN2_PUSH_SLOTS];               // the g_push_seq of the last push into that slot (0 = never pushed): keys the GPU copy (push_gpu)
} S;
// The handle c2 holds at byte b, as encode_args fills the table (DRV2): a combined slot (past slot 31 the image there, tex_slot_h), a separate texture, else none
static uint64_t c2_handle(int stage, unsigned b) {
    if (b >= C2_TEX && b < C2_SEPTEX && !((b - C2_TEX) & 7)) return tex_slot_h(S.tex[stage], S.img[stage], (b - C2_TEX) / 8);
    if (b >= C2_SEPTEX && b < C2_SAMP && !((b - C2_SEPTEX) & 7)) return S.tex[stage][NVN_SEPTEX_SLOT0 + (b - C2_SEPTEX) / 8];
    return 0;
}
// A deferred inline update changes what the draws after it read through the uniform bindings it overlaps (they get a shadow): the argument blocks of those stages are encoded again.
// Only those: marking every stage made each later draw encode all of its blocks again, which with the updates kept across passes cost about 1.5 ms a frame in Breath of the Wild
static uint8_t g_args_dirty[6];
static void ubd_dirty(uint64_t lo, uint64_t hi) {
    for (int st = 0; st < 6; st++) { if (g_args_dirty[st]) continue;
        for (int r = 0; r < 16; r++) { const p_bind_buf *u = &S.ubo[st][r]; if (u->addr && lo < u->addr + u->size && u->addr < hi) { g_args_dirty[st] = 1; break; } } }
}
// Resolved guest streams are separate from the table cache: vconv_bind may overwrite a stream's table slot.
// Take the pool generation before resolving, so a concurrent pool change forces a fresh lookup next time.
static id<MTLBuffer> g_vbuf_zero; static uint64_t g_vbuf_zero_gpu;
static void vbuf_zero(id en, int s) {   // en: the render encoder (plain id: MTL4 types stay inside the wrappers, mtl4 / avail ratchets)
    if (!g_vbuf_zero) { g_vbuf_zero = [g_dev newBufferWithLength:64 options:MTLResourceStorageModeShared]; res_add(g_vbuf_zero); g_vbuf_zero_gpu = g_vbuf_zero.gpuAddress; }
    if (s >= 0) enc_r_vbuf(en, VB_SLOT(s), g_vbuf_zero_gpu);
}
static void bind_vbufs(id<MTL4RenderCommandEncoder> en) {
    static struct { uint64_t addr, gpu, gen; } cache[16];
    uint64_t gen = atomic_load_explicit(&g_pool_gen, memory_order_acquire);
    for (int s = 0; s < 16; s++) {
        uint64_t addr = S.vbuf[s].address, gpu;
        if (!addr) continue;
        if (g_vbuf_cache && cache[s].addr == addr && cache[s].gen == gen) { gpu = cache[s].gpu; g_vbuf_reuse++; }
        else {
            void *mb; uint64_t mo; g_vbuf_resolve++;
            // Not in any pool (审计 #1534 P1-112 读数缺口): the slot used to keep the previous draw's address, so the draw read another buffer silently;
            //   now it reads the zero buffer and says so (the address and slot of the first case)
            uint64_t pav; if (!gpu_addr_want(addr, 1, S.vbuf[s].size, &mb, &mo, &gpu, &pav)) { RED_ONCE(162, "vertex buffer slot %d address %#llx is in no memory pool: the slot reads zeros (first case)", s, (unsigned long long)addr); vbuf_zero(en, s); continue; }
            cache[s].addr = addr; cache[s].gpu = gpu; cache[s].gen = gen;
        }
        enc_r_vbuf(en, VB_SLOT(s), gpu);
    }
    vbuf_zero(en, -1); uint64_t zero_gpu = g_vbuf_zero_gpu;
    enc_r_vbuf(en, 30, zero_gpu);
    if (g_wd_push[0] != 0 || g_wd_push[1] != 0 || g_wd_push[2] != 0 || g_wd_push[3] != 0) {   // S2Arm widen edge push (see g_wd_push): zero reads the zero buffer
        id<MTLBuffer> pb; size_t po = arena_alloc(sizeof g_wd_push, &pb); memcpy((uint8_t *)pb.contents + po, g_wd_push, sizeof g_wd_push); enc_r_vbuf(en, PUSH_SLOT, pb.gpuAddress + po);
    } else enc_r_vbuf(en, PUSH_SLOT, zero_gpu);
}
// Size of an attachment-less pass (rp_begin_ex_): the far corner of viewport 0, else of the scissor, clamped to Metal's 1..16384
static void bare_dims(NSUInteger *w, NSUInteger *h) {
    double x1 = S.has_vp ? MAX(S.vp[0][0], S.vp[0][0] + S.vp[0][2]) : R.has_sc ? (double)R.sc.x + R.sc.w : 1;
    double y1 = S.has_vp ? MAX(S.vp[0][1], S.vp[0][1] + S.vp[0][3]) : R.has_sc ? (double)R.sc.y + R.sc.h : 1;
    *w = (NSUInteger)MIN(MAX(ceil(x1), 1.0), 16384.0); *h = (NSUInteger)MIN(MAX(ceil(y1), 1.0), 16384.0);
}
// The open draw pass has a draw whose shaders write an image or a storage buffer. NVN orders later draws after those writes when the game asks with nvnCommandBufferBarrier
// (ORDER_FRAGMENTS / ORDER_FRAGMENTS_TILED); Metal gives no order between draws of one render pass for shader writes, so such a barrier ends the pass and the next draw opens one
// behind the full consumer barrier. FINAL FANTASY TACTICS - The Ivalice Chronicles composites its UI into the window texture in software, a read-modify-write of the image by draw after
// draw in one attachment-less pass with barrier bits 0x12 between them: without the split a later element read the window before the earlier one had landed and wrote the old pixels
// back (the dialog boxes had holes the size of their text)
static void swrite_note(NvProg *pr) {
    if (!pr || g_pass_swrite) return;
    for (int st = 0; st < 6; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh) continue;
        for (int i = 0; i < sh->rf.nb; i++) if (sh->rf.b[i].rw && (sh->rf.b[i].kind == NVN_RB_IMG || sh->rf.b[i].kind == NVN_RB_IMGU || sh->rf.b[i].kind == NVN_RB_IMGA || sh->rf.b[i].kind == NVN_RB_SBUFP || sh->rf.b[i].kind == NVN_RB_GMEM)) { g_pass_swrite = 1; return; } }
}
// S2Arm (10-30): the written marks and the unwritten-attachment store (udc_on) no longer hang on tbdr_on(). They need no reader inference (an attachment this pass did not write
//   holds in memory exactly what it was loaded from), but sat in the TBDR set, which is off by default because its reader inference misses bindless textures: every game paid a full
//   write-back of every loaded attachment, and "unwritten-attachment store saved" read 0 MB on The Witcher 3 / Octopath 2 / Diablo II / Monster Hunter (frame-rate line, 10-30).
//   Only the zero-source skip below stays in the set
// Does this draw write physical color slot i? The same rule the pipeline's write mask is built by (pso_desc): logical output l (merged-pass map, 0xff = none), its channel mask,
//   and 0 when the fragment shader's output list is known and lacks l. It used to be "channel mask nonzero OR the shader writes it": an attachment the shader never outputs
//   but whose channel mask is left fully open (the default) counted as written, so the unwritten-attachment store almost never fired
static const uint8_t *g_udc_lmap; static int g_udc_fsfn;   // the merged-pass map and replacement fragment function this draw's pipeline was fetched with (draw() keeps them before clearing g_pso_lmap / g_pso_fsfn)
static int udc_slot_writes(int i, __unsafe_unretained NvShader *fs) {
    int l = g_udc_lmap ? g_udc_lmap[i] : i; if (l == 0xff || l > 7) return 0;
    uint32_t m = (S.chmask.mask >> (4 * l)) & 0xf;
    if (fs && fs->rf.color_known && !g_udc_fsfn && !(fs->rf.color_mask >> l & 1)) m = 0;
    return m != 0;
}
// The written marks are kept at the one place every game draw passes, the encode (udc_encode, called by every enc_r_draw* wrapper): udc_note_draw (draw()'s precise
//   account from the pipeline state and the fragment shader's outputs) covers the next encode; any other encode marks every attachment of the open pass written.
//   Opting in per draw path lost writes: DrawTexture, tessellation and merged passes never reported, and their attachments' write-backs became DontCare
//   (t_nvn_drawtex / t_nvn_tess_dom / t_nvn_color_round, 10-30). A draw that encodes more than once counts conservatively from its second encode on
static int g_udc_precise;
static void udc_encode(void) {
    if (g_udc_precise) { g_udc_precise = 0; return; }
    for (int i = 0; i < g_nsd; i++) if (!g_sd[i].wrote) { if (g_sd[i].lskip) noload_witness(i, 6, 0); g_sd[i].wrote = 1; g_sd[i].wwhy = 6; }
}
static void udc_note_draw(NvProg *pr) {
    g_udc_precise = 1;
    if (tbdr_on()) {
        if (R.has_rt) for (int i = 0; i < R.rt.n && i < 8; i++) if (R.rt.color[i]) { zskip_del(R.rt.color[i]->serial); g_zskip_cand_ok[i] = 0; }   // Zero-source set: once really drawn it is no longer all zeros
        if (pr) for (int st = 0; st < 6; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh) continue; for (int i = 0; i < sh->rf.nb; i++) if (sh->rf.b[i].kind == NVN_RB_IMG || sh->rf.b[i].kind == NVN_RB_IMGU) { zskip_clear(); break; } }
    }   // Image slots are writable: conservatively clear
    int image_write = 0;
    uint32_t shader_color_mask = 0;
    if (pr) for (int st = 0; st < 6; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh) continue;
        if (st == 1) shader_color_mask = sh->rf.color_mask;
        for (int i = 0; i < sh->rf.nb; i++) if ((sh->rf.b[i].kind == NVN_RB_IMG || sh->rf.b[i].kind == NVN_RB_IMGU) && sh->rf.b[i].rw) { image_write = 1; break; }
        if (image_write) break;
    }
    if (R.has_rt) for (int i = 1; i < R.rt.n && i < 8; i++)   // a slot attached twice (left unattached) really written: the writes are lost (see rt_dup_slot)
        if ((shader_color_mask >> i & 1) && ((S.chmask.mask >> (4 * i)) & 0xf) && rt_dup_slot(&R.rt, i))
            RED_ONCE(79, "color slot %d holds the same texture as an earlier slot (ser=%llu) and this draw writes it (mask %#x): these writes are lost", i, (unsigned long long)R.rt.color[i]->serial, (S.chmask.mask >> (4 * i)) & 0xf);
    for (int i = 0; i < g_nsd; i++) {
        sd_att *t = &g_sd[i]; int was = t->wrote;
        if (image_write) { t->wrote = 1; t->wwhy = 1; }
        else if (t->depth == 0 && t->idx >= 0 && udc_slot_writes(t->idx, pr ? pr->sh[1] : nil)) { t->wrote = 1; t->wwhy = 2; }
        else if (t->depth == 1 && S.ds.dw) { t->wrote = 1; t->wwhy = 4; }
        else if (t->depth == 2 && S.ds.st && (S.st_wmask[0] || S.st_wmask[1])
                && (S.ds.fail_f != NVN_STENCIL_OP_KEEP || S.ds.zfail_f != NVN_STENCIL_OP_KEEP || S.ds.zpass_f != NVN_STENCIL_OP_KEEP
                    || S.ds.fail_b != NVN_STENCIL_OP_KEEP || S.ds.zfail_b != NVN_STENCIL_OP_KEEP || S.ds.zpass_b != NVN_STENCIL_OP_KEEP)) { t->wrote = 1; t->wwhy = 5; }
        if (t->lskip && !was && t->wrote) noload_witness(i, t->wwhy, 1);
    }
}
// NVN's BindProgram(program, stage bits) binds per stage: the stages in the bits take that program's shaders (a null program unbinds them), the other stages stay.
// Metroid Dread's depth prepass calls BindProgram(program, vertex | fragment), then BindProgram(null, fragment): only the vertex shader remains and depth is drawn.
// Every bind used to replace S.prog as a whole, a null program meant "no program bound", and the prepass's ~140 draws per frame were all dropped: depth stayed empty, the G-buffer's depth EQUAL test passed no pixel, and scenes and characters were black.
// When every stage comes from the same program, that program is the effective one (all of Mario's and Engage's binds are like this, so nothing changes for them); otherwise a composite is made: a host-made prog_t carrying only a serial, whose NvProg in the serial table takes each stage from its source program (a null fragment = a vertex-only pipeline)
// S2Arm: the program a bind refers to at replay time. NVN puts the shaders into the command buffer when it is recorded: a game may finalize or reuse the program object before the submit
// (Diablo III, 10-25: one run crashed in keys_hash on a control pointer that was float data). While the object is still the bound program (magic and serial as at bind time) it is used
// as before; otherwise the bind-time snapshot: the program's entry in the host table by serial (hle_nvn.c prog_snap_put, never evicted: a command buffer may be submitted many times,
// frames after it was recorded), with its keys and no control section (it went with the program: a key missing from the map is reported, not translated). The entry's pointer stays valid
void prog_keys_put(const prog_t *p, const uint8_t keys[6][8], uint8_t ok);
static const prog_t *prog_by_serial(uint64_t ser);
static const prog_t *prog_live(const p_bind_program *b) {
    const prog_t *p = b->prog;
    if (!p || (p->magic == MAGIC('P', 'R', 'O', 'G') && p->serial == b->snap.serial)) return p;
    const prog_t *s = nvn_prog_snap_get ? nvn_prog_snap_get(b->snap.serial, NULL, NULL, NULL) : NULL;
    if (!s) { static int red; if (!red++) MLOG("【红】 program %p was finalized or reused after it was bound and serial %llu has no snapshot: its stages are taken by serial", (const void *)p, (unsigned long long)b->snap.serial); return prog_by_serial(b->snap.serial); }
    prog_keys_put(s, b->keys, b->kok);
    { static int once; if (!once++) MLOG("program %p was finalized or reused after it was bound: replaying from the bind-time snapshot (serial %llu)", (const void *)p, (unsigned long long)b->snap.serial); }
    return s;
}
// S2Arm: a host stand-in carrying only a serial, for a stage whose program object the game finalized or reused after an earlier bind: prog_get finds the stage's resolved
// shaders in the serial table under it (none once the program was finalized: the stage is then empty and a draw with it is reported, not read from freed memory)
static const prog_t *prog_by_serial(uint64_t ser) {
    enum { NSER = 64 }; static prog_t sp[NSER]; static int nsp, next;
    for (int i = 0; i < nsp; i++) if (sp[i].serial == ser) return &sp[i];
    int i = nsp < NSER ? nsp++ : next++ % NSER;
    memset(&sp[i], 0, sizeof sp[i]); sp[i].magic = MAGIC('P', 'R', 'O', 'G'); sp[i].serial = ser;
    return &sp[i];
}
enum { NCMP = 64 };
static struct { prog_t cp[NCMP]; const prog_t *ck[NCMP][5]; uint64_t cs[NCMP][5]; int ncp, next; } g_bind_cache;
static const prog_t *bind_stages(const prog_t *p, int stages) {
    // A program binds only the stages it has shaders for: Taiko no Tatsujin (0100383012646000, 10-30) makes one program per stage and binds each with
    //   all graphics bits (0x1f), vertex then fragment, before every draw; taking every bit replaced the vertex stage with the fragment-only program and all
    //   of its draws were dropped ("no vertex stage"). A null program still unbinds the stages in the bits (Metroid Dread's prepass, above). A program with a
    //   shader whose stage is not known (not in the map) keeps the old rule, so that shader is still reported at the draw rather than an old stage drawn.
    // Only the vertex and fragment bits are narrowed: those two stages cannot be disabled, so a program without them leaves them as they were (Taiko). The geometry and
    //   tessellation bits still unbind those stages when the program has no shader for them: Xenoblade 3 binds its UI / composite programs (vertex + fragment) with 0x1f
    //   after a sprite program with the geometry shader 95bfab6122539993; narrowing that bit away kept 95bfab on every later draw, which turned each triangle into a quad
    //   sized by the motion tile map (all 0 on a still screen), and the whole picture came out black (10-31)
    if (p) { __unsafe_unretained NvProg *pr = prog_get(p); if (pr && !pr->unres && pr->smask) stages &= pr->smask | ~0x3; }
    for (int st = 0; st < 5; st++) if (stages >> st & 1) { S.bst[st] = p; S.bser[st] = p ? p->serial : 0; }
    // A stage this bind leaves alone still names the program of an earlier bind, maybe from an earlier submission: the game may have finalized or reused that object since, and
    // reading it gave prog_get garbage (Diablo III, 10-26 cold run: keys_hash read a control pointer 0x20200ffffffff and crashed; the stage's program was gone, its pointer kept)
    for (int st = 0; st < 5; st++) { const prog_t *q = S.bst[st];
        if (q && !(q->magic == MAGIC('P', 'R', 'O', 'G') && q->serial == S.bser[st])) {
            S.bst[st] = prog_by_serial(S.bser[st]);
            static unsigned n; if (!n++ || !(n & (n - 1))) MLOG("stage %d keeps a program %p finalized or reused since its bind: its shaders are taken by the bind-time serial %llu (%u times so far)", st, (const void *)q, (unsigned long long)S.bser[st], n); } }
    const prog_t *v = S.bst[0] ? S.bst[0] : S.bst[4];   // an NVN2 program with a mesh stage (at 4, nvn2_cmd.h) has no vertex stage (interface contract item 5)
    if (!v) return NULL;
    int same = 1; for (int st = 1; st < 5; st++) if (S.bst[st] && S.bst[st] != v) same = 0;
    if (same && S.bst[1] == v) return v;
    prog_t *cp = g_bind_cache.cp; const prog_t *(*ck)[5] = g_bind_cache.ck; uint64_t (*cs)[5] = g_bind_cache.cs; int ncp = g_bind_cache.ncp;
    for (int i = 0; i < ncp; i++) {
        int hit = 1; for (int st = 0; st < 5 && hit; st++) hit = ck[i][st] == S.bst[st] && (!S.bst[st] || cs[i][st] == S.bst[st]->serial);
        if (hit) return &cp[i];
    }
    int i = ncp < NCMP ? g_bind_cache.ncp++ : g_bind_cache.next++ % NCMP;
    if (cp[i].serial) serial_del(cp[i].serial);
    NvProg *o = [NvProg new];
    for (int st = 0; st < 5; st++) { ck[i][st] = S.bst[st]; cs[i][st] = S.bst[st] ? S.bst[st]->serial : 0; if (S.bst[st]) { __unsafe_unretained NvProg *src = prog_get(S.bst[st]); o->sh[st] = src ? src->sh[st] : nil; } }
    prog_fold_gs(o);   // the geometry stage came from another program (see prog_fold_gs)
    o->gp = S.bst[1];   // S2Arm: the guest program the fragment stage came from (pso_fout_variant finds the fragment shader's code / control there); bound for this draw, checked by pointer and serial above
    memset(&cp[i], 0, sizeof cp[i]); cp[i].magic = MAGIC('P', 'R', 'O', 'G'); cp[i].serial = nvn_new_serial(); serial_put(cp[i].serial, o);
    { static int once; if (!once++) MLOG("per-stage program binding: first combined program (vertex %s fragment %s)", o->sh[0] ? o->sh[0]->key : "-", o->sh[1] ? o->sh[1]->key : "-"); }
    return &cp[i];
}
// S.prog after S was copied back from a saved state (the precompile prediction, the fusion probe and redraw, deferred draws). A combined program is a slot of the ring above, and binds
// replayed after the save can give the slot the saved pointer names to another combination. AI: THE SOMNIUM FILES (Unity 2017.4) binds its vertex and fragment programs apart; the
// prediction over a 280-draw submission (pso_predict_rest) made more than NCMP combinations, and the draw after it ran Legacy Shaders/VertexLit's shadow vertex shader with
// PSYNC/BG_AlphaTest's shadow pixel shader, a pipeline Metal refused (the pixel shader reads two outputs that vertex shader does not write). The combination is taken again from S.bst
static void prog_resolve(void) {
    const prog_t *np = bind_stages(NULL, 0); if (np == S.prog) return;
    S.prog = np; g_pso_dirty = 1;
    static unsigned n; if (!n++ || !(n & (n - 1))) MLOG("combined program taken again after a state restore: its ring slot had been reused (%u times so far)", n);
}
static void state_reset(void) {
    memset(&S, 0, sizeof S);
    g_pso_dirty = g_dss_dirty = 1;
    for (int i = 0; i < 8; i++) S.blend[i] = (blend_st){i, NVN_BLEND_FUNC_ONE, NVN_BLEND_FUNC_ZERO, NVN_BLEND_FUNC_ONE, NVN_BLEND_FUNC_ZERO, NVN_BLEND_EQUATION_ADD, NVN_BLEND_EQUATION_ADD};
    S.color = (color_st){0, NVN_LOGIC_OP_COPY, NVN_ALPHA_FUNC_ALWAYS}; S.chmask.mask = 0xffffffffu;
    S.ms.enable = 1;   // NVN default (MultisampleStateSetDefaults): a game that never binds a multisample state keeps multisampling on (pso_key.msoff)
    S.poly = (poly_st){NVN_FACE_NONE, NVN_FRONT_FACE_CCW, NVN_POLYGON_MODE_FILL, 0};
    S.ds = (ds_st){0, 1, NVN_DEPTH_FUNC_LESS, 0, NVN_STENCIL_FUNC_ALWAYS, NVN_STENCIL_FUNC_ALWAYS, 1, 1, 1, 1, 1, 1};
    S.patch_size = 3;   // S2Arm tessellation: default control points per patch
    S.st_vmask[0] = S.st_vmask[1] = S.st_wmask[0] = S.st_wmask[1] = 0xff; S.dr[1] = 1;
}

// Correct the vertex format by the shader input's component type: Metal requires integer inputs to get integer formats of the same signedness, and float inputs float / normalized formats.
// Integer input (inferred at translation time as "only used as an integer", dmsh_build.py int_inputs) with an integer format: on a signedness mismatch switch to the same width with the other sign (bit pattern unchanged for 32-bit components;
// 8 / 16-bit ones would be widened the wrong way, so vconv_wanted converts them first and this switch is only the fallback when the conversion slots run out); with a 32-bit float format read it as an integer of the same width (bit pattern unchanged).
// Other mismatches (integer input with a normalized / half format, float input with an integer format) cannot keep the bit pattern: report once and keep the format.
static MTLVertexFormat vfmt_for_ct(MTLVertexFormat f, int ct, int nvn_fmt) {
    static const MTLVertexFormat U[] = { MTLVertexFormatUChar, MTLVertexFormatUChar2, MTLVertexFormatUChar3, MTLVertexFormatUChar4, MTLVertexFormatUShort, MTLVertexFormatUShort2, MTLVertexFormatUShort3, MTLVertexFormatUShort4, MTLVertexFormatUInt, MTLVertexFormatUInt2, MTLVertexFormatUInt3, MTLVertexFormatUInt4 };
    static const MTLVertexFormat I[] = { MTLVertexFormatChar, MTLVertexFormatChar2, MTLVertexFormatChar3, MTLVertexFormatChar4, MTLVertexFormatShort, MTLVertexFormatShort2, MTLVertexFormatShort3, MTLVertexFormatShort4, MTLVertexFormatInt, MTLVertexFormatInt2, MTLVertexFormatInt3, MTLVertexFormatInt4 };
    static const MTLVertexFormat F[] = { MTLVertexFormatFloat, MTLVertexFormatFloat2, MTLVertexFormatFloat3, MTLVertexFormatFloat4 };
    int iu = -1, ii = -1, iff = -1;
    for (int i = 0; i < 12; i++) { if (U[i] == f) iu = i; if (I[i] == f) ii = i; }
    for (int i = 0; i < 4; i++) if (F[i] == f) iff = i;
    if (ct == NVN_CT_UINT) { if (iu >= 0) return f; if (ii >= 0) return U[ii]; if (iff >= 0) return U[8 + iff]; }
    else if (ct == NVN_CT_INT) { if (ii >= 0) return f; if (iu >= 0) return I[iu]; if (iff >= 0) return I[8 + iff]; }
    else { if (iu < 0 && ii < 0) return f; if ((iu >= 8 && iu < 12) || (ii >= 8 && ii < 12)) return F[(iu >= 8 ? iu : ii) - 8]; }   // 32-bit integers into a float input: the same bits as floats
    // An integer input fed a normalized, half or packed format: Maxwell would hand the shader the bits of the converted float, which Metal cannot, and Metal refuses the whole pipeline
    // ("Vertex attribute … of type uint4 cannot be read using MTLAttributeFormatHalf2"). Read the same bytes as integers of the same layout instead, so the pipeline exists and the draw is kept.
    // Fire Emblem: Three Houses: KTGL's character shaders read attribute 5 as integer bits (skinning data) and static meshes bind a Half2 there; with the pipeline refused, the characters'
    // shading draws were dropped and only black silhouettes remained (gender choice, in the prologue)
    if (ct == NVN_CT_UINT || ct == NVN_CT_INT) {
        static const struct { MTLVertexFormat f; uint8_t u; } P[] = {   // u = index into U / I with the same component size and count
            { MTLVertexFormatUCharNormalized, 0 }, { MTLVertexFormatCharNormalized, 0 }, { MTLVertexFormatUChar2Normalized, 1 }, { MTLVertexFormatChar2Normalized, 1 },
            { MTLVertexFormatUChar3Normalized, 2 }, { MTLVertexFormatChar3Normalized, 2 }, { MTLVertexFormatUChar4Normalized, 3 }, { MTLVertexFormatChar4Normalized, 3 }, { MTLVertexFormatUChar4Normalized_BGRA, 3 },
            { MTLVertexFormatUShortNormalized, 4 }, { MTLVertexFormatShortNormalized, 4 }, { MTLVertexFormatHalf, 4 }, { MTLVertexFormatUShort2Normalized, 5 }, { MTLVertexFormatShort2Normalized, 5 }, { MTLVertexFormatHalf2, 5 },
            { MTLVertexFormatUShort3Normalized, 6 }, { MTLVertexFormatShort3Normalized, 6 }, { MTLVertexFormatHalf3, 6 }, { MTLVertexFormatUShort4Normalized, 7 }, { MTLVertexFormatShort4Normalized, 7 }, { MTLVertexFormatHalf4, 7 },
            { MTLVertexFormatUInt1010102Normalized, 8 }, { MTLVertexFormatInt1010102Normalized, 8 }, { MTLVertexFormatFloatRG11B10, 8 },
        };
        for (unsigned i = 0; i < sizeof P / sizeof *P; i++) if (P[i].f == f) {
            RED_ONCE(91, "vertex attribute format %#x feeds a %s input: Metal does not allow it and the conversion slots are full; the raw bytes are read with the integer format of the same layout (the bit pattern differs from Maxwell's converted one)", nvn_fmt, ct == NVN_CT_UINT ? "uint" : "int");
            return ct == NVN_CT_UINT ? U[P[i].u] : I[P[i].u];
        }
    }
    RED_ONCE(66, "vertex attribute format %#x does not match shader input type %s; the bit pattern is not preserved (original format kept)", nvn_fmt, ct == NVN_CT_UINT ? "uint" : ct == NVN_CT_INT ? "int" : "float");
    return f;
}
// Integer shader inputs fed float-type vertex formats (half, unorm / snorm 8 and 16, 10:10:10:2, 11:11:10, BGRA8). Maxwell's fetch converts by the format and the register holds float32
// bits, which such shaders take back with as_type<float> (`int_inputs` declared the input uint because its first translation only bit-cast it). Metal can neither convert into an integer
// input nor build such a pipeline, and reading the raw bytes as integers (vfmt_for_ct's fallback) gives denormals: Fire Emblem: Three Houses' and Age of Calamity's soldiers and Claude came
// out flat tan, their UVs collapsed onto one texel. So the replay converts these attributes on the CPU into float32 bits, four components with the missing ones (0, 0, 0, 1.0) as the fetch
// fills them, in the frame arena, and the pipeline reads them as UInt4 / Int4 from buffer slots of their own (VCONV_SLOT0 + n, in reflection order; slots 1-12 are unused by translated shaders)
enum { VCONV_SLOT0 = 1, VCONV_MAX = 12 };
static int vconv_ncomp(int f) {   // components of an NVN float-type vertex format that needs the conversion; 0 = not one
    switch (f) {
        case 0x01: case 0x02: case 0x05: case 0x06: case 0x07: return 1;
        case 0x0D: case 0x0E: case 0x11: case 0x12: case 0x13: return 2;
        case 0x19: case 0x1A: case 0x1D: case 0x1E: case 0x1F: case 0x3F: return 3;
        case 0x25: case 0x26: case 0x29: case 0x2A: case 0x2B: case 0x3D: case 0x69: case 0x9A: return 4;
    }
    return 0;
}
// 8- and 16-bit integer formats: Maxwell's fetch widens each component into the 32-bit register by the format's own signedness (sign for SINT, zero for UINT). Metal reads them only into
// an input of the same signedness, and vfmt_for_ct's switch to the other sign keeps the 8 / 16 bits but widens them the other way. So an input of the other signedness takes the 32-bit
// values converted here too. Fire Emblem: Three Houses: the terrain's heights are RGBA16I into a uint input; negative heights read as 32768-65535 and the ground under close-up
// cameras was never drawn (the lighting then saw depth 0 and painted fog there)
static int vconv_int(int f, int *bits, int *sgn) {   // components of an 8 / 16-bit integer format (with its component size and signedness); 0 = not one
    static const uint8_t T[16] = { 0x03, 0x04, 0x08, 0x09, 0x0F, 0x10, 0x14, 0x15, 0x1B, 0x1C, 0x20, 0x21, 0x27, 0x28, 0x2C, 0x2D };   // per component count: UI8, I8, UI16, I16
    for (int i = 0; i < 16; i++) if (T[i] == f) { *bits = i & 2 ? 16 : 8; *sgn = i & 1; return i / 4 + 1; }
    return 0;
}
// *_UI2F / *_I2F formats (0x51-0x68, R8 R16 R32 RG8 … RGBA32, unsigned then signed): integers that the fetch converts to float without normalizing (200 → 200.0). Metal has no such vertex
// format and refuses an integer format into a float input, so they are converted here too; an integer input of the same format takes the float32 bits, as from Maxwell's fetch.
// Breath of the Wild: an RG8_UI2F attribute (0x57, at the title) had no Metal format and read 0
static int vconv_i2f(int f, int *bits, int *sgn) {   // components of an integer-read-as-float format (with its component size and signedness); 0 = not one
    if (f < 0x51 || f > 0x68) return 0;
    int i = (f - 0x51) >> 1; *sgn = (f - 0x51) & 1; *bits = 8 << (i % 3); return i / 3 + 1;
}
static int vconv_size(int f) {   // bytes of one element
    int ib, is, in = vconv_int(f, &ib, &is); if (in) return in * ib / 8;
    if ((in = vconv_i2f(f, &ib, &is))) return in * ib / 8;
    switch (f) { case 0x01: case 0x02: return 1; case 0x05: case 0x06: case 0x07: case 0x0D: case 0x0E: return 2; case 0x19: case 0x1A: return 3;
                 case 0x1D: case 0x1E: case 0x1F: return 6; case 0x29: case 0x2A: case 0x2B: return 8; }
    return 4;
}
static float vconv_uf(uint32_t v, int mbits) {   // unsigned small float of R11G11B10F: 5-bit exponent (bias 15), mbits-bit mantissa
    uint32_t e = v >> mbits & 31, m = v & ((1u << mbits) - 1);
    if (!e) return ldexpf((float)m, -14 - mbits);
    if (e == 31) return m ? NAN : INFINITY;
    return ldexpf(1.0f + (float)m / (float)(1u << mbits), (int)e - 15);
}
static void vconv_elem(int f, const uint8_t *p, float o[4]) {
    int ib, is, in = vconv_int(f, &ib, &is);
    if (in) {   // integer format: the register's 32-bit value, the missing components (0, 0, 0, 1) as integers
        uint32_t u[4] = { 0, 0, 0, 1 };
        for (int i = 0; i < in; i++) {
            if (ib == 8) u[i] = is ? (uint32_t)(int32_t)(int8_t)p[i] : p[i];
            else { uint16_t h; memcpy(&h, p + 2 * i, 2); u[i] = is ? (uint32_t)(int32_t)(int16_t)h : h; } }
        memcpy(o, u, sizeof u); return; }
    o[0] = o[1] = o[2] = 0; o[3] = 1;
    if ((in = vconv_i2f(f, &ib, &is))) {   // integers read as floats: each value as a float, the missing components (0, 0, 0, 1.0)
        for (int i = 0; i < in; i++) {
            if (ib == 8) o[i] = is ? (float)(int8_t)p[i] : (float)p[i];
            else if (ib == 16) { uint16_t h; memcpy(&h, p + 2 * i, 2); o[i] = is ? (float)(int16_t)h : (float)h; }
            else { uint32_t w; memcpy(&w, p + 4 * i, 4); o[i] = is ? (float)(int32_t)w : (float)w; } }
        return; }
    int n = vconv_ncomp(f);
    for (int i = 0; i < n; i++) switch (f) {
        case 0x01: case 0x0D: case 0x19: case 0x25: o[i] = p[i] / 255.0f; break;
        case 0x02: case 0x0E: case 0x1A: case 0x26: o[i] = fmaxf((int8_t)p[i] / 127.0f, -1.0f); break;
        case 0x05: case 0x11: case 0x1D: case 0x29: { _Float16 h; memcpy(&h, p + 2 * i, 2); o[i] = (float)h; break; }
        case 0x06: case 0x12: case 0x1E: case 0x2A: { uint16_t u; memcpy(&u, p + 2 * i, 2); o[i] = u / 65535.0f; break; }
        case 0x07: case 0x13: case 0x1F: case 0x2B: { int16_t s; memcpy(&s, p + 2 * i, 2); o[i] = fmaxf(s / 32767.0f, -1.0f); break; }
        case 0x9A: o[i] = p[i == 3 ? 3 : 2 - i] / 255.0f; break;   // BGRA8 unorm: the fetch hands the shader R, G, B, A
        case 0x3D: case 0x69: case 0x3F: {
            uint32_t w; memcpy(&w, p, 4);
            if (f == 0x3F) o[i] = vconv_uf(i == 0 ? w & 0x7ff : i == 1 ? w >> 11 & 0x7ff : w >> 22, i == 2 ? 5 : 6);
            else { uint32_t bits = i == 3 ? 2 : 10, v = w >> (10 * i) & ((1u << bits) - 1);
                   if (f == 0x3D) o[i] = (float)v / (float)((1u << bits) - 1);
                   else { int32_t sv = (int32_t)(v << (32 - bits)) >> (32 - bits); o[i] = fmaxf((float)sv / (float)((1u << (bits - 1)) - 1), -1.0f); } }
            break; }
    }
}
// Shadow inputs instead of the conversion: a vertex shader with integer inputs also has a library <key>_bv (dmsh_vin.py) whose entry points declare each integer input again as a float4
// and as the integer of the other sign, at Metal attribute indices 16-30, and OR the three into the input the body reads. A pipeline sends each attribute to the declaration of its
// format's class (half / normalized formats to the float one, 8 / 16-bit integers to the one of their own sign) and the zero buffer to the others, and Metal's fetch then gives the
// shader Maxwell's register bits: no CPU conversion, whatever mix of formats the pipeline has (Age of Calamity's soldiers feed Half2 beside RGBA8UI and Short2 to one shader; the
// conversion was about a quarter of its replay thread in battle). Transform feedback captures (main0_tf) keep the conversion. DM_NVN_VCONV_CPU=1 converts on the CPU as before
static int vin_cpu(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_VCONV_CPU"); v = e && !strcmp(e, "1"); if (v) MLOG("DM_NVN_VCONV_CPU=1: integer vertex inputs fed formats of another class are converted on the CPU (no shadow inputs)"); } return v; }
static os_unfair_lock g_vin_lock = OS_UNFAIR_LOCK_INIT;
static uint64_t g_vin_loaded, g_vin_failed, g_vin_psos;   // shadow-input libraries loaded / not usable, pipelines built with them
static id<MTLFunction> vin_fn(NvShader *vs) {   // the shadow-input entry point, loaded on first need; a failure is final for the shader (it keeps the conversion)
    if (!vs->rf.has_vin || vin_cpu()) return nil;
    os_unfair_lock_lock(&g_vin_lock);
    if (!vs->vfn_state) {
        vs->vfn_state = 2;
        size_t kl = strlen(vs->key); NSString *path = [NSString stringWithFormat:@"%.*s_bv", (int)(kl > 2 ? kl - 2 : kl), vs->key];
        NSError *e = nil; id<MTLLibrary> lib = lib_from_pack(path.UTF8String, &e); id<MTLFunction> f = lib && vs->ventry ? [lib newFunctionWithName:fnn(vs, vs->ventry)] : nil;   // a batched _bv library carries the _b batch's prefix (dmsh_build.py vin_flush)
        if (f && f.functionConstantsDictionary.count) f = [lib newFunctionWithName:fnn(vs, vs->ventry) constantValues:[MTLFunctionConstantValues new] error:&e];   // as shader_load
        const char *why = !lib ? "no library" : !f ? "no entry point" : NULL;
        if (f && vs->rf.nb && argcheck_on() && [f newArgumentEncoderWithBufferIndex:vs->rf.abi].encodedLength != vs->arg_len) { why = "its argument buffer differs from the base library's"; f = nil; }   // asks Metal only under S2A_ARGCHECK (shader_args_init)
        if (f) { vs->vfn = f; vs->vfn_state = 1; g_vin_loaded++; }
        else if (g_vin_failed++ < 8) MLOG("【红】 shadow-input library of %s not usable (%s%s%s): its integer inputs keep the CPU conversion", vs->key, why, e ? ": " : "", e ? e.localizedDescription.UTF8String : "");
    }
    id<MTLFunction> f = vs->vfn_state == 1 ? vs->vfn : nil;
    os_unfair_lock_unlock(&g_vin_lock);
    return f;
}
static inline int vin_fmt(const pso_key *k, int a) { return a >= 16 ? 0 : k ? k->attr[a].fmt : a < S.nattr ? S.attr[a].fmt : 0; }   // as pso_key_fill fills the key
// The component type input v takes its attribute as: the class of the attribute's format when a shadow of that class exists (on), else the declared type
static int vin_ct(const nvn_refl *rf, int v, int f, int on) {
    int ct = rf->v[v].ct, ib, is;
    if (!on || ct == NVN_CT_FLOAT) return ct;
    int want = vconv_ncomp(f) ? NVN_CT_FLOAT : vconv_int(f, &ib, &is) ? (is ? NVN_CT_INT : NVN_CT_UINT) : ct;
    return want != ct && rf->v[v].sh[want] != 0xff ? want : ct;
}
// Whether this pipeline (k, or the current state at bind time: both give the same answer) uses the shadow inputs: some input takes a shadow and the library loads. Asked by pso_desc
// and vconv_bind alike, so the converted attributes and the pipeline's buffer slots agree
static int vin_on(NvShader *vs, const pso_key *k, int tf) {
    const nvn_refl *rf = &vs->rf;
    if (tf || !rf->has_vin || vin_cpu()) return 0;
    int need = 0; for (int v = 0; v < rf->nv && !need; v++) need = vin_ct(rf, v, vin_fmt(k, rf->v[v].nvn), 1) != rf->v[v].ct;
    return need && vin_fn(vs) != nil;
}
// A float input fed an 8 / 16-bit integer format takes the same 32-bit register values through a Float4 attribute, which Metal passes through bit for bit: Monster Hunter Rise's
// skinned vertex shaders (40609cd5c1443df4, 1369a37113da0012) read RGBA8UI attribute 5 as flags (as_type<int>(x) & 2 ...) and also as a float, so the build leaves the input float
static int vconv_wanted(const nvn_refl *rf, int v, const pso_key *k, int on) {   // does Metal input v of this pipeline take converted data (on: it uses the shadow inputs, vin_on)
    int a = rf->v[v].nvn, ct = rf->v[v].ct, ib, is;
    if (a >= 16) return 0;
    int f = k ? k->attr[a].fmt : S.attr[a].fmt;
    if (vconv_i2f(f, &ib, &is)) return 1;   // whatever the input type
    if (ct == NVN_CT_FLOAT) return vconv_int(f, &ib, &is) > 0;
    if (ct != NVN_CT_UINT && ct != NVN_CT_INT) return 0;
    if (vin_ct(rf, v, f, on) != ct) return 0;   // a shadow input takes it
    return vconv_ncomp(f) || (vconv_int(f, &ib, &is) && is != (ct == NVN_CT_INT));
}
// nv elements from src (stride bytes apart) into d, four 32-bit values each. Integer, integer-to-float and half formats (Age of Calamity's soldiers: Short2, Half2) have loops
// of their own with the format decoded once; vconv_elem decodes it for every element
static void vconv_fill(int f, uint64_t src, uint32_t stride, uint64_t nv, float *d) {
    const uint8_t *p = (const uint8_t *)(uintptr_t)src; uint32_t *u = (uint32_t *)d; int ib, is, in = vconv_int(f, &ib, &is);
    if (in) {   // as vconv_elem: the register's 32-bit value, the missing components (0, 0, 0, 1)
        for (uint64_t i = 0; i < nv; i++, p += stride, u += 4) {
            u[0] = u[1] = u[2] = 0; u[3] = 1;
            for (int c = 0; c < in; c++) {
                if (ib == 8) u[c] = is ? (uint32_t)(int32_t)(int8_t)p[c] : p[c];
                else { uint16_t h; memcpy(&h, p + 2 * c, 2); u[c] = is ? (uint32_t)(int32_t)(int16_t)h : h; } } }
        return; }
    if ((in = vconv_i2f(f, &ib, &is))) {   // as vconv_elem: decode this attribute range's format once
        if (in == 4 && ib == 8) {   // all four components are present; read exactly four bytes, including at a page boundary
            typedef int8_t vc_i8x4 __attribute__((ext_vector_type(4)));
            typedef uint8_t vc_u8x4 __attribute__((ext_vector_type(4)));
            typedef float vc_f32x4 __attribute__((ext_vector_type(4)));
            if (is) for (uint64_t i = 0; i < nv; i++, p += stride, d += 4) {
                vc_i8x4 v; memcpy(&v, p, sizeof v);
                vc_f32x4 out = __builtin_convertvector(v, vc_f32x4); memcpy(d, &out, sizeof out);
            } else for (uint64_t i = 0; i < nv; i++, p += stride, d += 4) {
                vc_u8x4 v; memcpy(&v, p, sizeof v);
                vc_f32x4 out = __builtin_convertvector(v, vc_f32x4); memcpy(d, &out, sizeof out);
            }
            return; }
        for (uint64_t i = 0; i < nv; i++, p += stride, d += 4) {
            d[0] = d[1] = d[2] = 0; d[3] = 1;
            for (int c = 0; c < in; c++) {
                if (ib == 8) d[c] = is ? (float)(int8_t)p[c] : (float)p[c];
                else if (ib == 16) { uint16_t h; memcpy(&h, p + 2 * c, 2); d[c] = is ? (float)(int16_t)h : (float)h; }
                else { uint32_t w; memcpy(&w, p + 4 * c, 4); d[c] = is ? (float)(int32_t)w : (float)w; } } }
        return; }
    if (f == 0x05 || f == 0x11 || f == 0x1D || f == 0x29) {   // R16F … RGBA16F
        int n = vconv_ncomp(f);
        for (uint64_t i = 0; i < nv; i++, p += stride, d += 4) {
            d[0] = d[1] = d[2] = 0; d[3] = 1;
            for (int c = 0; c < n; c++) { _Float16 h; memcpy(&h, p + 2 * c, 2); d[c] = (float)h; } }
        return; }
    for (uint64_t i = 0; i < nv; i++) vconv_elem(f, p + i * stride, d + 4 * i);
}
// Profile vconv_range (Age of Calamity): convert only the vertices each draw reads. KTGL binds whole mesh pools (up to ~590,000 vertices) and draws parts of them, so
// converting the bound range came to millions of vertices a frame in a battle with hundreds of soldiers: 24 of the 32 ms the replay took per frame on the Mac (26 fps at
// a 30 or a 60 fps target). The range is first / count, or for a direct indexed draw the indices' smallest and largest plus the base vertex; the conversion is bound as many
// vertices before its start as the range starts at. The indices' range is kept while their pages stay unwritten (write-protected as packaged textures, nvn_dirty_protect),
// and never trusted again once a GPU copy, update or fill is queued on them (pend_add). Keeping the conversions too did not pay: the soldiers' attributes change every frame.
// DM_NVN_VCONV_CHECK=1 scans the indices again at every reuse and reports differences. DM_NVN_VCONV_RANGE=0 / 1 overrides the profile
enum { VC_RGN = 1 << 16 };   // bits of the region filter
typedef struct { uint64_t ibuf; int32_t count, itype; } ir_key;
typedef struct { uint32_t mn, mx; uint64_t stamp, seen, lo, n; const void *span; int gpuw; } ir_ent;   // gpuw: a GPU write was queued on the indices: never trusted again
static nvn_hmap g_ir = {.klen = sizeof(ir_key)};
static uint64_t g_vc_rgn[VC_RGN / 64], g_vc_stat, g_vc_conv, g_vc_whole, g_vc_checks, g_vc_bad;   // g_vc_rgn: 1 MB regions holding a kept index range (hashed); g_vc_conv / g_vc_whole: vertices converted / in the bound ranges
static int vc_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_VCONV_RANGE"); v = e && *e ? atoi(e) != 0 : DM_GAME_VCONV_RANGE; MLOG("vertex conversion of the draw's vertices only: %s", v ? "on" : "off"); } return v; }
static int vc_check(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_VCONV_CHECK"); v = e && *e && atoi(e); } return v; }
static inline uint32_t vc_rgn(uint64_t r) { return (uint32_t)((r * 0x9E3779B97F4A7C15ull) >> 48) & (VC_RGN - 1); }
static void vc_rgn_mark(uint64_t lo, uint64_t n) { for (uint64_t r = lo >> 20; r <= (lo + n - 1) >> 20; r++) { uint32_t b = vc_rgn(r); g_vc_rgn[b >> 6] |= 1ull << (b & 63); } }
static int vc_rgn_hit(uint64_t lo, uint64_t n) { for (uint64_t r = lo >> 20; r <= (lo + n - 1) >> 20; r++) { uint32_t b = vc_rgn(r); if (g_vc_rgn[b >> 6] >> (b & 63) & 1) return 1; } return 0; }
static void vc_gpu_write(uint64_t dst, uint64_t n) {   // pend_add: a GPU write queued on [dst, dst + n)
    if (!n || !g_ir.n || !vc_rgn_hit(dst, n)) return;
    for (uint32_t i = 0; i < g_ir.cap; i++) { ir_ent *e = g_ir.vals[i]; if (e && dst < e->lo + e->n && dst + n > e->lo) e->gpuw = 1; }
}
static void ix_minmax(const void *p, int isz, int32_t count, uint32_t *mn, uint32_t *mx) {
    uint32_t a = UINT32_MAX, b = 0;
    if (isz == 1) for (int32_t i = 0; i < count; i++) { uint32_t x = ((const uint8_t *)p)[i]; if (x < a) a = x; if (x > b) b = x; }
    else if (isz == 2) for (int32_t i = 0; i < count; i++) { uint32_t x = ((const uint16_t *)p)[i]; if (x < a) a = x; if (x > b) b = x; }
    else for (int32_t i = 0; i < count; i++) { uint32_t x = ((const uint32_t *)p)[i]; if (x < a) a = x; if (x > b) b = x; }
    *mn = a; *mx = b;
}
// Smallest and largest index of a direct indexed draw whose indices no GPU write queued in this submission covers; 0 = not known (the whole bound range is converted)
static int ix_range(const p_draw_idx *di, uint32_t *mn, uint32_t *mx) {
    int isz = di->itype == 0 ? 1 : di->itype == 1 ? 2 : 4; uint64_t n = (uint64_t)di->count * (uint64_t)isz;
    if (di->ind || di->mdi_cnt || di->count <= 0 || !di->ibuf || pend_hits(di->ibuf, n)) return 0;
    const void *p = (const void *)(uintptr_t)di->ibuf;
    ir_key k = {di->ibuf, di->count, di->itype}; ir_ent *e = nvn_hm_get(&g_ir, &k); uint64_t now = nvn_dirty_now();
    if (e && e->gpuw) return 0;
    if (e && (now == e->seen || !nvn_dirty_since_span(e->span, p, (size_t)n, e->stamp))) {
        e->seen = now; *mn = e->mn; *mx = e->mx;
        if (vc_check()) { uint32_t a, b; ix_minmax(p, isz, di->count, &a, &b); g_vc_checks++;
            if ((a != e->mn || b != e->mx) && g_vc_bad++ < 20) MLOG("【红】 vertex conversion: the kept index range of %#llx (%d indices) is %u-%u, the indices now %u-%u", (unsigned long long)di->ibuf, di->count, e->mn, e->mx, a, b); }
        return 1;
    }
    const void *span = nvn_dirty_span(p, (size_t)n);
    if (!span) return 0;   // not in a tracked memory pool
    if (!e) { if (g_ir.n >= 1 << 16) { nvn_hm_clear(&g_ir, free); memset(g_vc_rgn, 0, sizeof g_vc_rgn); } e = calloc(1, sizeof *e); nvn_hm_put(&g_ir, &k, e); }
    nvn_dirty_protect(p, (size_t)n); e->stamp = e->seen = nvn_dirty_now(); e->span = span; e->lo = di->ibuf; e->n = n; vc_rgn_mark(e->lo, e->n);   // protect, take the stamp, then read (as pkg_upload)
    ix_minmax(p, isz, di->count, &e->mn, &e->mx); *mn = e->mn; *mx = e->mx;
    return 1;
}
// The vertex ids a direct draw reads: [*lo, *hi]; 0 = not known (indirect, multi-draw, indices not known)
static int vc_draw_range(const p_draw *dw, const p_draw_idx *di, int64_t *lo, int64_t *hi) {
    if (dw) { if (dw->ind || dw->mdi_cnt || dw->count <= 0) return 0; *lo = dw->first; *hi = (int64_t)dw->first + dw->count - 1; return 1; }
    uint32_t mn, mx; if (!di || !ix_range(di, &mn, &mx)) return 0;
    *lo = (int64_t)mn + di->base_vertex; *hi = (int64_t)mx + di->base_vertex; return 1;
}
static void vc_stat(void) {   // every 3600 submissions
    if (g_sub_serial - g_vc_stat < 3600) return;
    if (g_vc_stat) MLOG("vertex conversion: %.0f vertices per submission (the bound ranges: %.0f), %u index ranges kept%s; shadow-input libraries loaded %llu (not usable %llu), pipelines built with them %llu", g_vc_conv / 3600.0, g_vc_whole / 3600.0, g_ir.n,
        vc_check() ? [NSString stringWithFormat:@"; checked %llu, %llu differed", (unsigned long long)g_vc_checks, (unsigned long long)g_vc_bad].UTF8String : "",
