        if (!fs->ft_tried) { fs->ft_tried = 1; char nm[32]; snprintf(nm, sizeof nm, "%.16s_ft", fs->key); fs->ft_lib = lib_from_pack(nm, NULL); }
        id<MTLFunction> lf = lib_entry(fs->ft_lib, [NSString stringWithFormat:@"main0_t%x_%x", need & 0xff, need >> 8]);
        if (lf) { if (!fs->fn_t) fs->fn_t = [NSMutableDictionary dictionary]; fs->fn_t[@(need)] = f = lf; }
    }
