    // A variant an older host made (another format version, still fresh by its source): made again from the guest code when there is some (version 4 added folded textures, 11-03)
    if (src && ![src hasPrefix:ver] && code && !dm_shader_se(md, code, ctl, p, sizeof p)) { snprintf(p, sizeof p, "%s/%.16s_se.metal", fb, sh->key); src = [NSString stringWithContentsOfFile:@(p) encoding:NSUTF8StringEncoding error:nil]; }
    if (!src || ![src hasPrefix:ver]) { snprintf(why, n, "%s %s", p, src ? "is of another format" : "is unreadable"); return nil; }
    NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:src options:dm_msl_opts() error:&e];
    if (!lib) { snprintf(why, n, "failed to build: %s", e.localizedDescription.UTF8String); return nil; }
