static void se_done(NvShader *sh, id<MTLFunction> f, const char *why, uint64_t t0, const char *how) {
    if (f) sh->se_main = f;
    __atomic_store_n(&sh->se_st, f ? SE_READY : SE_FAIL, __ATOMIC_RELEASE); se_signal();
    atomic_fetch_add(f ? &g_se_made : &g_se_failed, 1);
    fprintf(stderr, "[s2a] 归约变体：程序号 %s 着色器 %.16s %s%s %.1f ms%s%s\n", s2a_nvn_game_id(), sh->key, how, f ? "完成" : "失败", (bp_now() - t0) / 1e6, f ? "" : "：", f ? "" : why);
    if (!f) MLOG("【红】 shader %s binds a sampler this GPU cannot do natively (min / max without native reduction, or a custom border colour), but it has no emulation variant: %s; its draws keep main0 (averaged / nearest standard border colour)", sh->key, why);
}
static int se_sync(void) {   // S2A_SE_SYNC=1: the variant is made on the submit thread at its first use (se_want)
    static int v; static dispatch_once_t once;
    dispatch_once(&once, ^{ const char *e = getenv("S2A_SE_SYNC"); v = e && !strcmp(e, "1"); if (v) MLOG("S2A_SE_SYNC=1: sampler reduction variants are made on the submit thread at their first use"); });
    return v;
}
// Ask for the variant at the shader's first use that needs it (se_want, submit thread; the caller claimed the shader). The guest code / control come from program p as for
//   pso_fout_variant: the control section is only valid during SetShaders, so its key is recomputed (prog_stage_of); for the background both are copied here first (dm_shader_snap)
static dispatch_queue_t se_queue(void) {   // the background queue of se_kick (a function so t_nvn_red can hold it: dispatch_suspend until its first draw is read back)
    static dispatch_queue_t q; static dispatch_once_t once;
    dispatch_once(&once, ^{ q = dispatch_queue_create("dm.nvn.se", s2a_qos_queue_attr(DISPATCH_QUEUE_SERIAL, S2A_QOS_SHADER_VARIANT)); });
    return q;
}
static void se_kick(const prog_t *p, NvShader *sh, int sync) {   // sync: made here on the submit thread (S2A_SE_SYNC=1, or a draw reading a folded texture: se_want)
    uint8_t md[8] = {0}; int at = p ? prog_stage_of(p, sh->key, md) : -1; uint64_t t0 = bp_now();
    if (sync || se_sync()) { char why[300] = ""; id<MTLFunction> f = se_build(sh, md, at < 0 ? 0 : p->sd[at].data, at < 0 ? NULL : p->sd[at].control, why, sizeof why); se_done(sh, f, why, t0, "同步现编"); return; }
    uint64_t code = 0; const void *ctl = NULL; void *snap = at < 0 ? NULL : dm_shader_snap(p->sd[at].data, p->sd[at].control, &code, &ctl); uint64_t key; memcpy(&key, md, 8);
    fprintf(stderr, "[s2a] 归约变体：程序号 %s 着色器 %.16s 首遇，后台编，编好前这支照常用 main0 画（取平均）\n", s2a_nvn_game_id(), sh->key);
    dispatch_async(se_queue(), ^{ @autoreleasepool {
        if (dm_gfx_session_stopping()) { free(snap); return; }
        uint8_t m[8]; memcpy(m, &key, 8); char why[300] = "";
        id<MTLFunction> f = se_build(sh, m, code, ctl, why, sizeof why); free(snap);
        se_done(sh, f, why, t0, "后台编");
    } });
}
// S2Arm (10-30, Kirby Star Allies, census c1029c: "vertex … does not write user(locn) mask 0x8 that fragment … reads: draw skipped"): a vertex shader the game pairs at run time with a
//   pixel shader that reads a user(locn) it does not write. Metal refuses the pipeline (pso_pair_ok). The package's pairs (shader_pairs.tsv → offline vs_pad) cannot know every pair a
//   game makes stage by stage, and the old answer (skip the draw, record the pair in pso_user.tsv for the next build) never reached a player: the package is built once.
//   Now the variant is made on this device at the pair's first use (vp_ask, submit thread): S2A.Dsh writes <key>_vp<mask>.metal (dm_shader_vpad: the shader's own translation with
//   those outputs (0,0,0,1), the offline vs_pad's rule, what the hardware reads there) and it is compiled in the background (vp_kick); until it is ready the pair's draws are skipped
//   as before, from the next draw after it they draw with it (pso_desc). One variant per vertex shader, for the union of the masks asked for: a pair that needs more rebuilds it.
//   S2A_SE_SYNC=1 makes it on the submit thread too. One line per variant ("[s2a] 顶点补齐变体：…"), and a count in the run's summary (mtl_vp_stats)
static pthread_mutex_t g_vp_mu = PTHREAD_MUTEX_INITIALIZER;
static _Atomic uint64_t g_vp_made, g_vp_failed;
void mtl_vp_stats(uint64_t out[2]) { out[0] = atomic_load(&g_vp_made); out[1] = atomic_load(&g_vp_failed); }
static uint32_t pso_pair_miss(NvShader *vs, NvShader *fs) {   // the user(locn) fs reads and vs does not write (0 = none, or positions unknown on either side)
    if (!vs || !fs || !(vs->rf.has_user & 1) || !(fs->rf.has_user & 2)) return 0;
    return fs->rf.user_in & ~vs->rf.user_out;
}
static id<MTLFunction> vp_fn(NvShader *vs, uint32_t miss) {   // the padded variant when it covers miss, else nil (any thread)
    pthread_mutex_lock(&g_vp_mu); id<MTLFunction> f = vs->vp_st == SE_READY && (vs->vp_mask & miss) == miss ? vs->vp_main : nil; pthread_mutex_unlock(&g_vp_mu);
    return f;
}
// Make the variant and load it: S2A.Dsh writes it from the guest code / control (code 0: none to make it from). → the shader's entry point in it, nil with why
static id<MTLFunction> vp_build(NvShader *vs, const uint8_t md[8], uint64_t code, const void *ctl, uint32_t mask, char *why, size_t n) {
    if (!code) { snprintf(why, n, "the game no longer holds its control section to translate it"); return nil; }
    char path[1200]; int rc = dm_shader_vpad(md, code, ctl, mask, path, sizeof path);
    if (rc) { snprintf(why, n, "%s", rc == 3 ? "its translation already writes those outputs (or has no main0_out to add them to)" : "the device could not make it"); return nil; }
    NSString *src = [NSString stringWithContentsOfFile:@(path) encoding:NSUTF8StringEncoding error:nil];
    if (!src || ![src hasPrefix:@"// s2a:vs-pad 1 "]) { snprintf(why, n, "%s %s", path, src ? "is of another format" : "is unreadable"); return nil; }
    NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:src options:dm_msl_opts() error:&e];
    if (!lib) { snprintf(why, n, "failed to build: %s", e.localizedDescription.UTF8String); return nil; }
    id<MTLFunction> f = lib_entry(lib, vs->ventry);   // the logical entry the library's function is (main0 / main0_z / the layer ones); a source library has no name prefix
    NSUInteger al = f && vs->rf.nb ? [f newArgumentEncoderWithBufferIndex:vs->rf.abi].encodedLength : vs->arg_len;
    if (!f || al != vs->arg_len) { snprintf(why, n, "%s", f ? "it takes another argument buffer than the library's entry" : "it has no such entry"); return nil; }
    return f;
}
static void vp_done(NvShader *vs, id<MTLFunction> f, uint32_t mask, const char *why, uint64_t t0, const char *how) {
    pthread_mutex_lock(&g_vp_mu); if (f) { vs->vp_main = f; vs->vp_mask = mask; } vs->vp_st = f ? SE_READY : SE_FAIL; pthread_mutex_unlock(&g_vp_mu);
    atomic_fetch_add(f ? &g_vp_made : &g_vp_failed, 1);
    fprintf(stderr, "[s2a] 顶点补齐变体：程序号 %s 顶点 %.16s 补 user(locn) 掩码 %#x %s%s %.1f ms%s%s\n", s2a_nvn_game_id(), vs->key, mask, how, f ? "完成" : "失败", (bp_now() - t0) / 1e6, f ? "" : "：", f ? "" : why);
    if (!f) MLOG("【红】 vertex shader %s has no padded variant for user(locn) mask %#x: %s; draws pairing it with such a fragment shader stay skipped", vs->key, mask, why);
}
// A pair needs outputs the vertex shader does not write (miss): ask for the variant (submit thread). 1 = being made or just made (the caller skips this draw, nothing is recorded as
//   failed), 0 = it cannot be made (the caller records the pair as failed, as before)
static int vp_ask(const prog_t *p, NvShader *vs, uint32_t miss) {
    pthread_mutex_lock(&g_vp_mu);
    int st = vs->vp_st; uint32_t want = (st == SE_READY ? vs->vp_mask : 0) | miss;
    if (st == SE_BUSY || st == SE_FAIL || (st == SE_READY && (vs->vp_mask & miss) == miss)) { pthread_mutex_unlock(&g_vp_mu); return st != SE_FAIL; }
    vs->vp_st = SE_BUSY; pthread_mutex_unlock(&g_vp_mu);
    uint8_t md[8] = {0}; int at = p ? prog_stage_of(p, vs->key, md) : -1; uint64_t t0 = bp_now();
    if (se_sync()) { char why[300] = ""; id<MTLFunction> f = vp_build(vs, md, at < 0 ? 0 : p->sd[at].data, at < 0 ? NULL : p->sd[at].control, want, why, sizeof why); vp_done(vs, f, want, why, t0, "同步现编"); return f != nil; }
    uint64_t code = 0; const void *ctl = NULL; void *snap = at < 0 ? NULL : dm_shader_snap(p->sd[at].data, p->sd[at].control, &code, &ctl); uint64_t key; memcpy(&key, md, 8);
    fprintf(stderr, "[s2a] 顶点补齐变体：程序号 %s 顶点 %.16s 首遇缺 user(locn) 掩码 %#x，后台编，编好前这对的绘制照旧跳过\n", s2a_nvn_game_id(), vs->key, want);
    static dispatch_queue_t q; static dispatch_once_t once;
    dispatch_once(&once, ^{ q = dispatch_queue_create("dm.nvn.vp", s2a_qos_queue_attr(DISPATCH_QUEUE_SERIAL, S2A_QOS_SHADER_VARIANT)); });
    dispatch_async(q, ^{ @autoreleasepool {
        if (dm_gfx_session_stopping()) { free(snap); pthread_mutex_lock(&g_vp_mu); vs->vp_st = SE_NONE; pthread_mutex_unlock(&g_vp_mu); return; }
        uint8_t m[8]; memcpy(m, &key, 8); char why[300] = "";
        id<MTLFunction> f = vp_build(vs, m, code, ctl, want, why, sizeof why); free(snap);
        vp_done(vs, f, want, why, t0, "后台编");
    } });
    return 1;
}
// Gap families 34 / 37 (contract: state/直连缺陷线.md, Dsh.cs FsAlphaMs): the fragment entry (main0, or main0_u when u) specialized with S2A_AT = the NVN alpha function
//   (1 NEVER … 7 GEQUAL; not given when 0, the test compiled out) and S2A_MSOFF = sample mask written full. Built once per (u, at, msoff) and kept; nil when the shader declares none
static os_unfair_lock g_atfn_lock = OS_UNFAIR_LOCK_INIT;
static id<MTLFunction> fs_atms_fn(NvShader *fs, int u, int at, int msoff) {
    if (!fs || !fs->has_atms || (u && !fs->at_u)) return nil;
    NSNumber *key = @(u << 9 | at << 1 | (msoff != 0));
    os_unfair_lock_lock(&g_atfn_lock); id<MTLFunction> f = fs->at_fns[key]; os_unfair_lock_unlock(&g_atfn_lock);
    if (f) return f;
    MTLFunctionConstantValues *cv = [MTLFunctionConstantValues new];
    if (at) { int32_t a = at; [cv setConstantValue:&a type:MTLDataTypeInt withName:@"S2A_AT"]; }
    if (msoff) { bool b = true; [cv setConstantValue:&b type:MTLDataTypeBool withName:@"S2A_MSOFF"]; }
    NSError *e = nil; f = [fs->at_lib newFunctionWithName:u ? fs->at_u : fs->at_main constantValues:cv error:&e];
    if (!f) { MLOG("【红】 fragment shader %s: specializing alpha test %d / multisampling off %d failed: %s", fs->key, at, msoff, e.localizedDescription.UTF8String); return nil; }
    os_unfair_lock_lock(&g_atfn_lock); if (!fs->at_fns) fs->at_fns = [NSMutableDictionary dictionary]; fs->at_fns[key] = f; os_unfair_lock_unlock(&g_atfn_lock);
    return f;
}
static MTLRenderPipelineDescriptor *pso_desc(const pso_key *k, NvShader *vs, NvShader *fs, id<MTLFunction> fsfn, int merged) {
    MTLRenderPipelineDescriptor *d = [MTLRenderPipelineDescriptor new];
    // vs nil: no vertex stage, the fragment half of a task / mesh pipeline (mtk_pso copies it into its mesh descriptor). Setting the mesh function as vertexFunction is what Metal's
    //   validation layer (MTL_DEBUG_LAYER=1) aborts on (#376: the tool that checks the M1 Metal 4 hang could not be turned on)
    if (vs) { uint32_t pm = pso_pair_miss(vs, fs); id<MTLFunction> vf = pm ? vp_fn(vs, pm) : nil; d.vertexFunction = vf ? vf : vs->fn; }   // a pair the vertex shader needs padding for (vp_ask)
    d.fragmentFunction = fsfn ? fsfn : fs ? fs->fn : nil;
    // Diagnostic DM_NVN_HILITE=fragment shader key,...: these draws use a solid-color fragment instead (keys 1–6 in order magenta / green / cyan / yellow / blue / white), to see where the geometry lands
    // Pipelines are built on several threads at once: the keys and the library are set up once (a lazy setup raced, and a thread used a library another had just replaced: Hades II, 6 keys)
    if (fs) { static char keys[6][24]; static int nk; static id<MTLLibrary> hl; static dispatch_once_t once;
        dispatch_once(&once, ^{ const char *e = getenv("DM_NVN_HILITE");
            for (const char *q = e; q && *q && nk < 6; q = strchr(q, ',') ? strchr(q, ',') + 1 : q + strlen(q)) { size_t n = strcspn(q, ","); if (n > 23) n = 23; memcpy(keys[nk], q, n); keys[nk++][n] = 0; }
            if (!nk) return;
            NSError *err = nil; hl = [g_dev newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal;\nstruct O { float4 c0 [[color(0)]]; float4 c1 [[color(1)]]; float4 c2 [[color(2)]]; };\n"
                "fragment O hl0() { return {float4(1,0,1,1),float4(1,0,1,1),float4(1,0,1,1)}; } fragment O hl1() { return {float4(0,1,0,1),float4(0,1,0,1),float4(0,1,0,1)}; }\n"
                "fragment O hl2() { return {float4(0,1,1,1),float4(0,1,1,1),float4(0,1,1,1)}; } fragment O hl3() { return {float4(1,1,0,1),float4(1,1,0,1),float4(1,1,0,1)}; }\n"
                "fragment O hl4() { return {float4(0,0,1,1),float4(0,0,1,1),float4(0,0,1,1)}; } fragment O hl5() { return {float4(1,1,1,1),float4(1,1,1,1),float4(1,1,1,1)}; }\n" options:nil error:&err];
            if (!hl) MLOG("【红】 HILITE shader compile failed %s", err.localizedDescription.UTF8String); });
