// Bytes of a pipeline key that pso_desc never reads go to 0, so one Metal descriptor is one key (S2Arm 10-25). The game leaves blend state, channel masks and blend-enable bits on targets
// it does not draw to, or on targets whose blending is off; kept in the key they split one pipeline into several builds, and keys from elsewhere (recorded seeds of other runs, community
// pipeline data) never matched them: in Mario Kart 8 Deluxe's recorded keys, 279 of 400 carried blend bytes of targets with blending off. Normal passes only: a merged pass reads target i's
// state at lmap[i] (pso_desc), kept as it is. fs: the fragment shader (its output map), or nil. Called where the key is made (pso_key_fill) and on recorded keys as they are read (warm_task)
static void pso_key_norm(pso_key *k, NvShader *vs, NvShader *fs, int merged) {
    if (vs) {   // vertex attributes the vertex shader does not read, and streams no kept attribute uses (pso_key_fill copies only those; keys from elsewhere may carry more)
        uint32_t read = 0, used = 0; for (int v = 0; v < vs->rf.nv; v++) if (vs->rf.v[v].nvn < 16) read |= 1u << vs->rf.v[v].nvn;
        for (int a = 0; a < 16; a++) { if (!(read >> a & 1)) memset(&k->attr[a], 0, sizeof k->attr[a]); else if (k->attr[a].stream < 16) used |= 1u << k->attr[a].stream; }
        for (int i = 0; i < 16; i++) if (!(used >> i & 1)) memset(&k->stream[i], 0, sizeof k->stream[i]);
    }
    if (merged) return;
    for (int i = 0; i < 8; i++) {
        int unwritten = k->cfmt[i] && fs && fs->rf.color_known && !(fs->rf.color_mask >> i & 1);   // pso_desc: write mask 0, no blending
        if (!k->cfmt[i] || unwritten) { k->chmask &= ~(0xfu << (4 * i)); k->blend_en &= ~(1u << i); memset(&k->blend[i], 0, sizeof k->blend[i]); continue; }
        if (!(k->blend_en >> i & 1) || pf_int_kind((MTLPixelFormat)k->cfmt[i])) { k->blend_en &= ~(1u << i); memset(&k->blend[i], 0, sizeof k->blend[i]); continue; }   // no blending (integer targets never blend)
        k->blend[i].target = 0;   // pso_desc reads only the factors and equations
    }
}
// Pipeline key: current state S + pass formats (normal pass; a merged pass additionally carries lmap / specialized function, filled in by pso_get)
static void pso_key_fill(pso_key *k, NvShader *vs, NvShader *fs, const uint32_t cfmt[8], uint32_t dfmt, uint32_t sfmt, uint32_t samples, int lmap) {
    memset(k, 0, sizeof *k);
    k->vs = (__bridge void *)vs; k->fs = (__bridge void *)fs;
    memcpy(k->cfmt, cfmt, sizeof k->cfmt); k->dfmt = dfmt; k->sfmt = sfmt; k->samples = samples;
    k->blend_en = S.color.blend_en; k->chmask = S.chmask.mask; k->a2c = S.ms.a2c;
    { int af = (int)S.color.alpha_func, ms_off = !S.ms.enable && samples > 1;   // gap families 34 / 37: NVN alpha test (ALWAYS 8 = off) and multisampling off on a multisampled target
      if (fs && fs->has_atms) { k->at = af >= 1 && af <= 7 ? (uint8_t)af : 0; k->msoff = (uint8_t)ms_off; }
      else if (fs && ((af >= 1 && af <= 7) || ms_off)) RED_ONCE(134, "fragment shader %s: alpha test %d / multisampling off %d asked, but its library has no S2A_AT / S2A_MSOFF (built before the gap-family translator): drawn without them", fs->key, af, ms_off); }
    // 高级混合位（blend_st.adv_*，#344）只为 NVN 查询保真、渲染器不模拟，进键前清掉：键只含影响编译结果的状态，否则同一条管线按不影响画面的位拆成多份、白编（10-25 维护者）
    for (int i = 0; i < 8; i++) if (k->cfmt[i] || lmap) { k->blend[i] = S.blend[i]; k->blend[i].adv_mode = k->blend[i].adv_overlap = k->blend[i].adv_premul = k->blend[i].adv_normdst = 0; }
    const nvn_refl *rf = &vs->rf;
    for (int v = 0; v < rf->nv; v++) { int a = rf->v[v].nvn; if (a < 16 && a < S.nattr) { k->attr[a] = S.attr[a]; int st = S.attr[a].stream; if (st < 16) k->stream[st] = S.stream[st]; } }
    pso_key_norm(k, vs, fs, lmap);
}
// ---- Parallel precompile: pipelines met for the first time used to be compiled synchronously one by one on the submit thread; 9 misses in a row in one frame = 284 ms (heavy scene on a real device).
// Now: on the first pipeline miss in a submission, scan ahead once along the remaining commands (replaying state only, no drawing) and kick all the normal-pass pipelines that will also miss later to the background to compile in parallel;
// when the submit thread reaches that draw it only waits for 'the remaining time not yet compiled'. The compiled pipelines are identical to synchronously compiled ones (same descriptor). Pipeline keys of merged passes / specialized fragments depend on the planning result at replay time, are not predicted, and are compiled synchronously as before.
#define PSO_PEND_MAX 384
static struct { pso_key k; id<MTLRenderPipelineState> ps; int used, done, late, stuck; } g_pp[PSO_PEND_MAX];   // late: the submit thread already waited its limit for it once (pso_pend_take); stuck: a draw that cannot be skipped waited the unsafe cap for it
static pthread_mutex_t g_pp_mu = PTHREAD_MUTEX_INITIALIZER; static pthread_cond_t g_pp_cv = PTHREAD_COND_INITIALIZER;
static uint64_t g_pp_submit_mark, g_pp_kicked, g_pp_taken, g_pp_dropped;   // Whether this submission has already been predicted (by submission serial); cumulative kicked / taken / dropped untaken (pso_pend_kick) counts
static void pso_predict_rest(void);
// A pixel shader that reads a user(locn) its vertex shader does not write makes a pipeline Metal refuses: on the Mac the build returns an error, on iOS it aborted inside Metal
// (The Witcher 3, 10-26 test device 2, cold run, frame 1758: SIGABRT under pso_get_ on a vertex / pixel pair the build had not paired, so vs_pad gave the vertex shader nothing).
// Checked before any pipeline with the pair is built (pso_get_, pso_pend_kick, the prewarm). report: one red line, and the pair goes to pso_user.tsv as a P row, from which the next
// build's pairs (direct_lib.sh → shader_pairs.tsv) let vs_pad give the vertex shader those outputs as (0,0,0,1), what the hardware reads there. Positions unknown on either side
// (a library from before user_locs, or a fallback translation without them): as before
static uint32_t pso_pair_miss(NvShader *vs, NvShader *fs); static id<MTLFunction> vp_fn(NvShader *vs, uint32_t miss);
static int pso_pair_ok(NvShader *vs, NvShader *fs, int report) {
    uint32_t miss = pso_pair_miss(vs, fs);
    if (!miss || vp_fn(vs, miss)) return 1;   // the vertex shader's padded variant writes them (vp_ask)
    if (report) { pso_user_record("P\t%.16s\t%.16s\n", vs->key, fs->key);
        static unsigned n; if (n++ < 16) MLOG("vertex %s does not write user(locn) mask %#x that fragment %s reads: its draws wait for the padded variant (vp_ask)", vs->key, miss, fs->key); }
    return 0;
}
static int pso_pend_find(const pso_key *k) { for (int i = 0; i < PSO_PEND_MAX; i++) if (g_pp[i].used && !memcmp(&g_pp[i].k, k, sizeof *k)) return i; return -1; }
static void pso_pend_kick(const pso_key *k, NvShader *vs, NvShader *fs) {   // Called by the submit thread: kick only if it is neither in the cache nor in the table
    if (hm_get_id(&g_pso, k) || !pso_pair_ok(vs, fs, 0)) return;
    pthread_mutex_lock(&g_pp_mu);
    int at = pso_pend_find(k), slot = -1;
    if (at < 0) for (int i = 0; i < PSO_PEND_MAX; i++) if (!g_pp[i].used) { slot = i; break; }
    // Full: reuse a slot whose compile is done but which no draw took. Only a draw's own wait frees a slot, and the lookahead also kicks the attach modes a pass may not use, so
    //   those stayed for the whole run and a full table sent every later first use back to a synchronous build. Dropped, it costs nothing later: Metal keeps what this process
    //   compiled, and building the same descriptor again took 0.0 ms (M5 Max, 24 pipelines, 11-02 microbenchmark), and its records are written when a draw builds it
    if (at < 0 && slot < 0) for (int i = 0; i < PSO_PEND_MAX; i++) if (g_pp[i].used && g_pp[i].done) { slot = i; g_pp[i].ps = nil; g_pp_dropped++; break; }
    if (at < 0 && slot >= 0) { g_pp[slot].k = *k; g_pp[slot].ps = nil; g_pp[slot].done = 0; g_pp[slot].late = 0; g_pp[slot].stuck = 0; g_pp[slot].used = 1; }
    pthread_mutex_unlock(&g_pp_mu);
    if (at >= 0 || slot < 0) return;
    MTLRenderPipelineDescriptor *d = pso_desc(k, vs, fs, nil, 0); g_pp_kicked++; NSString *pkey = par_rkey(k, vs, fs, 0, nil);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        NSError *e = nil; id<MTLRenderPipelineState> ps = par_render(d, pkey, &e);
        pthread_mutex_lock(&g_pp_mu); g_pp[slot].ps = ps; g_pp[slot].done = 1; pthread_cond_broadcast(&g_pp_cv); pthread_mutex_unlock(&g_pp_mu);
    });
}
// How long the submit thread waits for a pipeline compiling in the background (DM_NVN_PSO_WAIT_MS, default 2000; 0 = no limit). The system compiler service runs every compile in this process
//   in turn: Splatoon 3 (10-26, test device 2) waited on one for over 45 seconds at frame 62, the whole output stopped and the watchdog gave up on direct mode; the generic mode's retry stalled
//   for tens of seconds at frame 50 the same way and then went on. Past the limit the draw is skipped like a first-use skip (the pipeline stays queued and is taken once compiled)
// The cap for a draw that cannot be skipped (skip_safe false: its target keeps content across frames): DM_NVN_PSO_UNSAFE_WAIT_MS, default 10000; 0 = no cap. It waits through the
//   per-pipeline limit and the frame budget, since skipping it leaves a hole later frames read (Super Mario Odyssey's black 3D, 10-27). Past this cap the compiler service is
//   stuck rather than slow (Splatoon 3's 45 s wait, 10-26): the draw is skipped after all, with a red line, and the pipeline is marked late like one past its limit, so the run
//   goes on and the watchdog does not give up on direct mode; the picture may then be wrong until the pipeline arrives
static int g_pso_unsafe_ms = -1;   // cache of DM_NVN_PSO_UNSAFE_WAIT_MS (−1 = not read; unit tests set it back to −1 after changing it)
static int pso_unsafe_wait_ms(void) { if (g_pso_unsafe_ms < 0) { const char *e = getenv("DM_NVN_PSO_UNSAFE_WAIT_MS"); g_pso_unsafe_ms = e && *e ? atoi(e) : 10000; if (g_pso_unsafe_ms < 0) g_pso_unsafe_ms = 0; } return g_pso_unsafe_ms; }
static int pso_wait_ms(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_PSO_WAIT_MS"); v = e && *e ? atoi(e) : 2000; if (v < 0) v = 0; } return v; }
static uint64_t g_pp_timeouts;
// The frame's budget for those waits (DM_NVN_PSO_FRAME_MS, default 100; 0 = none): one limit per pipeline was not enough. Splatoon 3's second device run (10-26 21:24, package
//   7b2170220) had one pipeline time out and then 30-odd first uses on targets not started fresh this frame, each compiling 1-2 s behind the same slow compiler service and
//   none past the 2 s limit: frame 51 took 66.9 s in submit. Once the frame has waited this long, its other first uses skip their draw at once (still compiling in the background,
//   taken in a later frame) instead of waiting; the next frame starts a new budget
static int g_pso_frame_ms = -1;   // cache of DM_NVN_PSO_FRAME_MS (−1 = not read; unit tests set it back to −1 after changing it)
static int pso_frame_ms(void) { if (g_pso_frame_ms < 0) { const char *e = getenv("DM_NVN_PSO_FRAME_MS"); g_pso_frame_ms = e && *e ? atoi(e) : 100; if (g_pso_frame_ms < 0) g_pso_frame_ms = 0; } return g_pso_frame_ms; }
static uint64_t g_pp_bud_frame, g_pp_bud_ns, g_pp_bud_skips;   // submit thread only
static int64_t pso_budget_left_ms(void) {   // what this frame may still wait; INT64_MAX without a budget
    if (!pso_frame_ms()) return INT64_MAX;
    uint64_t f = atomic_load_explicit(&g_cur_frame, memory_order_relaxed);
    if (f != g_pp_bud_frame) { g_pp_bud_frame = f; g_pp_bud_ns = 0; }
    int64_t left = (int64_t)pso_frame_ms() - (int64_t)(g_pp_bud_ns / 1000000ull);
    return left > 0 ? left : 0;
}
static void pso_budget_skip_note(void) {
    uint64_t n = ++g_pp_bud_skips;
    if (!(n & (n - 1))) MLOG("pipeline wait budget: %llu first uses skipped their draw after their frame had waited %d ms for compiles (still compiling in the background)", (unsigned long long)n, pso_frame_ms());
}
// 首遇让路（11-07 卡顿线，异度3 冷装读档第 888 帧 2380.7 ms：那条管线在清单里还没轮到，提交线程等它时后台预热 2 个工人照领新行、跟它抢系统编译服务）：
//   提交线程在等一条首遇管线（g_fu_waiting > 0）期间，预热工人不领新行（warm_pick 里等，每次最多 FU_YIELD_MAX_MS，防饿死），已在编的编完。
//   g_warm_busy = 正在编的预热行数，首遇等待行里报「开始等时几个在编」，好分清等的是排队还是编译本身。DM_PSO_FU_YIELD=0 关（A/B 用）
enum { FU_YIELD_MAX_MS = 3000 };
static _Atomic int g_fu_waiting, g_warm_busy;
static _Atomic uint64_t g_fu_yield_n, g_fu_yield_ns;
static int fu_yield_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_PSO_FU_YIELD"); v = !(e && !strcmp(e, "0")); } return v; }
static id<MTLRenderPipelineState> pso_pend_take(const pso_key *k, int *timed_out, int may_skip) {   // Called by the submit thread: if it is in the table, wait for it to finish compiling and take it; otherwise return nil. *timed_out: 1 = past its own limit (late), 2 = the frame's budget ran out
    pthread_mutex_lock(&g_pp_mu);
    // may_skip = 0 (skip_safe: a draw whose target keeps content across frames, or one a shader writes storage in): no limit and no budget, it waits until the pipeline is compiled.
    //   Super Mario Odyssey's Mac cold start (10-27): the system compiler was slow, the frame budget skipped 2048 draws in 4 frames, among them the temporal anti-aliasing / exposure
    //   chain whose output feeds the next frame, and the 3D picture stayed black for the whole run; first_skip_ok never let those draws be skipped, these limits did
    int at = pso_pend_find(k), blk = 0, ms = may_skip ? pso_wait_ms() : pso_unsafe_wait_ms(); id<MTLRenderPipelineState> ps = nil; *timed_out = 0;
    if (may_skip && at >= 0 && g_pp[at].late && !g_pp[at].done) { pthread_mutex_unlock(&g_pp_mu); *timed_out = 1; return nil; }   // waited its limit once already: every later draw with it skips at once until it is done
    // A draw that cannot be skipped waited the whole unsafe cap for it once: the compiler service is stuck on it, and every later draw with it, safe or not, skips at once until it is done.
    //   Splatoon 3 (10-27 PSB, t0100c2500fc20000_1027065706_2): three such draws in a row each waited 10 s for the same pipeline (Hoian_UBER fragment fc88b546d13b4a9f), 31 s at frame 47
    if (at >= 0 && g_pp[at].stuck && !g_pp[at].done) { pthread_mutex_unlock(&g_pp_mu); *timed_out = 1; return nil; }
