static __unsafe_unretained id<MTLRenderPipelineState> pso_get_(NvProg *pr, MTLRenderPassDescriptor *unused);
static id<MTLFunction> ms_fs_override(NvShader *fs);   // DM_NVN_MAGSCAN (defined before draw)
// A pipeline Metal refused: when a colour the fragment shader writes has an integer attachment, its output was most likely translated as float (a game without PC reflection has no output types,
// Tears of the Kingdom's BC4 block encoder and Ultrahand mask were the first cases). Writes the facts row that declares the outputs, for the profile's shader_facts_manual.tsv (merged by shader_split.py)
static const char *pso_fout_hint(NvShader *fs, const uint32_t cfmt[8], char *b, size_t n) {
    if (!fs || strlen(fs->key) < 16) return "";
    int o = snprintf(b, n, "; if its outputs are integers, add to shader_facts_manual.tsv: %.16s\t{\"fout\":{", fs->key), any = 0;
    for (int c = 0; c < 8; c++) { int kind = !fs->rf.color_known || fs->rf.color_mask >> c & 1 ? pf_int_kind((MTLPixelFormat)cfmt[c]) : 0;
        if (kind && o < (int)n) o += snprintf(b + o, n - o, "%s\"%d\":\"%s\"", any++ ? "," : "", c, kind == 1 ? "uint" : "sint"); }
    if (!any) return "";
    if (o < (int)n) snprintf(b + o, n - o, "}}");
    return b;
}
// S2Arm: a pipeline whose integer attachments or dual-source blending the library's entry points do not match (pso_fout_need): the fragment shader's MSL is translated on the device (S2A.Dsh) and given
// an entry point main0_t with exactly those outputs typed as integers and outputs 0 / 1 as [[color(0), index(0 / 1)]] under PSO_FOUT_DUAL (DshCompiler.FsTyped), kept per need mask; tried once per shader and mask. The code / control come from the guest program; the control section is only
// guaranteed valid during SetShaders, so its key is recomputed first (prog_key_live) and a section the game has since reused is refused. → 1 when the variant is there to retry with
int prog_key_live(const prog_t *p, unsigned st, uint8_t key[8]);
// The stage of guest program p whose control section still hashes to the shader key (prog_key_live), md = that key; -1 = none (the game has since reused the section)
static int prog_stage_of(const prog_t *p, const char *key, uint8_t md[8]) {
    for (unsigned i = 0; i < p->nstage; i++) {
        char hx[17]; if (!prog_key_live(p, i, md)) continue;
        for (int b = 0; b < 8; b++) snprintf(hx + 2 * b, 3, "%02x", md[b]);
        if (!strncmp(hx, key, 16)) return (int)i;
    }
    return -1;
}
static int pso_fout_variant(NvProg *pr, NvShader *fs, const pso_key *k, int merged) {
