    pthread_mutex_lock(&g_fnt_mu); int tried = fs->fn_t[@(need | 1u << 31)] != nil; if (!tried) { if (!fs->fn_t) fs->fn_t = [NSMutableDictionary dictionary]; fs->fn_t[@(need | 1u << 31)] = NSNull.null; } pthread_mutex_unlock(&g_fnt_mu);
    if (tried) return 0;   // one attempt per shader and mask
