    uint64_t t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);   // built synchronously on the submit thread: the time is logged to judge whether it should move to the background
    if (dm_shader_fout(md, p->sd[at].data, p->sd[at].control, need & 0xff, need >> 8, path, sizeof path) || !fs_typed_fn(fs, need)) return 0;
