    return 1;
}
static int g_first_skipped;   // pso_get_ returned nil to skip this draw (the draw counts it instead of logging a failure)
static uint64_t g_fsk_draws, g_fsk_frames, g_fsk_run, g_fsk_run_max, g_fsk_last_f, g_fsk_occl;   // g_fsk_occl: skipped while an occlusion query counted (its sample count reads low that frame)
static int shader_writes(NvShader *s) { if (!s) return 0; for (int i = 0; i < s->rf.nb; i++) if (s->rf.b[i].rw) return 1; return 0; }
static uint64_t g_fsk_no[4], g_fsk_no_n;   // why a first use was built here instead: [0] a shader writes storage [1] a target is loaded, not started fresh [2] a target not drawn every frame [3] background table full
static const char *const g_fsk_no_s[4] = {"a shader writes storage", "a target not started fresh this frame", "a target not drawn in the last two frames", "background table full"};
static int fsk_no(int i) {
