#define FSKN(i) fsk_no(i)
// Whether losing this draw costs at most a frame: no shader writes storage, every target is started fresh this frame and was drawn in the last two frames (first_skip_ok's rules).
//   Every skip goes through it: the first-use skip, a compile past its limit and a frame past its wait budget (pso_pend_take)
static int skip_safe(NvShader *vs, NvShader *fs) {
    if (shader_writes(vs) || shader_writes(fs)) return 0;
    for (int i = 0; i < R.rt.n; i++) if (R.rt.color[i] && (!rt_fresh_now(R.rt.color[i]) || !rt_seen_steady(R.rt.color[i]))) return 0;
    if (R.rt.depth && (!rt_fresh_now(R.rt.depth) || !rt_seen_steady(R.rt.depth))) return 0;
