}
static int first_skip_ok(const pso_key *k, NvShader *vs, NvShader *fs) {
    if (!first_skip_on()) return 0;
    if (shader_writes(vs) || shader_writes(fs)) return FSKN(0);
    // Drawn every frame is not enough: a temporal history, accumulated decals or a partly updated shadow atlas are attached every frame and drawn on top of the last frame's content
    //   (direct line 10-26): a draw skipped there leaves its hole for good. Only a target started fresh this frame (cleared / covered) gets it back next frame
    for (int i = 0; i < R.rt.n; i++) if (R.rt.color[i] && !rt_fresh_now(R.rt.color[i])) return FSKN(1);
    if (R.rt.depth && !rt_fresh_now(R.rt.depth)) return FSKN(1);
    for (int i = 0; i < R.rt.n; i++) if (R.rt.color[i] && !rt_seen_steady(R.rt.color[i])) return FSKN(2);
    if (R.rt.depth && !rt_seen_steady(R.rt.depth)) return FSKN(2);
    if (!pso_pend_state(k)) pso_pend_kick(k, vs, fs);   // not queued yet (or the kick before was refused)
