static NSString *warm_key(const char *s, size_t n) {
    size_t z = strnlen(s, n);
    return [[NSString alloc] initWithBytes:s length:z encoding:NSUTF8StringEncoding];
}
// The prewarm runs the lines of its lists as tasks: a shader (S), a compute pipeline (C), or every render pipeline (R) of one shader pair (the pipelines of a pair share their
// shaders, so one worker builds them one after the other). The tasks keep the lists' order (a pair at its first line). shader_load shares successful objects and in-flight loads
// with prefetch and runtime, without negatively caching failures. After the upstream reference implementation (MIT) warm_parse / warm_task
@interface WarmTask : NSObject { @public int kind, stage, fc; NSString *key, *vkey, *fkey; NSMutableArray<NSData *> *rs; } @end   // fc: a C line's sampler-emulation bits this GPU runs (#800, warm_parse)
@implementation WarmTask @end
static _Atomic long g_warm_done;   // lines done (the prepare step's progress)
static _Atomic int g_wp_phase, g_wp_why, g_wp_play; static _Atomic long g_wp_total; static _Atomic uint64_t g_wp_t0;
static void warm_tick_full(long total);   // the front end's (total, total) tick (see s2a_front_warm_tick)   // the host's progress (nvn_warm.h, s2a_warm_progress)
// A prewarm list may name shaders of another version of the game: the bundled list of the version the profile was brought up on, packed with another version (the NSP script's
// derived profile: Hollow Knight: Silksong's 1.0.30000 list named 16 shaders its base game 1.0.27776 does not have), or a device's pso_user.tsv kept across a game update.
// A line with a key the shader map does not have is dropped quietly (counted in the "prewarm done" line); the game never draws with it
static int fb_loadable(NSString *pc);
static NSMutableSet<NSString *> *g_warm_fb_ok;   // keys found current in the fallback directory (warm_stale reads each key's json once)
static int warm_stale(NSString *key, NSMutableSet<NSString *> *stale) {
    // library names are <map key>_b; a geometry-emulation stage's are <map key>_bgv / _bg<i> (lp_kind_of): their map key is the same 16 digits. 11-05 Switch Sports: only _b was stripped,
    //   so the menu transitions' geometry pipelines (pso_user.tsv R rows with a _bgv vertex key) counted as "another game version" and were built on the submit thread every run
    NSString *mk = [key hasSuffix:@"_b"] ? [key substringToIndex:key.length - 2] : key.length > 16 && lp_kind_of(key.UTF8String, 0) >= 0 ? [key substringToIndex:16] : key;
    if (g_shmap[mk]) return 0;
    // S2Arm 11-06: a library this device translated before (DM_MSL_FALLBACK, same chain and translator: fb_loadable) is this game's, not another version's. pso_user.tsv lists the pipelines
    //   built with it; dropping them left the library and its pipelines to the submit thread at their first draw in every run (DRAGON BALL Sparking! ZERO, 测试设备1: all 25 libraries loaded
    //   from the fallback directory in a run were outside the package's map, and the prewarm counted 429 stale keys)
    if ([g_warm_fb_ok containsObject:key]) return 0;
    if (![stale containsObject:key]) {
        if (fb_loadable(key)) { if (!g_warm_fb_ok) g_warm_fb_ok = [NSMutableSet set]; [g_warm_fb_ok addObject:key]; return 0; }
        [stale addObject:key]; g_warm_skip_stale++;
    }
    return 1;
}
// S2Arm: a library to load: in the package (mtl_shlib_has) or translated on this device before (DM_MSL_FALLBACK). A hot-key package's cold key is neither until its first use compiles it
//   (dsh_miss.inc): the prewarm (this device's pso_user.tsv may list it) and the prefetch skip it quietly instead of a red "failed to load" per key (283 in a Mario run with 86 keys removed)
static _Atomic uint64_t g_cold_skips;
static int fb_loadable(NSString *pc) {   // translated on this device before, by this chain and translator
    const char *fb = getenv("DM_MSL_FALLBACK"); if (!fb || !*fb) return 0;
    NSData *jd = [NSData dataWithContentsOfFile:[NSString stringWithFormat:@"%s/%@.json", fb, pc]];   // an older translator's leftover (fb_json_current) is cold too
    NSDictionary *j = jd ? [NSJSONSerialization JSONObjectWithData:jd options:0 error:nil] : nil;
    return [j isKindOfClass:[NSDictionary class]] && fb_json_current(j);
}
static int shader_loadable(NSString *pc) { return mtl_shlib_has(pc.UTF8String) || fb_loadable(pc); }
static NvShader *warm_shader(NSString *key, int stage) {
    if (!shader_loadable(key)) { atomic_fetch_add_explicit(&g_cold_skips, 1, memory_order_relaxed); return nil; }
    return shader_load(key, stage, 0);
}
static void warm_enqueue(WarmItem *item) {
    os_unfair_lock_lock(&g_warm_lock);
    if (!g_warm_items) g_warm_items = [NSMutableArray array];   // the shader prefetch can come before (or without) the prewarm list
    [g_warm_items addObject:item];
    atomic_store_explicit(&g_warm_ready, 1, memory_order_release);
    os_unfair_lock_unlock(&g_warm_lock);
}
// S2Arm: shader libraries are prefetched when the game sets a program's shaders (ProgramSetShaders, on a game thread), off the frame path. The submit thread used to read the reflection
// json and map the metallib synchronously at the first draw with the program: in Mario Kart 8 Deluxe's cold run the 13 late frames after MARK were all 30-350 ms of "new pipelines +
// shader libraries" (mk8d_1025033857_1). A serial background queue loads them and hands them over the way the prewarm list does (warm_claim); a draw that comes before its load is done
// shares that in-flight load. Keys in neither the package map nor the device's fallback translation (shmap_stage: builtin kernels, keys not translated yet) stay on the submit thread. Geometry stages take these lanes too (P1-91, 11-03):
//   they were left out at a26d74664 with no reason given, and their library (or a slice writer's stub, shader_build) was read on the submit thread at the first draw with them
// DM_NVN_SHPRE=0 turns it off
static int shpre_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_SHPRE"); v = !(e && !strcmp(e, "0")); if (!v) MLOG("DM_NVN_SHPRE=0: shader libraries are loaded at their first draw (no prefetch)"); } return v; }
static _Atomic uint64_t g_shpre_n, g_shpre_ns;
// Lanes: a few serial queues side by side, a key always on the same one. The prefetch ran on one serial queue at background QoS (CPU and I/O throttled), and a draw that came before
//   its load waited for it: Ori and the Will of the Wisps (11-02, c1102_recheck_ori, frame 1740) loaded 188 libraries in one frame, 62.5 s, the prefetch averaged 21 ms a library
//   behind a backlog of thousands; Super Mario Party's prefetch 0.5-0.7 s a library. Width: half the cores, at most what the device compiles at once
//   (maximumConcurrentCompilationTaskCount, 18 on an M5 Max), 2..SHQ_MAX
enum { SHQ_MAX = 8 };
typedef struct { dispatch_queue_t q[SHQ_MAX]; int n; } shq_t;
static int shq_width(void) {
    static int w; if (!w) { NSUInteger c = NSProcessInfo.processInfo.activeProcessorCount / 2, m = 2;
        if (@available(macOS 13.3, iOS 26.0, *)) { if (g_dev && [g_dev respondsToSelector:@selector(maximumConcurrentCompilationTaskCount)]) m = g_dev.maximumConcurrentCompilationTaskCount; }   // iOS 26.0 真机上系统版本判断为真、方法却不存在，直接调用抛 NSInvalidArgumentException 闪退（#85）
        NSUInteger x = c < m ? c : m; w = x < 2 ? 2 : x > SHQ_MAX ? SHQ_MAX : (int)x;
        MLOG("shader load lanes: %d (cores %lu, device compiles at once %lu)", w, (unsigned long)NSProcessInfo.processInfo.activeProcessorCount, (unsigned long)m); }
    return w;
}
static void shq_init(shq_t *s, const char *name, qos_class_t qos) {
    if (s->n) return;
    for (int i = 0; i < shq_width(); i++) s->q[i] = dispatch_queue_create(name, dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL, qos, 0));
    s->n = shq_width();
}
static void shq_async(shq_t *s, NSString *k, dispatch_block_t b) { dispatch_async(s->q[(NSUInteger)k.hash % (NSUInteger)s->n], b); }
// A marker on every lane into group g: once g is empty, everything queued on the lanes before the marking has run. Callers that must order it after enqueues mark under g_shpre_mu
static void shq_mark(shq_t *s, dispatch_group_t g) { for (int i = 0; i < s->n; i++) dispatch_group_async(g, s->q[i], ^{}); }
static shq_t g_shpre, g_shurg;   // the prefetch at ProgramSetShaders (utility QoS) / the lookahead's loads for this submission (user-initiated, shader_urgent)
static NSMutableSet<NSString *> *g_shpre_seen;
static os_unfair_lock g_shpre_mu = OS_UNFAIR_LOCK_INIT;
static _Atomic int g_shpre_stopping;
static void shpre_sync(void) { dispatch_group_t g = dispatch_group_create(); os_unfair_lock_lock(&g_shpre_mu); shq_mark(&g_shpre, g); shq_mark(&g_shurg, g); os_unfair_lock_unlock(&g_shpre_mu); dispatch_group_wait(g, DISPATCH_TIME_FOREVER); }   // unit tests: wait for every queued load
// The lookahead (prog_peek) found a stage of a draw later in this submission not loaded: load it now on the urgent lanes, beside the submit thread, instead of when its draw reaches
//   prog_get. The submit thread then takes it from the cache or shares the load in flight (shader_load_depth, which lends it this thread's urgency). At most 2 per lane queued
static _Atomic int g_shurg_live; static _Atomic uint64_t g_shurg_n, g_shurg_ns;
static void shader_urgent(NSString *k, int st) {
    if (!shpre_on() || st < 0 || atomic_load(&g_shurg_live) >= 2 * shq_width()) return;
    os_unfair_lock_lock(&g_shpre_mu);
    if (atomic_load(&g_shpre_stopping)) { os_unfair_lock_unlock(&g_shpre_mu); return; }
    shq_init(&g_shurg, "dm.nvn.sh-urg", s2a_qos(S2A_QOS_SHADER_URGENT));
    atomic_fetch_add(&g_shurg_live, 1);
    shq_async(&g_shurg, k, ^{ @autoreleasepool {
        if (!atomic_load(&g_shpre_stopping)) {
            uint64_t t0 = bp_now(); NSString *key = [k stringByAppendingString:@"_b"];
            if (shader_loadable(key) && shader_load(key, st, 0)) {
                uint64_t n = atomic_fetch_add(&g_shurg_n, 1) + 1, ns = atomic_fetch_add(&g_shurg_ns, bp_now() - t0) + (bp_now() - t0);
                if (!(n & (n - 1)) && n >= 16) MLOG("shader lookahead loads: %llu libraries loaded beside the submit thread for later draws of their submission, %.1f ms in all", (unsigned long long)n, ns / 1e6);
            }
        }
        atomic_fetch_sub(&g_shurg_live, 1);
    } });
    os_unfair_lock_unlock(&g_shpre_mu);
}
void nvn_be_shader_prefetch(const uint8_t md[8]) {
    if (!shpre_on()) return;
    NSString *k = [NSString stringWithFormat:@"%02x%02x%02x%02x%02x%02x%02x%02x", md[0], md[1], md[2], md[3], md[4], md[5], md[6], md[7]];
    // Session stop takes this same lock: enqueue must finish before its drain marker can be submitted.
    os_unfair_lock_lock(&g_shpre_mu);
    if (atomic_load(&g_shpre_stopping)) { os_unfair_lock_unlock(&g_shpre_mu); return; }
    // S2Arm three tiers (commander 10-27): the hot set (the prewarm lists' lines) is built before the first frame (warm_start); the rest of the programs the game creates are loaded here at
    //   utility QoS on the lanes (shq_t), off the main and game threads; one a program draws with before its turn comes is loaded on the submit thread then (shader_get), or ahead of
    //   it by the lookahead (shader_urgent)
    if (!g_shpre.n) { shq_init(&g_shpre, "dm.nvn.sh-pre", s2a_qos(S2A_QOS_SHADER_PREFETCH)); g_shpre_seen = [NSMutableSet set]; }
    if ([g_shpre_seen containsObject:k]) { os_unfair_lock_unlock(&g_shpre_mu); return; }
    [g_shpre_seen addObject:k];
    shq_async(&g_shpre, k, ^{ @autoreleasepool {
        if (atomic_load(&g_shpre_stopping)) return;
        shmap_load();
        NSString *stage = shmap_stage(k); int st = stage ? stage_of(stage) : -1;
        if (st < 0) return;
        uint64_t t0 = bp_now(); NSString *key = [k stringByAppendingString:@"_b"];
        if (!shader_loadable(key)) { atomic_fetch_add_explicit(&g_cold_skips, 1, memory_order_relaxed); return; }   // compiled at its first use (dsh_miss.inc)
        NvShader *sh = shader_load(key, st, 0);
        if (!sh) return;   // the submit thread loads it again and logs the red line
        WarmItem *item = [WarmItem new]; item->kind = 3; item->key = key; item->shader = sh;
        warm_enqueue(item);
        uint64_t d = bp_now() - t0, n = atomic_fetch_add(&g_shpre_n, 1) + 1, ns = atomic_fetch_add(&g_shpre_ns, d) + d;
        if (!(n & (n - 1)) && n >= 64) MLOG("shader prefetch: %llu libraries loaded off the frame path on %d lanes, %.1f ms in all", (unsigned long long)n, g_shpre.n, ns / 1e6);
    } });
    os_unfair_lock_unlock(&g_shpre_mu);
}
// The lists' lines as tasks; *lines: the lines they hold
static NSArray<WarmTask *> *warm_parse(NSArray<NSString *> *paths, long *lines) {
    NSMutableArray<WarmTask *> *tasks = [NSMutableArray array];
    NSMutableSet<NSString *> *seen = [NSMutableSet set], *stale = [NSMutableSet set]; long n = 0;
    for (NSString *path in paths) {
        NSString *txt = [NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:nil];
        if (!txt) { MLOG("【红】 cannot read prewarm list: %s", path.UTF8String); continue; }
        { unsigned long nl = 0; for (NSString *l in [txt componentsSeparatedByString:@"\n"]) nl += l.length && ![l hasPrefix:@"#"];
          MLOG("pipeline prewarm list %s: %lu lines", path.UTF8String, nl); }   // Diagnostics: how many lines each manifest gave (when a device warms up 0, shows which one was missing)
        for (NSString *line in [txt componentsSeparatedByString:@"\n"]) {
            if (!line.length || [line hasPrefix:@"#"] || [seen containsObject:line]) continue;
            [seen addObject:line];
            NSArray<NSString *> *c = [line componentsSeparatedByString:@"\t"];
            WarmTask *t = nil;
            // S2Arm #800: a reduction-variant pipeline line (an R line's fc, a C line's third column: recorded where a GPU without the native reduction built one; the package's seed may
            //   carry them) is built as fc & the bits this GPU runs (se_mask): 0 on an Apple10 GPU, where it is the main0 pipeline and goes when another line already names that
            int fc = 0;
            if ([c[0] isEqualToString:@"C"] && c.count >= 3) {
                fc = (int)strtol(c[2].UTF8String, NULL, 16) & se_mask();
                NSString *ml = fc ? [NSString stringWithFormat:@"C\t%@\t%x", c[1], fc] : [@"C\t" stringByAppendingString:c[1]];
                if (![ml isEqualToString:line]) { if ([seen containsObject:ml]) continue; [seen addObject:ml]; }
            }
            if (([c[0] isEqualToString:@"S"] && c.count >= 3) || ([c[0] isEqualToString:@"C"] && c.count >= 2)) {
                if (!c[1].length || warm_stale(c[1], stale)) continue;
                t = [WarmTask new]; t->kind = [c[0] isEqualToString:@"S"] ? 0 : 2; t->key = c[1]; t->stage = t->kind ? 5 : c[2].intValue; t->fc = t->kind ? fc : 0; [tasks addObject:t];
            } else if ([c[0] isEqualToString:@"R"] && c.count >= 2) {
                pso_skey sk; if (pso_skey_parse(c[1].UTF8String, &sk)) continue;
                if (sk.k.fc & ~se_mask()) {
                    sk.k.fc &= (uint8_t)se_mask(); char hx[sizeof sk * 2 + 1]; pso_skey_hex(&sk, hx);
                    NSString *ml = [@"R\t" stringByAppendingString:@(hx)]; if ([seen containsObject:ml]) continue; [seen addObject:ml];
                }
                NSString *vkey = warm_key(sk.vs, sizeof sk.vs), *fkey = warm_key(sk.fs, sizeof sk.fs);
                if (!vkey.length || warm_stale(vkey, stale) || (fkey.length && warm_stale(fkey, stale))) continue;
                // One task per R line (11-06, Xenoblade 3 on 测试设备1): lines used to be grouped per (vertex, fragment) pair and a pair's pipelines built one after another on one
                //   worker; its list has a pair with 73 lines, so the prepare step's last lines ran on one core while the rest idled and the first frame waited the whole 15 s cap with
                //   12497 of 12523 lines done. The shaders' loads are shared anyway (shader_load_depth: one load per key, waiters join the one in flight), so the pair bought nothing
                t = [WarmTask new]; t->kind = 1; t->vkey = vkey; t->fkey = fkey; t->rs = [NSMutableArray arrayWithObject:[NSData dataWithBytes:&sk length:sizeof sk]]; [tasks addObject:t];
            } else continue;
            n++;
        }
    }
    *lines = n; return tasks;
}
// 预热插队（11-06 卡顿线，异度3 测试设备1 冷装读档）：清单按录制局「首次用到的先后」排，读档直接进的场景，它的管线在 12796 行的清单里排第 12679–12744 行；
//   加载页到点放行时只编到第 5341 行，场景第一帧整个 G-buffer 都是新开的目标（不能跳），13 条管线排在后台队列里没编到，提交线程干等，最长一条 2714 ms。
//   游戏读档装载场景时先登记着色器程序（ProgramSetShaders，见上面 prog 登记处）、几秒后才画第一帧：登记那一刻按（顶点键，片元键）在清单里查到这对的 R 行，
//   放进急件队列；工人领下一行时先领急件（warm_pick）。每行一个「已领」标记，急件和顺序两条路谁先领谁编，不重复编；在编的同键首遇照旧由 par_render 在途合并
static os_unfair_lock g_wu_lock = OS_UNFAIR_LOCK_INIT;
static NSDictionary<NSString *, NSArray<NSNumber *> *> *g_wu_pairs;   // "顶点键|片元键" → R 行下标；nil = 当前没有在跑的预热
static NSMutableArray<NSNumber *> *g_wu_q;                             // 急件下标（先进先出）
static _Atomic(uint8_t) *g_wu_claim; static long g_wu_n;                // 每行「已领」标记
static _Atomic uint64_t g_wu_bumped, g_wu_taken;                        // 放进急件的行数 / 由急件路领走编的行数
static void warm_urgent_index(NSArray<WarmTask *> *tasks) {
    NSMutableDictionary<NSString *, NSMutableArray<NSNumber *> *> *m = [NSMutableDictionary dictionary];
    for (NSUInteger i = 0; i < tasks.count; i++) { WarmTask *t = tasks[i]; if (t->kind != 1) continue;
        NSString *k = [NSString stringWithFormat:@"%@|%@", t->vkey, t->fkey ?: @""];
        NSMutableArray *a = m[k]; if (!a) m[k] = a = [NSMutableArray array]; [a addObject:@(i)]; }
    _Atomic(uint8_t) *c = calloc(tasks.count ? tasks.count : 1, sizeof *c);
    os_unfair_lock_lock(&g_wu_lock); free((void *)g_wu_claim); g_wu_claim = c; g_wu_n = (long)tasks.count; g_wu_pairs = m; g_wu_q = [NSMutableArray array]; os_unfair_lock_unlock(&g_wu_lock);
}
static void warm_urgent_end(void) { os_unfair_lock_lock(&g_wu_lock); g_wu_pairs = nil; [g_wu_q removeAllObjects]; os_unfair_lock_unlock(&g_wu_lock); }   // 标记数组留给还没退出的工人读（随下一次索引换掉）
// 工人领下一行：先急件，再按清单顺序；已领的跳过。→ 下标，-1 = 没有了
static long warm_pick(_Atomic long *next, long n) {
    if (fu_yield_on() && atomic_load(&g_fu_waiting)) {   // 首遇让路：提交线程在等首遇管线时不领新行
        uint64_t t0 = bp_now();
        while (atomic_load(&g_fu_waiting) && (bp_now() - t0) < FU_YIELD_MAX_MS * 1000000ull && !dm_gfx_session_stopping()) usleep(500);
        atomic_fetch_add(&g_fu_yield_n, 1); atomic_fetch_add(&g_fu_yield_ns, bp_now() - t0);
    }
    for (;;) {
        long i = -1;
        os_unfair_lock_lock(&g_wu_lock); if (g_wu_q.count) { i = g_wu_q[0].longValue; [g_wu_q removeObjectAtIndex:0]; } _Atomic(uint8_t) *c = g_wu_claim; long cn = g_wu_n; os_unfair_lock_unlock(&g_wu_lock);
        int urgent = i >= 0;
        if (!urgent) { i = atomic_fetch_add(next, 1); if (i >= n) return -1; }
        if (!c || i >= cn || !atomic_exchange(&c[i], 1)) { if (urgent) atomic_fetch_add(&g_wu_taken, 1); return i; }
    }
}
static void warm_bump(const char *vk, const char *fk) {
    if (!vk) return;
    NSString *k = [NSString stringWithFormat:@"%s|%s", vk, fk ? fk : ""]; uint64_t added = 0;
    os_unfair_lock_lock(&g_wu_lock);
    NSArray<NSNumber *> *rows = g_wu_pairs[k];
    for (NSNumber *r in rows) if (r.longValue < g_wu_n && !atomic_load(&g_wu_claim[r.longValue])) { [g_wu_q addObject:r]; added++; }
    os_unfair_lock_unlock(&g_wu_lock);
    if (added) { uint64_t n = atomic_fetch_add(&g_wu_bumped, added) + added;
        if (!((n - added) & (n - added - 1)) || n == added) MLOG("pipeline prewarm: the game registered a program whose pipelines were still queued: %llu lines moved to the front so far (%llu taken from the front)", (unsigned long long)n, (unsigned long long)atomic_load(&g_wu_taken)); }
}
static void warm_task_(WarmTask *t);
static void warm_task(WarmTask *t) { atomic_fetch_add(&g_warm_busy, 1); par_write_in_place = 1; warm_task_(t); par_write_in_place = 0; atomic_fetch_sub(&g_warm_busy, 1); }   // the prewarm writes what it compiles into the archive (pso_archive.h)
static void warm_task_(WarmTask *t) {
    @autoreleasepool {
        if (t->kind == 0) {
            NvShader *sh = warm_shader(t->key, t->stage);
            if (sh) { WarmItem *item = [WarmItem new]; item->kind = 0; item->key = t->key; item->shader = sh; warm_enqueue(item); g_warm_shaders++; }
            g_warm_done++; return;
        }
        if (t->kind == 2) {
            NvShader *cs = warm_shader(t->key, 5); NSError *e = nil;
            if (cs && cs->tensor == 1) { g_warm_skip_fz++; g_warm_done++; return; }   // a tensor-core network program: never dispatched (nvn_tensor.inc), no pipeline
            id<MTLFunction> fn = cs && t->fc ? se_warm(cs, t->fc) : cs ? cs->fn : nil;   // S2Arm #800: a C line's emulation bits (warm_parse): the variant a run before made, else made at its first use
            if (cs && !fn) { g_warm_skip_fz++; g_warm_done++; return; }
            id ps = fn ? par_compute(fn, par_ckey(cs, t->fc), &e) : nil;
            if (cs && !ps) MLOG("【红】 background compute pipeline creation failed: %s", e.localizedDescription.UTF8String);
            if (ps) { WarmItem *item = [WarmItem new]; item->kind = 2; item->fc = t->fc; item->key = t->key; item->shader = cs; item->object = ps; warm_enqueue(item); g_warm_cps++; }
            g_warm_done++; return;
        }
        pso_skey sk; [t->rs[0] getBytes:&sk length:sizeof sk];
        NvShader *vs = warm_shader(t->vkey, sk.vs_stage), *fs = t->fkey.length ? warm_shader(t->fkey, sk.fs_stage) : nil;
        for (NSData *row in t->rs) {
            [row getBytes:&sk length:sizeof sk];
            if (!vs || (t->fkey.length && !fs) || !pso_pair_ok(vs, fs, 0)) { g_warm_done++; continue; }
            id<MTLFunction> fsfn = nil;
            if (sk.fz) {
                if (sk.fz_desc.kind == 1 && fs) { int fx[32]; for (int i = 0; i < 32; i++) fx[i] = sk.fz_desc.fx[i]; fsfn = bf_fn(fs, fx, sk.fz_desc.fbmask, sk.k.lmap); }
                if (!fsfn) { g_warm_skip_fz++; g_warm_done++; continue; }
            }
            pso_key k = sk.k; k.vs = (__bridge void *)vs; k.fs = (__bridge void *)fs; k.fsfn = (__bridge void *)fsfn; pso_key_norm(&k, vs, fs, sk.merged);   // seeds written before the normalisation, and keys from elsewhere, still hit
            if (k.fc && !se_warm(fs, k.fc)) { g_warm_skip_fz++; g_warm_done++; continue; }   // S2Arm #800: a sampler-emulation pipeline (fc masked to this GPU's bits, warm_parse) whose variant this device has not made (yet): made at its first use
            NSString *akey = par_rkey(&k, vs, fs, sk.merged, fsfn);
            NSError *e = nil; id ps = par_render(pso_desc(&k, vs, fs, fsfn, sk.merged), akey, &e);
            if (!ps && !vs->layer_out && [e.localizedDescription containsString:@"render_target_array_index"]) {   // a vertex shader that writes the layer (see pso_get_)
                vs->layer_out = 1; e = nil; ps = par_render(pso_desc(&k, vs, fs, fsfn, sk.merged), akey, &e); }
            g_warm_done++;
            if (!ps) { MLOG("【红】 background render pipeline creation failed: %s", e.localizedDescription.UTF8String); continue; }
            WarmItem *item = [WarmItem new]; item->kind = 1; item->vs_key = t->vkey; item->fs_key = t->fkey; item->vs = vs; item->fs = fs; item->fsfn = fsfn; item->pso = k; item->object = ps;
            warm_enqueue(item); g_warm_rps++;
        }
    }
}
static void warm_finish(void) {
    shader_load_stats();
    MLOG("pipeline prewarm done: shaders %llu / render pipelines %llu (specialized fragment skipped %llu) / compute pipelines %llu, background time %.1f ms; shader keys not in the shader map (another game version) %llu; not in the library yet (compiled at their first use) %llu",
         (unsigned long long)g_warm_shaders, (unsigned long long)g_warm_rps, (unsigned long long)g_warm_skip_fz, (unsigned long long)g_warm_cps, (bp_now() - g_warm_t0) / 1e6, (unsigned long long)g_warm_skip_stale, (unsigned long long)atomic_load(&g_cold_skips));
    if (g_par_on) MLOG("pipeline archive after the prewarm: %llu builds from the archive, %llu compiled (written beside it, in the background), %llu stale files dropped",
                       (unsigned long long)g_par_hits, (unsigned long long)g_par_misses, (unsigned long long)g_par_stale);
    atomic_store(&g_warm_running, 0); atomic_store(&g_wp_phase, WARM_DONE);   // the host's progress (nvn_warm.h)
    warm_urgent_end();
    if (atomic_load(&g_fu_yield_n)) MLOG("pipeline prewarm: workers held back %llu times while the submit thread waited for a first-use pipeline, %.1f ms in all", (unsigned long long)atomic_load(&g_fu_yield_n), atomic_load(&g_fu_yield_ns) / 1e6);
    if (atomic_load(&g_wu_bumped)) MLOG("pipeline prewarm: %llu lines moved to the front when the game registered their programs, %llu of them built from the front", (unsigned long long)atomic_load(&g_wu_bumped), (unsigned long long)atomic_load(&g_wu_taken));
    warm_tick_full(atomic_load(&g_wp_total));   // the whole list is built (the front end's "fully prewarmed" mark)
    par_flush_bg();
}
// Wait for the background warm-up to finish (at most timeout_ms): returns how many milliseconds were actually waited, 0 if it is not running. On first install the system shader cache is fully cold; if warm-up is slower than the player entering a run,
// pipelines not yet warmed are compiled on the spot on the submit thread = in-run stutter; the loading screen on entering a run blocks the player anyway, so let it load a little longer (called where hle_nvn.c presents).
int mtl_warm_wait(int timeout_ms) {
    if (!atomic_load(&g_warm_running)) return 0;
    uint64_t t0 = bp_now();
    DM_BLOCK_BEGIN(); while (atomic_load(&g_warm_running) && (bp_now() - t0) / 1000000ull < (uint64_t)timeout_ms) usleep(2000); DM_BLOCK_END();
    return (int)((bp_now() - t0) / 1000000ull) + 1;
}
// ---- The prepare step: the prewarm before the game's first frame (after the upstream reference implementation's warm_prepare, MIT) ----
// With DM_PSO_PREPARE=1 (no longer the iOS default, see prepare_on) the first submission waits until every line of the prewarm lists (the package's pso_manifest.tsv, then this device's pso_user.tsv) is built:
// the shaders loaded and the pipelines made, on as many workers as the device has cores, at user-initiated QoS, since the game draws nothing meanwhile. One serial background worker
// used to run them while the game played: a fresh install's first run met them first on the submit thread (mhrise 10-26: 111 pipelines without a linked stand-in, built there).
// Each start runs it (a stamp would skip it exactly when the system dropped the Metal cache); past 0.5 s with 0.3 s or more still to go the front end may show progress
// (front_progress, a weak hook). without DM_PSO_PREPARE=1 the prewarm runs in the background (warm_start, the default everywhere since 11-02); DM_PSO_PREPARE_THREADS=<n> sets the workers
// The loading page (S2Arm 10-30, device / native line: the page, its estimate, its guards and the start flow are the front end's): s2a_front_warm_tick(done, total) once when the
//   prepare step starts (0, total), every 50 ms while it waits, and once when the whole list is built (total, total: the front end marks this package as fully prewarmed, so that
//   call is always made, from warm_finish too when the rest finished in the background). It returns 1 = enter the game now (the rest goes on in the background, as late below),
//   0 = keep waiting. The weak definition here returns -1: no front end linked (the Mac, tests), and this file's own guards apply (DM_PSO_PREPARE_STALL_MS / _MAX_MS)
int s2a_front_warm_tick(long done, long total);
__attribute__((weak)) int s2a_front_warm_tick(long done, long total) { (void)done; (void)total; return -1; }
// The prepare step stopped waiting on its own (the cap, or every line taken: see warm_prepare), not because the front end said so: the front end closes its page then (11-06: the page
//   used to close only on its own guards, so a release here left it on "optimizing" until those fired). Weak no-op without a front end
void s2a_front_warm_released(void);
__attribute__((weak)) void s2a_front_warm_released(void) {}
static _Atomic int g_wp_full_sent;   // the (total, total) tick went out
static void warm_tick_full(long total) { if (!atomic_exchange(&g_wp_full_sent, 1)) (void)s2a_front_warm_tick(total, total); }
// 11-02 (Monster Hunter Rise on an iPhone 17 Pro, a cold start): the first frame waited 64 s for 12,741 of 17,630 lines on every core and the phone was in the serious thermal state
//   from then on (60 fps fell back to 30, the CPU ran at 1.36 GHz). The first frames need only the few pipelines they draw with, and those compile at their first use (pso_pend, at
//   user-initiated QoS, ahead of the prewarm). So no platform waits by default any more: the prewarm runs in the background (warm_bg) and the game starts at once. DM_PSO_PREPARE=1 waits
// 开局准备（首帧前阻塞预热）缺省开、DM_PSO_PREPARE=0 关。来历：10-30 维护者 批加载页等整张清单；11-02 cd3dfd8a1 改成各平台缺省不等、全在后台 2 路 utility
//   （怪猎首帧等整段预热 64 s，6 核 user-initiated 起局即严重发热、60 帧掉 30）。11-05 改回有上限：斯普拉遁3（c1104_r2）进局后第 54 / 232 帧单条首用等待 26.5 / 36.7 s，
//   31 条等的管线 31 条都在清单里，只是后台还没排到。判据（维护者 10-29）：首装一次性 loading ≤ 15 s、之后不卡 → 首帧前满核编清单最前面（首遇先后）的，
//   15 s（DM_PSO_PREPARE_MAX_MS）到点必放行、前端也不能延长，剩下的交给后台 DM_PSO_BG_THREADS 路 utility（同 11-02 的后台）
static int prepare_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DM_PSO_PREPARE"); v = !(e && !strcmp(e, "0")); }
    return v;
}
static int prepare_workers(void) {
    const char *e = getenv("DM_PSO_PREPARE_THREADS"); int n = e ? atoi(e) : 0;
    if (n <= 0) { size_t sz = sizeof n; if (sysctlbyname("hw.activecpu", &n, &sz, NULL, 0) || n < 2) n = 2; }
    return n;
}
// The first submission waits for the whole list (S2Arm 10-30, 维护者: the loading page shows the progress, nvn_warm.h), no longer at most 15 s. It hands back to the host, the rest going on in
//   the background as before, when the player taps "play now" (s2a_warm_play_now), when no line has finished for DM_PSO_PREPARE_STALL_MS (default 20000) or after DM_PSO_PREPARE_MAX_MS
//   (default 30000 since 11-06, 维护者: 15000 since 11-05 left cold first runs half compiled; see prepare_on; it binds with a front end too; 0 = none for either). Both are set from device measurements of whole lists (Monster Hunter Rise 10-26: 17625 seed lines, 77 s in all).
//   Returns 1 when everything was built before it returned, 0 when the rest goes on in the background (warm_finish runs when they end)
static int prepare_max_ms(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_PSO_PREPARE_MAX_MS"); v = e ? atoi(e) : 30000; } return v; }   // 11-06 维护者：30 s（原 11-05 定 15 s，冷装首玩编不完；8 s 后可「先开始玩」照旧）
static int prepare_stall_ms(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_PSO_PREPARE_STALL_MS"); v = e ? atoi(e) : 20000; } return v; }
// The progress the host reads (nvn_warm.h): phase / why / total are written by the prewarm, done is g_warm_done, the rate comes from a small ring sampled by whoever reads (under g_wp_mu)
static pthread_mutex_t g_wp_mu = PTHREAD_MUTEX_INITIALIZER; static warm_ring g_wp_ring;
static double wp_sample(uint64_t now, long done) { pthread_mutex_lock(&g_wp_mu); warm_ring_add(&g_wp_ring, now, done); double r = warm_ring_rate(&g_wp_ring, now, done, WARM_RATE_WIN_NS); pthread_mutex_unlock(&g_wp_mu); return r; }
__attribute__((visibility("default"))) int s2a_warm_progress(s2a_warm_state *o) {
    if (!o) return 0;
    uint64_t now = bp_now(), t0 = atomic_load(&g_wp_t0); long done = atomic_load(&g_warm_done);
    *o = (s2a_warm_state){atomic_load(&g_wp_phase), atomic_load(&g_wp_why), atomic_load(&g_wp_total), done, 0, t0 ? (now - t0) / 1e9 : 0};
    if (o->phase == WARM_FRONT || o->phase == WARM_BG) o->rate = wp_sample(now, done);
    return 1;
}
__attribute__((visibility("default"))) void s2a_warm_play_now(void) { atomic_store(&g_wp_play, 1); }
static _Atomic long g_warm_bg_after_cap;   // 到点放行后由后台 utility 工人编的行数（单测 t_nvn_warm_cap 看）
#ifndef WARM_PREPARE_TASK
#define WARM_PREPARE_TASK warm_task   // the prepare workers' per-line call (t_nvn_warmtick.m swaps in one that holds the last line to test the tail release)
#endif
// 后台预热工人的 QoS（游戏在玩、后台编剩余管线：首帧到上限转后台那段 + 配置全后台那支）。default，不用 utility：
//   11-06 卡顿线 iPhone 旷野之息冷装同包三臂（b1fd0aa24）：2 路 utility 编完 4819 条 179.7 s、头 2 分钟 3 路 utility 4512 条 159.4 s、
//   2 路 default 5143 条 45.6 s（系统缓存命中三臂相近 1721 / 1635 / 1589）——utility 被排到能效核是慢的主因，加线程几乎不帮；
//   同停菜单同时长（约 554 s）的整局整机 3 路 utility 2.35 W / 2 路 default 2.37 W，能耗差 1% 内。首遇现建（user-initiated）仍排在它前面
#define WARM_BG_QOS QOS_CLASS_DEFAULT
static int warm_prepare(NSArray<WarmTask *> *tasks, long lines) {
    int workers = prepare_workers(); long n = (long)tasks.count; uint64_t t0 = bp_now(), lim = (uint64_t)prepare_max_ms() * 1000000ull, stall = (uint64_t)prepare_stall_ms() * 1000000ull;
    atomic_store(&g_wp_total, lines); atomic_store(&g_wp_phase, WARM_FRONT);
    __block _Atomic long next = 0; __block _Atomic int stop = 0;   // stop：到点放行后满核的准备工人不再领新行（剩下的交后台低优先，见下）
    dispatch_group_t g = dispatch_group_create();
    for (int w = 0; w < workers; w++) dispatch_group_async(g, dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        for (;;) { if (atomic_load(&stop)) break; long i = warm_pick(&next, n); if (i < 0 || dm_gfx_session_stopping()) break; WARM_PREPARE_TASK(tasks[(NSUInteger)i]); }
    });
    int shown = 0, late = 0; long seen = -1; uint64_t moved = t0;
    int front = s2a_front_warm_tick(0, lines) >= 0;   // a front end decides when to stop waiting (it was told the total); else this file's guards
    while (dispatch_group_wait(g, dispatch_time(DISPATCH_TIME_NOW, 50 * (int64_t)NSEC_PER_MSEC))) {
        uint64_t now = bp_now(), el = now - t0; long done = g_warm_done; double rest = done ? (double)el * (double)(lines - done) / (double)done : 1e18;
        if (done != seen) { seen = done; moved = now; }
        wp_sample(now, done);   // the rate window keeps moving while nobody reads
        int why;
        if (front) why = s2a_front_warm_tick(done, lines) == 1 || atomic_load(&g_wp_play) ? WARM_WHY_PLAYER : WARM_WHY_NONE;   // the front end owns the page, its estimate and its guards
        else why = warm_hold_why(el, now - moved, atomic_load(&g_wp_play), lim, stall);
        if (!why && lim && el >= lim) why = WARM_WHY_LIMIT;   // 11-05：上限对前端同样生效——到点必放行进局，前端不能延长（维护者 判据 ≤ 15 s）
        // 11-06（异度3 测试设备1 再启动局：归档 2048 / 2048 全命中，首帧仍等满 15 s，12523 行剩 26 行）：清单每一行都已有工人领走、只剩在编的几条时不再挡首帧——
        //   再等也不会让任何一条更早开编；游戏真用到其中一条时，首遇路径按同键等那一条在编的（不重编），用不到的不该拖住进局。在编的照常在满核工人上编完
        if (!why && atomic_load(&next) >= n) why = WARM_WHY_TAIL;
        if (why) { late = why; break; }
        if (!shown && el >= 500000000ull && rest >= 3e8) { shown = 1; MLOG("pipeline prepare: %ld of %ld lines done after %.1f s (estimate %.1f s more)", done, lines, el / 1e9, rest / 1e9); }
    }
    if (late) {
        atomic_store(&stop, 1);   // 满核的准备工人做完手上这行就退；剩下的从同一位置交给后台 DM_PSO_BG_THREADS 路 WARM_BG_QOS（11-02 怪猎发热：别让满核 user-initiated 一直编下去）
        { const char *e = getenv("DM_PSO_BG_THREADS"); int bw = e && atoi(e) > 0 ? atoi(e) : 2; workers = bw;
          for (int w = 0; w < bw; w++) dispatch_group_async(g, dispatch_get_global_queue(WARM_BG_QOS, 0), ^{
              for (;;) { long i = warm_pick(&next, n); if (i < 0 || dm_gfx_session_stopping()) break; atomic_fetch_add(&g_warm_bg_after_cap, 1); warm_task(tasks[(NSUInteger)i]); }
          }); }
        atomic_store(&g_wp_why, late); atomic_store(&g_wp_phase, WARM_BG);
        MLOG("pipeline prepare: the first frame waited %.0f ms (%s); %ld of %ld lines done, the rest goes on in the background on %d workers", (bp_now() - t0) / 1e6,
             late == WARM_WHY_PLAYER ? "the player chose to play now" : late == WARM_WHY_STALL ? "no line finished for DM_PSO_PREPARE_STALL_MS" :
             late == WARM_WHY_TAIL ? "every line taken, only the ones being built left; they finish on the prepare workers" : "the cap, DM_PSO_PREPARE_MAX_MS",
             (long)g_warm_done, lines, workers);
        if (front) s2a_front_warm_released();
        { long left = lines - (long)g_warm_done; pthread_mutex_lock(&g_fe_mu); fe_bg_begin(&g_fe, left > 0 ? (uint64_t)left : 0, bp_now()); pthread_mutex_unlock(&g_fe_mu); }   // fe_stat.h ②
        dispatch_group_notify(g, dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{ pthread_mutex_lock(&g_fe_mu); fe_bg_end(&g_fe, bp_now()); pthread_mutex_unlock(&g_fe_mu); warm_finish(); });
        return 0;
    }
    MLOG("pipeline prepare: %ld lines (%llu shaders, %llu render pipelines, %llu compute pipelines) in %.2f s on %d workers before the first frame (the first frame waited %.0f ms)%s",
         lines, (unsigned long long)g_warm_shaders, (unsigned long long)g_warm_rps, (unsigned long long)g_warm_cps, (bp_now() - t0) / 1e9, workers, (bp_now() - t0) / 1e6, shown ? ", a long wait" : "");
    return 1;
}
// The prewarm lists: DM_PSO_MANIFEST (off = none), else the package's seed beside the shader map plus this device's user list when it exists. nil = none. say: log why
static NSArray<NSString *> *warm_paths(int say) {
    const char *e = getenv("DM_PSO_MANIFEST");
    if (e && !strcmp(e, "off")) return nil;
    if (e && *e) return @[@(e)];
    NSString *seed = [shmap_path().stringByDeletingLastPathComponent stringByAppendingPathComponent:@"pso_manifest.tsv"];
    NSMutableArray<NSString *> *all = [NSMutableArray arrayWithObject:seed];
    NSString *user = pso_user_path();
    if (user && [NSFileManager.defaultManager fileExistsAtPath:user]) [all addObject:user];
    else if (say) MLOG("pipeline prewarm: this device's user list %s%s", user ? "does not exist yet: " : "has no path (neither DM_PSO_USER nor DM_SAVE is set)", user ? user.UTF8String : "");
    if (![NSFileManager.defaultManager fileExistsAtPath:seed]) { if (say) MLOG("【红】 pipeline prewarm: seed list does not exist: %s", seed.UTF8String); return nil; }
    return all;
}
// Tell the front end at once that the first frame will wait for the prewarm (10-30 device line, Monster Hunter Rise cold start mhrise_1030172905_1: the game's first present, 0.96 s, came
//   before its first submission, where the shader map loads lazily and the prewarm runs, so the loading page was taken down at that present and the 15 s prewarm showed black).
//   mtl_init runs at the game's first memory pool, before any present: (0, n) here, n = the lists' non-comment lines (an upper bound: warm_prepare drops repeats and stale keys and then
//   gives the exact total with its own (0, total)). The prewarm itself cannot move here: its pipelines need the depth mode the game sets later (nvn_be_set_depth_zero)
static void warm_announce(void) {
    if (!prepare_on()) return;
    NSArray<NSString *> *paths = warm_paths(0); long n = 0;
    for (NSString *path in paths) { NSString *txt = [NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:nil];
        for (NSString *l in [txt componentsSeparatedByString:@"\n"]) n += l.length && ![l hasPrefix:@"#"]; }
    if (n <= 0) return;
    int r = s2a_front_warm_tick(0, n);
    MLOG("pipeline prepare: announced before the first frame (%ld list lines; front end %s)", n, r < 0 ? "absent" : "told");
}
static void warm_start(void) {
    if (g_warm_started++) return;
    NSArray<NSString *> *paths = warm_paths(1);
    if (!paths) return;
    if (!g_warm_items) g_warm_items = [NSMutableArray array];
    g_warm_t0 = bp_now(); atomic_store(&g_wp_t0, g_warm_t0);
    atomic_store(&g_warm_running, 1);
    if (prepare_on()) {
        long lines = 0; NSArray<WarmTask *> *tasks = warm_parse(paths, &lines); warm_urgent_index(tasks);
        if (!lines) { MLOG("pipeline prepare: the prewarm lists hold nothing to build"); warm_finish(); }
        else if (warm_prepare(tasks, lines)) warm_finish();
        return;
    }
    // warm_bg: DM_PSO_BG_THREADS workers (default 2) at WARM_BG_QOS while the game plays: first uses (pso_pend, user-initiated) go ahead of them at the compiler service, and two
    //   workers keep the compile load off the cores the game and the system need (six at user-initiated were the heat above)
    dispatch_async(dispatch_get_global_queue(WARM_BG_QOS, 0), ^{ @autoreleasepool { long lines = 0; NSArray<WarmTask *> *ts = warm_parse(paths, &lines); warm_urgent_index(ts);
        atomic_store(&g_wp_total, lines); atomic_store(&g_wp_why, WARM_WHY_CONFIG); atomic_store(&g_wp_phase, WARM_BG);
        const char *e = getenv("DM_PSO_BG_THREADS"); int workers = e && atoi(e) > 0 ? atoi(e) : 2; long n = (long)ts.count;
        MLOG("pipeline prewarm: %ld lines in the background on %d workers at default QoS, the game does not wait for it", lines, workers);
        __block _Atomic long next = 0; dispatch_group_t g = dispatch_group_create();
        for (int w = 0; w < workers; w++) dispatch_group_async(g, dispatch_get_global_queue(WARM_BG_QOS, 0), ^{
            for (;;) { long i = warm_pick(&next, n); if (i < 0 || dm_gfx_session_stopping()) break; warm_task(ts[(NSUInteger)i]); }
        });
        dispatch_group_notify(g, dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{ warm_finish(); }); } });
}
// S2Arm pso harvest (S2A_PSO_HARVEST=<folder>, Mac only, shader line 10-26): the pack builds the package's pipeline archives without running the game ("no trial run at pack
//   time"): initialize Metal, load the shader map and the package's seed list (DM_NVN_SHMAP / DM_MSL_DIR as for a run), set the game's depth mode, run the prepare step on every
//   core and write each pipeline it builds into <folder> at once (pso_archive.h, the same keys the device looks up), then return. The depth mode decides every vertex entry
//   (nvn_be_set_depth_zero), and only the game sets it: DM_PSO_HARVEST_DEPTH=zero (near = 0) or gl must be given, a guess would make archives that never hit.
//   The shader line turns the archives into the target GPU's (metal-tt) and ships them in shaders/direct/pipelines/ (par_bundle_for). Returns 0, or 1 with the reason logged
int nvn_pso_harvest(const char *dir) {
    const char *dm = getenv("DM_PSO_HARVEST_DEPTH");
    if (!dm || (strcmp(dm, "zero") && strcmp(dm, "gl"))) { MLOG("【红】 pipeline harvest: DM_PSO_HARVEST_DEPTH must be zero or gl (the game's nvnDeviceSetDepthMode decides every vertex entry)"); return 1; }
    // The package's shader map and libraries: a run sets them at the game's first nvnBootstrapLoader (host_adapt.m direct_paths); no game runs here, so the same paths from S2A_GAME_DATA
    { const char *gd = getenv("S2A_GAME_DATA"); char p[1300];
      if (gd && *gd) { snprintf(p, sizeof p, "%s/shaders/direct", gd); setenv("DM_MSL_DIR", p, 0); snprintf(p, sizeof p, "%s/shaders/direct/shader_map.tsv", gd); setenv("DM_NVN_SHMAP", p, 0); }
      if (!getenv("DM_NVN_SHMAP") || !getenv("DM_MSL_DIR")) { MLOG("【红】 pipeline harvest: give S2A_GAME_DATA (the package folder), or DM_NVN_SHMAP and DM_MSL_DIR"); return 1; } }
    [NSFileManager.defaultManager createDirectoryAtPath:@(dir) withIntermediateDirectories:YES attributes:nil error:nil];
    g_par_harvest = dir; setenv("DM_PSO_PREPARE", "1", 1); setenv("DM_PSO_PREPARE_MAX_MS", "0", 1); unsetenv("DM_PSO_USER"); unsetenv("DM_SAVE");   // the package's seed list only
    mtl_init();
    nvn_be_set_depth_zero(!strcmp(dm, "zero"));
    uint64_t t0 = bp_now();
    shmap_load();   // ends with warm_start: the prepare step, waiting for every line
    while (atomic_load(&g_warm_running)) usleep(10000);
    MLOG("pipeline harvest into %s: depth mode %s, %llu written, %llu failed to write, %.1f s", dir, dm, (unsigned long long)atomic_load(&g_par_written), (unsigned long long)atomic_load(&g_par_write_failed), (bp_now() - t0) / 1e9);
    return atomic_load(&g_par_written) ? 0 : 1;
}
static id<MTLDepthStencilState> dss_get(int has_depth, int has_stencil) {
    struct { ds_st ds; uint32_t vm[2], wm[2]; int hd, hs; } k;
    memset(&k, 0, sizeof k); k.ds = S.ds; memcpy(k.vm, S.st_vmask, 8); memcpy(k.wm, S.st_wmask, 8); k.hd = has_depth; k.hs = has_stencil;
    if (!g_dss.klen) g_dss.klen = sizeof k;
    id<MTLDepthStencilState> s = hm_get_id(&g_dss, &k);
    if (s) return s;
    MTLDepthStencilDescriptor *d = [MTLDepthStencilDescriptor new];
    if (has_depth && S.ds.dt) { d.depthCompareFunction = (MTLCompareFunction)(S.ds.df - 1); d.depthWriteEnabled = S.ds.dw; }
    if (has_stencil && S.ds.st) {
        MTLStencilDescriptor *f = [MTLStencilDescriptor new], *b = [MTLStencilDescriptor new];
        f.stencilCompareFunction = (MTLCompareFunction)(S.ds.sf_f - 1); f.stencilFailureOperation = (MTLStencilOperation)(S.ds.fail_f - 1);
        f.depthFailureOperation = (MTLStencilOperation)(S.ds.zfail_f - 1); f.depthStencilPassOperation = (MTLStencilOperation)(S.ds.zpass_f - 1);
        f.readMask = S.st_vmask[0]; f.writeMask = S.st_wmask[0];
        b.stencilCompareFunction = (MTLCompareFunction)(S.ds.sf_b - 1); b.stencilFailureOperation = (MTLStencilOperation)(S.ds.fail_b - 1);
        b.depthFailureOperation = (MTLStencilOperation)(S.ds.zfail_b - 1); b.depthStencilPassOperation = (MTLStencilOperation)(S.ds.zpass_b - 1);
        b.readMask = S.st_vmask[1]; b.writeMask = S.st_wmask[1];
        d.frontFaceStencil = f; d.backFaceStencil = b;
    }
    s = [g_dev newDepthStencilStateWithDescriptor:d];
    hm_put_id(&g_dss, &k, s);
    return s;
}
// Argument buffer: filled item by item per the B reflection (uniform slot r, separate texture / sampler slot r, storage buffer slot r, driver segments c0 / c2, c1, support_buffer)
// Unbound resources read 0: give all-zero dummy resources (NVN descriptors 0..255 are reserved for the driver; the game binding handle 0 means 'this slot is empty')
static uint64_t g_dummy_tbuf_rid[4];
static id<MTLTexture> dummy_tex(int dtt, int dpf) {
    static __strong id<MTLTexture> cache[16][4];
    MTLTextureType tt = (MTLTextureType)dtt;
    MTLPixelFormat pf = dpf == NVN_DPF_DEPTH ? MTLPixelFormatDepth32Float : dpf == NVN_DPF_UINT ? MTLPixelFormatRGBA32Uint : dpf == NVN_DPF_SINT ? MTLPixelFormatRGBA32Sint : MTLPixelFormatRGBA8Unorm;
    id<MTLTexture> t = cache[dtt & 15][dpf & 3];
    if (t) return t;
    MTLTextureDescriptor *d = [MTLTextureDescriptor new];
    int ms = tt == MTLTextureType2DMultisample || tt == MTLTextureType2DMultisampleArray;
    d.textureType = tt; d.pixelFormat = pf; d.width = d.height = d.depth = 1; d.storageMode = MTLStorageModeShared; d.usage = MTLTextureUsageShaderRead;
    if (ms) { d.sampleCount = 4; d.storageMode = MTLStorageModePrivate; }   // a multisample texture cannot be shared: private, which the system hands out zero-filled like any new allocation
    t = [g_dev newTextureWithDescriptor:d];   // Shared storage is all zeros when newly created
    if (pf != MTLPixelFormatDepth32Float && !ms) { uint8_t z[64] = {0}; NSUInteger faces = tt == MTLTextureTypeCube || tt == MTLTextureTypeCubeArray ? 6 : 1;
        for (NSUInteger f = 0; f < faces; f++) [t replaceRegion:MTLRegionMake3D(0, 0, 0, 1, 1, 1) mipmapLevel:0 slice:f withBytes:z bytesPerRow:16 bytesPerImage:16]; }
    cache[dtt & 15][dpf & 3] = t; g_dummy_tex_rid[dtt & 15][dpf & 3] = t.gpuResourceID._impl; res_add(t);
    return t;
}
// Write sink for unbound image slots: kept separate from the dummy textures that read 0 (writes must not pollute them); one is shared per same type and same pixel class
static id<MTLTexture> dummy_img(int dtt, int dpf, int native_atomic) {
    static __strong id<MTLTexture> cache[16][4][2];
    id<MTLTexture> t = cache[dtt & 15][dpf & 3][!!native_atomic]; if (t) return t;
    MTLTextureDescriptor *d = [MTLTextureDescriptor new];
    d.textureType = (MTLTextureType)dtt;
    d.pixelFormat = dpf == NVN_DPF_UINT ? (native_atomic ? MTLPixelFormatR32Uint : MTLPixelFormatRGBA32Uint)
                 : dpf == NVN_DPF_SINT ? (native_atomic ? MTLPixelFormatR32Sint : MTLPixelFormatRGBA32Sint) : MTLPixelFormatRGBA16Float;
    d.width = d.height = d.depth = 1; d.storageMode = MTLStorageModePrivate; d.usage = MTLTextureUsageShaderRead | MTLTextureUsageShaderWrite;
    if (native_atomic) d.usage |= MTLTextureUsageShaderAtomic;
    if (dtt == MTLTextureTypeTextureBuffer) {
        id<MTLBuffer> b = [g_dev newBufferWithLength:256 options:MTLResourceStorageModeShared];
        d.storageMode = MTLStorageModeShared;
        t = [b newTextureWithDescriptor:d offset:0 bytesPerRow:256]; res_add(b);
    } else t = [g_dev newTextureWithDescriptor:d];
    if (native_atomic && t) tex_note_atomic(t);
    cache[dtt & 15][dpf & 3][!!native_atomic] = t; res_add(t); return t;
}
static id<MTLBuffer> dummy_buf(void);
static id<MTLTexture> dummy_tbuf(int dpf) {   // Unbound typed buffer: all zeros (pixel class matches the shader's texture_buffer<T>)
    static __strong id<MTLTexture> cache[4];
    id<MTLTexture> t = cache[dpf & 3]; if (t) return t;
    MTLPixelFormat pf = dpf == NVN_DPF_UINT ? MTLPixelFormatRGBA32Uint : dpf == NVN_DPF_SINT ? MTLPixelFormatRGBA32Sint : MTLPixelFormatRGBA32Float;
    id<MTLBuffer> b = dummy_buf();
    MTLTextureDescriptor *d = [MTLTextureDescriptor textureBufferDescriptorWithPixelFormat:pf width:b.length / 16 resourceOptions:b.resourceOptions usage:MTLTextureUsageShaderRead];
    t = [b newTextureWithDescriptor:d offset:0 bytesPerRow:b.length];
    cache[dpf & 3] = t; g_dummy_tbuf_rid[dpf & 3] = t.gpuResourceID._impl; return t;
}
static id<MTLSamplerState> dummy_samp(void) {
    static id<MTLSamplerState> s; if (!s) { MTLSamplerDescriptor *d = [MTLSamplerDescriptor new]; d.supportArgumentBuffers = YES; s = [g_dev newSamplerStateWithDescriptor:d]; }
    return s;
}
static uint64_t dummy_samp_rid(void) { static uint64_t rid; if (!rid) rid = dummy_samp().gpuResourceID._impl; return rid; }
static id<MTLBuffer> dummy_buf(void) { static id<MTLBuffer> b; if (!b) { b = [g_dev newBufferWithLength:64 << 10 options:MTLResourceStorageModeShared]; res_add(b); } return b; }
static uint64_t dummy_buf_gpu(void) { static uint64_t gpu; if (!gpu) gpu = dummy_buf().gpuAddress; return gpu; }
// ---------- Texture / sampler pools for handles traced to no slot (nvn_refl.h TEXP / SAMPP, Dsh.cs PoolArrays) ----------
// Upstream reference implementation (MIT) the reference port nvn_mtl.m pool_gpu / pool_seen_scan (cf3ec563, b1d7c707, 6121fd75) for what a table holds; how it is kept is this host's own (11-06, below).
// A shader that reads a texture handle from game memory names a texture by its ID in the pool bound at the draw. The translator used to declare a 32-entry array, index min(ID, 31), and
// the host bound slot k at element k: a handle naming ID 32 or above (nearly all of them) read some other texture (11-06 Ocarina of Time: 4,454 shaders, one sampled was a shadow's depth
// compare). Now a table per element type and pool base: the bound n (DMSH_POOL_HEAD bytes of head), then the resource ID of each ID of the pool (base = S.tex_base / S.samp_base, as
// ubo_tex_id adds), the dummy where an ID holds nothing or a texture of another type, and the dummy at n for IDs past the table.
// A table is walked once, when its key is first asked for, and from then on kept entry by entry, in place: an ID registered, dropped or given another texture (pool_dirty, from the
//   registration paths), an object a table names leaving the residency set (pool_pin_retire, from res_remove: a replaced, upgraded, overwritten or finalized texture), an ID a shader
//   read for the first time or whose CPU-written texture may have been re-uploaded (pool_seen_scan), and the small textures the budget left out (pool_left_scan, once a frame). Upstream
//   walked every ID again on any registration or texture change, and one of them in 2 ms of walks a submission; on an iPhone a walk of Ocarina of Time's 33,024 IDs takes 2–4 ms, so
//   tables stood stale into later submissions naming freed textures (GPU address faults ~4,500 frames in), and walking every changed table every submission took the game to 20 fps
//   and ran the low address space out (11-06 builds 38 / 40 / 42).
// What a table names stays alive and resident until the submissions that may read it have completed, whoever else lets it go: the table retains each object (obj), and each of its
//   allocations (the texture, its root texture, a texture buffer's buffer, an atomic view's storage) is pinned: res_remove of a pinned allocation leaves it resident and only notes it,
//   the next pool_gpu looks its entries up again, and the allocation leaves (defer_obj_release, behind this submission) once no entry names it. An entry it replaces is unref'd behind
//   this submission (defer_obj_unref): a draw already encoded may still read it. The buffer stays; past its room a larger one takes over and the old one leaves behind this submission.
// Caller holds g_rmu
#define POOL_TABS 16
typedef struct {
    __strong id<MTLBuffer> buf; uint64_t gpu, dummy; uint32_t cap, n;   // n IDs from base (entry n the dummy); cap: entries the buffer has room for
    int used, samp, dtt, dpf, base;
    void **obj;   // per entry: the object it names, retained by the table; NULL: the dummy
} pool_tab;
static pool_tab g_ptab[POOL_TABS]; static unsigned g_ptab_next; static _Atomic int g_ptab_any;
static uint64_t g_psnap_gen = 1;   // bumped when a table's address changes (made, grown, dropped): an argument block holding a pool address is not reused past it (encode_args_ ab_pgen)
// Counters (t_nvn_pool_tex reads them): whole walks, buffers made, entries looked up again by cause
static uint64_t g_pool_walks, g_pool_made, g_pool_upd_dirty, g_pool_upd_ret, g_pool_upd_seen, g_pool_upd_left, g_pool_calls; static double g_pool_ms, g_pool_walk_ms;
// Whether a registered texture's storage still exists before a walk makes a texture no draw has bound: a game leaves IDs registered after it is done with their textures, and upstream's
// first pool walk crashed on a finalized pool's garbage storage (its GitHub issue #934). So: not marked gone (its pool was finalized, treg_drop_pool_views), the pool object is live
// (nvnMemoryPoolFinalize clears the magic) and an ordinary pool's storage lies in a pool the host maps (otherwise the upload would read the guest address on the CPU)
static int tex_storage_live(const treg_t *r) {
    const tex_t *t = &r->t; const pool_t *p = t->pool;
    if (r->gone || (p && p->magic != MAGIC('P', 'O', 'O', 'L'))) return 0;
    if (p && nvn_sparse_pool(p)) return 1;
    if (!t->mem) return 0;
    pthread_mutex_lock(&g_mu); int ok = pool_find((uint64_t)(uintptr_t)t->mem, t->L.size ? t->L.size : 1) >= 0; pthread_mutex_unlock(&g_mu);
    return ok;
}
// A handle read from game memory may name any registered texture, and on the console that costs nothing: the data is in the pool and a handle is a number. Here each is a Metal texture beside
// the pool's copy, and making them all took Ocarina of Time past Metal's working set on a 16 GB Mac (upstream: 12.1 GB, once a kernel panic at 14.7 GB wired). Shaders read few of them:
// a shader's read sets the ID's bit (pool_seen) and those are made whatever the budget, up to POOL_REQ_BYTES a frame (a budget without this left out exactly the large textures those
// shaders read: scenery in shadow near black, upstream). The smallest textures are made up front, POOL_FRAME_BYTES a frame up to a twentieth of the working set, as a pass that
// runs once (a bake) has no second frame to find its texture in. A read of the rest finds the dummy until the next submission folds its bit
enum { POOL_FRAME_BYTES = 32u << 20, POOL_REQ_BYTES = 128u << 20 };
static uint64_t g_walk_frame = ~0ull, g_walk_spent, g_walk_req;
static uint64_t pool_tex_size(const tex_t *t) { return t->L.size ? t->L.size : 1; }
static uint64_t pool_budget(void) { return g_dev.recommendedMaxWorkingSetSize / 20; }
static void pool_walk_frame(void) { uint64_t f = atomic_load(&g_cur_frame); if (f != g_walk_frame) { g_walk_frame = f; g_walk_spent = 0; g_walk_req = 0; } }
static uint64_t pool_room(void) {   // what may still be made up front this frame
    pool_walk_frame();
    uint64_t want = pool_budget(), have = g_dev.currentAllocatedSize, room = have < want ? want - have : 0;
    uint64_t left = g_walk_spent < POOL_FRAME_BYTES ? POOL_FRAME_BYTES - g_walk_spent : 0;
    return room < left ? room : left;
}
// A render target no pass has written holds nothing to read, and a pass makes its texture when it renders. Made for a read, one that only registers next frame's target took three times the
// textures and 17 GB allocated on Ocarina of Time (upstream): the game re-registers its IDs with transient targets, whose IDs a shader read as the previous texture
//   "No pass has written" is about the storage, not the object: an NVN texture object is a description, its content is the memory. A game that draws through one object and registers
//   another over the same storage for its shaders (the same description but for use flags such as COMPRESSIBLE: the sharing table's key, alias_key_of) reads what the first drew; judged by
//   the second object's own serial it read the dummy for good, however much the first drew. A shared texture already made over that storage and description means it is not unwritten
static int pool_unwritten_target(const tex_t *t) {   // caller holds g_rmu (g_smu is taken after it, as everywhere)
    if (!(t->d.flags & NVN_TEXTURE_FLAGS_COMPRESSIBLE) || !t->serial || tex_get(t->serial)) return 0;
    alias_key ak; alias_key_of(&ak, t);
    pthread_mutex_lock(&g_smu); int shared = nvn_hm_get(&g_alias, &ak) != NULL; pthread_mutex_unlock(&g_smu);
    if (shared) { static int n; if (n++ < 8) MLOG("texture pool: render target ser=%llu %ux%u format %#x has no host texture of its own, but its storage was drawn through another object: read as that texture (previously the dummy, reading 0; case %d)",
                                               (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format, n); }
    return !shared;
}
static int pool_size_cmp(const void *a, const void *b) { uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b; return x < y ? -1 : x > y; }
static int pool_unmade(int id_) { return id_ > 0 && id_ < g_ntreg && g_treg[id_].ok && !g_treg[id_].gone && !g_treg[id_].view && !tex_get(g_treg[id_].t.serial); }
// The largest texture these IDs may make: this frame's room, spent from the smallest up. UINT64_MAX while they all fit. ids NULL: base .. base + n - 1
static uint64_t pool_walk_limit(int base, int n, const uint32_t *ids) {
    uint64_t room = pool_room(), sum = 0;
    if (!room) return 0;   // no need to size a walk that can make nothing
    uint64_t *z = malloc(sizeof *z * (size_t)(n ? n : 1)); int m = 0;
    if (!z) return 0;
    for (int i = 0; i < n; i++) { int id_ = ids ? (int)ids[i] : base + i; if (pool_unmade(id_)) { z[m] = pool_tex_size(&g_treg[id_].t); sum += z[m]; m++; } }
    uint64_t limit = UINT64_MAX;
    if (sum > room) {
        qsort(z, (size_t)m, sizeof *z, pool_size_cmp);
        limit = 0; sum = 0;
        for (int i = 0; i < m && sum + z[i] <= room; i++) { sum += z[i]; limit = z[i]; }
    }
    free(z);
    return limit;
}
static uint64_t pool_seen_gpu(void) {
    if (!g_seen_buf) { g_seen_buf = [g_dev newBufferWithLength:POOL_SEEN_WORDS * 4 options:MTLResourceStorageModeShared]; res_add(g_seen_buf); res_commit(); }
    return g_seen_buf.gpuAddress;
}
// ----- Pins: allocation → the entries naming it (entry code: table << 20 | index), and the pinned allocations res_remove was asked to retire. Under g_pin_mu, which res_remove takes
//   inside g_res_mu: nothing here calls res_add / res_remove / defer_* with it held
typedef struct { uint32_t n, cap; uint32_t e[]; } pin_list;
static pthread_mutex_t g_pin_mu = PTHREAD_MUTEX_INITIALIZER;
static nvn_hmap g_pin = {.klen = 8}, g_pin_ret = {.klen = 8};
static void **g_pin_new; static uint32_t g_pin_nnew, g_pin_cnew;   // retired while pinned since the last pool_gpu
static int pool_pin_keys(void *o, void *k[4]) {   // the allocations a table entry naming o keeps (always the same for the same object: a view's parent and buffer never change)
    int n = 0; k[n++] = o;
    id x = (__bridge id)o;
    if (![x conformsToProtocol:@protocol(MTLTexture)]) return n;
    id<MTLTexture> t = (id<MTLTexture>)x; while (t.parentTexture) t = t.parentTexture;
    if ((__bridge void *)t != o) k[n++] = (__bridge void *)t;
    if (t.buffer) k[n++] = (__bridge void *)t.buffer;
    id root = objc_getAssociatedObject(x, &g_atomic_root_key); if (root) k[n++] = (__bridge void *)root;
    return n;
}
static void pin_add(void *k, uint32_t code) {
    pthread_mutex_lock(&g_pin_mu);
    pin_list *l = nvn_hm_get(&g_pin, &k);
    if (!l || l->n == l->cap) { uint32_t c = l ? l->cap * 2 : 4; pin_list *g = realloc(l, sizeof *g + c * sizeof g->e[0]); if (!g) MDIE("pool pins: out of memory"); if (!l) g->n = 0; g->cap = c; l = g; nvn_hm_put(&g_pin, &k, l); }
    l->e[l->n++] = code;
    pthread_mutex_unlock(&g_pin_mu);
}
static int pin_del(void *k, uint32_t code) {   // 1: no entry names k any more and res_remove was asked to retire it while pinned (the caller retires it now)
    int ret = 0;
    pthread_mutex_lock(&g_pin_mu);
    pin_list *l = nvn_hm_get(&g_pin, &k);
    if (l) { for (uint32_t j = 0; j < l->n; j++) if (l->e[j] == code) { l->e[j] = l->e[--l->n]; break; }
        if (!l->n) { nvn_hm_del(&g_pin, &k); free(l); ret = nvn_hm_del(&g_pin_ret, &k) != NULL; } }
    pthread_mutex_unlock(&g_pin_mu);
    return ret;
}
static int pool_pin_retire(void *r) {   // res_remove (g_res_mu held): 1 = pinned, stays resident
    if (!atomic_load_explicit(&g_ptab_any, memory_order_relaxed)) return 0;
    pthread_mutex_lock(&g_pin_mu);
    int pinned = g_pin.n && nvn_hm_get(&g_pin, &r) != NULL;
    if (pinned && !nvn_hm_get(&g_pin_ret, &r)) {
        nvn_hm_put(&g_pin_ret, &r, (void *)1);
        if (g_pin_nnew == g_pin_cnew) { uint32_t c = g_pin_cnew ? g_pin_cnew * 2 : 64; void **g = realloc(g_pin_new, c * sizeof *g); if (!g) MDIE("pool pins: out of memory"); g_pin_new = g; g_pin_cnew = c; }
        g_pin_new[g_pin_nnew++] = r;
    }
    pthread_mutex_unlock(&g_pin_mu);
    return pinned;
}
// Entry i of table ti names o (NULL: the dummy)
static void pool_ent_put(int ti, uint32_t i, void *o, uint64_t rid) {
    pool_tab *t = &g_ptab[ti]; void *old = t->obj[i];
    ((uint64_t *)((uint8_t *)t->buf.contents + DMSH_POOL_HEAD))[i] = o ? rid : t->dummy;
    if (old == o) return;
    uint32_t code = (uint32_t)ti << 20 | i; void *k[4]; int nk;
    if (o) { CFRetain(o); nk = pool_pin_keys(o, k); for (int j = 0; j < nk; j++) pin_add(k[j], code); }
    t->obj[i] = o;
    if (old) { nk = pool_pin_keys(old, k); for (int j = 0; j < nk; j++) if (pin_del(k[j], code)) defer_obj_release((__bridge id)k[j]);
        defer_obj_unref((__bridge id)old); CFRelease(old); }
}
// ----- What an ID names
static int pool_covers(const pool_tab *t, int id_) { return t->used && id_ >= t->base && (uint32_t)(id_ - t->base) < t->n; }
// The texture ID id_ names, made if the budget allows (limit: the largest texture made up front; a texture a shader read is made up to POOL_REQ_BYTES a frame). NULL: the dummy;
//   *left: registered and left out by the budget (pool_left_scan makes it later)
static void *pool_tex_obj(int id_, uint64_t limit, int *left, uint64_t *rid) {
    *left = 0;
    if (id_ <= 0 || id_ >= g_ntreg || !g_treg[id_].ok) return NULL;
    treg_t *r = &g_treg[id_];
    if (!r->view && (!tex_storage_live(r) || pool_unwritten_target(&r->t))) return NULL;   // a target: the dummy until a pass writes it (a shader's read keeps it waiting, pool_seen_scan)
    int made = r->view || tex_get(r->t.serial);
    if (!made && pool_tex_size(&r->t) > limit && !(pool_seen(id_) && g_walk_req < POOL_REQ_BYTES)) { *left = 1; return NULL; }
    void *tv = NULL; uint64_t tr = tex_fast_rid(id_, &tv);
    if (!made && tv) { g_walk_spent += pool_tex_size(&r->t); if (pool_seen(id_)) g_walk_req += pool_tex_size(&r->t); }
    if (!tv || !tr) return NULL;
    r->tt1 = (uint8_t)((__bridge id<MTLTexture>)tv).textureType + 1;
    *rid = tr; return tv;
}
static void *pool_samp_obj(int id_, uint64_t *rid) {
    if (id_ <= 0 || id_ >= g_nsreg || !g_sreg_ok[id_]) return NULL;
    void *s = samp_fast(id_); if (!s) return NULL;
    *rid = ((__bridge id<MTLSamplerState>)s).gpuResourceID._impl; return s;
}
// Looks texture ID id_ up again for every table it lies in. Returns 1 if it was left out by the budget
static int pool_tex_update(int id_, uint64_t limit) {
    int any = 0, want = 0; uint8_t tt1 = id_ > 0 && id_ < g_ntreg && g_treg[id_].ok ? g_treg[id_].tt1 : 0;
    for (int k = 0; k < POOL_TABS; k++) { const pool_tab *t = &g_ptab[k]; if (!t->samp && pool_covers(t, id_)) { any = 1; want |= !tt1 || tt1 - 1 == t->dtt; } }
    if (!any) return 0;
    int left = 0; uint64_t rid = 0; void *o = want ? pool_tex_obj(id_, limit, &left, &rid) : NULL;   // an ID of a type no table holds: nothing to look up or make
    int tt = o ? (int)((__bridge id<MTLTexture>)o).textureType : -1;
    for (int k = 0; k < POOL_TABS; k++) { const pool_tab *t = &g_ptab[k]; if (!t->samp && pool_covers(t, id_)) pool_ent_put(k, (uint32_t)(id_ - t->base), tt == t->dtt ? o : NULL, rid); }
    return left;
}
static void pool_samp_update(int id_) {
    uint64_t rid = 0; void *o = NULL; int got = 0;
    for (int k = 0; k < POOL_TABS; k++) { const pool_tab *t = &g_ptab[k]; if (!t->samp || !pool_covers(t, id_)) continue;
        if (!got) { o = pool_samp_obj(id_, &rid); got = 1; } pool_ent_put(k, (uint32_t)(id_ - t->base), o, rid); }
}
// ----- What changed. Dirty IDs: registration paths mark them (under g_rmu) while a table exists; each is looked up again once at the next pool_gpu
typedef struct { uint32_t *bits, *list; uint32_t n, cap, nbits; } pool_dset;
static pool_dset g_pdirty[2], g_pleft;   // [0] texture IDs, [1] sampler IDs; g_pleft: texture IDs the budget left out
static void pool_dset_add(pool_dset *d, int id_) {
    if (id_ < 0 || id_ >= (1 << 20)) return;
    if (!d->bits) { d->bits = calloc((1u << 20) / 32, 4); if (!d->bits) MDIE("pool dirty set: out of memory"); }
    uint32_t w = (uint32_t)id_ >> 5, b = 1u << (id_ & 31); if (d->bits[w] & b) return;
    if (d->n == d->cap) { uint32_t c = d->cap ? d->cap * 2 : 256; uint32_t *g = realloc(d->list, c * sizeof *g); if (!g) MDIE("pool dirty set: out of memory"); d->list = g; d->cap = c; }
    d->bits[w] |= b; d->list[d->n++] = (uint32_t)id_;
}
static void pool_dset_clear(pool_dset *d) { for (uint32_t j = 0; j < d->n; j++) d->bits[d->list[j] >> 5] &= ~(1u << (d->list[j] & 31)); d->n = 0; }
static void pool_dirty(int samp, int id_) { if (atomic_load_explicit(&g_ptab_any, memory_order_relaxed)) pool_dset_add(&g_pdirty[samp != 0], id_); }
// At most once a submission: the bits the shaders set since go into g_seen_done, and their textures are made (up to POOL_REQ_BYTES a frame; the rest, and targets not yet written, wait in
// g_seen_todo) and put into the tables. The IDs shaders read are looked up again when a texture changed somewhere (g_ser_gen: storage swapped or taken over, a shared texture replaced
// while its old one stays alive elsewhere, a target first written) or guest memory did (a CPU-written texture is checked against guest writes only when it is looked up, tex_by_id
// view_pkg): what nothing retires or registers still reaches what shaders read within a submission. Shaders read a few hundred of the tens of thousands of IDs
static uint64_t g_seen_dirty = ~0ull, g_seen_ser = ~0ull;
static void pool_seen_scan(void) {
    if (!g_seen_buf || g_seen_sub == g_sub_serial) return;
    g_seen_sub = g_sub_serial;
    pool_walk_frame();
    const uint32_t *w = (const uint32_t *)g_seen_buf.contents; unsigned words = MIN((unsigned)g_ntreg / 32 + 1, (unsigned)POOL_SEEN_WORDS);
    uint64_t dg = nvn_dirty_now(), sg = g_ser_gen; int recheck = dg != g_seen_dirty || sg != g_seen_ser; g_seen_dirty = dg; g_seen_ser = sg;
    for (unsigned i = 0; i < words; i++) {
        uint32_t fresh = w[i] & ~g_seen_done[i];
        if (fresh) { g_seen_done[i] |= fresh; g_seen_todo[i] |= fresh; }
        for (uint32_t bits = g_seen_todo[i]; bits; bits &= bits - 1) {
            int b = __builtin_ctz(bits), id_ = (int)i * 32 + b;
            if (id_ <= 0 || id_ >= g_ntreg || !g_treg[id_].ok || (!g_treg[id_].view && !tex_storage_live(&g_treg[id_]))) { g_seen_todo[i] &= ~(1u << b); continue; }
            if (!g_treg[id_].view && pool_unwritten_target(&g_treg[id_].t)) continue;   // waits for a pass to write it
            if (!g_treg[id_].view && !tex_get(g_treg[id_].t.serial)) { if (g_walk_req >= POOL_REQ_BYTES) break; }
            g_seen_todo[i] &= ~(1u << b);
            pool_tex_update(id_, 0); g_pool_upd_seen++;
        }
        if (recheck) for (uint32_t bits = g_seen_done[i] & ~g_seen_todo[i]; bits; bits &= bits - 1) {
            int id_ = (int)i * 32 + __builtin_ctz(bits);
            if (id_ < g_ntreg && g_treg[id_].ok) { pool_tex_update(id_, 0); g_pool_upd_seen++; }
        }
    }
}
// Once a frame, while there is room: the textures the budget left out, smallest first
static uint64_t g_left_frame = ~0ull;
static void pool_left_scan(void) {
    uint64_t f = atomic_load(&g_cur_frame); if (!g_pleft.n || f == g_left_frame) return;
    g_left_frame = f;
    uint64_t limit = pool_walk_limit(0, (int)g_pleft.n, g_pleft.list); if (!limit) return;
    uint32_t *ids = malloc(g_pleft.n * sizeof *ids), m = g_pleft.n; if (!ids) return;
    memcpy(ids, g_pleft.list, m * sizeof *ids); pool_dset_clear(&g_pleft);
    for (uint32_t j = 0; j < m; j++) { g_pool_upd_left++; if (pool_tex_update((int)ids[j], limit)) pool_dset_add(&g_pleft, (int)ids[j]); }
    free(ids);
}
// ----- Tables
static void pool_tab_put_n(pool_tab *t, uint32_t n) {   // the IDs a table covers grew to n (the registration table grew): new entries the dummy until their IDs are looked up
    if (n <= t->n) return;
    if (DMSH_POOL_HEAD + 8 * ((size_t)n + 1) > t->buf.length) {   // past its room: a larger buffer takes over, the old one leaves behind this submission (a draw already encoded reads it)
        uint32_t cap = n + n / 4 + 1; size_t len = (DMSH_POOL_HEAD + 8 * (size_t)cap + 0xffff) & ~(size_t)0xffff;
        id<MTLBuffer> b = [g_dev newBufferWithLength:len options:MTLResourceStorageModeShared];
        if (!b) { RED_ONCE(173, "cannot grow a %s pool table to %u IDs: IDs past %u read the dummy", t->samp ? "sampler" : "texture", n, t->n); return; }
        res_add(b); res_commit(); g_pool_made++;
        memcpy(b.contents, t->buf.contents, DMSH_POOL_HEAD + 8 * (size_t)t->n);
        cap = (uint32_t)((len - DMSH_POOL_HEAD) / 8);   // obj holds as many entries as t->cap says (the buffer's room, rounded up to 64 KB), as pool_tab_new's calloc: sized to n + n/4 + 1 it
                                                        //   fell short of t->cap, a later growth within the room skipped the realloc and pool_ent_put read past it (11-06 第47版 SIGSEGV objc_retain 0x1f7)
        void **o = realloc(t->obj, (size_t)cap * sizeof *o); if (!o) MDIE("pool table: out of memory");
        memset(o + t->n, 0, (size_t)(cap - t->n) * sizeof *o); t->obj = o;
        defer_obj_release(t->buf); t->buf = b; t->gpu = b.gpuAddress; t->cap = cap; g_psnap_gen++;
    } else if (t->cap < n + 1) { void **o = realloc(t->obj, (size_t)(n + 1) * sizeof *o); if (!o) MDIE("pool table: out of memory"); memset(o + t->n, 0, (size_t)(n + 1 - t->n) * sizeof *o); t->obj = o; t->cap = n + 1; }
    uint64_t *e = (uint64_t *)((uint8_t *)t->buf.contents + DMSH_POOL_HEAD);
    for (uint32_t i = t->n; i <= n; i++) e[i] = t->dummy;
    t->n = n; *(uint32_t *)t->buf.contents = n;   // the bound last: a draw in flight with the old bound reads only entries it had
}
static void pool_tab_drop(int ti) {   // a key pushed out by a sixteenth other: its entries let go behind this submission
    pool_tab *t = &g_ptab[ti]; if (!t->used) return;
    for (uint32_t i = 0; i < t->n; i++) if (t->obj[i]) pool_ent_put(ti, i, NULL, 0);
