static int se_samp(const nvn_rbind *b) { return b->kind == NVN_RB_SAMP || b->kind == NVN_RB_SAMPT || b->kind == NVN_RB_SAMPI || (b->kind == NVN_RB_SAMPU && !b->n); }   // a single sampler member
