static id<MTLFunction> se_warm(NvShader *sh, int fc) {
    uint8_t st = SE_NONE;
    if (sh && (fc & SE_RD) && __atomic_compare_exchange_n(&sh->se_st, &st, SE_BUSY, 0, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) {
        uint64_t t0 = bp_now(); id<MTLFunction> f = se_packed(sh);
        if (f) se_done(sh, f, "", t0, "包内");
        else if (dm_shader_se_fresh(sh->key) && se_file_current(sh->key)) { uint8_t md[8] = {0}; char why[300] = ""; se_done(sh, se_build(sh, md, 0, NULL, why, sizeof why), why, t0, "后台编"); }
        else { __atomic_store_n(&sh->se_st, SE_NONE, __ATOMIC_RELEASE); se_signal(); }   // neither: left to its first use (se_want), which has the guest code to make it
    }
    return se_fn(sh, fc);
}
