    for (;;) {
        uint8_t st = SE_NONE;
        if (__atomic_compare_exchange_n(&sh->se_st, &st, SE_BUSY, 0, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) { se_kick(p, sh, 1); return; }   // the prewarm gave up: made here
        if (st != SE_BUSY || dm_gfx_session_stopping()) return;
        pthread_mutex_lock(&g_se_mu);
        if (__atomic_load_n(&sh->se_st, __ATOMIC_ACQUIRE) == SE_BUSY) { struct timespec dl; clock_gettime(CLOCK_REALTIME, &dl); dl.tv_nsec += 100000000; if (dl.tv_nsec >= 1000000000) { dl.tv_sec++; dl.tv_nsec -= 1000000000; }
            pthread_cond_timedwait(&g_se_cv, &g_se_mu, &dl); }   // woken by se_done / se_signal; the 100 ms bound only re-checks the session stop (a background job dropped at the stop never finishes)
        pthread_mutex_unlock(&g_se_mu);
    }
}
static int se_want(const prog_t *p, NvShader *sh, int nvn_stage) {
    int fold, fc = se_need_(sh, nvn_stage, &fold);
    if (nvn_stage >= 0 && nvn_stage < 6) g_fold_sh[nvn_stage] = NULL;
    if (!fc) return 0;
    uint8_t st = SE_NONE;
    if (__atomic_compare_exchange_n(&sh->se_st, &st, SE_BUSY, 0, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) {
        uint64_t t0 = bp_now(); id<MTLFunction> f = se_packed(sh);
        if (f && fold && !sh->se_fold) { f = nil; sh->se_fold = 0; }   // the package's variant predates folded textures: made here instead
        if (f) se_done(sh, f, "", t0, "包内"); else se_kick(p, sh, fold);   // folded: no stand-in, made here (se_fold_wait)
    }
    if (fold && !se_fn(sh, fc)) se_fold_wait(p, sh);   // being made elsewhere: wait for it
    if (!se_fn(sh, fc)) return 0;
    if (fold && sh->se_fold && nvn_stage >= 0 && nvn_stage < 6) g_fold_sh[nvn_stage] = sh;
    else if (fold) RED_ONCE(140, "shader %s reads a folded linear texture, but its sampler-emulation variant cannot (made before format 4): the texture reads 0", sh->key);
    return fc;
}
// S2Arm #800: the s2a_lb table of a pixel / compute shader (argument buffer member, NVN_RB_LB; dmsh_red.py fs_lb): one float per sampler member at its argument id, the LOD bias main0 adds
//   to each sample through it. Where the GPU ignores a sampler's bias (g_lb_emu: M3; the sampler carries none, samp_by_id) the bound sampler's lod_bias, else 0 (the sampler applies it:
//   Apple10, M4 Pro). All zero → one shared zero buffer, nothing written per draw. Caller holds g_rmu (encode_args)
static uint64_t lb_fill(NvShader *sh, int nvn_stage) {
    static id<MTLBuffer> zero; static uint64_t zero_gpu; static float q[NVN_REFL_MAXARG];
    if (!zero) { zero = [g_dev newBufferWithLength:sizeof q options:MTLResourceStorageModeShared]; res_add(zero); zero_gpu = zero.gpuAddress; }
    if (!g_lb_emu) return zero_gpu;
    int top = -1;
    for (int i = 0; i < sh->rf.nb; i++) {
        const nvn_rbind *b = &sh->rf.b[i]; if (!se_samp(b) || b->aid >= NVN_REFL_MAXARG) continue;
        int sid = bind_sid(b, nvn_stage); if (sid <= 0 || sid >= g_nsreg || !g_sreg_ok[sid] || g_sreg[sid].lod_bias == 0) continue;
        if (top < b->aid) { for (int k = top + 1; k <= b->aid; k++) q[k] = 0; top = b->aid; }
        q[b->aid] = g_sreg[sid].lod_bias;
    }
    if (top < 0) return zero_gpu;
    id<MTLBuffer> ab; size_t o = arena_alloc(sizeof q[0] * (size_t)(top + 1), &ab); memcpy((uint8_t *)ab.contents + o, q, sizeof q[0] * (size_t)(top + 1));
    return ab.gpuAddress + o;
}
// #1204 T1 bounds hardening (gal_spvx.m direct form): the two length tables the shader clamps its indices with, from this draw's bindings. Caller holds g_rmu (encode_args)
//   NVN_RB_UBOLEN (gal_ubo_len): uint[NVN uniform slot] = vec4 count of the bound buffer (rounded up, capped at 4096, the declared vec4 data[4096]); unbound 0 (the slot reads the zero bank).
//   NVN_RB_SBSZ (spvBufferSizeConstants): uint[argument id of each storage buffer member] = its bound byte size; a buffer whose size the game never gave (SBUFU: an address kept in its
//   own uniform buffer; a binding of size 0) gets UINT32_MAX & ~15, i.e. no clamp, as before hardening; an unbound one 0 (it reads the dummy buffer)
// 审计 #1534 P1-20 被动采样（只计数、不改行为）：离线翻译缺纹理类型时按 2D 翻（dmsh_xlate QuerySamplerType），运行时绑的纹理可能是别的类型 / 别的像素类。
//   每个有真纹理的 TEX / TEXU / IMG 绑定比一次：反射声明的 Metal 类型（b->dtt）对登记时的纹理类型，声明的像素类（b->dpf）对实际格式的类（深度格式按深度类；声明 float 读深度格式在 Metal 合法，不计）。
//   比的是后面 tex_fit / img_fit / tbuf_as_2d 改造之前的原样纹理；1D 取数按行读的缓冲纹理（f1d）是有意的，不计。库元数据里记了「缺类型按 2D」的槽另计一类（sh->d2d）。
//   首例每个着色器键一行（键 / 阶段 / 槽 / 声明 / 实际），全局封顶 64 行，超了只计数
static uint64_t g_p20_checked, g_p20_type, g_p20_type_d2d, g_p20_cls; static unsigned g_p20_shown;
static __attribute__((noinline, cold)) void p20_note(NvShader *sh, int st, const nvn_rbind *b, unsigned tt, unsigned pf, int tm, int cm) {
    int d2d = b->kind == NVN_RB_TEX && b->reg < 256 && (sh->d2d[b->reg >> 6] >> (b->reg & 63) & 1);
    if (tm) { g_p20_type++; if (d2d) g_p20_type_d2d++; }
    if (cm) g_p20_cls++;
    if (sh->logged & 0x100) return;
    sh->logged |= 0x100;
    if (g_p20_shown >= 64) return;
    g_p20_shown++;
    MLOG("audit #1534 P1-20 probe: shader %s stage %d %s slot %d declares Metal type %u class %u%s, bound texture is type %u, Metal format %u (class %u)%s%s",
         sh->key, st, b->kind == NVN_RB_IMG ? "image" : b->kind == NVN_RB_TEXU ? "texture handle in uniform" : "texture", (int)b->reg, (unsigned)b->dtt, (unsigned)b->dpf, d2d ? " (type unknown offline, taken as 2D)" : "",
         tt, pf, mtl_fmt_depth((MTLPixelFormat)pf) ? (unsigned)NVN_DPF_DEPTH : (unsigned)mtl_pf_dpf((MTLPixelFormat)pf), tm ? "; type differs" : "", cm ? "; class differs" : "");
}
static inline void p20_check(NvShader *sh, int st, const nvn_rbind *b, int tid, void *tv) {
    g_p20_checked++;
    unsigned tt, pf;
    if (tid >= 0 && tid < g_ntreg && g_treg[tid].view == tv) { tt = g_treg[tid].view_tt; pf = g_treg[tid].view_pf; }
    else { __unsafe_unretained id<MTLTexture> t = (__bridge id<MTLTexture>)tv; tt = (unsigned)t.textureType; pf = (unsigned)t.pixelFormat; }   // not the cached view (rare)
    int cls = mtl_fmt_depth((MTLPixelFormat)pf) ? NVN_DPF_DEPTH : mtl_pf_dpf((MTLPixelFormat)pf);
    int tm = tt != b->dtt && !(b->f1d && tt == (unsigned)MTLTextureTypeTextureBuffer), cm = b->dpf != cls && !(b->dpf == NVN_DPF_FLOAT && cls == NVN_DPF_DEPTH);
    if (__builtin_expect(tm | cm, 0)) p20_note(sh, st, b, tt, pf, tm, cm);
}
// 审计 #1534 P1-65 被动采样（只计数、不改行为）：界长表（NVN_RB_UBOLEN）按 u->size 记、封顶 4096 vec4，GPU 指针后面实际可读的字节可能更短。
//   常量读范围表（cb_ext）已证明有界的影子拷贝不查；剩下两种风险点分开计：① 宽屏改写副本（只拷了 cb_len 字节）② 绑定越过池的零拷贝缓冲末尾。
//   计数单位 = 带界长表、新建的参数表（复用上一次参数表的绘制不重算）；首例一行（不是红行：行为没变）。汇总见 audit_probe_report
static uint64_t g_p65_tables, g_p65_wd, g_p65_pool;
static __attribute__((noinline, cold)) void p65_first(NvShader *sh, int st, int k, int reg, uint64_t tb, uint64_t av) {
    static int once; if (once++) return;
    MLOG("audit #1534 P1-65 probe: first bounds table longer than the bytes behind the pointer: shader %s stage %d uniform slot %d, table %llu bytes, %llu bytes behind the pointer (%s)",
         sh->key, st, reg, (unsigned long long)tb, (unsigned long long)av, k == 1 ? "widen rewritten copy" : "past the end of the pool buffer");
}
static inline void p65_count(NvShader *sh, int st, int hit, int k, int reg, uint64_t tb, uint64_t av) {
    g_p65_tables++;
    if (__builtin_expect(!hit, 1)) return;
    if (hit & 1) g_p65_wd++;
    if (hit & 2) g_p65_pool++;
    p65_first(sh, st, k, reg, tb, av);
}
// Uniform bounds-table entry (vec4 count the shader may read): the binding's length, rounded up to a vec4, at most 4096 (Maxwell constant buffers address 64 KB),
//   and at most the whole vec4s actually behind the pointer handed to the GPU this draw (cap, bytes): the widen rewritten copy, the pool buffer's end, or a deferred-update shadow.
//   Audit #1646 P1-65: the table used to follow the binding alone, so with a shorter copy / shadow the shader's clamp let it read past it (11-07 census: 112921 widen-copy hits in one run)
static inline uint32_t ubolen_vec4_cap(const p_bind_buf *u, uint64_t cap) { uint64_t v = u->addr ? (u->size + 15) / 16 : 0; if (v > 4096) v = 4096; if (v > cap / 16) v = cap / 16; return (uint32_t)v; }
static inline uint32_t ubolen_vec4(const p_bind_buf *u) { return ubolen_vec4_cap(u, UINT64_MAX); }
typedef struct { int stage; } sbsz_ctx;
static uint32_t sbsz_bound(void *ctx, const nvn_rbind *b) {
    int nvn_stage = ((sbsz_ctx *)ctx)->stage;
    const p_bind_buf *u = b->reg < 16 ? (b->kind == NVN_RB_UBOP ? &S.ubo[nvn_stage][b->reg] : &S.ssbo[nvn_stage][b->reg]) : NULL;
    if (b->kind == NVN_RB_GMEM) return GMEM_ENTRIES * GMEM_ENTRY;   // the raw memory pool table and its write log: their whole size (gmem_map / gml_take)
    if (b->kind == NVN_RB_GMEML) return GML_BYTES;
    return !u || !u->addr ? 0 : !u->size ? UINT32_MAX & ~15u : u->size > UINT32_MAX ? UINT32_MAX & ~15u : (uint32_t)u->size;
}
static uint64_t len_fill(NvShader *sh, int nvn_stage, int kind, const uint64_t *ubcap) {
    uint32_t q[NVN_REFL_MAXARG]; int n = 0;
    if (kind == NVN_RB_UBOLEN) {
        for (n = 0; n < NVN_UBOLEN_N; n++) q[n] = ubolen_vec4_cap(&S.ubo[nvn_stage][n], ubcap ? ubcap[n] : UINT64_MAX);
    } else { sbsz_ctx c = {nvn_stage}; n = nvn_sbsz_fill(sh->rf.b, sh->rf.nb, sbsz_bound, &c, g_geo_size, q); }   // 几何缓冲的长度 = g_geo_size（geo_draw 与 g_geo_bind 同时设）
    id<MTLBuffer> ab; size_t o = arena_alloc(sizeof q[0] * (size_t)n, &ab); memcpy((uint8_t *)ab.contents + o, q, sizeof q[0] * (size_t)n);
    return ab.gpuAddress + o;
}
// Binds the table the variant reads to RED_SLOT (fragment or compute; Metal 3's DmTable3 and Metal 4's argument table take it the same way, enc_r_args / enc_c_args): an entry (nvn_se_ent,
//   64 bytes) per sampler member at its argument id, filled for each sampler of this draw that needs emulation (nvn_red_entry; a custom border also gets the sampler's transparent black /
//   opaque white twins, samp_border_rid), zero for every other (a zero entry leaves the sample as it was). Caller: a draw / dispatch with fc != 0 (the variant's last parameter is the
//   table; main0 has none)
enum { RED_SLOT = 26 };   // = dmsh_red.py RED_SLOT: 0 is the argument buffer, 13 the push, 20-25 the tessellation patches, 27 the compute spill; 1-12 vertex conversions, 14-30 vertex streams
static void se_bind(id en, NvShader *sh, int nvn_stage) {
    static nvn_se_ent q[NVN_REFL_MAXARG];
    int last = -1;   // every argument id of the shader gets an entry (zero unless filled below): a sampler member the reflection did not resolve still reads inside the table
    for (int i = 0; i < sh->rf.nb; i++) { const nvn_rbind *b = &sh->rf.b[i]; last = MAX(last, b->aid + (b->n ? b->n - 1 : 0)); }
    if (last >= NVN_REFL_MAXARG) last = NVN_REFL_MAXARG - 1;
    if (last < 0) last = 0;
    size_t len = sizeof q[0] * (size_t)(last + 1);
    pthread_mutex_lock(&g_rmu);
    memset(q, 0, len);
    for (int i = 0; i < sh->rf.nb; i++) {   // every sampler this draw binds that the shader stands in for, each at its own argument id
        const nvn_rbind *b = &sh->rf.b[i]; if (!se_samp(b) || b->aid >= NVN_REFL_MAXARG) continue;
        int sid = bind_sid(b, nvn_stage); if (sid <= 0 || sid >= g_nsreg || !g_sreg_ok[sid]) continue;
        nvn_se_ent *e = &q[b->aid];
        int ft = g_fold_sh[nvn_stage == 5 ? 5 : 1] == sh ? fold_samp_tid(b, nvn_stage) : -1;
        if (ft >= 0) {   // this sampler reads a folded texture: the fold entry (its own reduction / custom border are not emulated on top; nvn_red.h nvn_se_fold)
            const samp_par *sp = &g_sreg[sid]; const tex_t *tt = &g_treg[ft].t;
            if (nvn_red_entry(!g_red_emu, sp->reduction, sp->minf, sp->magf, sp->ws, sp->wt, sp->wr, sp->cmp_mode, sp->lod_min, sp->lod_max, sp->lod_bias, sp->border, e))
                RED_ONCE(141, "shader %s samples folded texture ser=%llu with a min / max or custom-border sampler: read with the fold's plain filtering", sh->key, (unsigned long long)tt->serial);
            nvn_se_fold(sp->minf, sp->magf, sp->ws, sp->wt, sp->lod_min, sp->lod_max, sp->lod_bias, g_lb_emu, sp->border, tt->d.width, tt->d.height, tex_fold_pitch(tt), tex_fold_k(tt), e);
            continue;
        }
        if (se_entry(sid, e) && e->q[3] != 0) { e->s0 = samp_border_rid(sid, 0); e->s1 = samp_border_rid(sid, 1); if (!e->s0 || !e->s1) e->q[3] = 0; }
    }
    pthread_mutex_unlock(&g_rmu);
    id<MTLBuffer> ab; size_t o = arena_alloc(len, &ab); memcpy((uint8_t *)ab.contents + o, q, len); uint64_t gpu = ab.gpuAddress + o;
    if (nvn_stage == 5) enc_c_args(en, gpu, RED_SLOT);
    else enc_r_args(en, MTLRenderStageFragment, gpu, RED_SLOT);
}
// 审计 #1534 被动采样汇总（随内存行每 300 帧调一次）：累计值，0 也打（普查按它统计射程）；首次、任何一项变了、或距上一行满 3000 帧时打一行
static void audit_probe_report(uint64_t frame) {
    static uint64_t last_frame, sum0; static int any;
    uint64_t sum = g_p65_tables + g_p65_wd + g_p65_pool + g_p20_checked + g_p20_type + g_p20_cls;
    if (any && sum == sum0 && frame - last_frame < 3000) return;
    any = 1; sum0 = sum; last_frame = frame;
    MLOG("audit probes up to frame %llu: P1-65 bounds tables built %llu, longer than the bytes behind the pointer: widen rewritten copy %llu, past the pool buffer end %llu; "
         "P1-20 texture / image bindings checked %llu, declared type differs %llu (of them typed 2D by default offline %llu), pixel class differs %llu",
         (unsigned long long)frame, (unsigned long long)g_p65_tables, (unsigned long long)g_p65_wd, (unsigned long long)g_p65_pool,
         (unsigned long long)g_p20_checked, (unsigned long long)g_p20_type, (unsigned long long)g_p20_type_d2d, (unsigned long long)g_p20_cls);
}
static int encode_args_(id<MTLCommandEncoder> en, NvShader *sh, int nvn_stage, int metal_vertex);
static int encode_args(id<MTLCommandEncoder> en, NvShader *sh, int nvn_stage, int metal_vertex) { AP_B; int r = encode_args_(en, sh, nvn_stage, metal_vertex); AP_E(3); return r; }
static int encode_args_(id<MTLCommandEncoder> en, NvShader *sh, int nvn_stage, int metal_vertex) {
    if (!sh->arg_len) return 1;   // no argument buffer (shader_args_init)
    args_sync_dirty();
    // Exact ABI2 reuses on the same conditions as every program (its table follows the bound views, which mark args dirty, and the pass attachments, keyed by
    //   pass serial), plus one of its own: its support copy lives in this submission's arena (ab_size_sub). 10-31 iPhone A/B: excluding it cost +6–13% instructions per draw
    if ((!sh->size_exact || sh->ab_size_sub == g_sub_serial) && (!sh->ab_ub || sh->ab_size_sub == g_sub_serial) && !passdump() && !g_args_dirty[nvn_stage] && sh->ab_buf && sh->ab_pass == g_pass.serial && nvn_stage != 5 && !(sh->rf.drv_read[0] && sh->ab_binst != g_draw_binst) && !(sh->rf.pool && sh->ab_pgen != g_psnap_gen)) {
        bind_args(en, nvn_stage, metal_vertex, sh->ab_buf, sh->ab_gpu, sh->ab_off, sh->rf.abi);
        g_stat_args_reuse++;
        return 1;
    }
    NSUInteger arg_len = sh->arg_len;
    int size_abi = sh->size_abi && sh->size_exact && sh->nts;   // only exact ABI2 programs with texture entries build a per-draw table; without them the table follows the pass (size_abi_pass_support); legacy_1x keeps main's support buffer binding byte for byte (10-31 iPhone A/B: +6–11% CPU otherwise)
    if (size_abi) size_abi_begin(sh, nvn_stage);
    uint32_t ubw[3] = {0, 0, 0};   // #968: this draw's s2a_flags.y / z / w (ub_note)
    int p65_ul = 0, p65_hit = 0, p65_reg = 0, p65_k = 0; uint64_t p65_tb = 0, p65_av = 0;
    int ul_aid = -1; uint64_t ubcap[NVN_UBOLEN_N]; for (int r = 0; r < NVN_UBOLEN_N; r++) ubcap[r] = UINT64_MAX;   // P1-65: bytes behind each uniform slot's pointer this draw (CBUF branch); the table is filled after the loop   // audit #1534 P1-65 probe: the shader has a bounds table / which risk points this table hit (1 widen copy, 2 pool end) / first hit
    uint64_t slots[NVN_REFL_MAXARG]; memset(slots, 0, arg_len < sizeof slots ? arg_len : sizeof slots);   // only the bytes that are copied out (they used to be zeroed in full, before the reuse check too)
    #define USE(r, u) do { (void)(u); if (__builtin_expect(g_res_check_on, 0)) res_check((r), sh->key, reg); } while (0)
    // DM_NVN_PASSDUMP: on the first new encode per pass per stage, records the shader key (K) and the actual source of each binding (B: UBO address / length / first 4 floats, texture ID and serial, or "dummy")
    static uint64_t bl_pass[6]; static int bl_all = -1; if (bl_all < 0) bl_all = getenv("DM_NVN_PASSDUMP_ALL") != NULL;   // Record on every new encode (otherwise only the first time per pass per stage)
    int bl = passdump() && (bl_all || g_kd_force || bl_pass[nvn_stage] != g_stat_pass);
    if (bl) { bl_pass[nvn_stage] = g_stat_pass; PD("K %llu st%d key=%s nb=%d", g_stat_pass, nvn_stage, sh->key[0] ? sh->key : sh->builtin ? sh->builtin : "?", sh->rf.nb); }
    pthread_mutex_lock(&g_rmu);   // The texture / sampler registration tables may be being grown or rewritten by the game thread
    for (int i = 0; i < sh->rf.nb; i++) {
        const nvn_rbind *b = &sh->rf.b[i];
        int reg = b->reg, aid = b->aid;
        if (b->kind == NVN_RB_GEOMETRY) { slots[aid] = g_geo_bind[reg]; continue; }
        if (b->kind == NVN_RB_UVX) { slots[aid] = uvx_fill(sh, nvn_stage); continue; }   // S2Arm widen 16:9 sampling remap (see uvx_fill)
        if (b->kind == NVN_RB_LB) { slots[aid] = lb_fill(sh, nvn_stage); continue; }   // S2Arm #800 sampler LOD bias in the shader (see lb_fill)
        if (b->kind == NVN_RB_UBOLEN) { ul_aid = aid; p65_ul = 1; continue; }   // #1204 T1 uniform bounds table: filled after the loop, once the CBUF branch knows what each pointer has behind it
        if (b->kind == NVN_RB_SBSZ) { slots[aid] = len_fill(sh, nvn_stage, b->kind, NULL); continue; }   // #1204 T1 bounds tables (see len_fill)
        if (b->kind == NVN_RB_CBUF) {
            const p_bind_buf *u = reg < 16 ? &S.ubo[nvn_stage][reg] : NULL;
            void *mb; uint64_t mo, gpu, pav;
            if (!u || !u->addr || !gpu_addr_want(u->addr, 1, u->size, &mb, &mo, &gpu, &pav)) {   // reads 0 (the all-zero bank), as an unbound texture slot does, instead of through a null pointer
                RED_ONCE(16, "stage %d cb%d has no uniform buffer bound", nvn_stage, reg); slots[aid] = zero_bank_gpu(); USE(zero_bank(), MTLResourceUsageRead); continue; }
            uint64_t ul = cb_len(sh, reg, u->size);   // what the shader can read of it
            // S2Arm widen: the rewritten copy replaces the binding (compute: wd_dispatch). Checked first: the deferred-update shadow below used to be built for it and then thrown away,
            //   shadow copies issued to the GPU included (audit P1-91)
            uint64_t wdg = g_wd > 0 && nvn_stage < 6 ? g_wd_gpu[nvn_stage][reg] : 0;
            int pk = 2;   // P1-65 probe: what the pointer is: 1 the widen rewritten copy (g_wd_last len bytes), 2 the pool's buffer (pav bytes to its end), 0 a deferred-update shadow (bounded by the read range: not checked)
            if (wdg) { gpu = wdg; pk = 1; pav = g_wd_last[nvn_stage][reg].len; }
            else if (g_nubd && ubd_hits(u->addr, u->addr + ul)) { pk = 0;   // inline updates deferred in this pass (see mtl_sub_update); ubd_conflict made sure they cover the binding or the rest can be read from memory
                uint64_t g; const uint8_t *c; if (ubd_covers(u->addr, u->addr + ul)) gpu = ubd_shadow(u->addr, u->addr + ul);
                else if (ubp_get(u->addr, u->addr + ul, &g, &c)) { gpu = g; ubq_gpu(g_ubp_q); }   // the GPU reads it: its copies go now
                else RED_ONCE(92, "a uniform update deferred inside the pass covers only part of the binding (stage %d cb%d): the content before the update is read", nvn_stage, reg); }
            if (reg < NVN_UBOLEN_N) { ubcap[reg] = pk ? pav : ul;   // pk 0: a deferred-update shadow covers exactly the read range ul
