static inline int rec_bad(op_hdr h) { return h.size < 8 || (h.size & 7) || h.op >= OP_NVN2_END_ || h.op == OP_BEGIN; }
static const uint8_t *g_exec_top;   // The top-level handle being replayed (nvn_be_exec at return depth 0)
// One red line per bad header (the first 16 in a run): which cursor, where, the handle and list it was walking, the record before it; the cursor then ends that list
static void rec_bad_red(const char *who, const uint8_t *p, op_hdr h, const uint8_t *list, const uint8_t *prev) {
    static _Atomic unsigned n; if (atomic_fetch_add(&n, 1) >= 16) return;
    op_hdr ph = {0, 0}; if (prev) memcpy(&ph, prev, sizeof ph);
    char hx[3 * 32 + 1]; for (int k = 0; k < 32; k++) snprintf(hx + 3 * k, 4, "%02x ", p[k]);
    MLOG("【红】 command record at %p is not one of ours (%s): op %u size %u; handle %p, list %p + %#lx, previous record %p op %u size %u, call depth %d: that list ends here; bytes: %s",
         p, who, h.op, h.size, g_exec_top, list, list ? (unsigned long)(p - list) : 0ul, prev, ph.op, ph.size, g_ret_n, hx);
}
typedef struct { const uint8_t *p, *ret[sizeof g_ret / sizeof *g_ret]; int ret_n, rest_i, bad; } fz_cursor;   // ret: same capacity as the replay return stack it is copied from
// Lookahead starting from the op after the current draw, carrying the replay return stack so that sub-list boundaries are correctly crossed.
// Every lookahead that may run while inside a CALL sub-list must use this; a bare {.p = g_exec_next} with ret_n=0 would cross an OP_END by consuming g_rest instead of returning to the caller.
static inline fz_cursor fz_cursor_from_exec(void) {
    fz_cursor c = {.p = g_exec_next};
    // g_ret_n counts every CALL but g_ret keeps only the first entries: deeper than that the caller chain is lost, so the lookahead stops rather than guess (or copy past the array)
    if (g_ret_n < 0 || g_ret_n > (int)(sizeof c.ret / sizeof *c.ret)) { c.p = NULL; c.bad = 1; return c; }
    c.ret_n = g_ret_n; memcpy(c.ret, g_ret, sizeof(*g_ret) * (size_t)g_ret_n);
    return c;
}
static int fz_next(fz_cursor *c, const uint8_t **out, op_hdr *oh, const void **oa) {
    for (int guard = 0; guard < 1000000; guard++) {
        if (!c->p) return 0;
        op_hdr h; memcpy(&h, c->p, sizeof h); const void *a = c->p + 8;
        if (rec_bad(h)) { rec_bad_red("lookahead fz_next", c->p, h, NULL, NULL); c->p = NULL; c->bad = 1; return 0; }
        switch (h.op) {
            case OP_END:
                if (c->ret_n) c->p = c->ret[--c->ret_n];
                else if (c->rest_i < g_nrest) c->p = (const uint8_t *)g_rest[c->rest_i++];
                else { c->p = NULL; return 0; }
                continue;
            case OP_JUMP: memcpy(&c->p, a, 8); continue;
            case OP_MULTI_DRAW: c->bad = 1; return 0;   // its live draws and their argument addresses are resolved at replay (draw_multi): a lookahead cannot move work across the range (c7ba23df)
            case OP_CALL: { uint64_t t; memcpy(&t, a, 8); if (c->ret_n >= (int)(sizeof c->ret / sizeof *c->ret)) { c->bad = 1; return 0; }
                c->ret[c->ret_n++] = c->p + h.size; c->p = (const uint8_t *)t; continue; }
            default: break;
        }
        const uint8_t *p = c->p; c->p += h.size;
        if (g_hoist_n && hoist_skipped(p)) continue;
        if (out) *out = p; if (oh) *oh = h; if (oa) *oa = a; return 1;
    }
    c->bad = 1; return 0;
}
// State of the readable-tile pass merge (merge B step 2): the earlier pass (phase 1) and the later pass (phase 2) share one render pass, and the attachments are the union
typedef struct {
    int active, phase, n1, nskip;
    int nreuse;
    const uint8_t *rt2_op, *reuse[8], *skip[12];
    p_set_rt rt1, rt2;                 // Logical targets of each of the two passes (R.rt is the union during the merge)
    int8_t p2map[8];                   // Logical color number of the later pass → physical attachment
