        WF(MTLVertexFormatShortNormalized, 3, 1, 2) WF(MTLVertexFormatShort2Normalized, 3, 2, 2) WF(MTLVertexFormatShort3Normalized, 3, 3, 2) WF(MTLVertexFormatShort4Normalized, 3, 4, 2)
        WF(MTLVertexFormatUChar, 4, 1, 1) WF(MTLVertexFormatUChar2, 4, 2, 1) WF(MTLVertexFormatUChar3, 4, 3, 1) WF(MTLVertexFormatUChar4, 4, 4, 1)
        WF(MTLVertexFormatChar, 5, 1, 1) WF(MTLVertexFormatChar2, 5, 2, 1) WF(MTLVertexFormatChar3, 5, 3, 1) WF(MTLVertexFormatChar4, 5, 4, 1)
        WF(MTLVertexFormatUShort, 4, 1, 2) WF(MTLVertexFormatUShort2, 4, 2, 2) WF(MTLVertexFormatUShort3, 4, 3, 2) WF(MTLVertexFormatUShort4, 4, 4, 2)
        WF(MTLVertexFormatShort, 5, 1, 2) WF(MTLVertexFormatShort2, 5, 2, 2) WF(MTLVertexFormatShort3, 5, 3, 2) WF(MTLVertexFormatShort4, 5, 4, 2)
