        NSString *path = [NSString stringWithFormat:@"%.*s_bf", (int)(kl > 2 ? kl - 2 : kl), fs->key];
        fs->bf_lib = lib_from_pack(path.UTF8String, &e);   // S2Arm: from the library container, or its file without one
        if (!fs->bf_lib) MLOG("【红】 failed to load the readable-tile version %s: %s", path.UTF8String, e.localizedDescription.UTF8String);
        else g_bf_libs++;
    }
    id<MTLLibrary> lib = fs->bf_lib;
    if (!lib) { os_unfair_lock_unlock(&g_fz_fn_lock); return nil; }
    MTLFunctionConstantValues *cv = [MTLFunctionConstantValues new];
    for (int i = 0; i < fs->rf.nfc; i++) { int v = fx[i]; [cv setConstantValue:&v type:MTLDataTypeInt atIndex:(NSUInteger)i]; }
    for (int q = 0; q < 8; q++) { bool b = fbmask >> q & 1; [cv setConstantValue:&b type:MTLDataTypeBool atIndex:(NSUInteger)(32 + q)]; }
    for (int j = 0; j < fs->rf.nfo; j++) for (int q = 0; q < 8; q++) { bool b = lmap[q] == fs->rf.fo_color[j]; [cv setConstantValue:&b type:MTLDataTypeBool atIndex:(NSUInteger)(64 + 8 * j + q)]; }
    NSError *e = nil; id<MTLFunction> f = [lib newFunctionWithName:@"main0" constantValues:cv error:&e];
