}
// The game profile's zero_skip (game.tsv, filled at library build from games/zero_skip.tsv by title ID): "<fragment key>:<ubo register>:<vector>:<component>", whitespace-separated.
//   DM_NVN_ZSKIP_FACTS replaces the list (0 = none). Read once, before the first lookup; unit tests' zskip_test_add entries stay
static int g_zskip_loaded;
static void zskip_facts_load(void) {
    g_zskip_loaded = 1;
    const char *e = getenv("DM_NVN_ZSKIP_FACTS"), *src = e && *e ? e : DM_GAME_ZERO_SKIP;
    if (!strcmp(src, "0")) return;
    for (const char *q = src; *q;) { size_t n = strcspn(q, " \t,");
        char w[64]; char key[17]; int slot, vec, comp, used = 0;
        if (n && n < sizeof w) { memcpy(w, q, n); w[n] = 0;
            if (sscanf(w, "%16[0-9a-f]:%d:%d:%d%n", key, &slot, &vec, &comp, &used) == 4 && used == (int)n && strlen(key) >= 8 && (slot < 0 || (slot < 18 && vec >= 0 && vec < 1024 && comp >= 0 && comp < 4))) zskip_test_add(key, slot, vec, comp);
            else RED_ONCE(49, "zero_skip entry not understood (want <key>:<ubo>:<vec>:<comp>), ignored"); }
        q += n; q += strspn(q, " \t,"); }
    if (g_zskip_nf) MLOG("zero-source skip facts: %d shader(s) (%s)", g_zskip_nf, e && *e ? "DM_NVN_ZSKIP_FACTS" : "profile key zero_skip");
}
static int zskip_fact_for(const char *key, zskip_fact *out) {
    if (!key) return 0;
    if (!g_zskip_loaded) zskip_facts_load();
    for (int i = 0; i < g_zskip_nf; i++) if (!strncmp(key, g_zskip_facts[i].key, strlen(g_zskip_facts[i].key))) { *out = g_zskip_facts[i]; return 1; }   // Runtime keys carry the _b suffix
    return 0;
}
static int zskip_view_zero(int tid) {
