static int fb_tile_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_FB_TILE"); v = !(e && !strcmp(e, "0")); if (!v) MLOG("same-pass feedback sampling: on-chip read off (DM_NVN_FB_TILE=0)"); } return v; }
// 颜色格式的分量数（只认能当附件的常见单 / 双 / 三分量格式；其余按 4，即「缺的分量」为空、只认恒等）
static int pf_ncomp(MTLPixelFormat f) {
