    for (int a = 0; a < n; a++) { r3[a] = fbc_copy(g_fbc.att[a]); if (!r3[a]) return; }
    for (int a = 0; a < n; a++) enc_b_copy_texture(blit(), g_fbc.s0[a], 0, 0, MTLOriginMake(0, 0, 0), MTLSizeMake(g_fbc.s0[a].width, g_fbc.s0[a].height, 1), g_fbc.att[a], 0, 0, MTLOriginMake(0, 0, 0));
    g_fbc.forcing = 1; draw(dw, di); g_fbc.forcing = 0; rp_end();
