}
// After a draw: the color slots it wrote now differ from memory until the pass ends (fb_prepare copies a hit on such a slot); the same write test as udc_note_draw
static void fb_note_draw(NvProg *pr) {
    uint32_t cm = pr && pr->sh[1] ? pr->sh[1]->rf.color_mask : 0;
    if (R.has_rt) for (int i = 0; i < R.rt.n && i < 8; i++) if ((cm >> i & 1) && ((S.chmask.mask >> (4 * i)) & 0xf)) g_fb_dirty[i] = 1;
