            if (g_fb_use[g_fb_n] && g_fb_use[g_fb_n] != use) defer_obj_unref(g_fb_use[g_fb_n]);
            g_fb_src[g_fb_n] = t; g_fb_use[g_fb_n] = use; g_fb_rid[g_fb_n] = use.gpuResourceID._impl; g_fb_n++; g_fb_hits++; g_fb_count++; g_fb_depth++;
            g_dsnap.ser = ser; g_dsnap.src = t; g_dsnap.use = use; g_dsnap.valid = 1;
            if (g_fb_depth == 1 || g_fb_depth == 100 || g_fb_depth % 100000 == 0) MLOG("same-pass depth sampling: draw %llu (shader %s) samples its pass's depth attachment ser=%llu (%lux%lu format %lu); the pass ends and it reads a copy (%llu so far)",
                (unsigned long long)g_draw_seq, fs->key, (unsigned long long)ser, (unsigned long)base.width, (unsigned long)base.height, (unsigned long)base.pixelFormat, (unsigned long long)g_fb_depth);
            PD("N %llu same-pass depth sampling: depth attachment ser=%llu sampled at slot %d; the pass ends and this draw reads a copy", g_stat_pass, (unsigned long long)ser, b->reg);
            continue;
        }
        for (int k = 0; k < R.rt.n && k < 8 && g_fb_n < 4; k++) {
            const tex_t *attachment = R.rt.color[k]; if (!attachment) continue;
            int alias = attachment->serial != ser; id<MTLTexture> attachment_storage = nil;
            if (alias) {
                // Serial numbers name NVN objects, not storage. Reject unrelated pool ranges
                // cheaply, then use the same layout key as the shared-texture table.
                if (!sampled.pool || sampled.pool != (uint64_t)(uintptr_t)attachment->pool || sampled.off != attachment->off) continue;
                alias_key attached; alias_key_of(&attached, attachment); if (memcmp(&sampled, &attached, sizeof sampled)) continue;
                attachment_storage = tex_mtl(attachment);
            }
            uint64_t aser; int lv, sl; rt_sub(&R.rt, k, &aser, &lv, &sl);
            pthread_mutex_lock(&g_rmu); void *tv = NULL; tex_fast_rid(tid, &tv); id<MTLTexture> t = (__bridge id<MTLTexture>)tv; pthread_mutex_unlock(&g_rmu);
            if (!t) continue;
            int dup = 0; for (int q = 0; q < g_fb_n; q++) dup |= g_fb_src[q] == t; if (dup) continue;
            id<MTLTexture> base = t.parentTexture ? t.parentTexture : t; NSUInteger tl = t.parentTexture ? t.parentRelativeLevel : 0, ts = t.parentTexture ? t.parentRelativeSlice : 0;
            // Packaged textures may have identical descriptors but independent host copies.
            // Only an actual shared root can be feedback through a different serial.
            if (alias && (!attachment_storage || (attachment_storage.parentTexture ?: attachment_storage) != base)) continue;
            if (tl + t.mipmapLevelCount <= (NSUInteger)lv || tl > (NSUInteger)lv) continue;   // the sampled levels do not include the attachment's level (mip generation etc.): not feedback
            MTLTextureType tt = t.textureType, vt = (MTLTextureType)b->dtt;
            // The same for layers: a view that holds only some of the base's slices and not the one being drawn (Breath of the Wild 9a08f70c2775ebe7 samples
            // layers 0-5 of a 2D array while drawing layer 6 of it) samples no texel this draw writes - not feedback, and the red line below was reporting it
            if (tt == MTLTextureType2D || tt == MTLTextureType2DArray) { NSUInteger nv = tt == MTLTextureType2D ? 1 : (NSUInteger)t.arrayLength;
                if ((NSUInteger)sl < ts || (NSUInteger)sl >= ts + nv) continue; }
            g_fb_hits++;
            // ① a mip chain step (Super Mario Odyssey ba12a528caca7398, its bloom: samples a view of levels 0-1 while drawing level 1): the Switch reads the levels below the one being
            //   drawn, so the view is narrowed to them (same base level: the shader's LOD means the same) — a view, no copy, the pass stays open
            //   Same for 2D arrays and 3D textures (Odyssey 05896129adcb7c5e: levels 0-1 of a 3D texture while drawing level 1): the view keeps its type and all its slices; a 2D array
            //   the shader declares as a cube / cube array (Mario Wonder 87d7d85e75a62a08: prefilters a cube array level by level, drawing one face of level 1 while sampling levels 0-7)
            //   gets the declared type directly, so the slot needs no type bridge (tex_fit) after the substitution
            int cube = tt == MTLTextureType2DArray && (vt == MTLTextureTypeCube || vt == MTLTextureTypeCubeArray) && t.arrayLength % 6 == 0 && (vt == MTLTextureTypeCubeArray || t.arrayLength == 6);
            // ⓪ the draw's sampler pins one level (fb_pinned_level; upstream reference implementation, MIT, 56e4577b): a view of that level alone, whichever side of the attachment it
            //   lies on. ① below keeps only the levels under the attachment's: an upsample pass reads the level above (level n drawn from n + 1), which that view clamped to n - 1, a
            //   sharper level the chain then added back up, and rendering the view's base level ① makes no view at all, so it read the attachment's own level (Donkey Kong Bananza's
            //   bloom chains, 576x324 R11G11B10F, 5 levels: the stage intro's neon letters came out fat and filled)
            int pin = t.mipmapLevelCount > 1 ? fb_pinned_level(fs, b->reg, (int)(tex_slot_h(S.tex[1], S.img[1], b->reg) >> 20)) : -1;
            if (pin >= 0 && (NSUInteger)pin >= t.mipmapLevelCount) pin = (int)t.mipmapLevelCount - 1;   // past the view's levels: its last one, where the sampler's clamp ends
            if (pin >= 0 && tl + (NSUInteger)pin != (NSUInteger)lv && (tt == MTLTextureType2D || tt == MTLTextureType2DArray || tt == MTLTextureType3D) && (vt == tt || cube)
                && t.sampleCount == 1 && !base.parentTexture && (tt != MTLTextureType2D || ts == (NSUInteger)sl)) {
                id<MTLTexture> use = fb_narrow_view(base, t, vt, tl + (NSUInteger)pin, 1, tt == MTLTextureType3D ? 0 : ts, 0);
                if (!use) { RED_ONCE(133, "same-pass feedback sampling: cannot make the view of level %lu the sampler pins (shader %s); left as is", (unsigned long)(tl + (NSUInteger)pin), fs->key); continue; }
                if (g_fb_use[g_fb_n] && g_fb_use[g_fb_n] != use) defer_obj_unref(g_fb_use[g_fb_n]);
                g_fb_src[g_fb_n] = t; g_fb_use[g_fb_n] = use; g_fb_rid[g_fb_n] = use.gpuResourceID._impl; g_fb_n++; g_fb_l1++;
                if (g_fb_pin++ == 0) MLOG("same-pass feedback sampling: first pinned-level view (frame %llu, shader %s slot %d renders level %d of a view of levels %lu+%lu; its sampler pins level %lu, which it samples alone)",
                                          (unsigned long long)atomic_load(&g_cur_frame), fs->key, b->reg, lv, (unsigned long)tl, (unsigned long)t.mipmapLevelCount, (unsigned long)(tl + (NSUInteger)pin));
                PD("N %llu same-pass feedback sampling: attachment %d ser=%llu draws level %d; the sampler pins level %lu, sampled alone", g_stat_pass + !g_enc, k, (unsigned long long)ser, lv, (unsigned long)(tl + (NSUInteger)pin));
                continue; }
            if ((tt == MTLTextureType2D || tt == MTLTextureType2DArray || tt == MTLTextureType3D) && (vt == tt || cube) && t.sampleCount == 1 && t.mipmapLevelCount > 1 && (NSUInteger)lv > tl && !base.parentTexture
                && (tt != MTLTextureType2D || ts == (NSUInteger)sl)) {
                id<MTLTexture> use = fb_narrow_view(base, t, vt, tl, (NSUInteger)lv - tl, tt == MTLTextureType3D ? 0 : ts, 0);
                if (!use) { RED_ONCE(133, "same-pass feedback sampling: cannot narrow the view (levels %lu+%lu, attachment level %d, shader %s); left as is", (unsigned long)tl, (unsigned long)t.mipmapLevelCount, lv, fs->key); continue; }
                if (g_fb_use[g_fb_n] && g_fb_use[g_fb_n] != use) defer_obj_unref(g_fb_use[g_fb_n]);
                g_fb_src[g_fb_n] = t; g_fb_use[g_fb_n] = use; g_fb_rid[g_fb_n] = use.gpuResourceID._impl; g_fb_n++;
                if (++g_fb_l1 == 1) MLOG("same-pass feedback sampling: first narrowed view (frame %llu, shader %s slot %d samples levels %lu+%lu of attachment %d ser=%llu, which draws level %d)",
                                         (unsigned long long)atomic_load(&g_cur_frame), fs->key, b->reg, (unsigned long)tl, (unsigned long)t.mipmapLevelCount, k, (unsigned long long)ser, lv);
                PD("N %llu same-pass feedback sampling: attachment %d ser=%llu draws level %d; the sampled view is narrowed to levels %lu+%d", g_stat_pass + !g_enc, k, (unsigned long long)ser, lv, (unsigned long)tl, lv - (int)tl);
                continue; }
            // ①b the level being drawn is in the view, but the layer being drawn is the view's last block (Mario Wonder 1e723ca2d350980e: filters cube 0 of a 2-cube array into cube 1,
            //   drawing face 0 of cube 1 while the view holds both cubes): drop that block; the blocks before it keep their indices (a cube array counts in blocks of 6), no copy
            if (tt == MTLTextureType2DArray && (vt == tt || cube) && t.sampleCount == 1 && !base.parentTexture && (NSUInteger)sl >= ts) {
                NSUInteger unit = vt == tt ? 1 : 6, wb = ((NSUInteger)sl - ts) / unit, nb = t.arrayLength / unit;
                if (wb > 0 && wb == nb - 1) {
                    id<MTLTexture> use = fb_narrow_view(base, t, vt, tl, t.mipmapLevelCount, ts, wb * unit);
                    if (!use) { RED_ONCE(133, "same-pass feedback sampling: cannot narrow the view (layers %lu+%lu, attachment layer %d, shader %s); left as is", (unsigned long)ts, (unsigned long)t.arrayLength, sl, fs->key); continue; }
                    if (g_fb_use[g_fb_n] && g_fb_use[g_fb_n] != use) defer_obj_unref(g_fb_use[g_fb_n]);
                    g_fb_src[g_fb_n] = t; g_fb_use[g_fb_n] = use; g_fb_rid[g_fb_n] = use.gpuResourceID._impl; g_fb_n++;
                    g_fb_l1++; if (g_fb_l1b++ == 0) MLOG("same-pass feedback sampling: first layer-narrowed view (frame %llu, shader %s slot %d samples layers %lu+%lu of attachment %d ser=%llu, which draws layer %d: layers %lu+%lu read)",
                                                 (unsigned long long)atomic_load(&g_cur_frame), fs->key, b->reg, (unsigned long)ts, (unsigned long)t.arrayLength, k, (unsigned long long)ser, sl, (unsigned long)ts, (unsigned long)(wb * unit));
                    PD("N %llu same-pass feedback sampling: attachment %d ser=%llu draws layer %d; the sampled view is narrowed to layers %lu+%lu", g_stat_pass + !g_enc, k, (unsigned long long)ser, sl, (unsigned long)ts, (unsigned long)(wb * unit));
                    continue; } }
            // A clear still waiting (this draw's own targets' load-action clears, or lazy clears of earlier targets) has not reached memory yet: land it first, then the layers below
            // see memory as the Switch does (② would read what was there before the clear, ④ would copy it: xy0v0 ae42eb856 measured (0,0,0) for a pending clear color)
            if (!settled) { int pend = g_nlc || R.clear_d || R.clear_s; for (int c = 0; c < 8; c++) pend |= R.clear_c[c];
                settled = 1; if (pend) { lc_land(); rp_flush(); memset(g_fb_dirty, 0, sizeof g_fb_dirty); } }
            int self_write = listed || ((fs->rf.color_mask >> k & 1) && ((S.chmask.mask >> (4 * k)) & 0xf));
            // ② unchanged memory is safe to sample only if this draw does not also write that slot (the diagnostic override restores the old self-read).
            if (!g_fb_dirty[k] && !listed && (g_fb_selfread || !self_write)) { g_fb_l2++; continue; }
            // ⑤ read the tile instead of sampling the attachment, whenever the tile holds exactly the content from before this draw:
            //   - the open pass drew it (dirty): the tile has those draws' writes, memory does not;
            //   - the open pass loaded it and has not drawn it yet: the tile is memory;
            //   - the pass is not open yet (the first draw of the pass): it is opened with this slot loaded (g_fb_want_load; no don't-care load, no covered-load skip), the tile is memory.
            //   The last two used to go to ④ (#307 Breath of the Wild: the first self-sampling draw of each pass copied a 1600x900 attachment, ~8 copies / ~50 MB a frame; iPhone
            //   energy per frame +5-26% when hot). Reading the tile costs one load instead of a copy, a snapshot and its sampling, and the pass is not split
            if (!listed && g_fb_dirty[k] && g_enc && fb_tile_try(pr, fs, k, b->reg, t, 0)) { PD("N %llu same-pass feedback sampling: attachment %d ser=%llu was drawn in this pass; this draw reads it on-chip (slot %d), the pass stays open", g_stat_pass, k, (unsigned long long)ser, b->reg); continue; }
            if (!listed && !g_fb_dirty[k] && g_enc && (g_fb_loaded >> k & 1) && fb_tile_try(pr, fs, k, b->reg, t, 0)) { g_fb_l5ld++; PD("N %llu same-pass feedback sampling: attachment %d ser=%llu was loaded and not yet drawn in this pass; this draw reads it on-chip (slot %d)", g_stat_pass, k, (unsigned long long)ser, b->reg); continue; }
            //   (not with a deferred replay pending: it runs other draws' fb_prepare after the pass opens; not inside a pass merge)
            if (!listed && !g_fb_dirty[k] && !g_enc && !g_defer_replaying && !g_defer_natq && !g_fz.active && fb_tile_try(pr, fs, k, b->reg, t, 1)) { g_fb_want_load |= (uint8_t)(1u << k); g_fb_l5ld++; PD("N %llu same-pass feedback sampling: attachment %d ser=%llu, pass not open yet: opened with it loaded, this draw reads it on-chip (slot %d)", g_stat_pass + 1, k, (unsigned long long)ser, b->reg); continue; }
            // ③ ending the pass makes prior writes visible, but does not isolate a self-writing draw in the next pass.
            if (!listed && (!self_write || g_fb_selfread)) {
                if (g_enc) { rp_end(); PD("N %llu same-pass feedback sampling: attachment %d ser=%llu was drawn in this pass%s; the pass ends before this draw samples it", g_stat_pass, k, (unsigned long long)ser, self_write ? " (self-write)" : ""); }
                memset(g_fb_dirty, 0, sizeof g_fb_dirty); g_fb_l3++; continue; }
            // ④ this draw writes the slot it samples: copy the whole sampled view (every level and layer of it) into a snapshot of the same
            //   shape and sample that. Any 2D / 2D array view works, including one the shader declares as a cube / cube array and one that holds several mip levels
            //   (Breath of the Wild 9a08f70c2775ebe7: a 4-level 2D array sampled while drawing layer 6 of it): the levels the pass does not write are copied unchanged,
            //   so a LOD read means the same in the snapshot. Non-root views (a view of a view), multisample and 3D are reported once and left as they are
            if ((tt != MTLTextureType2D && !(tt == MTLTextureType2DArray && (vt == tt || cube))) || t.sampleCount != 1 || base.parentTexture) {
                RED_ONCE(80, "same-pass feedback sampling: the sampled view cannot be copied whole (type %lu levels %lu+%lu layer %lu, attachment level %d layer %d, shader %s); left as is", (unsigned long)t.textureType, (unsigned long)tl, (unsigned long)t.mipmapLevelCount, (unsigned long)ts, lv, sl, fs->key);
                continue; }
            NSUInteger nl = t.mipmapLevelCount, nsh = tt == MTLTextureType2D ? 1 : (NSUInteger)t.arrayLength;
            {   // A whole-view copy costs about 1.34 x level 0 x layers; a view far larger than the attachment being drawn is left as it is (reported once)
                uint64_t mb = 0; for (NSUInteger l = 0; l < nl; l++) mb += (uint64_t)mip_extent(base.width, tl + l) * mip_extent(base.height, tl + l) * nsh * (uint64_t)MAX(mtl_pf_bytes(base.pixelFormat), 1u);
                if (mb > 64u << 20) { RED_ONCE(127, "same-pass feedback sampling: the sampled view is too large to copy whole (%.1f MB, type %lu levels %lu layers %lu, shader %s); left as is", mb / 1048576.0, (unsigned long)t.textureType, (unsigned long)nl, (unsigned long)nsh, fs->key); continue; } }
            // The snapshot is always 2D / 2D array storage, as every cube texture is (tex_desc): a cube / cube array view is made from it by fb_narrow_view
            int q = 0; while (q < ncopy && !(cbase[q] == base && ckey[q][0] == tl && ckey[q][1] == nl && ckey[q][2] == ts && ckey[q][3] == nsh)) q++;   // views of one real subresource share one copy
            id<MTLTexture> snap = q < ncopy ? csnap[q] : nil; int fresh = !snap;
            if (!snap) {   // first view of this subresource in the draw: copy it (copies of other subresources go to other slots)
                snap = fb_snap_shape(tt == MTLTextureType2D ? MTLTextureType2D : MTLTextureType2DArray, base.pixelFormat, base.width, base.height, tl, nl, nsh, ncopy); if (!snap) continue;
                if (g_enc) rp_end();
                id<MTL4ComputeCommandEncoder> e = blit();
                for (NSUInteger l = 0; l < nl; l++) {
                    NSUInteger w = mip_extent(base.width, tl + l), h = mip_extent(base.height, tl + l);
                    for (NSUInteger s = 0; s < nsh; s++) enc_b_copy_texture(e, base, ts + s, tl + l, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, 1), snap, s, l, MTLOriginMake(0, 0, 0));
                    g_fb_bytes += (uint64_t)w * h * nsh * (uint64_t)MAX(mtl_pf_bytes(base.pixelFormat), 1u); }
                cbase[ncopy] = base; csnap[ncopy] = snap; ckey[ncopy][0] = tl; ckey[ncopy][1] = nl; ckey[ncopy][2] = ts; ckey[ncopy][3] = nsh; ncopy++; g_fb_count++; }   // g_fb_count: ④ copies (one per real subresource and draw)
            MTLTextureType stp = tt == MTLTextureType2D ? MTLTextureType2D : vt;   // the view the draw needs (cube / cube array on the snapshot's 2D array storage)
            id<MTLTexture> use = fb_narrow_view(snap, t, stp, 0, nl, 0, nsh);
            if (!use) { RED_ONCE(81, "same-pass feedback sampling: cannot create the snapshot view (format %lu type %lu); left as is", (unsigned long)t.pixelFormat, (unsigned long)stp); continue; }
            if (g_fb_use[g_fb_n] && g_fb_use[g_fb_n] != use) defer_obj_unref(g_fb_use[g_fb_n]);
            g_fb_src[g_fb_n] = t; g_fb_use[g_fb_n] = use; g_fb_rid[g_fb_n] = use.gpuResourceID._impl; g_fb_n++;
            if (fresh && (g_fb_count == 1 || g_fb_count == 10 || g_fb_count == 1000 || g_fb_count % 100000 == 0))
                MLOG("same-pass feedback sampling: snapshot #%llu (frame %llu pass %llu, shader %s slot %d samples attachment %d ser=%llu %lux%lu levels %lu layers %lu format %lu)", (unsigned long long)g_fb_count, (unsigned long long)atomic_load(&g_cur_frame), g_stat_pass + !g_enc,
                     fs->key, b->reg, k, (unsigned long long)ser, (unsigned long)mip_extent(base.width, tl), (unsigned long)mip_extent(base.height, tl), (unsigned long)nl, (unsigned long)nsh, (unsigned long)base.pixelFormat);
            PD("N %llu same-pass feedback sampling: attachment %d ser=%llu level %d layer %d copied into a snapshot; this draw samples the snapshot", g_stat_pass + !g_enc, k, (unsigned long long)ser, lv, sl);
        } }
    if (g_fb_n) { g_fb_seq = g_draw_seq; args_dirty_all(); g_fb_rebind = 1; }
}
// ---------- Indirect draws Metal cannot take as they are ----------
// Quads and triangle fans (DrawArraysIndirect), and indexed quads / fans / 8-bit indices (DrawElementsIndirect). The {count, instances, first, ...} record is usually written by the GPU earlier
// in the frame (Hyrule Warriors: Age of Calamity draws GPU-driven effects as indirect quads in its first battle), so the CPU cannot expand it at replay. A compute pass converts each record into
// MTLDrawIndexedPrimitivesIndirectArguments in the frame arena, and the draw becomes an indexed indirect draw: arrays index the shared g_quad_ib / g_fan_ib with first as the base vertex,
// indexed ones are expanded into a 32-bit list of at most IXC_CAP indices. The compute pass cannot run inside a render pass. When the first such draw is met, ixc_run converts it and every
// such draw after it up to the next buffer write outside a render pass (copy, update / fill, texture → buffer, dispatch: they bump g_wr_epoch), so each record is read after its last writer
// and the later draws find their conversion. Only a draw met inside an open render pass with no conversion yet splits that pass.
#define IXC_MAX 128
#define IXC_CAP (3 * 16384)
typedef struct { uint64_t ind, ibuf; int32_t prim, itype; uint64_t args, ixb; uint32_t ixlen; } ixc_ent;   // args 0: the record could not be converted
static ixc_ent g_ixc[IXC_MAX]; static int g_ixc_n; static uint64_t g_ixc_epoch, g_ixc_sub, g_ixc_runs, g_ixc_splits;
static const char k_ixc_msl[] =
"#include <metal_stdlib>\nusing namespace metal;\n"
"struct ajob { device const uint *rec; device uint *args; uint prim, cap; };\n"   // arrays record {count, instances, first, base instance}; cap: indices in the shared index buffer
"kernel void ixc_arrays(device const ajob *j [[buffer(0)]], uint i [[threadgroup_position_in_grid]]) {\n"
"  if (j[i].prim == 0x40) { device const uint *s = j[i].rec; device uint *d = j[i].args; d[0] = s[0]; d[1] = 1; d[2] = 1; d[3] = 0; d[4] = s[1]; return; }\n"   // NVN2 DrawMeshTasksIndirect {count, first} → MTLDispatchThreadgroupsIndirectArguments {count, 1, 1}, first at word 4 (buffer 29 of the task / mesh draw; nvn_geometry.inc mtk_encode)
"  device const uint *s = j[i].rec; uint n = s[0], c = j[i].prim == 7 ? n / 4 * 6 : n >= 3 ? (n - 2) * 3 : 0;\n"
"  device uint *d = j[i].args; d[0] = min(c, j[i].cap); d[1] = s[1]; d[2] = 0; d[3] = s[2]; d[4] = s[3]; }\n"
"struct ejob { device const uint *rec; device const uchar *ib; device uint *out; device uint *args; uint prim, isz, ilen, cap; };\n"   // elements record {count, instances, first index, base vertex, base instance}; ilen: bytes readable at ib
"kernel void ixc_expand(constant ejob &j [[buffer(0)]], uint i [[thread_position_in_grid]]) {\n"
"  uint n = j.rec[0], m = min(j.prim == 7 ? n / 4 * 6 : j.prim == 6 ? (n >= 3 ? (n - 2) * 3 : 0) : n, j.cap);\n"
"  if (i == 0) { j.args[0] = m; j.args[1] = j.rec[1]; j.args[2] = 0; j.args[3] = j.rec[3]; j.args[4] = j.rec[4]; }\n"
"  if (i >= m) return;\n"
"  uint t = i / 3, c = i % 3, p = j.prim == 7 ? t / 2 * 4 + (c ? c + (t & 1) : 0) : j.prim == 6 ? (c ? t + c : 0) : i, x = j.rec[2] + p;\n"   // quads (q, q+1+h, q+2+h), fans (0, t+1, t+2), as the CPU expansion in draw
"  j.out[i] = (ulong)x * j.isz + j.isz > j.ilen ? 0u : j.isz == 1 ? uint(j.ib[x]) : j.isz == 2 ? uint(((device const ushort *)j.ib)[x]) : ((device const uint *)j.ib)[x]; }\n";
static int ixc_wanted(const p_draw *dw, const p_draw_idx *di) {
    if (dw) return dw->ind && (dw->prim == 6 || dw->prim == 7 || dw->prim == DM_PRIM_MESH_TASKS);   // and NVN2 DrawMeshTasksIndirect (nvn_geometry.inc mesh_tasks_draw)
    return di->ind && (di->prim == 6 || di->prim == 7 || di->itype == 0);
}
static const ixc_ent *ixc_find(const p_draw *dw, const p_draw_idx *di) {
    if (g_ixc_epoch != g_wr_epoch || g_ixc_sub != g_arena_gen) return NULL;
    uint64_t ind = dw ? dw->ind : di->ind, ib = dw ? 0 : di->ibuf; int prim = dw ? dw->prim : di->prim, it = dw ? -1 : di->itype;
    for (int i = 0; i < g_ixc_n; i++) if (g_ixc[i].ind == ind && g_ixc[i].ibuf == ib && g_ixc[i].prim == prim && g_ixc[i].itype == it) return &g_ixc[i];
    return NULL;
}
static void ixc_take(const p_draw *dw, const p_draw_idx *di) {
    if (g_ixc_n < IXC_MAX && !ixc_find(dw, di)) g_ixc[g_ixc_n++] = (ixc_ent){dw ? dw->ind : di->ind, dw ? 0 : di->ibuf, dw ? dw->prim : di->prim, dw ? -1 : di->itype, 0, 0, 0};
}
static void ixc_run(const p_draw *dw, const p_draw_idx *di) {
    static id<MTLComputePipelineState> ps[2]; static id at; static int failed;
    if (failed) return;
    if (!at) { NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:@(k_ixc_msl) options:nil error:&e];
        for (int k = 0; k < 2 && lib; k++) { id<MTLFunction> f = [lib newFunctionWithName:k ? @"ixc_expand" : @"ixc_arrays"]; ps[k] = f ? [g_dev newComputePipelineStateWithFunction:f error:&e] : nil; }
        at = ps[0] && ps[1] ? rec_table(tab_new(1, 0, 0, &e)) : nil;
        if (!at) { failed = 1; MLOG("【红】 indirect draw conversion: cannot create the compute pipeline %s (indirect draws of quads / fans / 8-bit indices are skipped)", e.localizedDescription.UTF8String); return; } }
    if (g_ixc_epoch != g_wr_epoch || g_ixc_sub != g_arena_gen || g_ixc_n > IXC_MAX - 8) { g_ixc_n = 0; g_ixc_epoch = g_wr_epoch; g_ixc_sub = g_arena_gen; }
    int n0 = g_ixc_n; ixc_take(dw, di);
    if (g_exec_next && g_ret_n <= 8) {   // Later draws in replay order (current list → callers → the rest of this submission), up to the next buffer write
        fz_cursor cur = fz_cursor_from_exec();
        const uint8_t *q; op_hdr h; const void *a;
        for (int guard = 0; guard < 200000 && g_ixc_n < IXC_MAX && fz_next(&cur, &q, &h, &a); guard++) {
            if (h.op == OP_DISPATCH || h.op == OP_COPY_B2B || h.op == OP_UPDATE_UB || h.op == OP_CLEAR_BUF || h.op == OP_COPY_T2B) break;
            p_draw dt; p_draw_idx it; const p_draw *d = h.op == OP_DRAW ? draw_rec(a, h.size, &dt) : NULL; const p_draw_idx *x = h.op == OP_DRAW_IDX ? draw_idx_rec(a, h.size, &it) : NULL;
