}
// A large indirect-count multi-draw (OP_MULTI_DRAW; upstream reference implementation, MIT, c7ba23df): one record whatever the maximum. Through the GPU mask (mdx_run) in batches with a
//   table fresh for this range, no CPU wait. Coincident records (stride 0) need a different predicate at each index and the conversion paths (quads, fans, 8-bit indices) a resolved
//   count; beyond the mask table's capacity the count is read once too, so an INT_MAX maximum with a few live draws neither allocates nor encodes billions of masked draws
int nvn_be_multi_draw_range(void) { return 1; }   // hle_nvn.c records a large call as one OP_MULTI_DRAW (draw_multi replays it)
int nvn_be_buf_extent_consumer(void) { return 0; }   // Metal 回放不按地址查活缓冲长度：hle_nvn.c 不登记活缓冲（建删零开销）
static void draw_multi(const p_multi_draw *m) {
    if (!m->cnt || m->max <= 0) return;
    ubd_land();   // a deferred inline update can feed the count or any record in the range
    p_draw arr = {.prim = m->prim, .instances = 1, .ind = m->ind, .mdi_cnt = m->cnt};
    p_draw_idx idx = {.prim = m->prim, .itype = m->itype, .instances = 1, .ibuf = m->ibuf, .ind = m->ind, .mdi_cnt = m->cnt};
    p_draw *dw = m->itype < 0 ? &arr : NULL; p_draw_idx *di = dw ? NULL : &idx;
