// S2Arm: draws the game issued that were dropped (docs/设计_双轨.md §11.3 picture check, graphics/nvn/host/pic_watch.inc): feat = a feature the host lacks (geometry capture limits, transform
// feedback it cannot capture, DrawTransformFeedback), err = no render pipeline, the pass did not begin, no program. Benign skips (rasterizer discard, both faces culled, empty scissor) are not counted
static _Atomic uint64_t g_bad_feat, g_bad_err;
void nvn_be_bad_draw_feat(void) { atomic_fetch_add_explicit(&g_bad_feat, 1, memory_order_relaxed); }
void mtl_bad_draws(uint64_t *feat, uint64_t *err) { *feat = atomic_load_explicit(&g_bad_feat, memory_order_relaxed); *err = atomic_load_explicit(&g_bad_err, memory_order_relaxed); }
#define BAD_ERR() atomic_fetch_add_explicit(&g_bad_err, 1, memory_order_relaxed)
// ---------- Transform feedback ----------
// A draw under rasterizer discard rasterizes nothing; with feedback active it captures its vertex shader's outputs into the bound feedback buffers. Pokémon Legends: Z-A skins its characters
// so: a vertex-only skinning program writes positions (12 bytes a vertex) and packed normal / tangent bits (4 bytes each), and the character draws read those buffers as vertex streams.
// Metal has no feedback stage: the shader's main0_tf entry point (dmsh_build.py vs_tf) runs in a pipeline with rasterization off, in an encoder of its own with no attachments (the game draws
// these while its frame target is bound; a pass of that target would load and store it for nothing), and stores the outputs at TF_SLOT + b. Each draw writes from the buffer's current offset on.
// Only plain array draws are captured (all this game makes); the encoder's barriers order the writes before the draws that read them
enum { TF_SLOT = 8 };   // = dmsh_build.py TF_SLOT
static __unsafe_unretained id<MTLRenderPipelineState> tf_pso(NvShader *vs) {
    pso_key k; static const uint32_t cf[8]; pso_key_fill(&k, vs, nil, cf, 0, 0, 1, 0); k.fsfn = TF_MARK;
    __unsafe_unretained id<MTLRenderPipelineState> cached = hm_get_id(&g_pso, &k);
    if (cached) return cached;
    if (hm_get_id(&g_pso_fail, &k)) return nil;
    NSError *e = nil; id<MTLRenderPipelineState> ps = [g_dev newRenderPipelineStateWithDescriptor:pso_desc(&k, vs, nil, nil, 0) error:&e];
    if (!ps) { MLOG("【红】 failed to create the transform feedback pipeline (vertex %s): %s", vs->key, e.localizedDescription.UTF8String); hm_put_id(&g_pso_fail, &k, NSNull.null); return nil; }
    hm_put_id(&g_pso, &k, ps);
    return ps;
}
// Instanced draws capture one instance at a time (the feedback stage writes instance j's vertices after instance j - 1's). Indexed draws capture each index in draw order: the
// vertex function runs over the index range [lo, hi] into scratch (store slot = vertex id - lo), and a gather kernel (tf_gather) copies the records in index order into the
// feedback buffers; Metal gives a vertex function no ordinal of its index and may share one invocation among repeated indices, so the index list cannot drive the stores itself
static void tf_draw(NvProg *pr, const p_draw *dw, const p_draw_idx *di) {
    __unsafe_unretained NvShader *vs = pr ? pr->sh[0] : nil;
    if (!S.tf_on) { PD("Z %llu draw skipped: rasterizer discard (vertex %s%s)", g_stat_pass + !g_enc, vs ? vs->key : "-", shader_writes(vs) ? ", writes storage" : ""); return; }
    if (S.tf_gpu) { nvn_be_bad_draw_feat(); RED_ONCE(126, "transform feedback: a vertex shader capture after a geometry shader capture in the same Begin (vertex %s): the offset is on the GPU only, not captured", vs ? vs->key : "-"); return; }
    if (!vs || !vs->tf_fn) { nvn_be_bad_draw_feat(); RED_ONCE(100, "transform feedback with vertex shader %s, which has no capture entry point: nothing captured", vs ? vs->key : "-"); return; }
    int prim = dw ? dw->prim : di ? di->prim : 0;
    if ((!dw && !di) || (dw && (dw->ind || dw->mdi_cnt)) || (di && (di->ind || di->mdi_cnt)) || prim == 6 || prim == 7) {
        nvn_be_bad_draw_feat(); RED_ONCE(101, "transform feedback draw that is indirect or a fan / quad list (vertex %s): not captured", vs->key); return; }
    int count = dw ? dw->count : di->count; uint32_t inst = (uint32_t)MAX(dw ? dw->instances : di->instances, 1), base_inst = (uint32_t)(dw ? dw->base_instance : di->base_instance);
    if (count <= 0) return;
