        if (lib) gather = [g_dev newComputePipelineStateWithFunction:[lib newFunctionWithName:@"tf_gather"] error:&e];
        if (!gather) { free(order); nvn_be_bad_draw_feat(); RED_ONCE(125, "transform feedback gather kernel: %s", e.localizedDescription.UTF8String); return; } }
