    { static int once; if ((di || inst > 1) && !once++) MLOG("transform feedback: first %s capture (vertex %s, %d %s × %u instances)", di ? "indexed" : "instanced", vs->key, count, di ? "indices" : "vertices", inst); }
    PD("T %llu tf capture vs=%s first=%lld count=%d instances=%u indexed=%d written %llu/%llu/%llu/%llu", g_stat_pass, vs->key, (long long)first, count, inst, di != NULL,
