static void noload_witness(int i, int wwhy, int prec) {   // see g_nlw
    if (i < 0 || i >= SD_MAX) return;
    nl_wit *w = &g_nlw[i]; memset(w, 0, sizeof *w);
    w->pass = g_stat_pass; w->draw = g_stat_draw; w->wwhy = (uint8_t)wwhy; w->prec = (uint8_t)prec; w->geo = g_geo_program != nil; w->run = (uint8_t)g_gr.active; w->wd = g_wd; w->wdm = g_wd_mode;
    __unsafe_unretained NvProg *pr = g_geo_program ? g_geo_program : S.prog ? prog_peek(S.prog) : nil, *gp = S.prog ? prog_peek(S.prog) : nil;   // drawing program; the geometry stage is the bound program's
    snprintf(w->vs, sizeof w->vs, "%s", pr && pr->sh[0] ? pr->sh[0]->key : "-"); snprintf(w->fs, sizeof w->fs, "%s", pr && pr->sh[1] ? pr->sh[1]->key : "-");
    snprintf(w->gs, sizeof w->gs, "%s", gp && gp->sh[2] ? gp->sh[2]->key : "-");
}

// Lazy clears. A set of targets that gets only clears before the game sets other targets used to open a pass just to land them (rp_flush), storing the cleared attachments, and the next
// pass that attached them loaded them back. Breath of the Wild clears its G-buffer one target at a time (depth with the lighting target, then albedo, normals, the fourth), then attaches all
// five: four passes stored 27 MB of cleared memory at 1600x900 and the G-buffer pass loaded it again. Such clears now wait (g_lc): the next pass that attaches the same texture level and
// layer through the same view takes the clear as its load action. The rest land as before, in order, each in a pass of its own (lc_land), before anything else could see their textures: a
// draw whose program samples one, the pass of a draw that does not attach it (before that pass opens), and any operation other than targets, clears, state, uniform updates and buffer
// copies or fills, and the end of a command list (not of a sub-list it calls). A newer clear of the same subresource replaces an older one. Also on in TBDR mode (see ubd_on): hoisting takes the clear-only passes it proves, the rest wait here.
// DM_NVN_LAZY_CLEAR=0 turns it off
typedef struct { p_set_rt rt; uint8_t clear_c[8]; MTLClearColor cc[8]; uint8_t clear_d, clear_s; double cd; uint32_t cs; } lc_group;
enum { LC_MAX = 8 };
static lc_group g_lc[LC_MAX]; static int g_nlc;
static uint64_t g_lc_taken, g_lc_landed;   // clears a later pass took as its load action / clear-only passes still opened for them (the residency set line)
void nvn_be_lc_stats(uint64_t *taken, uint64_t *landed) { *taken = g_lc_taken; *landed = g_lc_landed; }
static int lc_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_LAZY_CLEAR"); v = !(e && !strcmp(e, "0")); if (!v) MLOG("DM_NVN_LAZY_CLEAR=0: clears with no draw open a pass of their own as before"); } return v; }
static int lc_same(const p_set_rt *a, int ka, const p_set_rt *b, int kb) {   // the same subresource through the same view (k = 8: depth / stencil)
    uint64_t s1, s2; int l1, l2, x1, x2; rt_sub(a, ka, &s1, &l1, &x1); rt_sub(b, kb, &s2, &l2, &x2);
    if (!s1 || s1 != s2 || l1 != l2 || x1 != x2) return 0;
    int h1 = ka == 8 ? a->has_dview : a->has_cview[ka], h2 = kb == 8 ? b->has_dview : b->has_cview[kb];
    return h1 == h2 && (!h1 || !memcmp(ka == 8 ? &a->dview : &a->cview[ka], kb == 8 ? &b->dview : &b->cview[kb], sizeof(view_t)));
}
// Land every waiting clear, oldest first, each group in a pass of its own (rp_flush's way)
static void lc_land(void) {
    if (!g_nlc) return;
    if (g_enc) rp_end();
    int n = g_nlc; g_nlc = 0;
    typeof(R) save = R;
    for (int gi = 0; gi < n; gi++) { const lc_group *g = &g_lc[gi]; int any = g->clear_d || g->clear_s; for (int i = 0; i < 8; i++) any |= g->clear_c[i];
        if (!any || !g_cb) continue;
        R.rt = g->rt; R.has_rt = 1; memcpy(R.clear_c, g->clear_c, sizeof R.clear_c); memcpy(R.cc, g->cc, sizeof R.cc);
        R.clear_d = g->clear_d; R.clear_s = g->clear_s; R.cd = g->cd; R.cs = g->cs;
        rp_begin_ex(1); rp_end(); g_lc_landed++; }
    R = save;
}
// SetRenderTargets with clears pending and no draw since: the clears wait instead of opening a pass
static void lc_push(void) {
    if (g_nlc == LC_MAX) lc_land();
    lc_group *g = &g_lc[g_nlc];
    g->rt = R.rt; memcpy(g->clear_c, R.clear_c, sizeof g->clear_c); memcpy(g->cc, R.cc, sizeof g->cc); g->clear_d = R.clear_d; g->clear_s = R.clear_s; g->cd = R.cd; g->cs = R.cs;
    for (int gi = 0; gi < g_nlc; gi++) { lc_group *o = &g_lc[gi];   // older clears of the same subresources are overwritten
        for (int i = 0; i < 8; i++) if (o->clear_c[i]) for (int j = 0; j < 8; j++) if (g->clear_c[j]) { uint64_t s1, s2; int l1, l2, x1, x2; rt_sub(&o->rt, i, &s1, &l1, &x1); rt_sub(&g->rt, j, &s2, &l2, &x2);
            if (s1 && s1 == s2 && l1 == l2 && x1 == x2) { o->clear_c[i] = 0; break; } }
        if ((o->clear_d || o->clear_s) && (g->clear_d || g->clear_s)) { uint64_t s1, s2; int l1, l2, x1, x2; rt_sub(&o->rt, 8, &s1, &l1, &x1); rt_sub(&g->rt, 8, &s2, &l2, &x2);
            if (s1 && s1 == s2 && l1 == l2 && x1 == x2) { if (g->clear_d) o->clear_d = 0; if (g->clear_s) o->clear_s = 0; } } }
    g_nlc++;
    memset(R.clear_c, 0, sizeof R.clear_c); R.clear_d = R.clear_s = 0;
}
// Whether the program samples a texture with a waiting clear (a program with bindless or dynamic handles counts as sampling)
static int lc_sampled(NvProg *pr) {
    if (!pr) return 1;
    for (int st = 0; st < 5; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh || sh->stage >= 6) continue;
        if (sh->rf.bindless || sh->rf.dyn) return 1;
        for (int i = 0; i < sh->rf.nb; i++) { const nvn_rbind *b = &sh->rf.b[i]; uint64_t h;
            if (b->kind == NVN_RB_IMG) h = b->reg < 32 ? S.img[sh->stage][b->reg] : 0; else if (b->kind == NVN_RB_TEX || b->kind == NVN_RB_TBUF) h = tex_slot_h(S.tex[sh->stage], S.img[sh->stage], b->reg); else continue;
            uint64_t ser = h ? h_ser(h) : 0; if (!ser) continue;
            for (int gi = 0; gi < g_nlc; gi++) { const lc_group *g = &g_lc[gi];
                for (int k = 0; k < 8; k++) if (g->clear_c[k] && g->rt.color[k] && g->rt.color[k]->serial == ser) return 1;
                if ((g->clear_d || g->clear_s) && g->rt.depth && g->rt.depth->serial == ser) return 1; } } }
    return 0;
}
// The draw about to open a pass: its attachments take the waiting clears of the same subresources (the newest one; the pass's own pending clear is newer still), the rest land first
static void lc_take(NvProg *pr) {
    if (lc_sampled(pr)) { lc_land(); return; }
    for (int gi = g_nlc - 1; gi >= 0; gi--) { lc_group *g = &g_lc[gi];
        for (int i = 0; i < 8; i++) if (g->clear_c[i])
            for (int j = 0; j < R.rt.n && j < 8; j++) if (R.rt.color[j] && !rt_dup_slot(&R.rt, j) && !nvn_fmt_bc(R.rt.color[j]->d.format) && lc_same(&g->rt, i, &R.rt, j)) {
                if (!R.clear_c[j]) { R.clear_c[j] = 1; R.cc[j] = g->cc[i]; }
                g->clear_c[i] = 0; g_lc_taken++; break; }
        if ((g->clear_d || g->clear_s) && R.rt.depth && lc_same(&g->rt, 8, &R.rt, 8)) {
            if (g->clear_d) { if (!R.clear_d) { R.clear_d = 1; R.cd = g->cd; } g->clear_d = 0; }
            if (g->clear_s) { if (!R.clear_s) { R.clear_s = 1; R.cs = g->cs; } g->clear_s = 0; }
            g_lc_taken++; } }
    lc_land();
}
// The operations a waiting clear can wait across: they neither read nor write textures
static int lc_keeps(uint32_t op) {
    switch (op) {
        case OP_SET_RT: case OP_CLEAR_COLOR: case OP_CLEAR_DS: case OP_DRAW: case OP_DRAW_IDX: case OP_BEGIN: case OP_JUMP: case OP_CALL:
        case OP_SCISSOR: case OP_BIND_PROGRAM: case OP_BIND_STATE: case OP_BIND_VATTR: case OP_BIND_VSTREAM: case OP_BIND_VBUF:
        case OP_BIND_UBO: case OP_BIND_SSBO: case OP_BIND_TEX: case OP_BIND_TEX1: case OP_BIND_SAMP: case OP_BIND_IMG: case OP_STENCIL:
        case OP_POLY_OFFSET: case OP_VIEWPORTS: case OP_DEPTH_RANGE: case OP_DEPTH_CLAMP: case OP_VP_SWIZZLE: case OP_BLEND_COLOR:
        case OP_TF_BIND: case OP_TF_STATE: case OP_RAST_DISCARD: case OP_PRIM_RESTART: case OP_SET_PATCH_SIZE: case OP_ALPHA_REF: case OP_BARRIER: case OP_SET_TEX_POOL: case OP_SET_SAMP_POOL: case OP_RENDER_COND:
        case OP_UPDATE_UB: case OP_COPY_B2B: case OP_CLEAR_BUF: return 1;
        default: return 0;
    }
}

// Depth-stencil state, stencil reference, viewport, scissor, cull / winding / fill / bias / depth clip, blend colour: everything a draw sets on its encoder besides the pipeline,
// the vertex buffers and the arguments. Shared by draw and the tessellation render pass (tess_draw ④, whose vertex stage is the domain shader): the same game state applies to both.
// → 0 when nothing of this draw can be drawn (empty scissor, both faces culled); the caller skips it.
// Gap family 34: an alpha-tested fragment variant (pso_key.at, fs_atms_fn) reads the reference at fragment slot 30 (Dsh.cs FsAlphaMs s2a_aref). The value is command-buffer state
//   (SetAlphaRef, OP_ALPHA_REF), written per draw through the argument table (the deferred encoder records table writes, no new encoder method); draws without the test bind nothing
static void alpha_ref_bind(id en, NvShader *fs) {
    int af = (int)S.color.alpha_func; if (!fs || !fs->has_atms || af < 1 || af > 7) return;
    id<MTLBuffer> b; size_t o = arena_alloc(sizeof S.alpha_ref, &b); memcpy((uint8_t *)b.contents + o, &S.alpha_ref, sizeof S.alpha_ref);
    enc_r_args(en, MTLRenderStageFragment, b.gpuAddress + o, 30);
}
static int draw_pass_state(id en, NvShader *fs) {   // en: the render encoder (typed id: enc_r_dss and friends take the Metal 4 type; naming it here would add an unguarded Metal 4 symbol, tools/avail_count.sh)
    static id<MTLDepthStencilState> cur_ds; static uint64_t cur_ds_pass;
    // Diagnostic DM_NVN_DEPTHOVR=fragment shader key prefix,...: those draws compare depth with ALWAYS, which tells "the depth test rejects every fragment" from "nothing rasterizes" (with DM_NVN_HILITE); unset = unchanged
    static char dko[8][24]; static int ndko = -1;
    if (ndko < 0) { ndko = 0; const char *e = getenv("DM_NVN_DEPTHOVR");
        for (const char *q = e; q && *q && ndko < 8; q = strchr(q, ',') ? strchr(q, ',') + 1 : q + strlen(q)) { size_t n = strcspn(q, ","); if (n > 23) n = 23; memcpy(dko[ndko], q, n); dko[ndko++][n] = 0; } }
    if (ndko) { int ovr = 0; for (int i = 0; i < ndko && fs; i++) ovr |= !strncmp(fs->key, dko[i], strlen(dko[i]));
        unsigned df0 = (unsigned)S.ds.df; if (ovr) S.ds.df = 8; cur_ds = dss_get(g_pass.hd, g_pass.hs); S.ds.df = df0; cur_ds_pass = g_pass.serial; g_dss_dirty = 0; }
    else if (g_dss_dirty || cur_ds_pass != g_pass.serial) { cur_ds = dss_get(g_pass.hd, g_pass.hs); cur_ds_pass = g_pass.serial; g_dss_dirty = 0; }
    if (cur_ds != g_enc_dss) { enc_r_dss(en, cur_ds); g_enc_dss = cur_ds; }
    if (!(g_ed.ok & ED_SREF) || g_ed.sref[0] != S.st_ref[0] || g_ed.sref[1] != S.st_ref[1]) {   // front and back references (audit gap family 36: the back one used to be dropped)
        enc_r_stencil_ref(en, S.st_ref[0], S.st_ref[1]); g_ed.sref[0] = S.st_ref[0]; g_ed.sref[1] = S.st_ref[1]; g_ed.ok |= ED_SREF; }
    // Viewport / scissor (clamped within the target size)
    NSUInteger tw = g_pass.tw, th = g_pass.th;
    { MTLViewport v = S.has_vp ? (MTLViewport){S.vp[0][0], S.vp[0][1], S.vp[0][2], S.vp[0][3], S.dr[0], S.dr[1]} : (MTLViewport){0, 0, tw / g_pass.rs, th / g_pass.rs, 0, 1};   // no viewport: the whole target, in canvas units (internal resolution)
      if (g_wd > 0) { float x = (float)v.originX, w = (float)v.width, r0 = x + w; s2a_widen_map_viewport(g_wd_mode, &x, &w); v.originX = x; v.width = w;
        { float y = (float)v.originY, h = (float)v.height; s2a_widen_map_viewport_y(g_wd_mode, &y, &h); v.originY = y; v.height = h; }   // narrower screen: more picture above and below (s2a_widen_ky > 1)
        if (x + w > (float)(tw / g_pass.rs) + 1.0f && x + w > r0 + 0.5f) RED_ONCE(113, "widen: viewport %.0f+%.0f past the target's storage width %lu (ser=%llu, storage not widened): the right part is clipped (first case)", x, w, (unsigned long)tw,
                                              (unsigned long long)(R.has_rt && R.rt.n > 0 && R.rt.color[0] ? R.rt.color[0]->serial : 0)); }   // S2Arm widen: the storage is narrower than the widened viewport (tex_widen could not widen it); up to a texel over is level rounding: 391 wide, level 2 is 97, 80 x k = 97.75; only past what the game's own viewport reached (Monster Hunter Rise draws a 156-wide viewport on a 78-wide target, widen off as well)
      if (g_pass.rs != 1.0) { v.originX *= g_pass.rs; v.originY *= g_pass.rs; v.width *= g_pass.rs; v.height *= g_pass.rs; }   // S2Arm internal resolution: canvas → storage (nvn_rscale.inc)
      if (atomic_load_explicit(&g_origin_ll, memory_order_relaxed)) { v.originY += v.height; v.height = -v.height; }   // lower-left origin (see g_origin_ll)
      // Viewport swizzle: NEGATIVE_Y negates clip y, the same as the viewport flipped about its centre; facing is decided after it on the GPU as in Metal, so the winding stays.
      // Other swizzles (axis exchanges, negated x / z / w) are no viewport change and are drawn unswizzled
      { uint32_t sw; memcpy(&sw, S.vp_sw[0], 4);
        if (sw == 0x100) { v.originY += v.height; v.height = -v.height; }
        else if (sw) RED_ONCE(108, "viewport swizzle %d,%d,%d,%d not implemented (drawn unswizzled)", S.vp_sw[0][0], S.vp_sw[0][1] ^ 2, S.vp_sw[0][2] ^ 4, S.vp_sw[0][3] ^ 6); }
      if (!(g_ed.ok & ED_VP) || memcmp(&g_ed.vp, &v, sizeof v)) { enc_r_viewport(en, v); g_ed.vp = v; g_ed.ok |= ED_VP; } }
    MTLScissorRect sc = {0, 0, tw, th};
    if (R.has_sc) {
        p_scissor rs = R.sc; if (g_wd > 0) { s2a_widen_map_scissor(g_wd_mode, &rs.x, &rs.w); s2a_widen_map_scissor_y(g_wd_mode, &rs.y, &rs.h); }   // S2Arm widen
        if (g_wd > 0 && wd_tr_on()) MLOG("S2Arm widen trace: frame %llu scissor %d,%d %dx%d -> %d,%d %dx%d mode %d", (unsigned long long)g_wd_frame, R.sc.x, R.sc.y, R.sc.w, R.sc.h, rs.x, rs.y, rs.w, rs.h, g_wd_mode);   // 11-02 怪猎对话框正文被切：剪刀原值 / 换算后对照（追踪行只打视口）
        long sx = rs.x, sy = rs.y, sw = rs.w, sh = rs.h; rs_rect(g_pass.rs, &sx, &sy, &sw, &sh);   // S2Arm internal resolution: canvas → storage
        long x0 = sx < 0 ? 0 : sx, y0 = sy <= 0 ? 0 : sy, x1 = sx + sw, y1 = sy + sh;
        if (x1 > (long)tw) x1 = tw; if (y1 > (long)th) y1 = th;
        if (x1 <= x0 || y1 <= y0) { PD("Z %llu draw skipped: empty scissor (%d,%d %dx%d, target %lux%lu)", g_stat_pass, rs.x, rs.y, rs.w, rs.h, (unsigned long)tw, (unsigned long)th); return 0; }
        sc = (MTLScissorRect){(NSUInteger)x0, (NSUInteger)y0, (NSUInteger)(x1 - x0), (NSUInteger)(y1 - y0)};
    }
    if (!(g_ed.ok & ED_SC) || memcmp(&g_ed.sc, &sc, sizeof sc)) { enc_r_scissor(en, sc); g_ed.sc = sc; g_ed.ok |= ED_SC; }
    if (S.poly.cull == NVN_FACE_FRONT_AND_BACK) { PD("Z %llu draw skipped: both faces culled", g_stat_pass); return 0; }
    { int cu = S.poly.cull == NVN_FACE_FRONT ? MTLCullModeFront : S.poly.cull == NVN_FACE_BACK ? MTLCullModeBack : MTLCullModeNone;
      // Front face: the game's own driver writes the API value into the front-face register and sets Maxwell's TriangleRastFlip once, in QueueInitialize, when the device's
      //   window origin is not upper-left at that moment (s2a_nvn_rast_flip, hle_nvn.c). Ryujinx keeps the register with the flip on and swaps it with the flip off
      //   (StateUpdater.UpdateFrontFace), and its Metal backend inverts it: Metal gets the inverse of the API value with the flip on, the API value with it off.
      //   Measured in the generic mode: Need for Speed Hot Pursuit Remastered (queue created before it set upper-left: flip on, front CW) and Diablo III (upper-left first:
      //   flip off, front CCW) both end at counter-clockwise. This used to follow the current window origin, the same thing for games that set it before creating the queue;
      //   Need for Speed got its front faces culled and drew car and track black (tests/t_nvn_winding.m)
      int wi = (S.poly.front == NVN_FRONT_FACE_CCW) != (s2a_nvn_rast_flip != 0) ? MTLWindingCounterClockwise : MTLWindingClockwise;
      int fi = S.poly.mode == NVN_POLYGON_MODE_LINE ? MTLTriangleFillModeLines : MTLTriangleFillModeFill, cl = !S.depth_clamp;   // depth clip off = SetDepthClamp
      float bi[3] = {0, 0, 0}; if (S.poly.offset_en & 4) { bi[0] = S.po.units; bi[1] = S.po.factor; bi[2] = S.po.clamp; }
      if (!(g_ed.ok & ED_CULL) || g_ed.cull != cu) { enc_r_cull(en, (MTLCullMode)cu); g_ed.cull = cu; g_ed.ok |= ED_CULL; }
      if (!(g_ed.ok & ED_WIND) || g_ed.wind != wi) { enc_r_winding(en, (MTLWinding)wi); g_ed.wind = wi; g_ed.ok |= ED_WIND; }
      if (!(g_ed.ok & ED_FILL) || g_ed.fill != fi) { enc_r_fill(en, (MTLTriangleFillMode)fi); g_ed.fill = fi; g_ed.ok |= ED_FILL; }
      if (!(g_ed.ok & ED_BIAS) || memcmp(g_ed.bias, bi, sizeof bi)) { enc_r_depth_bias(en, bi[0], bi[1], bi[2]); memcpy(g_ed.bias, bi, sizeof bi); g_ed.ok |= ED_BIAS; }
      if (!(g_ed.ok & ED_CLIP) || g_ed.clip != cl) { enc_r_depth_clip(en, cl); g_ed.clip = cl; g_ed.ok |= ED_CLIP; }
      if (!(g_ed.ok & ED_BLEND) || memcmp(g_ed.blend, S.blend_color, sizeof g_ed.blend)) { enc_r_blend_color(en, S.blend_color[0], S.blend_color[1], S.blend_color[2], S.blend_color[3]); memcpy(g_ed.blend, S.blend_color, sizeof g_ed.blend); g_ed.ok |= ED_BLEND; } }
    return 1;
}
// S2Arm tessellation: 曲面绘制（prim == 14 patches）
// 四段流程：①VS 捕获（光栅关的渲染遍跑 main0_gs，写 144 字捕获记录）+ 搬运核（按映射 / 规范布局搬成 TCS 输入） ②TCS（计算核）→曲面因子+域控制点 ③固定核（count/scan/emit）→域点+索引 ④渲染pass（TES顶点+fragment）
// ① 照 nvn_geometry.inc geo_draw：槽 13 绑捕获信息块 {输入缓冲地址, 0, first, span, first_instance, instances}（dmsh_geometry.py dm_geometry_capture），间接参数与索引在 CPU 上读（先等 GPU 写完），
//   索引去重排序后画点，第 i 个控制点 = 捕获里的 索引[i] − lo（nvn_builtin.h nvn_tess_index_plan）；搬运核 nvn_tess_gather 按这张表把控制点搬成规范布局（gal_tessxc.m gal_tess_canon）的连续缓冲，
//   因为捕获记录与 TCS 读的规范布局都是 576 字节却排布不同（位置在字 0 对字 128、通用位置在字 16+4L 对 4L），TCS 是离线翻好的核改不了读法
static inline void tess_skipped(void) { g_tess_skips++; g_tess_dom_skips[g_tess_dom]++; }
#define TESS_SKIP(...) do { tess_skipped(); static int n_; if (n_++ < 8) MLOG("【红】 " __VA_ARGS__); } while (0)
static void tess_stat_line(uint64_t frame) {   // 定期（nvn_be_mem_stat）：局里看得到曲面画了 / 跳过多少、各在哪个域；没有曲面绘制不打
    if (!g_tess_draws && !g_tess_skips) return;
    MLOG("tessellation up to frame %llu: drawn %llu (isolines %llu / triangles %llu / quads %llu, %llu patches), skipped %llu (isolines %llu / triangles %llu / quads %llu / undefined domain %llu / before the domain was known %llu)",
         (unsigned long long)frame, (unsigned long long)g_tess_draws, (unsigned long long)g_tess_dom_draws[0], (unsigned long long)g_tess_dom_draws[1], (unsigned long long)g_tess_dom_draws[2],
         (unsigned long long)g_tess_patches, (unsigned long long)g_tess_skips, (unsigned long long)g_tess_dom_skips[0], (unsigned long long)g_tess_dom_skips[1], (unsigned long long)g_tess_dom_skips[2],
         (unsigned long long)g_tess_dom_skips[3], (unsigned long long)g_tess_dom_skips[4]);
}
// hull 核按域载入：dmsh_build.py tess_finish 按域各翻一份 hull（只有域改变翻译：曲面因子的布局与含义），首个域进 <key>_b（宿主载入的 hs->fn），其余域进 <key>_b_t<域>
//   （另一份库，函数即逻辑入口 main0、不并批；容器种类 LP_K_BT + 域，lp_kind_of）；分区 / 绕序 / 点模式由域着色器在运行时交给固定核，不进 hull 的翻译。
//   所以计算管线按域各一份：变体库是 hs 自己就用 hs->fn，否则载那份库的入口。绑定的域没有核（没有该域的变体、库载不进来、管线建不出）或寄存器域值 3（没有定义）返回 nil：
//   这一笔跳过并计数，每个 hull × 域组合报红一次。别的域的核没有一份能证明等价（因子布局随域变），不拿来替（审计 #814 F-tess-dom-first：改前拿 allValues.firstObject 的 flags 与 hs->fn 照画）
static id<MTLComputePipelineState> tess_hull_pso(NvShader *hs, uint32_t dom, NSDictionary **varp) {
    if (dom > 2) {
        if (!(hs->tess_dom_red & 8)) { hs->tess_dom_red |= 8; MLOG("【红】 hull shader %s: the domain shader's tessellation domain code 3 is undefined (0 isolines / 1 triangles / 2 quads); tessellation draws of this pair skipped", hs->key); }
        return nil;
