    if (hs->tess_dom_red & (1u << dom)) return nil;   // 已判过没有：不重载、不重报
    hs->tess_dom_red |= 1u << dom;   // 下面任何一步失败都只报这一次（建成了 tess_pso[dom] 非空，不再走到这里）
    NSString *lib = [var isKindOfClass:[NSDictionary class]] && [var[@"library"] isKindOfClass:[NSString class]] ? var[@"library"] : nil;
    if (!lib) { MLOG("【红】 hull shader %s has no %s-domain kernel (variants: %s); tessellation draws of this pair skipped", hs->key, dn.UTF8String,
                     hs->tess_variants.count ? [hs->tess_variants.allKeys componentsJoinedByString:@" "].UTF8String : "none"); return nil; }
    id<MTLFunction> fn = nil; NSError *e = nil;
    if ([lib isEqualToString:@(hs->key)]) fn = hs->fn;
    else {
