        fn = [l newFunctionWithName:entry];
        if (fn.functionConstantsDictionary.count) fn = [l newFunctionWithName:entry constantValues:[MTLFunctionConstantValues new] error:&e];   // 同 shader_load：声明了函数常量的要先特化
        if (!fn) { MLOG("【红】 hull shader %s: its %s-domain kernel library %s did not load (%s); tessellation draws of this pair skipped", hs->key, dn.UTF8String, lib.UTF8String,
                        l ? [NSString stringWithFormat:@"no function %@", entry].UTF8String : e.localizedDescription.UTF8String); return nil; }
    }
    if (!fn) { MLOG("【红】 hull shader %s has no loaded function for its %s-domain kernel; tessellation draws of this pair skipped", hs->key, dn.UTF8String); return nil; }
    id<MTLComputePipelineState> ps = [g_dev newComputePipelineStateWithFunction:fn error:&e];
    if (!ps) { MLOG("【红】 hull shader %s: %s-domain compute PSO (%s) build failed: %s; tessellation draws of this pair skipped", hs->key, dn.UTF8String, lib.UTF8String, e.localizedDescription.UTF8String); return nil; }
    hs->tess_pso[dom] = ps; *varp = var; return ps;
