    uint32_t N = [var[@"output_control_points"] unsignedIntValue] ?: (hs->tess_ocp ? hs->tess_ocp : 3);   // 输出控制点数：绑定域那份核的（json tess.variants[域].output_control_points），缺省3
    uint32_t prim = ppoint ? 0 : dom == 0 ? 1 : cw ? 2 : 3;   // PIPE_TESSELLATOR_OUTPUT_PRIMITIVE：0点1线2顺时针三角3逆时针三角（同 gal_tess.m）
