    id<MTLRenderPipelineState> capture = geo_capture_pso(vs);   // 失败处已报红
    if (!capture) { free(map); free(unique); TESS_SKIP("vertex capture pipeline for %s not built; patch draw skipped", vs->key); return; }

    // 临时缓冲（随提交回收）：捕获记录、映射表、唯一索引表、捕获信息块、搬运参数、规范布局控制点（TCS 的 IN）
