    id<MTLBuffer> map_buf; size_t map_off = arena_alloc((size_t)Vp * 4, &map_buf); uint64_t map_gpu = map_buf.gpuAddress + map_off; memcpy((uint8_t *)map_buf.contents + map_off, map, (size_t)Vp * 4);
    uint64_t ix_gpu = 0; if (di0) { id<MTLBuffer> ix_buf; size_t ix_off = arena_alloc((size_t)nu * 4, &ix_buf); ix_gpu = ix_buf.gpuAddress + ix_off; memcpy((uint8_t *)ix_buf.contents + ix_off, unique, (size_t)nu * 4); }
