    { id tab = tab_new(8, 0, 0, NULL); tab_addr(tab, params_gpu, 0); tab_addr(tab, cnt_gpu, 2); tab_addr(tab, off_gpu, 3); tab_addr(tab, args_gpu, 4); enc_c_table(ce, tab); }
