    { uint64_t th; uint32_t gr; nvn_tess_patch_grid(Pt, &th, &gr); enc_c_dispatch_threads(ce, MTLSizeMake(th, 1, 1), MTLSizeMake(gr, 1, 1)); }   // 同计数核
    enc_c_end(ce);

