    id en = rp_begin();
    if (!en) { tess_skipped(); static int n; if (n++ < 8) MLOG("【红】 tessellation render pass did not begin; draw skipped"); return; }

    // 渲染管线：顶点阶段是域着色器 pr->sh[4]（不是 sh[0] 的游戏原顶点着色器）。取 sh[0] 会拿曲面前段那支去配读域输出（user(locn)）的片元着色器，
    //   pso_pair_ok 判它不写片元读的位置，管线永远建不出来（巫师3 8 次曲面绘制全跳过，w3tess6b 10-28）
    //   S2Arm #800：片元着色器的归约模拟位同 draw 逐笔取（se_want），换了就换管线、绘制前绑表（se_bind）
    static id<MTLRenderPipelineState> cur_tess_ps; static NvProg *cur_tess_pr; static NvShader *cur_tess_ds; static uint64_t cur_tess_pass; static int cur_tess_fc; static uint8_t cur_tess_round;
    int fc = se_want(pr->gp, fs, 1);
    if (g_pso_dirty || pr != cur_tess_pr || ds != cur_tess_ds || cur_tess_pass != g_pass.serial || fc != cur_tess_fc) {
        g_pso_fc = fc; cur_tess_ps = pso_get_vs(pr, ds); cur_tess_round = g_pso_color_round; g_pso_fc = 0; cur_tess_pr = pr; cur_tess_ds = ds; cur_tess_pass = g_pass.serial; cur_tess_fc = fc; g_pso_dirty = !cur_tess_ps; }
    __unsafe_unretained id<MTLRenderPipelineState> ps = cur_tess_ps;
    if (!ps) { tess_skipped(); static int n; if (n++ < 8) MLOG("【红】 tessellation render pipeline not built (domain %s fragment %s): %s; draw skipped", ds->key, fs->key, g_pso_why);
        PD("Z %llu tessellation draw skipped: no render pipeline", g_stat_pass); return; }

    enc_r_pso(en, ps);
    enc_r_half_mask(en, cur_tess_round);
    // 深度 / 模板 / 视口 / 裁剪 / 剔除 / 绕序 / 填充：① 捕获遍结束时清了编码器状态（g_enc_pso / g_enc_dss 置空、g_ed.ok = 0），新编码器是空状态，
    //   不设就是深度测试关、不写深度。与 draw 同一份规则（draw_pass_state）
    if (!draw_pass_state(en, 0)) { tess_skipped(); PD("Z %llu tessellation draw skipped: empty scissor", g_stat_pass); return; }
    alpha_ref_bind(en, fs);   // gap family 34

    // 域着色器的参数（uniform / 纹理 / 采样器，msl 里 [[buffer(0)]] 的参数缓冲）编进 g_vt 槽 0，曲面接口缓冲走 TESS_BASE+0..5。
    //   只 tab_new(8) 建表写 20–25 是越界的（上限 8），而且换掉整张顶点表会把槽 0 的参数缓冲一起丢掉。
    //   槽位照域着色器的 MSL 实际读数绑：buffer(20) = TCS 输出控制点（spvIn）、buffer(22) = 每片属性（spvPatchIn）、
    //   buffer(24) = 输出控制点数（s2a_ocp）、buffer(25) = 域点（s2a_pts）；21 / 23 三支域着色器都不读，不绑（绑地址 0 在 Metal 3 上每笔报红）
    args_dirty_all(); encode_args(en, ds, 4, 1);
    enc_r_vbuf(en, TESS_BASE + 0, tcs_out_gpu);   // IN: TCS 输出控制点（buffer(20)）
    enc_r_vbuf(en, TESS_BASE + 2, patch_gpu);     // PATCH: 每片属性（buffer(22)，TCS 在 ② 写的那块）
    enc_r_vbuf(en, TESS_BASE + 3, factors_gpu);   // FACTOR: 曲面因子（hull 侧槽位，域着色器不读）
    { uint32_t ocp_val = N; id<MTLBuffer> ocp_buf; size_t ocp_off = arena_alloc(4, &ocp_buf); memcpy((uint8_t *)ocp_buf.contents + ocp_off, &ocp_val, 4);
      enc_r_vbuf(en, TESS_BASE + 4, ocp_buf.gpuAddress + ocp_off); }   // PARAMS: 输出控制点数（buffer(24)）
    enc_r_vbuf(en, TESS_BASE + 5, pts_gpu);       // POINTS: 域点（buffer(25)，TS_POINT 数组）

    // 绑定片元阶段参数（游戏绑定的纹理/采样器/uniform，与普通绘制同一个 encode_args）
    if (fs) encode_args(en, fs, 1, 0);
    if (fc) se_bind(en, fs, 1);   // 采样器模拟变体的表（26 号槽），本笔现填

    // 间接索引绘制：索引缓冲 idx_buf，间接参数 args_buf（indexCount / instanceCount / indexStart / baseVertex / baseInstance）
    MTLPrimitiveType pt = prim == 0 ? MTLPrimitiveTypePoint : prim == 1 ? MTLPrimitiveTypeLine : MTLPrimitiveTypeTriangle;   // 同 gal_tess.m：点 / 等值线 / 三角
    enc_r_draw_indexed_indirect(en, pt, MTLIndexTypeUInt32, idx_gpu, (NSUInteger)(TESS_IX_CAP * 4), args_gpu);

    // 顶点表是共享的：TESS_BASE(20)–25 与普通绘制的顶点流 4–9（VB_SLOT(st) = 16 + st）同号。上面写进去的是本笔的临时缓冲，
    //   本笔结束后改绑零缓冲（没绑顶点流的普通绘制在那里读到 0，与改绑前一样），否则后续绘制会读到已被回收的曲面缓冲地址
    for (int i = TESS_BASE; i < TESS_BASE + 6; i++) enc_r_vbuf(en, i, zero_bank_gpu());

    g_tess_draws++; g_tess_dom_draws[dom]++; g_tess_patches += Pt;
    PD("T %llu tessellation draw: %llu patches (domain %u part %u cw %u point %u, %u control points in, %u out) %s", g_stat_pass, (unsigned long long)Pt, dom, part, cw, ppoint, P, N, di0 ? "indexed" : "array");
    static int once; if (!once++) MLOG("tessellation draw: first patch draw (vertex %s hull %s domain %s, P %u N %u, %llu patches, domain code %u, factor stride %u)", vs->key, hs->key, ds->key, P, N, (unsigned long long)Pt, dom, fstride);
}

static void draw_emit(id en, MTLPrimitiveType mp, int prim, const p_draw *dw, const p_draw_idx *di, uint64_t mdx);
// S2Arm (10-30, Bare Knuckle IV, census c1029c: "NVN unimplemented function called: nvnCommandBufferDrawTexture"): DrawTexture draws a textured rectangle into the bound targets.
//   As Ryujinx (Vulkan PipelineBase.DrawTexture / HelperShader.DrawTexture): the current blend state, channel masks and multisample state stay, culling and the depth / stencil
//   tests are off, the viewport is the destination rectangle (in the game's viewport coordinates, so the widen mapping and the lower-left flip apply as to any viewport,
//   draw_pass_state), the scissor stays, and the source rectangle is sampled with the handle's texture and sampler, normalized by the texture's size as the game created it
//   (a widened texture is addressed as its shaders address it). Only color(0) is written (Ryujinx's colour blit program). The pipeline is keyed as any (pso_key_fill: targets,
//   blend) and kept here; the built-in shaders are not in the library and never reach pso_user.tsv. Integer / depth sources or targets, and non-2D textures, are skipped with one line
static int fmt_int_or_ds(MTLPixelFormat f);
static NvShader *g_dt_vs, *g_dt_fs; static id g_dt_tab;
static void draw_tex(const p_draw_tex *t) {
    g_udc_precise = 0;   // not draw(): its encode marks every attachment of the pass written (udc_encode)
    static int failed, once[6]; static NSMutableDictionary<NSData *, id<MTLRenderPipelineState>> *psos;
    if (failed) return;
    if (!g_dt_vs) {
        static const char *src =
            "#include <metal_stdlib>\nusing namespace metal;\n"
            "struct V { float4 p [[position]]; float2 uv; };\n"
            // a 4-vertex strip over the whole viewport: (0,0) (1,0) (0,1) (1,1), uv (0,0) at the destination's first corner (top on an upper-left origin)
            "vertex V dt_vs(uint id [[vertex_id]]) { float2 c = float2(id & 1, id >> 1); V o; o.p = float4(c.x * 2 - 1, 1 - c.y * 2, 0, 1); o.uv = c; return o; }\n"
            // r = normalized source u0 u1 v0 v1
            "fragment float4 dt_fs(V in [[stage_in]], texture2d<float> t [[texture(0)]], sampler s [[sampler(0)]], constant float4 *r [[buffer(0)]]) {\n"
            "  return t.sample(s, float2(mix(r[0].x, r[0].y, in.uv.x), mix(r[0].z, r[0].w, in.uv.y))); }\n";
        NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:@(src) options:nil error:&e];
        id<MTLFunction> vf = [lib newFunctionWithName:@"dt_vs"], ff = [lib newFunctionWithName:@"dt_fs"];
        g_dt_tab = vf && ff ? rec_table(tab_new(1, 1, 1, &e)) : nil;
        if (!g_dt_tab) { failed = 1; MLOG("【红】 DrawTexture: cannot build its shaders / argument table: %s; DrawTexture draws nothing", e.localizedDescription.UTF8String); return; }
        NvShader *v = [NvShader new], *f = [NvShader new];
        v->fn = vf; v->stage = 0; strlcpy(v->key, "s2a_drawtex_vs", sizeof v->key);
        f->fn = ff; f->stage = 1; strlcpy(f->key, "s2a_drawtex_fs", sizeof f->key); f->rf.color_known = 1; f->rf.color_mask = 1;   // writes color(0) only (pso_key_norm / pso_desc: the rest masked)
        g_dt_vs = v; g_dt_fs = f; psos = [NSMutableDictionary dictionary];
    }
    int tid = (int)(t->handle & 0xfffff), sid = (int)(t->handle >> 20);
    pthread_mutex_lock(&g_rmu);
    id<MTLTexture> tx = tex_by_id(tid); id<MTLSamplerState> sp = samp_by_id(sid);
    float gw = tid >= 0 && tid < g_ntreg ? (float)g_treg[tid].t.d.width : 0, gh = tid >= 0 && tid < g_ntreg ? (float)g_treg[tid].t.d.height : 0;
    pthread_mutex_unlock(&g_rmu);
    if (!once[0]++) MLOG("DrawTexture: first call: texture %d sampler %d, destination %g,%g → %g,%g, source %g,%g → %g,%g (texture %gx%g)", tid, sid, t->dst[0], t->dst[1], t->dst[2], t->dst[3],
                         t->src[0], t->src[1], t->src[2], t->src[3], gw, gh);
    if (!tx || !sp) return;   // the lookups said why (texture / sampler ID not registered)
    int own_view = tx.textureType == MTLTextureType2DArray;   // layer 0 as a 2D view (made here, kept until the submission has run)
    if (own_view) tx = [tx newTextureViewWithPixelFormat:tx.pixelFormat textureType:MTLTextureType2D levels:NSMakeRange(0, tx.mipmapLevelCount) slices:NSMakeRange(0, 1)];
    if (!tx || tx.textureType != MTLTextureType2D || fmt_int_or_ds(tx.pixelFormat)) {
        if (!once[1]++) MLOG("【红】 DrawTexture: source texture %d (type %lu, format %lu) is not a 2D colour texture with float reads: not drawn (first case)", tid, (unsigned long)tx.textureType, (unsigned long)tx.pixelFormat);
        return; }
    if (gw <= 0 || gh <= 0) { gw = (float)tx.width; gh = (float)tx.height; }
    float x0 = t->dst[0], y0 = t->dst[1], x1 = t->dst[2], y1 = t->dst[3];
    if (x0 == x1 || y0 == y1) return;   // an empty rectangle draws nothing
    float r[4] = {t->src[0] / gw, t->src[2] / gw, t->src[1] / gh, t->src[3] / gh};
    if (x1 < x0) { float q = r[0]; r[0] = r[1]; r[1] = q; }   // a mirrored destination walks the source the other way (Ryujinx)
    if (y1 < y0) { float q = r[2]; r[2] = r[3]; r[3] = q; }
    if (g_enc && g_pass.layered) rp_end();
    id en = rp_begin_ex(0);   // plain id as in draw(): the encoder is a Metal 3 one on NXGAL_BE=mtl3 (mtl4_count ratchet)
    if (!en) return;   // rp_begin_ex said why
    if (pf_int_kind((MTLPixelFormat)g_pass.cfmt[0]) || !g_pass.cfmt[0]) {
        if (!once[2]++) MLOG("【红】 DrawTexture: target 0 is %s (format %u): not drawn (first case)", g_pass.cfmt[0] ? "an integer target" : "not bound", g_pass.cfmt[0]);
        return; }
    pso_key k; pso_key_fill(&k, g_dt_vs, g_dt_fs, g_pass.cfmt, g_pass.dfmt, g_pass.sfmt, g_pass.samples, 0);
    NSData *kd = [NSData dataWithBytes:&k length:sizeof k];
    id<MTLRenderPipelineState> ps = psos[kd];
    if (!ps) {
        NSError *e = nil; ps = [g_dev newRenderPipelineStateWithDescriptor:pso_desc(&k, g_dt_vs, g_dt_fs, nil, 0) error:&e];
        if (!ps) { if (!once[3]++) MLOG("【红】 DrawTexture: pipeline for target format %u failed: %s (first case)", g_pass.cfmt[0], e.localizedDescription.UTF8String); return; }
        psos[kd] = ps;
    }
    // The destination as the viewport, no culling, no depth / stencil test: the game's state is put back right after (the next draw sets its own through g_ed / g_dss_dirty)
    ds_st ds0 = S.ds; poly_st po0 = S.poly; int hv0 = S.has_vp; float vp0[4], dr0[2]; uint8_t sw0[4];
    memcpy(vp0, S.vp[0], sizeof vp0); memcpy(dr0, S.dr, sizeof dr0); memcpy(sw0, S.vp_sw[0], sizeof sw0);
    S.ds.dt = S.ds.dw = S.ds.st = 0; S.poly.cull = NVN_FACE_NONE; S.has_vp = 1;
    S.vp[0][0] = MIN(x0, x1); S.vp[0][1] = MIN(y0, y1); S.vp[0][2] = fabsf(x1 - x0); S.vp[0][3] = fabsf(y1 - y0); S.dr[0] = 0; S.dr[1] = 1; memset(S.vp_sw[0], 0, sizeof sw0);
    g_dss_dirty = 1;
    int drawn = draw_pass_state(en, nil);
    S.ds = ds0; S.poly = po0; S.has_vp = hv0; memcpy(S.vp[0], vp0, sizeof vp0); memcpy(S.dr, dr0, sizeof dr0); memcpy(S.vp_sw[0], sw0, sizeof sw0);
    g_dss_dirty = 1;
    if (!drawn) return;   // empty scissor
    id<MTLBuffer> pb; size_t po = arena_alloc(16, &pb);
    if (!pb) return;
    memcpy((uint8_t *)pb.contents + po, r, sizeof r);
    enc_r_pso(en, ps); g_enc_pso = ps; g_pso_dirty = 1;
    enc_r_table(en, g_dt_tab, MTLRenderStageFragment);
    tab_tex(g_dt_tab, tx, 0); tab_samp(g_dt_tab, sp, 0); tab_buf(g_dt_tab, pb, po, 0);
    enc_r_draw(en, MTLPrimitiveTypeTriangleStrip, 0, 4);
    args_dirty_all();   // the fragment table above replaced the game's: the next draw binds its own again
    g_stat_draw++;
    if (own_view) defer_obj_unref(tx);
}
// 本笔的宽屏状态：每条要上屏的编码路径（常规 draw、几何 geo_draw、曲面细分 tess_draw）在编码参数前为自己的程序算一次，不沿用上一笔的（g_wd_gpu 改写副本、g_wd_push 外推量、
//   g_wd_inst）。只产出数据、不上屏的路径（sx_draw、tf_draw）用 wd_drop。11-01：几何 / 曲面细分原先分叉在 wd_draw 之前，顶点捕获、几何计算、曲面各阶段都绑着上一笔的副本
static void draw_widen(NvProg *pr, const p_draw *dw, const p_draw_idx *di) {
    memset(g_wd_push, 0, sizeof g_wd_push);   // S2Arm widen edge push: unpushed unless wd_draw sets it
    g_wdg_dw = dw; g_wdg_di = di; g_wdg_pr = pr;   // for wd_geom_cb (the widen core asks back on shrink candidates)
    if (wd_on() > 0) { g_wd_inst = dw && !dw->ind ? dw->instances : di && !di->ind ? di->instances : 0; g_wd_vc = dw && !dw->ind ? dw->count : di && !di->ind ? di->count : 0; wd_draw(pr); }   // this draw's mode and rewritten uniforms; g_wd_inst: its instance count when known on the CPU (indirect: 0 = unknown)
}
// 原始内存池表的动态占比（11-07 卡顿线，维护者：常驻轻量计数、只计不改行为）：真正编码的绘制 / 派发里，绑了池表（NVN_RB_GMEM，翻译器追不到来源、
//   按地址查宿主池表）的程序占多少。着色器绑没绑池表在第一次用到时扫一遍反射记在 gmem_use，之后只读标记。周期资源计数行行尾 gmem_draws / gmem_dispatches 报「用到 / 总数」
static int gmem_uses(NvShader *s) {
    if (!s) return 0;
    if (!s->gmem_use) { s->gmem_use = 1; for (int i = 0; i < s->rf.nb; i++) if (s->rf.b[i].kind == NVN_RB_GMEM) { s->gmem_use = 2; break; } }
    return s->gmem_use == 2;
}
static void gmem_count_draw(NvProg *pr) { g_gmem_draws_all++; for (int i = 0; i < 5; i++) if (gmem_uses(pr->sh[i])) { g_gmem_draws++; break; } }

static void draw(const p_draw *dw, const p_draw_idx *di) {
    if (dw && dw->prim == DM_PRIM_MESH_TASKS && !g_mtk.on) { mesh_tasks_draw(dw); return; }   // NVN2 task / mesh draw: binds its stages and comes back with its pixel stage (nvn_geometry.inc)
    g_udc_precise = 0;   // only this draw's own udc_note_draw may cover its encode (a draw that returned without encoding leaves no stale cover)
    g_udc_lmap = NULL; g_udc_fsfn = 0;   // the output map is this draw's own too: the one a previous (on-chip read / merged) draw used must not judge the next pass's lookahead (pass_color_unwritten) or a geometry / tessellation draw's writes (11-06 TotK: tiled lights black outside the lit tiles)
    g_draw_binst = (uint32_t)(dw ? dw->base_instance : di ? di->base_instance : 0);   // c0 + 0x644 of the stages that read the driver segment (encode_args)
    if (!g_geo_program && S.prog) {
        NvProg *geometry_program = prog_get(S.prog);
        if (geometry_program && geometry_program->sh[2] && geometry_program->sh[2]->geo_vertices) {
            if ((dw && dw->mdi_cnt && !mdi_live(dw->mdi_cnt, dw->mdi_i)) || (di && di->mdi_cnt && !mdi_live(di->mdi_cnt, di->mdi_i))) return;
            draw_widen(geometry_program, dw, di); geo_draw(geometry_program, dw, di); return;
        }
    }
    if (!g_geo_program) geo_run_flush();   // any other draw ends a geometry run (nvn_geometry.inc ①)
    int mdx_on = (dw && dw->mdi_cnt) || (di && di->mdi_cnt) ? mdx_wanted(dw, di) : 0;   // an indirect-count multi-draw's record masked on the GPU (mdx_run), else read after a wait
    if (!mdx_on && ((di && di->mdi_cnt && !mdi_live(di->mdi_cnt, di->mdi_i)) || (dw && dw->mdi_cnt && !mdi_live(dw->mdi_cnt, dw->mdi_i)))) return;   // past the multi-draw's count
    if (mdx_on && mdx_next(dw, di)) return;   // the next draw of a masked multi-draw: only the draw is encoded
    g_mdxc.next = NULL;
    if (!S.prog) { BAD_ERR(); RED_ONCE(18, "no program bound before the draw"); PD("Z %llu draw skipped: no program bound", g_stat_pass + !g_enc); return; }
    __unsafe_unretained NvProg *pr = g_geo_program ? g_geo_program : prog_get(S.prog);
    for (int stage = 0; stage < 5; stage++) if (!img_atomic_prepare(pr->sh[stage], stage)) return;
    draw_gs_check(pr);   // a geometry stage left with no function (see prog_fold_gs)
    if (S.rast_discard) { if (!S.tf_on && sx_draw(pr, dw, di)) return; tf_draw(pr, dw, di); return; }   // the vertex stage only: transform feedback capture, a vertex shader's storage writes (sx_draw), or nothing (tf_draw)
    if (g_nubd && (g_enc || ubd_lazy()) && ubd_conflict(pr, dw, di)) { g_ubd_conflicts++; rp_end(); ubd_land(); }   // land the deferred inline updates before this draw (see ubd_conflict)
    if (zskip_can_draw(pr)) {   // Zero-source skip: the output is always 0, writing 0 over 0, so this draw changes no result (see zskip_can_draw)
        g_zskip_count++; { static int once; if (!once++) MLOG("zero-source skip: first case pass %llu", g_stat_pass + 1); }
        PD("N %llu zero-source draw skipped", g_stat_pass + 1); return; }
    gmem_count_draw(pr);
    if (g_nlc && !g_enc) lc_take(pr);   // waiting clears: this pass's load actions, or landed before it (see lc_take)
    tba_prepare(pr->sh[0], pr->sh[1], pr->sh[2], pr->sh[3], pr->sh[4], 0);   // #309: unaligned buffer textures read as 2D rows, copied on the GPU before this draw (see tba_ent)
    if (ixc_wanted(dw, di) && !ixc_find(dw, di)) ixc_run(dw, di);   // indirect quads / fans / 8-bit indices: converted on the GPU before the render pass, at their own place in the replay (see ixc_run)
    uint64_t mdx = 0;   // the masked copy of the record (mdx_run); a draw it could not copy waits for the count instead
    if (mdx_on) { uint64_t ind = dw ? dw->ind : di->ind, cnt = dw ? dw->mdi_cnt : di->mdi_cnt; int i = dw ? dw->mdi_i : di->mdi_i;
        if (!mdx_find(ind, cnt, &mdx)) { mdx_run(dw, di); if (!mdx_find(ind, cnt, &mdx)) mdx = 0; }
        if (!mdx && !mdi_live(cnt, i)) return; }
    if (di && wide_wanted(di) && !wide_find(di)) wide_run(di);   // 8-bit indices written earlier in this submission: widened on the GPU before the render pass (see wide_run)
    if (!g_defer_replaying && !g_geo_program) {
        if (g_defer.active && g_defer.in_p && !g_defer.at_q) { if (defer_take(dw, di)) return; }
    }
    // Draws that cannot draw anything (both faces culled, empty scissor) return before the render pass is opened: otherwise the render pass is already open and on TBDR the whole attachment is loaded and stored for nothing
    // (Mac character select page: 3 render passes are opened only because of such draws, all loaded, zero draws)
    // Diagnostic switch for measuring an upper bound DM_NVN_SKIP_FS=<fragment key>[,<fragment key>...] (none by default): drops all draws of these fragment shaders (the picture will be wrong; only used in real-device ABA to measure "how much GPU time this class of draws is worth in total")
    { static char sk[16][20]; static int nsk = -1;
      if (nsk < 0) { nsk = 0; for (const char *q = getenv("DM_NVN_SKIP_FS"); q && *q && nsk < 16; q = strchr(q, ',') ? strchr(q, ',') + 1 : q + strlen(q)) { size_t n = strcspn(q, ","); if (n > 16) n = 16; memcpy(sk[nsk], q, n); sk[nsk++][n] = 0; }
                     if (nsk) MLOG("DM_NVN_SKIP_FS: dropping the draws of %d fragment shaders (diagnostic; the picture is wrong)", nsk); }
      if (g_ub_n > 0 && pr->sh[1] && !g_defer_replaying && ub_skip(pr->sh[1]->key)) return;   // In-process alternating measurement: this phase drops this class
      if (nsk && pr->sh[1] && !g_defer_replaying) for (int i = 0; i < nsk; i++) if (!strncmp(pr->sh[1]->key, sk[i], strlen(sk[i]))) return;
      if (ms_draw(pr)) return; }
