                { static uint64_t hp = ~0ull; static int hn; if (hp != g_stat_pass) { hp = g_stat_pass; hn = 0; }   // For the first 6 draws of each render pass, additionally print buffers of <= 608 bytes in hex (to compare byte by byte which fields changed across frames)
                  if (hn < 12 && u->size <= 608 && v->rf.b[i].reg == 3) { hn++; char hx[1300]; for (uint64_t q = 0; q < u->size; q++) snprintf(hx + 2 * q, 3, "%02x", base[mo + q]); PD("x %llu r%d %s", g_stat_pass, v->rf.b[i].reg, hx); } }
                o += snprintf(ub + o, sizeof ub - o, " r%d=%016llx/%llu/%016llx", v->rf.b[i].reg, (unsigned long long)h, (unsigned long long)u->size, (unsigned long long)h64); }
            PD("u %llu%s", g_stat_pass, ub); }
        if (all) { char vb[1600]; size_t o = 0; o += snprintf(vb + o, sizeof vb - o, "nattr=%d", S.nattr);
            for (int i = 0; i < S.nattr && i < 16 && o < sizeof vb - 100; i++) { int st = S.attr[i].stream; if (!S.attr[i].fmt) continue;   // only attributes with a format
                o += snprintf(vb + o, sizeof vb - o, " a%d{fmt=%#x off=%d s=%d stride=%u div=%u vb=%#llx/%llu}", i, S.attr[i].fmt, S.attr[i].offset, st,
                              st < 16 ? S.stream[st].stride : 0, st < 16 ? S.stream[st].divisor : 0, st < 16 ? (unsigned long long)S.vbuf[st].address : 0ull, st < 16 ? (unsigned long long)S.vbuf[st].size : 0ull); }
            PD("v %llu %s", g_stat_pass, vb);
            // DM_NVN_CBDUMP + DM_NVN_CBDUMP_KEY=vertex shader key: also save that draw's vertex streams and indices (F<frame>_p<pass>_vb<stream>_<address>.bin / _ib_<address>.bin)
            const char *cbd = getenv("DM_NVN_CBDUMP"), *cbk = getenv("DM_NVN_CBDUMP_KEY");
            if (cbd && cbk && pr->sh[0] && !strcmp(pr->sh[0]->key, cbk)) {
                char fp[1024];
                for (int st = 0; st < 16; st++) if (S.vbuf[st].address && S.vbuf[st].size) {
                    snprintf(fp, sizeof fp, "%s/F%llu_p%llu_vb%d_%llx.bin", cbd, (unsigned long long)atomic_load(&g_cur_frame), g_stat_pass, st, (unsigned long long)S.vbuf[st].address);
                    FILE *f = fopen(fp, "wb"); if (f) { fwrite((const void *)S.vbuf[st].address, 1, S.vbuf[st].size, f); fclose(f); } }
                if (di && di->ibuf) {
                    snprintf(fp, sizeof fp, "%s/F%llu_p%llu_ib%d_%llx.bin", cbd, (unsigned long long)atomic_load(&g_cur_frame), g_stat_pass, di->itype, (unsigned long long)di->ibuf);
                    FILE *f = fopen(fp, "wb"); if (f) { fwrite((const void *)di->ibuf, 1, (size_t)di->count << (di->itype == 2 ? 2 : di->itype), f); fclose(f); } }
            } }
        if (last_pass != g_stat_pass) {
            last_pass = g_stat_pass;
            PD("D %llu prim=%d vc=%d inst=%d blend=%#x wm=%#x dt=%d dw=%d df=%d st=%d sc=%lu,%lu,%lu,%lu tgt=%lux%lu vp=%.0f,%.0f,%.0f,%.0f dr=%g,%g lo=%u", g_stat_pass, prim,
               dw ? dw->count : di->count, dw ? dw->instances : di->instances, S.color.blend_en, S.chmask.mask, (int)S.ds.dt, (int)S.ds.dw, (int)S.ds.df, (int)S.ds.st,
               (unsigned long)g_ed.sc.x, (unsigned long)g_ed.sc.y, (unsigned long)g_ed.sc.width, (unsigned long)g_ed.sc.height, (unsigned long)g_pass.tw, (unsigned long)g_pass.th,   // the scissor draw_pass_state just made current (g_ed.sc; a new encoder starts unset) and the target size
               S.has_vp ? S.vp[0][0] : 0, S.has_vp ? S.vp[0][1] : 0, S.has_vp ? S.vp[0][2] : (float)g_pass.tw, S.has_vp ? S.vp[0][3] : (float)g_pass.th, S.has_vp ? S.dr[0] : 0.f, S.has_vp ? S.dr[1] : 1.f, (unsigned)S.color.logic_op);
        }
    }
    g_kd_force = 0;
    if (rt_range_on() && !rt_range_pr_ro(pr)) g_pass.range_external=1;
    rt_range_note_depth();
#ifdef NVN_RT_RANGE_TEST
    rr_snap(dw,di);
#endif
    udc_note_draw(pr);
    swrite_note(pr);
    fb_note_draw(pr);
    if (g_mtk.on) { mtk_encode(en); return; }   // a task / mesh draw (nvn_geometry.inc)
    if (g_geo_program) {
        enc_r_draw_indexed_indirect(en, mp, MTLIndexTypeUInt32, g_geo_indices, g_geo_index_bytes, g_geo_args); g_pass_geo++;
        return;
    }
    if (dw && dw->tfc) { if (g_tfd_args) enc_r_draw_indirect(en, mp, g_tfd_args); return; }   // DrawTransformFeedback: the arguments tfd_args made (nvn_geometry.inc)
    // A draw with 0 primitives (the game does send count=0) draws no pixels, so skip encoding; Metal requires the count to be non-zero, otherwise the validation layer aborts on the spot (measured on the camp / wilderness / combat pages)
    draw_emit(en, mp, prim, dw, di, mdx);
}
// The draw itself, once the pass, pipeline and bindings are in place: picks the Metal draw call for the NVN draw (indirect, quads / fans, 8-bit indices, plain)
static void draw_emit(id en, MTLPrimitiveType mp, int prim, const p_draw *dw, const p_draw_idx *di, uint64_t mdx) {
    if ((dw && dw->ind) || (di && di->ind)) {   // DrawArraysIndirect / DrawElementsIndirect: NVN's argument records {count, instances, first, base instance} and {count, instances, first index,
        // base vertex, base instance} have the layouts of MTLDrawPrimitivesIndirectArguments and MTLDrawIndexedPrimitivesIndirectArguments; quads, fans and 8-bit indices use the converted ones (ixc_run)
        const ixc_ent *e = ixc_wanted(dw, di) ? ixc_find(dw, di) : NULL; void *mb, *ab; uint64_t mo, ao, ig;
        if (di && S.restart.on) { int isz = di->itype == 0 ? 1 : di->itype == 1 ? 2 : 4; int64_t rv = rst_val(isz);   // the indices are only known to the GPU: restart is not translated
            int native = isz != 1 && rv == (isz == 2 ? 0xFFFF : 0xFFFFFFFF);   // a 16 / 32-bit strip restarting at all-ones: Metal does the same (8-bit ones are widened without it)
            if (prim == 6 || prim == 7 || ((prim == 3 || prim == 5) && !native))
                RED_ONCE(131, "indirect indexed draw (primitive %d, %d-byte indices) with primitive restart %#llx: the GPU path does not translate it, a restart index draws as a vertex", prim, isz, (unsigned long long)rv); }
        uint64_t ind = dw ? dw->ind : di->ind;
        if (ixc_wanted(dw, di)) { if (e && e->args) enc_r_draw_indexed_indirect(en, mp, MTLIndexTypeUInt32, e->ixb, e->ixlen, e->args); else RED_ONCE(88, "indirect draw skipped: the arguments for primitive %d were not converted (argument address %#llx is in no memory pool, or the conversion pipeline was not created)", prim, (unsigned long long)ind); }
        else if (!mdx && !nvn_be_addr(ind, dw ? 16 : 20, &ab, &ao)) RED_ONCE(88, "indirect draw skipped: argument address %#llx is in no memory pool", (unsigned long long)ind);
        else if (dw) { enc_r_draw_indirect(en, mp, mdx ? mdx : ((__bridge id<MTLBuffer>)ab).gpuAddress + ao); if (mdx) mdx_chain(dw->mdi_cnt, dw->mdi_i, mp, MTLIndexTypeUInt32, 0, 0); }
        else if (!gpu_addr_want(di->ibuf, 1, 0, &mb, &mo, &ig, &(uint64_t){0})) RED_ONCE(22, "index buffer is in no memory pool");
        else { MTLIndexType ty = di->itype == 1 ? MTLIndexTypeUInt16 : MTLIndexTypeUInt32; uint64_t il = ((__bridge id<MTLBuffer>)mb).length - mo;
            enc_r_draw_indexed_indirect(en, mp, ty, ig, il, mdx ? mdx : ((__bridge id<MTLBuffer>)ab).gpuAddress + ao); if (mdx) mdx_chain(di->mdi_cnt, di->mdi_i, mp, ty, ig, il); }
    } else if (dw && (prim == 7 || prim == 6)) {   // Quads (shared indices 0,1,2,0,2,3) and triangle fans (13 Sentinels, shared (0, i, i+1)), first as the base vertex
        uint32_t nt = fanquad_tris(prim, dw->count);
        if (!nt) return;
        if (nt <= SHARED_IB_N * (prim == 7 ? 2u : 1u)) {   // within the shared index buffers
            if (prim == 7) quad_ib_make(); else fan_ib_make();
            enc_r_draw_indexed(en, mp, (NSUInteger)nt * 3, MTLIndexTypeUInt32, prim == 7 ? g_quad_gpu : g_fan_gpu, prim == 7 ? g_quad_ib.length : g_fan_ib.length, dw->instances > 0 ? dw->instances : 1, dw->first, dw->base_instance);
        } else {   // more than they cover (audit #846 F-nvn-shared-ib): this draw's own list in the frame arena, as for indexed fans / quads
            if ((uint64_t)nt * 12 > g_dev.maxBufferLength) { RED_ONCE(130, "%s draw of %d vertices needs %llu bytes of indices, more than a Metal buffer holds: skipped", prim == 7 ? "quad" : "triangle fan", dw->count, (unsigned long long)nt * 12); return; }
            id<MTLBuffer> ab; size_t off = arena_alloc((size_t)nt * 12, &ab);
            fanquad_expand(prim, NULL, 0, (uint32_t)dw->count, -1, (uint32_t *)((uint8_t *)ab.contents + off));
            enc_r_draw_indexed(en, mp, (NSUInteger)nt * 3, MTLIndexTypeUInt32, ab.gpuAddress + off, (NSUInteger)nt * 12, dw->instances > 0 ? dw->instances : 1, dw->first, dw->base_instance);
        }
    } else if (dw) {
        if (dw->count && (dw->instances > 1 || dw->base_instance)) enc_r_draw_instanced(en, mp, dw->first, dw->count, dw->instances > 0 ? dw->instances : 1, dw->base_instance);
        else if (dw->count) enc_r_draw(en, mp, dw->first, dw->count);
    } else {
        if (prim == 6 || prim == 7) {
                                        // indexed triangle fans / quads (13 Sentinels): at replay the indices are read from guest memory and expanded into a 32-bit triangle list in this frame's arena (as for 8-bit indices)
            int isz = di->itype == 0 ? 1 : di->itype == 1 ? 2 : 4;
            uint32_t nt = fanquad_tris(prim, di->count);
            if (!nt) return;
            void *mb; uint64_t mo; const uint8_t *src;
            if (!nvn_be_addr(di->ibuf, (uint64_t)di->count * isz, &mb, &mo) || !(src = [(__bridge id<MTLBuffer>)mb contents])) { RED_ONCE(22, "index buffer is in no memory pool"); return; }
            if (pend_hits(di->ibuf, (uint64_t)di->count * isz)) RED_ONCE(73, "triangle fan / quad index buffer has GPU-side writes in this submission: expanded from the current content");
            src += mo;
            id<MTLBuffer> ab; size_t off = arena_alloc(((size_t)nt * 12 + 15) & ~(size_t)15, &ab);
            nt = fanquad_expand(prim, src, isz, (uint32_t)di->count, rst_val(isz), (uint32_t *)((uint8_t *)ab.contents + off));   // restart starts a new fan / run of quads
            if (nt) enc_r_draw_indexed(en, mp, nt * 3, MTLIndexTypeUInt32, ab.gpuAddress + off, (NSUInteger)nt * 12, di->instances ? di->instances : 1, di->base_vertex, di->base_instance);
            if (g_rt_range_pending) { PD("j rt_level_range pass=%llu vc=%u", g_stat_pass, (unsigned)di->count); g_rt_range_pending = 0; }
            return;
        }
        if (di->itype == 0) {
                                // 8-bit indices: Metal only has 16 / 32-bit. At replay they are read from guest memory and widened to 16-bit in this frame's arena (SMBW's full-screen passes and the final copy into the window all use 8-bit indices; without this the whole screen is black)
            if (!di->count) return;
            int64_t rv = prim == 3 || prim == 5 ? rst_val(1) : -1;   // strips: NVN's restart index becomes Metal's 0xFFFF when widened
            const wide_ent *w = wide_wanted(di) ? wide_find(di) : NULL;
            if (w && w->gpu) {   // written earlier in this submission: widened on the GPU before this pass (wide_run)
                if (rv >= 0) RED_ONCE(131, "8-bit strip indices widened on the GPU with primitive restart on (primitive %d, restart %#llx): the restart index stays a vertex", prim, (unsigned long long)rv);
                enc_r_draw_indexed(en, mp, di->count, MTLIndexTypeUInt16, w->gpu, (NSUInteger)di->count * 2, di->instances ? di->instances : 1, di->base_vertex, di->base_instance);
                if (g_rt_range_pending) { PD("j rt_level_range pass=%llu vc=%u", g_stat_pass, (unsigned)di->count); g_rt_range_pending = 0; }
                return;
            }
            void *mb; uint64_t mo; const uint8_t *src;
            if (!nvn_be_addr(di->ibuf, di->count, &mb, &mo) || !(src = [(__bridge id<MTLBuffer>)mb contents])) { RED_ONCE(22, "index buffer is in no memory pool"); return; }
            if (pend_hits(di->ibuf, di->count)) RED_ONCE(48, "8-bit index buffer has GPU-side writes in this submission and the GPU expansion failed: expanded from the current content");
            id<MTLBuffer> ab; size_t off = arena_alloc(((size_t)di->count * 2 + 15) & ~(size_t)15, &ab);
            uint16_t *d = (uint16_t *)((uint8_t *)ab.contents + off); src += mo;
            for (int32_t i = 0; i < di->count; i++) d[i] = src[i] == rv ? 0xFFFF : src[i];
            enc_r_draw_indexed(en, mp, di->count, MTLIndexTypeUInt16, g_cur_arena->gpu + off, (NSUInteger)di->count * 2, di->instances ? di->instances : 1, di->base_vertex, di->base_instance);
            if (g_rt_range_pending) { PD("j rt_level_range pass=%llu vc=%u", g_stat_pass, (unsigned)di->count); g_rt_range_pending = 0; }
            return;
        }
        int isz = di->itype == 1 ? 2 : 4; int64_t rv = rst_val(isz);
        if ((prim == 3 || prim == 5) && di->count > 0 && (isz == 2 ? rv != 0xFFFF : rv >= 0 && rv != 0xFFFFFFFF)) {   // a strip whose restarts Metal may place differently: check the indices
            void *sb; uint64_t so; const uint8_t *src;
            if (nvn_be_addr(di->ibuf, (uint64_t)di->count * isz, &sb, &so) && (src = [(__bridge id<MTLBuffer>)sb contents]) && strip_rst_fix(src + so, isz, (uint32_t)di->count, rv, NULL)) {
                if (pend_hits(di->ibuf, (uint64_t)di->count * isz)) RED_ONCE(132, "strip index buffer has GPU-side writes in this submission: primitive restart rewritten from the current content");
                id<MTLBuffer> ab; size_t off = arena_alloc((size_t)di->count * 4, &ab);
                strip_rst_fix(src + so, isz, (uint32_t)di->count, rv, (uint32_t *)((uint8_t *)ab.contents + off));
                enc_r_draw_indexed(en, mp, di->count, MTLIndexTypeUInt32, ab.gpuAddress + off, (NSUInteger)di->count * 4, di->instances ? di->instances : 1, di->base_vertex, di->base_instance);
                if (g_rt_range_pending) { PD("j rt_level_range pass=%llu vc=%u", g_stat_pass, (unsigned)di->count); g_rt_range_pending = 0; }
                return;
            }
        }
        void *mb; uint64_t mo;
        uint64_t gpu;
        if (!gpu_addr_want(di->ibuf, 1, (uint64_t)di->count << (di->itype == 1 ? 1 : di->itype == 2 ? 2 : 0), &mb, &mo, &gpu, &(uint64_t){0})) { RED_ONCE(22, "index buffer is in no memory pool"); return; }
        if (di->count) enc_r_draw_indexed(en, mp, di->count, di->itype == 1 ? MTLIndexTypeUInt16 : MTLIndexTypeUInt32, gpu, ((__bridge id<MTLBuffer>)mb).length - mo,
                di->instances ? di->instances : 1, di->base_vertex, di->base_instance);
    }
    if (g_rt_range_pending) { PD("j rt_level_range pass=%llu vc=%u", g_stat_pass, (unsigned)(dw ? dw->count : di->count)); g_rt_range_pending=0; }
}
static nvn_hmap g_cps = {.klen = sizeof(void *)};
typedef struct { const void *cs; uintptr_t fc; } cps_se_key;
static nvn_hmap g_cps_se = {.klen = sizeof(cps_se_key)};   // S2Arm #800: compute pipelines of the sampler-emulation variant (se_want), by shader and SE_* bits: keyed apart from main0's
static void warm_claim(void) {
    if (!atomic_exchange_explicit(&g_warm_ready, 0, memory_order_acq_rel)) return;
    os_unfair_lock_lock(&g_warm_lock);
    NSArray<WarmItem *> *items = [g_warm_items copy];
    [g_warm_items removeAllObjects];
    os_unfair_lock_unlock(&g_warm_lock);
    for (WarmItem *item in items) {
        if (item->kind == 0) {
            if (!item->shader->warm_claimed) { item->shader->warm_claimed = 1; g_warm_claim_shaders++; }
        } else if (item->kind == 3) {   // S2Arm: prefetched at ProgramSetShaders; its S line waits for its first use (shader_used)
            // Already published by shader_load, including its complete identity.
        } else if (item->kind == 1) {
            if (!hm_get_id(&g_pso, &item->pso)) { hm_put_id(&g_pso, &item->pso, item->object); g_warm_claim_rps++; }
        } else {
            const void *key = (__bridge const void *)item->shader; cps_se_key fk = {key, (uintptr_t)item->fc};   // S2Arm #800: an emulation variant's pipeline goes where dispatch looks for it
            nvn_hmap *cps = item->fc ? &g_cps_se : &g_cps; const void *ck = item->fc ? (const void *)&fk : (const void *)&key;
            if (!hm_get_id(cps, ck)) { hm_put_id(cps, ck, item->object); g_warm_claim_cps++; }
        }
    }
}
// Dispatches share the open copy encoder (a Metal 4 compute encoder) with the copies and dispatches around them, each ordered after everything the encoder already holds by a barrier inside it,
// as a texture copy is (blit). An encoder of their own, with full queue barriers on both sides, cost the GPU a drain per dispatch: Hyrule Warriors: Age of Calamity's battles after the first cutscene
// run about 1,060 small dispatches a frame, and the Mac GPU went from 6.7 to 16 ms a frame at the same draws, the iPhone's from 15 to about 50 (17 fps).
// DM_NVN_DISPATCH_OWN=1 gives each dispatch its own encoder again
static int dispatch_own(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DM_NVN_DISPATCH_OWN"); v = e && !strcmp(e, "1"); if (v) MLOG("compute dispatches: each in an encoder of its own (DM_NVN_DISPATCH_OWN=1)");
        if (getenv("DM_NVN_PASSGPU")) MLOG("【黄】 DM_NVN_PASSGPU was removed (it never produced data on Metal 4 and changed compute encoding): use DM_NVN_GPUPROF=<first frame>-<last frame>"); }
    return v;
}
static id<MTL4ComputeCommandEncoder> dispatch_enc(void) {
    blit_open_k(1);   // Metal 3: a compute encoder (blit_open_k)
    if (g_blit_ops) blit_barrier();
    g_bw_lo[0] = 0; g_bw_hi[0] = ~0ull; g_bw_n = 1; g_br_n = 0; g_blit_ops = 1;   // recorded as "everything written": the next copy or dispatch gets a barrier
    if (!g_blit_ct) { enc_c_table(g_blit, g_ct); g_blit_ct = 1; }
    args_dirty_all();
    return g_blit;
}
// A dispatch's own image slots holding textures made without shader writes (see img_wr_note): queued so they are upgraded before its encoder opens
static void img_wr_prescan(NvShader *sh, int nvn_stage) {
    pthread_mutex_lock(&g_rmu);
    for (int i = 0; i < sh->rf.nb; i++) { const nvn_rbind *b = &sh->rf.b[i];
        if (b->kind != NVN_RB_IMGU && (b->kind != NVN_RB_IMG || b->reg >= 32)) continue;
        int tid = img_tid(b, nvn_stage);
        if (tid < 0 || tid >= g_ntreg || !g_treg[tid].ok) continue;
        nvn_be_pool_gpu_written(g_treg[tid].t.pool);   // before it resolves: a shader image is a GPU write into its pool (tex_cpu_content)
        id<MTLTexture> t = tex_mtl(&g_treg[tid].t); if (t.parentTexture) t = t.parentTexture;
        if (t && !(t.usage & MTLTextureUsageShaderWrite) && !mtl_fmt_depth(t.pixelFormat)) img_wr_note(tid); }
    pthread_mutex_unlock(&g_rmu);
}
static void tensor_standin(NvShader *cs);   // nvn_tensor.inc
static uint64_t g_tensor_native_runs;
static void dispatch(const p_dispatch *dp) {
    geo_run_flush();
    zskip_clear();
    g_wr_epoch++; g_mdx_epoch++;
    if (!S.cprog) { RED_ONCE(27, "no program bound before the dispatch"); return; }
    // DispatchComputeIndirect: the group counts {x, y, z} at ind (MTLDispatchThreadgroupsIndirectArguments) are usually written by the GPU earlier in the frame; Metal reads them when the dispatch runs
    void *ib = NULL; uint64_t io = 0, ig = 0;
    if (dp->ind && !mtl_gpu_addr(dp->ind, 12, &ib, &io, &ig)) { RED_ONCE(94, "indirect dispatch skipped: argument address %#llx is in no memory pool", (unsigned long long)dp->ind); return; }
    if (dp->ind) { static int once; if (!once++) MLOG("indirect dispatch: first time (the GPU reads the threadgroup counts from %#llx)", (unsigned long long)dp->ind); }
    NvShader *cs = prog_get(S.cprog)->sh[5];
    if (!cs) { RED_ONCE(28, "the dispatched program has no compute shader (or it is not mapped)"); return; }
    if (cs->tensor == 1) { tensor_standin(cs); return; }   // S2Arm 11-05: the game's own tensor-core upscaling network: not dispatched (nvn_tensor.inc)
    g_gmem_disp_all++; if (gmem_uses(cs)) g_gmem_disp++;   // 原始内存池表动态占比（gmem_count_draw）
    const void *k = (__bridge const void *)cs;
    int fc = se_want(S.cprog, cs, 5);   // S2Arm #800: this dispatch binds a sampler the GPU cannot reduce natively: the reduction variant (see se_bind)
    cps_se_key fk = {k, (uintptr_t)fc}; nvn_hmap *cps = fc ? &g_cps_se : &g_cps; const void *ck = fc ? (const void *)&fk : (const void *)&k;
    id<MTLComputePipelineState> ps = hm_get_id(cps, ck);
    if ((id)ps == (id)NSNull.null) return;   // its pipeline failed before: built once, reported once (see below)
    if (!ps) {
        NSError *e = nil; uint64_t bt = bp_now(); ps = par_compute(fc ? se_fn(cs, fc) : cs->fn, par_ckey(cs, fc), &e);
        { uint64_t d_ = bp_now() - bt; g_bp_pso_n++; g_bp_pso_ns += d_; fe_sync_note(d_); }
        // A failure is remembered like a success: it was rebuilt at every dispatch (Monster Hunter Rise's 36,880-byte threadgroup memory, over Apple's 32,768: 2,472–6,450 builds in one
        // Mac run; on the test device the compiles kept the frame from ending for 45 s, 10-26 cold run, frame 1150)
        if (!ps) { MLOG("【红】 failed to create compute pipeline %s%s: %s", cs->key, fc ? " (sampler-emulation variant)" : "", e.localizedDescription.UTF8String); hm_put_id(cps, ck, NSNull.null); return; }
        pso_record("C\t%s\n", cs->key);
        if (cs->key[0]) { if (fc) pso_user_record("C\t%s\t%x\n", cs->key, fc); else pso_user_record("C\t%s\n", cs->key); }   // a reduction variant's: its bits (warm_parse masks them per GPU)
        hm_put_id(cps, ck, ps);
    }
    if (cs->builtin) {   // Built-in compute kernel: n = uniform buffer 0, src = storage buffer 0, dst = storage buffer 1
        const p_bind_buf *u = &S.ubo[5][0], *a0 = &S.ssbo[5][0], *a1 = &S.ssbo[5][1];
        void *ub, *sb, *db; uint64_t uo, so, dof;
        if (!nvn_be_addr(u->addr, 4, &ub, &uo) || !nvn_be_addr(a0->addr, 8, &sb, &so) || !nvn_be_addr(a1->addr, 8, &db, &dof)) { RED_ONCE(30, "embedded compute kernel %s does not have all its buffers bound", cs->builtin); return; }
        if (!cs->logged++) {
