            uint32_t a[3] = {0}; mdi_wait();
            if (g_mdi_ev.signaledValue < g_mdi_v || !nvn_host_readable(dp->ind, 12)) { RED_ONCE(117, "indirect dispatch of compute shader %s with spilled shared memory: group counts not readable, dispatch skipped", cs->key); if (own) enc_c_end(ce); return; }
            memcpy(a, (const void *)(uintptr_t)dp->ind, 12); n = (uint64_t)a[0] * a[1] * a[2];
        }
        uint64_t bytes = n * cs->spill;
        if (!n) { if (own) enc_c_end(ce); return; }
        if (bytes > (512ull << 20)) { RED_ONCE(118, "compute shader %s: %llu threadgroups × %u spilled bytes exceed 512 MiB, dispatch skipped", cs->key, (unsigned long long)n, cs->spill); if (own) enc_c_end(ce); return; }
        id<MTLBuffer> sb; size_t so = arena_alloc((size_t)bytes, &sb); enc_c_args(ce, sb.gpuAddress + so, cs->spill_slot);
        static int once; if (!once++) MLOG("compute shared-memory spill: first dispatch of %s (%u bytes per threadgroup, %llu threadgroups)", cs->key, cs->spill, (unsigned long long)n);
    }
    if (dp->ind) {   // The shader reads the group counts from c0 + 0x200: copy the GPU-written ones there first (Metal 4 orders nothing inside an encoder without a barrier)
        if (g_c0_dim_buf && g_m3) {
            // Metal 3 needs compute -> blit -> compute, ordered by g_fence3 at each encoder boundary.
            // Keep the argument table from encode_args: encoding it again would allocate a new c0 with CPU counts.
            if (own) enc_c_end(ce);
            enc_b_copy_buffer(blit_open(), (__bridge id<MTLBuffer>)ib, io, g_c0_dim_buf, g_c0_dim_off, 12);
            if (own) { enc_b_end(g_blit); g_blit = nil; }
            ce = own ? own_compute() : (id<MTLComputeCommandEncoder>)dispatch_enc();
            enc_c_pso(ce, ps);   // enc_c_dispatch_indirect rebinds the persistent DmTable3 on this encoder
            static int once; if (!once++) MLOG("Metal 3 indirect dispatch: GPU counts copied to c0 through a blit encoder");
        } else if (g_c0_dim_buf) { [(id<MTL4ComputeCommandEncoder>)ce copyFromBuffer:(__bridge id<MTLBuffer>)ib sourceOffset:io toBuffer:g_c0_dim_buf destinationOffset:g_c0_dim_off size:12];
            [(id<MTL4ComputeCommandEncoder>)ce barrierAfterEncoderStages:MTLStageBlit beforeEncoderStages:MTLStageDispatch visibilityOptions:MTL4VisibilityOptionDevice]; }
        if (!own) g_gp_disp++;
        enc_c_dispatch_indirect(ce, ig, MTLSizeMake(tg[0], tg[1], tg[2]));
    } else { if (!own) g_gp_disp++; enc_c_dispatch(ce, MTLSizeMake(gx, gy, dp->z), MTLSizeMake(tg[0], tg[1], tg[2])); }
    if (cs->tensor == 3) {
        g_tensor_native_runs++;
        if (!(cs->tensor_log & 16)) { cs->tensor_log |= 16; MLOG("native neural super-resolution dispatch: %s, groups %ux%ux%d, local %ux%ux%u", cs->key, gx, gy, dp->z, tg[0], tg[1], tg[2]); }
    }
    if (own) enc_c_end(ce);
}
// GPU: texture -> buffer (row stride taken from SetCopyRowStride, layer stride from SetCopyImageStride, 0 = tightly packed)
// S2Arm widen: CPU-visible copies of a widened storage go through a game-width scratch texture, scaled with the copy draw (the generic mode's Narrowed readback / WidenUpload;
// Ryujinx reads a scaled texture back at scale 1 too, DmaClass): a readback sees the game's width, an upload fills the whole widened width. One cached scratch per format and size
static int copy_t2t_draw(id<MTLTexture> s, id<MTLTexture> d, unsigned sl, unsigned ss, unsigned dl, unsigned ds, const NVNcopyRegion *sr, const NVNcopyRegion *dr, int linear, int mirror);
static id<MTLTexture> wd_scratch(MTLPixelFormat pf, int w, int h) {
    static __strong id<MTLTexture> t;
    if (t && t.pixelFormat == pf && (int)t.width == w && (int)t.height == h) return t;
    MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:pf width:(NSUInteger)w height:(NSUInteger)h mipmapped:NO];
    d.usage = MTLTextureUsageShaderRead | MTLTextureUsageRenderTarget; d.storageMode = MTLStorageModePrivate;
    id<MTLTexture> n = [g_dev newTextureWithDescriptor:d]; if (!n) return nil;
    if (t) defer_obj_release(t);
    res_add(n); t = n; return t;
}
// The game's region r of a level-`level` copy on texture ct (Metal texture mt) in storage texels (out): x where the widen core widened the storage, y too where the internal
//   resolution scaled it (storage ÷ game on each axis, as copy_t2t); 0 = the storage is the game's size there
static int wd_copy_xy(const tex_t *ct, id<MTLTexture> mt, unsigned level, const NVNcopyRegion *r, NVNcopyRegion *out) {
    if ((!g_wd_widened && !rs_on()) || !ct || !mt || ct->d.target == 2) return 0;
    long gw = MAX(ct->d.width >> level, 1u), sw = MAX(mt.width >> level, 1u), gh = MAX(ct->d.height >> level, 1u), sh = rs_on() ? MAX(mt.height >> level, 1u) : gh;
    if (gw == sw && gh == sh) return 0;
    long x0 = lround((double)r->xoffset * sw / gw), x1 = lround((double)(r->xoffset + r->width) * sw / gw), y0 = lround((double)r->yoffset * sh / gh), y1 = lround((double)(r->yoffset + r->height) * sh / gh);
    out->xoffset = (int)x0; out->width = (int)(x1 - x0); out->yoffset = (int)y0; out->height = (int)(y1 - y0); return 1;
}
// Copies and clears into / out of a folded linear texture (tex_linear) would address its texels at their unfolded places: not done, reported (none seen in a game yet)
static int fold_copy_skip(const tex_t *t, const char *what) {
    if (!g_fold_any || !tex_fold_k(t)) return 0;
    RED_ONCE(142, "%s with folded linear texture ser=%llu %ux%u skipped (first case)", what, (unsigned long long)t->serial, t->d.width, t->d.height); return 1;
}
static void copy_t2b(const p_copy_b2t *c) {
    if (fold_copy_skip(c->tex, "texture→buffer copy")) return;
    g_wr_epoch++; g_mdx_epoch++;
    if (c->tex) xv_check(c->tex->serial, c->has_view && c->view.set_levels ? c->view.base_level : 0, c->has_view && c->view.set_layers ? c->view.min_layer : 0, "texture-to-buffer copy");
    id<MTLTexture> t = tex_mtl(c->tex);
    if (!t) return;
    { uint32_t upf; int ubpp; if (fmt_unpack(c->tex->d.format, &upf, &ubpp)) { RED_ONCE(115, "texture→buffer copy of texture ser=%llu (format %#x) skipped: the host stores it in another format (BC decompressed / expanded, fmt_unpack), not the game's bytes", c->tex->serial, c->tex->d.format); return; } }
    int bw, bh, bpb = nvn_fmt_bpb(c->tex->d.format, &bw, &bh);
    unsigned level = c->has_view && c->view.set_levels ? c->view.base_level : 0, layer0 = c->has_view && c->view.set_layers ? c->view.min_layer : 0;
    size_t row = c->row_stride ? c->row_stride : (size_t)((c->r.width + bw - 1) / bw) * bpb;
    size_t rows = (c->r.height + bh - 1) / bh, img = c->image_stride ? c->image_stride : row * rows;   // per layer: recorded SetCopyImageStride, else tightly packed
    int is3d = c->tex->d.target == 2, nz = c->r.depth ? c->r.depth : 1;
    void *mb; uint64_t mo;
    if (!nvn_be_addr(c->src, img * nz, &mb, &mo)) { RED_ONCE(31, "texture→buffer copy destination is in no memory pool"); return; }
    sbw_note(c->src, img * nz, SBW_GPU);
    for (int zi = 0; zi < nz; zi++) for (size_t ri = 0; ri < rows; ri++) gpw_clear(c->src + zi * img + ri * row, (size_t)((c->r.width + bw - 1) / bw) * bpb);   // the bytes this copy writes (gpw_mark)
    { NVNcopyRegion sr = c->r, dr = {0, 0, 0, c->r.width, c->r.height, 1};   // S2Arm widen / internal resolution: back to the game's size first (see wd_scratch), one layer at a time
      if (!is3d && (nz == 1 || rs_on()) && wd_copy_xy(c->tex, t, level, &c->r, &sr)) {   // (widen alone keeps its single-layer rule)
          id<MTLTexture> tmp = wd_scratch(t.pixelFormat, c->r.width, c->r.height); int z = 0; sr.depth = 1;
          for (; tmp && z < nz; z++) {
              if (!copy_t2t_draw(t, tmp, level, layer0 + c->r.zoffset + z, 0, 0, &sr, &dr, 1, 0)) break;
              enc_b_copy_texture_buffer(blit(), tmp, 0, 0, MTLOriginMake(0, 0, 0), MTLSizeMake(c->r.width, c->r.height, 1), (__bridge id<MTLBuffer>)mb, mo + z * img, row, img); }
          if (tmp && z == nz) return;
          RED_ONCE(120, "widen / internal resolution: readback of resized storage ser=%llu (format %lu) not brought back to the game's size: it reads storage texels", c->tex->serial, (unsigned long)t.pixelFormat); } }
    id<MTL4ComputeCommandEncoder> b = blit();
    if (is3d)
        enc_b_copy_texture_buffer(b, t, 0, level, MTLOriginMake(c->r.xoffset, c->r.yoffset, c->r.zoffset), MTLSizeMake(c->r.width, c->r.height, nz), (__bridge id<MTLBuffer>)mb, mo, row, img);
    else
        for (int z = 0; z < nz; z++)
            enc_b_copy_texture_buffer(b, t, layer0 + c->r.zoffset + z, level, MTLOriginMake(c->r.xoffset, c->r.yoffset, 0), MTLSizeMake(c->r.width, c->r.height, 1), (__bridge id<MTLBuffer>)mb, mo + z * img, row, img);
}
// CPU texture read (ReadTexels): for packaged textures the pool memory is the ground truth, de-layout and read directly; the rest are read back from the MTLTexture by blit (the caller has already waited for the GPU per NVN rules)
void nvn_be_read_texels(const tex_t *t, unsigned level, unsigned layer0, const NVNcopyRegion *r, uint8_t *dst, size_t row, size_t img) {
    xv_check(t->serial, level, layer0, "CPU readback");
    PD("U cpu_read ser=%llu lv%u sl%u xyz=%d,%d,%d size=%d,%d,%d dst=%p row=%lu img=%lu", t->serial, level, layer0, r->xoffset, r->yoffset, r->zoffset, r->width, r->height, r->depth, dst, (unsigned long)row, (unsigned long)img);
    int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh);
    size_t wb = (size_t)((r->width + bw - 1) / bw) * bpb, hb = (r->height + bh - 1) / bh, x0 = (size_t)(r->xoffset / bw) * bpb, y0 = r->yoffset / bh;
    int nz = r->depth ? r->depth : 1, is3d = t->d.target == 2;
    // A texture the CPU filled has its content in guest memory: read it there, on whatever thread asks, without resolving (and maybe uploading) the host texture.
    // That includes a tex_dirty_upload texture the CPU wrote since registration but the submit thread has not resolved yet: Tears of the Kingdom fills 1024x1024 BC4 material
    // textures from the CPU, reads them back with ReadTexels on its own thread before any draw uses them, and copies the blocks into its 5120x5120 roughness atlas. Read from the
    // never-uploaded host texture they were zeros, the atlas stayed empty, and the opening cave's stone blocks got roughness 0 and no torch light
    int nvn_ft_written(const tex_t *);
    if ((t->has_layout || tex_cpu_written(t->serial) || (DM_GAME_TEX_DIRTY_UPLOAD && nvn_ft_written(t))) && t->mem) {
        uint32_t lw = MAX(t->d.width >> level, 1u), lh = MAX(t->d.height >> level, 1u), lz = is3d ? MAX(t->d.depth >> level, 1u) : 1;
        size_t lp = (size_t)((lw + bw - 1) / bw) * bpb, lr = (lh + bh - 1) / bh;
        uint8_t *lin = malloc(lp * lr * lz);
        for (int z = 0; z < nz; z++) {
            unsigned layer = is3d ? 0 : layer0 + r->zoffset + z;
            if ((is3d && z == 0) || !is3d) if (nvn_deswizzle(&t->d, level, layer, t->mem, lin, lp)) { RED_ONCE(32, "ReadTexels deswizzle failed"); free(lin); return; }
            const uint8_t *src = lin + (is3d ? (size_t)(r->zoffset + z) * lp * lr : 0);
            for (size_t y = 0; y < hb; y++) memcpy(dst + z * img + y * row, src + (y0 + y) * lp + x0, wb);
        }
        free(lin);
        return;
    }
    id<MTLTexture> mt = tex_mtl(t);
    { uint32_t upf; int ubpp; if (fmt_unpack(t->d.format, &upf, &ubpp)) { RED_ONCE(116, "ReadTexels of GPU-made texture ser=%llu (format %#x) returns zeros: the host stores it in another format (BC decompressed / expanded, fmt_unpack)", t->serial, t->d.format); mt = nil; } }
    if (!mt) { memset(dst, 0, img * nz); return; }
    mtl_finish_gpu();
    if (!is3d && bw == 1 && bh == 1 && rs_state(mt) == RS_SCALED) {   // S2Arm internal resolution: read the storage rectangle, then take each game texel's nearest storage texel on the CPU
        double sc = g_rs; long sx = r->xoffset, sy = r->yoffset, sw = r->width, sh = r->height; rs_rect(sc, &sx, &sy, &sw, &sh);   // (this runs on the caller's thread: no copy draw)
        long lw = (long)MAX(mt.width >> level, 1u), lh = (long)MAX(mt.height >> level, 1u); if (sx + sw > lw) sw = lw - sx; if (sy + sh > lh) sh = lh - sy;
        if (sw <= 0 || sh <= 0) { memset(dst, 0, img * nz); return; }
        size_t swb = (size_t)sw * bpb;
        id<MTLBuffer> sb = [g_dev newBufferWithLength:swb * (size_t)sh * nz options:MTLResourceStorageModeShared];
        id<MTLCommandBuffer> cb = q_cb(); id<MTLBlitCommandEncoder> b = enc_b_begin(cb);
        for (int z = 0; z < nz; z++)
            [b copyFromTexture:mt sourceSlice:layer0 + r->zoffset + z sourceLevel:level sourceOrigin:MTLOriginMake(sx, sy, 0) sourceSize:MTLSizeMake(sw, sh, 1)
                      toBuffer:sb destinationOffset:z * swb * sh destinationBytesPerRow:swb destinationBytesPerImage:swb * sh];
        [b endEncoding]; DM_BLOCK_BEGIN(); cb_run(cb); DM_BLOCK_END();
        for (int z = 0; z < nz; z++) for (int y = 0; y < r->height; y++) {
            long ty = (long)floor((r->yoffset + y + 0.5) * sc) - sy; if (ty < 0) ty = 0; if (ty >= sh) ty = sh - 1;
            for (int x = 0; x < r->width; x++) {
                long tx = (long)floor((r->xoffset + x + 0.5) * sc) - sx; if (tx < 0) tx = 0; if (tx >= sw) tx = sw - 1;
                memcpy(dst + z * img + (size_t)y * row + (size_t)x * bpb, (uint8_t *)sb.contents + (size_t)z * swb * sh + (size_t)ty * swb + (size_t)tx * bpb, (size_t)bpb); } }
        return;
    }
    id<MTLBuffer> buf = [g_dev newBufferWithLength:wb * hb * nz options:MTLResourceStorageModeShared];
    id<MTLCommandBuffer> cb = q_cb(); id<MTLBlitCommandEncoder> b = enc_b_begin(cb);
    for (int z = 0; z < nz; z++)
        [b copyFromTexture:mt sourceSlice:is3d ? 0 : layer0 + r->zoffset + z sourceLevel:level sourceOrigin:MTLOriginMake(r->xoffset, r->yoffset, is3d ? r->zoffset + z : 0)
                sourceSize:MTLSizeMake(r->width, r->height, 1) toBuffer:buf destinationOffset:z * wb * hb destinationBytesPerRow:wb destinationBytesPerImage:wb * hb];
    [b endEncoding]; DM_BLOCK_BEGIN(); cb_run(cb); DM_BLOCK_END();   // the old queue: no fence (m4_end)
    for (int z = 0; z < nz; z++) for (size_t y = 0; y < hb; y++) memcpy(dst + z * img + y * row, (uint8_t *)buf.contents + z * wb * hb + y * wb, wb);
}
// S2Arm internal resolution, diagnostics for tests (graphics/nvn/tests/t_nvn_rscale.m): a texture object's Metal storage size and scale record (returns RS_NONE / RS_SCALED / RS_BLACK,
//   −1 = not a texture), its level-0 layer-0 storage bytes as stored (no scaling back: the counter-proof that a scaled texture really holds fewer texels), and marking it as read where
//   scaling is not supported (rs_bad: the binding checks' queue, taken at the next pass / dispatch)
int nvn_be_tex_storage_size(const void *nvntex, int *w, int *h) {
    const tex_t *t = nvntex; if (!t || t->magic != MAGIC('T', 'E', 'X', 0)) return -1;
    id<MTLTexture> mt = tex_mtl(t); if (!mt) return -1;
    if (w) *w = (int)mt.width; if (h) *h = (int)mt.height;
    return rs_state(mt);
}
int nvn_be_tex_storage_read(const void *nvntex, uint8_t *dst, size_t row) {
    const tex_t *t = nvntex; if (!t || t->magic != MAGIC('T', 'E', 'X', 0)) return -1;
    id<MTLTexture> mt = tex_mtl(t); size_t bpp = mt ? mtl_pf_bytes(mt.pixelFormat) : 0; if (!mt || !bpp) return -1;
    mtl_finish_gpu();
    size_t wb = mt.width * bpp; id<MTLBuffer> buf = [g_dev newBufferWithLength:wb * mt.height options:MTLResourceStorageModeShared];
    id<MTLCommandBuffer> cb = q_cb(); id<MTLBlitCommandEncoder> b = enc_b_begin(cb);
    [b copyFromTexture:mt sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(mt.width, mt.height, 1) toBuffer:buf destinationOffset:0 destinationBytesPerRow:wb destinationBytesPerImage:wb * mt.height];
    [b endEncoding]; if (!cb_run(cb)) return -1;
    for (NSUInteger y = 0; y < mt.height; y++) memcpy(dst + y * row, (uint8_t *)buf.contents + y * wb, wb);
    return 0;
}
void nvn_be_rs_mark_bad(const void *nvntex) { const tex_t *t = nvntex; if (t && t->magic == MAGIC('T', 'E', 'X', 0)) rs_bad(tex_mtl(t), "测试标记"); }
static void copy_b2t(const p_copy_b2t *c) {
    if (fold_copy_skip(c->tex, "buffer→texture copy")) return;
    if (c->tex) zskip_del(c->tex->serial);
    id<MTLTexture> t = tex_mtl(c->tex);
    if (!t) { PD("C ser=%llu (no host texture)", c->tex->serial); return; }
    if (rs_state(t) == RS_SCALED) { rs_rescale(t, 0, "缓冲写入（CPU 数据）"); t = tex_mtl(c->tex); if (!t) return; }   // S2Arm internal resolution: as Ryujinx, a region written from the CPU side takes the texture back to 1
    int bw, bh, bpb = nvn_fmt_bpb(c->tex->d.format, &bw, &bh);
    unsigned level = c->has_view && c->view.set_levels ? c->view.base_level : 0, layer0 = c->has_view && c->view.set_layers ? c->view.min_layer : 0;
    size_t row = c->row_stride ? c->row_stride : (size_t)((c->r.width + bw - 1) / bw) * bpb;
    size_t rows = (c->r.height + bh - 1) / bh, img = c->image_stride ? c->image_stride : row * rows;   // per layer: recorded SetCopyImageStride, else tightly packed
    int is3d = c->tex->d.target == 2, nz = c->r.depth ? c->r.depth : 1;
    PD("C ser=%llu target %d %ux%ux%u format %#x lv%u sl%u region %d,%d,%d %dx%dx%d from %#llx row %zu image %zu", c->tex->serial, c->tex->d.target, c->tex->d.width, c->tex->d.height, c->tex->d.depth,
       c->tex->d.format, level, layer0, c->r.xoffset, c->r.yoffset, c->r.zoffset, c->r.width, c->r.height, c->r.depth, (unsigned long long)c->src, row, img);
    void *mb; uint64_t mo;
    if (!nvn_be_addr(c->src, img * nz, &mb, &mo)) { RED_ONCE(23, "buffer→texture copy source is in no memory pool"); return; }
    g_cut_copy = 1;
    if (is3d && passdump()) { const char *dd = getenv("DM_NVN_CBDUMP"); if (dd) {   // the source bytes of a 3D upload, beside the uniform dumps (F<frame>_c3d_<serial>.bin)
        char p[1024]; snprintf(p, sizeof p, "%s/F%llu_c3d_%llu.bin", dd, (unsigned long long)atomic_load(&g_cur_frame), (unsigned long long)c->tex->serial);
        FILE *f = fopen(p, "wb"); if (f) { fwrite((const uint8_t *)((__bridge id<MTLBuffer>)mb).contents + mo, 1, img * nz, f); fclose(f); } } }
    id<MTL4ComputeCommandEncoder> b = blit();
    pkg_gpu_wrote(c->tex, level, is3d ? 0 : layer0 + c->r.zoffset, is3d ? 1 : (unsigned)nz, c->r.xoffset, c->r.yoffset, c->r.width, c->r.height);
    { uint32_t upf; int ubpp;
      if (fmt_unpack(c->tex->d.format, &upf, &ubpp)) {   // stored in another format (fmt_unpack): the source is decompressed / expanded on the CPU into a scratch buffer, then copied as pixels into the texture
          size_t up = (size_t)c->r.width * ubpp, uimg = up * c->r.height; const uint8_t *src = (const uint8_t *)((__bridge id<MTLBuffer>)mb).contents + mo;
          id<MTLBuffer> tb = [g_dev newBufferWithLength:uimg * nz ? uimg * nz : 16 options:MTLResourceStorageModeShared];
          if (!tb) { RED_ONCE(114, "buffer→texture conversion scratch of %zu bytes failed", uimg * nz); return; }
          for (int z = 0; z < nz; z++) fmt_decode(c->tex->d.format, src + z * img, row, c->r.width, c->r.height, (uint8_t *)tb.contents + z * uimg, up);
          bc_note(c->tex->d.format, "buffer→texture copy");
          res_add(tb); defer_obj_release(tb);
          if (is3d) enc_b_copy_buffer_texture(b, tb, 0, up, uimg, MTLSizeMake(c->r.width, c->r.height, nz), t, 0, level, MTLOriginMake(c->r.xoffset, c->r.yoffset, c->r.zoffset));
          else for (int z = 0; z < nz; z++) enc_b_copy_buffer_texture(b, tb, z * uimg, up, uimg, MTLSizeMake(c->r.width, c->r.height, 1), t, layer0 + c->r.zoffset + z, level, MTLOriginMake(c->r.xoffset, c->r.yoffset, 0));
          return;
      } }
    { NVNcopyRegion dr = c->r, sr = {0, 0, 0, c->r.width, c->r.height, 1};   // S2Arm widen: upload at the game's width, then widen into place (see wd_scratch)
      if (!is3d && nz == 1 && wd_copy_xy(c->tex, t, level, &c->r, &dr)) {
          id<MTLTexture> tmp = wd_scratch(t.pixelFormat, c->r.width, c->r.height);
          if (tmp) { enc_b_copy_buffer_texture(b, (__bridge id<MTLBuffer>)mb, mo, row, img, MTLSizeMake(c->r.width, c->r.height, 1), tmp, 0, 0, MTLOriginMake(0, 0, 0));
              if (!(t.usage & MTLTextureUsageRenderTarget)) t = tex_upgrade(c->tex, t, MTLTextureUsageRenderTarget, t.pixelFormat);
              if (copy_t2t_draw(tmp, t, 0, 0, level, layer0 + c->r.zoffset, &sr, &dr, 1, 0)) return; }
          RED_ONCE(119, "widen: upload into widened storage ser=%llu (format %lu) not widened: it fills the left %d columns only", c->tex->serial, (unsigned long)t.pixelFormat, c->r.width);
          b = blit(); } }
    if (is3d)
        enc_b_copy_buffer_texture(b, (__bridge id<MTLBuffer>)mb, mo, row, img, MTLSizeMake(c->r.width, c->r.height, nz), t, 0, level, MTLOriginMake(c->r.xoffset, c->r.yoffset, c->r.zoffset));
    else
        for (int z = 0; z < nz; z++)
            enc_b_copy_buffer_texture(b, (__bridge id<MTLBuffer>)mb, mo + z * img, row, img, MTLSizeMake(c->r.width, c->r.height, 1), t, layer0 + c->r.zoffset + z, level, MTLOriginMake(c->r.xoffset, c->r.yoffset, 0));
}

// Texture copies a blit cannot do -- a format change, a scaled region or a mirrored one (MIRROR_X / MIRROR_Y) (Link's Awakening converts its 1408x792 RG11B10F scene to RGBA16F every frame; Super Mario 3D World scales 1920x1080 to 1280x720
// when leaving the title): one render pass per layer that draws the source region into the destination region, nearest or (LINEAR_FILTER) bilinear. Float, unorm and sRGB formats only, 2D / 2D array,
// destinations that can be render targets; anything else returns 0 and keeps the red line. Depth (Depth32Float / Depth32Float_Stencil8 into the same format) is drawn by writing depth from the fragment shader,
// always nearest, and stencil is written from the fragment shader too ([[stencil]] export, read through an X32_Stencil8 view of the source). Link's Awakening halves its depth-stencil buffer twice
// (1920x1080 → 960x540 → 480x270) and its depth-of-field mask pass only writes where stencil bit 1 is clear: with the stencil left as the new texture's undefined content, the mask kept its
// clear value 1.0 (full blur) everywhere and the whole picture was out of focus. Without a stencil view the stencil is cleared to 0 instead
static int fmt_int_or_ds(MTLPixelFormat f) {
    switch (f) {
        case MTLPixelFormatR8Uint: case MTLPixelFormatR8Sint: case MTLPixelFormatR16Uint: case MTLPixelFormatR16Sint: case MTLPixelFormatRG8Uint: case MTLPixelFormatRG8Sint:
        case MTLPixelFormatR32Uint: case MTLPixelFormatR32Sint: case MTLPixelFormatRG16Uint: case MTLPixelFormatRG16Sint: case MTLPixelFormatRGBA8Uint: case MTLPixelFormatRGBA8Sint:
        case MTLPixelFormatRGB10A2Uint: case MTLPixelFormatRG32Uint: case MTLPixelFormatRG32Sint: case MTLPixelFormatRGBA16Uint: case MTLPixelFormatRGBA16Sint:
        case MTLPixelFormatRGBA32Uint: case MTLPixelFormatRGBA32Sint: case MTLPixelFormatDepth16Unorm: case MTLPixelFormatDepth32Float: case MTLPixelFormatStencil8:
        case MTLPixelFormatDepth32Float_Stencil8: case MTLPixelFormatX32_Stencil8: return 1;
        default: return 0;
    }
}
static int copy_t2t_draw(id<MTLTexture> s, id<MTLTexture> d, unsigned sl, unsigned ss, unsigned dl, unsigned ds, const NVNcopyRegion *sr, const NVNcopyRegion *dr, int linear, int mirror) {
    static NSMutableDictionary<NSNumber *, id<MTLRenderPipelineState>> *pso; static id<MTLFunction> vf, ff, fd, fds; static id<MTLSamplerState> samp[2]; static id at; static id<MTLDepthStencilState> dss, dss_s; static int failed;
    if (failed || sr->width <= 0 || sr->height <= 0 || dr->width <= 0 || dr->height <= 0) return 0;
    int depth = (s.pixelFormat == MTLPixelFormatDepth32Float || s.pixelFormat == MTLPixelFormatDepth32Float_Stencil8) && d.pixelFormat == s.pixelFormat, stencil = depth && d.pixelFormat == MTLPixelFormatDepth32Float_Stencil8;
    if (!depth && (fmt_int_or_ds(s.pixelFormat) || fmt_int_or_ds(d.pixelFormat))) return 0;
    if (mtl_fmt_block(d.pixelFormat) || !(d.usage & MTLTextureUsageRenderTarget) || s.sampleCount > 1 || d.sampleCount > 1) return 0;
    if (!pso) {
        static const char *src =
            "#include <metal_stdlib>\nusing namespace metal;\n"
            "struct V { float4 p [[position]]; };\n"
            "vertex V vs(uint id [[vertex_id]]) { float2 uv = float2((id << 1) & 2, id & 2); V o; o.p = float4(uv * float2(2, -2) + float2(-1, 1), 0, 1); return o; }\n"
            // p[0] = source origin (texels) + source texels per destination texel, p[1] = destination origin + source level size
            "fragment float4 fs(V in [[stage_in]], texture2d<float> t [[texture(0)]], sampler s [[sampler(0)]], constant float4 *p [[buffer(0)]]) {\n"
            "  float2 st = p[0].xy + (in.p.xy - p[1].xy) * p[0].zw; return t.sample(s, st / p[1].zw, level(0)); }\n"
            "struct D { float d [[depth(any)]]; };\n"
            "fragment D fsd(V in [[stage_in]], depth2d<float> t [[texture(0)]], sampler s [[sampler(0)]], constant float4 *p [[buffer(0)]]) {\n"
            "  float2 st = p[0].xy + (in.p.xy - p[1].xy) * p[0].zw; D o; o.d = t.read(uint2(st)); return o; }\n"
            "struct DS { float d [[depth(any)]]; uint s [[stencil]]; };\n"
            "fragment DS fsds(V in [[stage_in]], depth2d<float> t [[texture(0)]], texture2d<uint> ts [[texture(1)]], constant float4 *p [[buffer(0)]]) {\n"
            "  float2 st = p[0].xy + (in.p.xy - p[1].xy) * p[0].zw; DS o; o.d = t.read(uint2(st)); o.s = ts.read(uint2(st)).r; return o; }\n";
        NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:@(src) options:nil error:&e];
        vf = [lib newFunctionWithName:@"vs"]; ff = [lib newFunctionWithName:@"fs"]; fd = [lib newFunctionWithName:@"fsd"]; fds = [lib newFunctionWithName:@"fsds"];
        MTLDepthStencilDescriptor *dd = [MTLDepthStencilDescriptor new]; dd.depthCompareFunction = MTLCompareFunctionAlways; dd.depthWriteEnabled = YES; dss = [g_dev newDepthStencilStateWithDescriptor:dd];
        MTLStencilDescriptor *sd_ = [MTLStencilDescriptor new]; sd_.stencilCompareFunction = MTLCompareFunctionAlways; sd_.depthStencilPassOperation = MTLStencilOperationReplace;   // Replace writes the [[stencil]] output
        dd.frontFaceStencil = dd.backFaceStencil = sd_; dss_s = [g_dev newDepthStencilStateWithDescriptor:dd];
        at = rec_table(tab_new(1, 2, 1, &e));
        for (int i = 0; i < 2; i++) { MTLSamplerDescriptor *sd = [MTLSamplerDescriptor new]; sd.minFilter = sd.magFilter = i ? MTLSamplerMinMagFilterLinear : MTLSamplerMinMagFilterNearest;
            sd.sAddressMode = sd.tAddressMode = MTLSamplerAddressModeClampToEdge; sd.supportArgumentBuffers = YES; samp[i] = [g_dev newSamplerStateWithDescriptor:sd]; }
        if (!vf || !ff || !fd || !fds || !dss || !dss_s || !at || !samp[0] || !samp[1]) { failed = 1; MLOG("【红】 cannot create the pipelines for format-converting / scaling texture copies: %s", e.localizedDescription.UTF8String); return 0; }
        pso = [NSMutableDictionary dictionary];
    }
    // Stencil: read through a stencil-only view of the source (one per layer below); without one it is cleared to 0
    id<MTLTexture> stv0 = stencil && s.pixelFormat == MTLPixelFormatDepth32Float_Stencil8 ? [s newTextureViewWithPixelFormat:MTLPixelFormatX32_Stencil8 textureType:MTLTextureType2D levels:NSMakeRange(sl, 1) slices:NSMakeRange(ss + sr->zoffset, 1)] : nil;
    int scopy = stv0 != nil;
    NSNumber *pk = @(d.pixelFormat * 2 + scopy);
    id<MTLRenderPipelineState> ps = pso[pk];
    if (!ps) {
        MTLRenderPipelineDescriptor *pd = [MTLRenderPipelineDescriptor new]; pd.vertexFunction = vf; pd.fragmentFunction = depth ? (scopy ? fds : fd) : ff;
        if (depth) { pd.depthAttachmentPixelFormat = d.pixelFormat; if (stencil) pd.stencilAttachmentPixelFormat = d.pixelFormat; } else pd.colorAttachments[0].pixelFormat = d.pixelFormat;
        NSError *e = nil; ps = [g_dev newRenderPipelineStateWithDescriptor:pd error:&e];
        if (!ps) { RED_ONCE(83, "format-converting / scaling texture copy: cannot create the pipeline for destination format %lu: %s", (unsigned long)d.pixelFormat, e.localizedDescription.UTF8String); return 0; }
        pso[pk] = ps;
    }
    unsigned sw = MAX(s.width >> sl, 1ul), sh = MAX(s.height >> sl, 1ul), dw = MAX(d.width >> dl, 1ul), dh = MAX(d.height >> dl, 1ul);
    if ((unsigned)(dr->xoffset + dr->width) > dw || (unsigned)(dr->yoffset + dr->height) > dh) return 0;
    int nz = sr->depth ? sr->depth : 1;
    rp_end(); if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    for (int z = 0; z < nz; z++) {
        id<MTLTexture> sv = [s newTextureViewWithPixelFormat:s.pixelFormat textureType:MTLTextureType2D levels:NSMakeRange(sl, 1) slices:NSMakeRange(ss + sr->zoffset + z, 1)];
        id<MTLBuffer> pb; size_t po = arena_alloc(32, &pb);   // parameters in the frame arena (resident already): a fresh 32-byte buffer per copy was a residency add, a commit and a release (Link's Awakening, about 11 a frame)
        if (!sv || !pb) { RED_ONCE(84, "format-converting / scaling texture copy: cannot create the source view / argument block"); return z > 0; }
        float *p = (float *)((uint8_t *)pb.contents + po); p[0] = sr->xoffset; p[1] = sr->yoffset; p[2] = (float)sr->width / dr->width; p[3] = (float)sr->height / dr->height;
        if (mirror & NVN_COPY_FLAGS_MIRROR_X_BIT) { p[0] += sr->width; p[2] = -p[2]; }   // mirrored: walk the source region from its far edge
        if (mirror & NVN_COPY_FLAGS_MIRROR_Y_BIT) { p[1] += sr->height; p[3] = -p[3]; }
        p[4] = dr->xoffset; p[5] = dr->yoffset; p[6] = sw; p[7] = sh;
        MTL4RenderPassDescriptor *rp = pass_desc();
        MTLRenderPassAttachmentDescriptor *a = depth ? (MTLRenderPassAttachmentDescriptor *)rp.depthAttachment : (MTLRenderPassAttachmentDescriptor *)rp.colorAttachments[0];
        int whole = !dr->xoffset && !dr->yoffset && (unsigned)dr->width == dw && (unsigned)dr->height == dh;   // the copy draws every pixel of the level (no blending, no discard): its old content is not loaded (Link's Awakening copies its scene this way every frame)
        a.texture = d; a.level = dl; a.slice = ds + dr->zoffset + z; a.loadAction = whole ? MTLLoadActionDontCare : MTLLoadActionLoad; a.storeAction = MTLStoreActionStore;
        id<MTLTexture> stv = scopy ? (z ? [s newTextureViewWithPixelFormat:MTLPixelFormatX32_Stencil8 textureType:MTLTextureType2D levels:NSMakeRange(sl, 1) slices:NSMakeRange(ss + sr->zoffset + z, 1)] : stv0) : nil;
        if (stencil) { MTLRenderPassStencilAttachmentDescriptor *st = rp.stencilAttachment; st.texture = d; st.level = dl; st.slice = a.slice; st.loadAction = scopy ? (whole ? MTLLoadActionDontCare : MTLLoadActionLoad) : MTLLoadActionClear; st.clearStencil = 0; st.storeAction = MTLStoreActionStore; }
        ser_gate(); id<MTL4RenderCommandEncoder> en = enc_r_begin(rp);
        if (depth) [en setDepthStencilState:scopy ? dss_s : dss];
        enc_r_table(en, at, MTLRenderStageFragment);
        tab_tex(at, sv, 0); if (stv) tab_tex(at, stv, 1); tab_samp(at, samp[!!linear && !depth], 0); tab_buf(at, pb, po, 0);
        [en setViewport:(MTLViewport){dr->xoffset, dr->yoffset, dr->width, dr->height, 0, 1}];
        [en setScissorRect:(MTLScissorRect){(NSUInteger)dr->xoffset, (NSUInteger)dr->yoffset, (NSUInteger)dr->width, (NSUInteger)dr->height}];
        [en setRenderPipelineState:ps]; enc_r_draw(en, MTLPrimitiveTypeTriangle, 0, 3); enc_r_end(en);
        defer_obj_unref(sv); if (stv) defer_obj_unref(stv);   // released after this submission has run
    }
    args_dirty_all(); g_pso_dirty = g_dss_dirty = 1;
    { static int once[2]; if (!once[depth]++) MLOG("format-converting / scaling texture copy: first case %dx%d format %lu → %dx%d format %lu%s%s", sr->width, sr->height, (unsigned long)s.pixelFormat, dr->width, dr->height, (unsigned long)d.pixelFormat,
                                                    linear && !depth ? " (bilinear)" : "", stencil ? (scopy ? " (depth + stencil)" : " (no stencil view possible, cleared to 0)") : ""); }
    return 1;
}
// GPU: texture -> texture (previously mislisted as a no-op, 3 times per frame on the character select page). Same size, not mirrored, same format -> blit layer by layer; the other semantics (scaling with filtering, mirroring, format change) cannot be expressed by blit: report a failure, to be implemented
// S2Arm widen: copies between render targets whose storage tex_widen widened. A copy of the whole game width from one widened storage into another takes the whole widened width
//   (the widened strips go with the picture, as every full-screen pass that draws it does); others stay in game coordinates, the left part, counted on the first ones (a widened
//   texture copied into an unwidened one, or a part of one: not seen yet, so not mapped)
static uint64_t g_wd_copy_full, g_wd_copy_part;
static void copy_t2t_(const p_copy_t2t *c);
static void dlss_eval(const p_dlss *d, uint32_t size);   // nvn_dlss.inc
static void copy_t2t(const p_copy_t2t *c) {
    // GPU 写出的贴图拷到别处，目标也是 GPU 内容，不当 16:9 原比例页的来源（核心按 src 判：CPU 供图拷来拷去仍是图片；10-26 八方2 场景图）
    if (g_wd > 0 && c->src && c->dst) { pthread_mutex_lock(&g_wd_mu); s2a_widen_gpu_wrote((uint32_t)c->dst->serial, (uint32_t)c->src->serial); pthread_mutex_unlock(&g_wd_mu); }
    if (rs_on() && c->dst && (c->flags & DM_COPY_RESOLVE) && rs_state(tex_mtl(c->dst)) == RS_SCALED) rs_rescale(tex_mtl(c->dst), 0, "多重采样解析的目标");   // S2Arm internal resolution: a resolve needs equal sizes (multisample storages are never scaled)
    if ((c->flags & DM_COPY_RESOLVE) && c->src && c->dst) wd_widen_resolve_dst(c->src, c->dst);   // S2Arm widen: a widened multisample target resolves into a destination widened the same
    // S2Arm widen: the same copied the same way between two textures of one game size (11-02 Mario & Sonic Tokyo 2020: each frame copies its widened 1920x1080 canvas, drawn in the
    //   handheld 1280x720 corner, into the unwidened swap-chain image; each side mapped by its own storage turned that into a squeezing copy and the presented image stayed 16:9)
    else if (c->src && c->dst && c->src->d.width == c->dst->d.width && c->src->d.height == c->dst->d.height && !memcmp(&c->sr, &c->dr, sizeof c->sr)) wd_widen_resolve_dst(c->src, c->dst);
    if ((g_wd_widened || rs_on()) && c->src && c->dst) {
        id<MTLTexture> s = tex_mtl(c->src), d = tex_mtl(c->dst);
        unsigned sl = c->has_sv && c->sv.set_levels ? c->sv.base_level : 0, dl = c->has_dv && c->dv.set_levels ? c->dv.base_level : 0;
        int sw0 = (int)MAX(c->src->d.width >> sl, 1u), dw0 = (int)MAX(c->dst->d.width >> dl, 1u), sw1 = s ? (int)MAX(s.width >> sl, 1u) : sw0, dw1 = d ? (int)MAX(d.width >> dl, 1u) : dw0;
        int sh0 = (int)MAX(c->src->d.height >> sl, 1u), dh0 = (int)MAX(c->dst->d.height >> dl, 1u), sh1 = s ? (int)MAX(s.height >> sl, 1u) : sh0, dh1 = d ? (int)MAX(d.height >> dl, 1u) : dh0;
        // y by each texture's storage ÷ game height too: the narrower screen's tall widening (s2a_widen_tex_h) and the internal resolution both change it.
        //   11-02 Silksong on the narrow Duo screen: x only copied the top 576 rows of a 1024x702 tall scene into a 1024x576 texture that is then composited back = a Ky-scaled ghost
        if (c->src->d.target == 2 || c->dst->d.target == 2) sh1 = sh0, dh1 = dh0, sw1 = sw0, dw1 = dw0;   // 3D: never widened / scaled, a depth slice's height is not a plane's
        if (sw1 != sw0 || dw1 != dw0 || sh1 != sh0 || dh1 != dh0) {
            // Ryujinx scales both rectangles of a copy by their own texture's scale (TwodClass: srcX × srcScale, dstX × dstScale; TextureCopy); here the scale is the storage's
            // horizontal widening at that level (stored width ÷ game width). Equal ratios keep a plain copy; unequal ones become a scaling copy (copy_t2t_draw)
            p_copy_t2t cc = *c;
            #define WD_MAPX(x, w0, w1) ((int)lround((double)(x) * (w1) / (w0)))
            int sx0 = WD_MAPX(c->sr.xoffset, sw0, sw1), sx1 = WD_MAPX(c->sr.xoffset + c->sr.width, sw0, sw1), dx0 = WD_MAPX(c->dr.xoffset, dw0, dw1), dx1 = WD_MAPX(c->dr.xoffset + c->dr.width, dw0, dw1);
            #undef WD_MAPX
            cc.sr.xoffset = sx0; cc.sr.width = sx1 - sx0; cc.dr.xoffset = dx0; cc.dr.width = dx1 - dx0;
            if (sh1 != sh0 || dh1 != dh0) {   // tall widening / internal resolution: y by each texture's own storage ÷ game height too (Ryujinx scales both rectangles by their texture's scale)
                int sy0 = (int)lround((double)c->sr.yoffset * sh1 / sh0), sy1 = (int)lround((double)(c->sr.yoffset + c->sr.height) * sh1 / sh0);
                int dy0 = (int)lround((double)c->dr.yoffset * dh1 / dh0), dy1 = (int)lround((double)(c->dr.yoffset + c->dr.height) * dh1 / dh0);
                cc.sr.yoffset = sy0; cc.sr.height = sy1 - sy0; cc.dr.yoffset = dy0; cc.dr.height = dy1 - dy0;
            }
            if (c->sr.xoffset == 0 && c->sr.width == sw0 && c->dr.xoffset == 0 && c->dr.width == dw0) g_wd_copy_full++;
            else if (g_wd_copy_part++ < 6) MLOG("widen: texture copy ser=%llu (%d wide, storage %d) x %d+%d → ser=%llu (%d wide, storage %d) x %d+%d mapped to x %d+%d → x %d+%d (%llu so far)",
                                                 (unsigned long long)c->src->serial, sw0, sw1, c->sr.xoffset, c->sr.width, (unsigned long long)c->dst->serial, dw0, dw1, c->dr.xoffset, c->dr.width,
                                                 cc.sr.xoffset, cc.sr.width, cc.dr.xoffset, cc.dr.width, (unsigned long long)g_wd_copy_part);
            copy_t2t_(&cc); return;
        }
    }
    copy_t2t_(c);
}
// Downsample from a multisample texture of another size (11-02 Digimon Story Time Stranger: 1920x1080 4 samples → 1280x720, with or without widening): the game renders its handheld
//   1280x720 picture into the corner of a 1920x1080 multisample target and resolves that corner into a 1280x720 texture, so the destination takes the source's corner of its own size
//   (a whole-source scaling copy put the frame into the lower-left 2/3 of the screen with the rest black: Mac quick run dg_qt2). Metal's resolve needs equal sizes: resolve into a
//   single-sample scratch of the source's size, then copy the corner of the destination's game size (each side in its own storage, i.e. widened alike) onto the whole destination.
//   0 = not done (the caller reports it)
static int copy_resolve_scaled(const p_copy_t2t *c, id<MTLTexture> s, id<MTLTexture> d0, unsigned sl, unsigned sz0, unsigned dl, unsigned dz0) {
    static id<MTLTexture> tmp;
    MTLPixelFormat pf = s.pixelFormat;
    int depth = pf == MTLPixelFormatDepth32Float || pf == MTLPixelFormatDepth16Unorm || pf == MTLPixelFormatDepth32Float_Stencil8;
    if (!depth && (fmt_int_or_ds(pf) || mtl_fmt_block(pf))) return 0;
    id<MTLTexture> d = d0;
    if (!(d.usage & MTLTextureUsageRenderTarget) && !depth) d = tex_upgrade(c->dst, d, MTLTextureUsageRenderTarget, d.pixelFormat);
    if (!(d.usage & MTLTextureUsageRenderTarget)) return 0;
    if (!tmp || tmp.width != s.width || tmp.height != s.height || tmp.pixelFormat != pf) {
        if (tmp) defer_obj_release(tmp);
        MTLTextureDescriptor *td = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:pf width:s.width height:s.height mipmapped:NO];
        td.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead; td.storageMode = MTLStorageModePrivate;
        tmp = [g_dev newTextureWithDescriptor:td];
        if (!tmp) return 0;
        res_add(tmp);
    }
    rp_end(); if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    id rpd = pass_desc(); MTLRenderPassDescriptor *rp = (MTLRenderPassDescriptor *)rpd;   // the attachment properties both descriptor classes share (as the clear-only pass below; MTL4 ratchet)
    MTLRenderPassAttachmentDescriptor *a = depth ? rp.depthAttachment : rp.colorAttachments[0];
    a.texture = s; a.level = sl; a.slice = sz0; a.resolveTexture = tmp; a.resolveLevel = 0; a.resolveSlice = 0;
    a.loadAction = MTLLoadActionLoad; a.storeAction = MTLStoreActionStoreAndMultisampleResolve;
    if (depth) rp.depthAttachment.depthResolveFilter = MTLMultisampleDepthResolveFilterSample0;
    ser_gate(); enc_r_end(enc_r_begin(rpd));
    unsigned dw = (unsigned)MAX(d.width >> dl, 1ul), dh = (unsigned)MAX(d.height >> dl, 1ul);
    // the source's corner of the destination's game size, in the source's storage (storage ÷ game width / height of the source, so a widened source gives its widened corner)
    unsigned gsw = MAX(c->src->d.width >> sl, 1u), gsh = MAX(c->src->d.height >> sl, 1u), gdw = MAX(c->dst->d.width >> dl, 1u), gdh = MAX(c->dst->d.height >> dl, 1u);
    int rw = (int)MIN((unsigned long)lround((double)gdw * tmp.width / gsw), (unsigned long)tmp.width), rh = (int)MIN((unsigned long)lround((double)gdh * tmp.height / gsh), (unsigned long)tmp.height);
    // 角的起点取游戏给的源矩形起点（换到源存储；审计 P1-88：原先写死 0,0，源矩形不从原点起的解析取错了角）。数码宝贝的源矩形从 0,0 起，不变
    int rx = (int)MIN((unsigned long)lround((double)MAX(c->sr.xoffset, 0) * tmp.width / gsw), tmp.width - (unsigned long)rw);
    int ry = (int)MIN((unsigned long)lround((double)MAX(c->sr.yoffset, 0) * tmp.height / gsh), tmp.height - (unsigned long)rh);
    NVNcopyRegion sr = {rx, ry, 0, rw, rh, 1}, dr = {0, 0, 0, (int)dw, (int)dh, 1};
    if (!copy_t2t_draw(tmp, d, 0, 0, dl, dz0, &sr, &dr, 1, 0)) return 0;
    static int once; if (!once++) MLOG("Downsample: first resolve of another size %lux%lu %lu samples → %ux%u format %lu (resolve, then the corner %dx%d onto the destination)", (unsigned long)s.width,
                                      (unsigned long)s.height, (unsigned long)s.sampleCount, dw, dh, (unsigned long)pf, rw, rh);
    return 1;
}
static void copy_t2t_(const p_copy_t2t *c) {
    if (fold_copy_skip(c->src, "texture copy source") || fold_copy_skip(c->dst, "texture copy destination")) return;
    if (c->src) xv_check(c->src->serial, c->has_sv && c->sv.set_levels ? c->sv.base_level : 0, c->has_sv && c->sv.set_layers ? c->sv.min_layer : 0, "texture copy source");
    rp_flush();   // Land the pending pure-clear render pass first (zero-source candidates only enter the set when the render pass ends); the blit() below would end the render pass anyway
    if (c->dst) zskip_del(c->dst->serial);
    if (c->src && c->dst && c->sr.xoffset == 0 && c->sr.yoffset == 0 && c->dr.xoffset == 0 && c->dr.yoffset == 0
        && c->sr.width == (int)c->src->d.width && c->sr.height == (int)c->src->d.height && c->dr.width == (int)c->dst->d.width && c->dr.height == (int)c->dst->d.height) {
        int sl = c->has_sv && c->sv.set_levels ? c->sv.base_level : 0, dl = c->has_dv && c->dv.set_levels ? c->dv.base_level : 0;
        int ss = c->has_sv && c->sv.set_layers ? c->sv.min_layer : 0, ds = c->has_dv && c->dv.set_layers ? c->dv.min_layer : 0;
        if (zskip_has(c->src->serial, sl, ss)) zskip_add(c->dst->serial, dl, ds);
    }
    id<MTLTexture> s = tex_mtl(c->src), d = tex_mtl(c->dst);
    PD("T src=%llu dst=%llu %dx%dx%d→%dx%dx%d flags=%#x", c->src->serial, c->dst->serial, c->sr.width, c->sr.height, c->sr.depth, c->dr.width, c->dr.height, c->dr.depth, c->flags);
    if (!s || !d) return;
    unsigned sl = c->has_sv && c->sv.set_levels ? c->sv.base_level : 0, dl = c->has_dv && c->dv.set_levels ? c->dv.base_level : 0;
    unsigned sz0 = c->has_sv && c->sv.set_layers ? c->sv.min_layer : 0, dz0 = c->has_dv && c->dv.set_layers ? c->dv.min_layer : 0;
    pkg_gpu_wrote(c->dst, dl, c->dst->d.target == 2 ? 0 : dz0 + (unsigned)c->dr.zoffset, c->dst->d.target == 2 ? 1 : (unsigned)MAX(c->dr.depth, 1), c->dr.xoffset, c->dr.yoffset, c->dr.width, c->dr.height);
    if (c->flags & DM_COPY_RESOLVE) {   // Downsample: multisample resolve into the single-sample destination (depth takes sample 0); with equal sample counts it is a plain whole copy
        if (s.sampleCount == d.sampleCount && s.pixelFormat == d.pixelFormat && s.width == d.width && s.height == d.height) {
            enc_b_copy_texture(blit(), s, sz0, sl, MTLOriginMake(0, 0, 0), MTLSizeMake(s.width, s.height, 1), d, dz0, dl, MTLOriginMake(0, 0, 0));
            return;
        }
        if (s.sampleCount > 1 && d.sampleCount == 1 && s.pixelFormat == d.pixelFormat && (s.width != d.width || s.height != d.height) && copy_resolve_scaled(c, s, d, sl, sz0, dl, dz0)) return;
        if (s.sampleCount <= 1 || d.sampleCount != 1 || s.pixelFormat != d.pixelFormat || s.width != d.width || s.height != d.height) {
            RED_ONCE(72, "Downsample case not implemented: %lux%lu %lu samples format %lu → %lux%lu %lu samples format %lu", (unsigned long)s.width, (unsigned long)s.height, (unsigned long)s.sampleCount,
                     (unsigned long)s.pixelFormat, (unsigned long)d.width, (unsigned long)d.height, (unsigned long)d.sampleCount, (unsigned long)d.pixelFormat);
            return;
        }
        rp_end(); if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
        MTL4RenderPassDescriptor *rp = pass_desc();
        MTLPixelFormat pf = s.pixelFormat;
        int depth = pf == MTLPixelFormatDepth32Float || pf == MTLPixelFormatDepth16Unorm || pf == MTLPixelFormatDepth32Float_Stencil8;
        MTLRenderPassAttachmentDescriptor *a = depth ? rp.depthAttachment : rp.colorAttachments[0];
        a.texture = s; a.level = sl; a.slice = sz0; a.resolveTexture = d; a.resolveLevel = dl; a.resolveSlice = dz0;
        a.loadAction = MTLLoadActionLoad; a.storeAction = MTLStoreActionStoreAndMultisampleResolve;
        if (depth) rp.depthAttachment.depthResolveFilter = MTLMultisampleDepthResolveFilterSample0;
        ser_gate(); enc_r_end(enc_r_begin(rp));
        return;
    }
    PD("t src=%llu lv%u sl%u xyz=%d,%d,%d dst=%llu lv%u sl%u xyz=%d,%d,%d size=%d,%d,%d", c->src->serial, sl, sz0, c->sr.xoffset, c->sr.yoffset, c->sr.zoffset,
       c->dst->serial, dl, dz0, c->dr.xoffset, c->dr.yoffset, c->dr.zoffset, c->sr.width, c->sr.height, c->sr.depth);
    int s3 = c->src->d.target == 2, d3 = c->dst->d.target == 2, nz = c->sr.depth ? c->sr.depth : 1;
    // The draw path renders into the destination: one made without render-target use (packaged) gets it first, as a whole-level clear does (Paper Mario: The Thousand-Year Door copies a
    // 128x128 RGBA8 render target into an RG8 texture, mirrored in Y)
    if ((c->sr.width != c->dr.width || c->sr.height != c->dr.height || s.pixelFormat != d.pixelFormat || (c->flags & (NVN_COPY_FLAGS_MIRROR_X_BIT | NVN_COPY_FLAGS_MIRROR_Y_BIT))) && !s3 && !d3
        && !(d.usage & MTLTextureUsageRenderTarget) && !mtl_fmt_block(d.pixelFormat) && d.sampleCount == 1 && !fmt_int_or_ds(s.pixelFormat) && !fmt_int_or_ds(d.pixelFormat))
        d = tex_upgrade(c->dst, d, MTLTextureUsageRenderTarget, d.pixelFormat);
    if ((c->sr.width != c->dr.width || c->sr.height != c->dr.height || s.pixelFormat != d.pixelFormat || (c->flags & (NVN_COPY_FLAGS_MIRROR_X_BIT | NVN_COPY_FLAGS_MIRROR_Y_BIT))) && !s3 && !d3
        && (c->sr.depth ? c->sr.depth : 1) == (c->dr.depth ? c->dr.depth : 1)
        && !(c->flags & ~(NVN_COPY_FLAGS_ENGINE_2D_BIT | NVN_COPY_FLAGS_LINEAR_FILTER_BIT | NVN_COPY_FLAGS_MIRROR_X_BIT | NVN_COPY_FLAGS_MIRROR_Y_BIT))
        && copy_t2t_draw(s, d, sl, sz0, dl, dz0, &c->sr, &c->dr, !!(c->flags & NVN_COPY_FLAGS_LINEAR_FILTER_BIT), c->flags)) return;   // format change / scaling / mirroring: draw it (see copy_t2t_draw)
    if (c->sr.width != c->dr.width || c->sr.height != c->dr.height || (c->sr.depth ? c->sr.depth : 1) != (c->dr.depth ? c->dr.depth : 1) || (c->flags & ~NVN_COPY_FLAGS_ENGINE_2D_BIT & ~NVN_COPY_FLAGS_LINEAR_FILTER_BIT)
        || s.pixelFormat != d.pixelFormat || s3 != d3) {
        RED_ONCE(33, "texture→texture copy case not implemented: %dx%dx%d→%dx%dx%d flags %#x format %lu→%lu 3D %d→%d", c->sr.width, c->sr.height, c->sr.depth, c->dr.width, c->dr.height, c->dr.depth,
                 c->flags, (unsigned long)s.pixelFormat, (unsigned long)d.pixelFormat, s3, d3);
        return;
    }
    id<MTL4ComputeCommandEncoder> b = blit();
    if (s3)
        enc_b_copy_texture(b, s, 0, sl, MTLOriginMake(c->sr.xoffset, c->sr.yoffset, c->sr.zoffset), MTLSizeMake(c->sr.width, c->sr.height, nz), d, 0, dl, MTLOriginMake(c->dr.xoffset, c->dr.yoffset, c->dr.zoffset));
    else
        for (int z = 0; z < nz; z++)
            enc_b_copy_texture(b, s, sz0 + c->sr.zoffset + z, sl, MTLOriginMake(c->sr.xoffset, c->sr.yoffset, 0), MTLSizeMake(c->sr.width, c->sr.height, 1), d, dz0 + c->dr.zoffset + z, dl, MTLOriginMake(c->dr.xoffset, c->dr.yoffset, 0));
    // Diagnostic DM_NVN_T2T_TRACE=WxH:file: after each copy into an RGBA16F texture of that size, copy the result once more into a trace buffer on the GPU timeline (frame numbers kept on the CPU side); after 240 copies write the file
    { static int on = -1; static uint32_t tw, th; static const char *tf; static id<MTLBuffer> tb; static int tn; static uint64_t tfr[240], from;
      if (on < 0) { const char *e = getenv("DM_NVN_T2T_TRACE"), *fe = getenv("DM_NVN_T2T_FROM"); on = e && sscanf(e, "%ux%u", &tw, &th) == 2 && (tf = strchr(e, ':')) && *++tf; from = fe ? strtoull(fe, NULL, 10) : 0; }
      if (on > 0 && tn < 240 && atomic_load(&g_cur_frame) >= from && d.width == tw && d.height == th && d.pixelFormat == MTLPixelFormatRGBA16Float && !s3) {
          if (!tb) { tb = [g_dev newBufferWithLength:(size_t)240 * tw * th * 8 options:MTLResourceStorageModeShared]; res_add(tb); }
          enc_b_copy_texture_buffer(blit(), d, dz0, dl, MTLOriginMake(0, 0, 0), MTLSizeMake(tw, th, 1), tb, (size_t)tn * tw * th * 8, (size_t)tw * 8, (size_t)tw * th * 8);
          tfr[tn++] = atomic_load(&g_cur_frame);
          if (tn == 240) {
              rp_end(); if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
              mtl_finish_gpu();
              FILE *f = fopen(tf, "wb");
              if (f) { fprintf(f, "%u %u %d\n", tw, th, tn); fwrite(tfr, 8, 240, f); fwrite(tb.contents, 1, (size_t)240 * tw * th * 8, f); fclose(f); }
              MLOG("[t2t-trace] %d copies → %s (frames %llu–%llu)", tn, tf, (unsigned long long)tfr[0], (unsigned long long)tfr[239]);
          }
      }
    }
}

// The colour channels a Metal format has, as a channel write mask: a clear whose mask covers them all writes every texel whole (FINAL FANTASY TACTICS - The Ivalice Chronicles clears an
// R8 render target with mask 0x1)
static unsigned mtl_pf_chmask(MTLPixelFormat pf) {
    switch ((int)pf) {
        case 1: return 0x8;                                                                                      // A8
        case 10: case 11: case 12: case 13: case 14: case 20: case 22: case 23: case 24: case 25: case 53: case 54: case 55: return 0x1;   // R8 / R16 / R32
        case 30: case 31: case 32: case 33: case 34: case 60: case 62: case 63: case 64: case 65: case 103: case 104: case 105: return 0x3;   // RG8 / RG16 / RG32
        case 40: case 92: case 93: return 0x7;                                                                   // B5G6R5 / RG11B10F / RGB9E5
    }
    return 0xf;
}
// GPU: clear a texture region with the given value (previously mislisted as a no-op, called 5 times at initialization; the initial value of a Metal private texture is undefined, and the game relies on the cleared initial value).
// Whole level and whole face, all four channels written -> open one clear-only render pass per layer / depth slice (the hardware converts the clear value by the texture format, including integer and depth);
// A single-sample 2D colour region / channel mask uses the same typed clear triangle as attachment clears; unsupported targets and formats report a failure.
static void clear_tex_tri(const p_clear_tex *c, id<MTLTexture> t, unsigned level, unsigned layer);
static void clear_tex(const p_clear_tex *c) {
    if (!(c->mask & 0xf) || !c->r.width || !c->r.height) return;
    if (fold_copy_skip(c->tex, "texture clear")) return;
    rp_flush();   // Land pending attachment clears before this write, including before an upgrade copies the old texture.
    if (c->tex) zskip_del(c->tex->serial);
    id<MTLTexture> t = tex_mtl(c->tex);
    // double 精确表示所有 int32/uint32 值；不能先经过 float 或把负数按 uint32 解释。
    MTLClearColor color = c->value_type == CLEAR_TEX_UINT ? MTLClearColorMake(c->c.u[0], c->c.u[1], c->c.u[2], c->c.u[3]) :
                          c->value_type == CLEAR_TEX_INT ? MTLClearColorMake(c->c.i[0], c->c.i[1], c->c.i[2], c->c.i[3]) :
                          MTLClearColorMake(c->c.f[0], c->c.f[1], c->c.f[2], c->c.f[3]);
    PD("X ser=%llu view format %#x region %d,%d,%d %dx%dx%d mask %#x %s %g,%g,%g,%g", c->tex->serial, c->has_view && c->view.set_format ? c->view.format : -1, c->r.xoffset, c->r.yoffset, c->r.zoffset, c->r.width, c->r.height, c->r.depth, c->mask,
       c->value_type == CLEAR_TEX_UINT ? "ui" : c->value_type == CLEAR_TEX_INT ? "i" : "f", color.red, color.green, color.blue, color.alpha);
    if (!t) return;
    unsigned lv = c->has_view && c->view.set_levels ? c->view.base_level : 0, l0 = c->has_view && c->view.set_layers ? c->view.min_layer : 0;
    if (lv >= t.mipmapLevelCount) { RED_ONCE(44, "texture clear level %u outside %lu levels", lv, (unsigned long)t.mipmapLevelCount); return; }
    // S2Arm widen: a whole-width clear gives the target's side bands this frame's content, as an attachment clear does (OP_CLEAR_COLOR): without it the first draw that frame takes
    //   the sides as stale and clears them black (WidenSession.Draw side fallback). 11-02 Mario & Sonic Tokyo 2020: the half-size effect layer is texture-cleared to (0, 0, 0, 1) each frame,
    //   its first particle draw then zeroed columns [0, 88) of 977, and compositing it (dst × src alpha) blacked the scene's left 9%.
    //   Only when the storage is already widened (the clear below reaches the sides): a clear before the first widening lands on the game-width storage and tex_widen copies it
    //   to the origin, so the added right strip is unwritten (Mario Kart 8 split-screen race intro: reporting it left the right 9% dark) while the left strip the fallback would
    //   clear holds the clear value (the Mario & Sonic results page went black on the left again). Such a clear is repeated on the widened storage instead (wd_pclr_apply)
    if (g_wd > 0 && c->tex && rs_cw(t) > c->tex->d.width && !c->r.xoffset && (unsigned)c->r.width >= MAX(c->tex->d.width >> lv, 1u)) s2a_widen_target_cleared((uint32_t)c->tex->serial);
    else if (g_wd > 0 && c->tex && !c->r.xoffset && !c->r.yoffset && (unsigned)c->r.width >= MAX(c->tex->d.width >> lv, 1u) && (unsigned)c->r.height >= MAX(c->tex->d.height >> lv, 1u))
        wd_pclr_note(c);   //   not widened yet: wd_widen_rts repeats this clear on the widened storage, so the strip it adds holds the clear value too (wd_pclr_apply)
    //   A clear is a GPU write: a texture not widened that is only cleared is no CPU-supplied picture, so the core must not start a 16:9 page on its source (as wd_dispatch reports
    //   image writes). 11-02 Mario & Sonic line-up page: the effect layer, cleared and not drawn that frame, was composited onto the scene as a "page", sides [0, 178) cleared black
    if (g_wd > 0 && c->tex && rs_cw(t) <= c->tex->d.width) { pthread_mutex_lock(&g_wd_mu); s2a_widen_gpu_wrote((uint32_t)c->tex->serial, 0); pthread_mutex_unlock(&g_wd_mu); }
    pkg_gpu_wrote(c->tex, lv, t.textureType == MTLTextureType3D ? 0 : l0 + (unsigned)c->r.zoffset, t.textureType == MTLTextureType3D ? 1 : (unsigned)MAX(c->r.depth, 1), c->r.xoffset, c->r.yoffset, c->r.width, c->r.height);
    p_clear_tex rsc;
    if (g_wd > 0 && c->tex && (rs_cw(t) > c->tex->d.width || rs_ch(t) > c->tex->d.height)) {   // S2Arm widen: the region in the widened storage (canvas units), as an attachment's scissored clear (wd_clear_x / wd_clear_y);
        //   before this a texture clear stayed in game texels and left the widened strip of a cleared level with old memory (11-02 Mario Party bloom mip chain, see wd_clear_x)
        long x0 = c->r.xoffset, x1 = x0 + c->r.width, y0 = c->r.yoffset, y1 = y0 + c->r.height, cw = (long)MAX(rs_cw(t) >> lv, 1u), ch = (long)MAX(rs_ch(t) >> lv, 1u);
        wd_clear_x(c->tex, lv, &x0, &x1); wd_clear_y(c->tex, &y0, &y1); if (x1 > cw) x1 = cw; if (y1 > ch) y1 = ch;
        rsc = *c; rsc.r.xoffset = (int)x0; rsc.r.yoffset = (int)y0; rsc.r.width = (int)(x1 - x0); rsc.r.height = (int)(y1 - y0); c = &rsc;
    }
    { double rss = rs_of(t); if (rss != 1.0) {   // S2Arm internal resolution: the region in storage texels from here on (the guest-byte bookkeeping above stays in game texels)
        long x = c->r.xoffset, y = c->r.yoffset, ww = c->r.width, hh = c->r.height; rs_rect(rss, &x, &y, &ww, &hh);
        rsc = *c; rsc.r.xoffset = (int)x; rsc.r.yoffset = (int)y; rsc.r.width = (int)ww; rsc.r.height = (int)hh; c = &rsc; } }
    NSUInteger w = MAX(t.width >> lv, 1u), h = MAX(t.height >> lv, 1u);
    int is3d = t.textureType == MTLTextureType3D, nz = c->r.depth ? c->r.depth : 1;
    NSUInteger slices = is3d ? MAX(t.depth >> lv, 1u) : t.arrayLength * (t.textureType == MTLTextureTypeCube || t.textureType == MTLTextureTypeCubeArray ? 6 : 1);
    if (c->r.xoffset < 0 || c->r.yoffset < 0 || c->r.zoffset < 0 || c->r.width < 0 || c->r.height < 0 || nz < 0 ||
        (uint64_t)c->r.xoffset + c->r.width > w || (uint64_t)c->r.yoffset + c->r.height > h ||
        (uint64_t)(is3d ? 0 : l0) + c->r.zoffset + nz > slices) {
        RED_ONCE(44, "texture clear region outside mip / layer bounds"); return;
    }
    int plane2d = t.textureType == MTLTextureType2D || t.textureType == MTLTextureType2DArray;
    int whole = !c->r.xoffset && !c->r.yoffset && (NSUInteger)c->r.width == w && (NSUInteger)c->r.height == h;
    if (!(t.usage & MTLTextureUsageRenderTarget) && !mtl_fmt_block(t.pixelFormat) && t.sampleCount == 1 &&
        (plane2d || (whole && (c->mask & mtl_pf_chmask(t.pixelFormat)) == mtl_pf_chmask(t.pixelFormat))))
        t = tex_upgrade(c->tex, t, MTLTextureUsageRenderTarget, t.pixelFormat);   // Keep every old texel when adding render-target use.
    if (c->has_view && c->view.set_format) {   // View with changed format: the clear value is interpreted in the view format (all 5 of the game's calls are the ui version with an integer view), and the clear is done on a view of the same format
        uint32_t vpf = 0; uint8_t swz[4];
        if (!nvn_fmt_to_mtl(c->view.format, &vpf, swz) || !vpf) { RED_ONCE(42, "texture clear view format %#x has no equivalent", c->view.format); return; }
        // Same Metal validation rule as attach(): an incompatible view aborts the process. A no-BC BC texture
        // cleared through a 16-byte block view is one such case; clear in the base format instead.
        int compat = mtl_pfv_compatible(t.pixelFormat, (MTLPixelFormat)vpf);
        if (!compat) RED_ONCE(185, "texture clear view format %#x (Metal %u) is not compatible with base texture Metal format %lu: cleared in the base format", c->view.format, vpf, (unsigned long)t.pixelFormat);
        if (compat && tex_need_pfv(t.pixelFormat, (MTLPixelFormat)vpf) && !(t.usage & MTLTextureUsagePixelFormatView)) t = tex_upgrade_pfv(c->tex, t, (MTLPixelFormat)vpf);
        if (compat && tex_need_pfv(t.pixelFormat, (MTLPixelFormat)vpf)) {
            id<MTLTexture> v = [t newTextureViewWithPixelFormat:(MTLPixelFormat)vpf];
            if (!v) { RED_ONCE(43, "texture clear: cannot create the view: format %lu → %u", (unsigned long)t.pixelFormat, vpf); return; }
            t = v; defer_obj_unref(v);
        }
    }
    MTLPixelFormat pf = t.pixelFormat;
    int depth = pf == MTLPixelFormatDepth32Float || pf == MTLPixelFormatDepth16Unorm || pf == MTLPixelFormatDepth32Float_Stencil8, stencil = pf == MTLPixelFormatStencil8 || pf == MTLPixelFormatDepth32Float_Stencil8;
    if (!depth && !stencil && !(c->mask & mtl_pf_chmask(pf))) return;
    if (c->r.xoffset || c->r.yoffset || (NSUInteger)c->r.width != w || (NSUInteger)c->r.height != h || (c->mask & mtl_pf_chmask(pf)) != mtl_pf_chmask(pf)
        || !(t.usage & MTLTextureUsageRenderTarget)) {
        if (plane2d && t.sampleCount == 1 && !depth && !stencil && !mtl_fmt_block(pf) && (t.usage & MTLTextureUsageRenderTarget)) {
            clear_tex_tri(c, t, lv, l0); return;
        }
        RED_ONCE(44, "texture clear case not implemented: region %d,%d %dx%d (level size %lux%lu) mask %#x render-target capable %d (format %#x flags %#x)", c->r.xoffset, c->r.yoffset, c->r.width, c->r.height,
                 (unsigned long)w, (unsigned long)h, c->mask, !!(t.usage & MTLTextureUsageRenderTarget), c->tex->d.format, c->tex->d.flags);
        return;
    }
    rp_end(); if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    for (int z = 0; z < nz; z++) {
        MTL4RenderPassDescriptor *rp = pass_desc();
        MTLRenderPassAttachmentDescriptor *a = depth ? rp.depthAttachment : stencil ? rp.stencilAttachment : rp.colorAttachments[0];
        a.texture = t; a.level = lv; a.loadAction = MTLLoadActionClear; a.storeAction = MTLStoreActionStore;
        if (is3d) a.depthPlane = c->r.zoffset + z; else a.slice = l0 + c->r.zoffset + z;
        if (depth) { rp.depthAttachment.clearDepth = depth_clear_value(t.pixelFormat, c->c.f[0]);
            if (stencil) { rp.stencilAttachment.texture = t; rp.stencilAttachment.level = lv; rp.stencilAttachment.slice = a.slice; rp.stencilAttachment.loadAction = MTLLoadActionClear;
                           rp.stencilAttachment.storeAction = MTLStoreActionStore; rp.stencilAttachment.clearStencil = c->c.u[1]; } }
        else if (stencil) rp.stencilAttachment.clearStencil = c->c.u[0];
        else rp.colorAttachments[0].clearColor = color;
        ser_gate(); enc_r_end(enc_r_begin(rp));
    }
}

// Context description of one submit (nvn_be_sub_commit takes one per submit and prints it into the failure line when the command buffer errors): for the GPU memory fault on the first frame entering Travincal, the failure line had only the sequence number and error code, and it was impossible to tell what was in that submit
static const char *cctx_snap(void) {
    static char b[320]; static uint64_t p_pass, p_up, p_reup, p_ser; uint64_t up = 0, reup = 0; nvn_be_pkg_stats(&up, &reup);
    pthread_mutex_lock(&g_deferred_mu); unsigned long nd = (unsigned long)g_deferred.count; pthread_mutex_unlock(&g_deferred_mu);
    snprintf(b, sizeof b, "frame %llu; since the last submission: passes +%llu, first texture uploads +%llu, re-uploads +%llu, serial table changes +%llu; deferred-release queue %lu",
             (unsigned long long)atomic_load(&g_cur_frame), (unsigned long long)(g_stat_pass - p_pass), (unsigned long long)(up - p_up), (unsigned long long)(reup - p_reup),
             (unsigned long long)(g_ser_gen - p_ser), nd);
    p_pass = g_stat_pass; p_up = up; p_reup = reup; p_ser = g_ser_gen; return b;
}
// When the game itself asks for 30 fps (pacing by the game's present interval, interval 2, hle_nvn.c) the display link runs at 30 Hz too: games whose logic counts frames, such as Engage, are not pulled up to 60 fps by the display link on iOS
__attribute__((weak)) int nvn_game_fps(void) { return 60; }   // hle_nvn.c provides the strong definition
static int fps_override(void) { static int env = -2; if (env == -2) { const char *e = getenv("DM_FPS"); env = e ? atoi(e) : -1; if (env != 30 && env != 60) env = -1; else MLOG("DM_FPS=%d: frame rate pinned by the test switch", env); } return env; }
int nvn_be_fps_target(void) { int env = fps_override(); return env > 0 ? env : nvn_game_fps() == 30 ? 30 : 60; }
// Hand a submission to the GPU in segments (DM_NVN_CUT=draw count, 0 = off; default 64): when the game holds back the next frame's submit until this frame's GPU work is done (The Legend of Zelda: Breath of the Wild: the main thread's nvnSyncWait on the fence of the frame just submitted),
// the GPU sits idle for the milliseconds the host spends translating inside the submit (in the shrine each frame is GPU 13 ms + translation 7 ms back to back). Each time this many draws have accumulated, the command buffer encoded so far is committed between two passes: the GPU runs the earlier passes while the CPU translates the later ones.
// Cut only when no encoder is open and no pass is deferred / merged / hoisted; commit this batch's uploads first (later draws use them). The fence signal and completion work stay on the last segment only: the queue executes in commit order and every encoder starts with a queue barrier
// A buffer → texture copy is cut after as well, at the next pass boundary whatever the draw count (g_cut_copy, set by copy_b2t): on the Switch the GPU runs a submission's copies as soon as the
// submit returns, and a game may reuse the copy's source right after. Catherine: Full Body's resource thread writes the next texture into the staging block 64 ms after the main thread
// recorded a copy from it (main+0x305e64, frame start) and before that frame's submit had even returned: the host was building pipelines inside the submit for 300 ms, and committed the
// copy only at its end, so the subtitle band's gradient (BC3, 32x512) came out as the next texture's blocks. Committed at the first pass boundary, the copies run while the host encodes the rest
static int cut_draws(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_CUT"); v = e ? atoi(e) : 64; MLOG("segmented submission: a segment is submitted between passes every %d draws (DM_NVN_CUT, 0 = off)", v); } return v; }
static uint64_t g_cut_draw0, g_cuts, g_copy_cuts, g_cut_busy;   // g_cut_busy: boundaries kept without a commit (GPU still busy)
// The count starts with the submission (nvn_be_sub_begin; upstream reference implementation, MIT). It used to start at the submission's first sub_cut, which only a render target change reaches (OP_SET_RT):
// the draws a submission makes into the target it inherited, before its first target change, were never counted, and the first segment came that many draws late
static void sub_cut_begin(void) { g_cut_draw0 = g_stat_draw; }
// Segment times without the segments (upstream reference implementation, MIT). A report in segment mode takes the GPU start or end of the segment it fell in, and what a game's controller makes of those depends on where the boundaries lie.
// So the boundaries stay every cut_draws() draws, each with a GPU timestamp, whether or not the host commits there (sub_cut): the game reads what it read, and a GPU still busy gets no extra command buffer.
// Metal 3 and the encode thread record their encoders without such a write: with them each boundary stays a commit
enum { TS_SLOTS = 4096 };   // the largest timestamp heap Metal makes
static uint32_t g_ts_next; static int g_ts_state, g_ts_s0;   // state: 0 not tried, 1 on, -1 off; s0: the slot of this submission's first boundary
static int ts_on(void) {
    if (!g_ts_state) { g_ts_state = -1;
        if (seg_ts() && !g_m3 && !rec_on()) { NSError *er = nil;
            g_ts_heap = ts_heap_new(TS_SLOTS, &er);
            if (g_ts_heap) g_ts_state = 1; else MLOG("【红】 counter timestamps: no counter heap (%s): every segment boundary stays a commit", er.description.UTF8String); } }
    return g_ts_state > 0;
}
static int ts_stamp(void) {   // no render encoder open. Written at the start of the next encoder (gp_begin), or into the copy encoder if one is open; boundaries with nothing between them are one time
    if (g_ts_pend >= 0) return g_ts_pend;
    int slot = (int)(g_ts_next++ % TS_SLOTS); [g_ts_heap invalidateCounterRange:NSMakeRange((NSUInteger)slot, 1)];
    if (!g_blit) g_ts_pend = slot;
    else ts_write(g_blit, 'C', MTLRenderStageVertex, g_ts_heap, (NSUInteger)slot);
    return slot;
}
static void ts_sub_begin(void) { if (ts_on()) g_ts_s0 = ts_stamp(); }
static void ts_clk(void) {   // the submission's first report or boundary
    if (!ts_on() || g_sclk) return;
    g_sclk = calloc(1, sizeof *g_sclk); if (!g_sclk) MDIE("segment clock allocation failed"); atomic_store(&g_sclk->refs, 1); g_sclk->b[0] = (uint16_t)g_ts_s0; g_sclk->nb = 1;
}
static void ts_boundary(void) {   // the end of a segment and the start of the next
    if (!ts_on()) return;
    ts_clk(); if (g_sclk->nb <= SEG_CLK_N) g_sclk->b[g_sclk->nb++] = (uint16_t)ts_stamp();
}
static void sub_cut(void) {
    int n = cut_draws();
    if (!g_cb || g_enc) return;
    int scratch = g_arena_seg >= ARENA_CUT;   // the segment's frame scratch passed the bound (see NvArena): cut whatever the draw count, DM_NVN_CUT=0 included
    if ((!g_cut_copy && !scratch && (n <= 0 || g_stat_draw - g_cut_draw0 < (uint64_t)n)) || g_hoist_n || g_defer_nact || g_defer_pend || g_fz.active || g_rt_merged) return;
    // The cut is there so that the GPU does not sit idle while the host encodes. With earlier work still running a commit gains nothing and queues one more command buffer (upstream reference implementation, MIT: with buffers queued
    // behind running work the GPU waited 5-40 ms with the next one already committed). So it stays a boundary for the game's timestamps (ts_boundary), the commit left for when the GPU has run out.
    // A copy still commits, as its data must land, and so does a cut for frame scratch, whose blocks come back only when their segment completes. DM_NVN_CUT_BUSY=0: every cut commits
    static int busy = -1; if (busy < 0) { const char *e = getenv("DM_NVN_CUT_BUSY"); busy = !e || atoi(e) != 0; if (!busy) MLOG("DM_NVN_CUT_BUSY=0: every segment boundary commits, the GPU busy or not"); }
    if (busy && !g_cut_copy && !scratch && (!seg_ts() || ts_on()) && atomic_load_explicit(&g_seg_inflight, memory_order_relaxed) > 0) {
        if (ts_on()) { ts_boundary(); g_seg++; }
        g_cut_busy++; g_cut_draw0 = g_stat_draw; return; }
    if (ts_on()) ts_boundary();
    if (g_cut_copy) g_copy_cuts++;
    if (scratch && !g_arena_cuts++) MLOG("segmented submission: first cut for frame scratch (%llu MB in the segment) at frame %llu", (unsigned long long)(g_arena_seg >> 20), (unsigned long long)atomic_load(&g_cur_frame));
    g_cut_copy = 0;
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    up_flush();
    uint64_t f = atomic_load(&g_cur_frame); double gpu_sub = gpu_tag_begin(f);
    uint32_t k = g_seg++; seg_clk *sc = NULL;   // reports encoded so far keep this segment's GPU times (seg_ts)
    NSArray<NSString *> *qsus = quar_take();
    uint64_t sf = arena_cut();
    if (seg_ts()) { if (!g_sclk) { g_sclk = calloc(1, sizeof *g_sclk); atomic_store(&g_sclk->refs, 1); } sc = g_sclk; atomic_fetch_add(&sc->refs, 1); }
    id o = fb_new();
    atomic_fetch_add(&g_seg_inflight, 1);
    fb_add(o, ^(id<MTL4CommitFeedback> cb) {
        atomic_fetch_sub(&g_seg_inflight, 1);
        gpu_tag_done(f, 0, gpu_sub, cb.GPUStartTime, cb.GPUEndTime);
        arena_seg_done(sf);
        if (sc) { if (k < SEG_CLK_N) { atomic_store(&sc->t[k][0], gpu_s_guest_ns(cb.GPUStartTime)); atomic_store(&sc->t[k][1], gpu_s_guest_ns(cb.GPUEndTime)); } seg_clk_put(sc); }
        if (cb.error) { atomic_store(&g_last_commit_error, 1); atomic_fetch_add(&g_commit_error_n, 1); if (mtl_gpu_halted()) mtl_gpu_cb_error(cb.error, "segment", f); else { static int k; if (![cb.error.description containsString:@"InnocentVictim"]) quar_fault(qsus, cb.error); if (k++ < 8) MLOG("【红】 segment command buffer execution error: %s", cb.error.description.UTF8String); mtl_gpu_cb_error(cb.error, "segment", f); s2a_direct_gpu_error(cb.error.localizedDescription.UTF8String); } }
    });
    res_commit();
    main_barrier_reset();
    if (g_m3) { rec_commit_m3(g_cb, o, nil, 0, 1); g_cb = rec_cb_new(); }
    else {
        [g_cb endCommandBuffer];
        rec_commit(g_cb, o);
        g_cb = rec_cb_new();
        [g_cb beginCommandBufferWithAllocator:g_alloc4[g_alloc_cur]];   // one allocator encodes several command buffers in sequence; it is reset only once its fence (the last segment) has passed, when a later submission starts
    }
    g_cut_draw0 = g_stat_draw;
    if (!g_cuts++) MLOG("segmented submission: first segment submitted at frame %llu pass %llu", (unsigned long long)f, (unsigned long long)g_stat_pass);
}
// 遍内切段（11-07 Switch2 线时之笛 GPU 空等）：sub_cut 只在两遍之间被调，一遍画得再多也要整遍编完才交出去。时之笛主遍一遍 800–1200 笔，
//   宿主编它的几毫秒里 GPU 已把前面的活跑完、干等（Duo 诊断局 v80n_d_n1b，DM_NVN_GPUPROF 8500–10500：帧内空等 5.2 ms/帧，其中 1.6 ms 就在装着主遍的那段命令缓冲提交之前，单帧最多 3.6 ms）。
//   这里在绘制之间补一个切段点：攒够 cut_draws() 笔、且前面交出去的命令缓冲都已回报（g_seg_inflight == 0，GPU 确实没活了）时，结束渲染编码器、提交，
//   下一笔绘制照常重开本遍（附件 Load，和遍中因拷贝 / 统一缓冲落地拆遍是同一条路）。GPU 还忙就不拆：拆遍要多一次附件写回 + 读入，忙时拆了得不到什么。
//   不拆：合并 / 提前 / 推迟中的遍（g_fz、g_hoist_n、g_defer_*：它们的跳过表跨编码器边界就错），与 sub_cut 自己的守卫一致。DM_NVN_CUT=0 时同样关闭
static uint64_t g_pass_cuts;   // 遍内切段次数（hle_nvn.c 的 split submits 行）
static void sub_cut_pass(void) {   // 一笔绘制之前（nvn_be_exec 的 OP_DRAW / OP_DRAW_IDX）
    int n = cut_draws();
    if (!g_enc || !g_cb || n <= 0 || g_stat_draw - g_cut_draw0 < (uint64_t)n) return;
    if (atomic_load_explicit(&g_seg_inflight, memory_order_relaxed) > 0) return;
    if (g_hoist_n || g_defer_nact || g_defer_pend || g_fz.active) return;
    uint64_t c0 = g_cuts; rp_end(); sub_cut();
    if (g_cuts != c0 && !g_pass_cuts++) MLOG("segmented submission: first segment submitted inside a draw pass at frame %llu pass %llu (the GPU had run out of work)", (unsigned long long)atomic_load(&g_cur_frame), (unsigned long long)g_stat_pass);
}
uint64_t nvn_be_pass_cut_count(void) { return g_pass_cuts; }
uint64_t nvn_be_cut_count(void) { return g_cuts; }
uint64_t nvn_be_copy_cut_count(void) { return g_copy_cuts; }

// ---------- Clears a load action cannot express ----------
// A colour clear issued inside an open render pass, with a partial channel mask or with a scissor smaller than the target, and a depth / stencil clear with a scissor inside an
// open pass (Tears of the Kingdom issues all of them) are drawn as one triangle over the whole pass in the render encoder. It writes the clear value into the masked channels of
// that attachment, or the depth / the stencil bits of the clear's write mask, inside the scissor, with the depth test ALWAYS and no visibility counting. The value is read from
// the frame arena through the triangle's own argument tables (the draws' g_vt / g_ft are put back after it), so the pipelines depend only on the pass formats, the slot and the
// mask. Clears the load action expresses keep it. Adapted from MacNativeGames' clear_quad / clear_ds_quad (github.com/ly05010419/MacNativeGames, MIT).
static id<MTLLibrary> clr_lib(int slot, int kind) {   // vertex clr_vs (the triangle, depth from buffer 0) and fragment clr_fs (colour slot `slot` of type `kind` from buffer 0)
    static id<MTLLibrary> libs[8][3]; static uint8_t failed[8][3];
    if (libs[slot][kind] || failed[slot][kind]) return libs[slot][kind];
    static const char *ty[3] = {"float", "uint", "int"}; char src[720];
    snprintf(src, sizeof src, "#include <metal_stdlib>\nusing namespace metal;\nstruct V { float4 p [[position]]; };\n"
             "vertex V clr_vs(uint i [[vertex_id]], device const float *z [[buffer(0)]]) { V o; o.p = float4(float2(float((i << 1) & 2), float(i & 2)) * 2.0 - 1.0, z[0], 1.0); return o; }\n"
             "struct O { %s4 c [[color(%d)]]; };\nfragment O clr_fs(device const %s4 *v [[buffer(0)]]) { O o; o.c = v[0]; return o; }\n", ty[kind], slot, ty[kind]);
    NSError *e = nil; libs[slot][kind] = [g_dev newLibraryWithSource:@(src) options:nil error:&e];
    if (!libs[slot][kind]) { failed[slot][kind] = 1; MLOG("【红】 clear-triangle shader compile failed (slot %d kind %d): %s", slot, kind, e.localizedDescription.UTF8String); }
    return libs[slot][kind];
}
typedef struct { int32_t slot, kind, mask; uint32_t cfmt[8], dfmt, sfmt, samples; } clr_key;   // slot -1: a depth / stencil clear (no fragment function)
static id<MTLRenderPipelineState> clr_pso(const clr_key *k) {
    static NSMutableDictionary<NSData *, id<MTLRenderPipelineState>> *cache; if (!cache) cache = [NSMutableDictionary dictionary];
    NSData *kd = [NSData dataWithBytes:k length:sizeof *k]; id<MTLRenderPipelineState> ps = cache[kd]; if (ps) return ps;
    id<MTLLibrary> lib = clr_lib(k->slot < 0 ? 0 : k->slot, k->slot < 0 ? 0 : k->kind); if (!lib) return nil;
    MTLRenderPipelineDescriptor *d = [MTLRenderPipelineDescriptor new];
    d.vertexFunction = [lib newFunctionWithName:@"clr_vs"]; if (k->slot >= 0) d.fragmentFunction = [lib newFunctionWithName:@"clr_fs"];
    for (int i = 0; i < 8; i++) if (k->cfmt[i]) { d.colorAttachments[i].pixelFormat = (MTLPixelFormat)k->cfmt[i]; d.colorAttachments[i].writeMask = MTLColorWriteMaskNone; }   // the other attachments stay as they are
    if (k->slot >= 0) d.colorAttachments[k->slot].writeMask = (MTLColorWriteMask)((k->mask & 1 ? MTLColorWriteMaskRed : 0) | (k->mask & 2 ? MTLColorWriteMaskGreen : 0) | (k->mask & 4 ? MTLColorWriteMaskBlue : 0) | (k->mask & 8 ? MTLColorWriteMaskAlpha : 0));
    d.depthAttachmentPixelFormat = (MTLPixelFormat)k->dfmt; d.stencilAttachmentPixelFormat = (MTLPixelFormat)k->sfmt; d.rasterSampleCount = k->samples ? k->samples : 1;
    NSError *e = nil; ps = [g_dev newRenderPipelineStateWithDescriptor:d error:&e];
    if (!ps) { static int n; if (n++ < 4) MLOG("【红】 cannot create the clear-triangle pipeline (slot %d color format %u depth %u stencil %u samples %u): %s; this clear is skipped", k->slot, k->slot >= 0 ? k->cfmt[k->slot] : 0, k->dfmt, k->sfmt, k->samples, e.localizedDescription.UTF8String); return nil; }
    cache[kd] = ps; return ps;
}
static id<MTLDepthStencilState> clr_dss(int dw, unsigned sm) {   // depth ALWAYS, written when dw; stencil ALWAYS → REPLACE through write mask sm (no stencil test when 0)
    static id<MTLDepthStencilState> c[2][256];
    if (c[dw][sm]) return c[dw][sm];
    MTLDepthStencilDescriptor *d = [MTLDepthStencilDescriptor new]; d.depthCompareFunction = MTLCompareFunctionAlways; d.depthWriteEnabled = dw != 0;
    if (sm) { MTLStencilDescriptor *st = [MTLStencilDescriptor new]; st.stencilCompareFunction = MTLCompareFunctionAlways; st.stencilFailureOperation = st.depthFailureOperation = MTLStencilOperationKeep;
        st.depthStencilPassOperation = MTLStencilOperationReplace; st.readMask = 0xff; st.writeMask = sm; d.frontFaceStencil = d.backFaceStencil = st; }
    return c[dw][sm] = [g_dev newDepthStencilStateWithDescriptor:d];
}
// S2Arm widen: a scissored clear's x range on attachment t in its storage (Ryujinx scales a clear's scissor by the target's scale, DrawManager.Clear; the generic mode maps it
// as ScaleK, WidenRenderer.Clear): the game's x through s2a_widen_map_x, which leaves a target that is not widened as it is.
//   On level lv the x is in that level's texels: mapped in level-0 texels, the start rounded down and the end up, so a whole game level is the whole widened level
//   (11-02 Mario Party: a bloom mip chain cleared and drawn level by level, 288 of 352 columns on level 1; the right strip of every level kept old memory, sampled as coloured blocks)
static void wd_clear_x(const tex_t *t, unsigned lv, long *x0, long *x1) {
    if (g_wd <= 0 || !t) return;
    long u = 1L << lv, a = s2a_widen_map_x((uint32_t)t->serial, (int)(*x0 * u)), b = s2a_widen_map_x((uint32_t)t->serial, (int)(*x1 * u));
    *x0 = a / u; *x1 = (b + u - 1) / u;
}
// The same for y on a target the narrower screen made taller (core height ÷ game height, as copy_t2t maps a copy's rows): the start rounds down, the end up, so every row the game's
//   rectangle touches is cleared. Before this only x was mapped and a scissored clear of a taller target left its added bands above and below with old content (audit P1-79)
static void wd_clear_y(const tex_t *t, long *y0, long *y1) {
    if (g_wd <= 0 || !t || !t->d.height) return;
    pthread_mutex_lock(&g_wd_mu); long gh = (long)t->d.height, th = (long)wd_tex_h(t); pthread_mutex_unlock(&g_wd_mu);
    if (th <= gh) return;
    *y0 = *y0 * th / gh; *y1 = (*y1 * th + gh - 1) / gh;
}
static unsigned rt_level(const tex_t *t) {   // the mip level the open pass renders attachment t at
    if (t && t == R.rt.depth) return R.rt.has_dview && R.rt.dview.set_levels ? R.rt.dview.base_level : 0;
    for (int i = 0; i < R.rt.n && i < 8; i++) if (t && R.rt.color[i] == t) return R.rt.has_cview[i] && R.rt.cview[i].set_levels ? R.rt.cview[i].base_level : 0;
    return 0;
}
static int clr_scissor(MTLScissorRect *sc, const tex_t *t) {   // the clear's scissor in the open pass on attachment t, clamped as for draws; 0 = empty
    NSUInteger tw = g_pass.tw, th = g_pass.th; *sc = (MTLScissorRect){0, 0, tw, th};
    if (!R.has_sc) return tw && th;
    long x0 = R.sc.x < 0 ? 0 : R.sc.x, y0 = R.sc.y < 0 ? 0 : R.sc.y, x1 = (long)R.sc.x + R.sc.w, y1 = (long)R.sc.y + R.sc.h;
    wd_clear_x(t, rt_level(t), &x0, &x1); wd_clear_y(t, &y0, &y1);
    if (g_pass.rs != 1.0) { long w_ = x1 - x0, h_ = y1 - y0; rs_rect(g_pass.rs, &x0, &y0, &w_, &h_); x1 = x0 + w_; y1 = y0 + h_; }   // S2Arm internal resolution: canvas → storage
    if (x1 > (long)tw) x1 = (long)tw; if (y1 > (long)th) y1 = (long)th;
    if (x1 <= x0 || y1 <= y0) return 0;
    *sc = (MTLScissorRect){(NSUInteger)x0, (NSUInteger)y0, (NSUInteger)(x1 - x0), (NSUInteger)(y1 - y0)}; return 1;
}
static void clr_tri(id<MTL4RenderCommandEncoder> en, id<MTLRenderPipelineState> ps, id<MTLDepthStencilState> ds, MTLScissorRect sc, NSUInteger width, NSUInteger height, const uint32_t val[4], float z, uint32_t sref) {
    static id vt, ft;
    if (!ft) { NSError *e = nil;
        vt = rec_table(tab_new(1, 0, 0, &e)); ft = vt ? rec_table(tab_new(1, 0, 0, &e)) : nil;
        if (!ft) { vt = nil; static int n; if (!n++) MLOG("【红】 cannot create the clear-triangle argument table: %s; this clear is skipped", e.localizedDescription.UTF8String); return; } }
    id<MTLBuffer> b; size_t o = arena_alloc(32, &b); uint8_t *p = (uint8_t *)b.contents + o; memcpy(p, val, 16); memcpy(p + 16, &z, 4);   // colour at 0, depth at 16
    tab_buf(ft, b, o, 0); tab_buf(vt, b, o + 16, 0);
    enc_r_table(en, vt, MTLRenderStageVertex); enc_r_table(en, ft, MTLRenderStageFragment);
    enc_r_pso(en, ps); g_enc_pso = nil; enc_r_dss(en, ds); g_enc_dss = nil;   // the next draw sets its own again
    if (g_enc_vis) { enc_r_visibility(en, MTLVisibilityResultModeDisabled, 0); g_enc_vis = 0; }   // not counted by an occlusion query; the next counted draw turns counting back on
    enc_r_viewport(en, (MTLViewport){0, 0, (double)width, (double)height, 0, 1}); enc_r_scissor(en, sc);
    enc_r_cull(en, MTLCullModeNone); enc_r_fill(en, MTLTriangleFillModeFill); enc_r_depth_bias(en, 0, 0, 0); enc_r_depth_clip(en, YES); enc_r_stencil_ref(en, sref, sref); g_ed.ok = 0;
    // 11-07 鬼灭快速移动地面黑洞：这次编码的写由调用方记——遍内的跟着 clr_note（只记清到的那张），clear_tex_tri 是自己的遍。走 udc_encode 的保守分支会把本遍
    //   每张附件都记「写过」，前瞻证明不写、没读入的（lskip）随之遍末写回未定义的片上内容（满屏起页清条带在 draw() 精确记账之前，正好落在这条分支）
    g_udc_precise = 1;
    enc_r_draw(en, MTLPrimitiveTypeTriangle, 0, 3);
    enc_r_table(en, g_vt, MTLRenderStageVertex); enc_r_table(en, g_ft, MTLRenderStageFragment);
}
static void clear_tex_tri(const p_clear_tex *c, id<MTLTexture> t, unsigned level, unsigned layer) {
    NSUInteger w = MAX(t.width >> level, 1u), h = MAX(t.height >> level, 1u);
    int nz = c->r.depth ? c->r.depth : 1;
    clr_key k = {0}; k.kind = pf_int_kind(t.pixelFormat); k.mask = c->mask & 0xf; k.cfmt[0] = (uint32_t)t.pixelFormat; k.samples = 1;
    id<MTLRenderPipelineState> ps = clr_pso(&k); id<MTLDepthStencilState> ds = clr_dss(0, 0); if (!ps || !ds) return;
    uint32_t v[4];
    for (int i = 0; i < 4; i++) {
        double n = c->value_type == CLEAR_TEX_UINT ? (double)c->c.u[i] : c->value_type == CLEAR_TEX_INT ? (double)c->c.i[i] : (double)c->c.f[i];   // #323 的三种清除值（float / int / uint），double 精确表示全部 32 位整数
        if (k.kind == 1) v[i] = !(n > 0) ? 0 : n >= UINT32_MAX ? UINT32_MAX : (uint32_t)n;
        else if (k.kind == 2) { int32_t si = !(n == n) ? 0 : n >= INT32_MAX ? INT32_MAX : n <= INT32_MIN ? INT32_MIN : (int32_t)n; memcpy(&v[i], &si, 4); }
        else { float f = (float)n; memcpy(&v[i], &f, 4); }
    }
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    MTLScissorRect sc = {(NSUInteger)c->r.xoffset, (NSUInteger)c->r.yoffset, (NSUInteger)c->r.width, (NSUInteger)c->r.height};
    for (int z = 0; z < nz; z++) {
        MTL4RenderPassDescriptor *rp = pass_desc(); MTLRenderPassColorAttachmentDescriptor *a = rp.colorAttachments[0];
        a.texture = t; a.level = level; a.slice = layer + c->r.zoffset + z; a.loadAction = MTLLoadActionLoad; a.storeAction = MTLStoreActionStore;
        ser_gate(); id<MTL4RenderCommandEncoder> en = enc_r_begin(rp);
        clr_tri(en, ps, ds, sc, w, h, v, 0, 0); enc_r_end(en);
    }
    args_dirty_all(); g_pso_dirty = g_dss_dirty = 1;
}
static void clr_note(int slot, int depth, int stencil) {   // as udc_note_draw for a draw: the attachment was written (zero-source skip, unwritten-attachment store)
    if (slot >= 0 && R.rt.color[slot]) { zskip_del(R.rt.color[slot]->serial); g_zskip_cand_ok[slot] = 0; }
    for (int i = 0; i < g_nsd; i++) { sd_att *t = &g_sd[i];
        if ((t->depth == 0 && slot >= 0 && t->idx == slot) || (t->depth == 1 && depth) || (t->depth == 2 && stencil)) { if (t->lskip && !t->wrote) noload_witness(i, 2, 2); t->wrote = 1; t->wwhy = 2; } }
}
static uint64_t g_clr_tri[2];   // clears drawn as a triangle: colour, depth / stencil
static void clear_color_tri(const p_clear_color *c) {
    int slot = c->index, mask = c->mask & 0xf;
    if (!mask || slot < 0 || slot >= 8 || slot >= R.rt.n || !R.rt.color[slot]) return;
    id<MTL4RenderCommandEncoder> en = rp_begin();   // a clear outside a pass opens it as a draw would (pending clears land first)
    if (en && !g_pass.cfmt[slot] && g_enc_mode) { rp_end(); en = rp_begin(); }   // opened without this attachment (clear-only / TBDR modes): reopen with all of them
    if (!en) return;
    int at = slot;
    if (!g_pass.cfmt[at] && rt_dup_slot(&R.rt, slot))   // a slot attached twice is attached only once (rt_dup_slot): clear the first one
        for (int j = 0; j < slot; j++) { const tex_t *a = R.rt.color[j], *b = R.rt.color[slot]; if (!a || a->serial != b->serial || !g_pass.cfmt[j]) continue;
            const view_t *va = &R.rt.cview[j], *vb = &R.rt.cview[slot]; int ha = R.rt.has_cview[j], hb = R.rt.has_cview[slot];
            if ((ha && va->set_levels ? va->base_level : 0) == (hb && vb->set_levels ? vb->base_level : 0) && (ha && va->set_layers ? va->min_layer : 0) == (hb && vb->set_layers ? vb->min_layer : 0)) { at = j; break; } }
    if (!g_pass.cfmt[at]) { PD("c %llu color-clear triangle skipped: slot %d is not in this pass", g_stat_pass, slot); return; }
    MTLScissorRect sc; if (!clr_scissor(&sc, R.rt.color[slot])) { PD("c %llu color-clear triangle skipped: empty scissor slot %d", g_stat_pass, slot); return; }
    int kind = pf_int_kind((MTLPixelFormat)g_pass.cfmt[at]);
    clr_key k; memset(&k, 0, sizeof k); k.slot = at; k.kind = kind; k.mask = mask; memcpy(k.cfmt, g_pass.cfmt, sizeof k.cfmt); k.dfmt = g_pass.dfmt; k.sfmt = g_pass.sfmt; k.samples = g_pass.samples;
    id<MTLRenderPipelineState> ps = clr_pso(&k); id<MTLDepthStencilState> ds = clr_dss(0, 0); if (!ps || !ds) return;
    float rgba[4] = {c->rgba[0], c->rgba[1], c->rgba[2], c->rgba[3]};
    if (kind == 0 && g_wd > 0) {   // S2Arm widen: a scissored clear of the pure-2D world target also gets the sentinel alpha (fallback side-coverage sampling, widen_glue.inc wd_p2_clear_tri)
        const tex_t *t = R.rt.color[slot]; long gx0 = 0, gx1 = (long)t->d.width;
        if (R.has_sc) { gx0 = R.sc.x < 0 ? 0 : R.sc.x; gx1 = (long)R.sc.x + R.sc.w; if (gx1 > (long)t->d.width) gx1 = (long)t->d.width; }
        long cx0 = gx0, cx1 = gx1; wd_clear_x(t, rt_level(t), &cx0, &cx1);
        wd_p2_clear_tri(t, rgba, mask, sc, gx1 - gx0, cx1 - cx0);
    }
    uint32_t v[4];
    for (int i = 0; i < 4; i++) { float f = rgba[i]; int32_t si;   // integer attachments take the value converted, as a load-action clear does
        if (kind == 1) v[i] = f > 0 ? (f < 4294967040.f ? (uint32_t)f : 0xffffffffu) : 0;
        else if (kind == 2) { si = !(f == f) ? 0 : f >= 2147483520.f ? INT32_MAX : f <= -2147483648.f ? INT32_MIN : (int32_t)f; memcpy(&v[i], &si, 4); }
        else memcpy(&v[i], &f, 4); }
    clr_tri(en, ps, ds, sc, g_pass.tw, g_pass.th, v, 0, 0); clr_note(at, 0, 0);
    if (!g_clr_tri[0]++) MLOG("mid-pass / partial-mask / partial-scissor color clear: drawn as a full-pass triangle (first case pass %llu slot %d mask %#x scissor %lu,%lu %lux%lu)", g_stat_pass, at, mask,
                              (unsigned long)sc.x, (unsigned long)sc.y, (unsigned long)sc.width, (unsigned long)sc.height);
    PD("c %llu color clear drawn as a triangle slot%d ser=%llu mask=%#x scissor=%lu,%lu,%lu,%lu color=%g,%g,%g,%g", g_stat_pass, at, (unsigned long long)R.rt.color[at]->serial, mask,
       (unsigned long)sc.x, (unsigned long)sc.y, (unsigned long)sc.width, (unsigned long)sc.height, c->rgba[0], c->rgba[1], c->rgba[2], c->rgba[3]);
}
// S2Arm widen: a 16:9 page starts at this draw (s2a_widen_page_sides): colour target 0's two side strips, full height, cleared to 0 before the draw, as the generic mode's ClearCols
static void wd_page_clear(id<MTL4RenderCommandEncoder> en) {
    int rows = g_wd_row_on; g_wd_side_on = g_wd_row_on = 0;   // 10-28 B06：窄屏加高的目标另清上下两条（行，整宽）
    if (!en || !g_pass.cfmt[0]) { RED_ONCE(110, "widen page side strips not cleared: colour target 0 is not in this pass"); return; }
    clr_key k; memset(&k, 0, sizeof k); k.slot = 0; k.kind = pf_int_kind((MTLPixelFormat)g_pass.cfmt[0]); k.mask = 0xf; memcpy(k.cfmt, g_pass.cfmt, sizeof k.cfmt); k.dfmt = g_pass.dfmt; k.sfmt = g_pass.sfmt; k.samples = g_pass.samples;
    id<MTLRenderPipelineState> ps = clr_pso(&k); id<MTLDepthStencilState> ds = clr_dss(0, 0); if (!ps || !ds) return;
    const uint32_t v[4] = {0};
    for (int i = 0; i < 4; i += 2) {
        long x0 = g_wd_sides[i] < 0 ? 0 : g_wd_sides[i], x1 = g_wd_sides[i + 1];
        if (g_pass.rs != 1.0) { long y_ = 0, w_ = x1 - x0, h_ = 1; rs_rect(g_pass.rs, &x0, &y_, &w_, &h_); x1 = x0 + w_; }   // S2Arm internal resolution: the core's canvas columns → storage
        if (x1 > (long)g_pass.tw) x1 = (long)g_pass.tw;
        if (x1 > x0) clr_tri(en, ps, ds, (MTLScissorRect){(NSUInteger)x0, 0, (NSUInteger)(x1 - x0), g_pass.th}, g_pass.tw, g_pass.th, v, 0, 0);
    }
    for (int i = 0; rows && i < 4; i += 2) {
        long y0 = g_wd_rows[i] < 0 ? 0 : g_wd_rows[i], y1 = g_wd_rows[i + 1];
        if (g_pass.rs != 1.0) { long x_ = 0, w_ = 1, h_ = y1 - y0; rs_rect(g_pass.rs, &x_, &y0, &w_, &h_); y1 = y0 + h_; }   // S2Arm internal resolution: canvas rows → storage
        if (y1 > (long)g_pass.th) y1 = (long)g_pass.th;
        if (y1 > y0) clr_tri(en, ps, ds, (MTLScissorRect){0, (NSUInteger)y0, g_pass.tw, (NSUInteger)(y1 - y0)}, g_pass.tw, g_pass.th, v, 0, 0);
    }
    clr_note(0, 0, 0);
}
// S2Arm widen: write the fallback sentinel (black, alpha WD_P2_DA) into the two side bands of colour target 0 (widen_glue.inc wd_p2_want_self), as wd_page_clear does its strips
static void wd_p2_self_clear(id en, const uint32_t r5[5]) {
    if (!en || !g_pass.cfmt[0] || pf_int_kind((MTLPixelFormat)g_pass.cfmt[0]) != 0) return;
    clr_key k; memset(&k, 0, sizeof k); k.slot = 0; k.kind = 0; k.mask = 0xf; memcpy(k.cfmt, g_pass.cfmt, sizeof k.cfmt); k.dfmt = g_pass.dfmt; k.sfmt = g_pass.sfmt; k.samples = g_pass.samples;
    id<MTLRenderPipelineState> ps = clr_pso(&k); id<MTLDepthStencilState> ds = clr_dss(0, 0); if (!ps || !ds) return;
    float f[4] = {0, 0, 0, (float)WD_P2_DA}; uint32_t v[4]; memcpy(v, f, sizeof v);
    uint32_t xs[2] = {r5[0], r5[0] + r5[1] - r5[4]};
    for (int i = 0; i < 2; i++) { NSUInteger x = xs[i], w = r5[4], y = r5[2], h = r5[3];
        if (x >= g_pass.tw || y >= g_pass.th) continue; if (x + w > g_pass.tw) w = g_pass.tw - x; if (y + h > g_pass.th) h = g_pass.th - y;
        clr_tri(en, ps, ds, (MTLScissorRect){x, y, w, h}, g_pass.tw, g_pass.th, v, 0, 0); }
    clr_note(0, 0, 0);
}
static void clear_ds_tri(const p_clear_ds *c) {
    unsigned want_s = (unsigned)c->stencil_mask & 0xff;
    if (!c->depth_mask && !want_s) return;
    id<MTL4RenderCommandEncoder> en = rp_begin();
    if (en && g_enc_mode && ((c->depth_mask && !g_pass.hd) || (want_s && !g_pass.hs))) { rp_end(); en = rp_begin(); }   // opened without the depth or stencil plane (TBDR lookahead): reopen with all attachments
    if (!en) return;
    int dw = c->depth_mask && g_pass.hd; unsigned sm = g_pass.hs ? want_s : 0;
    if (!dw && !sm) return;
    MTLScissorRect sc; if (!clr_scissor(&sc, R.rt.depth)) { PD("c %llu depth-stencil clear triangle skipped: empty scissor", g_stat_pass); return; }
    clr_key k; memset(&k, 0, sizeof k); k.slot = -1; memcpy(k.cfmt, g_pass.cfmt, sizeof k.cfmt); k.dfmt = g_pass.dfmt; k.sfmt = g_pass.sfmt; k.samples = g_pass.samples;
    id<MTLRenderPipelineState> ps = clr_pso(&k); id<MTLDepthStencilState> ds = clr_dss(dw, sm); if (!ps || !ds) return;
    float z = c->depth > 0 ? (c->depth < 1 ? c->depth : 1) : 0;   // as clearDepth: within [0, 1] (NaN → 0)
    const uint32_t v[4] = {0};
    clr_tri(en, ps, ds, sc, g_pass.tw, g_pass.th, v, z, (uint32_t)c->stencil & 0xff); clr_note(-1, dw, sm != 0);
    if (!g_clr_tri[1]++) MLOG("mid-pass scissored depth-stencil clear: drawn as a full-pass triangle (first case pass %llu depth %d stencil mask %#x scissor %lu,%lu %lux%lu)", g_stat_pass, dw, sm,
                              (unsigned long)sc.x, (unsigned long)sc.y, (unsigned long)sc.width, (unsigned long)sc.height);
    PD("c %llu depth-stencil clear drawn as a triangle ser=%llu depth=%g(%d) stencil=%d mask=%#x scissor=%lu,%lu,%lu,%lu", g_stat_pass, R.rt.depth ? (unsigned long long)R.rt.depth->serial : 0ull, z, dw, c->stencil, sm,
       (unsigned long)sc.x, (unsigned long)sc.y, (unsigned long)sc.width, (unsigned long)sc.height);
}

static void xq_unwind_push(const uint8_t *p);   // nvn_xqueue.inc
void nvn_be_exec(const uint8_t *p) {
    static int inited; if (!inited) { inited = 1; state_reset(); }
    static int dump_all = -1; if (dump_all < 0) dump_all = getenv("DM_NVN_PASSDUMP_ALL") != NULL;
    int trace = dump_all && passdump();   // Normal mode does not check the frame range per operation; the full command position is only used for the designated diagnostic frames
    const uint8_t *list = p, *prev = NULL; if (!g_ret_n) g_exec_top = p;
    for (;;) {
        op_hdr h; memcpy(&h, p, sizeof h);
        if (rec_bad(h)) { rec_bad_red("replay", p, h, list, prev); g_exec_cur = NULL; return; }   // ends this list as its END would; the caller goes on after its CALL
        prev = p;
        g_exec_cur = p;   // Scan start point of the store lookahead: the operation that ends the render pass (inclusive)
        if (p == g_defer_pend) { for (int gi = 0; gi < 4; gi++) if (g_defer_slots[gi].active && g_defer_slots[gi].p_end_op == p) g_defer_slots[gi].in_p = 0; g_defer_pend = NULL; }
        sdx_seq(p);
        if (trace) PD("o cmd=%p pass=%llu op=%u size=%u", p, g_stat_pass, (unsigned)h.op, (unsigned)h.size);
        // Diagnostic DM_NVN_ALLOCPROF=1: growth of the GPU allocated size is charged to the previous operation's type (rough: allocations on other threads are counted too); the memory report line appends the top 4
        if (g_allocprof < 0) g_allocprof = getenv("DM_NVN_ALLOCPROF") != NULL;
        if (g_allocprof) { static uint64_t last; static int prev = -1; uint64_t now = g_dev.currentAllocatedSize; if (prev >= 0 && prev < 64 && now > last) g_ap_bytes[prev] += now - last; last = now; prev = h.op; }
        if (g_hoist_n && hoist_take(p)) { if (g_fz.active && p == g_fz.rt2_op) { g_fz.phase = 2; g_rt_merged = 0; PD("F %llu merged pass enters the later pass's draws", g_stat_pass); } p += h.size; continue; }   // A pure-clear render pass already executed early / the start of a later pass already merged in   // Entering the later pass: the same-target continuation of the earlier pass ends here; the later pass reading the earlier pass's attachment is proven to be same-pixel by fz_p2_draw, and is no longer split by the continuation rule
        const void *a = p + 8;
        if (g_nlc && !lc_keeps(h.op) && !(h.op == OP_END && g_ret_n)) lc_land();   // see lc_keeps (a sub-list's end returns to its caller)
        if (g_gr.active && !geo_run_keeps(h.op)) geo_run_flush();   // only state settings and draws stay inside a geometry run (nvn_geometry.inc ①)
        switch (h.op) {
            case OP_END: g_exec_cur = NULL;
                if (g_hoist_n && !g_ret_n && !g_nrest) {
                    if (g_fz.active) fz_unskip();
                    if (g_hoist_n) { MLOG("【红】 pure-clear pass hoisting: %d hoisted operations were not reached by the end of the submission; cleared (should not happen)", g_hoist_n); g_hoist_n = 0; }
                }
                return;   // An end-of-pass triggered outside a list (present / CPU readback etc.) must not scan expired command memory: a null start point means store everything
            case OP_BEGIN: break;
            case OP_JUMP: { const uint8_t *t; memcpy(&t, a, 8); p = t; continue; }
            case OP_CALL: { uint64_t t; memcpy(&t, a, 8);
                if (g_ret_n < 16) g_ret[g_ret_n] = p + h.size; g_ret_n++;   // Return stack for lookahead: after a sub-list ends, continue looking at the caller
                nvn_be_exec((const uint8_t *)t); g_ret_n--;
                if (g_xq_unwind) { xq_unwind_push(p + h.size); g_exec_cur = NULL; return; }   // parked inside the sub-list: the caller goes on after its CALL (nvn_xqueue.inc)
                break; }
            case OP_SIGNAL_EVENT: { volatile uint32_t *val; uint32_t m, v; memcpy(&val, a, 8); memcpy(&m, (const uint8_t *)a + 8, 4); memcpy(&v, (const uint8_t *)a + 12, 4);
                if (m & NVN_EV_WAIT) { PD("Y wait_event cmd=%p dst=%p mode=%u value=%u now=%u", p, val, m & ~NVN_EV_WAIT, v, val ? *val : 0);   // nvnCommandBufferWaitEvent（同一记录，见 ev_wait）
                    if (ev_wait(val, m & ~NVN_EV_WAIT, v, p + h.size)) { PD("Y parked at the wait (cross-queue order)"); xq_unwind_push(p + h.size); g_exec_cur = NULL; return; }
                    break; }
                PD("Y signal_event cmd=%p dst=%p mode=%u value=%u", p, val, m, v); mtl_sub_event(val, m, v); break; }
            case OP_REPORT_COUNTER: { uint64_t t, ad; memcpy(&t, a, 8); memcpy(&ad, (const uint8_t *)a + 8, 8); g_cnt_report[t & 31]++;
                PD("Q report type=%llu cmd=%p dst=%#llx", (unsigned long long)t, p, (unsigned long long)ad);
                if (DM_GAME_RENDER_COND) rc_note(ad, t == 0 || t == 0x10 ? 1 : 2);
                if (t == NVN_COUNTER_TYPE_SAMPLES_PASSED) { post((post_op){3, NULL, 0, 0, ad, (uint32_t)t, vis_snapshot()}); g_vis_cur = -1; }
                else mtl_sub_counter(ad, (uint32_t)t);
                break; }
            case OP_RENDER_COND: { const p_render_cond *rc = a;   // recorded only with the profile key render_cond (hle_nvn.c)
                if (rc->mode >= 2) { g_rc_skip = rc->mode == 3; PD("E %llu render enable %d", g_stat_pass, rc->mode == 2); }
                else { uint64_t x = 0, y = 0; int known = rc_value(rc->addr, &x) & rc_value(rc->addr + 16, &y);
                    g_rc_skip = known && (rc->mode ? x == y : x != y);
                    PD("E %llu conditional render %s addr=%#llx values %llu / %llu%s%s", g_stat_pass, rc->mode ? "draw if not equal" : "draw if equal", (unsigned long long)rc->addr, (unsigned long long)x, (unsigned long long)y, known ? "" : " (unknown, drawn)", g_rc_skip ? " → not drawn" : ""); }
                break; }
            case OP_WAIT_SYNC: { const sync_t *s; memcpy(&s, a, 8); void *ev; uint64_t v;   // another queue's fence: the queue waits for it before this submission commits (hle_nvn.c WaitSync)
                if (s && sync_ext(s, &ev, &v)) queue_wait_event(ev, v);
                g_pkg_epoch++;   // what the other queue wrote before its fence is visible after the wait: packaged textures are checked again
                PD("Y wait_sync cmd=%p sync=%p", p, (const void *)s); break; }
            case OP_FENCE_SYNC: { sync_t *s; memcpy(&s, a, 8); uint64_t fv = g_fence + 1; sync_publish(s, fv);   // the fence value this submission (segment) commits with
                PD("Y fence_sync cmd=%p sync=%p fence=%llu", p, (void *)s, (unsigned long long)fv); break; }
            case OP_RESET_COUNTER: { uint64_t t; memcpy(&t, a, 8); g_cnt_reset[t & 31]++; PD("Q reset type=%llu cmd=%p", (unsigned long long)t, p);
                if (t == NVN_COUNTER_TYPE_SAMPLES_PASSED) {
#ifdef NVN_RT_RANGE_TEST
                    rr_reset();
#endif
                    g_vis_on = 1; g_vis_counting = 1; vis_clear();
                    // The first reset can come inside a render pass that was begun without a visibility buffer (Octopath Traveler 0: Unreal's occlusion queries, once at boot): split the pass
                    // here, so the continuation is begun with the buffer and its samples are counted (they used not to be: RED "occlusion query counting began in a pass without a visibility buffer")
                    if (g_enc && !g_enc_has_vis) { PD("M %llu occlusion query counting starts: render pass split here", g_stat_pass); rp_end(); } }
                break; }
            case OP_CLEAR_BUF: { const p_clear_buf *cb = a; dsnap_stale(); mtl_sub_fill(cb->addr, cb->size, cb->value); break; }
            case OP_COPY_B2B: { dsnap_stale(); uint64_t s_, d, n; memcpy(&s_, a, 8); memcpy(&d, (const uint8_t *)a + 8, 8); memcpy(&n, (const uint8_t *)a + 16, 8);
                PD("Y copy_b2b cmd=%p src=%#llx dst=%#llx bytes=%llu", p, (unsigned long long)s_, (unsigned long long)d, (unsigned long long)n); mtl_sub_copy(s_, d, n); break; }
            case OP_UPDATE_UB: { uint64_t d, n; memcpy(&d, a, 8); memcpy(&n, (const uint8_t *)a + 8, 8);
                if (p == g_mdx_stop) { g_mdx_epoch++; g_mdx_stop = NULL; }   // it writes a record or count that masked copies were made of (mdx_run)
                PD("Y update_ub cmd=%p src=%#llx dst=%#llx bytes=%llu f=%g,%g,%g,%g", p, (unsigned long long)((const uint8_t *)a + 16), (unsigned long long)d, (unsigned long long)n,
                   n >= 4 ? ((const float *)((const uint8_t *)a + 16))[0] : 0.f, n >= 8 ? ((const float *)((const uint8_t *)a + 16))[1] : 0.f, n >= 12 ? ((const float *)((const uint8_t *)a + 16))[2] : 0.f, n >= 16 ? ((const float *)((const uint8_t *)a + 16))[3] : 0.f); mtl_sub_update((const uint8_t *)a + 16, d, n); break; }
            case OP_SET_RT: {
                p_set_rt rb; const p_set_rt *r = set_rt_rec(a, h.size, &rb); dsnap_stale();
                if (defer_begin_q(p)) break;
                int pend = R.clear_d || R.clear_s; for (int i = 0; i < 8; i++) pend |= R.clear_c[i];
                if (g_enc && !pend && R.has_rt && tbdr_on() && rt_range_same(&R.rt,r)) {
                    g_rt_merged = g_rt_range_active = g_rt_range_pending = 1; R.rt = *r; break; }
                if (g_enc && g_fz.active && g_fz.phase == 1 && fz_reuse_op(p) && !pend && g_enc_mode != 1 && R.has_rt && tbdr_on() && rt_same(&g_fz.rt1, r)) {
                    g_rt_merged = 1; if (!g_rt_merge_n++) MLOG("same-target continuation: first case pass %llu", g_stat_pass); PD("M %llu same-target continuation pass", g_stat_pass); break; }
                // Do not continue a render pass opened only for a clear; one with fewer depth / stencil attachments can be continued (check the planes before drawing)
                if (g_enc && g_enc_mode != 1 && !pend && R.has_rt && tbdr_on() && rt_same(&R.rt, r)) { g_rt_merged = 1; if (!g_rt_merge_n++) MLOG("same-target continuation: first case pass %llu", g_stat_pass); PD("M %llu same-target continuation pass", g_stat_pass); R.rt = *r; break; }
                if (pend && !g_enc && g_cb && lc_on()) lc_push(); else rp_flush();   // clears with no draw wait for the next pass that attaches their targets (lc_push)
                sub_cut(); R.rt = *r; R.has_rt = 1; break;
            }
            case OP_CLEAR_COLOR: {
                const p_clear_color *c = a;
                if (g_rc_skip) { PD("c %llu color clear skipped by conditional rendering slot%d", g_stat_pass, c->index); break; }
                if (g_wd > 0 && c->index >= 0 && c->index < R.rt.n && R.rt.color[c->index]) s2a_widen_target_cleared((uint32_t)R.rt.color[c->index]->serial);   // S2Arm widen: the target's screen-copy origin is void (WidenRenderer.Clear → Frame.OnTargetCleared)
                // A scissored clear to 0 outside a pass with all channels (SMBW clears pyramid levels as sub-rectangles of 480×272 and other targets): copy from the zero buffer into the scissor rectangle in the replay stream
                int p2w = g_wd > 0 && c->index >= 0 && c->index < R.rt.n && R.rt.color[c->index] && wd_p2_is_world(R.rt.color[c->index]->serial);   // S2Arm widen: per-path clear counts on the fallback world target (status line, widen_glue.inc)
                if (!g_enc && c->mask == 0xf && !c->rgba[0] && !c->rgba[1] && !c->rgba[2] && !c->rgba[3] && R.has_sc && c->index >= 0 && c->index < R.rt.n && R.rt.color[c->index]
                    && !scissor_full(R.rt.color[c->index], &R.rt.cview[c->index], R.rt.has_cview[c->index]) && clear_rect_zero(c->index)) { if (p2w) g_p2_clr[2]++; break; }
                if (g_rt_merged) rp_end();   // A clear arrived in a continued render pass: end it here, and the clear is attached to the start of the next render pass as usual
                if (c->index < 0 || c->index >= R.rt.n || !R.rt.color[c->index]) { RED_ONCE(5, "color clear target %d invalid", c->index); break; }
                if (g_enc || c->mask != 0xf || !scissor_full(R.rt.color[c->index], &R.rt.cview[c->index], R.rt.has_cview[c->index])) {
                    // Inside a pass, with a partial mask or a partial scissor: drawn as a triangle (clear_color_tri)
                    static uint64_t n; static int clog = -1; if (clog < 0) clog = getenv("DM_NVN_CLEARLOG") != NULL; if (clog && n++ < 40) MLOG("color clear drawn as a triangle frame %llu pass %llu target %d ser=%llu %ux%u mid=%d mask=%#x scissor=%d,%d,%d,%d color=%g,%g,%g,%g", (unsigned long long)atomic_load(&g_cur_frame), g_stat_pass, c->index,
                        (unsigned long long)R.rt.color[c->index]->serial, R.rt.color[c->index]->d.width, R.rt.color[c->index]->d.height, g_enc != nil, c->mask, R.sc.x, R.sc.y, R.sc.w, R.sc.h, c->rgba[0], c->rgba[1], c->rgba[2], c->rgba[3]);
                    if (p2w) g_p2_clr[1]++; clear_color_tri(c); break; }
                if (p2w) g_p2_clr[0]++;
                R.clear_c[c->index] = 1; R.cc[c->index] = MTLClearColorMake(c->rgba[0], c->rgba[1], c->rgba[2], c->rgba[3]);
                wd_p2_clear(R.rt.color[c->index], &R.cc[c->index]);   // S2Arm widen: the pure-2D world target gets a sentinel alpha (fallback side-coverage sampling, widen_glue.inc)
                PD("c %llu color clear recorded slot%d ser=%llu mask=%#x scissor=%d:%d,%d,%d,%d", g_stat_pass, c->index, (unsigned long long)R.rt.color[c->index]->serial, c->mask, R.has_sc, R.sc.x, R.sc.y, R.sc.w, R.sc.h);
                break;
            }
            case OP_CLEAR_DS: {
                const p_clear_ds *c = a; dsnap_stale();
                if (g_rc_skip) { PD("c %llu depth-stencil clear skipped by conditional rendering", g_stat_pass); break; }
                if (g_rt_merged) rp_end();
                // Load-action clears cannot express a partial rectangle or a
                // stencil write mask, even before the first encoder is opened.
                unsigned sm = (unsigned)c->stencil_mask & 0xff;
                if (R.rt.depth && (!scissor_full(R.rt.depth, &R.rt.dview, R.rt.has_dview) || (sm && sm != 0xff))) {
                    clear_ds_tri(c); break;
                }
                // Depth / stencil clear in the middle of a pass: end the current pass and attach the clear to the start of the next one (color attachments load as usual, as a continued pass does above when a clear arrives). It used to be skipped, and later draws depth-tested against stale depth.
                if (g_enc) {
                    { static int once; if (!once++) MLOG("mid-pass depth-stencil clear: ending this pass; the clear moves to the start of the next pass (first case pass %llu)", g_stat_pass); }
                    rp_end();
                }
                if (c->depth_mask) { R.clear_d = 1; R.cd = c->depth; }
                if (sm) { R.clear_s = 1; R.cs = (uint32_t)c->stencil; }
                PD("c %llu depth-stencil clear recorded ser=%llu depth=%g depth_mask=%d stencil=%d stencil_mask=%#x", g_stat_pass, R.rt.depth ? (unsigned long long)R.rt.depth->serial : 0ull, c->depth, c->depth_mask, c->stencil, c->stencil_mask);
                break;
            }
            case OP_DRAW: { if (g_rc_skip) break; sub_cut_pass(); p_draw t; g_exec_cur = p; g_exec_next = p + h.size; const p_draw *d = draw_rec(a, h.size, &t);
                if (d->tfc) { g_tfd_args = tfd_args(d); if (g_tfd_args) draw(d, NULL); g_tfd_args = 0; } else draw_top(d, NULL); g_exec_next = NULL; break; }   // Lookahead start point
            case OP_DRAW_IDX: { if (g_rc_skip) break; sub_cut_pass(); p_draw_idx t; g_exec_cur = p; g_exec_next = p + h.size; draw_top(NULL, draw_idx_rec(a, h.size, &t)); g_exec_next = NULL; break; }
            case OP_MULTI_DRAW:   // a lookahead from outside the range stops at it (fz_next), including scans for inline writes to its arguments: masked copies made before it are not used past it
                g_mdx_epoch++; g_mdx_stop = NULL;
                if (!g_rc_skip && h.size >= 8 + sizeof(p_multi_draw)) { g_exec_cur = p; g_exec_next = NULL; draw_multi(a); }
                g_mdx_epoch++;
                break;
            case OP_DRAW_TEX: if (!g_rc_skip) draw_tex(a); break;
            // Do not mark dirty if the state did not change (the game often re-sends the same program / state block / vertex format before each draw; the dirty flag only decides whether to re-fetch the pipeline / depth-stencil object, and equal values mean the same object)
            case OP_SCISSOR: case OP_BIND_PROGRAM: case OP_BIND_STATE: case OP_BIND_VATTR: case OP_BIND_VSTREAM: case OP_BIND_VBUF:
            case OP_BIND_UBO: case OP_BIND_SSBO: case OP_BIND_TEX: case OP_BIND_TEX1: case OP_BIND_SAMP: case OP_BIND_IMG: case OP_STENCIL:
            case OP_POLY_OFFSET: case OP_VIEWPORTS: case OP_DEPTH_RANGE: case OP_DEPTH_CLAMP: case OP_VP_SWIZZLE: case OP_BLEND_COLOR:
                state_op(h.op, a, h.size); break;
            case OP_TF_BIND: { const p_tf_bind *b = a; PD("Y tf bind %d addr=%#llx size=%llu", b->index, (unsigned long long)b->addr, (unsigned long long)b->size); state_op(h.op, a, h.size); break; }
            case OP_TF_STATE: { const p_tf_state *b = a; static const char *const w[4] = {"begin", "end", "pause", "resume"}; PD("Y tf %s ctl=%#llx written %llu/%llu/%llu/%llu", w[b->what & 3], (unsigned long long)b->ctl,
                (unsigned long long)S.tf_off[0], (unsigned long long)S.tf_off[1], (unsigned long long)S.tf_off[2], (unsigned long long)S.tf_off[3]); tf_state_end(b); state_op(h.op, a, h.size); break; }   // tf_state_end: End / Pause keep what this Begin captured (nvn_geometry.inc)
            case OP_PRIM_RESTART: state_op(h.op, a, h.size); break;
            case OP_SET_PATCH_SIZE: case OP_ALPHA_REF: state_op(h.op, a, h.size); break;
            case OP_RAST_DISCARD: PD("Y rasterizer discard %d", ((const p_rast_discard *)a)->on); state_op(h.op, a, h.size); break;
            case OP_COPY_B2T: dsnap_stale(); copy_b2t(a); break;
            case OP_COPY_T2B: copy_t2b(a); break;
            case OP_COPY_T2T: dsnap_stale(); copy_t2t(a); break;
            case OP_DLSS: dlss_eval(a, h.size); break;   // NVN2 EvaluateDlss → MetalFX temporal upscale (nvn_dlss.inc)
            case OP_PUSH_CONST: case OP_PUSH_CONST_PTR: state_op(h.op, a, h.size); break;
            case OP_CLEAR_TEX: dsnap_stale(); clear_tex(a); break;   // it may clear the depth texture the copy was taken from (audit P2-247)
            case OP_DISPATCH: dispatch(a); break;
            case OP_BARRIER: { int32_t bits; memcpy(&bits, a, 4);   // ordered at the next draw pass (barrier_game); inside a pass with shader writes, the pass ends first (swrite_note)
                int split = g_enc && g_pass_swrite && (bits & (NVN_BARRIER_ORDER_FRAGMENTS_BIT | NVN_BARRIER_ORDER_FRAGMENTS_TILED_BIT));
                PD("I %llu barrier bits %#x%s", g_stat_pass, bits, split ? ": ends the pass (shader writes)" : g_enc ? " (render pass open)" : "");
                if (split) { rp_end(); static int once; if (!once++) MLOG("a game barrier (bits %#x) after shader writes in a draw pass: the pass ends there (first case pass %llu)", bits, (unsigned long long)g_stat_pass); }
                if (bits) g_game_barrier = 1; break; }
            case OP_SET_TEX_POOL: case OP_SET_SAMP_POOL: state_op(h.op, a, h.size); break;
            default: break;
        }
        p += h.size;
    }
}

// ---------- Present: draw the swapchain texture to the CAMetalLayer; optional screenshot ----------
static id<MTLRenderPipelineState> g_blit_pso; static MTLPixelFormat g_blit_fmt;
static id<MTLSamplerState> g_blit_samp;
static uint64_t g_present_n;
uint64_t mtl_present_count(void) { return g_present_n; }   // Actual present count (heat attribution DM_HEAT computes the present frame rate)
void mtl_res_snapshot(mtl_res_count *out) {
    memset(out, 0, sizeof *out);
    out->pso = g_pso.n;
    out->cps = g_cps.n;
    out->dss = g_dss.n;
    out->shaders = shader_cache_count();
    os_unfair_lock_lock(&g_c1_lock);
    out->c1_bufs = (uint32_t)(g_c1_banks.count + g_c1_exclusive); out->c1_alloc = g_c1_alloc_bytes; out->c1_data = g_c1_data_bytes;
    os_unfair_lock_unlock(&g_c1_lock);
    pthread_mutex_lock(&g_smu);
    out->live_tex = g_by_serial.n;
    pthread_mutex_unlock(&g_smu);
    pthread_mutex_lock(&g_mu);
    out->pools = (uint32_t)g_npool;
    out->pool_adds = g_pool_adds;
    pthread_mutex_unlock(&g_mu);
    pthread_mutex_lock(&g_rmu);
    out->view_slots = (uint32_t)g_ntreg;
    for (int i = 0; i < g_ntreg; i++) if (g_treg[i].view) out->view_nonnull++;
    for (int i = 0; i < g_nsreg; i++) if (g_sview[i]) out->sview_nonnull++;
    pthread_mutex_unlock(&g_rmu);
}
// ---------- GPU memory by category (DM_NVN_MEM_DETAIL, off by default) ----------
// One block of lines every DM_NVN_MEM_DETAIL_INTERVAL seconds (default 10; the frame hook that calls this runs every 300 frames, so anything shorter is one block per call).
// Why: the phone is killed for memory (phys_footprint) at about 8 GB while the same scene on the Mac peaks about 1.7 GB lower. "GPU allocated" alone cannot say which kind of allocation
// grew. This splits it the way the two platforms can differ: textures by format class / storage mode / render-target use (a decompressed BC texture shows up as 8-bit or 16-bit, a
// memoryless attachment as nothing), pool mirror buffers by mapped against resident bytes (mincore: on iOS a pool put in the residency set is read in whole and stays wired), upload
// staging blocks, shader libraries and pipeline states, open pipeline archives, the residency set and the deferred-release queue. Counts are of live objects only; the frame hook's
// cadence bounds the cost. All integer math on purpose: this runs on the guest thread's small stack, like nvn_be_mem_stat.
enum { MD_BC, MD_PVRTC_ETC, MD_ASTC, MD_8BIT, MD_16_32, MD_DEPTH, MD_OTHER, MD_NFMT };
// Only pixel formats that exist on iOS are named here (Depth24Unorm_Stencil8 / X24_Stencil8 are macOS-only and would not compile for the device);
// anything else falls into MD_OTHER rather than failing the build
static int nvn_mem_fmt_class(MTLPixelFormat pf) {
    if (pf >= MTLPixelFormatBC1_RGBA && pf <= MTLPixelFormatBC7_RGBAUnorm_sRGB) return MD_BC;
    if (pf >= MTLPixelFormatPVRTC_RGB_2BPP && pf <= MTLPixelFormatEAC_RG11Snorm) return MD_PVRTC_ETC;
    if (pf >= MTLPixelFormatASTC_4x4_sRGB && pf <= MTLPixelFormatASTC_12x12_LDR) return MD_ASTC;
    switch (pf) {
        case MTLPixelFormatA8Unorm: case MTLPixelFormatR8Unorm: case MTLPixelFormatR8Unorm_sRGB: case MTLPixelFormatR8Snorm: case MTLPixelFormatR8Uint: case MTLPixelFormatR8Sint:
        case MTLPixelFormatRG8Unorm: case MTLPixelFormatRG8Unorm_sRGB: case MTLPixelFormatRG8Snorm: case MTLPixelFormatRG8Uint: case MTLPixelFormatRG8Sint:
        case MTLPixelFormatRGBA8Unorm: case MTLPixelFormatRGBA8Unorm_sRGB: case MTLPixelFormatRGBA8Snorm: case MTLPixelFormatRGBA8Uint: case MTLPixelFormatRGBA8Sint:
        case MTLPixelFormatBGRA8Unorm: case MTLPixelFormatBGRA8Unorm_sRGB: case MTLPixelFormatRGB10A2Unorm:
        case MTLPixelFormatR16Unorm: case MTLPixelFormatRG16Unorm: case MTLPixelFormatRGBA16Unorm: case MTLPixelFormatR16Snorm: return MD_8BIT;
        case MTLPixelFormatR16Float: case MTLPixelFormatRG16Float: case MTLPixelFormatRGBA16Float: case MTLPixelFormatR32Uint: case MTLPixelFormatR32Sint: case MTLPixelFormatR32Float:
        case MTLPixelFormatRG32Uint: case MTLPixelFormatRG32Sint: case MTLPixelFormatRG32Float: case MTLPixelFormatRGBA32Uint: case MTLPixelFormatRGBA32Sint:
        case MTLPixelFormatRGBA32Float: case MTLPixelFormatRG11B10Float: return MD_16_32;
        case MTLPixelFormatDepth16Unorm: case MTLPixelFormatDepth32Float: case MTLPixelFormatStencil8:
        case MTLPixelFormatDepth32Float_Stencil8: case MTLPixelFormatX32_Stencil8: return MD_DEPTH;
        default: return MD_OTHER;
    }
}
// Allocation identities use independent strong pointer snapshots, one owner lock at a time.
#include <mach/mach.h>
#if TARGET_OS_IPHONE
#include <os/proc.h>
#endif
#include "nvn_xqueue.inc"   // cross-queue event ordering: nvn_be_submit
#include "nvn_mem_account.inc"
static void nvn_mem_detail(unsigned long long frame) {
    static int on = -1, interval_f = 300; static unsigned long long last;
    if (on < 0) { const char *e = getenv("DM_NVN_MEM_DETAIL"); on = e && *e && strcmp(e, "0"); if (on) { const char *iv = getenv("DM_NVN_MEM_DETAIL_INTERVAL"); int seconds = iv ? atoi(iv) : 10; interval_f = seconds > 5 && seconds <= INT_MAX / 60 ? seconds * 60 : 300; } }
    if (!on) return;
    // NvPkg/upload/arena mutable fields belong to the submit lane; do not walk them elsewhere.
    if (!on_sub_thread()) { static int warned; if (!warned++) MLOG("[mem_detail] skipped: not submit lane"); return; }
    if (last && frame - last < (unsigned long long)interval_f) return;
    last = frame;
    @autoreleasepool {
        uint64_t begin = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
        enum { MU_LIVE, MU_GHOST, MU_ALIAS, MU_POOLS, MU_VIEWS, MU_RESIDENCY, MU_DEFERRED, MU_UPLOAD, MU_ARENAS, MU_BANKS, MU_ALLOCATORS, MU_N };
        const char *names[MU_N] = {"live", "ghost", "alias", "pools", "views", "residency", "deferred", "upload", "arenas", "banks", "command-allocators"};
        NSHashTable *snap[MU_N]; for (int k = 0; k < MU_N; k++) snap[k] = nvn_mem_account_snapshot();
        NSHashTable *owners[3]; for (int m = 0; m < 3; m++) owners[m] = nvn_mem_account_snapshot();
        pthread_mutex_lock(&g_smu);
        nvn_hmap *maps[] = {&g_by_serial, &g_ghost, &g_alias};
        for (int m = 0; m < 3; m++) for (uint32_t i = 0; i < maps[m]->cap; i++) if (maps[m]->vals[i]) [owners[m] addObject:(__bridge id)maps[m]->vals[i]];
        pthread_mutex_unlock(&g_smu);
        for (int m = 0; m < 3; m++) for (id o in owners[m]) {
            if ([o isKindOfClass:NvPkg.class]) { NvPkg *p = o; if (p->tex) [snap[m] addObject:p->tex]; if (p->spare) [snap[m] addObject:p->spare]; if (p->view) [snap[m] addObject:p->view]; }
            else [snap[m] addObject:o];
        }
        uint64_t pool_mapped = 0;
        NSMutableArray<NSArray<NSNumber *> *> *pool_ranges = [NSMutableArray array];
        pthread_mutex_lock(&g_mu);
        for (int i = 0; i < g_npool; i++) {
            uint64_t len = (uint64_t)(g_pools[i].hi - g_pools[i].lo); pool_mapped += len;
            if (g_pools[i].buf) [snap[MU_POOLS] addObject:g_pools[i].buf];
            [pool_ranges addObject:@[@((uintptr_t)g_pools[i].base), @(len)]];
        }
        for (id b in g_dead_pools) if (b) [snap[MU_POOLS] addObject:b];
        pthread_mutex_unlock(&g_mu);
        pthread_mutex_lock(&g_rmu);
        for (uint32_t i = 0; i < g_vc.cap; i++) { vc_set *s = g_vc.vals[i]; if (!s) continue;
            for (int w = 0; w < VC_WAYS; w++) if (s->view[w]) [snap[MU_VIEWS] addObject:(__bridge id)s->view[w]];
            if (s->rows) [snap[MU_VIEWS] addObject:(__bridge id)s->rows];
        }
        for (int i = 0; i < g_ntreg; i++) { treg_t *t = &g_treg[i]; void *vs[] = {t->view,t->alt,t->ar,t->im};
            for (int v = 0; v < 4; v++) if (vs[v]) [snap[MU_VIEWS] addObject:(__bridge id)vs[v]];
        }
        pthread_mutex_unlock(&g_rmu);
        pthread_mutex_lock(&g_res_mu);
        for (id o in g_res_objects) if (o) [snap[MU_RESIDENCY] addObject:o];
        pthread_mutex_unlock(&g_res_mu);
        pthread_mutex_lock(&g_deferred_mu);
        for (NvDeferredRelease *d in g_deferred) if (d->object) [snap[MU_DEFERRED] addObject:d->object];
        pthread_mutex_unlock(&g_deferred_mu);
        for (int i = 0; i < 3; i++) if (g_up_slot_blk[i]) [snap[MU_UPLOAD] addObject:g_up_slot_blk[i]];
        if (g_up_block) [snap[MU_UPLOAD] addObject:g_up_block];
        for (id b in g_up_keep) if (b) [snap[MU_UPLOAD] addObject:b];
        for (NvArena *a in g_arenas) if (a->buf) [snap[MU_ARENAS] addObject:a->buf];
        for (NvArena *a in g_sub_arenas) if (a->buf) [snap[MU_ARENAS] addObject:a->buf];
        os_unfair_lock_lock(&g_c1_lock);
        for (id b in g_c1_banks) if (b) [snap[MU_BANKS] addObject:b];
        os_unfair_lock_unlock(&g_c1_lock);
        // Submit-owned main/upload slots; present slots are initialized before the queue starts.
        for (int i = 0; i < g_alloc_n; i++) if (g_alloc4[i]) [snap[MU_ALLOCATORS] addObject:g_alloc4[i]];
        for (int i = 0; i < 3; i++) { if (g_up_alloc4[i]) [snap[MU_ALLOCATORS] addObject:g_up_alloc4[i]]; if (g_present_alloc4[i]) [snap[MU_ALLOCATORS] addObject:g_present_alloc4[i]]; }
        // mincore does not dereference guest memory; an unmapped snapshot range is reported unknown.
        uint64_t pool_resident = 0; unsigned pool_unknown = 0; size_t page = (size_t)getpagesize();
        for (NSArray<NSNumber *> *range in pool_ranges) {
            uint64_t len = range[1].unsignedLongLongValue; size_t pages = len <= SIZE_MAX - page ? (size_t)((len + page - 1) / page) : 0; char *vec = pages && pages <= 8 * 1024 * 1024 ? malloc(pages) : NULL;
            if (!vec || mincore((void *)(uintptr_t)range[0].unsignedLongLongValue, (size_t)len, vec)) pool_unknown++;
            else for (size_t j = 0; j < pages; j++) if (vec[j] & 1) pool_resident += page;
            free(vec);
        }
        NvnMemAccount *all = [NvnMemAccount new];
        for (int k = 0; k < MU_N; k++) for (id o in snap[k]) [all addResource:o ownerMask:1ull << k];
        if (all.overflow) { MLOG("【红】[mem_detail] allocation byte total overflow; no residual published"); return; }
        for (int k = 0; k < MU_N; k++) {
            uint64_t bytes = 0; unsigned roots = 0;
            for (id root in all.roots) if ([[all.owners objectForKey:root] unsignedLongLongValue] & (1ull << k)) { bytes += [[all.allocationBytes objectForKey:root] unsignedLongLongValue]; roots++; }
            MLOG("[mem_detail] F%llu owner=%s references=%lu allocation_bytes=%llu roots=%u (owner buckets overlap; independent source snapshots)", frame, names[k], (unsigned long)snap[k].count, (unsigned long long)bytes, roots);
        }
        // Preserve every owner bit of each shared root. A missing live bit does not mean
        // an object is disposable: ghost/alias/views can still be needed by future replay.
        NSMutableDictionary<NSString *, NSMutableArray<NSNumber *> *> *groups = [NSMutableDictionary dictionary];
        uint64_t grouped_bytes = 0;
        for (id root in all.roots) {
            unsigned kind = 0; if (!nvn_mem_account_root(root, &kind)) continue;
            uint64_t bytes = [[all.allocationBytes objectForKey:root] unsignedLongLongValue];
            uint64_t mask = [[all.owners objectForKey:root] unsignedLongLongValue];
            unsigned long pf = 0, storage = 0, usage = 0;
            if (kind == NVN_MEM_TEXTURE) { id<MTLTexture> t = root; pf = t.pixelFormat; storage = t.storageMode; usage = t.usage; }
            int format_class = kind == NVN_MEM_TEXTURE ? nvn_mem_fmt_class((MTLPixelFormat)pf) : -1;
            NSString *key = [NSString stringWithFormat:@"owners=%llu kind=%u format=%lu class=%d storage=%lu usage=%lu", (unsigned long long)mask, kind, pf, format_class, storage, usage];
            NSMutableArray<NSNumber *> *g = groups[key];
            if (!g) groups[key] = g = [NSMutableArray arrayWithObjects:@0, @0, nil];
            g[0] = @([g[0] unsignedLongLongValue] + bytes); g[1] = @([g[1] unsignedLongLongValue] + 1); grouped_bytes += bytes;
        }
        for (NSString *key in groups) MLOG("[mem_detail_roots] F%llu %s bytes=%llu count=%llu", frame, key.UTF8String, groups[key][0].unsignedLongLongValue, groups[key][1].unsignedLongLongValue);
        MLOG("[mem_detail_roots] F%llu grouped_bytes=%llu counted_bytes=%llu owner_bits=live:1,ghost:2,alias:4,pools:8,views:16,residency:32,deferred:64,upload:128,arenas:256,banks:512,command-allocators:1024; capacity queries,not physical residency or permission to evict", frame, (unsigned long long)grouped_bytes, (unsigned long long)all.bytes);
        uint64_t gpu = g_dev.currentAllocatedSize, footprint = 0, available = 0;
        task_vm_info_data_t info; mach_msg_type_number_t count = TASK_VM_INFO_COUNT;
        if (task_info(mach_task_self(), TASK_VM_INFO, (task_info_t)&info, &count) == KERN_SUCCESS) footprint = info.phys_footprint;
#if TARGET_OS_IPHONE
        available = os_proc_available_memory();
#endif
        int64_t residual = 0; BOOL residual_ok = nvn_mem_account_delta(gpu, all.bytes, &residual);
        if (!residual_ok) { MLOG("【红】[mem_detail] GPU allocation counter too large; no signed residual published"); return; }
        MLOG("[mem_detail] F%llu unique_object_bytes=%llu buffers=%lu/%llu textures=%lu/%llu heaps=%lu/%llu other_allocations=%lu/%llu duplicates=%lu ignored=%lu GPU_allocated_bytes=%llu GPU_minus_known_bytes=%lld footprint_bytes=%llu available_bytes=%llu snapshot_us=%llu; not physical-page accounting, owner buckets overlap; excludes driver/library/PSO internals",
             frame, (unsigned long long)all.bytes, (unsigned long)all.buffers, (unsigned long long)all.bufferBytes, (unsigned long)all.textures, (unsigned long long)all.textureBytes, (unsigned long)all.heaps, (unsigned long long)all.heapBytes, (unsigned long)all.others, (unsigned long long)all.otherBytes,
             (unsigned long)all.duplicateReferences, (unsigned long)all.ignored, (unsigned long long)gpu, (long long)residual, (unsigned long long)footprint, (unsigned long long)available, (unsigned long long)((clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - begin) / 1000));
        MLOG("[mem_detail] F%llu no_copy_mapped_logical_bytes=%llu no_copy_resident_virtual_range_bytes=%llu unknown_ranges=%u; ranges may alias physical pages,never add to allocation-object totals", frame, (unsigned long long)pool_mapped, (unsigned long long)pool_resident, pool_unknown);

    }
    return;
}

// Resource counts (read by long-run stability L3): the host calls it per game tick / event (every 250 ticks, loading screen dismissed, exit), not sampled by wall clock / present count.
// Line format: [nvn] resource counts tick <tick number> <trigger>: <name> <value> ... (names contain no spaces, single-space separated); new fields are appended to the end of this line
void mtl_res_counts(uint32_t tick, const char *why) {
    mtl_res_count c;
    mtl_res_snapshot(&c);
    int dl, du; uint64_t da; nvn_dirty_slot_stats(&dl, &du, &da);
    LOG("[nvn] resource counts tick %u %s: render_pipelines %u compute_pipelines %u shaders %u depth_stencil_states %u views_nonnull %u view_slots %u live_textures %u pools_live %u pools_total %llu sampler_views_nonnull %u dirty_ranges_live %d dirty_ranges_total %llu c1_buffers %u c1_bytes %llu c1_used %llu gmem_draws %llu/%llu gmem_dispatches %llu/%llu",
        tick, why, c.pso, c.cps, c.shaders, c.dss, c.view_nonnull, c.view_slots, c.live_tex,
        c.pools, (unsigned long long)c.pool_adds, c.sview_nonnull, dl, (unsigned long long)da, c.c1_bufs, (unsigned long long)c.c1_alloc, (unsigned long long)c.c1_data,
        (unsigned long long)g_gmem_draws, (unsigned long long)g_gmem_draws_all, (unsigned long long)g_gmem_disp, (unsigned long long)g_gmem_disp_all);   // 原始内存池表动态占比（gmem_count_draw，读数不加锁：只作统计）
    char a[256], b[256]; pthread_mutex_lock(&g_fe_mu); fe_line_mark(a, sizeof a, &g_fe); fe_line_bg(b, sizeof b, &g_fe, bp_now()); pthread_mutex_unlock(&g_fe_mu);
    LOG("%s", a); LOG("%s", b);   // the first-encounter lines (fe_stat.h): fixed format, read by the run summaries
}
// Screenshot on request (used by DM_NVN_SHOT_UI): dm_gfx_shot_at(k, path) = take a screenshot at the kth frame after the current present frame; due requests are checked at every frame's present
#define SHOTQ_MAX 8
static struct { uint64_t frame; char path[1024]; } g_shotq[SHOTQ_MAX]; static int g_nshotq;
static pthread_mutex_t g_shotq_mu = PTHREAD_MUTEX_INITIALIZER;
static int present_encode(id<MTLCommandBuffer> cb, id<MTLTexture> src, id<MTLTexture> dst, const int crop[4]);
API_AVAILABLE(macos(26.0), ios(26.0))
static int present_encode_m4(id<MTL4CommandBuffer> cb, id<MTLTexture> src, id<MTLTexture> dst, const int crop[4], int uv_i);
// Game picture needed by the whole-window screenshot (front end window_shot; no longer does drawViewHierarchy on a Metal layer with the display link attached): at the next present, the present thread draws the same frame
// with the same encoding as the present (present_encode) into an offscreen texture of the same size as the swapchain, and after the GPU finishes hands out a CGImage in the completion callback (the callback does not block the present). Guarded by g_shotq_mu
static void (^g_grab_cb)(const uint8_t *bgra, size_t w, size_t h, size_t row);   // S2Arm: raw BGRA8 bytes (valid only during the call), no CGImage: the caller copies them once
void mtl_grab_next_present(void (^cb)(const uint8_t *bgra, size_t w, size_t h, size_t row)) { pthread_mutex_lock(&g_shotq_mu); g_grab_cb = [cb copy]; pthread_mutex_unlock(&g_shotq_mu); }
// S2Arm full-screen check (10-26): the same judgement, thresholds and log lines as the generic present layer graphics/metal/gal_present.m (shared in graphics/metal/fit_judge.h); the run executors
//   (tools/dev_run.sh) read "【红】出图未满屏" from host.log, and before this the direct present never wrote it, so every direct run read as full screen whatever it showed.
//   Geometry: on every present, the picture's viewport (present_encode's rule: aspect kept, filled when within 1%) narrower than the screen by more than 2 pixels, except a frame the core keeps
//   as a 16:9 page with black bars (g_fit_pillar). Content: judged on the full-window grab the autoplayer already asks for (about 20 a second in runs), on the autoplayer's thread, at most once every 30 presents,
//   or on the next grab while a geometry miss is unconfirmed; no grab, no judgement (no readback of our own: a GPU drain once a second would cost the player a frame)
#define FJ_LOG(...) MLOG(__VA_ARGS__)
#include "../../../metal/fit_judge.h"
static fj_state g_fj; static int g_fj_geo; static char g_fj_geo_why[160]; static uint64_t g_fj_last;   // g_fj_geo / why / last: present thread only (g_fj's counters are atomic for tests)
// S2Arm (10-30): the content check runs on the thread that takes the screenshot (host_adapt.m s2a_direct_screenshot, the autoplayer), never on the present thread. a04532dbe's seam check
//   ran inside grab_present and cost d2r 2.4% slow frames. The present thread only picks which grab is checked and keeps the geometry state of that moment (g_fj_due, a token per pick);
//   the consumer hands its own copy of those bytes back with the token (mtl_fit_judge_shot). fj_judge's own buffers (S->buf, fj_dark_band / fj_seam statics) are guarded by g_fj_run_mu
static pthread_mutex_t g_fj_mu = PTHREAD_MUTEX_INITIALIZER, g_fj_run_mu = PTHREAD_MUTEX_INITIALIZER;
static struct { uint64_t tok, n; int geo, kind, cw, ch; char why[160]; } g_fj_due;   // under g_fj_mu (held for a copy only: the present thread takes it); cw / ch: the picture's size at that present (fit_geom)
static _Thread_local uint64_t g_fj_tok_now;   // set only around the grab callback, on the thread that calls it: token of the grab being handed over (0 = not picked for the check)
int mtl_fit_bad(int kind) { return atomic_load(&g_fj.st[kind & 1]); }   // tests: 1 = the geometry (0) / content (1) check last said not full screen
static void fit_on(void) { static int once; if (!once++) MLOG("[画] 满屏判据 已开（直连上屏：几何每次出图判，内容在自动玩家截图上判、至少隔 30 次出图一次；免判 1 = 16:9 原比例页、4 = 游戏自己出宽图的纯 2D 帧）"); }   // the run executors read this line (ops-line receiving end)
// S2Arm: native widen.c refreshes this for each session. Match gal_present.m and do not retain the previous session's setting.
static int fit_narrow(void) { const char *e = getenv("S2A_WIDEN_NARROW"); return e && !strcmp(e, "1"); }
static int g_fj_cw, g_fj_ch;   // present thread: the picture's size at the last fit_geom (mtl_fit_judge_shot judges only the part of the grab it was drawn into)
static void fit_geom(double dw, double dh, NSUInteger cw, NSUInteger ch) {
    fit_on();
    if (dw <= 0 || dh <= 0 || !cw || !ch) return;
    g_fj_cw = (int)cw; g_fj_ch = (int)ch;
    double s = fmin(dw / cw, dh / ch), vw = fabs((dw / dh) / ((double)cw / ch) - 1) < 0.01 ? dw : round(cw * s);
    g_fj_geo = vw < dw - 2 && atomic_load(&g_fit_pillar) != 1 && atomic_load(&g_fit_pillar) != 5 && !fit_narrow();   // 5 = 原比例回退（3D 镜头帧回退上屏收进中间 16:9，留边是有意的）
    if (g_fj_geo) snprintf(g_fj_geo_why, sizeof g_fj_geo_why, "画面 %lux%lu 上屏只占 %.0f / %.0f 像素宽（左右留边）", (unsigned long)cw, (unsigned long)ch, vw, dw);
    else fj_note(&g_fj, 0, 0, "", g_present_n);
}
typedef struct { const uint8_t *p; size_t row; int w, h; } fit_px;
static void fit_col(void *c, int x, uint8_t *buf) { const fit_px *f = c; for (int y = 0; y < f->h; y++) memcpy(buf + 4 * y, f->p + (size_t)y * f->row + 4 * (size_t)x, 4); }
static void fit_row(void *c, int y, uint8_t *px) { const fit_px *f = c; memcpy(px, f->p + (size_t)y * f->row, 4 * (size_t)f->w); }
static uint64_t fit_pick(void) {   // present thread, at each grab: pick it for the content check (at most once every 30 presents, or every grab while a geometry miss is unconfirmed); 0 = not picked
    if (g_present_n - g_fj_last < 30 && !(g_fj_geo && !atomic_load(&g_fj.st[0]))) return 0;
    g_fj_last = g_present_n; fit_on(); static uint64_t seq;
    pthread_mutex_lock(&g_fj_mu);
    uint64_t tok = g_fj_due.tok = ++seq; g_fj_due.n = g_present_n; g_fj_due.geo = g_fj_geo; g_fj_due.cw = g_fj_cw; g_fj_due.ch = g_fj_ch; memcpy(g_fj_due.why, g_fj_geo_why, sizeof g_fj_due.why);
    g_fj_due.kind = fit_narrow() ? 1 : atomic_load(&g_fit_pillar);   // not on the widen verified list: 16:9 page by design (kind 1)
    pthread_mutex_unlock(&g_fj_mu);
    return tok;
}
// S2Arm (10-30): the frame a red line was judged on is kept (the first 3 reds of a run): <documents>/shots/fit_red_<k>.png, documents = S2A_DOCS (Mac runs: the run dir) or $HOME/Documents (iOS;
//   tools/dev_run.sh pulls Documents/shots/). Before this a red named a column and a row share but nothing showed it: the autoplayer's saved MARK / end shots are other frames
//   (10-30 mhrise device runs: three reds at column 260, every saved shot clean). Only autoplayer grabs are judged, so player runs write nothing
//   The first frame of each 16:9-with-black-bars stretch (fit_judge.h pst turns to 1 / 3 / 5) is kept the same way (11-02 commander: those stretches are judged in game or menu
//   page from their own frame; before this most stretches after MARK had no shot at all and could not be layered (神之天平外传)): fit_pil_<k>.png, the first 8 of a run
static void fit_shot_png(const char *name, int k, uint64_t n, const char *what, const uint8_t *p, size_t w, size_t h, size_t row);
// S2A_FRAME_REC_RED=1 (with S2A_FRAME_REC=<dir>): each of the first 3 reds also records the next present as <dir>/fitred<k>/ for frame replay (graphics/nvn/docs/frame_replay.md):
//   a red segment's page is reached at a different present every run, so a fixed present number misses it (11-02 Mario & Sonic line-up page, 13010 in one run, never in another)
int nvn_frec_on(void); void nvn_frec_request(const char *name);
//   S2A_FRAME_REC_RED=黑带 / 接缝 / 暗带: only reds of that content kind (fit_judge.h last_kind 1 / 2 / 3), so a page's reds of another kind do not use up the 3 recordings
static int fit_rec_red(void) {   // 0 off, -1 any red, else the content kind wanted
    static int on = 2; if (on != 2) return on;
    const char *e = getenv("S2A_FRAME_REC_RED");
    on = !e || !nvn_frec_on() ? 0 : !strcmp(e, "1") ? -1 : !strcmp(e, "黑带") ? 1 : !strcmp(e, "接缝") ? 2 : !strcmp(e, "暗带") ? 3 : 0;
    if (e && !on) MLOG("【红】 S2A_FRAME_REC_RED=%s 不认识（1 / 黑带 / 接缝 / 暗带；还要开 S2A_FRAME_REC），不录", e);
    return on;
}
static void fit_red_png(int k, uint64_t n, const uint8_t *p, size_t w, size_t h, size_t row) { fit_shot_png("fit_red", k, n, "红的那一帧", p, w, h, row); }
static void fit_shot_png(const char *name, int k, uint64_t n, const char *what, const uint8_t *p, size_t w, size_t h, size_t row) {
    char path[1200]; s2a_docs_path(path, sizeof path, "shots");
    mkdir(path, 0755); size_t L = strlen(path); snprintf(path + L, sizeof path - L, "/%s_%d.png", name, k);
    CGColorSpaceRef cs = CGColorSpaceCreateWithName(kCGColorSpaceSRGB);
    CGContextRef ctx = CGBitmapContextCreate((void *)p, w, h, 8, row, cs, kCGImageAlphaNoneSkipFirst | kCGBitmapByteOrder32Little);
    CGImageRef img = ctx ? CGBitmapContextCreateImage(ctx) : NULL;
    CFURLRef url = CFURLCreateFromFileSystemRepresentation(NULL, (const UInt8 *)path, strlen(path), false);
    CGImageDestinationRef dst = url ? CGImageDestinationCreateWithURL(url, (__bridge CFStringRef)UTTypePNG.identifier, 1, NULL) : NULL;
    int ok = 0; if (ctx && img && dst) { CGImageDestinationAddImage(dst, img, NULL); ok = CGImageDestinationFinalize(dst); }
    if (dst) CFRelease(dst); if (url) CFRelease(url); CGImageRelease(img); CGContextRelease(ctx); CGColorSpaceRelease(cs);
    MLOG("满屏判据第 %d 次%s（第 %llu 次出图）%s %s", k, what, (unsigned long long)n, ok ? "存到" : "没存成", path);
}
// 最近一次内容判定（fit_judge.h last_kind，原始样本）：0 正常 / 1 黑带 / 2 接缝 / 3 暗带 / 4 几何 / 5 免判；seq = 判定次数，present_n = 那次判的出图号（可空）。
//   11-02 体验线「局内扩展区异常（1–3）累计 20 秒问玩家是否退回原生 16:9」只读这里、不改判法；任意线程
int mtl_fit_last(uint64_t *seq, uint64_t *present_n) {
    if (seq) *seq = atomic_load(&g_fj.last_seq);
    if (present_n) *present_n = atomic_load(&g_fj.last_n);
    return atomic_load(&g_fj.last_kind);
}
uint64_t mtl_grab_fit_token(void) { return g_fj_tok_now; }   // call inside the grab callback: nonzero = these bytes are picked; pass it to mtl_fit_judge_shot with a copy of them
int mtl_fit_judge_shot(uint64_t tok, const uint8_t *p, size_t w, size_t h, size_t row) {   // any thread but the present one; 1 = judged (a newer pick replaces an unjudged one)
    pthread_mutex_lock(&g_fj_mu);
    int ok = tok && tok == g_fj_due.tok && p && w >= 8 && h >= 8; uint64_t n = g_fj_due.n; int geo = g_fj_due.geo, kind = g_fj_due.kind, cw = g_fj_due.cw, ch = g_fj_due.ch; char why[160]; memcpy(why, g_fj_due.why, sizeof why);
    if (ok) g_fj_due.tok = 0;
    pthread_mutex_unlock(&g_fj_mu);
    if (!ok) return 0;
    // 只判画面画进去的那块（11-09 质量线，哈迪斯 II Mac 验证局）：上屏按比例把画面放进窗口（present_encode 同一规则，宽高比差 1% 内算铺满），窗口比例 ≠ 画面比例时
    //   多出来的边是上屏自己留的。Mac 窗口 16:9、模拟手机屏 2.17:1 时整窗不比 16:9 宽，横向内容判据整段不跑，画面中间露空也报满屏 0 红；手机上画面就是整屏，裁不裁一样
    int vx = 0, vy = 0, vw = (int)w, vh = (int)h;
    if (cw > 0 && ch > 0 && fabs(((double)w / h) / ((double)cw / ch) - 1) >= 0.01) {
        double sc = fmin((double)w / cw, (double)h / ch); vw = (int)lround(cw * sc); vh = (int)lround(ch * sc);
        if (vw < 8 || vh < 8 || vw > (int)w || vh > (int)h) { vw = (int)w; vh = (int)h; } else { vx = ((int)w - vw) / 2; vy = ((int)h - vh) / 2; }
    }
    fit_px f = {p + (size_t)vy * row + (size_t)vx * 4, row, vw, vh}; fj_src s = {vw, vh, &f, fit_col, fit_row};
    static int npil;
    pthread_mutex_lock(&g_fj_run_mu); int r0 = atomic_load(&g_fj.nred), p0 = g_fj.pst; fj_judge(&g_fj, &s, geo, why, kind, n); int r1 = atomic_load(&g_fj.nred), p1 = g_fj.pst;
    int pil = p1 != p0 && (p1 == 1 || p1 == 3 || p1 == 5) && npil < 8 ? ++npil : 0; pthread_mutex_unlock(&g_fj_run_mu);
    if (r1 > r0 && r1 <= 3) fit_red_png(r1, n, p, w, h, row);
    { static int nrec; int want = fit_rec_red();   // the next present of this red, recorded for replay (the first 3 of the wanted kind)
      if (r1 > r0 && want && nrec < 3 && (want < 0 || atomic_load(&g_fj.last_kind) == want)) { char nm[16]; snprintf(nm, sizeof nm, "fitred%d", ++nrec); nvn_frec_request(nm); } }
    if (pil) fit_shot_png("fit_pil", pil, n, "留黑边段的第一帧", p, w, h, row);
    return 1;
}
// 玩家包请求判下一帧（11-02 体验线）：内容判据原先只在自动玩家截图上判，玩家包没有自动玩家就一条不判。这里借同一条离屏取图（mtl_grab_next_present，
//   上屏线程照上屏同一编码画一份离屏图），回调里只拷一份字节，判定交后台队列（不占上屏线程与 GPU 完成回调；10-30 d2r 判据在上屏线程跑过 2.4% 慢帧）。
//   自动玩家已挂着取图请求时让路（返回 0，不抢它的图）；判不判仍由 fit_pick 定（至少隔 30 次出图）。建议调用方 ≤ 1 次 / 秒。返回 1 = 已请求
int mtl_fit_sample(void) {
    pthread_mutex_lock(&g_shotq_mu); int busy = g_grab_cb != nil; pthread_mutex_unlock(&g_shotq_mu);
    if (busy) return 0;
    mtl_grab_next_present(^(const uint8_t *bgra, size_t w, size_t h, size_t row) {
        uint64_t tok = mtl_grab_fit_token(); if (!tok || !bgra || !w || !h) return;
        uint8_t *cp = malloc(row * h); if (!cp) return; memcpy(cp, bgra, row * h);
        dispatch_async(s2a_qos_global(S2A_QOS_IO_BG), ^{ mtl_fit_judge_shot(tok, cp, w, h, row); free(cp); });
    });
    return 1;
}
// S2Arm (10-30): the grab no longer stops the present thread. It used to drain the GPU (mtl_finish_gpu), copy on the old queue and wait for the copy (waitUntilCompleted) about
//   20 times a second in autoplayer runs: every grab broke the CPU / GPU overlap, and every autoplayer run's frame times and power readings carried it (frame-rate / energy line review
//   of e74f4b096). Now only what the copy really depends on waits, and only on the GPU or where the texture comes back:
//   - before the copy: the frame that drew this texture (g_ev at the fence committed so far; Metal 3 = queue order on g_q3, the game's own queue) and an external producer's
//     value for it (g_ext_ev, the value ext_wait was given for this present); other work keeps running alongside;
//   - after the copy: only the next write of this texture. The game gets a swapchain / external texture back through nvn_be_present_wait (AcquireTexture), which now also waits
//     while a grab of a ticket at or before the one it waits for is still copying (the Xenoblade 3 case of the old comment: the next frame's clear ran before the copy, a black grab)
//   The bytes go to the callback from the copy's completed handler (a Metal thread); one grab in flight at a time (out / buf are reused), a request made meanwhile waits for the
//   next present
static _Atomic int g_grab_busy;   // a grab is in flight: out / buf are in use until its callback has returned
// Tests (t_nvn_m3): a grab is still in flight. The completed handler calls the caller's callback before it clears g_grab_busy, so a caller that presents again right after
//   its callback fired can hit grab_present while busy: that present is not grabbed (the request stays for the next present). A caller that wants one grab per present
//   waits for this to read 0 before presenting again (11-06: t_nvn_m3 "screenshot of present N did not arrive in 5 s" on a loaded gate-host was this race, not a slow GPU)
int mtl_grab_inflight(void) { return atomic_load(&g_grab_busy); }
static uint64_t g_grab_tk;   // under g_pq_mu: ticket of the present whose texture is still being copied (0 = none); nvn_be_present_wait waits on it
static uint64_t g_ext_cur;   // present thread: the external producer value ext_wait was given for the present being made (0 = none)
static id<MTLSharedEvent> g_ext_ev;
static void grab_present(id<MTLTexture> src, const int crop[4], CGSize sz, uint64_t ticket) {
    if (atomic_load(&g_grab_busy)) return;
    pthread_mutex_lock(&g_shotq_mu); void (^cb)(const uint8_t *, size_t, size_t, size_t) = g_grab_cb; g_grab_cb = nil; pthread_mutex_unlock(&g_shotq_mu);
    if (!cb) return;
    size_t w = (size_t)sz.width, h = (size_t)sz.height, row = w * 4;
    // S2Arm: the offscreen texture and readback buffer are kept for the next grab of the same size. The autoplayer asks about 20 times a second; a fresh full-window texture and buffer
    //   each time showed up as 707 of 1844 samples of the main thread in IOKit (Breath of the Wild, 10 s Time Profiler, botw_1025095845_2). Only the present path calls this (one thread)
    static id<MTLTexture> out; static id<MTLBuffer> buf;
    if (!out || out.width != w || out.height != h) {
        MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm width:w height:h mipmapped:NO];
        d.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead; d.storageMode = MTLStorageModePrivate;
        out = w && h ? [g_dev newTextureWithDescriptor:d] : nil; buf = out ? [g_dev newBufferWithLength:row * h options:MTLResourceStorageModeShared] : nil; }
    id<MTLCommandBuffer> cb2 = !buf ? nil : g_m3 ? [g_q3 commandBuffer] : [g_q commandBuffer];   // retained references: out / buf / src live until it is done
    if (!cb2) { MLOG("【红】 full-window screenshot: no command buffer (%zux%zu)", w, h); cb(NULL, 0, 0, 0); return; }
    if (!g_m3 && g_ev && g_fence) [cb2 encodeWaitForEvent:g_ev value:g_fence];   // the frame that drew src (and anything committed before it); the old queue is not ordered with g_q4
    if (g_ext_cur && g_ext_ev) [cb2 encodeWaitForEvent:g_ext_ev value:g_ext_cur];   // an external producer's frame (the Vulkan layer)
    if (!present_encode(cb2, src, out, crop)) { MLOG("【红】 full-window screenshot: offscreen encoding of the game image failed (%zux%zu)", w, h); cb_put(cb2); cb(NULL, 0, 0, 0); return; }
    id<MTLBlitCommandEncoder> b = [cb2 blitCommandEncoder];
    [b copyFromTexture:out sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(w, h, 1) toBuffer:buf destinationOffset:0 destinationBytesPerRow:row destinationBytesPerImage:row * h];
    [b endEncoding];
    uint64_t tok = fit_pick();   // the content check itself runs on the consumer's thread (mtl_fit_judge_shot)
    id<MTLBuffer> bb = buf;
    atomic_store(&g_grab_busy, 1);
    pthread_mutex_lock(&g_pq_mu); g_grab_tk = ticket ? ticket : 1; pthread_mutex_unlock(&g_pq_mu);
    [cb2 addCompletedHandler:^(id<MTLCommandBuffer> c) {
        pthread_mutex_lock(&g_pq_mu); g_grab_tk = 0; pthread_cond_broadcast(&g_pq_cv); pthread_mutex_unlock(&g_pq_mu);   // the copy is done: src may be handed back (nvn_be_present_wait)
        // S2Arm: the bytes as they are (BGRA8, sRGB), valid during the call; the caller copies them once. buf stays ours until the callback returns
        if (c.error) { if (!mtl_gpu_cb_error(c.error, "screenshot", 0)) MLOG("【红】 full-window screenshot: copy failed: %s", c.error.description.UTF8String); cb(NULL, 0, 0, 0); }
        else { g_fj_tok_now = tok; cb((const uint8_t *)bb.contents, w, h, row); g_fj_tok_now = 0; }
        atomic_store(&g_grab_busy, 0);
    }];
    if (!cb_put(cb2)) { pthread_mutex_lock(&g_pq_mu); g_grab_tk = 0; pthread_cond_broadcast(&g_pq_cv); pthread_mutex_unlock(&g_pq_mu); atomic_store(&g_grab_busy, 0); cb(NULL, 0, 0, 0); }   // GPU 安全停：没交，回调不会来
}
void dm_gfx_shot_at(long k, const char *path) {
    pthread_mutex_lock(&g_shotq_mu);
    if (g_nshotq < SHOTQ_MAX) { g_shotq[g_nshotq].frame = g_present_n + (uint64_t)(k > 0 ? k : 0); strlcpy(g_shotq[g_nshotq].path, path, sizeof g_shotq[0].path); g_nshotq++; }
    else MLOG("【红】 more than %d screenshot requests; dropping %s", SHOTQ_MAX, path);
    pthread_mutex_unlock(&g_shotq_mu);
}
// DM_NVN_SHOT_OUT=WIDTHxHEIGHT (for picture quality metrics): the present-frame screenshot instead captures the result "upscaled to this resolution by present_encode", i.e. the picture the player sees on screen; screen=0 (texture dump) is unaffected
static void shot(id<MTLTexture> src, const char *path, int screen, const int crop[4]) {
    static int out_w = -1, out_h;
    if (out_w < 0) {
        out_w = 0;
        const char *e = getenv("DM_NVN_SHOT_OUT"); int w = 0, h = 0; char sep = 0, extra = 0;
        if (e && sscanf(e, "%d%c%d%c", &w, &sep, &h, &extra) == 3 && sep == 'x' && w > 0 && h > 0) { out_w = w; out_h = h; }
    }
    id<MTLTexture> read = src;
    if (out_w && screen) {
        MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm width:out_w height:out_h mipmapped:NO];
        d.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead; d.storageMode = MTLStorageModePrivate;
        id<MTLTexture> out = [g_dev newTextureWithDescriptor:d];
        if (!out) { MLOG("【红】 cannot create the screenshot output texture %dx%d", out_w, out_h); return; }
        id<MTLCommandBuffer> cb = q_cb();
        if (!present_encode(cb, src, out, crop) || !cb_run(cb)) return;
        read = out;
    }
    if (read.pixelFormat != MTLPixelFormatRGBA8Unorm && read.pixelFormat != MTLPixelFormatRGBA8Unorm_sRGB &&
        read.pixelFormat != MTLPixelFormatBGRA8Unorm && read.pixelFormat != MTLPixelFormatBGRA8Unorm_sRGB) { MLOG("【红】 screenshot does not support format %lu", (unsigned long)read.pixelFormat); return; }
    size_t w = read.width, h = read.height, row = w * 4;
    id<MTLBuffer> buf = [g_dev newBufferWithLength:row * h options:MTLResourceStorageModeShared];
    id<MTLCommandBuffer> cb = q_cb();
    id<MTLBlitCommandEncoder> b = [cb blitCommandEncoder];
    [b copyFromTexture:read sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(w, h, 1)
              toBuffer:buf destinationOffset:0 destinationBytesPerRow:row destinationBytesPerImage:row * h];
    [b endEncoding]; if (!cb_run(cb)) return;
    if (screen && read == src && atomic_load_explicit(&g_origin_ll, memory_order_relaxed)) {   // lower-left origin: the window image is stored bottom-up (see g_origin_ll)
        uint8_t *p = buf.contents, *tmp = malloc(row);
        if (tmp) { for (size_t y = 0; y < h / 2; y++) { memcpy(tmp, p + y * row, row); memcpy(p + y * row, p + (h - 1 - y) * row, row); memcpy(p + (h - 1 - y) * row, tmp, row); } free(tmp); } }
    int bgra = read.pixelFormat == MTLPixelFormatBGRA8Unorm || read.pixelFormat == MTLPixelFormatBGRA8Unorm_sRGB;
    CGColorSpaceRef cs = CGColorSpaceCreateWithName(kCGColorSpaceSRGB);
    CGBitmapInfo bi = bgra ? (kCGImageAlphaNoneSkipFirst | kCGBitmapByteOrder32Little) : (CGBitmapInfo)kCGImageAlphaNoneSkipLast;
    CGContextRef ctx = CGBitmapContextCreate(buf.contents, w, h, 8, row, cs, bi);
    CGImageRef img = ctx ? CGBitmapContextCreateImage(ctx) : NULL;
    CFURLRef url = CFURLCreateFromFileSystemRepresentation(NULL, (const UInt8 *)path, strlen(path), false);
    CGImageDestinationRef dst = url ? CGImageDestinationCreateWithURL(url, (__bridge CFStringRef)UTTypePNG.identifier, 1, NULL) : NULL;
    // If any step yields null (directory does not exist / not writable, bitmap context cannot be created), report a failure and return; previously it went straight to CFRelease(NULL) and crashed in CFRelease.cold (hit during a 1952-wide TEXDUMP)
    int ok = 0;
    if (!ctx || !img || !dst) MLOG("【红】 screenshot %s failed: %s", path, !ctx ? "cannot create the bitmap context" : !img ? "cannot get the image" : "cannot write (directory missing or not writable)");
    else { CGImageDestinationAddImage(dst, img, NULL); ok = CGImageDestinationFinalize(dst); }
    if (dst) CFRelease(dst); if (url) CFRelease(url); CGImageRelease(img); CGContextRelease(ctx); CGColorSpaceRelease(cs);
    MLOG("screenshot %zux%zu format %lu → %s %s", w, h, (unsigned long)read.pixelFormat, path, ok ? "ok" : "failed");
    if (g_defer_ab >= 0 && getenv("DM_NVN_DEFER_AB") && !strcmp(getenv("DM_NVN_DEFER_AB"), "1") && ok) { static int shots; if (++shots == 2) { g_defer_ab_on = 1; MLOG("DM_NVN_DEFER_AB: second screenshot written; deferred pass merging on"); } }
    if (g_udc_ab >= 0 && getenv("DM_NVN_UDC_AB") && !strcmp(getenv("DM_NVN_UDC_AB"), "1") && ok) {
        static int shots;
        if (++shots == 2) { g_udc_ab_on = 1; MLOG("DM_NVN_UDC_AB: second screenshot written; DM_NVN_UNWRITTEN_DC on"); }
    }
}
// ---------- DM_NVN_TEXDUMP=frame[,frame...]:path (%d remains "serial*100+layer*10+mip level"): save each selected guest frame's color targets ----------
// Diagnostic: before the first render pass of the next frame is opened, wait for the GPU to finish, then draw each one (the mip level used by that frame) by full-screen sampling into RGBA8 and save as PNG (float formats are clamped to [0,1])
static long g_td_frame = -2; static const char *g_td_path; static NSMutableArray *g_td_list; static int g_td_done;
static char *g_td_owned_path;
static NSIndexSet *g_td_frames;   // only the explicit comma-list mode; sorted and deduplicated
static void td_dump(void);
static void td_path(char *path, size_t n, int index) {
    if (!g_td_frames) { snprintf(path, n, g_td_path, index); return; }   // legacy single-frame / size filenames
    char base[1024]; if (snprintf(base, sizeof base, g_td_path, index) >= (int)sizeof base) MDIE("TEXDUMP output path is too long");
    const char *dot = strrchr(base, '.'), *slash = strrchr(base, '/');
    if (dot && slash && dot < slash) dot = NULL;
    int prefix = (int)(dot ? dot - base : strlen(base));
    if (snprintf(path, n, "%.*s_f%ld%s", prefix, base, g_td_frame, dot ? dot : "") >= (int)n) MDIE("TEXDUMP output path is too long");
}
static void td_clear(int pending_gpu) {
    // Only entries with a pass index own a diagnostic copy. Game attachments stay resident.
    for (NSArray *e in g_td_list) if (e.count > 4) { if (pending_gpu) defer_obj_release(e[0]); else res_remove(e[0]); }
    [g_td_list removeAllObjects];
}
// DM_NVN_TEXDUMP=size=WxH:path instead picks the frame by content: the first frame that opens a render pass whose first color attachment level is WxH (for one-off work whose frame differs between runs)
static unsigned g_td_w, g_td_h;
void td_note(MTL4RenderPassDescriptor *pd, NSUInteger nc) {
    if (g_td_frame == -2) { const char *e = getenv("DM_NVN_TEXDUMP"), *c = e ? strchr(e, ':') : NULL; g_td_frame = c ? atol(e) : -1; g_td_path = c ? c + 1 : NULL; g_td_list = [NSMutableArray array];
        if (c && !strncmp(e, "size=", 5) && sscanf(e + 5, "%ux%u", &g_td_w, &g_td_h) == 2) g_td_frame = LONG_MAX;
        else if (c && memchr(e, ',', (size_t)(c - e))) {
            NSMutableIndexSet *frames = [NSMutableIndexSet indexSet];
            for (const char *q = e; q < c;) {
                char *end; errno = 0; long f = strtol(q, &end, 10);
                if (*q < '0' || *q > '9' || errno || f < 0 || f == LONG_MAX || end > c || (end != c && (*end != ',' || end + 1 == c))) MDIE("invalid DM_NVN_TEXDUMP frame list: %s", e);
                [frames addIndex:(NSUInteger)f]; q = end == c ? c : end + 1;
            }
            if (!frames.count || !c[1]) MDIE("invalid DM_NVN_TEXDUMP frame list: %s", e);
            g_td_frames = frames; g_td_frame = (long)frames.firstIndex;
        } }
    if (g_td_frame < 0 || g_td_done) return;
    long f = (long)atomic_load(&g_cur_frame);
    if (g_td_frame == LONG_MAX) { id<MTLTexture> t0 = nc ? pd.colorAttachments[0].texture : nil; NSUInteger lv = pd.colorAttachments[0].level;
        if (t0 && MAX(t0.width >> lv, 1ul) == g_td_w && MAX(t0.height >> lv, 1ul) == g_td_h) { g_td_frame = f; MLOG("[texdump] first %ux%u render target at frame %ld: dumping this frame", g_td_w, g_td_h, f); } }
    while (f > g_td_frame) {
        td_dump();
        NSUInteger next = g_td_frames ? [g_td_frames indexGreaterThanIndex:(NSUInteger)g_td_frame] : NSNotFound;
        if (next == NSNotFound) return;
        g_td_frame = (long)next; g_td_done = 0;   // adjacent selected frames start collecting in this same td_note call
    }
    if (f != g_td_frame) return;
    for (NSUInteger i = 0; i < nc && i < 8; i++) {
        id<MTLTexture> t = pd.colorAttachments[i].texture; if (!t) continue;
        uint64_t ser = i < (NSUInteger)R.rt.n && R.rt.color[i] ? R.rt.color[i]->serial : 0;
        NSUInteger lv = pd.colorAttachments[i].level, sl = t.textureType == MTLTextureType2DArray ? pd.colorAttachments[i].slice : 0;
        BOOL seen = NO; for (NSArray *e in g_td_list) if (e.count < 5 && [e[1] unsignedLongLongValue] == ser && [e[2] unsignedIntegerValue] == lv && [e[3] unsignedIntegerValue] == sl) seen = YES;
        if (!seen) [g_td_list addObject:@[t, @(ser), @(lv), @(sl)]];
    }
}
void dm_gfx_texdump_next(const char *path) {
    if (g_td_frame == -2) td_note(nil, 0);   // read DM_NVN_TEXDUMP first, so it does not override the request
    // Render replay thread, like td_note/ts_after. A replaced copy may still be in the current submission; retire it without waiting here.
    rp_end();   // finish any selected pass's snapshot before discarding the old collection
    td_clear(1);
    free(g_td_owned_path); g_td_owned_path = strdup(path);
    if (!g_td_owned_path) MDIE("TEXDUMP output path allocation failed");
    g_td_path = g_td_owned_path; g_td_list = [NSMutableArray array]; g_td_frames = nil; g_td_done = 0; g_td_frame = (long)atomic_load(&g_cur_frame) + 1;
}
static void td_dump(void) {
    g_td_done = 1;
    rp_end(); if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    mtl_finish_gpu();
    static id<MTLRenderPipelineState> ps; static id<MTLSamplerState> sp;
    if (!ps) {
        static const char *src_msl =
            "#include <metal_stdlib>\nusing namespace metal;\n"
            "struct V { float4 p [[position]]; float2 uv; };\n"
            "vertex V vs(uint id [[vertex_id]]) { float2 uv = float2((id << 1) & 2, id & 2); V o; o.p = float4(uv * float2(2, -2) + float2(-1, 1), 0, 1); o.uv = uv; return o; }\n"
            "fragment float4 fs(V in [[stage_in]], texture2d<float> t [[texture(0)]], sampler s [[sampler(0)]]) { float4 c = t.sample(s, in.uv); return float4(c.rgb, 1); }\n";
        NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:@(src_msl) options:nil error:&e];
        MTLRenderPipelineDescriptor *d = [MTLRenderPipelineDescriptor new];
        d.vertexFunction = [lib newFunctionWithName:@"vs"]; d.fragmentFunction = [lib newFunctionWithName:@"fs"];
        d.colorAttachments[0].pixelFormat = MTLPixelFormatRGBA8Unorm;
        ps = [g_dev newRenderPipelineStateWithDescriptor:d error:&e];
        MTLSamplerDescriptor *sd = [MTLSamplerDescriptor new]; sp = [g_dev newSamplerStateWithDescriptor:sd];
        if (!ps) { MLOG("【红】 TEXDUMP pipeline failed %s", e.localizedDescription.UTF8String); td_clear(0); return; }
    }
    MLOG("[texdump] frame %ld: %lu color targets", g_td_frame, (unsigned long)g_td_list.count);
    // DM_NVN_TEXRAW=index,...: save raw bytes by texture index (including 3D; file: %d in the path is replaced with the index, suffix .raw, first-line text header: width height depth format bytes-per-row)
    for (const char *q = getenv("DM_NVN_TEXRAW"); q && *q; q = strchr(q, ',') ? strchr(q, ',') + 1 : q + strlen(q)) {
        if (!strncmp(q, "info", 4)) {   // DM_NVN_TEXRAW=info: the textures remembered by DM_NVN_TEXINFO
            static char buf[256]; size_t o = 0; for (int i = 0; i < g_texinfo_n; i++) o += snprintf(buf + o, sizeof buf - o, "%s%llu", i ? "," : "", (unsigned long long)g_texinfo_ser[i]);
            if (o) { static char env[300]; snprintf(env, sizeof env, "%s", buf); setenv("DM_NVN_TEXRAW", env, 1); q = getenv("DM_NVN_TEXRAW"); MLOG("[texraw] info → %s", q); } else continue;
        }
        uint64_t ser = (uint64_t)atoll(q); id o = serial_get(ser);
        id<MTLTexture> t = [o isKindOfClass:[NvPkg class]] ? ((NvPkg *)o)->tex : o;
        if (!t) { MLOG("[texraw] ser=%llu not in the serial table", ser); continue; }
        int bw, bh; NSUInteger w = t.width, h = t.height, dz = t.depth;
        size_t bpp = t.pixelFormat == MTLPixelFormatRGBA16Float ? 8 : t.pixelFormat == MTLPixelFormatRGBA32Float ? 16 : 4; (void)bw; (void)bh;
        size_t row = w * bpp, img = row * h;
        id<MTLBuffer> buf = [g_dev newBufferWithLength:img * dz options:MTLResourceStorageModeShared];
        id<MTLCommandBuffer> cb = q_cb(); id<MTLBlitCommandEncoder> b = [cb blitCommandEncoder];
        MTLBlitOption bo = t.pixelFormat == MTLPixelFormatDepth32Float_Stencil8 ? MTLBlitOptionDepthFromDepthStencil : MTLBlitOptionNone;   // depth-stencil: the 32-bit float depth plane only
        [b copyFromTexture:t sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(w, h, dz) toBuffer:buf destinationOffset:0 destinationBytesPerRow:row destinationBytesPerImage:img options:bo];
        [b endEncoding]; if (!cb_run(cb)) continue;
        char path[1024]; td_path(path, sizeof path, (int)ser); strlcat(path, ".raw", sizeof path);
        FILE *f = fopen(path, "wb"); if (f) { fprintf(f, "%lu %lu %lu %lu %zu\n", (unsigned long)w, (unsigned long)h, (unsigned long)dz, (unsigned long)t.pixelFormat, row); fwrite(buf.contents, 1, img * dz, f); fclose(f); }
        MLOG("[texraw] ser=%llu %lux%lux%lu format %lu → %s", ser, (unsigned long)w, (unsigned long)h, (unsigned long)dz, (unsigned long)t.pixelFormat, path);
    }
    for (NSArray *e in g_td_list) {
        id<MTLTexture> t = e[0]; uint64_t ser = [e[1] unsignedLongLongValue]; NSUInteger lv = [e[2] unsignedIntegerValue], sl = [e[3] unsignedIntegerValue];
        // 2D arrays are saved by the attached layer (file index ser*100 + layer*10 + level; layer 0 is named like 2D)
        if (t.textureType != MTLTextureType2D && t.textureType != MTLTextureType2DArray) { MLOG("[texdump] ser=%llu type %lu skipped", ser, (unsigned long)t.textureType); continue; }
        if (getenv("DM_NVN_SNAPRAW")) {   // Also save the raw bytes (converting an HDR target to an 8-bit image truncates; first-line text header: width height format bytes-per-row)
            NSUInteger rw = MAX(t.width >> lv, 1u), rh = MAX(t.height >> lv, 1u);
            size_t bpp = t.pixelFormat == MTLPixelFormatRGBA16Float ? 8 : t.pixelFormat == MTLPixelFormatRGBA32Float ? 16 : t.pixelFormat == MTLPixelFormatR16Float || t.pixelFormat == MTLPixelFormatR16Unorm ? 2 : 4;
            id<MTLBuffer> rb = [g_dev newBufferWithLength:rw * rh * bpp options:MTLResourceStorageModeShared];
            id<MTLCommandBuffer> rc = q_cb(); id<MTLBlitCommandEncoder> bb = [rc blitCommandEncoder];
            [bb copyFromTexture:t sourceSlice:0 sourceLevel:lv sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(rw, rh, 1) toBuffer:rb destinationOffset:0 destinationBytesPerRow:rw * bpp destinationBytesPerImage:rw * rh * bpp];
            [bb endEncoding]; if (!cb_run(rc)) continue;
            char rp_[1024]; td_path(rp_, sizeof rp_, (int)(ser * 100 + lv));
            if (e.count > 4) { char tail[64]; snprintf(tail, sizeof tail, "_s%03d", [e[4] intValue]); strlcat(rp_, tail, sizeof rp_); }   // TEXSNAP copies of one target: one file per pass
            strlcat(rp_, ".raw", sizeof rp_);
            FILE *f = fopen(rp_, "wb"); if (f) { fprintf(f, "%lu %lu %lu %zu\n", (unsigned long)rw, (unsigned long)rh, (unsigned long)t.pixelFormat, rw * bpp); fwrite(rb.contents, 1, rw * rh * bpp, f); fclose(f); }
        }
        id<MTLTexture> v = [t newTextureViewWithPixelFormat:t.pixelFormat textureType:MTLTextureType2D levels:NSMakeRange(lv, 1) slices:NSMakeRange(sl, 1)];
        NSUInteger w = MAX(t.width >> lv, 1u), h = MAX(t.height >> lv, 1u);
        MTLTextureDescriptor *od = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:w height:h mipmapped:NO];
        od.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead; od.storageMode = MTLStorageModePrivate;
        id<MTLTexture> o = [g_dev newTextureWithDescriptor:od];
        id<MTLCommandBuffer> cb = q_cb();
        MTLRenderPassDescriptor *rp = [MTLRenderPassDescriptor renderPassDescriptor];
        rp.colorAttachments[0].texture = o; rp.colorAttachments[0].loadAction = MTLLoadActionDontCare; rp.colorAttachments[0].storeAction = MTLStoreActionStore;
        id<MTLRenderCommandEncoder> en = [cb renderCommandEncoderWithDescriptor:rp];
        [en setRenderPipelineState:ps]; [en setFragmentTexture:v atIndex:0]; [en setFragmentSamplerState:sp atIndex:0];
        [en drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3]; [en endEncoding]; if (!cb_run(cb)) continue;
        char path[1024]; td_path(path, sizeof path, (int)(ser * 100 + sl * 10 + lv));
        if (e.count > 4) { td_path(path, sizeof path, 0); char *dot = strrchr(path, '.'), *slash = strrchr(path, '/'); char ext[16] = ""; if (dot && slash && dot < slash) dot = NULL; if (dot) { strlcpy(ext, dot, sizeof ext); *dot = 0; }
            char tail[64]; snprintf(tail, sizeof tail, "_s%03d_%llu_%lu%s", [e[4] intValue], (unsigned long long)ser, (unsigned long)lv, ext); strlcat(path, tail, sizeof path); }   // TEXSNAP copy
        MLOG("[texdump] ser=%llu lv=%lu layer %lu format %lu %lux%lu", ser, (unsigned long)lv, (unsigned long)sl, (unsigned long)t.pixelFormat, (unsigned long)w, (unsigned long)h);
        shot(o, path, 0, NULL);
    }
    td_clear(0);
}
// DM_NVN_TEXSNAP=in-frame index,... (together with the frame number and path of DM_NVN_TEXDUMP): as soon as these render passes end, copy their color attachments and save them together with the end-of-frame dump
// (the same target is often cleared and reused within a frame, so the end-of-frame state cannot reflect the output of intermediate passes); saved as <TEXDUMP path with %d = 0>_s<in-frame index>_<serial>_<level>.png
static int g_ts_idx[64], g_ts_n = -1, g_ts_on; static uint64_t g_ts_first, g_ts_curf = ~0ull;
static __strong id<MTLTexture> g_ts_att[8]; static uint64_t g_ts_ser[8]; static NSUInteger g_ts_lv[8]; static int g_ts_na;
void ts_note(MTL4RenderPassDescriptor *pd, NSUInteger nc) {
    if (g_ts_n < 0) { g_ts_n = 0; const char *e = getenv("DM_NVN_TEXSNAP");
        for (const char *q = e; q && *q && g_ts_n < 64; q = strchr(q, ',') ? strchr(q, ',') + 1 : q + strlen(q)) g_ts_idx[g_ts_n++] = atoi(q); }
    g_ts_on = 0; if (!g_ts_n || g_td_frame < 0 || g_td_done) return;
    uint64_t f = atomic_load(&g_cur_frame); if (f != g_ts_curf) { g_ts_curf = f; g_ts_first = g_stat_pass; }
    if ((long)f != g_td_frame) return;
    int idx = (int)(g_stat_pass - g_ts_first); for (int i = 0; i < g_ts_n; i++) if (g_ts_idx[i] == idx) g_ts_on = idx + 1;
    g_ts_na = 0; if (!g_ts_on) return;
    for (NSUInteger i = 0; i < nc && i < 8; i++) { id<MTLTexture> t = pd.colorAttachments[i].texture; if (!t) continue;
        g_ts_att[g_ts_na] = t; g_ts_ser[g_ts_na] = R.rt.color[i] ? R.rt.color[i]->serial : 0; g_ts_lv[g_ts_na] = pd.colorAttachments[i].level; g_ts_na++; }
}
void ts_after(void) {
    if (!g_ts_on) return;
    // The copy goes into the replay stream (Metal 4 copy encoder, after the pass that just ended). A command buffer of the classic queue, committed here, ran before the
    // Metal 4 command buffer holding the pass was even committed, so every snapshot showed the attachments as they were before the pass (found on Tears of the Kingdom)
    for (int i = 0; i < g_ts_na; i++) {
        id<MTLTexture> t = g_ts_att[i]; g_ts_att[i] = nil;
        if (t.textureType != MTLTextureType2D && t.textureType != MTLTextureType2DArray) continue;   // 2D arrays take slice 0
        MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:t.pixelFormat width:t.width height:t.height mipmapped:t.mipmapLevelCount > 1];
        d.usage = MTLTextureUsageShaderRead; d.storageMode = MTLStorageModePrivate; d.mipmapLevelCount = t.mipmapLevelCount;
        id<MTLTexture> c = [g_dev newTextureWithDescriptor:d]; res_add(c);
        NSUInteger lv = g_ts_lv[i], w = MAX((NSUInteger)1, t.width >> lv), h = MAX((NSUInteger)1, t.height >> lv);
        enc_b_copy_texture(blit(), t, 0, lv, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, 1), c, 0, lv, MTLOriginMake(0, 0, 0));
        [g_td_list addObject:@[c, @(g_ts_ser[i]), @(g_ts_lv[i]), @0, @(g_ts_on - 1)]];   // the end-of-frame fields (texture, serial, level, layer) plus the in-frame pass index: saved as <path with %d = 0>_s<index>_<serial>_<level>.png
    }
    g_ts_on = 0;
}
// Ring of actual presentation times: present sequence number -> presentedTime (seconds; -1 = dropped by the system, not presented)
#define PRING 1024
typedef struct { uint64_t n; double t; } pres_ent;
static pres_ent g_pres[PRING];
// Get the actual presentation time of the nth present (returns 0 if not ready, -1 if dropped)
double nvn_be_presented_time(uint64_t n) { pres_ent e = g_pres[n % PRING]; return e.n == n ? e.t : 0; }
static _Atomic uint64_t g_drawable_ns;   // Accumulated wall clock waiting for nextDrawable in present (timing instrumentation)
uint64_t nvn_be_drawable_ns_take(void) { return atomic_exchange(&g_drawable_ns, 0); }
// Maximum refresh rate (Hz) of the screen when there is a window; returns 0 without a window. Mac uses CoreGraphics display modes (thread-safe C interface; the present configuration is read on the game thread)
int nvn_be_display_hz(void) {
    if (!front_metal_layer()) return 0;
#if TARGET_OS_OSX
    CGDisplayModeRef m = CGDisplayCopyDisplayMode(CGMainDisplayID());
    double hz = m ? CGDisplayModeGetRefreshRate(m) : 0; if (m) CGDisplayModeRelease(m);
    return (int)(hz + 0.5);
#else
    Class c = NSClassFromString(@"UIScreen"); id s = c ? [c valueForKey:@"mainScreen"] : nil;
    return s ? [[s valueForKey:@"maximumFramesPerSecond"] intValue] : 0;
#endif
}
static _Atomic uint64_t g_present_stall_ns;   // For unit tests: an extra pause before each present on the present thread (simulating a drawable that stays unavailable)
static CAMetalLayer *g_present_layer_resident;
void mtl_present_test_stall(uint64_t ns) { g_present_stall_ns = ns; }
#include "nvn_present_aa.inc"
static void present_pipeline(MTLPixelFormat format) {
    present_options();
    if (!g_blit_pso || g_blit_fmt != format) {
        static const char *src_msl =
            "#include <metal_stdlib>\nusing namespace metal;\n"
            "struct V { float4 p [[position]]; float2 uv; };\n"
            "vertex V vs(uint id [[vertex_id]]) { float2 uv = float2((id << 1) & 2, id & 2); V o; o.p = float4(uv * float2(2, -2) + float2(-1, 1), 0, 1); o.uv = uv; return o; }\n"
            "struct Crop { float4 rect; float4 edge; };\n"
            "fragment float4 fs(V in [[stage_in]], texture2d<float> t [[texture(0)]], sampler s [[sampler(0)]], constant Crop& c [[buffer(0)]]) { return t.sample(s, clamp(in.uv * c.rect.zw + c.rect.xy, c.edge.xy, c.edge.zw)); }\n";
        NSError *e = nil;
        id<MTLLibrary> lib = [g_dev newLibraryWithSource:@(src_msl) options:nil error:&e];
        if (!lib) MDIE("present shader compile failed %s", e.localizedDescription.UTF8String);
        MTLRenderPipelineDescriptor *pd = [MTLRenderPipelineDescriptor new];
        pd.vertexFunction = [lib newFunctionWithName:@"vs"]; pd.fragmentFunction = [lib newFunctionWithName:@"fs"];
        pd.colorAttachments[0].pixelFormat = format;
        g_blit_pso = [g_dev newRenderPipelineStateWithDescriptor:pd error:&e];
        if (!g_blit_pso) MDIE("present pipeline failed %s", e.localizedDescription.UTF8String);
        g_blit_fmt = format;
        MTLSamplerDescriptor *sd = [MTLSamplerDescriptor new]; sd.minFilter = sd.magFilter = g_present_nearest ? MTLSamplerMinMagFilterNearest : MTLSamplerMinMagFilterLinear; sd.supportArgumentBuffers = YES;
        g_blit_samp = [g_dev newSamplerStateWithDescriptor:sd];
    }
}
// Present samples only the valid source rectangle declared by NVN; kept separate from the raw swapchain readback screenshot. Edges are clamped to the texel centers of the valid area, so bilinear does not read the black texels outside.
// Present samples the raw bytes stored in the swapchain texture (the Switch's scan-out sends the stored bytes as they are): an sRGB source is replaced by a non-sRGB view of the same storage,
// otherwise sampling decodes to linear first, the BGRA8Unorm layer does not encode again, and the whole picture comes out dark. Other formats are returned as they are (Mario's swapchain is RGBA8 and does not come here).
// View cache of 4 entries: swapchain textures live long and are few; a view holds its parent, so an equal parent pointer means the same object. A replaced view is released after the submissions that used it complete (Metal 4 does not retain resources)
static id<MTLTexture> present_raw_src(id<MTLTexture> src) {
    MTLPixelFormat pf = src.pixelFormat == MTLPixelFormatRGBA8Unorm_sRGB ? MTLPixelFormatRGBA8Unorm : src.pixelFormat == MTLPixelFormatBGRA8Unorm_sRGB ? MTLPixelFormatBGRA8Unorm : MTLPixelFormatInvalid;
    if (pf == MTLPixelFormatInvalid) return src;
    static __strong id<MTLTexture> views[4]; static int next; static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mu);
    id<MTLTexture> v = nil;
    for (int i = 0; i < 4 && !v; i++) if (views[i] && views[i].parentTexture == src) v = views[i];
    if (!v && (v = [src newTextureViewWithPixelFormat:pf])) { if (views[next]) defer_obj_unref(views[next]); views[next] = v; next = (next + 1) & 3; }
    pthread_mutex_unlock(&mu);
    if (!v) { RED_ONCE(69, "present: cannot create a non-sRGB view of the sRGB swapchain texture (format %lu); presenting the decoded values", (unsigned long)src.pixelFormat); return src; }
    return v;
}
#include "nvn_present_fit.h"   // pf_crop_fit (present_now) / pf_viewport (both blits); plain C, tested by graphics/nvn/tests/t_present_fit.c
static int present_blit(id<MTLCommandBuffer> cb, id<MTLTexture> src, id<MTLTexture> dst, const int crop[4], BOOL flip) {
    NSUInteger cx = 0, cy = 0, cw = src.width, ch = src.height;
    if (crop && (crop[2] || crop[3])) {
        if (crop[0] < 0 || crop[1] < 0 || crop[2] <= 0 || crop[3] <= 0 ||
            (uint64_t)crop[0] + crop[2] > src.width || (uint64_t)crop[1] + crop[3] > src.height) {
            MLOG("【红】 present crop out of bounds: %d,%d %dx%d / source texture %lux%lu", crop[0], crop[1], crop[2], crop[3], (unsigned long)src.width, (unsigned long)src.height); return 0;
        }
        cx = crop[0]; cy = crop[1]; cw = crop[2]; ch = crop[3];
    }
    static uint64_t last_crop[8]; uint64_t meta[8] = {src.width, src.height, cx, cy, cw, ch, dst.width, dst.height};
    if (memcmp(meta, last_crop, sizeof meta)) { memcpy(last_crop, meta, sizeof meta);
        MLOG("present crop: source texture %lux%lu, valid %lu,%lu %lux%lu → target %lux%lu", (unsigned long)src.width, (unsigned long)src.height,
             (unsigned long)cx, (unsigned long)cy, (unsigned long)cw, (unsigned long)ch, (unsigned long)dst.width, (unsigned long)dst.height); }
    present_pipeline(dst.pixelFormat);
    MTLRenderPassDescriptor *rp = [MTLRenderPassDescriptor renderPassDescriptor];
    // Keep the game picture's aspect ratio and center it, leaving black bars in the rest (no stretching when the screen ratio differs from the game's, e.g. iPhone about 19.5:9 versus the game's 16:9);
    // when the ratio difference is < 1% (the remainder from the game width being a multiple of 8 in the full-screen setup, e.g. 1952x900 versus 2868x1320 differs by 0.17%) fill directly, leaving no few-pixel border
    double dw = dst.width, dh = dst.height;
    pf_vp pv = pf_viewport(dw, dh, cw, ch); MTLViewport vp = {pv.x, pv.y, pv.w, pv.h, 0, 1};
    int full = vp.originX == 0 && vp.originY == 0 && vp.width == dw && vp.height == dh;
    static double last_vp[4];   // Log one line when the viewport changes (used by the real-device screen-level acceptance screen_check.py to check the aspect ratio)
    if (memcmp(last_vp, &vp, sizeof last_vp)) { memcpy(last_vp, &vp, sizeof last_vp);
        MLOG("present viewport %.0f,%.0f %.0fx%.0f / canvas %.0fx%.0f (game image %lux%lu)", vp.originX, vp.originY, vp.width, vp.height, dw, dh, (unsigned long)src.width, (unsigned long)src.height); }
    rp.colorAttachments[0].texture = dst; rp.colorAttachments[0].loadAction = full ? MTLLoadActionDontCare : MTLLoadActionClear;
    rp.colorAttachments[0].clearColor = MTLClearColorMake(0, 0, 0, 1);
    rp.colorAttachments[0].storeAction = MTLStoreActionStore;
    id<MTLRenderCommandEncoder> en = [cb renderCommandEncoderWithDescriptor:rp];
    [en setViewport:vp];
    [en setRenderPipelineState:g_blit_pso]; [en setFragmentTexture:present_raw_src(src) atIndex:0]; [en setFragmentSamplerState:g_blit_samp atIndex:0];
    float uv[8] = {(float)cx / src.width, (float)cy / src.height, (float)cw / src.width, (float)ch / src.height,
                   (cx + 0.5f) / src.width, (cy + 0.5f) / src.height, (cx + cw - 0.5f) / src.width, (cy + ch - 0.5f) / src.height};
    if (flip) { uv[1] += uv[3]; uv[3] = -uv[3]; }   // lower-left origin: the window image is stored bottom-up
    [en setFragmentBytes:uv length:sizeof uv atIndex:0];
    [en drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3];
    [en endEncoding];
    return 1;
}
static int present_blit_m4(id<MTL4CommandBuffer> cb, id<MTLTexture> src, id<MTLTexture> dst, const int crop[4], id<MTLBuffer> uvBuffer, id table, BOOL flip) {
    NSUInteger cx = 0, cy = 0, cw = src.width, ch = src.height;
    if (crop && (crop[2] || crop[3])) {
        if (crop[0] < 0 || crop[1] < 0 || crop[2] <= 0 || crop[3] <= 0 ||
            (uint64_t)crop[0] + crop[2] > src.width || (uint64_t)crop[1] + crop[3] > src.height) {
            MLOG("【红】 present crop out of bounds: %d,%d %dx%d / source texture %lux%lu", crop[0], crop[1], crop[2], crop[3], (unsigned long)src.width, (unsigned long)src.height); return 0;
        }
        cx = crop[0]; cy = crop[1]; cw = crop[2]; ch = crop[3];
    }
    present_pipeline(dst.pixelFormat);
    double dw = dst.width, dh = dst.height;
    pf_vp pv = pf_viewport(dw, dh, cw, ch); MTLViewport vp = {pv.x, pv.y, pv.w, pv.h, 0, 1};
    int full = vp.originX == 0 && vp.originY == 0 && vp.width == dw && vp.height == dh;
    MTL4RenderPassDescriptor *rp = pass_desc();
    rp.colorAttachments[0].texture = dst;
    rp.colorAttachments[0].loadAction = full ? MTLLoadActionDontCare : MTLLoadActionClear;
    rp.colorAttachments[0].storeAction = MTLStoreActionStore;
    rp.colorAttachments[0].clearColor = MTLClearColorMake(0, 0, 0, 1);
    id<MTL4RenderCommandEncoder> en = [cb renderCommandEncoderWithDescriptor:rp];
    if (!en) { MLOG("【红】 failed to create the M4 present render encoder"); return 0; }
    enc_full_barrier_begin(en);
    enc_r_table(en, table, MTLRenderStageFragment);
    tab_tex(table, present_raw_src(src), 0);
    tab_samp(table, g_blit_samp, 0);
    float *uv = uvBuffer.contents;
    uv[0] = (float)cx / src.width; uv[1] = (float)cy / src.height; uv[2] = (float)cw / src.width; uv[3] = (float)ch / src.height;
    uv[4] = (cx + 0.5f) / src.width; uv[5] = (cy + 0.5f) / src.height; uv[6] = (cx + cw - 0.5f) / src.width; uv[7] = (cy + ch - 0.5f) / src.height;
    if (flip) { uv[1] += uv[3]; uv[3] = -uv[3]; }   // normalized AA input is already upright
    tab_buf(table, uvBuffer, 0, 0);
    [en setViewport:vp]; [en setRenderPipelineState:g_blit_pso];
    [en drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3];
    enc_end_on(en, YES);
    return 1;
}
#include "nvn_present_fx.inc"
#include "nvn_dlss.inc"   // NVN2 EvaluateDlss → MetalFX temporal upscale
#include "nvn_tensor.inc"   // Switch 2 tensor-core upscaling networks (HMMA compute) → MetalFX spatial upscale stand-in
static int present_encode_slot(id<MTLCommandBuffer> cb, id<MTLTexture> src, id<MTLTexture> dst, const int crop[4], int slot) {
    present_options();
    BOOL flip = atomic_load_explicit(&g_origin_ll, memory_order_relaxed) != 0;
    NvPresentFX *fx = present_fx_for(slot, src, dst, crop, NO);
    if (!g_present_aa && !fx) return present_blit(cb, src, dst, crop, flip);
    id<MTLTexture> out;
    if (g_present_aa) {
        NvPresentAA *s = present_aa_prepare(slot, src, crop);
        if (!s || !present_blit(cb, src, s->input, crop, flip) || !present_aa_encode(cb, s, NO)) return 0;
        out = s->output;
    } else {
        if (!present_blit(cb, src, fx->input, crop, flip)) return 0;
        out = fx->input;
    }
    if (fx) {
        if (out != fx->input && (out.usage & [(id<MTLFXSpatialScalerBase>)fx->scaler colorTextureUsage]) != [(id<MTLFXSpatialScalerBase>)fx->scaler colorTextureUsage]) {
            if (!present_blit(cb, out, fx->input, NULL, NO)) return 0;
            out = fx->input;
        }
        present_fx_encode(cb, fx, out);
        out = fx->output;
    }
    return present_blit(cb, out, dst, NULL, NO);
}
static int present_encode(id<MTLCommandBuffer> cb, id<MTLTexture> src, id<MTLTexture> dst, const int crop[4]) {
    return present_encode_slot(cb, src, dst, crop, 3); // synchronous screen captures
}
API_AVAILABLE(macos(26.0), ios(26.0))
static int present_encode_m4(id<MTL4CommandBuffer> cb, id<MTLTexture> src, id<MTLTexture> dst, const int crop[4], int slot) {
    present_options();
    BOOL flip = atomic_load_explicit(&g_origin_ll, memory_order_relaxed) != 0;
    NvPresentFX *fx = present_fx_for(slot, src, dst, crop, YES);
    if (!g_present_aa && !fx) return present_blit_m4(cb, src, dst, crop, g_present_uv[slot], g_present_args, flip);
    id<MTLTexture> out;
    if (g_present_aa) {
        NvPresentAA *s = present_aa_prepare(slot, src, crop);
        if (!s || !present_blit_m4(cb, src, s->input, crop, s->cropUV, s->cropTable, flip) || !present_aa_encode(cb, s, YES)) return 0;
        out = s->output;
    } else {
        if (!present_blit_m4(cb, src, fx->input, crop, fx->cropUV, fx->cropTable, flip)) return 0;
        out = fx->input;
    }
    if (fx) {
        // 抗锯齿输出的用途不含放大器要的：再拷一次进放大器输入（那次拷贝用 fx 的裁剪参数缓冲：同一命令缓冲里抗锯齿的输入拷贝用的是 AA 自己那份）
        if (out != fx->input && (out.usage & [(id<MTLFXSpatialScalerBase>)fx->scaler colorTextureUsage]) != [(id<MTLFXSpatialScalerBase>)fx->scaler colorTextureUsage]) {
            if (!present_blit_m4(cb, out, fx->input, NULL, fx->cropUV, fx->cropTable, NO)) return 0;
            out = fx->input;
        }
        present_fx_encode(cb, fx, out);
        out = fx->output;
    }
    return present_blit_m4(cb, out, dst, NULL, g_present_uv[slot], g_present_args, NO);
}
static double g_link_it_tin;   // Enqueue time of the frame the display-link callback is presenting (read and written only on the display-link thread)
#if !TARGET_OS_SIMULATOR
static void present_note(id<CAMetalDrawable> dr, uint64_t pn) {   // pn: the game's present sequence number (ticket number)
    [dr addPresentedHandler:^(id<MTLDrawable> d) {   // Actual presentation time (the time this frame is really put on screen, CACurrentMediaTime base)
        CFTimeInterval tt = d.presentedTime;
        g_pres[pn % PRING] = (pres_ent){pn, tt > 0 ? tt : -1};
    }];
}
#endif
// Metal 3 present (#277 D3-1): the present command buffer presents the drawable (presentDrawable, in place of Metal 4's waitForDrawable / signalDrawable), with the timing Metal 4 gives
// [dr present] below: as soon as possible on the display link or without a period, else after the minimum duration
static void ext_wait3(id<MTLCommandBuffer> cb);
static void present_m3(id<MTLCommandBuffer> cb, id<CAMetalDrawable> dr, uint64_t ticket, double period, double target_ts) {
#if TARGET_OS_SIMULATOR
    (void)ticket; (void)period; (void)target_ts; [cb presentDrawable:dr];
#else
    present_note(dr, ticket);
    if (target_ts > 0 || period <= 0) [cb presentDrawable:dr]; else [cb presentDrawable:dr afterMinimumDuration:period];
#endif
}
// DM_NVN_REGLUM row (see present_now): region mean luminance and a subsampled grayscale thumbnail of the w x h RGBA8 / BGRA8 pixels at q; any thread (GPU completion)
static FILE *g_rlf; static pthread_mutex_t g_rlmu = PTHREAD_MUTEX_INITIALIZER;
static __strong id<MTLBuffer> g_rl_buf[3];   // Metal 4 readback per present slot (alloc_i): a slot is reused only after its previous present completed
static void rl_row(const uint8_t *q, NSUInteger w, NSUInteger h, unsigned long long n, unsigned long long tns) {
    uint64_t sum = 0; uint8_t g[4096]; NSUInteger ng = 0;   // Subsampled grayscale thumbnail (every 4th row / column, at most 4096 points), recorded along with the mean, for per-frame image correlation analysis
    for (NSUInteger y = 0; y < h; y += 4) for (NSUInteger x = 0; x < w && ng < sizeof g; x += 4) { const uint8_t *px = q + 4 * (y * w + x); g[ng++] = (uint8_t)((px[0] + px[1] + px[2]) / 3); }
    for (NSUInteger k = 0; k < w * h; k++) sum += q[4 * k] + q[4 * k + 1] + q[4 * k + 2];
    pthread_mutex_lock(&g_rlmu); fprintf(g_rlf, "%llu\t%llu\t%.4f\t", n, tns, sum / (3.0 * w * h));
    for (NSUInteger k = 0; k < ng; k++) fprintf(g_rlf, "%02x", g[k]);
    fputc('\n', g_rlf); fflush(g_rlf); pthread_mutex_unlock(&g_rlmu);
}
static int present_now(const tex_t *t, double period, uint64_t frame, uint64_t ticket, const int crop[4], id<CAMetalDrawable> supplied, double target_ts) {
    if (mtl_gpu_halted()) { atomic_fetch_add_explicit(&g_gpu_refused, 1, memory_order_relaxed); return 0; }   // GPU 安全停：不取画布、不交上屏（调用方按「没交」把票记完成）
    if (g_present_stall_ns) { struct timespec ts = {0, (long)g_present_stall_ns}; nanosleep(&ts, NULL); }
    g_present_n++;
    if (bootprof() && (g_present_n == 1 || g_present_n % 120 == 0)) {
        shader_load_stats();
        if (g_present_n == 1) g_bp_first_present = bp_now() - g_bp_t0;
        MLOG("[bootprof] t=%.3f s present #%llu: shader constructions %llu / load %.1f ms (shared wait %.1f ms); pipelines created %llu / %.1f ms (all synchronous on the submit thread); prewarmed and used: shaders %llu / render pipelines %llu / compute pipelines %llu; "
             "texture uploads %.1f MB / %llu first uploads + %llu re-uploads / %.1f ms; first present t=%.3f s", (bp_now() - g_bp_t0) / 1e9, g_present_n,
             g_bp_lib_n, g_bp_lib_ns / 1e6, g_bp_lib_wait_ns / 1e6, g_bp_pso_n, g_bp_pso_ns / 1e6, g_warm_claim_shaders, g_warm_claim_rps, g_warm_claim_cps,
             g_bp_up_bytes / 1048576.0, g_pkg_uploads, g_pkg_reuploads,
             g_up_total_ns / 1e6, g_bp_first_present / 1e9);
    }
    PD("X ser=%llu", t->serial);
    id<MTLTexture> src = tex_mtl(t);
    if (!src) { RED_ONCE(8, "present texture could not get an MTLTexture"); return 0; }
    // S2Arm: a crop reaching past the source (10-28 Splatoon 3 direct full screen: the game sets a 2346x1080 crop for a few frames while the swap chain texture is still
    //   1920x1080) is shown as the part inside the source, 16:9 with black bars (pf_crop_fit), instead of dropping the frame with "present crop out of bounds";
    //   once the source covers the crop it is used as given again. Everything below (present, grab, screenshots, fit check, AA) takes the fitted crop
    int rsc[4]; if (crop && rs_state(src) == RS_SCALED) {   // S2Arm internal resolution: a scaled present source (none expected: display textures are never scaled) takes the crop in storage texels
        long x = crop[0], y = crop[1], w = crop[2], h = crop[3]; if (!w && !h) { w = (long)rs_cw(src); h = (long)rs_ch(src); }
        rs_rect(g_rs, &x, &y, &w, &h); rsc[0] = (int)x; rsc[1] = (int)y; rsc[2] = (int)w; rsc[3] = (int)h; crop = rsc; }
    int fitted[4]; int fit_rc = pf_crop_fit(crop, src.width, src.height, fitted);
    { static int last; static uint64_t n;
      if (fit_rc == 1 && (last != 1 || ++n % 600 == 0)) MLOG("present crop %d,%d %dx%d is larger than the source texture %lux%lu: showing %d,%d %dx%d at 16:9 with black bars until the source covers it",
                              crop[0], crop[1], crop[2], crop[3], (unsigned long)src.width, (unsigned long)src.height, fitted[0], fitted[1], fitted[2], fitted[3]);
      if (fit_rc != 1 && last == 1) { MLOG("present crop covered by the source texture %lux%lu again: crop used as given", (unsigned long)src.width, (unsigned long)src.height); n = 0; }
      last = fit_rc; }
    if (crop && fit_rc >= 0) crop = fitted;
    // DM_NVN_REGLUM=x0,y0,x1,y1:file (normalized coordinates): read back this region on every present and record "present sequence number, present time ns, region mean luminance, subsampled grayscale thumbnail (hex)" (diagnostic: verify that animation speed is independent of frame rate).
    // Does not wait for the GPU and does not disturb frame pacing. Metal 4 with a window: the copy goes into this present's own command buffer, after the present blit and behind the same
    //   queue barrier, so the row is exactly the picture this present showed. A classic-queue command buffer (the only way before 11-06, still used without a window or on Metal 3) is not
