            else if (TARGET_OS_IPHONE || (d && *d)) s2a_docs_path(rp, sizeof rp, "%s", c + 1);
            else strlcpy(rp, c + 1, sizeof rp);   // Mac 没给 S2A_DOCS：按当前目录
