        rx0 = (NSUInteger)(rr[0] * src.width); ry0 = (NSUInteger)(rr[1] * src.height); rw = (NSUInteger)(rr[2] * src.width) - rx0; rh = (NSUInteger)(rr[3] * src.height) - ry0;
        rn = g_present_n; rtns = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
