    (void)frame;
    return 1;
}
// ---------- Present thread ----------
// NVN semantics: QueuePresentTexture only queues the present and returns immediately (the game often calls it while holding a lock; iOS real device: synchronously waiting for nextDrawable inside it
// takes about 30 ms, the lock is held about 90% of the time, and the loading thread starves). Taking the drawable, blit and present are all done on this thread in enqueue order.
// Ticket number = which enqueue it is (starting from 1); g_pq_done = the ticket number that has been processed (blit committed to the GPU queue).
// Swapchain texture return: before AcquireTexture gets a texture it waits for the ticket of that texture's previous present to be processed (nvn_be_present_wait), after which the commands the game draws into it
// are necessarily ordered after that blit on the GPU queue.
#define PQ 8
typedef struct { tex_t t; double period; uint64_t frame; int crop[4]; double t_in; uint64_t ev_val; } pq_item;   // t_in: the time the game handed this frame into the present queue (CACurrentMediaTime); ev_val: see g_ext_ev
// External producer (the Vulkan layer, dm/gfx/vk) renders on its own queue and signals this event when a frame's rendering is done: the present of that frame waits for the value on g_q4
static uint64_t g_ext_pend3;   // Metal 3: the value ext_wait asked for, encoded into the next present command buffer (an old queue waits only inside a command buffer)
static void ext_wait(uint64_t v) { g_ext_cur = v; if (g_m3) { if (v) g_ext_pend3 = v; return; } if (v && g_ext_ev) [g_q4 waitForEvent:g_ext_ev value:v]; }
static void ext_wait3(id<MTLCommandBuffer> cb) { if (g_ext_pend3 && g_ext_ev) [cb encodeWaitForEvent:g_ext_ev value:g_ext_pend3]; g_ext_pend3 = 0; }
static pq_item g_pq[PQ];
static uint64_t g_pq_in;
static int present_now(const tex_t *, double, uint64_t, uint64_t, const int[4], id<CAMetalDrawable>, double);
static double g_link_vperiod, g_link_vhalf;   // virtual ticks (link_range): seconds per counted tick (0 = every callback is a tick) and half a refresh of the screen
// Protected by g_pq_mu. Measure delegate arrivals, before virtual-tick filtering;
// a requested range is not proof that Core Animation granted that callback rate.
static uint64_t g_link20_last, g_link20_ns[30];
static unsigned g_link20_n;
static int g_link20_sample, g_link20_reported;
static _Atomic int g_link20_unavailable;

@interface NvMetalDisplayLinkDelegate : NSObject <CAMetalDisplayLinkDelegate>
@end

// Fallback for the display link going silent while in the foreground (two smoke-test hangs before merge: the display link stopped calling back while the app was in the foreground, nobody takes the queued frames, and the game waits forever for its previous present to be processed before "acquiring the next swapchain texture"):
// when nvn_be_present_wait has waited longer than STALL_NS and the display link has not called back for that long, drop the waiting frame and earlier queued frames as when entering the background (accounted as dropped frames) and let the game keep running; when the display link comes back things return to normal automatically.
// One stall logs one hint line, and one line on recovery (neither is a failure); only when the same stall lasts longer than STALL_RED_NS is it a failure. All under g_pq_mu
#define STALL_NS 100000000ull
#define STALL_RED_NS 2000000000ull
static uint64_t g_stall_t0, g_stall_drop, g_stall_n; static int g_stall_red, g_stall_logged;
// The display link watchdog only recognizes the "active" state: when the App loses active status (pulling down Control Center / notifications, incoming call, system popup) and in the background the system does not call back anyway, and the picture is covered too -- the frame-drop fallback stays as before,
// but it is not counted as stuck and no failure is reported; the stall is measured from the later of "the most recent callback / the most recent activation" (A16 logs: 8–17 seconds inactive and 17 seconds in the background were both reported as "stuck in foreground")
__attribute__((weak)) int dm_focus_now(void) { return 1; }   // Mac/iOS application shells provide strong lifecycle-backed definitions; shell-less graphics components have no application focus
__attribute__((weak)) uint64_t dm_focus_in_since(void) { return 0; }
@implementation NvMetalDisplayLinkDelegate
- (void)metalDisplayLink:(CAMetalDisplayLink *)link needsUpdate:(CAMetalDisplayLinkUpdate *)update {
    (void)link;
    uint64_t arrival = now_ns();
    pthread_mutex_lock(&g_pq_mu);
    int active = dm_focus_now() == 1;
    uint64_t since = dm_focus_in_since();
    // A background throttle or a callback spanning a focus/stall boundary is
    // not evidence that foreground 20 Hz was refused. Start a fresh batch.
    if ((!active || g_stall_t0 || (g_link20_last && since > g_link20_last)) && (g_link20_last || g_link20_n)) {
        MLOG("20 Hz callback sampling reset at %llu ns: active=%d since=%llu stall=%llu, discarded %u intervals", (unsigned long long)arrival, active, (unsigned long long)since, (unsigned long long)g_stall_t0, g_link20_n);
        g_link20_last = 0; g_link20_n = 0;
    }
    if (g_link20_sample && active && !g_stall_t0) {
        if (g_link20_last && arrival > g_link20_last) g_link20_ns[g_link20_n++] = arrival - g_link20_last;
        g_link20_last = arrival;
        if (g_link20_n == 30) {
            uint64_t sorted[30]; memcpy(sorted, g_link20_ns, sizeof sorted);
            for (unsigned i = 1; i < 30; i++) {
                uint64_t v = sorted[i]; unsigned j = i;
                while (j && sorted[j - 1] > v) { sorted[j] = sorted[j - 1]; j--; }
                sorted[j] = v;
            }
            uint64_t median = sorted[14] + (sorted[15] - sorted[14]) / 2;
            g_link20_n = 0;
            if (median < 45000000ull || median > 55000000ull) {
                atomic_store(&g_link20_unavailable, 1); g_link20_sample = 0;
                MLOG("【红】 display link requested 20 Hz (50 ms), 30 real callback intervals median %.3f ms: 20 Hz unavailable for this session; requesting 60 Hz fallback on next present (50 ms waits 3 ticks)", median / 1e6);
            } else if (!g_link20_reported) {
                g_link20_reported = 1;
                MLOG("display link requested 20 Hz (50 ms), 30 real callback intervals median %.3f ms: granted at %llu ns; continuing to check", median / 1e6, (unsigned long long)arrival);
            }
        }
    }
    if (g_stall_t0) { uint64_t t = now_ns();
        g_link20_last = 0; g_link20_n = 0;
        MLOG("display link recovered: stalled %.0f ms (%.0f ms of it active), fallback dropped %llu frames (stall #%llu)", (t - g_stall_t0) / 1e6, (t - (g_stall_t0 > since ? g_stall_t0 : since)) / 1e6, (unsigned long long)g_stall_drop, (unsigned long long)g_stall_n); g_stall_t0 = 0; }
    pthread_mutex_unlock(&g_pq_mu);
    double vp = g_link_vperiod, tol = 0.002;   // tol: how early a tick may come and still end a hold (below)
    if (vp > 0) {   // virtual ticks: only the refresh nearest each slot of a steady clock at the wanted rate counts (link_range)
        static double next, vp_was; double t = update.targetPresentationTimestamp;
        if (vp != vp_was || t > next + vp) { next = t; vp_was = vp; }   // the first callback, a new rate, or after a stall: the clock starts again here
        if (t < next - g_link_vhalf) return;
        next += vp; tol += 2 * g_link_vhalf;   // a tick lies up to half a refresh off its slot, so two of them up to one refresh nearer each other than the slots
    }
    pthread_mutex_lock(&g_link_mu);
    g_link_tick_ns = now_ns();
    g_link_tick_n++;
    pthread_cond_broadcast(&g_link_cv);
    pthread_mutex_unlock(&g_link_mu);
    pthread_mutex_lock(&g_pq_mu);
    if (!g_dm_present_link || g_pq_read == g_pq_in) { pthread_mutex_unlock(&g_pq_mu); return; }
    // The previous frame's present interval was >= 2 (period > 25 ms): keep it on screen for its whole period before taking the next one, as the Switch flips only every N vertical syncs. This also holds while the link runs at 60 Hz (Mario 1.2.1 sets 2 for single frames, see nvn_game_fps in hle_nvn.c);
    //   before, every tick took the newest frame, so that frame, carrying the extra time step the game advanced for it, was shown for only 16.7 ms and the game looked like it jumped ahead
    if (g_link_hold_until > 0 && update.targetPresentationTimestamp < g_link_hold_until - tol) { g_link_held++; pthread_mutex_unlock(&g_pq_mu); return; }
    uint64_t first = g_pq_read + 1, ticket = g_pq_in;
    // In order, one frame per tick and at most one behind the newest: two waiting, the older now and the newer on the next tick; three or more, the older ones are dropped. Taking the newest
    // dropped the one before whenever two frames landed in the same refresh, as frames of a 60 fps game that take 16-17.5 ms do, and the next frame then stayed up 33 ms
    // (Dark Souls Remastered, from PR #31: presents within 14.7-18.7 ms 98.2 -> 99.98 %, about 2 ms more from enqueue to display). DM_PRESENT_FIFO=0 takes the newest, as before
    static int fifo = -1; if (fifo < 0) { const char *e = getenv("DM_PRESENT_FIFO"); fifo = !(e && !strcmp(e, "0")); MLOG("display link: %s", fifo ? "frames in order, at most one behind" : "the newest frame each tick (DM_PRESENT_FIFO=0)"); }
    if (fifo && ticket > first) ticket = ticket - first >= 2 ? g_pq_in - 1 : first;
    pq_item it = g_pq[(ticket - 1) % PQ]; g_link_it_tin = it.t_in;
    g_pq_read = ticket;
    if (ticket > first) { g_link_dropped += ticket - first; for (uint64_t k = first; k < ticket; k++) g_pres[k % PRING] = (pres_ent){k, -1}; }   // Old frames merged and dropped are recorded as "not presented", so the present statistics honestly count them as dropped frames
    if (ticket > 1 && g_pq_done < ticket - 1) g_pq_done = ticket - 1;
    pthread_cond_broadcast(&g_pq_cv);
    pthread_mutex_unlock(&g_pq_mu);
    int submitted;
    ext_wait(it.ev_val);
    @autoreleasepool { submitted = present_now(&it.t, it.period, it.frame, ticket, it.crop, update.drawable, update.targetPresentationTimestamp); }
    g_link_hold_until = submitted && it.period > 0.025 ? update.targetPresentationTimestamp + it.period : 0;
    if (!submitted) {
        pthread_mutex_lock(&g_pq_mu);
        if (ticket > g_pq_done) g_pq_done = ticket;
        pthread_cond_broadcast(&g_pq_cv);
        pthread_mutex_unlock(&g_pq_mu);
    }
}
@end

static CAMetalDisplayLink *g_link; static CFRunLoopRef g_link_rl; static _Atomic int g_link_started;
static pthread_t g_link_thread;
static int g_link_joinable, g_link_stop_queued;
static _Atomic int g_link_stop;
static int g_link_applied;
static int g_link_owns_layer, g_classic_busy;   // Under g_pq_mu: nextDrawable throws while the layer has the display link object attached, so the present thread that takes its own drawable and the display link object are mutually exclusive
static int link_on(void) { return g_dm_present_link && g_link != nil; }
// Screens whose refresh rate is not a multiple of the link's (144 or 165 Hz against 60 or 30): asked for 60 Hz, the system fires the link on every third refresh of a 165 Hz screen,
// 55 Hz, and a game paced by the link runs at 55 fps (27.5 at 30). There the link runs at the screen's rate and only the refreshes nearest a steady clock of the wanted rate count as
// ticks (g_link_vperiod, NvMetalDisplayLinkDelegate): 60 a second on average, each frame shown on the refreshes nearest its 1/60 s slot. DM_LINK_VTICK=0 keeps the system's choice
__attribute__((weak)) int front_screen_max_fps(void) { return 0; }   // front_mac.m; graphics unit tests and iOS have none
static CAFrameRateRange link_range(int mode) {
    static int on = -1; if (on < 0) { const char *e = getenv("DM_LINK_VTICK"); on = !(e && !strcmp(e, "0")); }
    int rate = mode == 4 ? 20 : mode == 3 ? 30 : mode == 2 ? 120 : 60, hz = on ? front_screen_max_fps() : 0;
    if (mode != 2 && hz > rate && hz % rate) {
        if (g_link_vperiod != 1.0 / rate) MLOG("display link at the screen's %d Hz, counting a tick every 1/%d s (the screen's rate is not a multiple of it)", hz, rate);
        g_link_vhalf = 0.5 / hz; g_link_vperiod = 1.0 / rate;
        return CAFrameRateRangeMake(rate, hz, hz);
    }
    g_link_vperiod = 0;
    return mode == 2 ? CAFrameRateRangeMake(60, 120, 120) : CAFrameRateRangeMake(rate, rate, rate);
}
static int g_link_mode = 1;   // 1 / 2 same as g_dm_present_link, 3 = 30 Hz, 4 = 20 Hz
static int g_link_pending;
static uint64_t g_link_pending_since, g_link_pending_period;
static link_backoff g_low;   // 降到低频档的退避（nvn_link_backoff.h）
// Called under g_pq_mu. Only link_main invalidates the display link; repeating
// invalidate after the run-loop block has detached its layer crashes in CA.
static void link_stop_locked(void) {
    CFRunLoopRef rl = g_link_rl;
    if (!rl || g_link_stop_queued) return;
    g_link_stop_queued = 1;
    CFRunLoopPerformBlock(rl, kCFRunLoopDefaultMode, ^{ CFRunLoopStop(rl); });
    CFRunLoopWakeUp(rl);
}
// The game submitter owns creation/reaping until it stops. Session shutdown
// takes that ownership only after all guest submitters have joined.
static void link_join(void) {
    if (!g_link_joinable) return;
    int e = pthread_join(g_link_thread, NULL);
    if (e) MDIE("cannot join the display link thread (%d)", e);
    g_link_joinable = 0;
}
// 显示链接线程的实时声明（10-30 帧率能耗线；DM_LINK_RT=0 关）：每拍回调只取画布、编一次拷贝、提交，活很少，但必须准时被调度。
//   丝之歌测试设备（轮询线程长退避、整机 1.7 W、CPU 多在能效核约 1.9 GHz）每约 35 帧一个 33.3 ms 帧：游戏按时交帧（交帧间隔 16.69 ms）、
//   GPU 交帧后 4.7 ms 做完，可那一拍没放出去，上屏晚一整个刷新（第 5509 帧：交帧到上屏 62.6 ms，相邻帧 46 ms）。只有 QoS 的这条线程在低主频下偶尔被晚调度。
//   周期 = 链接目标帧率的一拍，计算 2 ms（回调实测远小于它），约束 = 一拍：给的是「准时」，不是让它多占核
static void link_rt_declare(void) {
    const char *e = getenv("DM_LINK_RT"); if (e && !strcmp(e, "0")) { MLOG("DM_LINK_RT=0: the display link thread gets no time-constraint policy"); return; }
    CAFrameRateRange r = link_range(g_link_mode); float hz = r.preferred > 0 ? r.preferred : r.maximum > 0 ? r.maximum : 60;
    uint64_t period_ns = (uint64_t)(1e9 / hz), comp_ns = 2000000ull; if (comp_ns > period_ns / 2) comp_ns = period_ns / 2;
    static mach_timebase_info_data_t tb; if (!tb.denom) mach_timebase_info(&tb);
    thread_time_constraint_policy_data_t p = { .period = (uint32_t)(period_ns * tb.denom / tb.numer), .computation = (uint32_t)(comp_ns * tb.denom / tb.numer),
        .constraint = (uint32_t)(period_ns * tb.denom / tb.numer), .preemptible = 1 };
    kern_return_t kr = thread_policy_set(pthread_mach_thread_np(pthread_self()), THREAD_TIME_CONSTRAINT_POLICY, (thread_policy_t)&p, THREAD_TIME_CONSTRAINT_POLICY_COUNT);
    thread_time_constraint_policy_data_t g = {0}; mach_msg_type_number_t gc = THREAD_TIME_CONSTRAINT_POLICY_COUNT; boolean_t gd = 0;   // 读回内核实际生效的值（同 hle_nvn.c set_time_constraint_comp）
    int got = thread_policy_get(pthread_mach_thread_np(pthread_self()), THREAD_TIME_CONSTRAINT_POLICY, (thread_policy_t)&g, &gc, &gd) == KERN_SUCCESS && !gd;
    MLOG("display link thread time-constraint policy (period %.3f ms, computation %.3f ms) %s; kernel now holds computation %.3f / constraint %.3f ms%s", period_ns / 1e6, comp_ns / 1e6, kr == KERN_SUCCESS ? "set" : "failed to set",
         got ? g.computation * (double)tb.numer / tb.denom / 1e6 : 0, got ? g.constraint * (double)tb.numer / tb.denom / 1e6 : 0, got ? "" : " (read back failed)");
}
static void *link_main(void *arg) {   // Display link thread: started when switching to display-link mode, exits when switching back to 0
    (void)arg;
    pthread_setname_np("nvn-present-link");
    s2a_qos_set_self(S2A_QOS_PRESENT);
    @autoreleasepool {
    CAMetalLayer *layer = (__bridge CAMetalLayer *)front_metal_layer();
    link_rt_declare();
    pthread_mutex_lock(&g_pq_mu); g_link_owns_layer = 1; while (g_classic_busy) pthread_cond_wait(&g_pq_cv, &g_pq_mu); pthread_mutex_unlock(&g_pq_mu);   // Wait for the present thread to finish handing over the frame it holds
    NvMetalDisplayLinkDelegate *delegate = [NvMetalDisplayLinkDelegate new];
    CAMetalDisplayLink *link = [[CAMetalDisplayLink alloc] initWithMetalLayer:layer];
    pthread_mutex_lock(&g_pq_mu);
    g_link20_sample = g_link_mode == 4; g_link20_last = 0; g_link20_n = 0; g_link20_reported = 0;
    link.preferredFrameRateRange = link_range(g_link_mode);
    pthread_mutex_unlock(&g_pq_mu);
    link.preferredFrameLatency = g_present_latency;
    link.delegate = delegate;
    [link addToRunLoop:[NSRunLoop currentRunLoop] forMode:NSDefaultRunLoopMode];
    pthread_mutex_lock(&g_pq_mu); g_link_rl = CFRunLoopGetCurrent(); g_link = link; pthread_cond_broadcast(&g_pq_cv); pthread_mutex_unlock(&g_pq_mu);
    if (!atomic_load(&g_link_stop)) CFRunLoopRun();
    [link invalidate];
    pthread_mutex_lock(&g_pq_mu);
    g_link = nil; g_link_rl = NULL; g_link_owns_layer = 0;
    pthread_mutex_unlock(&g_pq_mu);
    }
    pthread_mutex_lock(&g_pq_mu);
    g_link_started = 0;
    pthread_cond_broadcast(&g_pq_cv); pthread_mutex_unlock(&g_pq_mu);
    return NULL;
}
static int link_exact(int mode, double period) {   // 该链路档能否用整数个刻度给出这个周期（周期 0 = 不限，任何档都算能）
    if (period <= 0 || mode < 3) return 1;
    double t = period * (mode == 4 ? 20 : 30);
    return t >= 1 - 1e-6 && fabs(t - round(t)) < 1e-6;
}
static void link_sync(double period) {   // Called every frame by the game's present thread: aligns the display link object's state to g_dm_present_link and the power-saving mode (can change at run time)
    if (atomic_load(&g_link_stop)) return;
    int applied = g_link_applied; int want = g_dm_present_link; const int base = want;
    if (want < 0 || want > 2) { g_dm_present_link = applied >= 3 ? 1 : applied; return; }
    // Follow the current final period, never permanently lock out low rates
    // after a loading screen. Preserve the native-30 stability gate and pins.
    // The requested range is a hint; actual iOS callbacks still need measuring.
    int candidate = want;
    if (want && fps_override() == 30) want = candidate = 3;
    else if (want) {
        if (fps_override() < 0 && fabs(period * 20 - 1) < 1e-6) candidate = 4;
        else {
            double slots = period * 30;
            if (slots >= 1 - 1e-6 && fabs(slots - round(slots)) < 1e-6) candidate = 3;
        }
        // 20 Hz 档只看周期本身（恰好 50 ms、连续 1 秒，下面的迟滞判）：间隔 3 不再计入 30 帧口径（见 hle_nvn.c present_period）
        if (nvn_be_fps_target() == 30 || nvn_fps_limit() == 30 || candidate == 4) want = candidate;
    }
    // Reuse the one-second rationale of g_itv2_since: a single slow frame must
    // not reconfigure the system's asynchronous display link. Both directions
    // require the same final period continuously; explicit pins / off do not.
    int fallback = want && fps_override() < 0 && atomic_load(&g_link20_unavailable) && (candidate == 4 || applied == 4);
    if (fallback) want = candidate = 1;
    // 当前低频档（30 / 20 Hz）表示不了这一帧的周期（30 Hz 上的 50 ms、20 Hz 上的 33.3 ms）：立即回基础档（60 / 120 Hz），不等 1 秒、
    //   也不直接跳到另一个低频档（2↔3 来回切时会逐帧在 20 / 30 Hz 间改链路）；往低频降仍只走下面「同一周期稳 1 秒」
    //   （11-04 金刚真机：间隔 2↔3 来回切、周期从不稳 1 秒，链路一直留在 30 Hz，间隔 3 的帧全成 67 / 100 ms）
    const int inexact = applied >= 3 && want && base && !fallback && fps_override() < 0 && !link_exact(applied, period);
    uint64_t now = now_ns(), period_ns = (uint64_t)llround(period * 1e9);
    // 退避（nvn_link_backoff.h）：进低频档不到 2 秒就被打回 = 来回切，下次降档要稳的时长翻倍；低频稳 60 秒恢复
    lb_tick(&g_low, now);
    if (inexact) { lb_forced_back(&g_low, now); want = base; }
    // Start observing before nvn_game_fps's native-30 gate opens, so the same
    // stable second satisfies both gates rather than adding another second.
    if (g_link_pending != candidate || g_link_pending_period != period_ns) {
        g_link_pending = candidate; g_link_pending_period = period_ns; g_link_pending_since = now;
    }
    if (applied && want != applied && want && fps_override() < 0 && !fallback && !inexact) {
        if (now - g_link_pending_since < (want >= 3 ? lb_hold(&g_low) : LB_S)) want = applied;
    }
    if (want == applied && (!want || g_link_started)) return;
    g_link_mode = want;
    if (!g_link_started) {
        link_join();
        if (!want) { g_link_applied = 0; return; }
        if (!front_metal_layer()) return;
        g_link_stop_queued = 0;
        g_link_started = 1; if (pthread_create(&g_link_thread, NULL, link_main, NULL)) MDIE("cannot start the display link thread"); g_link_joinable = 1;
        return;   // The display link object is created on a new thread; align again next frame
    }
    pthread_mutex_lock(&g_pq_mu);
    CAMetalDisplayLink *link = g_link;
    if (!link || g_link_stop_queued) { pthread_mutex_unlock(&g_pq_mu); return; }
    if (want != 4 || applied != 4) {
        g_link20_sample = want == 4; g_link20_last = 0; g_link20_n = 0; g_link20_reported = 0;
    }
    if (want) link.preferredFrameRateRange = link_range(want);
    else link_stop_locked();
    MLOG("present pacing mode %d → %d (low-rate hold %.0f s; frame %llu)", applied, want, lb_hold(&g_low) / 1e9, (unsigned long long)atomic_load(&g_cur_frame));
    lb_applied(&g_low, applied, want, now);
    g_link_applied = want;
    pthread_cond_broadcast(&g_pq_cv); pthread_mutex_unlock(&g_pq_mu);
}
// Before going to the background (nvn_be_drain): when the display link drives presents, frames queued but not yet presented can only be taken by the display-link callback, and in the background the system no longer calls back --
// waiting as-is for "the present queue to empty" would wait forever, the enter-background callback would not return, and the system would kill the process (the process disappears within 22 seconds after switching to another App).
// These frames will not be seen anyway: discard them directly (accounted as dropped frames) and only wait for the one present already submitted to the GPU to finish.
static void present_drop_for_suspend(void) {
    pthread_mutex_lock(&g_pq_mu);
    if (g_link_owns_layer) {
        uint64_t n = g_pq_in - g_pq_read;
        for (uint64_t k = g_pq_read + 1; k <= g_pq_in; k++) g_pres[k % PRING] = (pres_ent){k, -1};
        g_link_dropped += n; g_pq_read = g_pq_in;
        while (g_pq_inflight) pthread_cond_wait(&g_pq_cv, &g_pq_mu);
        if (g_pq_done < g_pq_in) g_pq_done = g_pq_in;
        pthread_cond_broadcast(&g_pq_cv);
        if (n) MLOG("entering the background: dropping %llu queued frames not yet displayed (the display link does not fire in the background)", (unsigned long long)n);
    }
    pthread_mutex_unlock(&g_pq_mu);
}
static void *present_main(void *arg) {
    (void)arg;
    pthread_setname_np("nvn-present");
    s2a_qos_set_self(S2A_QOS_PRESENT);
    qos_class_t qc = QOS_CLASS_UNSPECIFIED; int rp = 0; pthread_get_qos_class_np(pthread_self(), &qc, &rp); atomic_store(&g_present_qos, (uint32_t)qc);
    for (;;) {
        pthread_mutex_lock(&g_pq_mu);
        while (g_pq_read == g_pq_in || g_link_owns_layer) pthread_cond_wait(&g_pq_cv, &g_pq_mu);   // In display-link mode the display-link callback takes them; an empty queue is judged by "taken"; "done" has to wait for the feedback of the present submit and lags behind taken
        pq_item it = g_pq[g_pq_read % PQ];
        uint64_t ticket = ++g_pq_read; g_classic_busy = 1;
        pthread_mutex_unlock(&g_pq_mu);
        int submitted;
        ext_wait(it.ev_val);
        uint64_t lv0[2][4], lv1[2][4]; thr_lv_take(lv0);
        @autoreleasepool { submitted = present_now(&it.t, it.period, it.frame, ticket, it.crop, nil, 0); }
        thr_lv_take(lv1); thr_lv_add(1, lv0, lv1);
        pthread_mutex_lock(&g_pq_mu); g_classic_busy = 0; pthread_cond_broadcast(&g_pq_cv); pthread_mutex_unlock(&g_pq_mu);
        if (!submitted) {
            pthread_mutex_lock(&g_pq_mu);
            if (ticket > g_pq_done) g_pq_done = ticket;
            pthread_cond_broadcast(&g_pq_cv);
            pthread_mutex_unlock(&g_pq_mu);
        }
    }
    return NULL;
}
uint32_t nvn_be_present_qos(void) { return atomic_load(&g_present_qos); }
static void present_start(void) { pthread_t th; if (pthread_create(&th, NULL, present_main, NULL)) MDIE("cannot start the present thread"); pthread_detach(th); }
static _Atomic int g_present_discard;
void mtl_link_pause(int on);
// The short period when the front end goes to the background and waits for the game to save: presents are dropped directly (the display link does not call back in the background, enqueueing would block the game thread; nobody sees the picture anyway).
// When turned on, also clear the frames already queued: the system first stops the display-link callback and only afterwards notifies about going to the background, and in that gap the game has already filled the swapchain and is stuck at "before acquiring the next texture, wait for its previous present to be processed"
// (hle_nvn.c nvnWindowAcquireTexture -> nvn_be_present_wait). Without clearing, the game cannot advance a single tick during those 2.5 seconds of waiting for the save, and the save is not written (the same pattern three times in player logs: 3 frames queued, 0 submits)
void mtl_present_discard(int on) { atomic_store(&g_present_discard, on != 0); if (on) present_drop_for_suspend(); }
static uint64_t present_enqueue(const tex_t *t, double period, const int crop[4], uint64_t ev_val);
uint64_t nvn_be_present(const tex_t *t, double period, const int crop[4]) { int c[4] = {0}; if (crop) memcpy(c, crop, sizeof c); wd_present(t, c); return present_enqueue(t, period, crop || c[2] || c[3] ? c : NULL, 0); }   // S2Arm widen: present notice (a fallback crop the core set counts even when the game gave none)
void *mtl_device(void) { mtl_init(); return (__bridge void *)g_dev; }
// An external producer's texture (the Vulkan layer's swapchain images): a serial the present path resolves (serial_put), resident for the Metal 4 queue, never collected by the cross-submit ledger
uint64_t mtl_ext_tex(void *tex) {
    static _Atomic uint64_t n; id<MTLTexture> t = (__bridge id<MTLTexture>)tex; uint64_t ser = (1ull << 62) + atomic_fetch_add(&n, 1) + 1;
    // 登记即 commit（#298）：驻留集原先要等下一次提交才生效，上屏路径不 commit——登记后、提交前就上屏（GL / Vulkan 前端换链首帧）时 Metal 4 上屏命令缓冲缺页。
    //   外部贴图只在建窗口表面 / 交换链时登记，次数极少，多一次 commit 不进热路径
    res_add(t); res_commit(); serial_put(ser, t); nvn_be_xv_window_tex(ser); return ser;
}
// Present an external texture after the producer's event reaches ev_val (its rendering of the frame is done); returns the ticket for nvn_be_present_wait
uint64_t mtl_present_ext(uint64_t serial, double period, void *ev, uint64_t ev_val, const int crop[4]) {
    tex_t t; memset(&t, 0, sizeof t); t.magic = MAGIC('T', 'E', 'X', 0); t.serial = serial;
    if (ev && !g_ext_ev) g_ext_ev = (__bridge id<MTLSharedEvent>)ev;
    return present_enqueue(&t, period, crop, ev ? ev_val : 0);
}
static uint64_t present_enqueue(const tex_t *t, double period, const int crop[4], uint64_t ev_val) {
    if (atomic_load(&g_present_discard) || mtl_gpu_halted()) return 0;   // GPU 安全停同丢帧。Ticket number 0 = no pending present; the swapchain texture acquire does not wait
    if (t) { xv_check(t->serial, 0, 0, "present"); if (g_xv_npresent < 128) g_xv_present[g_xv_npresent++] = t->serial; }
    static pthread_once_t once = PTHREAD_ONCE_INIT; pthread_once(&once, present_start);
    link_sync(period);
    {   // Test switch DM_TEST_LINK_STALL=start seconds,duration seconds: counting from the first present, pause the display link at that point (imitating the display link not calling back while in the foreground) and release it when the duration is up. For verifying the fallback; not set in the product
        static double t0, at = -1, dur; static int st; double now = CACurrentMediaTime();
        if (at < 0) { at = 0; const char *e = getenv("DM_TEST_LINK_STALL"); if (e && sscanf(e, "%lf,%lf", &at, &dur) == 2 && at > 0 && dur > 0) { t0 = now; st = 1; } else at = 0; }
        if (st == 1 && link_on() && now - t0 >= at) { st = 2; mtl_link_pause(1); MLOG("DM_TEST_LINK_STALL: pausing the display link for %.1f s (frame %llu)", dur, (unsigned long long)atomic_load(&g_cur_frame)); }
        else if (st == 2 && now - t0 >= at + dur) { st = 3; mtl_link_pause(0); MLOG("DM_TEST_LINK_STALL: resuming the display link (frame %llu)", (unsigned long long)atomic_load(&g_cur_frame)); }
    }
    pthread_mutex_lock(&g_pq_mu);
    if (g_pq_in - g_pq_done >= PQ) { pthread_mutex_unlock(&g_pq_mu); DM_BLOCK_BEGIN(); pthread_mutex_lock(&g_pq_mu); while (g_pq_in - g_pq_done >= PQ && !atomic_load(&g_present_discard)) pthread_cond_wait(&g_pq_cv, &g_pq_mu); pthread_mutex_unlock(&g_pq_mu); DM_BLOCK_END(); pthread_mutex_lock(&g_pq_mu); }
    if (atomic_load(&g_present_discard)) { pthread_mutex_unlock(&g_pq_mu); return 0; }
    pq_item *it = &g_pq[g_pq_in % PQ]; *it = (pq_item){*t, period, atomic_load(&g_cur_frame), {0}, CACurrentMediaTime(), ev_val};
    if (crop) memcpy(it->crop, crop, sizeof it->crop);   // The current frame's state is enqueued with the ticket number, rather than reading the mutable window late on the present thread
    uint64_t tk = ++g_pq_in;
    pthread_cond_broadcast(&g_pq_cv);
    pthread_mutex_unlock(&g_pq_mu);
    return tk;
}
// Do not wait during discard: the frame enqueued only after the flag was set (the present thread had just passed the flag check) has nobody to take it, and waiting for it would stall again; it is left for the following nvn_be_drain to clear
// Do not wait indefinitely in display-link mode: see the note at STALL_NS. Only frames "not yet taken by the display link" are dropped; the one already on its way to the screen is waited for until handed to the GPU (same dropping as when entering the background)
void nvn_be_present_wait(uint64_t tk) {
    pthread_mutex_lock(&g_pq_mu);
    // S2Arm: a full-window grab of this ticket or an earlier one still copying reads the texture being handed back (grab_present); wait for the copy (GPU time, under a millisecond)
    while (g_grab_tk && g_grab_tk <= tk && !atomic_load(&g_present_discard)) pthread_cond_wait(&g_pq_cv, &g_pq_mu);
    int blk = g_pq_done < tk && !atomic_load(&g_present_discard); if (blk) { pthread_mutex_unlock(&g_pq_mu); DM_BLOCK_BEGIN(); pthread_mutex_lock(&g_pq_mu); }
    while (g_pq_done < tk && !atomic_load(&g_present_discard)) {
        if (!g_link_owns_layer) { pthread_cond_wait(&g_pq_cv, &g_pq_mu); continue; }
        if (g_pq_read >= tk) { pthread_cond_wait(&g_pq_cv, &g_pq_mu); continue; }   // This one has already been taken by the display link and is being presented: wait for it to be handed to the GPU (the GPU completion callback will wake us)
        struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts); ts.tv_nsec += (long)STALL_NS; if (ts.tv_nsec >= 1000000000L) { ts.tv_sec++; ts.tv_nsec -= 1000000000L; }
        // Already determined to be in a stall (when the display link comes back the callback first clears g_stall_t0, then records the display-link tick time): no longer wait 100 ms in vain every frame, drop directly, and the game proceeds by its own display-link wait timeout (about two ticks)
        if (!g_stall_t0 && (pthread_cond_timedwait(&g_pq_cv, &g_pq_mu, &ts) != ETIMEDOUT || g_pq_done >= tk)) continue;
        uint64_t now = now_ns(), last = __atomic_load_n(&g_link_tick_ns, __ATOMIC_RELAXED);
        if (g_pq_read >= tk) continue;
        if (now - last < STALL_NS) { pthread_cond_timedwait(&g_pq_cv, &g_pq_mu, &ts); continue; }   // The display link is still running, it is just not this one's turn yet: keep waiting (bounded, no busy spinning)
        uint64_t n = tk - g_pq_read;
        for (uint64_t k = g_pq_read + 1; k <= tk; k++) g_pres[k % PRING] = (pres_ent){k, -1};
        g_link_dropped += n; g_pq_read = tk;
        while (g_pq_inflight) pthread_cond_wait(&g_pq_cv, &g_pq_mu);
        if (g_pq_done < tk) g_pq_done = tk;
        pthread_cond_broadcast(&g_pq_cv);
        if (!g_stall_t0) { g_stall_t0 = last ? last : now; g_stall_drop = 0; g_stall_red = 0; g_stall_logged = 0; g_stall_n++; }
        g_stall_drop += n;
        int active = dm_focus_now() == 1; uint64_t since = dm_focus_in_since(), from = g_stall_t0 > since ? g_stall_t0 : since;
        if (active && !g_stall_logged && now - from >= STALL_NS) { g_stall_logged = 1;
            MLOG("display link silent for %.0f ms (active): dropping %llu queued frames not yet displayed, the game continues (stall #%llu; back to normal when the link returns)", (now - from) / 1e6, (unsigned long long)n, (unsigned long long)g_stall_n); }
        if (active && !g_stall_red && now - from >= STALL_RED_NS) { g_stall_red = 1; MLOG("【红】 display link silent for %.1f s while active; presenting relies entirely on fallback frame drops, the picture is frozen", (now - from) / 1e9); }
    }
    pthread_mutex_unlock(&g_pq_mu);
    if (blk) DM_BLOCK_END();
}
// Wait until all queued presents have been processed (used by nvn_be_finish = nvnQueueFinish etc.): goes through nvn_be_present_wait, so there is still a fallback when the display link stops (real device: the game called QueueFinish once while the display link was stopped,
// and this used to wait here without a timeout; nobody took the 3 queued frames and the game stalled; those two runs on Mac did not hit this call)
