#include "rt_range_check.inc"
#endif

// Called by the watchdog (no progress): writes the state of all blocking wait points on the graphics side to the log -- who is waiting for whom is visible at a glance (after switching to the Metal 4 submit model there was once a case of "ran to 900 frames then stopped, no failure line")
// Metal 3 argument tables self-test (#279 D3-3; graphics/nvn/tests/t_nvn_m3.m): a resident buffer bound by an address inside it (tab_addr → m3_buf_at), a dispatch on a real old
// compute encoder copies what its two slots point at, read back; an address in no resident buffer is not bound and is counted. → 0 passed, else what failed in why
// Partial re-upload geometry self-test (graphics/nvn/tests/t_nvn_m3.m): a 256x256 RGBA8 single-level 2D texture, block-linear. Hand-derived from the layout: a GOB column is 64 / 4 = 16 texels
// wide, 16 columns make a block row of 16 x (512 << tileH) bytes and (8 << tileH) texel rows. → 0 passed, else what failed in why
typedef struct { up_rect r[8]; int n; } rect_got;
static void rect_got_add(void *u, unsigned level, unsigned layer, uint32_t x, uint32_t y, uint32_t w, uint32_t h) { rect_got *g = u; if (g->n < 8) g->r[g->n++] = (up_rect){level, layer, x, y, w, h}; }
typedef struct { uint64_t lo[8], hi[8]; int n; } range_got;
static void range_got_add(void *u, uint64_t lo, uint64_t hi) { range_got *g = u; if (g->n < 8) { g->lo[g->n] = lo; g->hi[g->n++] = hi; } }
int mtl_rect_selftest(char *why, size_t n) {
    tex_t t; memset(&t, 0, sizeof t); t.d.target = NVN_TEXTURE_TARGET_2D; t.d.format = NVN_FORMAT_RGBA8; t.d.width = t.d.height = 256; t.d.depth = 1; t.d.levels = 1; nvn_tex_layout(&t.d, &t.L);
    int bw, bh, bpb = nvn_fmt_bpb(t.d.format, &bw, &bh); unsigned th = 0, td = 0; nvn_tex_level_tiles(&t.d, 0, &th, &td); uint32_t gobs = nvn_tex_level_gobs(&t.d, 0);
    if (bpb != 4 || gobs != 16 || td) { snprintf(why, n, "layout: bpb %d gobs %u tileD %u (want 4, 16, 0)", bpb, gobs, td); return 1; }
    uint64_t blk = 512ull << th, row = 16 * blk; uint32_t rh = 8u << th;
    rect_got g = {0}; tex_bytes_rects(&t, blk, 2 * blk, rect_got_add, &g);   // GOB column 1 of block row 0
    if (g.n != 1 || g.r[0].x != 16 || g.r[0].y != 0 || g.r[0].w != 16 || g.r[0].h != MIN(rh, 256u)) { snprintf(why, n, "bytes [blk, 2 blk): %d rects, first %u,%u %ux%u (want 16,0 16x%u)", g.n, g.r[0].x, g.r[0].y, g.r[0].w, g.r[0].h, MIN(rh, 256u)); return 1; }
    if (rh < 256) {
        g.n = 0; tex_bytes_rects(&t, row + 3 * blk, row + 3 * blk + 1, rect_got_add, &g);   // one byte in column 3 of block row 1
        if (g.n != 1 || g.r[0].x != 48 || g.r[0].y != rh || g.r[0].w != 16) { snprintf(why, n, "one byte in row 1 column 3: %d rects, %u,%u %ux%u (want 48,%u 16x..)", g.n, g.r[0].x, g.r[0].y, g.r[0].w, g.r[0].h, rh); return 1; }
        range_got r = {0}; tex_rect_bytes(&t, 0, 0, 20, rh + 2, 5, 5, range_got_add, &r);   // texels 20..24 of block row 1: column 1
        if (r.n != 1 || r.lo[0] != row + blk || r.hi[0] != row + 2 * blk) { snprintf(why, n, "rect 20,%u 5x5: %d ranges, [%llu, %llu) (want [%llu, %llu))", rh + 2, r.n, r.lo[0], r.hi[0], row + blk, row + 2 * blk); return 1; }
    }
    {   // ground truth from the deswizzler: storage with only bytes [blk, 2 blk) set must come out non-zero exactly inside the rectangle tex_bytes_rects gave for them
        uint8_t *st = calloc(1, t.L.size), *lin = calloc(256 * 4, 256); int bad = !st || !lin;
        if (!bad) { memset(st + blk, 0xff, blk); bad = nvn_deswizzle(&t.d, 0, 0, st, lin, 256 * 4); }
        uint32_t out = 0, in = 0, ry = MIN(rh, 256u);
        for (uint32_t y = 0; !bad && y < 256; y++) for (uint32_t x = 0; x < 256; x++) { int nz = lin[(size_t)y * 1024 + x * 4] != 0, inside = x >= 16 && x < 32 && y < ry; out += nz && !inside; in += nz && inside; }
        free(st); free(lin);
        if (bad || out || in != 16 * ry) { snprintf(why, n, "deswizzled [blk, 2 blk): %u texels set outside 16,0 16x%u, %u inside (want 0 and %u)%s", out, ry, in, 16 * ry, bad ? ", deswizzle failed" : ""); return 1; }
    }
    g.n = 0; tex_bytes_rects(&t, 0, t.L.size, rect_got_add, &g);   // the whole storage: every block row as full-width rectangles, covering all 256 rows
    uint32_t rows = 0; for (int i = 0; i < g.n; i++) { if (g.r[i].x || g.r[i].w != 256) { snprintf(why, n, "whole storage: rect %d at x %u width %u", i, g.r[i].x, g.r[i].w); return 1; } rows += g.r[i].h; }
    if (rows != 256) { snprintf(why, n, "whole storage covers %u rows (want 256)", rows); return 1; }
    snprintf(why, n, "tileH %u: GOB column 1 = rect 16,0 16x%u (the deswizzler agrees texel for texel), a byte in row 1 column 3 = 48,%u, rect 20,%u 5x5 = one block's bytes, whole storage = 256 full rows", th, MIN(rh, 256u), rh, rh + 2);
    return 0;
}
// Pipeline key normalisation self-test (graphics/nvn/tests/t_nvn_m3.m): expectations follow what pso_desc reads, written by hand. → 0 passed, else what failed in why
int mtl_psonorm_selftest(char *why, size_t n) {
    pso_key a; memset(&a, 0, sizeof a);
    a.cfmt[0] = MTLPixelFormatRGBA8Unorm; a.cfmt[2] = MTLPixelFormatR32Uint; a.samples = 1;
    a.blend_en = 0x07; a.chmask = 0xffffffff;
    a.blend[0].target = 3; a.blend[0].src_rgb = 5; a.blend[0].dst_rgb = 6; a.blend[0].src_a = 5; a.blend[0].dst_a = 6; a.blend[0].eq_rgb = 1; a.blend[0].eq_a = 1;
    a.blend[1].src_rgb = 2; a.blend[1].target = 1;   // target 1 has no format: everything about it is residue
    a.blend[2].src_rgb = 9; a.blend[2].target = 2;   // R32Uint never blends
    pso_key b = a; b.chmask = 0x00000f0f; b.blend[1].src_rgb = 7; b.blend[0].target = 0; b.blend_en = 0x05; b.blend[2].src_rgb = 0;
    pso_key_norm(&a, nil, nil, 0); pso_key_norm(&b, nil, nil, 0);
    if (a.chmask != 0xf0f || a.blend_en != 0x1 || a.blend[0].target || a.blend[0].src_rgb != 5 || a.blend[0].dst_a != 6 || a.blend[1].src_rgb || a.blend[2].src_rgb) {
        snprintf(why, n, "normalised: chmask %#x (want 0xf0f), blend_en %#x (want 0x1), target0 %u, src0 %u, src1 %u, src2 %u", a.chmask, a.blend_en, (unsigned)a.blend[0].target, (unsigned)a.blend[0].src_rgb, (unsigned)a.blend[1].src_rgb, (unsigned)a.blend[2].src_rgb); return 1; }
    if (memcmp(&a, &b, sizeof a)) { snprintf(why, n, "two keys that differ only in bytes pso_desc never reads still differ"); return 1; }
    pso_key c = b; c.blend[0].dst_rgb = 2; pso_key_norm(&c, nil, nil, 0);
    if (!memcmp(&b, &c, sizeof b)) { snprintf(why, n, "a blend factor of a blending target was dropped"); return 1; }
    pso_key m; memset(&m, 0, sizeof m); m.blend[1].src_rgb = 2; m.chmask = 0xff; pso_key mm = m; pso_key_norm(&mm, nil, nil, 1);
    if (memcmp(&m, &mm, sizeof m)) { snprintf(why, n, "a merged pass's key was changed (it reads target state through lmap)"); return 1; }
    snprintf(why, n, "residue on a target with no format / an integer target / the target field cleared, the blending target kept; two keys differing only there become one; merged keys untouched");
    return 0;
}
int mtl_tab_selftest(char *why, size_t n) {
    mtl_init();
    if (!g_m3) { snprintf(why, n, "not on the Metal 3 path"); return 1; }
    static const char *src = "#include <metal_stdlib>\nusing namespace metal;\n"
        "kernel void cp(device const uint *a [[buffer(0)]], device uint *b [[buffer(3)]], uint i [[thread_position_in_grid]]) { b[i] = a[i]; }\n";
    NSError *e = nil; id<MTLLibrary> lib = [g_dev newLibraryWithSource:@(src) options:nil error:&e];
    id<MTLComputePipelineState> ps = lib ? [g_dev newComputePipelineStateWithFunction:[lib newFunctionWithName:@"cp"] error:&e] : nil;
    if (!ps) { snprintf(why, n, "kernel: %s", e.localizedDescription.UTF8String); return 1; }
    id<MTLBuffer> buf = [g_dev newBufferWithLength:4096 options:MTLResourceStorageModeShared]; res_add(buf); res_commit();
    uint32_t *p = buf.contents; for (int i = 0; i < 1024; i++) p[i] = 0;
    for (int i = 0; i < 4; i++) p[4 + i] = 0xa5a50000u + (uint32_t)i;   // the source: 16 bytes into the buffer (an address inside it, not its start)
    id t = tab_new(31, 0, 0, &e); if (!t) { snprintf(why, n, "tab_new: %s", e.localizedDescription.UTF8String); return 1; }
    tab_addr(t, buf.gpuAddress + 16, 0); tab_addr(t, buf.gpuAddress + 1024, 3);   // destination: 1024 bytes in
    tab_addr(t, 0x10, 5);   // in no resident buffer: not bound, counted
    id<MTLCommandBuffer> cb = [g_q3 commandBuffer]; id<MTLComputeCommandEncoder> ce = [cb computeCommandEncoder];
    [ce setComputePipelineState:ps]; enc_c_table(ce, t); m3_bind_dispatch(ce);
    [ce dispatchThreads:MTLSizeMake(4, 1, 1) threadsPerThreadgroup:MTLSizeMake(4, 1, 1)]; [ce endEncoding]; [cb commit]; [cb waitUntilCompleted];
    DmTable3 *x = t; int bad = 0;
    for (int i = 0; i < 4; i++) bad |= p[256 + i] != 0xa5a50000u + (uint32_t)i;
    if (bad) { snprintf(why, n, "read back %#x %#x %#x %#x (want a5a50000..3)", p[256], p[257], p[258], p[259]); return 1; }
    if (x->off[0] != 16 || x->off[3] != 1024 || x->buf[5]) { snprintf(why, n, "slots off0 %lu off3 %lu buf5 %s", (unsigned long)x->off[0], (unsigned long)x->off[3], x->buf[5] ? "set" : "nil"); return 1; }
    if (x->dbuf[2] || g_m3_sent_enc[2] != ce || g_m3_sent_tab[2] != t || !x->dbuf[0] || !x->dbuf[1]) { snprintf(why, n, "after the dispatch: compute changed %#x (want 0), vertex %#x / fragment %#x (want what was set)", x->dbuf[2], x->dbuf[0], x->dbuf[1]); return 1; }
    // A helper table on the same encoder, then this one again with only slot 3 changed: slot 0 must come back from this table (the helper's table had taken it over)
    for (int i = 0; i < 4; i++) { p[512 + i] = 0x5a5a0000u + (uint32_t)i; p[384 + i] = 0; }
    id t2 = tab_new(31, 0, 0, &e); tab_addr(t2, buf.gpuAddress + 2048, 0); tab_addr(t2, buf.gpuAddress + 3072, 3);
    cb = [g_q3 commandBuffer]; ce = [cb computeCommandEncoder]; [ce setComputePipelineState:ps];
    enc_c_table(ce, t); m3_bind_dispatch(ce); [ce dispatchThreads:MTLSizeMake(4, 1, 1) threadsPerThreadgroup:MTLSizeMake(4, 1, 1)];
    enc_c_table(ce, t2); m3_bind_dispatch(ce); [ce dispatchThreads:MTLSizeMake(4, 1, 1) threadsPerThreadgroup:MTLSizeMake(4, 1, 1)];
    tab_addr(t, buf.gpuAddress + 1536, 3); enc_c_table(ce, t); m3_bind_dispatch(ce); [ce dispatchThreads:MTLSizeMake(4, 1, 1) threadsPerThreadgroup:MTLSizeMake(4, 1, 1)];
    [ce endEncoding]; [cb commit]; [cb waitUntilCompleted];
    for (int i = 0; i < 4; i++) bad |= p[384 + i] != 0xa5a50000u + (uint32_t)i;
    if (bad) { snprintf(why, n, "back on this table after a helper's: slot 0 read %#x (want a5a50000, 5a5a0000 = the helper's slot left bound)", p[384]); return 1; }
    // Fresh encoders one after another with the table unchanged: each gets all slots (a freed encoder's address handed to the next used to look like the same encoder)
    for (int k = 0; k < 64 && !bad; k++) @autoreleasepool {
        for (int i = 0; i < 4; i++) p[384 + i] = 0;
        cb = [g_q3 commandBuffer]; ce = [cb computeCommandEncoder]; [ce setComputePipelineState:ps];
        enc_c_table(ce, t); m3_bind_dispatch(ce); [ce dispatchThreads:MTLSizeMake(4, 1, 1) threadsPerThreadgroup:MTLSizeMake(4, 1, 1)];
        [ce endEncoding]; [cb commit]; [cb waitUntilCompleted];
        for (int i = 0; i < 4; i++) bad |= p[384 + i] != 0xa5a50000u + (uint32_t)i;
        if (bad) { snprintf(why, n, "fresh encoder %d with the table unchanged: read %#x (want a5a50000)", k, p[384]); return 1; }
    }
    res_remove(buf); id<MTLBuffer> b2; NSUInteger o2 = 0;
    if (m3_buf_at(buf.gpuAddress + 16, &b2, &o2)) { snprintf(why, n, "the address still resolves after res_remove"); return 1; }
    snprintf(why, n, "slot 0 at +16 and slot 3 at +1024 read back, an address in no resident buffer left unbound, only the compute stage marked sent, slot 0 back from this table after a helper table on the same encoder, 64 fresh encoders each bound in full, removed buffer no longer resolves");
    return 0;
}
// Graphics session begin (host_adapt.m dm_gfx_begin_host_state): the device and queue live for the process, but the in-process restart clears the native layer's
//   callback slots (s2a_direct_host_session_reset); the first session registers these in device setup above, a restarted one only here
void mtl_begin_session_hooks(void) {
    if (!g_dev) return;
    { void crash_set_wait_dump(void (*fn)(void)); void mtl_wait_state_dump(void); crash_set_wait_dump(mtl_wait_state_dump); }
    dm_res_report_register(mtl_res_counts);
}
void mtl_wait_state_dump(void) {
    MLOG("wait points: main fence submitted %llu / completed %llu; main allocator fences [%llu %llu %llu]; uploads pending %d, allocators busy [%d %d %d], seq %u, unflushed batch %d; present queue in %llu / done %llu; main command buffer encoding %d, submit thread set %d",
         (unsigned long long)g_fence, (unsigned long long)g_done, (unsigned long long)g_alloc_fence[0], (unsigned long long)g_alloc_fence[1], (unsigned long long)g_alloc_fence[2],
         atomic_load(&g_up_pending), atomic_load(&g_up_alloc_busy[0]), atomic_load(&g_up_alloc_busy[1]), atomic_load(&g_up_alloc_busy[2]), g_up_seq, g_up_cb != nil,
         (unsigned long long)g_pq_in, (unsigned long long)g_pq_done, g_cb != nil, atomic_load(&g_sub_thread_set));
    if (g_m3) MLOG("Metal 3: copy encoders split for a barrier %llu", (unsigned long long)g_blit_splits3);
}
void nvn_be_alloc_stats(uint64_t *waits, uint64_t *grown, int *n) { *waits = g_alloc_waits; *grown = g_alloc_grown; *n = g_alloc_n; }   // Main submit allocator pool: how many times it waited, how many times it grew, how many exist now
